fn cd_sigma(a: i32, b: i32, bits: i32) -> i32 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return -1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma(a_lo, 0, bits - 1) }
        return 0 - cd_sigma(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma(0, a_lo, bits - 1) }
    cd_sigma(b_lo, a_lo, bits - 1)
}

fn cd_basis(k: i32, idx: i32) -> CD with Mut, Panic {
    var r = cd_zero(k)
    r.c[idx as usize] = 1.0
    r
}

fn cd_mul(a: CD, b: CD) -> CD with Mut, Panic, Div {
    let n = 1 << a.bits
    var r = cd_zero(a.bits)
    var i: i32 = 0
    while i < n {
        if a.c[i as usize] != 0.0 {
            var j: i32 = 0
            while j < n {
                if b.c[j as usize] != 0.0 {
                    let idx = i ^ j
                    let sign = cd_sigma(i, j, a.bits)
                    r.c[idx as usize] = r.c[idx as usize]
                        + (sign as f64) * a.c[i as usize] * b.c[j as usize]
                }
                j = j + 1
            }
        }
        i = i + 1
    }
    r
}

fn cd_norm_sq(a: CD) -> f64 with Mut, Panic, Div {
    let n = 1 << a.bits
    var s: f64 = 0.0
    var i: i32 = 0
    while i < n { s = s + a.c[i as usize] * a.c[i as usize]; i = i + 1 }
    s
}

fn cd_sub(a: CD, b: CD) -> CD with Mut, Panic, Div {
    let n = 1 << a.bits
    var r = cd_zero(a.bits)
    var i: i32 = 0
    while i < n { r.c[i as usize] = a.c[i as usize] - b.c[i as usize]; i = i + 1 }
    r
}

fn cd_add(a: CD, b: CD) -> CD with Mut, Panic, Div {
    let n = 1 << a.bits
    var r = cd_zero(a.bits)
    var i: i32 = 0
    while i < n { r.c[i as usize] = a.c[i as usize] + b.c[i as usize]; i = i + 1 }
    r
}

fn dijkstra(adj: &[*const Edge], edge_counts: &[usize], n: usize, source: usize) -> *mut f64 with Alloc, Panic {
    // Allocate distance and visited arrays
    let dist = malloc(n * 8) as *mut f64
    let visited = malloc(n) as *mut bool

    // Initialize distances
    var i: usize = 0
    while i < n {
        dist[i] = INFINITY
        visited[i] = false
        i = i + 1
    }

    dist[source] = 0.0

    var remaining = n

    while remaining > 0 {
        // Find unvisited node with minimum distance
        var min_dist = INFINITY
        var min_node: i64 = -1

        i = 0
        while i < n {
            if !visited[i] && dist[i] < min_dist {
                min_dist = dist[i]
                min_node = i as i64
            }
            i = i + 1
        }

        if min_node == -1 {
            break
        }

        let u = min_node as usize
        visited[u] = true
        remaining = remaining - 1

        // Relax edges from u
        let edges = adj[u]
        let count = edge_counts[u]
        var j: usize = 0
        while j < count {
            let edge = &edges[j]
            let v = edge.to
            let new_dist = dist[u] + edge.weight

            if new_dist < dist[v] {
                dist[v] = new_dist
            }
            j = j + 1
        }
    }

    free(visited as *mut u8)
    return dist
}

fn bfs(adj: &[*const Edge], edge_counts: &[usize], n: usize, source: usize) -> *mut i64 with Alloc, Panic {
    let distances = malloc(n * 8) as *mut i64

    var i: usize = 0
    while i < n {
        distances[i] = -1
        i = i + 1
    }

    // Simple queue using array
    let queue = malloc(n * 8) as *mut usize
    var head: usize = 0
    var tail: usize = 0

    distances[source] = 0
    queue[tail] = source
    tail = tail + 1

    while head < tail {
        let u = queue[head]
        head = head + 1

        let edges = adj[u]
        let count = edge_counts[u]
        var j: usize = 0
        while j < count {
            let v = edges[j].to
            if distances[v] == -1 {
                distances[v] = distances[u] + 1
                queue[tail] = v
                tail = tail + 1
            }
            j = j + 1
        }
    }

    free(queue as *mut u8)
    return distances
}

fn dfs_visit(adj: &[*const Edge], edge_counts: &[usize], u: usize, visited: &!*mut bool) with Panic {
    visited[u] = true

    let edges = adj[u]
    let count = edge_counts[u]
    var i: usize = 0
    while i < count {
        let v = edges[i].to
        if !visited[v] {
            dfs_visit(adj, edge_counts, v, visited)
        }
        i = i + 1
    }
}

fn dfs(adj: &[*const Edge], edge_counts: &[usize], n: usize, source: usize) -> *mut bool with Alloc, Panic {
    let visited = malloc(n) as *mut bool

    var i: usize = 0
    while i < n {
        visited[i] = false
        i = i + 1
    }

    dfs_visit(adj, edge_counts, source, &!visited)

    return visited
}

fn quicksort_i64(arr: &![i64], len: usize) with Panic, Div {
    if len <= 1 {
        return
    }
    quicksort_range(&!arr, 0, len - 1)
}

fn quicksort_range(arr: &![i64], low: usize, high: usize) with Panic, Div {
    if low < high {
        let pivot_idx = partition(&!arr, low, high)

        if pivot_idx > 0 {
            quicksort_range(&!arr, low, pivot_idx - 1)
        }

        if pivot_idx < high {
            quicksort_range(&!arr, pivot_idx + 1, high)
        }
    }
}

fn partition(arr: &![i64], low: usize, high: usize) -> usize with Panic, Div {
    let mid = low + (high - low) / 2
    let pivot = arr[mid]

    var i = low
    var j = high

    while true {
        while arr[i] < pivot {
            i = i + 1
        }

        while arr[j] > pivot {
            j = j - 1
        }

        if i >= j {
            return j
        }

        let temp = arr[i]
        arr[i] = arr[j]
        arr[j] = temp

        i = i + 1
        j = j - 1
    }

    return j
}

fn mergesort_i64(arr: &![i64], len: usize) with Alloc, Panic, Div {
    if len <= 1 {
        return
    }

    let size_bytes = len * 8
    let temp = malloc(size_bytes) as *mut i64

    mergesort_recursive(&!arr, temp, 0, len - 1)

    free(temp as *mut u8)
}

fn mergesort_recursive(arr: &![i64], temp: *mut i64, left: usize, right: usize) with Panic, Div {
    if left >= right {
        return
    }

    let mid = left + (right - left) / 2

    mergesort_recursive(&!arr, temp, left, mid)
    mergesort_recursive(&!arr, temp, mid + 1, right)
    merge(&!arr, temp, left, mid, right)
}

fn merge(arr: &![i64], temp: *mut i64, left: usize, mid: usize, right: usize) with Panic, Div {
    var i = left
    while i <= right {
        temp[i] = arr[i]
        i = i + 1
    }

    var i1 = left
    var i2 = mid + 1
    var curr = left

    while i1 <= mid && i2 <= right {
        if temp[i1] <= temp[i2] {
            arr[curr] = temp[i1]
            i1 = i1 + 1
        } else {
            arr[curr] = temp[i2]
            i2 = i2 + 1
        }
        curr = curr + 1
    }

    while i1 <= mid {
        arr[curr] = temp[i1]
        i1 = i1 + 1
        curr = curr + 1
    }
}

fn heapsort_i64(arr: &![i64], len: usize) with Panic, Div {
    if len <= 1 {
        return
    }

    var i = len / 2
    while i > 0 {
        i = i - 1
        heapify(&!arr, len, i)
    }

    var end = len - 1
    while end > 0 {
        let temp = arr[0]
        arr[0] = arr[end]
        arr[end] = temp

        heapify(&!arr, end, 0)

        end = end - 1
    }
}

fn heapify(arr: &![i64], heap_size: usize, root: usize) with Panic {
    var largest = root
    let left = 2 * root + 1
    let right = 2 * root + 2

    if left < heap_size && arr[left] > arr[largest] {
        largest = left
    }

    if right < heap_size && arr[right] > arr[largest] {
        largest = right
    }

    if largest != root {
        let temp = arr[root]
        arr[root] = arr[largest]
        arr[largest] = temp

        heapify(&!arr, heap_size, largest)
    }
}

fn is_sorted(arr: &[i64], len: usize) -> bool with Panic, Div {
    if len <= 1 {
        return true
    }

    var i = 0
    while i < len - 1 {
        if arr[i] > arr[i + 1] {
            return false
        }
        i = i + 1
    }

    return true
}

fn print_array(arr: &[i64], len: usize) with Panic {
    printf("  [".as_ptr())
    var i: usize = 0
    while i < len {
        if i > 0 {
            printf(", ".as_ptr())
        }
        printf("%lld".as_ptr(), arr[i])
        i = i + 1
    }
    printf("]\n".as_ptr())
}

fn copy_array(dest: &![i64], src: &[i64], len: usize) with Panic {
    var i: usize = 0
    while i < len {
        dest[i] = src[i]
        i = i + 1
    }
}

fn swap(i: i64, j: i64) {
    var tmp = DATA[i]
    DATA[i] = DATA[j]
    DATA[j] = tmp
}

fn partition(lo: i64, hi: i64) -> i64 {
    var pivot = DATA[hi]
    var i = lo - 1
    var j = lo
    while j < hi {
        if DATA[j] <= pivot {
            i = i + 1
            swap(i, j)
        }
        j = j + 1
    }
    swap(i + 1, hi)
    return i + 1
}

fn qsort(lo: i64, hi: i64) {
    if lo < hi {
        var p = partition(lo, hi)
        qsort(lo, p - 1)
        qsort(p + 1, hi)
    }
}

fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 { return a }
    return gcd(b, a % b)
}

fn fib(n: i64) -> i64 {
    if n <= 1 { return n }
    return fib(n - 1) + fib(n - 2)
}

fn collatz_steps(n: i64) -> i64 {
    var steps = 0
    var x = n
    while x != 1 {
        if (x % 2) == 0 {
            x = x / 2
        } else {
            x = x * 3 + 1
        }
        steps = steps + 1
    }
    return steps
}

fn sieve_primes(limit: i64) -> i64 {
    // Use DATA as sieve (0=composite, 1=prime) up to limit
    var i = 2
    while i <= limit {
        DATA[i] = 1
        i = i + 1
    }
    i = 2
    while (i * i) <= limit {
        if DATA[i] == 1 {
            var j = i * i
            while j <= limit {
                DATA[j] = 0
                j = j + i
            }
        }
        i = i + 1
    }
    // Collect primes into PRIMES array
    var count = 0
    i = 2
    while i <= limit {
        if DATA[i] == 1 {
            PRIMES[count] = i
            count = count + 1
        }
        i = i + 1
    }
    return count
}

//@ run-pass
//! Mandelbrot Set: ASCII render at 80×40 resolution
//!
//! Demonstrates: f64 arithmetic, nested loops, complex iteration,
//! character output — zero external dependencies.
//!
//! Outputs a text-art rendering of the Mandelbrot set.
//!
//! Run: $SOUC run examples/algorithms/mandelbrot.sio

const WIDTH: i64 = 78
const HEIGHT: i64 = 36
const MAX_ITER: i64 = 64

// Compute Mandelbrot escape count for point (cx, cy)
fn mandelbrot(cx: f64, cy: f64) -> i64 {
    var zx: f64 = 0.0
    var zy: f64 = 0.0
    var iter: i64 = 0
    while iter < MAX_ITER {
        let zx2 = zx * zx
        let zy2 = zy * zy
        if zx2 + zy2 > 4.0 {
            return iter
        }
        let new_zx = zx2 - zy2 + cx
        zy = 2.0 * zx * zy + cy
        zx = new_zx
        iter = iter + 1
    }
    MAX_ITER
}

// Map escape count to ASCII character
fn iter_to_char(n: i64) -> i64 {
    if n == MAX_ITER { return 64 }   // '@' = 64
    if n > 48 { return 35 }          // '#' = 35
    if n > 32 { return 43 }          // '+' = 43
    if n > 16 { return 46 }          // '.' = 46
    if n > 8  { return 58 }          // ':' = 58
    32                                // ' ' = 32
}

fn print_char(c: i64) with IO {
    if c == 64 { print("@") }
    else if c == 35 { print("#") }
    else if c == 43 { print("+") }
    else if c == 46 { print(".") }
    else if c == 58 { print(":") }
    else { print(" ") }
}

fn main() -> i32 with IO {
    print("Mandelbrot Set (")
    print_int(WIDTH)
    print("x")
    print_int(HEIGHT)
    print(", max_iter=")
    print_int(MAX_ITER)
    print(")\n")
    print("Region: x in [-2.5, 1.0], y in [-1.2, 1.2]\n\n")

    let x_min: f64 = -2.5
    let x_max: f64 =  1.0
    let y_min: f64 = -1.2
    let y_max: f64 =  1.2

    var row: i64 = 0
    while row < HEIGHT {
        let cy = y_max - (y_max - y_min) * (row as f64) / (HEIGHT as f64)
        var col: i64 = 0
        while col < WIDTH {
            let cx = x_min + (x_max - x_min) * (col as f64) / (WIDTH as f64)
            let n = mandelbrot(cx, cy)
            print_char(iter_to_char(n))
            col = col + 1
        }
        print("\n")
        row = row + 1
    }

    // Count pixels in the set (escape == MAX_ITER)
    var in_set: i64 = 0
    row = 0
    while row < HEIGHT {
        let cy = y_max - (y_max - y_min) * (row as f64) / (HEIGHT as f64)
        var col: i64 = 0
        while col < WIDTH {
            let cx = x_min + (x_max - x_min) * (col as f64) / (WIDTH as f64)
            if mandelbrot(cx, cy) == MAX_ITER { in_set = in_set + 1 }
            col = col + 1
        }
        row = row + 1
    }

    print("\nPixels in Mandelbrot set: ")
    println(in_set)
    print("Total pixels: ")
    println(WIDTH * HEIGHT)

    0
}

