    let sum = p0 + p1 + p2 + p3

    // Value in [0, 1]
    let v = nn_forward_value(weights, 0.0)

    let sum_ok = if abs_f(sum - 1.0) < 0.01 { 1.0 } else { 0.0 }
    let v_ok = if v > 0.0 { 1.0 } else { 0.0 }

    sum_ok + v_ok
}

