    print(f"║  Solve rate: {mean*100:.1}% ± {std*100:.1}%                                    ║")
    print(f"║  95% CI: [{lo95*100:.1}%, {hi95*100:.1}%]                                      ║")
    print(f"║  Beta Posterior: Beta({sr.alpha:.1}, {sr.beta:.1})                             ║")
    print("╠══════════════════════════════════════════════════════════════════╣")
    print("║  Baselines:                                                      ║")
    print("║    AlphaGeometry: 83% (25/30)                                    ║")
