fn combine_weighted(sources: [BetaConfidence]) -> BetaConfidence {
    var total_weight = 0.0;
    var weighted_alpha = 0.0;
    var weighted_beta = 0.0;

    for source in sources {
        let weight = 1.0 / (source.variance() + 0.001);
        total_weight = total_weight + weight;
        weighted_alpha = weighted_alpha + source.alpha * weight;
        weighted_beta = weighted_beta + source.beta * weight;
    }

    BetaConfidence::new(
        weighted_alpha / total_weight,
        weighted_beta / total_weight
    )
}

fn variance_penalty(knowledges: [BetaConfidence], lambda: f64) -> f64 {
    var penalty = 0.0;
    for k in knowledges {
        penalty = penalty + lambda * k.variance();
    }
    penalty
}

fn epistemic_loss(
    policy_loss: f64,
    value_loss: f64,
    confidences: [BetaConfidence],
    lambda: f64
) -> f64 {
    policy_loss + value_loss + variance_penalty(confidences, lambda)
}

fn cd_sigma(a: i32, b: i32, bits: i32) -> i32 with Mut, Panic, Div {
    // Base case: dimension 2 (complex numbers)
    // e_0 = 1 (identity), e_1 = i
    // e_0 * e_0 = e_0 (+1), e_0 * e_1 = e_1 (+1)
    // e_1 * e_0 = e_1 (+1), e_1 * e_1 = -e_0 (-1)
    if a == 0 || b == 0 { return 1 }  // identity: e_0 * anything = itself
    if bits <= 1 {
        // a=1, b=1: e_1^2 = -1
        return -1
    }

    let half = 1 << (bits - 1)

    // Split into upper/lower halves
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)  // a mod half
    let b_lo = b & (half - 1)  // b mod half

    // Cayley-Dickson doubling: (a1, a2)(b1, b2) = (a1*b1 - conj(b2)*a2, b2*a1 + a2*conj(b1))
    // The sign depends on which "half" each element is in.
    //
    // Case analysis (a_hi, b_hi):
    //   (0,0): both in lower half → σ_{k-1}(a, b)
    //   (0,1): a lower, b upper → σ comes from "b2*a1" term → σ_{k-1}(b_lo, a_lo)
    //   (1,0): a upper, b lower → σ comes from "a2*conj(b1)" term
    //          conj(b_lo) flips sign for b_lo != 0
    //          → σ_{k-1}(a_lo, b_lo) * (if b_lo == 0 { 1 } else { -1 })
    //   (1,1): both upper → σ comes from "-conj(b2)*a2" term
    //          → -σ_{k-1}(b_lo, a_lo) * (if b_lo == 0 { 1 } else { -1 })
    //
    // This is the recursive structure. Let me implement it directly.

    if a_hi == 0 && b_hi == 0 {
        // Both in lower half: recurse
        return cd_sigma(a_lo, b_lo, bits - 1)
    }
    if a_hi == 0 && b_hi == 1 {
        // a lower, b upper: from "da" term (b2 * a1)
        return cd_sigma(b_lo, a_lo, bits - 1)
    }
    if a_hi == 1 && b_hi == 0 {
        // a upper, b lower: from "b*conj(c)" term (a2 * conj(b1))
        if b_lo == 0 {
            return cd_sigma(a_lo, b_lo, bits - 1)
        } else {
            return 0 - cd_sigma(a_lo, b_lo, bits - 1)
        }
    }
    // a_hi == 1 && b_hi == 1
    // Both upper: from "-conj(d)*b" term
    if b_lo == 0 {
        return 0 - cd_sigma(b_lo, a_lo, bits - 1)
    } else {
        return cd_sigma(b_lo, a_lo, bits - 1)
    }
}

fn alpha(i: i32, j: i32, k: i32, bits: i32) -> i32 with Mut, Panic, Div {
    cd_sigma(i, j, bits) * cd_sigma(i ^ j, k, bits)
}

fn beta(i: i32, j: i32, k: i32, bits: i32) -> i32 with Mut, Panic, Div {
    cd_sigma(j, k, bits) * cd_sigma(i, j ^ k, bits)
}

fn verify_at_dim(bits: i32) -> [i32; 3] with Mut, Panic, Div, IO {
    let n = (1 << bits) - 1  // number of imaginary basis elements
    var nonzero: i32 = 0
    var total: i32 = 0
    var all_binary = 1  // 1 = true

    var i: i32 = 1
    while i <= n {
        var j: i32 = 1
        while j <= n {
            var k: i32 = 1
            while k <= n {
                let a = alpha(i, j, k, bits)
                let b = beta(i, j, k, bits)
                let diff = a - b

                // THE PROOF: α, β ∈ {+1, -1} → diff ∈ {-2, 0, +2}
                // Verify this holds:
                if diff != 0 && diff != 2 && diff != -2 {
                    all_binary = 0
                    println("  VIOLATION at (")
                    println(i)
                    println(j)
                    println(k)
                    println("): diff = ")
                    println(diff)
                }

                total = total + 1
                if diff != 0 { nonzero = nonzero + 1 }

                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }

    var result: [i32; 3] = [0; 3]
    result[0] = nonzero
    result[1] = total
    result[2] = all_binary
    result
}

fn exp_q(x: f64) -> f64 with Mut, Div, Panic {
    if x > 15.0 { return exp_q(7.5) * exp_q(x - 7.5) }
    if x < 0.0 - 15.0 { return 0.0 }
    var sum = 1.0
    var term = 1.0
    var i = 1
    while i <= 20 { term = term * x / (i as f64); sum = sum + term; i = i + 1 }
    sum
}

fn rng_next() -> i64 with Mut {
    var x = RNG_A; let y = RNG_B; RNG_A = y
    x = x ^ (x << 23); x = x ^ (x >> 17); x = x ^ (y ^ (y >> 26))
    RNG_B = x; let r = x + y; if r < 0 { 0 - r } else { r }
}

fn check_balanced(slen: i64) -> i64 with Mut {
    // Verify a sequence is balanced using a stack
    STK_TOP = 0
    var i = 0
    while i < slen {
        let tok = SEQ[i]
        if tok == 1 { STK[STK_TOP] = 1; STK_TOP = STK_TOP + 1 }
        if tok == 3 { STK[STK_TOP] = 3; STK_TOP = STK_TOP + 1 }
        if tok == 2 {
            if STK_TOP == 0 { return 0 }
            STK_TOP = STK_TOP - 1
            if STK[STK_TOP] != 1 { return 0 }
        }
        if tok == 4 {
            if STK_TOP == 0 { return 0 }
            STK_TOP = STK_TOP - 1
            if STK[STK_TOP] != 3 { return 0 }
        }
        if STK_TOP > 9 { return 0 }
        i = i + 1
    }
    if STK_TOP == 0 { 1 } else { 0 }
}

fn generate_balanced(slen: i64) with Mut, Div {
    // Build balanced sequence by random push/pop decisions
    // We fill positions left-to-right: push open bracket or close matching
    STK_TOP = 0
    var pos = 0
    var remaining = slen
    while pos < slen {
        remaining = slen - pos
        let can_open = STK_TOP < remaining / 2
        let can_close = STK_TOP > 0
        if can_open == false {
            if can_close == false {
                // Should not happen if slen is even
                SEQ[pos] = 1
            }
        }
        var choice = 0
        if can_open { if can_close { choice = (rng_next() / 100) % 2 } }
        if can_open { if can_close == false { choice = 0 } }
        if can_open == false { if can_close { choice = 1 } }
        if choice == 0 {
            // Push an open bracket
            let btype = (rng_next() / 100) % 2
            if btype == 0 { SEQ[pos] = 1; STK[STK_TOP] = 1 }
            if btype == 1 { SEQ[pos] = 3; STK[STK_TOP] = 3 }
            STK_TOP = STK_TOP + 1
        }
        if choice == 1 {
            // Pop and close matching bracket
            STK_TOP = STK_TOP - 1
            let top = STK[STK_TOP]
            if top == 1 { SEQ[pos] = 2 }
            if top == 3 { SEQ[pos] = 4 }
        }
        pos = pos + 1
    }
}

fn generate_unbalanced(slen: i64) with Mut, Div {
    // Random brackets, reject if accidentally balanced
    var attempts = 0
    var done = 0
    while done == 0 {
        var i = 0
        while i < slen { SEQ[i] = (rng_next() / 100) % 4 + 1; i = i + 1 }
        if check_balanced(slen) == 0 { done = 1 }
        attempts = attempts + 1
        if attempts > 30 {
            // Force unbalanced: put two close brackets at start
            SEQ[0] = 2; SEQ[1] = 4
            done = 1
        }
    }
}

fn generate_sample_br(slen: i64) -> i64 with Mut, Div {
    let cls = (rng_next() / 100) % 2
    if cls == 1 { generate_balanced(slen) }
    if cls == 0 { generate_unbalanced(slen) }
    SEQ_LEN = slen
    cls
}

fn init_embed() with Mut, Div {
    var i = 0
    while i < 40 { ws(i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
}

fn init_a_matrix(is_cross: i64) with Mut, Div {
    var i = 0
    while i < 64 {
        var v = ((rng_next() % 2000) as f64 - 1000.0) / 10000.0
        let row = i / 8; let col = i - row * 8
        if row == col { v = 0.95 }
        if is_cross == 0 { if row != col { v = 0.0 } }
        ws(40 + i, v); i = i + 1
    }
}

fn init_b_out() with Mut, Div {
    var i = 0
    while i < 8 { ws(104 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 16 { ws(112 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
}

fn init_model(is_cross: i64) with Mut, Div {
    init_embed()
    init_a_matrix(is_cross)
    init_b_out()
    var i = 0
    while i < 128 { MOM[i] = 0; i = i + 1 }
}

fn model_step_cross(token: i64) with Mut, Div {
    var new_h: [f64; 8] = [0.0; 8]
    var d = 0
    while d < 8 {
        let inp = wg(token * 8 + d)
        var s = 0.0
        var j = 0
        while j < 8 { s = s + wg(40 + d*8 + j) * hg(j); j = j + 1 }
        s = s + wg(104 + d) * inp
        if s > 5.0 { s = 5.0 } if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        new_h[d] = s; d = d + 1
    }
    d = 0
    while d < 8 { hs(d, new_h[d]); d = d + 1 }
}

fn model_step_diag(token: i64) with Mut, Div {
    var d = 0
    while d < 8 {
        var s = wg(40 + d) * hg(d) + wg(104 + d) * wg(token * 8 + d)
        if s > 5.0 { s = 5.0 } if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        hs(d, s); d = d + 1
    }
}

fn model_step(token: i64, is_cross: i64) with Mut, Div {
    if is_cross == 1 { model_step_cross(token) } else { model_step_diag(token) }
}

fn compute_logits() with Mut, Div {
    var c = 0
    while c < 2 {
        var s = 0.0
        var d = 0
        while d < 8 { s = s + hg(d) * wg(112 + d*2 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn get_pred() -> i64 with Div {
    let v0 = (L[0] as f64) / 100000000.0
    let v1 = (L[1] as f64) / 100000000.0
    if v1 > v0 { 1 } else { 0 }
}

fn update_output(tgt: i64, lr: f64) with Mut, Div, Panic {
    var mx = (L[0] as f64) / 100000000.0
    let v1 = (L[1] as f64) / 100000000.0
    if v1 > mx { mx = v1 }
    var probs: [f64; 2] = [0.0; 2]
    var se = 0.0
    var i = 0
    while i < 2 { probs[i] = exp_q((L[i] as f64) / 100000000.0 - mx); se = se + probs[i]; i = i + 1 }
    i = 0
    while i < 2 { probs[i] = probs[i] / se; i = i + 1 }
    probs[tgt] = probs[tgt] - 1.0
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var c = 0
        while c < 2 {
            let idx = 112 + d*2 + c
            var g = hd * probs[c]
            if g > 0.3 { g = 0.3 } if g < 0.0 - 0.3 { g = 0.0 - 0.3 }
            let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            c = c + 1
        }
        d = d + 1
    }
}

fn run_config(is_cross: i64, slen: i64) -> f64 with IO, Mut, Div, Panic {
    rng_seed(55555 + slen * 100, 77777 + slen * 100)
    init_model(is_cross)

    let n_train = 300
    let n_epochs = 50
    rng_seed(12345 + slen * 10, 67890 + slen * 10)

    var ep = 0
    while ep < n_epochs {
        var correct = 0
        var s = 0
        while s < n_train {
            let cls = generate_sample_br(slen)
            var d = 0
            while d < 8 { H[d] = 0; d = d + 1 }
            var t = 0
            while t < SEQ_LEN {
                model_step(SEQ[t], is_cross)
                t = t + 1
            }
            compute_logits()
            if get_pred() == cls { correct = correct + 1 }
            update_output(cls, 0.01)
            s = s + 1
        }
        if ep % 15 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }

    // Evaluate
    rng_seed(99999 + slen, 11111 + slen)
    var correct = 0
    var s = 0
    while s < 200 {
        let cls = generate_sample_br(slen)
        var d = 0
        while d < 8 { H[d] = 0; d = d + 1 }
        var t = 0
        while t < SEQ_LEN { model_step(SEQ[t], is_cross); t = t + 1 }
        compute_logits()
        if get_pred() == cls { correct = correct + 1 }
        s = s + 1
    }
    let acc = (correct as f64) / 200.0 * 100.0
    print("    Eval: "); print(acc); print("%\n")
    acc
}

fn sqrt_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    var r = x
    var i = 0
    while i < 20 { r = 0.5 * (r + x / r); i = i + 1 }
    r
}

fn oct_sub(a: Oct, b: Oct) -> Oct with Mut, Panic, Div {
    var r = oct_zero()
    var i: i64 = 0
    while i < 8 { r.e[i as usize] = a.e[i as usize] - b.e[i as usize]; i = i + 1 }
    r
}

fn oct_scale(o: Oct, s: f64) -> Oct with Mut, Panic, Div {
    var r = oct_zero()
    var i: i64 = 0
    while i < 8 { r.e[i as usize] = o.e[i as usize] * s; i = i + 1 }
    r
}

fn oct_norm_sq(o: Oct) -> f64 with Mut, Panic, Div {
    var s: f64 = 0.0
    var i: i64 = 0
    while i < 8 { s = s + o.e[i as usize] * o.e[i as usize]; i = i + 1 }
    s
}

fn oct_conjugate(o: Oct) -> Oct with Mut, Panic, Div {
    var r = oct_zero()
    r.e[0] = o.e[0]
    var i: i64 = 1
    while i < 8 { r.e[i as usize] = 0.0 - o.e[i as usize]; i = i + 1 }
    r
}

fn oct_fano_index(i: i64, j: i64) -> i64 with Mut, Panic, Div {
    if i == j { return 0 }
    var t: [i64; 21] = [0; 21]
    t[0]=1;t[1]=2;t[2]=4; t[3]=2;t[4]=3;t[5]=5; t[6]=3;t[7]=4;t[8]=6
    t[9]=4;t[10]=5;t[11]=7; t[12]=5;t[13]=6;t[14]=1; t[15]=6;t[16]=7;t[17]=2
    t[18]=7;t[19]=1;t[20]=3
    var k: i64 = 0
    while k < 7 {
        let a=t[(k*3) as usize]; let b=t[(k*3+1) as usize]; let c=t[(k*3+2) as usize]
        if (i==a&&j==b)||(i==b&&j==c)||(i==c&&j==a) {
            if i==a&&j==b {return c}; if i==b&&j==c {return a}; return b
        }
        if (i==b&&j==a)||(i==c&&j==b)||(i==a&&j==c) {
            if i==b&&j==a {return c}; if i==c&&j==b {return a}; return b
        }
        k=k+1
    }
    0
}

fn oct_mul(a: Oct, b: Oct) -> Oct with Mut, Panic, Div {
    var result = oct_zero()
    var i: i64 = 0
    while i < 8 {
        var j: i64 = 0
        while j < 8 {
            let coeff = a.e[i as usize] * b.e[j as usize]
            if i==0&&j==0 { result.e[0] = result.e[0] + coeff }
            else if i==0 { result.e[j as usize] = result.e[j as usize] + coeff }
            else if j==0 { result.e[i as usize] = result.e[i as usize] + coeff }
            else if i==j { result.e[0] = result.e[0] - coeff }
            else {
                let k = oct_fano_index(i, j)
                let sign = oct_fano_sign(i, j)
                result.e[k as usize] = result.e[k as usize] + sign * coeff
            }
            j=j+1
        }
        i=i+1
    }
    result
}

fn oct_associator(a: Oct, b: Oct, c: Oct) -> Oct with Mut, Panic, Div {
    let ab = oct_mul(a, b)
    let bc = oct_mul(b, c)
    oct_sub(oct_mul(ab, c), oct_mul(a, bc))
}

fn make_asd_fc() -> BrainGraph with Mut, Panic, Div {
    var g = bg_new()
    // ASD: strong DMN internal (0), weak DMN-executive (0-1) link
    // Strong visual cluster (6-7), weak salience (2)
    // Local over-connectivity within modules, long-range under-connectivity

    // DMN-DMN (strong)
    g.fc[bg_idx(0,5) as usize] = 0.6; g.fc[bg_idx(5,0) as usize] = 0.6
    g.fc[bg_idx(0,7) as usize] = 0.5; g.fc[bg_idx(7,0) as usize] = 0.5

    // Visual-somatomotor cluster (strong local)
    g.fc[bg_idx(5,6) as usize] = 0.7; g.fc[bg_idx(6,5) as usize] = 0.7
    g.fc[bg_idx(6,7) as usize] = 0.4; g.fc[bg_idx(7,6) as usize] = 0.4

    // Attention networks (moderate)
    g.fc[bg_idx(3,4) as usize] = 0.5; g.fc[bg_idx(4,3) as usize] = 0.5

    // WEAK long-range connections (ASD signature)
    g.fc[bg_idx(0,1) as usize] = 0.15; g.fc[bg_idx(1,0) as usize] = 0.15  // DMN-executive
    g.fc[bg_idx(1,2) as usize] = 0.2; g.fc[bg_idx(2,1) as usize] = 0.2   // exec-salience
    g.fc[bg_idx(2,3) as usize] = 0.1; g.fc[bg_idx(3,2) as usize] = 0.1   // salience-attention

    // Self-connections (diagonal = 1)
    var i: i32 = 0
    while i < 8 { g.fc[bg_idx(i, i) as usize] = 1.0; i = i + 1 }
    g
}

fn make_adhd_fc() -> BrainGraph with Mut, Panic, Div {
    var g = bg_new()
    // ADHD: diffuse connectivity, excess short-range, weak executive control
    // Many moderate connections, few strong ones

    // Diffuse moderate connections (ADHD signature)
    g.fc[bg_idx(0,1) as usize] = 0.35; g.fc[bg_idx(1,0) as usize] = 0.35
    g.fc[bg_idx(0,2) as usize] = 0.3; g.fc[bg_idx(2,0) as usize] = 0.3
    g.fc[bg_idx(0,5) as usize] = 0.35; g.fc[bg_idx(5,0) as usize] = 0.35
    g.fc[bg_idx(1,2) as usize] = 0.3; g.fc[bg_idx(2,1) as usize] = 0.3
    g.fc[bg_idx(1,3) as usize] = 0.3; g.fc[bg_idx(3,1) as usize] = 0.3
    g.fc[bg_idx(2,4) as usize] = 0.35; g.fc[bg_idx(4,2) as usize] = 0.35
    g.fc[bg_idx(3,4) as usize] = 0.4; g.fc[bg_idx(4,3) as usize] = 0.4
    g.fc[bg_idx(3,6) as usize] = 0.3; g.fc[bg_idx(6,3) as usize] = 0.3
    g.fc[bg_idx(4,5) as usize] = 0.35; g.fc[bg_idx(5,4) as usize] = 0.35
    g.fc[bg_idx(5,6) as usize] = 0.4; g.fc[bg_idx(6,5) as usize] = 0.4
    g.fc[bg_idx(5,7) as usize] = 0.3; g.fc[bg_idx(7,5) as usize] = 0.3
    g.fc[bg_idx(6,7) as usize] = 0.35; g.fc[bg_idx(7,6) as usize] = 0.35

    // Self-connections
    var i: i32 = 0
    while i < 8 { g.fc[bg_idx(i, i) as usize] = 1.0; i = i + 1 }
