fn make_control_fc() -> BrainGraph with Mut, Panic, Div {
    var g = bg_new()
    // Control: balanced — moderate local, moderate long-range

    g.fc[bg_idx(0,1) as usize] = 0.4; g.fc[bg_idx(1,0) as usize] = 0.4   // DMN-exec
    g.fc[bg_idx(0,5) as usize] = 0.35; g.fc[bg_idx(5,0) as usize] = 0.35
    g.fc[bg_idx(1,2) as usize] = 0.45; g.fc[bg_idx(2,1) as usize] = 0.45  // exec-salience
    g.fc[bg_idx(2,3) as usize] = 0.4; g.fc[bg_idx(3,2) as usize] = 0.4   // salience-dorsal
    g.fc[bg_idx(3,4) as usize] = 0.45; g.fc[bg_idx(4,3) as usize] = 0.45  // attention pair
    g.fc[bg_idx(4,5) as usize] = 0.35; g.fc[bg_idx(5,4) as usize] = 0.35
    g.fc[bg_idx(5,6) as usize] = 0.5; g.fc[bg_idx(6,5) as usize] = 0.5   // motor-visual
    g.fc[bg_idx(6,7) as usize] = 0.3; g.fc[bg_idx(7,6) as usize] = 0.3
    g.fc[bg_idx(0,7) as usize] = 0.3; g.fc[bg_idx(7,0) as usize] = 0.3   // DMN-limbic

    var i: i32 = 0
    while i < 8 { g.fc[bg_idx(i, i) as usize] = 1.0; i = i + 1 }
    g
}

fn bg_threshold(g: BrainGraph, thresh: f64) -> BrainGraph with Mut, Panic, Div {
    var result = g
    var u: i32 = 0
    while u < 8 {
        var v: i32 = 0
        while v < 8 {
            if u != v && g.fc[bg_idx(u, v) as usize] >= thresh {
                result.adj[bg_idx(u, v) as usize] = 1
            }
            v = v + 1
        }
        u = u + 1
    }
    result
}

fn bg_compute_laplacian(g: BrainGraph) -> [f64; 64] with Mut, Panic, Div {
    var lap: [f64; 64] = [0.0; 64]
    var i: i32 = 0
    while i < 8 {
        // Degree
        var deg: f64 = 0.0
        var j: i32 = 0
        while j < 8 {
            deg = deg + (g.adj[bg_idx(i, j) as usize] as f64)
            j = j + 1
        }
        // Fill row
        j = 0
        while j < 8 {
            if i == j {
                lap[bg_idx(i, j) as usize] = deg
            } else {
                lap[bg_idx(i, j) as usize] = 0.0 - (g.adj[bg_idx(i, j) as usize] as f64)
            }
            j = j + 1
        }
        i = i + 1
    }
    lap
}

fn power_iter(mat: [f64; 64], n: i32, iters: i32, result: [f64; 8]) -> [f64; 8] with Mut, Panic, Div {
    var v = result  // initial vector
    var iter: i32 = 0
    while iter < iters {
        // w = mat * v
        var w: [f64; 8] = [0.0; 8]
        var i: i32 = 0
        while i < n {
            var s: f64 = 0.0
            var j: i32 = 0
            while j < n {
                s = s + mat[bg_idx(i, j) as usize] * v[j as usize]
                j = j + 1
            }
            w[i as usize] = s
            i = i + 1
        }
        // Normalize
        var norm: f64 = 0.0
        i = 0
        while i < n { norm = norm + w[i as usize] * w[i as usize]; i = i + 1 }
        norm = sqrt_f64(norm)
        if norm > 1e-12 {
            i = 0
            while i < n { w[i as usize] = w[i as usize] / norm; i = i + 1 }
        }
        v = w
        iter = iter + 1
    }
    v
}

fn deflate(mat: [f64; 64], n: i32, v: [f64; 8], lambda: f64) -> [f64; 64] with Mut, Panic, Div {
    var result = mat
    var i: i32 = 0
    while i < n {
        var j: i32 = 0
        while j < n {
            result[bg_idx(i, j) as usize] = result[bg_idx(i, j) as usize] - lambda * v[i as usize] * v[j as usize]
            j = j + 1
        }
        i = i + 1
    }
    result
}

fn bg_spectral_embed(g: BrainGraph) -> BrainGraph with Mut, Panic, Div {
    var result = g
    let lap = bg_compute_laplacian(g)
    var mat = lap

    // Extract 8 eigenvectors via deflated power iteration
    var eig: i32 = 0
    while eig < 8 {
        // Init with pseudo-random vector based on eigenvector index
        var init: [f64; 8] = [0.0; 8]
        var i: i32 = 0
        while i < 8 {
            // Simple deterministic init: sin-like pattern
            let val = (((i + 1) * (eig + 1) * 7 + 3) % 17) as f64 / 17.0
            init[i as usize] = val - 0.5
            i = i + 1
        }

        // Power iterate
        let v = power_iter(mat, 8, 50, init)

        // Compute eigenvalue: lambda = v^T M v
        var lambda: f64 = 0.0
        i = 0
        while i < 8 {
            var s: f64 = 0.0
            var j: i32 = 0
            while j < 8 {
                s = s + mat[bg_idx(i, j) as usize] * v[j as usize]
                j = j + 1
            }
            lambda = lambda + v[i as usize] * s
            i = i + 1
        }

        // Store eigenvector: spec[node * 8 + eig] = v[node]
        i = 0
        while i < 8 {
            result.spec[(i * 8 + eig) as usize] = v[i as usize]
            i = i + 1
        }

        // Deflate
        mat = deflate(mat, 8, v, lambda)
        eig = eig + 1
    }
    result
}

fn bg_get_spectral_oct(g: BrainGraph, node: i32) -> Oct with Mut, Panic, Div {
    var o = Oct { e: [0.0; 8] }
    var i: i32 = 0
    while i < 8 {
        o.e[i as usize] = g.spec[(node * 8 + i) as usize]
        i = i + 1
    }
    o
}

fn bg_encode_labels(g: BrainGraph) -> BrainGraph with Mut, Panic, Div {
    var result = g
    var u: i32 = 0
    while u < 8 {
        var v: i32 = 0
        while v < 8 {
            if g.adj[bg_idx(u, v) as usize] == 1 {
                let su = bg_get_spectral_oct(g, u)
                let sv = bg_get_spectral_oct(g, v)
                var diff = oct_sub(su, sv)
                let n = oct_norm(diff)
                if n > 1e-12 {
                    diff = oct_scale(diff, 1.0 / n)
                }
                let idx = bg_idx(u, v) as usize
                result.lab0[idx] = diff.e[0]; result.lab1[idx] = diff.e[1]
                result.lab2[idx] = diff.e[2]; result.lab3[idx] = diff.e[3]
                result.lab4[idx] = diff.e[4]; result.lab5[idx] = diff.e[5]
                result.lab6[idx] = diff.e[6]; result.lab7[idx] = diff.e[7]
            }
            v = v + 1
        }
        u = u + 1
    }
    result
}

fn bg_get_label(g: BrainGraph, u: i32, v: i32) -> Oct with Mut, Panic, Div {
    let idx = bg_idx(u, v) as usize
    var o = Oct { e: [0.0; 8] }
    o.e[0]=g.lab0[idx]; o.e[1]=g.lab1[idx]; o.e[2]=g.lab2[idx]; o.e[3]=g.lab3[idx]
    o.e[4]=g.lab4[idx]; o.e[5]=g.lab5[idx]; o.e[6]=g.lab6[idx]; o.e[7]=g.lab7[idx]
    o
}

fn bg_compute_stats(g: BrainGraph) -> BrainAssocStats with Mut, Panic, Div {
    var count: i32 = 0
    var sum_n: f64 = 0.0
    var max_n: f64 = 0.0
    var sum_sq: f64 = 0.0
    var zeros: i32 = 0
    var edges: i32 = 0

    // Count edges
    var u: i32 = 0
    while u < 8 {
        var v: i32 = 0
        while v < 8 {
            if g.adj[bg_idx(u, v) as usize] == 1 { edges = edges + 1 }
            v = v + 1
        }
        u = u + 1
    }

    // Compute associators over all length-3 directed paths
    u = 0
    while u < 8 {
        var v: i32 = 0
        while v < 8 {
            if g.adj[bg_idx(u, v) as usize] == 1 && u != v {
                var w: i32 = 0
                while w < 8 {
                    if g.adj[bg_idx(v, w) as usize] == 1 && v != w && w != u {
                        var x: i32 = 0
                        while x < 8 {
                            if g.adj[bg_idx(w, x) as usize] == 1 && w != x && x != v {
                                let a = bg_get_label(g, u, v)
                                let b = bg_get_label(g, v, w)
                                let c = bg_get_label(g, w, x)
                                let assoc = oct_associator(a, b, c)
                                let n = oct_norm(assoc)
                                count = count + 1
                                sum_n = sum_n + n
                                sum_sq = sum_sq + n * n
                                if n > max_n { max_n = n }
                                if n < 1e-9 { zeros = zeros + 1 }
                            }
                            x = x + 1
                        }
                    }
                    w = w + 1
                }
            }
            v = v + 1
        }
        u = u + 1
    }

    let mean = if count > 0 { sum_n / (count as f64) } else { 0.0 }
    // Compute eta = <k>^2 / N
    let avg_deg = (edges as f64) / 8.0
    let eta = avg_deg * avg_deg / 8.0

    BrainAssocStats {
        count: count,
        mean_norm: mean,
        max_norm: max_n,
        energy: sum_sq,
        zero_count: zeros,
        edge_count: edges,
        eta: eta,
    }
}

fn print_f4(x: f64) with IO, Mut, Panic, Div {
    if x < 0.0 { print("-"); print_f4(0.0 - x); return }
    let ip = x as i64
    let fp = ((x - (ip as f64)) * 10000.0 + 0.5) as i64
    print(ip); print(".")
    if fp < 10 { print("000") }
    else if fp < 100 { print("00") }
    else if fp < 1000 { print("0") }
    print(fp)
}

fn print_stats(name: i32, s: BrainAssocStats) with IO, Mut, Panic, Div {
    if name == 1 { print("  ASD     ") }
    else if name == 2 { print("  ADHD    ") }
    else if name == 3 { print("  Control ") }
    else { print("  ???     ") }

    print("| edges="); print(s.edge_count)
    print(" eta="); print_f4(s.eta)
    print(" | triples="); print(s.count)
    print(" mean="); print_f4(s.mean_norm)
    print(" max="); print_f4(s.max_norm)
    print(" zeros="); print(s.zero_count)

    // Zero fraction
    if s.count > 0 {
        print(" ("); print_f4((s.zero_count as f64) / (s.count as f64) * 100.0); print("%)")
    }
    println("")
}

fn dm_new(n: i64) -> DemoMatrix {
    DemoMatrix { data: [0.0; 2500], n: n }
}

fn dm_get(m: DemoMatrix, i: i64, j: i64) -> f64 with Panic {
    m.data[(i * m.n + j) as usize]
}

fn dm_set_sym(m: DemoMatrix, i: i64, j: i64, val: f64) -> DemoMatrix with Mut, Panic {
    var out = m
    out.data[(i * m.n + j) as usize] = val
    out.data[(j * m.n + i) as usize] = val
    out
}

fn lcg_f64(s: i64) -> f64 with Div, Panic {
    let v = if s < 0 { 0 - s } else { s }
    (v as f64) / 9223372036854775807.0
}

fn generate_connectome(
    n: i64, n_modules: i64, p_within: f64, p_between: f64, seed: i64
) -> DemoMatrix with Mut, Panic, Div {
    var m = dm_new(n)
    var s = seed

    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            s = lcg_next(s)
            let r = lcg_f64(s)
            let mod_i = i * n_modules / n
            let mod_j = j * n_modules / n
            let same_mod = mod_i == mod_j
            let p = if same_mod { p_within } else { p_between }

            if r < p {
                s = lcg_next(s)
                let w = 0.2 + 0.6 * lcg_f64(s)
                m = dm_set_sym(m, i, j, w)
            }
            j = j + 1
        }
        i = i + 1
    }
    m
}

fn generate_td(n: i64, seed: i64) -> DemoMatrix with Mut, Panic, Div {
    generate_connectome(n, 5, 0.70, 0.15, seed)
}

fn generate_asd(n: i64, seed: i64) -> DemoMatrix with Mut, Panic, Div {
    generate_connectome(n, 5, 0.55, 0.25, seed)
}

fn bg_from_matrix(m: DemoMatrix, threshold: f64) -> BinGraph with Mut, Panic, Div {
    var g = bg_new(m.n)
    var i: i64 = 0
    while i < m.n {
        var j: i64 = i + 1
        while j < m.n {
            if dm_get(m, i, j) > threshold {
                g.adj[(i * m.n + j) as usize] = 1
                g.adj[(j * m.n + i) as usize] = 1
            }
            j = j + 1
        }
        i = i + 1
    }
    g
}

fn bg_degree(g: BinGraph, v: i64) -> i64 with Mut, Panic, Div {
    var d: i64 = 0
    var j: i64 = 0
    while j < g.n {
        if g.adj[(v * g.n + j) as usize] == 1 { d = d + 1 }
        j = j + 1
    }
    d
}

fn bg_common_neighbors(g: BinGraph, u: i64, v: i64) -> i64 with Mut, Panic, Div {
    var count: i64 = 0
    var w: i64 = 0
    while w < g.n {
        if w != u && w != v {
            if g.adj[(u * g.n + w) as usize] == 1 && g.adj[(v * g.n + w) as usize] == 1 {
                count = count + 1
            }
        }
        w = w + 1
    }
    count
}

fn bg_edge_count(g: BinGraph) -> i64 with Mut, Panic, Div {
    var count: i64 = 0
    var i: i64 = 0
    while i < g.n {
        var j: i64 = i + 1
        while j < g.n {
            if g.adj[(i * g.n + j) as usize] == 1 { count = count + 1 }
            j = j + 1
        }
        i = i + 1
    }
    count
}

fn orc_lly(g: BinGraph, u: i64, v: i64) -> f64 with Mut, Panic, Div {
    let d_u = bg_degree(g, u)
    let d_v = bg_degree(g, v)
    if d_u == 0 || d_v == 0 { return 0.0 }

    let t = bg_common_neighbors(g, u, v)
    let inv_du = 1.0 / (d_u as f64)
    let inv_dv = 1.0 / (d_v as f64)
    (t as f64) * (inv_du + inv_dv) + inv_du + inv_dv - 1.0
}

fn compute_orc_stats(g: BinGraph) -> OrcStats with Mut, Panic, Div {
    var n_edges: i64 = 0
    var sum_k: f64 = 0.0
    var sum_k2: f64 = 0.0
    var min_k: f64 = 1000.0
    var max_k: f64 = 0.0 - 1000.0
    var n_pos: i64 = 0
    var n_zero: i64 = 0
    var n_neg: i64 = 0
    let eps = 0.01

    var u: i64 = 0
    while u < g.n {
        var v: i64 = u + 1
        while v < g.n {
            if g.adj[(u * g.n + v) as usize] == 1 {
                let k = orc_lly(g, u, v)
                n_edges = n_edges + 1
                sum_k = sum_k + k
                sum_k2 = sum_k2 + k * k
                if k < min_k { min_k = k }
                if k > max_k { max_k = k }
                if k > eps { n_pos = n_pos + 1 }
                else if k < (0.0 - eps) { n_neg = n_neg + 1 }
                else { n_zero = n_zero + 1 }
            }
            v = v + 1
        }
        u = u + 1
    }

    let mean = if n_edges > 0 { sum_k / (n_edges as f64) } else { 0.0 }
    let var_k = if n_edges > 0 {
        sum_k2 / (n_edges as f64) - mean * mean
    } else { 0.0 }

    OrcStats {
        n_edges: n_edges,
        mean_k: mean,
        min_k: if n_edges > 0 { min_k } else { 0.0 },
        max_k: if n_edges > 0 { max_k } else { 0.0 },
        std_k: sqrt_f64(abs_f64(var_k)),
        n_pos: n_pos, n_zero: n_zero, n_neg: n_neg,
    }
}

fn phase_name(stats: OrcStats) -> i64 with Div, Panic {
    if stats.n_edges == 0 { return 3 }
    let ne = stats.n_edges as f64
    let frac_pos = (stats.n_pos as f64) / ne
    let frac_neg = (stats.n_neg as f64) / ne
    if frac_pos > 0.5 { return 0 }
    if frac_neg > 0.5 { return 2 }
    if abs_f64(stats.mean_k) < 0.05 && stats.std_k < 0.1 { return 1 }
    3
}

fn oct_unit(idx: i64) -> Oct with Mut, Panic {
    var o = Oct { e: [0.0; 8] }
    if idx >= 0 && idx < 8 { o.e[idx as usize] = 1.0 }
    o
}

fn og_add_undir(g: OctGraph, u: i32, v: i32, label: Oct) -> OctGraph with Mut, Panic, Div {
    var r = og_set_edge(g, u, v, label)
    r = og_set_edge(r, v, u, oct_conjugate(label))
    r
}

fn og_get_label(g: OctGraph, u: i32, v: i32) -> Oct with Mut, Panic {
    let idx = og_idx(u, v) as usize
    var o = Oct { e: [0.0; 8] }
    o.e[0]=g.lab0[idx]; o.e[1]=g.lab1[idx]; o.e[2]=g.lab2[idx]; o.e[3]=g.lab3[idx]
    o.e[4]=g.lab4[idx]; o.e[5]=g.lab5[idx]; o.e[6]=g.lab6[idx]; o.e[7]=g.lab7[idx]
    o
}

fn matrix_to_octgraph(m: DemoMatrix, n_nodes: i32, threshold: f64) -> OctGraph with Mut, Panic, Div {
    var g = og_new(n_nodes)
    var i: i32 = 0
    while i < n_nodes {
        var j: i32 = i + 1
        while j < n_nodes {
            let w = dm_get(m, i as i64, j as i64)
            if w > threshold {
                // Cyclic basis labeling: weight * e_{(i+j) mod 7 + 1}
                let basis = (((i + j) as i64) % 7) + 1
                let label = oct_scale(oct_unit(basis), w)
                g = og_add_undir(g, i, j, label)
            }
            j = j + 1
        }
        i = i + 1
    }
    g
}

fn compute_assoc_stats(g: OctGraph) -> AssocStats with Mut, Panic, Div {
    var count: i32 = 0
    var sum_norm: f64 = 0.0
    var max_n: f64 = 0.0
    var sum_sq: f64 = 0.0
    var zeros: i32 = 0

    var u: i32 = 0
    while u < g.n {
        var v: i32 = 0
        while v < g.n {
            if g.adj[og_idx(u, v) as usize] == 1 && u != v {
                var w: i32 = 0
                while w < g.n {
                    if g.adj[og_idx(v, w) as usize] == 1 && v != w && w != u {
                        var x: i32 = 0
                        while x < g.n {
                            if g.adj[og_idx(w, x) as usize] == 1 && w != x && x != v {
                                let a = og_get_label(g, u, v)
                                let b = og_get_label(g, v, w)
                                let c = og_get_label(g, w, x)
                                let assoc = oct_associator(a, b, c)
                                let n = oct_norm(assoc)
                                count = count + 1
                                sum_norm = sum_norm + n
                                sum_sq = sum_sq + n * n
                                if n > max_n { max_n = n }
                                if n < 1e-9 { zeros = zeros + 1 }
                            }
                            x = x + 1
                        }
                    }
                    w = w + 1
                }
            }
            v = v + 1
        }
        u = u + 1
    }

    let mean = if count > 0 { sum_norm / (count as f64) } else { 0.0 }
    AssocStats {
        count: count, mean_norm: mean, max_norm: max_n,
        energy: sum_sq, zero_count: zeros,
    }
}

