fn ct_abs(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

fn ct_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i: i32 = 0
    while i < 30 {
        y = 0.5 * (y + x / y)
        i = i + 1
    }
    y
}

fn ct_exp(x: f64) -> f64 with Mut, Div, Panic {
    // Pade [3/3] approximation — accurate for |x| ≤ 4
    if x > 20.0 { return 485165195.4 }
    if x < 0.0-20.0 { return 0.0 }
    let x2 = x * x
    let x3 = x2 * x
    let num = 1.0 + x + 0.5*x2 + x3/6.0 + x2*x2/24.0 + x2*x3/120.0 + x3*x3/720.0
    let den_x = 0.0 - x
    let den_x2 = den_x * den_x
    let den_x3 = den_x2 * den_x
    let den = 1.0 + den_x + 0.5*den_x2 + den_x3/6.0 + den_x2*den_x2/24.0 + den_x2*den_x3/120.0 + den_x3*den_x3/720.0
    num / den
}

fn ct_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 1e30 }
    // Range-reduce to [0.5, 2.0) then use atanh series (converges fast)
    var y = x
    var k: i64 = 0
    while y >= 2.0 { y = y / 2.0; k = k + 1 }
    while y < 0.5  { y = y * 2.0; k = k - 1 }
    let u  = (y - 1.0) / (y + 1.0)
    let u2 = u * u
    let s  = u * (1.0 + u2/3.0 + u2*u2/5.0 + u2*u2*u2/7.0 + u2*u2*u2*u2/9.0)
    2.0 * s + (k as f64) * 0.6931471805599453
}

fn ct_uniform(state: i64) -> f64 {
    let s = if state < 0 { 0 - state } else { state }
    (s % 1000000) as f64 / 1000000.0
}

fn ct_cos(theta: f64) -> f64 with Mut, Div, Panic {
    let pi2  = 6.283185307
    let pi   = 3.141592653
    let pi_2 = 1.570796327
    var t = theta
    while t < 0.0  { t = t + pi2 }
    while t >= pi2 { t = t - pi2 }
    var sign: f64 = 1.0
    if t > pi   { t = t - pi; sign = 0.0 - sign }
    if t > pi_2 { t = pi - t; sign = 0.0 - sign }
    let t2 = t * t
    sign * (1.0 - t2/2.0 + t2*t2/24.0 - t2*t2*t2/720.0)
}

fn ct_normal(state1: i64, state2: i64, mean: f64, sd: f64) -> f64 with Mut, Div, Panic {
    // Box-Muller: Z = sqrt(-2*ln(U1)) * cos(2π*U2)
    let u1 = ct_uniform(state1) + 1e-12
    let u2 = ct_uniform(state2)
    mean + sd * ct_sqrt(0.0 - 2.0 * ct_ln(u1)) * ct_cos(6.283185307 * u2)
}

fn generate_weights(arm_seed: i64) -> [f64; 40] with Mut, Div, Panic {
    var w: [f64; 40] = [0.0; 40]
    var seed = arm_seed
    var i: i32 = 0
    while i < 40 {
        let s1 = lcg_next(seed)
        let s2 = lcg_next(s1)
        seed = lcg_next(s2)
        let wt = ct_normal(s1, s2, 75.0, 12.0)
        w[i as usize] = if wt < 40.0 { 40.0 } else { if wt > 130.0 { 130.0 } else { wt } }
        i = i + 1
    }
    w
}

fn compute_auc(weight_kg: f64, dose_mg_per_kg: f64) -> f64 with Mut, Div, Panic {
    let ref_weight: f64 = 70.0
    let ref_cl: f64 = 5.0  // L/h at 70kg
    // Allometric CL scaling: CL_i = CL_ref * (W/W_ref)^0.75
    // Approximate (W/W_ref)^0.75 = exp(0.75 * ln(W/W_ref))
    let ratio = weight_kg / ref_weight
    let ln_ratio = ct_ln(ratio)
    let scaled_cl = ref_cl * ct_exp(0.75 * ln_ratio)
    let dose_total = dose_mg_per_kg * weight_kg
    // AUC = Dose / CL  (mg*h/L)
    dose_total / scaled_cl
}

fn compute_arm_aucs(weights: [f64; 40], dose: f64) -> [f64; 40] with Mut, Div, Panic {
    var aucs: [f64; 40] = [0.0; 40]
    var i: i32 = 0
    while i < 40 {
        aucs[i as usize] = compute_auc(weights[i as usize], dose)
        i = i + 1
    }
    aucs
}

fn mean_40(arr: [f64; 40]) -> f64 with Mut, Div, Panic {
    var s: f64 = 0.0
    var i: i32 = 0
    while i < 40 {
        s = s + arr[i as usize]
        i = i + 1
    }
    s / 40.0
}

fn std_40(arr: [f64; 40], m: f64) -> f64 with Mut, Div, Panic {
    var s: f64 = 0.0
    var i: i32 = 0
    while i < 40 {
        let d = arr[i as usize] - m
        s = s + d * d
        i = i + 1
    }
    ct_sqrt(s / 39.0)  // sample SD
}

fn welch_t(m1: f64, s1: f64, m2: f64, s2: f64, n: f64) -> f64 with Mut, Div, Panic {
    let se = ct_sqrt(s1*s1/n + s2*s2/n)
    if se < 1e-12 { return 0.0 }
    (m1 - m2) / se
}

fn gum_auc_budget(auc_mean: f64) -> f64 with Mut, Div, Panic {
    // Type A: CV=3%, n=6 → u_A = AUC * 0.03 / sqrt(6)
    let u_a = auc_mean * 0.03 / ct_sqrt(6.0)
    // Type B: half-width = AUC * 0.02, rectangular → u_B = 0.02*AUC / sqrt(3)
    let u_b = auc_mean * 0.02 / ct_sqrt(3.0)
    // Allometric: half-width = AUC * 0.05, normal → already std
    let u_allom = auc_mean * 0.05
    // Combined standard uncertainty
    ct_sqrt(u_a*u_a + u_b*u_b + u_allom*u_allom)
}

fn beta_posterior_mean(n_resp: i64, n: i64) -> f64 with Div, Panic {
    let alpha = 1.0 + (n_resp as f64)
    let beta_p = 1.0 + (n as f64) - (n_resp as f64)
    alpha / (alpha + beta_p)
}

fn beta_posterior_sd(n_resp: i64, n: i64) -> f64 with Mut, Div, Panic {
    let alpha = 1.0 + (n_resp as f64)
    let beta_p = 1.0 + (n as f64) - (n_resp as f64)
    let ab = alpha + beta_p
    ct_sqrt(alpha * beta_p / (ab * ab * (ab + 1.0)))
}

fn apply(f: fn(i64) -> i64, x: i64) -> i64 {
    f(x)
}

fn bitset_new(len: usize) -> BitSet with Alloc {
    let num_words = (len + 63) / 64
    let size_bytes = num_words * 8
    let ptr = malloc(size_bytes) as *mut u64

    var i: usize = 0
    while i < num_words {
        ptr[i] = 0
        i = i + 1
    }

    let result = BitSet {
        bits: ptr,
        len: len,
        num_words: num_words,
    }
    return result
}

fn bitset_set(bs: &!BitSet, index: usize) with Panic {
    if index >= bs.len {
        panic("BitSet index out of bounds")
    }
    let word = index / 64
    let bit = index % 64
    bs.bits[word] = bs.bits[word] | (1u64 << bit)
}

fn bitset_clear(bs: &!BitSet, index: usize) with Panic {
    if index >= bs.len {
        panic("BitSet index out of bounds")
    }
    let word = index / 64
    let bit = index % 64
    bs.bits[word] = bs.bits[word] & !(1u64 << bit)
}

fn bitset_get(bs: &BitSet, index: usize) -> bool with Panic {
    if index >= bs.len {
        panic("BitSet index out of bounds")
    }
    let word = index / 64
    let bit = index % 64
    return (bs.bits[word] & (1u64 << bit)) != 0
}

fn bitset_count_ones(bs: &BitSet) -> usize {
    var count: usize = 0
    var i: usize = 0
    while i < bs.num_words {
        count = count + popcount64(bs.bits[i])
        i = i + 1
    }
    return count
}

fn bitset_union_with(bs: &!BitSet, other: &BitSet) with Panic {
    if bs.len != other.len {
        panic("BitSet union requires same length")
    }
    var i: usize = 0
    while i < bs.num_words {
        bs.bits[i] = bs.bits[i] | other.bits[i]
        i = i + 1
    }
}

fn bitset_intersect_with(bs: &!BitSet, other: &BitSet) with Panic {
    if bs.len != other.len {
        panic("BitSet intersection requires same length")
    }
    var i: usize = 0
    while i < bs.num_words {
        bs.bits[i] = bs.bits[i] & other.bits[i]
        i = i + 1
    }
}

fn bitset_drop(bs: &!BitSet) with Alloc {
    if bs.bits != null_mut() {
        free(bs.bits as *mut u8)
        bs.bits = null_mut()
    }
}

fn heap_new() -> BinaryHeap with Alloc {
    let initial_cap = 16
    let size_bytes = initial_cap * 8
    let ptr = malloc(size_bytes) as *mut i64

    let result = BinaryHeap {
        data: ptr,
        len: 0,
        cap: initial_cap,
    }
    return result
}

fn heap_push(h: &!BinaryHeap, item: i64) with Alloc, Panic, Div {
    if h.len >= h.cap {
        let new_cap = h.cap * 2
        let size_bytes = new_cap * 8
        let new_ptr = realloc(h.data as *mut u8, size_bytes) as *mut i64
        h.data = new_ptr
        h.cap = new_cap
    }

    h.data[h.len] = item
    h.len = h.len + 1
    heap_sift_up(&!h, h.len - 1)
}

fn heap_pop(h: &!BinaryHeap) -> Option<i64> with Panic, Div {
    if h.len == 0 {
        return None
    }

    let root = h.data[0]
    h.len = h.len - 1

    if h.len > 0 {
        h.data[0] = h.data[h.len]
        heap_sift_down(&!h, 0)
    }

    return Some(root)
}

fn heap_peek(h: &BinaryHeap) -> Option<i64> with Panic {
    if h.len == 0 {
        return None
    }
    return Some(h.data[0])
}

fn heap_sift_up(h: &!BinaryHeap, pos: usize) with Panic, Div {
    var current = pos

    while current > 0 {
        let parent = (current - 1) / 2

        if h.data[current] >= h.data[parent] {
            break
        }

        let temp = h.data[current]
        h.data[current] = h.data[parent]
        h.data[parent] = temp

        current = parent
    }
}

fn heap_sift_down(h: &!BinaryHeap, pos: usize) with Panic, Div {
    let len = h.len
    var current = pos

    while true {
        let left = 2 * current + 1
        let right = 2 * current + 2
        var smallest = current

        if left < len && h.data[left] < h.data[smallest] {
            smallest = left
        }

        if right < len && h.data[right] < h.data[smallest] {
            smallest = right
        }

        if smallest == current {
            break
        }

        let temp = h.data[current]
        h.data[current] = h.data[smallest]
        h.data[smallest] = temp

        current = smallest
    }
}

fn heap_drop(h: &!BinaryHeap) with Alloc {
    if h.data != null_mut() {
        free(h.data as *mut u8)
        h.data = null_mut()
    }
}

