fn rhs3(t: f64, y: [f64; 9]) -> [f64; 9] with Mut, Panic, Div {
    var dy: [f64; 9] = [0.0; 9]

    let cit_gut = y[0]
    let cit_pla = y[1]
    let bup_gut = y[2]
    let bup_pla = y[3]
    let cod_gut = y[4]
    let cod_pla = y[5]
    let morphine = y[6]
    let cyp2d6 = y[7]
    let cyp2c19 = y[8]

    // Citalopram
    dy[0] = 0.0 - cit_ka() * cit_gut
    let cit_cl = cit_cl_2c19() * cyp2c19 + cit_cl_3a4()
    dy[1] = cit_ka() * cit_gut * cit_f() - (cit_cl / cit_vd()) * cit_pla

    // Bupropion
    dy[2] = 0.0 - bup_ka() * bup_gut
    let bup_cl = bup_cl_2b6()
    dy[3] = bup_ka() * bup_gut * bup_f() - (bup_cl / bup_vd()) * bup_pla

    // Codeine — the KEY drug
    dy[4] = 0.0 - cod_ka() * cod_gut
    // CYP2D6 pathway: codeine → morphine (ACTIVE — this is what matters)
    let cod_to_morphine = (cod_cl_2d6() * cyp2d6 / cod_vd()) * cod_pla
    // CYP3A4 pathway: codeine → norcodeine (inactive)
    let cod_to_norcodeine = (cod_cl_3a4() / cod_vd()) * cod_pla
    dy[5] = cod_ka() * cod_gut * cod_f() - cod_to_morphine - cod_to_norcodeine

    // Morphine (the efficacy marker — more morphine = more pain relief)
    // Simple elimination: t1/2 ≈ 3h
    let morphine_ke = 0.23  // elimination rate (1/h)
    dy[6] = cod_to_morphine - morphine_ke * morphine

    // CYP2D6: inhibited by bupropion
    let bup_um = (bup_pla / bup_vd()) * 1000.0 / 240.0
    let target_2d6 = 1.0 / (1.0 + bup_um / bup_ki_2d6())
    dy[7] = (target_2d6 - cyp2d6) * 2.0

    // CYP2C19: weakly inhibited by citalopram
    let cit_um = (cit_pla / cit_vd()) * 1000.0 / 324.0
    let target_2c19 = 1.0 / (1.0 + cit_um / cit_ki_2c19())
    dy[8] = (target_2c19 - cyp2c19) * 2.0

    dy
}

fn rk4_step3(t: f64, y: [f64; 9], dt: f64) -> [f64; 9] with Mut, Panic, Div {
    let k1 = rhs3(t, y)
    var y2: [f64; 9] = [0.0; 9]
    var i: i32 = 0
    while i < 9 { y2[i] = y[i] + 0.5 * dt * k1[i]; i = i + 1 }
    let k2 = rhs3(t + 0.5 * dt, y2)
    var y3: [f64; 9] = [0.0; 9]
    i = 0
    while i < 9 { y3[i] = y[i] + 0.5 * dt * k2[i]; i = i + 1 }
    let k3 = rhs3(t + 0.5 * dt, y3)
    var y4: [f64; 9] = [0.0; 9]
    i = 0
    while i < 9 { y4[i] = y[i] + dt * k3[i]; i = i + 1 }
    let k4 = rhs3(t + dt, y4)
    var r: [f64; 9] = [0.0; 9]
    i = 0
    while i < 9 {
        r[i] = y[i] + (dt / 6.0) * (k1[i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i])
        i = i + 1
    }
    r
}

fn rhs(t: f64, y: [f64; 6]) -> [f64; 6] with Mut, Panic, Div {
    var dy: [f64; 6] = [0.0; 6]

    let cit_gut = y[0]
    let cit_pla = y[1]
    let bup_gut = y[2]
    let bup_pla = y[3]
    let cyp2d6_act = y[4]
    let cyp2c19_act = y[5]

    // Citalopram: gut → plasma (first-order absorption)
    dy[0] = 0.0 - cit_ka() * cit_gut

    // Citalopram plasma: absorption - clearance
    // CYP2C19 clearance modulated by enzyme activity
    let cit_cl_total = cit_cl_2c19() * cyp2c19_act + cit_cl_3a4()
    dy[1] = cit_ka() * cit_gut * cit_f() - (cit_cl_total / cit_vd()) * cit_pla

    // Bupropion: gut → plasma
    dy[2] = 0.0 - bup_ka() * bup_gut

    // Bupropion plasma: absorption - clearance
    // CYP2B6 + minor CYP2C19
    let bup_cl_total = bup_cl_2b6() + bup_cl_2c19() * cyp2c19_act
    dy[3] = bup_ka() * bup_gut * bup_f() - (bup_cl_total / bup_vd()) * bup_pla

    // CYP2D6 activity: inhibited by bupropion (competitive)
    // activity = 1 / (1 + [bup] / Ki)
    // Convert bup_pla (mg) to μM: MW bupropion ≈ 240 g/mol
    let bup_um = (bup_pla / bup_vd()) * 1000.0 / 240.0
    let target_2d6 = 1.0 / (1.0 + bup_um / bup_ki_2d6())
    dy[4] = (target_2d6 - cyp2d6_act) * 2.0  // rapid equilibrium

    // CYP2C19 activity: weakly inhibited by citalopram
    let cit_um = (cit_pla / cit_vd()) * 1000.0 / 324.0  // MW citalopram ≈ 324
    let target_2c19 = 1.0 / (1.0 + cit_um / cit_ki_2c19())
    dy[5] = (target_2c19 - cyp2c19_act) * 2.0

    dy
}

fn rk4_step(t: f64, y: [f64; 6], dt: f64) -> [f64; 6] with Mut, Panic, Div {
    let k1 = rhs(t, y)

    var y2: [f64; 6] = [0.0; 6]
    var i: i32 = 0
    while i < 6 { y2[i] = y[i] + 0.5 * dt * k1[i]; i = i + 1 }
    let k2 = rhs(t + 0.5 * dt, y2)

    var y3: [f64; 6] = [0.0; 6]
    i = 0
    while i < 6 { y3[i] = y[i] + 0.5 * dt * k2[i]; i = i + 1 }
    let k3 = rhs(t + 0.5 * dt, y3)

    var y4: [f64; 6] = [0.0; 6]
    i = 0
    while i < 6 { y4[i] = y[i] + dt * k3[i]; i = i + 1 }
    let k4 = rhs(t + dt, y4)

    var result: [f64; 6] = [0.0; 6]
    i = 0
    while i < 6 {
        result[i] = y[i] + (dt / 6.0) * (k1[i] + 2.0 * k2[i] + 2.0 * k3[i] + k4[i])
        i = i + 1
    }
    result
}

fn dose_cit(y: [f64; 6]) -> [f64; 6] with Mut, Panic, Div {
    var r: [f64; 6] = [0.0; 6]
    var i: i32 = 0
    while i < 6 { r[i] = y[i]; i = i + 1 }
    r[0] = r[0] + cit_dose()
    r
}

fn dose_bup(y: [f64; 6]) -> [f64; 6] with Mut, Panic, Div {
    var r: [f64; 6] = [0.0; 6]
    var i: i32 = 0
    while i < 6 { r[i] = y[i]; i = i + 1 }
    r[2] = r[2] + bup_dose()
    r
}

fn simulate(start_bup_day: i32) -> [f64; 4] with Mut, Panic, Div {
    // Returns: [cit_auc, bup_auc, cyp2d6_mean, cyp2c19_mean]
    var y: [f64; 6] = [0.0; 6]
    y[4] = 1.0  // CYP2D6 fully active
    y[5] = 1.0  // CYP2C19 fully active

    let dt: f64 = 0.25        // 15-min steps
    let days: i32 = 28        // 4 weeks
    let steps_per_day: i32 = 96  // 24h / 0.25h

    var cit_auc: f64 = 0.0
    var bup_auc: f64 = 0.0
    var cyp2d6_sum: f64 = 0.0
    var cyp2c19_sum: f64 = 0.0
    var total_steps: i32 = 0

    var day: i32 = 0
    while day < days {
        // Daily dosing at t=0 of each day
        y = dose_cit(y)
        if day >= start_bup_day {
            y = dose_bup(y)
        }

        // Integrate through the day
        var step: i32 = 0
        while step < steps_per_day {
            y = rk4_step((day * 24 + step) as f64 * dt, y, dt)

            // Clamp negatives
            var ci: i32 = 0
            while ci < 4 {
                if y[ci] < 0.0 { y[ci] = 0.0 }
                ci = ci + 1
            }
            if y[4] < 0.01 { y[4] = 0.01 }
            if y[5] < 0.01 { y[5] = 0.01 }
            if y[4] > 1.0 { y[4] = 1.0 }
            if y[5] > 1.0 { y[5] = 1.0 }

            // Accumulate AUC (trapezoidal)
            cit_auc = cit_auc + y[1] * dt
            bup_auc = bup_auc + y[3] * dt
            cyp2d6_sum = cyp2d6_sum + y[4]
            cyp2c19_sum = cyp2c19_sum + y[5]
            total_steps = total_steps + 1

            step = step + 1
        }
        day = day + 1
    }

    var result: [f64; 4] = [0.0; 4]
    result[0] = cit_auc
    result[1] = bup_auc
    result[2] = cyp2d6_sum / (total_steps as f64)
    result[3] = cyp2c19_sum / (total_steps as f64)
    result
}

fn init_table() with Mut {
    var i = 0
    while i < 8 {
        MULT[0*8+i] = i; SIGN[0*8+i] = 1
        MULT[i*8+0] = i; SIGN[i*8+0] = 1
        i = i + 1
    }
    i = 1
    while i < 8 { MULT[i*8+i] = 0; SIGN[i*8+i] = 0-1; i = i + 1 }
    var FA: [i64; 7] = [1,2,3,4,5,6,7]
    var FB: [i64; 7] = [2,3,4,5,6,7,1]
    var FC: [i64; 7] = [4,5,6,7,1,2,3]
    var t = 0
    while t < 7 {
        let a = FA[t]; let b = FB[t]; let c = FC[t]
        MULT[a*8+b]=c; SIGN[a*8+b]=1; MULT[b*8+a]=c; SIGN[b*8+a]=0-1
        MULT[b*8+c]=a; SIGN[b*8+c]=1; MULT[c*8+b]=a; SIGN[c*8+b]=0-1
        MULT[c*8+a]=b; SIGN[c*8+a]=1; MULT[a*8+c]=b; SIGN[a*8+c]=0-1
        t = t + 1
    }
}

fn basis_mul(i_idx: i64, i_sgn: i64, j_idx: i64, j_sgn: i64) with Mut {
    RES_IDX = MULT[i_idx*8+j_idx]
    RES_SGN = i_sgn * j_sgn * SIGN[i_idx*8+j_idx]
}

fn clear_adj() with Mut {
    var i = 0
    while i < 144 { ADJ[i] = 0; ADJ_SGN[i] = 0; i = i + 1 }
}

fn add_edge(i: i64, j: i64, label: i64) with Mut {
    ADJ[i*12+j] = label
    ADJ_SGN[i*12+j] = 1
    ADJ[j*12+i] = label
    ADJ_SGN[j*12+i] = 0 - 1
}

fn assign_label(is_intra: i64) -> i64 with Mut {
    if is_intra == 1 {
        let r = (rng_next() / 100) % 5
        if r < 2 { return 1 }
        if r < 3 { return 2 }
        if r < 4 { return 3 }
        return 4
    }
    // Inter-module
    let r = (rng_next() / 100) % 3
    if r < 1 { return 5 }
    if r < 2 { return 6 }
    7
}

fn generate_td() with Mut {
    clear_adj()
    // Module 1: nodes 0-5, Module 2: nodes 6-11
    // Intra: p=0.8, Inter: p=0.1
    var i = 0
    while i < 12 {
        var j = i + 1
        while j < 12 {
            let same_module = (i < 6) == (j < 6)
            let r = (rng_next() / 100) % 100
            var connect = 0
            if same_module == true {
                if r < 80 { connect = 1 }
            } else {
                if r < 10 { connect = 1 }
            }
            if connect == 1 {
                var is_intra = 0
                if same_module == true { is_intra = 1 }
                let label = assign_label(is_intra)
                add_edge(i, j, label)
            }
            j = j + 1
        }
        i = i + 1
    }
}

fn generate_asd() with Mut {
    clear_adj()
    // Intra: p=0.5, Inter: p=0.3
    var i = 0
    while i < 12 {
        var j = i + 1
        while j < 12 {
            let same_module = (i < 6) == (j < 6)
            let r = (rng_next() / 100) % 100
