fn sequences_equal(a: &Sequence, b: &Sequence) -> bool {
    let len_a = a.len()
    let len_b = b.len()
    if len_a != len_b { return false }

    var i: usize = 0
    while i < len_a {
        if a[i] != b[i] { return false }
        i = i + 1
    }
    true
}

fn is_in_orbit(seq: &Sequence, orbit: &[Sequence], count: usize) -> bool {
    var i: usize = 0
    let len = if count < orbit.len() { count } else { orbit.len() }
    while i < len {
        if sequences_equal(seq, &orbit[i]) {
            return true
        }
        i = i + 1
    }
    false
}

fn cyclic_period(seq: &Sequence) -> usize {
    let n = seq.len()
    if n == 0 { return 1 }

    var k: usize = 1
    while k <= n {
        if n % k == 0 {
            // Check if shift by k equals original
            let shifted = seq[k..] ++ seq[..k]
            if sequences_equal(seq, &shifted) {
                return k
            }
        }
        k = k + 1
    }
    n
}

fn rotational_symmetries(seq: &Sequence) -> usize {
    let n = seq.len()
    if n == 0 { return 1 }
    n / cyclic_period(seq)
}

fn has_reflective_symmetry(seq: &Sequence) -> bool {
    let n = seq.len()
    if n == 0 { return true }

    let rev = reverse(seq)
    var k: usize = 0
    while k < n {
        let shifted_rev = rev[k..] ++ rev[..k]
        if sequences_equal(seq, &shifted_rev) {
            return true
        }
        k = k + 1
    }
    false
}

pub fn orbit_size(seq: &Sequence) -> usize {
    let n = seq.len()
    if n == 0 { return 1 }

    // Dihedral group order: 2n
    let two: usize = 2
    let group_order = two * n

    // Stabilizer size = rotational symmetries × reflective factor
    let rot_sym = rotational_symmetries(seq)
    let ref_factor: usize = if has_reflective_symmetry(seq) { 2 } else { 1 }
    let stabilizer_size = rot_sym * ref_factor

    // Orbit-stabilizer theorem: |orbit| = |G| / |Stab(x)|
    group_order / stabilizer_size
}

pub fn orbit_ratio(seq: &Sequence) -> f64 {
    let n = seq.len()
    if n == 0 { return 1.0 }
    orbit_size(seq) as f64 / (2 * n) as f64
}

pub fn is_palindrome(seq: &Sequence) -> bool {
    let rev = reverse(seq)
    sequences_equal(seq, &rev)
}

pub fn is_rc_fixed(seq: &Sequence) -> bool {
    let rc = reverse_complement(seq)
    sequences_equal(seq, &rc)
}

pub fn rotational_period(seq: &Sequence) -> usize {
    let n = seq.len()
    if n == 0 { return 1 }

    var k: usize = 1
    while k <= n {
        if n % k == 0 {
            let shifted = shift(seq, k)
            if sequences_equal(seq, &shifted) {
                return k
            }
        }
        k = k + 1
    }
    n
}

