fn convert_to_bases(s: [u8], len: usize) -> [Base] {
    var bases: [Base] = []
    var i: usize = 0
    while i < len {
        bases.push((s[i] & 0x03) as Base)
        i = i + 1
    }
    bases
}

fn abs_f64(x: f64) -> f64  with Div, Panic {
    if x < 0.0 { return -x }
    return x
}

fn normalize_angle(x: f64) -> f64  with Div, Panic {
    var angle = x
    while angle > PI {
        angle = angle - 2.0 * PI
    }
    while angle < -PI {
        angle = angle + 2.0 * PI
    }
    return angle
}

fn sin_approx(x: f64) -> f64  with Div, Panic {
    let angle = normalize_angle(x)
    let x2 = angle * angle
    let x3 = angle * x2
    let x5 = x3 * x2
    let x7 = x5 * x2
    return angle - x3 / 6.0 + x5 / 120.0 - x7 / 5040.0
}

fn cos_approx(x: f64) -> f64  with Div, Panic {
    let angle = normalize_angle(x)
    let x2 = angle * angle
    let x4 = x2 * x2
    let x6 = x4 * x2
    return 1.0 - x2 / 2.0 + x4 / 24.0 - x6 / 720.0
}

fn atan(x: f64) -> f64  with Div, Panic {
    let ax = abs_f64(x)
    if ax <= 1.0 {
        let x2 = x * x
        return x * (1.0 - x2 * (1.0 / 3.0 - x2 * (1.0 / 5.0 - x2 * (1.0 / 7.0))))
    }
    let sign = if x > 0.0 { 1.0 } else { -1.0 }
    let inv = 1.0 / x
    let inv2 = inv * inv
    return sign * (PI / 2.0 - inv * (1.0 - inv2 * (1.0 / 3.0 - inv2 * (1.0 / 5.0))))
}

fn atan2(y: f64, x: f64) -> f64  with Div, Panic {
    if x > 0.0 {
        return atan(y / x)
    }
    if x < 0.0 && y >= 0.0 {
        return atan(y / x) + PI
    }
    if x < 0.0 && y < 0.0 {
        return atan(y / x) - PI
    }
    if x == 0.0 && y > 0.0 {
        return PI / 2.0
    }
    if x == 0.0 && y < 0.0 {
        return -PI / 2.0
    }
    return 0.0
}

fn sequence_shift(seq: [u8], k: usize) -> [u8]  with Div, Panic {
    let n = seq.len()
    if n == 0 { return [] }

    let k_mod = k % n
    var result: [u8] = []
    var i: usize = 0
    while i < n {
        let idx = (i + k_mod) % n
        result.push(seq[idx])
        i = i + 1
    }
    return result
}

fn sequence_reverse(seq: [u8]) -> [u8]  with Div, Panic {
    let n = seq.len()
    if n == 0 { return [] }

    var result: [u8] = []
    var i: usize = 0
    while i < n {
        result.push(seq[n - 1 - i])
        i = i + 1
    }
    return result
}

fn complement_base(b: u8) -> u8  with Div, Panic {
    return b ^ 3
}

fn sequence_complement(seq: [u8]) -> [u8]  with Div, Panic {
    let n = seq.len()
    if n == 0 { return [] }

    var result: [u8] = []
    var i: usize = 0
    while i < n {
        result.push(complement_base(seq[i]))
        i = i + 1
    }
    return result
}

fn sequence_reverse_complement(seq: [u8]) -> [u8]  with Div, Panic {
    let rev = sequence_reverse(seq)
    return sequence_complement(rev)
}

fn sequences_equal(a: [u8], b: [u8]) -> bool  with Div, Panic {
    let len_a = a.len()
    let len_b = b.len()
    if len_a != len_b { return false }

