        i = i + 1
    }
    return true
}

fn hamming_distance(a: [u8], b: [u8]) -> usize  with Div, Panic {
    let len_a = a.len()
    let len_b = b.len()
    if len_a != len_b { return 0 }

    var count: usize = 0
    var i: usize = 0
    while i < len_a {
        if a[i] != b[i] {
            count = count + 1
        }
        i = i + 1
    }
    return count
}

fn cyclic_period(seq: [u8]) -> usize  with Div, Panic {
    let n = seq.len()
    if n == 0 { return 1 }

    var k: usize = 1
    while k <= n {
        if n % k == 0 {
            let shifted = sequence_shift(seq, k)
            if sequences_equal(seq, shifted) {
                return k
            }
        }
        k = k + 1
    }
    return n
}

fn rotational_symmetries(seq: [u8]) -> usize  with Div, Panic {
    let n = seq.len()
    if n == 0 { return 1 }
    return n / cyclic_period(seq)
}

fn has_reflective_symmetry(seq: [u8]) -> bool  with Div, Panic {
