fn dmin(seq: [u8], include_rc: bool) -> usize  with Div, Panic {
    let n = seq.len()
    if n == 0 { return 0 }

    var min_dist = n

    var k: usize = 1
    while k < n {
        let shifted = sequence_shift(seq, k)
        let d = hamming_distance(seq, shifted)
        if d < min_dist { min_dist = d }
        k = k + 1
    }

    let rev = sequence_reverse(seq)
    k = 0
    while k < n {
        let shifted_rev = sequence_shift(rev, k)
        let d = hamming_distance(seq, shifted_rev)
        if d < min_dist { min_dist = d }
        k = k + 1
    }

    if include_rc {
        let rc = sequence_reverse_complement(seq)
        k = 0
        while k < n {
            let shifted_rc = sequence_shift(rc, k)
            let d = hamming_distance(seq, shifted_rc)
            if d < min_dist { min_dist = d }
            k = k + 1
        }
    }

    return min_dist
}

fn dmin_normalized(seq: [u8], include_rc: bool) -> f64  with Div, Panic {
    let n = seq.len()
    if n == 0 { return 0.0 }
    return (dmin(seq, include_rc) as f64) / (n as f64)
}

fn nearest_transform(seq: [u8], include_rc: bool) -> (usize, NearestTransform)  with Div, Panic {
    let n = seq.len()
    if n == 0 {
        return (0, NearestTransform { kind: TRANSFORM_SHIFT(), k: 0 })
    }

    var min_dist = n
    var nearest_kind = TRANSFORM_SHIFT()
    var nearest_k: usize = 1

    var k: usize = 1
    while k < n {
        let d = hamming_distance(seq, sequence_shift(seq, k))
        if d < min_dist {
            min_dist = d
            nearest_kind = TRANSFORM_SHIFT()
            nearest_k = k
        }
        k = k + 1
    }

    let rev = sequence_reverse(seq)
    k = 0
    while k < n {
        let d = hamming_distance(seq, sequence_shift(rev, k))
        if d < min_dist {
            min_dist = d
            nearest_kind = TRANSFORM_REVERSE_SHIFT()
            nearest_k = k
        }
        k = k + 1
    }

    if include_rc {
        let rc = sequence_reverse_complement(seq)
        k = 0
        while k < n {
            let d = hamming_distance(seq, sequence_shift(rc, k))
            if d < min_dist {
                min_dist = d
                nearest_kind = TRANSFORM_RC_SHIFT()
                nearest_k = k
            }
            k = k + 1
        }
    }

    return (min_dist, NearestTransform { kind: nearest_kind, k: nearest_k })
}

fn quaternion_new(w: f64, x: f64, y: f64, z: f64) -> Quaternion  with Div, Panic {
    Quaternion { w: w, x: x, y: y, z: z }
}

fn quaternion_identity() -> Quaternion  with Div, Panic {
    quaternion_new(1.0, 0.0, 0.0, 0.0)
}

fn quaternion_neg_identity() -> Quaternion  with Div, Panic {
    quaternion_new(-1.0, 0.0, 0.0, 0.0)
}

fn quaternion_mul(a: &Quaternion, b: &Quaternion) -> Quaternion  with Div, Panic {
    quaternion_new(
        a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
        a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
        a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
        a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w
    )
}

fn quaternion_neg(q: &Quaternion) -> Quaternion  with Div, Panic {
    quaternion_new(-q.w, -q.x, -q.y, -q.z)
}

fn quaternion_approx_eq(a: &Quaternion, b: &Quaternion, tol: f64) -> bool  with Div, Panic {
    abs_f64(a.w - b.w) < tol
        && abs_f64(a.x - b.x) < tol
        && abs_f64(a.y - b.y) < tol
        && abs_f64(a.z - b.z) < tol
}

fn dicyclic_group_new(n: usize) -> DicyclicGroup  with Div, Panic {
    DicyclicGroup { n: n }
}

fn dicyclic_order(g: &DicyclicGroup) -> usize  with Div, Panic {
    return 4 * g.n
}

fn dicyclic_element(g: &DicyclicGroup, k: usize, is_reflection: bool) -> DicyclicElement  with Div, Panic {
    let n = g.n
    let theta = PI * (k as f64) / (n as f64)
    let a_k = quaternion_new(cos_approx(theta), sin_approx(theta), 0.0, 0.0)

    if is_reflection {
        let b = quaternion_new(0.0, 0.0, 1.0, 0.0)
        return DicyclicElement { q: quaternion_mul(&a_k, &b) }
    }
    return DicyclicElement { q: a_k }
}

fn project_to_dihedral(elem: &DicyclicElement, g: &DicyclicGroup) -> (usize, bool)  with Div, Panic {
    let q = &elem.q
    let n = g.n
    let is_reflection = abs_f64(q.y) > 0.0000000001 || abs_f64(q.z) > 0.0000000001

    let angle = atan2(q.x, q.w)
    let k_float = angle * (n as f64) / PI
    let k_raw: i64 = if k_float >= 0.0 { (k_float + 0.5) as i64 } else { (k_float - 0.5) as i64 }
    let n_i64 = n as i64
    let k_mod = ((k_raw % n_i64) + n_i64) % n_i64
    let k = k_mod as usize

    return (k, is_reflection)
}

fn verify_double_cover(g: &DicyclicGroup) -> bool  with Div, Panic {
    let n = g.n

    var k: usize = 0
    while k < 2 * n {
        var is_ref_idx: usize = 0
        while is_ref_idx < 2 {
            let is_ref = is_ref_idx == 1
            let elem = dicyclic_element(g, k, is_ref)
            let neg_elem = DicyclicElement { q: quaternion_neg(&elem.q) }

            let proj1 = project_to_dihedral(&elem, g)
            let proj2 = project_to_dihedral(&neg_elem, g)

            if proj1.0 != proj2.0 || proj1.1 != proj2.1 {
                return false
            }
            is_ref_idx = is_ref_idx + 1
        }
        k = k + 1
    }
    return true
}

fn run_atlas_metrics(seq: [u8], include_rc: bool, dicyclic_n: usize) -> AtlasMetrics  with Div, Panic {
    let stats = compute_symmetry_stats(seq)
    let dmin_value = dmin(seq, include_rc)
    let dmin_norm = if stats.length == 0 { 0.0 } else { (dmin_value as f64) / (stats.length as f64) }

    let g = dicyclic_group_new(dicyclic_n)
    let double_cover_ok = verify_double_cover(&g)

    AtlasMetrics {
        length: stats.length,
        orbit_size: stats.orbit_size,
        orbit_ratio: stats.orbit_ratio,
        dmin: dmin_value,
        dmin_normalized: dmin_norm,
        is_palindrome: stats.is_palindrome,
        is_rc_fixed: stats.is_rc_fixed,
        rotational_period: stats.rotational_period,
        double_cover_ok: double_cover_ok,
    }
}

fn pipeline_ok(metrics: AtlasMetrics) -> bool  with Div, Panic {
    if metrics.length == 0 { return false }
    if metrics.orbit_size < 1 { return false }
    if metrics.orbit_ratio < 0.0 || metrics.orbit_ratio > 1.0 { return false }
    if metrics.dmin > metrics.length { return false }
    if metrics.dmin_normalized < 0.0 || metrics.dmin_normalized > 1.0 { return false }
    if !metrics.double_cover_ok { return false }
    return true
}

