fn complement(seq: &[u8]) -> [u8] {
    return seq.map(|b| b ^ 3)
}

fn reverse_complement(seq: &[u8]) -> [u8] {
    let rev = seq.reverse()
    return rev.map(|b| b ^ 3)
}

fn hamming_distance(seq1: &[u8], seq2: &[u8], n: i32) -> i32 {
    var count = 0
    var i = 0
    while i < n {
        if seq1[i] != seq2[i] {
            count = count + 1
        }
        i = i + 1
    }
    return count
}

