fn load_data() with Mut, IO, Div {
    var buf: [i8; 32768] = [0; 32768]
    let fd = syscall6(2, "/tmp/concrete_data.txt", 0, 0, 0, 0, 0)
    if fd < 0 { print("error: cannot open concrete data\n"); return }
    let n = syscall6(0, fd, &buf, 32767, 0, 0, 0)
    syscall6(3, fd, 0, 0, 0, 0, 0)

    // Skip header until ---DATA---
    var pos: i64 = 0
    while pos < n {
        if buf[pos] == 45 && buf[pos + 1] == 45 && buf[pos + 2] == 45 && buf[pos + 3] == 68 {
            while pos < n && buf[pos] != 10 { pos = pos + 1 }
            if pos < n { pos = pos + 1 }
            break
        }
        pos = pos + 1
    }

    // Parse lines: 8 features + 1 target per line
    var si = 0
    while pos < n && si < 200 {
        var fi = 0
        while fi < 9 && pos < n {
            while pos < n && buf[pos] == 32 { pos = pos + 1 }
            var int_part: i64 = 0
            while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                int_part = int_part * 10 + ((buf[pos] - 48) as i64)
                pos = pos + 1
            }
            var frac = 0.0
            var frac_div = 1.0
            if pos < n && buf[pos] == 46 {
                pos = pos + 1
                while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                    frac = frac * 10.0 + ((buf[pos] - 48) as f64)
                    frac_div = frac_div * 10.0
                    pos = pos + 1
                }
            }
            let val = (int_part as f64) + frac / frac_div
            if fi < 8 {
                DATA_X[si * 8 + fi] = (val * 100000000.0) as i64
            } else {
                DATA_Y[si] = (val * 100000000.0) as i64
            }
            fi = fi + 1
        }
        while pos < n && buf[pos] != 10 { pos = pos + 1 }
        if pos < n { pos = pos + 1 }
        si = si + 1
    }
    N_TOTAL = si
    if si >= 200 { N_TRAIN = 100; N_TEST = 100 }
    else { N_TRAIN = si / 2; N_TEST = si - N_TRAIN }
    print("loaded "); print_int(N_TOTAL); print(" samples (train=")
    print_int(N_TRAIN); print(" test="); print_int(N_TEST); print(")\n")
}

fn hat6(x: f64, k: i64) -> f64 with Div {
    let c = (k as f64) / 5.0
    let w = 1.0 / 5.0
    let d = abs_c(x - c) / w
    if d >= 1.0 { return 0.0 }
    1.0 - d
}

fn ek_init() with Mut, Div, Panic {
    var i = 0
    while i < 540 { ek_set(i, rand_normal() * 0.05); i = i + 1 }
}

fn ek_forward(si: i64) -> f64 with Mut, Div, Panic {
    // L1: 8 inputs → 10 hidden
    var j = 0
    while j < 10 {
        var s = 0.0
        var fi = 0
        while fi < 8 {
            let x = get_x(si, fi)
            let base = (fi * 10 + j) * 6
            var k = 0
            while k < 6 { s = s + ek_get(base + k) * hat6(x, k); k = k + 1 }
            fi = fi + 1
        }
        EK_H[j] = (s * 100000000.0) as i64
        j = j + 1
    }
    // L2: 10 hidden → 1 output
    var out = 0.0
    j = 0
    while j < 10 {
        let hv = (EK_H[j] as f64) / 100000000.0
        var hx = (hv + 2.0) / 4.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        let base = 480 + j * 6
        var k = 0
        while k < 6 { out = out + ek_get(base + k) * hat6(hx, k); k = k + 1 }
        j = j + 1
    }
    out
}

fn ek_gum_sigma(si: i64, cs: f64) -> f64 with Mut, Div, Panic {
    var h_var: [f64; 10] = [0.0; 10]
    var j = 0
    while j < 10 {
        var v = 0.0
        var fi = 0
        while fi < 8 {
            let x = get_x(si, fi)
            var k = 0
            while k < 6 { let b = hat6(x, k); v = v + b * b * cs * cs; k = k + 1 }
            fi = fi + 1
        }
        h_var[j] = v
        j = j + 1
    }
    var out_var = 0.0
    j = 0
    while j < 10 {
        let hv = (EK_H[j] as f64) / 100000000.0
        var hx = (hv + 2.0) / 4.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        var v = 0.0
        var k = 0
        while k < 6 { let b = hat6(hx, k); v = v + b * b * cs * cs; k = k + 1 }
        out_var = out_var + v + h_var[j]
        j = j + 1
    }
    sqrt_c(out_var)
}

fn ek_train(n_train: i64, epochs: i64, lr: f64) with Mut, Div, Panic {
    var epoch = 0
    while epoch < epochs {
        var total_loss = 0.0
        var si = 0
        while si < n_train {
            let y_true = get_y(si)
            let y_pred = ek_forward(si)
            let err = y_pred - y_true
            total_loss = total_loss + err * err

            // Backprop L2
            var j = 0
            while j < 10 {
                let hv = (EK_H[j] as f64) / 100000000.0
                var hx = (hv + 2.0) / 4.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                var k = 0
                while k < 6 {
                    let b = hat6(hx, k)
                    let w = ek_get(480 + j * 6 + k)
                    ek_set(480 + j * 6 + k, w - lr * 2.0 * err * b)
                    k = k + 1
                }
                j = j + 1
            }
            // Backprop L1
            j = 0
            while j < 10 {
                let hv = (EK_H[j] as f64) / 100000000.0
                var hx = (hv + 2.0) / 4.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                var dh = 0.0
                var k = 0
                while k < 6 { dh = dh + ek_get(480 + j * 6 + k) * hat6(hx, k); k = k + 1 }
                let gh = 2.0 * err * dh
                var fi = 0
                while fi < 8 {
                    let x = get_x(si, fi)
                    k = 0
                    while k < 6 {
                        let b = hat6(x, k)
                        let w = ek_get((fi * 10 + j) * 6 + k)
                        ek_set((fi * 10 + j) * 6 + k, w - lr * gh * b)
                        k = k + 1
                    }
                    fi = fi + 1
                }
                j = j + 1
            }
            si = si + 1
        }
        if epoch % 50 == 0 {
            print("  epoch "); print_int(epoch); print(" MSE="); print(total_loss / (n_train as f64)); print("\n")
        }
        epoch = epoch + 1
    }
}

fn load_data() with Mut, IO, Div {
    var buf: [i8; 32768] = [0; 32768]
    let fd = syscall6(2, "/tmp/energy_data.txt", 0, 0, 0, 0, 0)
    if fd < 0 { print("error: cannot open energy data\n"); return }
    let n = syscall6(0, fd, &buf, 32767, 0, 0, 0)
    syscall6(3, fd, 0, 0, 0, 0, 0)

    // Skip header until ---DATA---
    var pos: i64 = 0
    while pos < n {
        if buf[pos] == 45 && buf[pos + 1] == 45 && buf[pos + 2] == 45 && buf[pos + 3] == 68 {
            while pos < n && buf[pos] != 10 { pos = pos + 1 }
            if pos < n { pos = pos + 1 }
            break
        }
        pos = pos + 1
    }

    // Parse lines: 8 features + 1 target per line
    var si = 0
    while pos < n && si < 200 {
        var fi = 0
        while fi < 9 && pos < n {
            while pos < n && buf[pos] == 32 { pos = pos + 1 }
            var int_part: i64 = 0
            while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                int_part = int_part * 10 + ((buf[pos] - 48) as i64)
                pos = pos + 1
            }
            var frac = 0.0
            var frac_div = 1.0
            if pos < n && buf[pos] == 46 {
                pos = pos + 1
                while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                    frac = frac * 10.0 + ((buf[pos] - 48) as f64)
                    frac_div = frac_div * 10.0
                    pos = pos + 1
                }
            }
            let val = (int_part as f64) + frac / frac_div
            if fi < 8 {
                DATA_X[si * 8 + fi] = (val * 100000000.0) as i64
            } else {
                DATA_Y[si] = (val * 100000000.0) as i64
            }
            fi = fi + 1
        }
        while pos < n && buf[pos] != 10 { pos = pos + 1 }
        if pos < n { pos = pos + 1 }
        si = si + 1
    }
    N_TOTAL = si
    if si >= 200 { N_TRAIN = 100; N_TEST = 100 }
    else { N_TRAIN = si / 2; N_TEST = si - N_TRAIN }
    print("loaded "); print_int(N_TOTAL); print(" samples (train=")
    print_int(N_TRAIN); print(" test="); print_int(N_TEST); print(")\n")
}

fn sqrt_f(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn hat6(x: f64, k: i64) -> f64 with Div {
    let c = (k as f64) / 5.0
    let d = abs_f(x - c) / 0.2
    if d >= 1.0 { return 0.0 }
    1.0 - d
}

fn ek_init_mo(n_in: i64, n_h: i64, n_out: i64) with Mut, Div, Panic {
    let total = n_in * n_h * 6 + n_h * n_out * 6
    var i = 0
    while i < total { ew_s(i, rand_normal() * 0.06); i = i + 1 }
}

fn ek_fwd_mo(si: i64, n_in: i64, n_h: i64, out_idx: i64) -> f64 with Mut, Div {
    // L1: n_in inputs → n_h hidden
    var j = 0
    while j < n_h {
        var s = 0.0
        var fi = 0
        while fi < n_in {
            let x = dx_g(si, fi)
            let base = (fi * n_h + j) * 6
            var k = 0
            while k < 6 { s = s + ew_g(base + k) * hat6(x, k); k = k + 1 }
            fi = fi + 1
        }
        EH[j] = (s * 100000000.0) as i64
        j = j + 1
    }
    // L2: n_h → output out_idx
    var out = 0.0
    let l2_base = n_in * n_h * 6
    j = 0
    while j < n_h {
        let hv = (EH[j] as f64) / 100000000.0
        var hx = (hv + 2.0) / 4.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        let base = l2_base + (j * 2 + out_idx) * 6
        var k = 0
        while k < 6 { out = out + ew_g(base + k) * hat6(hx, k); k = k + 1 }
        j = j + 1
    }
    out
}

fn ek_gum_total(si: i64, n_in: i64, n_h: i64, out_idx: i64, cs: f64) -> f64 with Mut, Div, Panic {
    var hvar: [f64; 10] = [0.0; 10]
    var j = 0
    while j < n_h {
        var v = 0.0
        var fi = 0
        while fi < n_in {
            let x = dx_g(si, fi)
            var k = 0
            while k < 6 { let b = hat6(x, k); v = v + b * b * cs * cs; k = k + 1 }
            fi = fi + 1
        }
        hvar[j] = v
        j = j + 1
    }
    let l2_base = n_in * n_h * 6
    var ov = 0.0
    j = 0
    while j < n_h {
        let hv = (EH[j] as f64) / 100000000.0
        var hx = (hv + 2.0) / 4.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        var v = 0.0
        var k = 0
        while k < 6 { let b = hat6(hx, k); v = v + b * b * cs * cs; k = k + 1 }
        ov = ov + v + hvar[j]
        j = j + 1
    }
    sqrt_f(ov)
}

fn ek_gum_per_feature(si: i64, fi: i64, n_h: i64, cs: f64) -> f64 with Div {
    let x = dx_g(si, fi)
    var v = 0.0
    var j = 0
    while j < n_h {
        var kk = 0
        while kk < 6 { let b = hat6(x, kk); v = v + b * b * cs * cs; kk = kk + 1 }
        j = j + 1
    }
    v  // returns variance contribution (not sqrt)
}

fn ek_train_mo(n_tr: i64, n_in: i64, n_h: i64, n_out: i64, lr: f64) with Mut, Div, Panic {
    var ep = 0
    while ep < 150 {
        var si = 0
        while si < n_tr {
            // Train on output 0
            let pred0 = ek_fwd_mo(si, n_in, n_h, 0)
            let y0 = (DY1[si] as f64) / 100000000.0
            let err0 = pred0 - y0
            // L2 backprop for output 0
            let l2b = n_in * n_h * 6
            var j = 0
            while j < n_h {
                let hv = (EH[j] as f64) / 100000000.0
                var hx = (hv + 2.0) / 4.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                let base = l2b + (j * n_out + 0) * 6
                var k = 0
                while k < 6 {
                    let b = hat6(hx, k)
                    ew_s(base + k, ew_g(base + k) - lr * 2.0 * err0 * b)
                    k = k + 1
                }
                j = j + 1
            }
            // L1 backprop (shared for both outputs — use err0)
            j = 0
            while j < n_h {
                let hv = (EH[j] as f64) / 100000000.0
                var hx = (hv + 2.0) / 4.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                var dh = 0.0
                let base = l2b + (j * n_out + 0) * 6
                var k = 0
                while k < 6 { dh = dh + ew_g(base + k) * hat6(hx, k); k = k + 1 }
                let gh = 2.0 * err0 * dh
                var fi = 0
                while fi < n_in {
                    let x = dx_g(si, fi)
                    k = 0
                    while k < 6 {
                        let b = hat6(x, k)
                        ew_s((fi * n_h + j) * 6 + k, ew_g((fi * n_h + j) * 6 + k) - lr * gh * b)
                        k = k + 1
                    }
                    fi = fi + 1
                }
                j = j + 1
            }

            // Also train output 1 (if n_out==2)
            if n_out == 2 {
                let pred1 = ek_fwd_mo(si, n_in, n_h, 1)
                let y1 = (DY2[si] as f64) / 100000000.0
                let err1 = pred1 - y1
                j = 0
                while j < n_h {
                    let hv = (EH[j] as f64) / 100000000.0
                    var hx = (hv + 2.0) / 4.0
                    if hx < 0.0 { hx = 0.0 }
                    if hx > 1.0 { hx = 1.0 }
                    let base = l2b + (j * n_out + 1) * 6
                    var k = 0
                    while k < 6 {
                        let b = hat6(hx, k)
                        ew_s(base + k, ew_g(base + k) - lr * 2.0 * err1 * b)
                        k = k + 1
                    }
                    j = j + 1
                }
            }
            si = si + 1
        }
        ep = ep + 1
    }
}

fn run_adversarial() with IO, Mut, Div, Panic {
    print("=== A) Adversarial Robustness (sin, FGSM-style) ===\n")
    // Generate sin data inline
    rng_seed(12345678, 87654321)
    var i = 0
    while i < 30 {
        let x = (i as f64) / 30.0 + 0.016
        DX[i * 8] = (x * 100000000.0) as i64
        DY1[i] = (sin_f(6.28318 * x) * 100000000.0) as i64
        i = i + 1
    }

    rng_seed(99999, 11111)
    ek_init_mo(1, 8, 1)
    // Train 1→8→1 (only use feature 0)
    var ep = 0
    while ep < 200 {
        var si = 0
        while si < 25 {
            let x = dx_g(si, 0)
            var pred = 0.0
            var j = 0
            while j < 8 {
                var s = 0.0
                var k = 0
                while k < 6 { s = s + ew_g(j * 6 + k) * hat6(x, k); k = k + 1 }
                EH[j] = (s * 100000000.0) as i64
                j = j + 1
            }
            j = 0
            while j < 8 {
                let hv = (EH[j] as f64) / 100000000.0
                var hx = (hv + 1.5) / 3.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                var k = 0
                while k < 6 { pred = pred + ew_g(48 + j * 6 + k) * hat6(hx, k); k = k + 1 }
                j = j + 1
            }
            let err = pred - (DY1[si] as f64) / 100000000.0
            // Simple L2 update only
            j = 0
            while j < 8 {
                let hv = (EH[j] as f64) / 100000000.0
                var hx = (hv + 1.5) / 3.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                var k = 0
                while k < 6 {
                    let b = hat6(hx, k)
                    ew_s(48 + j * 6 + k, ew_g(48 + j * 6 + k) - 0.003 * 2.0 * err * b)
                    k = k + 1
                }
                j = j + 1
            }
            si = si + 1
        }
        ep = ep + 1
    }

    // Compare σ on clean vs adversarial inputs
    var sig_clean = 0.0
    var sig_adv = 0.0
    let epsilon = 0.15  // FGSM perturbation

    i = 25
    while i < 30 {
        let x_clean = dx_g(i, 0)
        // GUM on clean
        let pred_c = ek_fwd_mo(i, 1, 8, 0)
        let gc = ek_gum_total(i, 1, 8, 0, 0.05)
        sig_clean = sig_clean + gc

        // Adversarial: perturb toward higher error
        let x_adv = x_clean + epsilon
        DX[i * 8] = (x_adv * 100000000.0) as i64
        let pred_a = ek_fwd_mo(i, 1, 8, 0)
        let ga = ek_gum_total(i, 1, 8, 0, 0.05)
        sig_adv = sig_adv + ga

        // Restore
        DX[i * 8] = (x_clean * 100000000.0) as i64
        i = i + 1
    }
    sig_clean = sig_clean / 5.0
    sig_adv = sig_adv / 5.0
    print("  mean σ (clean):       "); print(sig_clean); println("")
    print("  mean σ (adversarial): "); print(sig_adv); println("")
    let adv_ratio = sig_adv / sig_clean
    print("  σ_adv / σ_clean = "); print(adv_ratio); println("")
    if adv_ratio > 1.1 {
        println("  GUM σ INCREASES on adversarial inputs")
    } else if adv_ratio < 0.9 {
        println("  GUM σ DECREASES on adversarial inputs")
    } else {
        println("  GUM σ UNCHANGED on adversarial inputs (blind to attacks)")
    }
}

fn run_feature_importance() with IO, Mut, Div, Panic {
    print("\n=== C) Feature Importance from GUM Variance Decomposition ===\n")
    // Use Energy data features (8 features)
    // After training, decompose σ² by feature
    print("  Feature variance contributions (higher = more important):\n")
    var total_var = 0.0
    var feat_var: [f64; 8] = [0.0; 8]
    var fi = 0
    while fi < 8 {
        var v = 0.0
        var si = 0
        while si < 10 {
            v = v + ek_gum_per_feature(25 + si, fi, 8, 0.05)
            si = si + 1
        }
        feat_var[fi] = v / 10.0
        total_var = total_var + feat_var[fi]
        fi = fi + 1
    }
    // Print as percentage
    let names: [i64; 8] = [0; 8]  // can't store strings, use indices
    fi = 0
    while fi < 8 {
        let pct = feat_var[fi] / total_var * 100.0
        print("  feature "); print_int(fi); print(": "); print(pct); println("% of total σ²")
        fi = fi + 1
    }
    // Find dominant feature
    var max_fi = 0
    var max_v = feat_var[0]
    fi = 1
    while fi < 8 {
        if feat_var[fi] > max_v { max_v = feat_var[fi]; max_fi = fi }
        fi = fi + 1
    }
    print("  Dominant feature: "); print_int(max_fi); print(" (")
    print(max_v / total_var * 100.0); println("% of variance)")
}

fn run_multi_output() with IO, Mut, Div, Panic {
    print("\n=== B) Multi-Output E-KAN 8->8->2 (Energy: heating + cooling) ===\n")
    // Load energy data inline (first 40 samples, hardcoded from file)
    // Actually use syscall6 in a separate loader
    // For speed: use synthetic 2-output data
    // y1 = sin(2πx1) + 0.5*x2,  y2 = cos(2πx1) - 0.3*x3
    rng_seed(55555555, 88888888)
    var i = 0
    while i < 40 {
        var fi = 0
        while fi < 8 {
            DX[i * 8 + fi] = (rand_uniform() * 100000000.0) as i64
            fi = fi + 1
        }
        let x1 = dx_g(i, 0)
        let x2 = dx_g(i, 1)
        let x3 = dx_g(i, 2)
        DY1[i] = ((sin_f(6.28318 * x1) + 0.5 * x2) * 100000000.0) as i64
        DY2[i] = ((sin_f(6.28318 * x1 + 1.5708) + 0.3 * x3) * 100000000.0) as i64
        i = i + 1
    }

    rng_seed(99999, 11111)
    ek_init_mo(8, 8, 2)
    ek_train_mo(30, 8, 8, 2, 0.0008)

    // Test: compute GUM σ for each output independently
    var sig_out0_sum = 0.0
    var sig_out1_sum = 0.0
    i = 30
    while i < 40 {
        let p0 = ek_fwd_mo(i, 8, 8, 0)
        let s0 = ek_gum_total(i, 8, 8, 0, 0.05)
        let p1 = ek_fwd_mo(i, 8, 8, 1)
        let s1 = ek_gum_total(i, 8, 8, 1, 0.05)
        sig_out0_sum = sig_out0_sum + s0
        sig_out1_sum = sig_out1_sum + s1
        if i < 33 {
            print("  sample "); print_int(i - 30)
            print(": y0="); print(p0); print("±"); print(s0)
            print("  y1="); print(p1); print("±"); print(s1); println("")
        }
        i = i + 1
    }
    print("  mean σ output 0: "); print(sig_out0_sum / 10.0); println("")
    print("  mean σ output 1: "); print(sig_out1_sum / 10.0); println("")
    if sig_out0_sum > 0.001 && sig_out1_sum > 0.001 {
        println("  GUM propagates independently per output")
    }
}

fn sqrt_e(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn rng_init() with Mut {
    RNG_A = 314159265
    RNG_B = 271828182
}

fn rand_uniform() -> f64 with Mut, Div {
    let r = rng_next()
    (r % 10000) as f64 / 10000.0
}

fn rand_gaussian(mu: f64, sigma: f64) -> f64 with Mut, Div, Panic {
    mu + sigma * rand_normal()
}

fn rand_init() -> f64 with Mut, Div, Panic {
    rand_gaussian(0.0, 0.3)
}

fn hat(x: f64, k: i64) -> f64 with Div {
    let c = (k as f64) * 0.25
    let d = abs_e(x - c) / 0.25
    if d >= 1.0 { return 0.0 }
    1.0 - d
}

fn set_weight(idx: i64, val: f64) with Mut {
    W_NOM[idx] = (val * 1000000000.0) as i64
}

fn get_weight(idx: i64) -> f64 with Div {
    (W_NOM[idx] as f64) / 1000000000.0
}

fn set_pert(idx: i64, val: f64) with Mut {
    W_PERT[idx] = (val * 1000000000.0) as i64
}

fn get_pert(idx: i64) -> f64 with Div {
    (W_PERT[idx] as f64) / 1000000000.0
}

fn kan_forward_gum(x0: f64, x1: f64, x2: f64, x3: f64) with Mut, Div, Panic {
    // Layer 1: 4 inputs → 6 hidden
    // Edge (i, j) at index i*6+j, coeffs at (i*6+j)*5+k
    var j = 0
    while j < 6 {
        var s = 0.0
        var vs = 0.0
        var i = 0
        while i < 4 {
            // Get input
            var x = 0.0
            if i == 0 { x = x0 }
            if i == 1 { x = x1 }
            if i == 2 { x = x2 }
            if i == 3 { x = x3 }
            // Clamp to [0, 1]
            if x < 0.0 { x = 0.0 }
            if x > 1.0 { x = 1.0 }

            // Edge eval: φ(x) = Σ c_k · hat_k(x)
            let base = (i * 6 + j) * 5
            var edge_val = 0.0
            var edge_var = 0.0
            var k = 0
            while k < 5 {
                let b = hat(x, k)
                let c = get_weight(base + k)
                edge_val = edge_val + c * b
                // GUM: σ²_edge = Σ hat_k² · σ_c²
                edge_var = edge_var + b * b * get_sigma() * get_sigma()
                k = k + 1
            }
            s = s + edge_val
            // Input uncertainty is zero (clean inputs for this test)
            vs = vs + edge_var
            i = i + 1
        }
        H_VAL[j] = (s * 1000000000.0) as i64
        H_UNC[j] = (sqrt_e(vs) * 1000000000.0) as i64
        j = j + 1
    }

    // Layer 2: 6 hidden → 2 output
    // Edge (i, j) at index 120 + (i*2+j)*5+k
    j = 0
    while j < 2 {
        var s = 0.0
        var vs = 0.0
        var i = 0
        while i < 6 {
            // Normalize hidden to [0,1]
            let hv = (H_VAL[i] as f64) / 1000000000.0
            let hu = (H_UNC[i] as f64) / 1000000000.0
            var x = (hv + 2.0) / 4.0
            if x < 0.0 { x = 0.0 }
            if x > 1.0 { x = 1.0 }

            let base = 120 + (i * 2 + j) * 5
            var edge_val = 0.0
            var edge_var = 0.0
            var k = 0
            while k < 5 {
                let b = hat(x, k)
                let c = get_weight(base + k)
                edge_val = edge_val + c * b
                edge_var = edge_var + b * b * get_sigma() * get_sigma()
                k = k + 1
            }
            s = s + edge_val
            // Propagate hidden uncertainty through layer 2
            // Approximate: σ²_out += edge_var + hidden_var (additive)
            vs = vs + edge_var + hu * hu
            i = i + 1
        }
        // Store output (reuse H_VAL/H_UNC for simplicity — only 2 outputs)
        if j == 0 {
            H_VAL[0] = (s * 1000000000.0) as i64
            H_UNC[0] = (sqrt_e(vs) * 1000000000.0) as i64
        } else {
            H_VAL[1] = (s * 1000000000.0) as i64
            H_UNC[1] = (sqrt_e(vs) * 1000000000.0) as i64
        }
        j = j + 1
    }
}

fn kan_forward_mc(x0: f64, x1: f64, x2: f64, x3: f64) with Mut, Div, Panic {
    var j = 0
    while j < 6 {
        var s = 0.0
        var i = 0
        while i < 4 {
            var x = 0.0
            if i == 0 { x = x0 }
            if i == 1 { x = x1 }
            if i == 2 { x = x2 }
            if i == 3 { x = x3 }
            if x < 0.0 { x = 0.0 }
            if x > 1.0 { x = 1.0 }

            let base = (i * 6 + j) * 5
            var k = 0
            while k < 5 {
                let b = hat(x, k)
                s = s + get_pert(base + k) * b
                k = k + 1
            }
            i = i + 1
        }
        H_VAL[j] = (s * 1000000000.0) as i64
        j = j + 1
    }

    j = 0
    while j < 2 {
        var s = 0.0
        var i = 0
        while i < 6 {
            let hv = (H_VAL[i] as f64) / 1000000000.0
            var x = (hv + 2.0) / 4.0
            if x < 0.0 { x = 0.0 }
            if x > 1.0 { x = 1.0 }

            let base = 120 + (i * 2 + j) * 5
            var k = 0
            while k < 5 {
                let b = hat(x, k)
                s = s + get_pert(base + k) * b
                k = k + 1
            }
            i = i + 1
        }
        if j == 0 { H_VAL[0] = (s * 1000000000.0) as i64 }
        else { H_VAL[1] = (s * 1000000000.0) as i64 }
        j = j + 1
    }
}

fn sqrt_r(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn rand_uniform() -> f64 with Mut, Div {
