                v = v + b * b * coeff_sigma * coeff_sigma
                k = k + 1
            }
            fi = fi + 1
        }
        h_var[j] = v
        j = j + 1
    }

    // L2 variance
    var out_var = 0.0
    j = 0
    while j < 10 {
        let hv = (EK_H[j] as f64) / 100000000.0
        var hx = (hv + 3.0) / 6.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        var v = 0.0
        var k = 0
        while k < 8 {
            let b = hat8(hx, k)
            v = v + b * b * coeff_sigma * coeff_sigma
            k = k + 1
        }
        out_var = out_var + v + h_var[j]
        j = j + 1
    }
    sqrt_fr(out_var)
}

fn ek_train(epochs: i64, lr: f64) with Mut, Div, Panic {
