fn hat6(x: f64, k: i64) -> f64 with Div {
    let c = (k as f64) / 5.0
    let w = 1.0 / 5.0
    let d = abs_b(x - c) / w
    if d >= 1.0 { return 0.0 }
    1.0 - d
}

fn ek_init() with Mut, Div, Panic {
