fn ek_forward(x: f64) -> f64 with Mut, Div, Panic {
    var j = 0
    while j < 8 {
        var s = 0.0
        var k = 0
        while k < 6 { s = s + ek_get(j * 6 + k) * hat6(x, k); k = k + 1 }
        EK_H[j] = (s * 100000000.0) as i64
        j = j + 1
    }
    var out = 0.0
    j = 0
    while j < 8 {
        let hv = (EK_H[j] as f64) / 100000000.0
        var hx = (hv + 1.5) / 3.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        var k = 0
        while k < 6 { out = out + ek_get(48 + j * 6 + k) * hat6(hx, k); k = k + 1 }
        j = j + 1
    }
    out
}

fn ek_gum_sigma(x: f64, cs: f64) -> f64 with Mut, Div, Panic {
    var h_var: [f64; 8] = [0.0; 8]
    var j = 0
    while j < 8 {
        var v = 0.0
        var k = 0
        while k < 6 { let b = hat6(x, k); v = v + b * b * cs * cs; k = k + 1 }
        h_var[j] = v
        j = j + 1
    }
    var out_var = 0.0
    j = 0
    while j < 8 {
        let hv = (EK_H[j] as f64) / 100000000.0
        var hx = (hv + 1.5) / 3.0
        if hx < 0.0 { hx = 0.0 }
        if hx > 1.0 { hx = 1.0 }
        var v = 0.0
        var k = 0
        while k < 6 { let b = hat6(hx, k); v = v + b * b * cs * cs; k = k + 1 }
        out_var = out_var + v + h_var[j]
        j = j + 1
    }
    sqrt_b(out_var)
}

fn ek_train(epochs: i64, lr: f64) with Mut, Div, Panic {
    var epoch = 0
    while epoch < epochs {
        var total_loss = 0.0
        var si = 0
        while si < 200 {
            let x = get_trx(si)
            let yt = get_try(si)
            let yp = ek_forward(x)
            let err = yp - yt
            total_loss = total_loss + err * err
            // Backprop L2
            var j = 0
            while j < 8 {
                let hv = (EK_H[j] as f64) / 100000000.0
                var hx = (hv + 1.5) / 3.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                var k = 0
                while k < 6 {
                    let b = hat6(hx, k)
                    let w = ek_get(48 + j * 6 + k)
                    ek_set(48 + j * 6 + k, w - lr * 2.0 * err * b)
                    k = k + 1
                }
                j = j + 1
            }
            // Backprop L1
            j = 0
            while j < 8 {
                let hv = (EK_H[j] as f64) / 100000000.0
                var hx = (hv + 1.5) / 3.0
                if hx < 0.0 { hx = 0.0 }
                if hx > 1.0 { hx = 1.0 }
                var dh = 0.0
                var k = 0
                while k < 6 {
                    dh = dh + ek_get(48 + j * 6 + k) * hat6(hx, k)
                    k = k + 1
                }
                let gh = 2.0 * err * dh
                k = 0
                while k < 6 {
                    let b = hat6(x, k)
                    let w = ek_get(j * 6 + k)
                    ek_set(j * 6 + k, w - lr * gh * b)
                    k = k + 1
                }
                j = j + 1
            }
            si = si + 1
        }
        if epoch % 50 == 0 {
            print("  ekan epoch "); print_int(epoch)
            print(" MSE="); print(total_loss / 200.0); print("\n")
        }
        epoch = epoch + 1
    }
}

