fn sqrt_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 }
    return sqrt(x)
}

fn log_f64(x: f64) -> f64 {
    if x <= 0.0 { return -1.0e308 }
    return log(x)
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn min_f64(a: f64, b: f64) -> f64 {
    if a < b { a } else { b }
}

fn max_f64(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

fn uncertainty_std(u: f64) -> Uncertainty {
    return Uncertainty {
        tag: 1,
        std_u: if u < 0.0 { 0.0 } else { u },
        std_k: 1.0,
        interval_lo: 0.0,
        interval_hi: 0.0,
    }
}

fn uncert_to_std(u: Uncertainty) -> f64 {
    if u.tag == 0 { return 0.0 }
    if u.tag == 1 { return u.std_u }
    return (u.interval_hi - u.interval_lo) / 4.0
}

fn from_literature(value: f64, cv_percent: f64, confidence: f64) -> EpistemicValue {
    // CV = coefficient of variation = std/mean * 100
    let std = value * cv_percent / 100.0
    return EpistemicValue {
        value: value,
        uncert: uncertainty_std(std),
        conf: confidence,
        source: 1,  // literature
    }
}

fn from_measurement(value: f64, std: f64, confidence: f64) -> EpistemicValue {
    return EpistemicValue {
        value: value,
        uncert: uncertainty_std(std),
        conf: confidence,
        source: 2,  // measured
    }
}

fn exact(value: f64, confidence: f64) -> EpistemicValue {
    return EpistemicValue {
        value: value,
        uncert: Uncertainty { tag: 0, std_u: 0.0, std_k: 1.0, interval_lo: 0.0, interval_hi: 0.0 },
        conf: confidence,
        source: 0,
    }
}

fn mul_ep(a: EpistemicValue, b: EpistemicValue) -> EpistemicValue {
    let value = a.value * b.value
    let conf = min_f64(a.conf, b.conf)

    let ua = uncert_to_std(a.uncert)
    let ub = uncert_to_std(b.uncert)

    var u_rel_a = 0.0
    var u_rel_b = 0.0
    if abs_f64(a.value) > 1.0e-15 {
        u_rel_a = ua / abs_f64(a.value)
    }
    if abs_f64(b.value) > 1.0e-15 {
        u_rel_b = ub / abs_f64(b.value)
    }

    let u_rel = sqrt_f64(u_rel_a * u_rel_a + u_rel_b * u_rel_b)
    let u_combined = abs_f64(value) * u_rel

    return EpistemicValue {
        value: value,
        uncert: uncertainty_std(u_combined),
        conf: conf,
        source: 3,  // computed
    }
}

fn div_ep(a: EpistemicValue, b: EpistemicValue) -> EpistemicValue {
    if abs_f64(b.value) < 1.0e-15 {
        return EpistemicValue {
            value: 0.0,
            uncert: Uncertainty { tag: 2, std_u: 0.0, std_k: 1.0, interval_lo: -1.0e308, interval_hi: 1.0e308 },
            conf: 0.0,
            source: 3,
        }
    }

    let value = a.value / b.value
    let conf = min_f64(a.conf, b.conf)

    let ua = uncert_to_std(a.uncert)
    let ub = uncert_to_std(b.uncert)

    var u_rel_a = 0.0
    var u_rel_b = 0.0
    if abs_f64(a.value) > 1.0e-15 {
        u_rel_a = ua / abs_f64(a.value)
    }
    if abs_f64(b.value) > 1.0e-15 {
        u_rel_b = ub / abs_f64(b.value)
    }

    let u_rel = sqrt_f64(u_rel_a * u_rel_a + u_rel_b * u_rel_b)
    let u_combined = abs_f64(value) * u_rel

    return EpistemicValue {
        value: value,
        uncert: uncertainty_std(u_combined),
        conf: conf,
        source: 3,
    }
}

fn neg_ep(a: EpistemicValue) -> EpistemicValue {
    return EpistemicValue {
        value: 0.0 - a.value,
        uncert: a.uncert,  // uncertainty unchanged
        conf: a.conf,
        source: 3,
    }
}

fn exp_ep(a: EpistemicValue) -> EpistemicValue {
    let value = exp_f64(a.value)
    let ua = uncert_to_std(a.uncert)

    // Derivative of exp is exp, so u(y) = |exp(x)| * u(x) = y * u(x)
    let u_combined = abs_f64(value) * ua

    return EpistemicValue {
        value: value,
        uncert: uncertainty_std(u_combined),
        conf: a.conf,  // confidence unchanged for unary ops
        source: 3,
    }
}

fn concentration_at_time(
    dose: EpistemicValue,
    volume: EpistemicValue,
    k_elim: EpistemicValue,
    time: EpistemicValue
) -> EpistemicValue {
    // C0 = D / V
    let c0 = div_ep(dose, volume)

    // k * t
    let kt = mul_ep(k_elim, time)

    // -k * t
    let neg_kt = neg_ep(kt)

    // exp(-k*t)
    let decay = exp_ep(neg_kt)

    // C(t) = C0 * exp(-k*t)
    let concentration = mul_ep(c0, decay)

    return concentration
}

fn half_life(k_elim: EpistemicValue) -> EpistemicValue {
    let ln2 = exact(0.693147, 1.0)  // ln(2) is exact
    return div_ep(ln2, k_elim)
}

fn auc_iv_bolus(
    dose: EpistemicValue,
    volume: EpistemicValue,
    k_elim: EpistemicValue
) -> EpistemicValue {
    // CL = V * k
    let clearance = mul_ep(volume, k_elim)

    // AUC = D / CL
    return div_ep(dose, clearance)
}

fn relative_uncertainty_percent(e: EpistemicValue) -> f64 {
    if abs_f64(e.value) < 1.0e-15 {
        return 100.0
    }
    return uncert_to_std(e.uncert) / abs_f64(e.value) * 100.0
}

fn get_95_ci_low(e: EpistemicValue) -> f64 {
    let u = uncert_to_std(e.uncert)
    return e.value - 1.96 * u
}

fn get_95_ci_high(e: EpistemicValue) -> f64 {
    let u = uncert_to_std(e.uncert)
    return e.value + 1.96 * u
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 {
        return -x
    }
    return x
}

fn bmi(weight_kg: f64, height_m: f64) -> f64 {
    return weight_kg / (height_m * height_m)
}

fn propagate_bmi(weight: KnowledgeF64, height: KnowledgeF64) -> KnowledgeF64 {
    let nominal = bmi(weight.value, height.value)

    // First-order sensitivities:
    // dBMI/dw = 1 / h^2
    // dBMI/dh = -2w / h^3
    let d_dw = 1.0 / (height.value * height.value)
    let d_dh = -2.0 * weight.value / (height.value * height.value * height.value)

    // Conservative linear uncertainty bound.
    let propagated = abs_f64(d_dw) * weight.uncertainty + abs_f64(d_dh) * height.uncertainty

    return KnowledgeF64 {
        value: nominal,
        uncertainty: propagated
    }
}

fn sqrt_c(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn exp_c(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_c(10.0) * exp_c(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var sum = 1.0
    var term = 1.0
    var i = 1
    while i <= 20 { term = term * x / (i as f64); sum = sum + term; i = i + 1 }
    sum
}

fn log_c(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 100.0 }
    var v = (x - 1.0) / (x + 1.0)
    let v2 = v * v
    var sum = v
    var pow = v
    var i = 1
    while i <= 15 {
        pow = pow * v2
        sum = sum + pow / (2.0 * (i as f64) + 1.0)
        i = i + 1
    }
    2.0 * sum
}

fn sigmoid(x: f64) -> f64 with Mut, Div, Panic {
    if x > 15.0 { return 0.999999 }
    if x < 0.0 - 15.0 { return 0.000001 }
    1.0 / (1.0 + exp_c(0.0 - x))
}

fn load_dataset() with Mut, IO, Div {
    // Read file
    var buf: [i8; 2048] = [0; 2048]
    let fd = syscall6(2, "/tmp/sounio_pk_classify.txt", 0, 0, 0, 0, 0)
    if fd < 0 { print("error: cannot open dataset\n"); return }
    let n = syscall6(0, fd, &buf, 2047, 0, 0, 0)
    syscall6(3, fd, 0, 0, 0, 0, 0)
    if n <= 0 { print("error: empty file\n"); return }

    // Parse: skip header until "---DATA---", then read "f1 f2 f3 f4 label" lines
    var pos: i64 = 0
    var in_data = 0

    // Find ---DATA--- marker
    while pos < n {
        // Check for '-' '-' '-' 'D'
        if buf[pos] == 45 && buf[pos + 1] == 45 && buf[pos + 2] == 45 && buf[pos + 3] == 68 {
            // Skip to next line
            while pos < n && buf[pos] != 10 { pos = pos + 1 }
            if pos < n { pos = pos + 1 }
            in_data = 1
            break
        }
        pos = pos + 1
    }

    if in_data == 0 { print("error: no DATA marker\n"); return }

    // Parse data lines
    var si = 0
    while pos < n && si < 24 {
        // Parse 4 floats + 1 int per line
        // Simple parser: read digits, '.', spaces
        var fi = 0
        while fi < 4 && pos < n {
            // Skip spaces
            while pos < n && buf[pos] == 32 { pos = pos + 1 }
            // Read number: integer part . decimal part
            var int_part: i64 = 0
            while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                int_part = int_part * 10 + ((buf[pos] - 48) as i64)
                pos = pos + 1
            }
            var frac = 0.0
            var frac_div = 1.0
            if pos < n && buf[pos] == 46 {
                pos = pos + 1
                while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                    frac = frac * 10.0 + ((buf[pos] - 48) as f64)
                    frac_div = frac_div * 10.0
                    pos = pos + 1
                }
            }
            let val = (int_part as f64) + frac / frac_div
            DATA_X[si * 4 + fi] = (val * 100000000.0) as i64
            fi = fi + 1
        }

        // Parse label
        while pos < n && buf[pos] == 32 { pos = pos + 1 }
        if pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
            DATA_Y[si] = (buf[pos] - 48) as i64
            pos = pos + 1
        }

        // Skip to next line
        while pos < n && buf[pos] != 10 { pos = pos + 1 }
        if pos < n { pos = pos + 1 }

        si = si + 1
    }
    N_SAMPLES = si
    print("loaded "); print_int(N_SAMPLES); println(" samples")
}

fn get_x(sample: i64, feat: i64) -> f64 with Div {
    (DATA_X[sample * 4 + feat] as f64) / 100000000.0
}

fn get_y(sample: i64) -> f64 {
    DATA_Y[sample] as f64
}

fn rand_xavier(fan_in: i64, fan_out: i64) -> f64 with Mut, Div, Panic {
    let r = rng_next()
    let u = (r % 10000) as f64 / 10000.0 - 0.5
    sqrt_c(6.0 / ((fan_in + fan_out) as f64)) * u
}

fn init_weights() with Mut, Div, Panic {
    var i = 0
    while i < 64 { set_w(W1_OFF() + i, rand_xavier(4, 16)); i = i + 1 }
    i = 0
    while i < 16 { set_w(B1_OFF() + i, 0.0); i = i + 1 }
    i = 0
    while i < 128 { set_w(W2_OFF() + i, rand_xavier(16, 8)); i = i + 1 }
    i = 0
    while i < 8 { set_w(B2_OFF() + i, 0.0); i = i + 1 }
    i = 0
    while i < 8 { set_w(WO_OFF() + i, rand_xavier(8, 1)); i = i + 1 }
    set_w(BO_OFF(), 0.0)
}

fn forward(si: i64) with Mut, Div, Panic {
    // Layer 1: z1[j] = Σ x[i]*w1[i*16+j] + b1[j], a1 = ReLU(z1)
    var j = 0
    while j < 16 {
        var s = get_w(B1_OFF() + j)
        var i = 0
        while i < 4 {
            s = s + get_x(si, i) * get_w(W1_OFF() + i * 16 + j)
            i = i + 1
        }
        Z1[j] = (s * 100000000.0) as i64
        if s < 0.0 { s = 0.0 }
        A1[j] = (s * 100000000.0) as i64
        j = j + 1
    }

    // Layer 2: z2[j] = Σ a1[i]*w2[i*8+j] + b2[j], a2 = ReLU(z2)
    j = 0
    while j < 8 {
        var s = get_w(B2_OFF() + j)
        var i = 0
        while i < 16 {
            s = s + (A1[i] as f64) / 100000000.0 * get_w(W2_OFF() + i * 8 + j)
            i = i + 1
        }
        Z2[j] = (s * 100000000.0) as i64
        if s < 0.0 { s = 0.0 }
        A2[j] = (s * 100000000.0) as i64
        j = j + 1
    }

    // Output: z = Σ a2[i]*wo[i] + bo, a = sigmoid(z)
    var s = get_w(BO_OFF())
    j = 0
    while j < 8 {
        s = s + (A2[j] as f64) / 100000000.0 * get_w(WO_OFF() + j)
        j = j + 1
    }
    Z_OUT = (s * 100000000.0) as i64
    let p = sigmoid(s)
    A_OUT = (p * 100000000.0) as i64
}

fn backward(si: i64) with Mut, Div, Panic {
    let y = get_y(si)
    let p = get_pred()

    // dL/dz_out = p - y (binary cross-entropy + sigmoid combined)
    let dz_out = p - y

    // Gradient for output weights
    var j = 0
    while j < 8 {
        let a2j = (A2[j] as f64) / 100000000.0
        DWO[j] = (a2j * dz_out * 100000000.0) as i64
        j = j + 1
    }
    DBO = (dz_out * 100000000.0) as i64

    // Backprop to layer 2: dz2[j] = dz_out * wo[j] * relu'(z2[j])
    var da2: [i64; 8] = [0; 8]
    j = 0
    while j < 8 {
        let g = dz_out * get_w(WO_OFF() + j)
        let z2j = (Z2[j] as f64) / 100000000.0
        var dz2j = g
        if z2j <= 0.0 { dz2j = 0.0 }  // ReLU derivative
        da2[j] = (dz2j * 100000000.0) as i64
        j = j + 1
    }

    // Gradient for W2, b2
    var i = 0
    while i < 16 {
        j = 0
        while j < 8 {
            let a1i = (A1[i] as f64) / 100000000.0
            let dz2j = (da2[j] as f64) / 100000000.0
            DW2[i * 8 + j] = (a1i * dz2j * 100000000.0) as i64
            j = j + 1
        }
        i = i + 1
    }
    j = 0
    while j < 8 { DB2[j] = da2[j]; j = j + 1 }

    // Backprop to layer 1: da1[i] = Σ dz2[j] * w2[i*8+j]
    //                       dz1[i] = da1[i] * relu'(z1[i])
    i = 0
    while i < 16 {
        var sum = 0.0
        j = 0
        while j < 8 {
            sum = sum + (da2[j] as f64) / 100000000.0 * get_w(W2_OFF() + i * 8 + j)
            j = j + 1
        }
        let z1i = (Z1[i] as f64) / 100000000.0
        if z1i <= 0.0 { sum = 0.0 }  // ReLU derivative

        // Gradient for W1, b1 — use ACTUAL sample input, not sample 0
        var k = 0
        while k < 4 {
            DW1[k * 16 + i] = (get_x(si, k) * sum * 100000000.0) as i64
            k = k + 1
        }
        DB1[i] = (sum * 100000000.0) as i64
        i = i + 1
    }
}

fn update_weights(lr: f64) with Mut, Div {
    var i = 0
    // W1
    while i < 64 { set_w(W1_OFF() + i, get_w(W1_OFF() + i) - lr * (DW1[i] as f64) / 100000000.0); i = i + 1 }
    // b1
    i = 0
    while i < 16 { set_w(B1_OFF() + i, get_w(B1_OFF() + i) - lr * (DB1[i] as f64) / 100000000.0); i = i + 1 }
    // W2
    i = 0
    while i < 128 { set_w(W2_OFF() + i, get_w(W2_OFF() + i) - lr * (DW2[i] as f64) / 100000000.0); i = i + 1 }
    // b2
    i = 0
    while i < 8 { set_w(B2_OFF() + i, get_w(B2_OFF() + i) - lr * (DB2[i] as f64) / 100000000.0); i = i + 1 }
    // Wo
    i = 0
    while i < 8 { set_w(WO_OFF() + i, get_w(WO_OFF() + i) - lr * (DWO[i] as f64) / 100000000.0); i = i + 1 }
    // bo
    set_w(BO_OFF(), get_w(BO_OFF()) - lr * (DBO as f64) / 100000000.0)
}

fn forward_gum(si: i64, input_sigma: f64) -> f64 with Mut, Div, Panic {
    // Propagate input uncertainty through all layers
    // σ²_output = Σ (∂output/∂x_i)² · σ²_x_i
    // Compute via finite differences on each input feature

    forward(si)
    let nom_out = get_pred()

    var var_out = 0.0
    var fi = 0
    while fi < 4 {
        // Temporarily perturb input feature fi
        let orig = DATA_X[si * 4 + fi]
        let orig_f = (orig as f64) / 100000000.0

        // +delta
        DATA_X[si * 4 + fi] = ((orig_f + input_sigma) * 100000000.0) as i64
        forward(si)
        let out_plus = get_pred()

        // -delta
        DATA_X[si * 4 + fi] = ((orig_f - input_sigma) * 100000000.0) as i64
        forward(si)
        let out_minus = get_pred()

        // Restore
        DATA_X[si * 4 + fi] = orig

        // Sensitivity
        let dc = (out_plus - out_minus) / (2.0 * input_sigma)
        var_out = var_out + dc * dc * input_sigma * input_sigma

        fi = fi + 1
    }

    // Restore nominal forward
    forward(si)

    sqrt_c(var_out)
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 {
        return 0.0 - x
    }
    return x
}

fn sqrt_f64(x: f64) -> f64 with Div, Panic, Mut {
    if x <= 0.0 { return 0.0 }
    var guess = x
    if x > 1.0 { guess = x / 2.0 }
    else { guess = 1.0 }
    var i: i64 = 0
    while i < 12 {
        guess = 0.5 * (guess + x / guess)
        i = i + 1
    }
    return guess
}

fn exp_f64(x: f64) -> f64 with Div, Panic, Mut {
    let ln2 = 0.693147180559945
    // Range reduction: find integer n such that r = x - n*ln2 is small
    var n_int: i64 = 0
    var remainder = x
    if x > 0.0 {
        while remainder > 0.5 * ln2 {
            remainder = remainder - ln2
            n_int = n_int + 1
        }
    } else {
        while remainder < 0.0 - 0.5 * ln2 {
            remainder = remainder + ln2
            n_int = n_int - 1
        }
    }
    // Taylor series for exp(r) where |r| < 0.35
    let r = remainder
    let r2 = r * r
    let r3 = r2 * r
    let r4 = r3 * r
    let r5 = r4 * r
    let r6 = r5 * r
    let r7 = r6 * r
    let r8 = r7 * r
    let r9 = r8 * r
    let r10 = r9 * r
    let exp_r = 1.0 + r + r2 / 2.0 + r3 / 6.0 + r4 / 24.0 + r5 / 120.0
             + r6 / 720.0 + r7 / 5040.0 + r8 / 40320.0 + r9 / 362880.0
             + r10 / 3628800.0
    // Multiply by 2^n
    var result = exp_r
    var j: i64 = 0
    if n_int > 0 {
        while j < n_int {
            result = result * 2.0
            j = j + 1
        }
    } else {
        let neg_n = 0 - n_int
        while j < neg_n {
            result = result / 2.0
            j = j + 1
        }
    }
    return result
}

fn pk_concentration(dose: f64, vd: f64, ke: f64, t: f64) -> f64 with Div, Panic, Mut {
    let c0 = dose / vd
    let decay = exp_f64(0.0 - ke * t)
    return c0 * decay
}

fn propagate_uncertainty(conc: f64, dose: f64, u_dose: f64,
                         ke: f64, u_ke: f64, t: f64) -> f64 with Div, Panic, Mut {
    let sens_dose = conc / dose
    let sens_ke = conc * t
    let term_dose = sens_dose * u_dose
    let term_ke = sens_ke * u_ke
    return sqrt_f64(term_dose * term_dose + term_ke * term_ke)
}

fn print_f64_2dp(x: f64) with Div, Panic, IO, Mut {
    let neg = x < 0.0
    var val = x
    if neg { val = 0.0 - x }
    // Multiply by 100, round, then split
    let scaled = val * 100.0 + 0.5
    var int_part: i64 = 0
    var rem = scaled
    while rem >= 1.0 {
        rem = rem - 1.0
        int_part = int_part + 1
    }
    let whole = int_part / 100
    let frac = int_part - whole * 100
    if neg { println("-") }
    println(whole)
    println(".")
    if frac < 10 { println("0") }
    println(frac)
}

fn run_simulation(dose_val: f64, dose_unc: f64,
                  ke_val: f64, ke_unc: f64,
                  vd: f64, t: f64, label: i64) -> EpiParam with Div, Panic, IO, Mut {
    let conc = pk_concentration(dose_val, vd, ke_val, t)
    let unc = propagate_uncertainty(conc, dose_val, dose_unc, ke_val, ke_unc, t)
    let result = EpiParam { value: conc, uncertainty: unc }
    return result
}

//@ run-pass
// Dempster-Shafer evidence combination with type-level guarantees
//
// This example demonstrates:
// 1. Dempster-Shafer combination of evidence
// 2. Type-level proof that DS never decreases confidence
// 3. SMT verification of belief mass propagation

// Dempster-Shafer combination
// Property: DS(a, b) = 1 - (1-a)(1-b) >= max(a, b)
// This means combining evidence never decreases confidence
fn combine_evidence<T>(
    evidence1: Knowledge<T>,
    evidence2: Knowledge<T>
) -> Knowledge<T> where result.confidence >= max(evidence1.confidence, evidence2.confidence) {
    // Type system proves DS property holds
    return evidence1.ds_combine(evidence2)
}

// Multiple evidence sources
fn fuse_multiple<T>(
    sources: [Knowledge<T>; 3]
) -> Knowledge<T> where result.confidence >= 0.85 {
    let temp = combine_evidence(sources[0], sources[1])
    return combine_evidence(temp, sources[2])
}

fn main() -> i32 with IO {
    // Multiple sensors measuring the same quantity
    let sensor1: Knowledge<f64> = measure(10.0, uncertainty: 0.5, confidence: 0.60)
    let sensor2: Knowledge<f64> = measure(10.1, uncertainty: 0.4, confidence: 0.70)

    // DS(0.60, 0.70) = 1 - (0.40 * 0.30) = 1 - 0.12 = 0.88
    let fused = combine_evidence(sensor1, sensor2)
    // Type system proves: fused.confidence >= max(0.60, 0.70) = 0.70

    // Three independent evidence sources
    let e1: Knowledge<f64> = measure(25.0, uncertainty: 1.0, confidence: 0.60)
    let e2: Knowledge<f64> = measure(25.2, uncertainty: 0.8, confidence: 0.70)
    let e3: Knowledge<f64> = measure(24.8, uncertainty: 0.9, confidence: 0.65)

    // DS(0.60, 0.70) = 0.88
    // DS(0.88, 0.65) = 1 - (0.12 * 0.35) = 1 - 0.042 = 0.958
    let multi_fused = fuse_multiple([e1, e2, e3])
    // Type system proves: multi_fused.confidence >= 0.85

    // Example: Diagnosis from multiple tests
    let test_a: Knowledge<bool> = measure(true, confidence: 0.75)  // Lab test
    let test_b: Knowledge<bool> = measure(true, confidence: 0.80)  // Imaging
    let test_c: Knowledge<bool> = measure(true, confidence: 0.70)  // Clinical

    let diagnosis = fuse_multiple([test_a, test_b, test_c])
    // Combined confidence: very high due to DS combination
    // SMT proves all refinements hold

    return 0
}

fn combine_evidence<T>(
    evidence1: Knowledge<T>,
    evidence2: Knowledge<T>
) -> Knowledge<T> where result.confidence >= max(evidence1.confidence, evidence2.confidence) {
    // Type system proves DS property holds
    return evidence1.ds_combine(evidence2)
}

fn fuse_multiple<T>(
    sources: [Knowledge<T>; 3]
) -> Knowledge<T> where result.confidence >= 0.85 {
    let temp = combine_evidence(sources[0], sources[1])
