fn forward_char(c: i64) with Mut, Div, Panic {
    // 1. Embed: x = EMB[c * 8 .. c * 8 + 8]
    var x: [f64; 8] = [0.0; 8]
    var xu: [f64; 8] = [0.0; 8]
    var i = 0
    while i < 8 {
        x[i as usize] = EMB[(c * 8 + i) as usize]
        xu[i as usize] = EMB_U[(c * 8 + i) as usize]
        i = i + 1
    }

    // 2. O-SSM step: h = sigmoid(A ⊗ h + B * x)
    // A ⊗ h
    var Ah: [f64; 8] = [0.0; 8]
    oct_mul_inline(&SSM_A, &H, &!Ah)

    // B * x (component-wise scale)
    var Bx: [f64; 8] = [0.0; 8]
    i = 0
    while i < 8 { Bx[i as usize] = SSM_B[i as usize] * x[i as usize]; i = i + 1 }

    // Combined + sigmoid
    i = 0
    while i < 8 {
        let combined = Ah[i as usize] + Bx[i as usize]
        H[i as usize] = sigmoid_l(combined)
        // GUM through sigmoid
        let s = H[i as usize]
        let ah_u2 = SSM_A_U[i as usize] * SSM_A_U[i as usize] + H_U[i as usize] * H_U[i as usize]
        let bx_u2 = SSM_B_U[i as usize] * SSM_B_U[i as usize] * x[i as usize] * x[i as usize] + xu[i as usize] * xu[i as usize] * SSM_B[i as usize] * SSM_B[i as usize]
        H_U[i as usize] = abs_l(s * (1.0 - s)) * sqrt_l(ah_u2 + bx_u2)
        i = i + 1
    }

    // 3. Output projection: logits[j] = Σ_i H[i] * OUT_W[i*128 + j]
    var j = 0
    while j < 128 {
        var sum = 0.0
        var vs = 0.0
        i = 0
        while i < 8 {
            let w = OUT_W[(i * 128 + j) as usize]
            sum = sum + H[i as usize] * w
            vs = vs + H[i as usize] * H[i as usize] * OUT_U[(i * 128 + j) as usize] * OUT_U[(i * 128 + j) as usize] + w * w * H_U[i as usize] * H_U[i as usize]
            i = i + 1
        }
        LOGITS[j as usize] = sum
        LOGITS_U[j as usize] = sqrt_l(vs)
        j = j + 1
    }

    // 4. Softmax
    var mx = LOGITS[0]
    j = 1
    while j < 128 { if LOGITS[j as usize] > mx { mx = LOGITS[j as usize] }; j = j + 1 }
    var sm = 0.0
    j = 0
    while j < 128 {
        let e = exp_l(LOGITS[j as usize] - mx)
        PROBS[j as usize] = e
        sm = sm + e
        j = j + 1
    }
    j = 0
    while j < 128 { PROBS[j as usize] = PROBS[j as usize] / sm; j = j + 1 }
}

fn ce_loss(target: i64) -> f64 with Mut, Div, Panic {
    let p = PROBS[target as usize]
    if p < 0.0000001 { return 20.0 }
    0.0 - log_l(p)
}

fn predict() -> i64 with Mut, Div, Panic {
    var best = 0
    var best_p = PROBS[0]
    var j = 1
    while j < 128 {
        if PROBS[j as usize] > best_p { best_p = PROBS[j as usize]; best = j }
        j = j + 1
    }
    best
}

fn train_step(input_seq: &[i64; 16], seq_len: i64, lr: f64) -> f64 with Mut, Div, Panic {
    // Forward pass: compute total loss
    reset_hidden()
    var total_loss = 0.0
    var t = 0
    while t < seq_len - 1 {
        forward_char(input_seq[t as usize])
        total_loss = total_loss + ce_loss(input_seq[(t + 1) as usize])
        t = t + 1
    }

    // Simple SGD on output weights (largest gradient signal)
    // Perturb each output weight, measure loss sensitivity
    let delta = 0.001
    var wi = 0
    while wi < 1024 {
        let orig = OUT_W[wi as usize]

        // Forward with +delta
        OUT_W[wi as usize] = orig + delta
        reset_hidden()
        var loss_plus = 0.0
        t = 0
        while t < seq_len - 1 {
            forward_char(input_seq[t as usize])
            loss_plus = loss_plus + ce_loss(input_seq[(t + 1) as usize])
            t = t + 1
        }

        // Gradient ≈ (loss+ - loss) / delta
        let grad = (loss_plus - total_loss) / delta
        OUT_W[wi as usize] = orig - lr * grad

        // Update uncertainty: σ decreases with informative gradients
        let u = OUT_U[wi as usize]
        var u_new = u * (1.0 - 0.1 * abs_l(grad))
        if u_new < 0.001 { u_new = 0.001 }
        OUT_U[wi as usize] = u_new

        wi = wi + 8  // stride 8 to keep it fast (update every 8th weight)
    }

    total_loss
}

fn sqrt_g(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn exp_g(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_g(10.0) * exp_g(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var s = 1.0
    var t = 1.0
    var i = 1
    while i <= 20 { t = t * x / (i as f64); s = s + t; i = i + 1 }
    s
}

fn log_g(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 100.0 }
    var y = 0.0
    if x > 1.0 { y = x / 3.0 }
    var i = 0
    while i < 30 { let ey = exp_g(y); if ey > 0.0 { y = y + 2.0 * (x - ey) / (x + ey) }; i = i + 1 }
    y
}

fn init() with Mut, Div, Panic {
    var i = 0
    while i < 74496 { LW[i as usize] = rng() * 0.10; i = i + 1 }
    i = 0
    while i < 6144 { EMB[i as usize] = rng() * 0.18; OW[i as usize] = rng() * 0.18; i = i + 1 }
}

fn zero_g() with Mut {
    var i = 0
    while i < 74496 { LG[i as usize] = 0.0; i = i + 1 }
    i = 0
    while i < 6144 { EMB_G[i as usize] = 0.0; OW_G[i as usize] = 0.0; i = i + 1 }
}

fn reset() with Mut {
    var i = 0
    while i < 384 { HS[i as usize] = 0.0; i = i + 1 }
}

fn fwd(c: i64) with Mut, Div, Panic {
    // Embed
    var i = 0
    while i < 48 { X_IN[i as usize] = EMB[(c * 48 + i) as usize]; i = i + 1 }

    // Process each layer
    var layer = 0
    while layer < 8 {
        let base = layer * 9312
        let h_off = layer * 48

        // Input to this layer: X_IN for layer 0, HS[(layer-1)*32..] for others
        // SSM step: h = sigmoid(A * h + B * input)
        i = 0
        while i < 48 {
            let a = LW[(base + i) as usize]
            let b = LW[(base + 48 + i) as usize]
            var inp = X_IN[i as usize]
            if layer > 0 { inp = HS[((layer - 1) * 48 + i) as usize] }
            let z = a * HS[(h_off + i) as usize] + b * inp
            Z_CACHE[(h_off + i) as usize] = z
            HS[(h_off + i) as usize] = sigmoid_g(z)
            i = i + 1
        }

        // Cache pre-FFN hidden
        i = 0
        while i < 48 { H_PRE[(h_off + i) as usize] = HS[(h_off + i) as usize]; i = i + 1 }

        // FFN: 48→96 (ReLU) →48, residual
        let w1_base = base + 96
        let w2_base = base + 4704
        let fh_off = layer * 96

        var j = 0
        while j < 96 {
            var s = 0.0
            i = 0
            while i < 48 { s = s + HS[(h_off + i) as usize] * LW[(w1_base + i * 96 + j) as usize]; i = i + 1 }
            FFZ[(fh_off + j) as usize] = s
            FFH[(fh_off + j) as usize] = relu_g(s)
            j = j + 1
        }

        j = 0
        while j < 48 {
            var s = 0.0
            i = 0
            while i < 96 { s = s + FFH[(fh_off + i) as usize] * LW[(w2_base + i * 48 + j) as usize]; i = i + 1 }
            HS[(h_off + j) as usize] = HS[(h_off + j) as usize] + s  // residual
            j = j + 1
        }

        layer = layer + 1
    }

    // Output: last layer hidden → logits
    let last_off = 7 * 48  // (N_LAYERS-1) * D
    var j = 0
    while j < 128 {
        var s = 0.0
        i = 0
        while i < 48 { s = s + HS[(last_off + i) as usize] * OW[(i * 128 + j) as usize]; i = i + 1 }
        LOGITS[j as usize] = s
        j = j + 1
    }

    // Softmax
    var mx = LOGITS[0]
    j = 1
    while j < 128 { if LOGITS[j as usize] > mx { mx = LOGITS[j as usize] }; j = j + 1 }
    var sm = 0.0
    j = 0
    while j < 128 { let e = exp_g(LOGITS[j as usize] - mx); PROBS[j as usize] = e; sm = sm + e; j = j + 1 }
    j = 0
    while j < 128 { PROBS[j as usize] = PROBS[j as usize] / sm; j = j + 1 }
}

fn bwd(target: i64, c: i64) with Mut, Div, Panic {
    // dL/dlogits = probs - one_hot
    var dl: [f64; 128] = [0.0; 128]
    var j = 0
    while j < 128 { dl[j as usize] = PROBS[j as usize]; j = j + 1 }
    dl[target as usize] = dl[target as usize] - 1.0

    // Output weight grads + dH for last layer
    let last_off = 7 * 48
    var dH: [f64; 48] = [0.0; 48]
    var i = 0
    while i < 48 {
        j = 0
        while j < 128 {
            OW_G[(i * 128 + j) as usize] = OW_G[(i * 128 + j) as usize] + HS[(last_off + i) as usize] * dl[j as usize]
            dH[i as usize] = dH[i as usize] + dl[j as usize] * OW[(i * 128 + j) as usize]
            j = j + 1
        }
        i = i + 1
    }

    // Backward through layers (reverse order)
    var layer = 7
    while layer >= 0 {
        let base = layer * 9312
        let h_off = layer * 48
        let w1_base = base + 96
        let w2_base = base + 4704
        let fh_off = layer * 96

        // FFN backward: W2
        var dFFH: [f64; 96] = [0.0; 96]
        j = 0
        while j < 48 {
            i = 0
            while i < 96 {
                LG[(w2_base + i * 48 + j) as usize] = LG[(w2_base + i * 48 + j) as usize] + FFH[(fh_off + i) as usize] * dH[j as usize]
                dFFH[i as usize] = dFFH[i as usize] + dH[j as usize] * LW[(w2_base + i * 48 + j) as usize]
                i = i + 1
            }
            j = j + 1
        }

        // ReLU backward
        i = 0
        while i < 96 { if FFZ[(fh_off + i) as usize] <= 0.0 { dFFH[i as usize] = 0.0 }; i = i + 1 }

        // FFN backward: W1
        var dH_pre: [f64; 48] = [0.0; 48]
        j = 0
        while j < 96 {
            i = 0
            while i < 48 {
                LG[(w1_base + i * 96 + j) as usize] = LG[(w1_base + i * 96 + j) as usize] + H_PRE[(h_off + i) as usize] * dFFH[j as usize]
                dH_pre[i as usize] = dH_pre[i as usize] + dFFH[j as usize] * LW[(w1_base + i * 96 + j) as usize]
                i = i + 1
            }
            j = j + 1
        }

        // Residual: add FFN path + direct path
        i = 0
        while i < 48 { dH_pre[i as usize] = dH_pre[i as usize] + dH[i as usize]; i = i + 1 }

        // SSM sigmoid backward
        var dH_next: [f64; 48] = [0.0; 48]
        i = 0
        while i < 48 {
            let s = sigmoid_g(Z_CACHE[(h_off + i) as usize])
            let ds = s * (1.0 - s)
            let dz = dH_pre[i as usize] * ds
            // dA
            LG[(base + i) as usize] = LG[(base + i) as usize] + dz * HS[(h_off + i) as usize]
            // dB
            var inp = X_IN[i as usize]
            if layer > 0 { inp = HS[((layer - 1) * 32 + i) as usize] }
            LG[(base + 48 + i) as usize] = LG[(base + 48 + i) as usize] + dz * inp
            // dInput (for previous layer)
            let b = LW[(base + 48 + i) as usize]
            dH_next[i as usize] = dz * b
            i = i + 1
        }

        // Pass gradient to previous layer (or embedding)
        if layer > 0 {
            i = 0
            while i < 48 { dH[i as usize] = dH_next[i as usize]; i = i + 1 }
        } else {
            // Embedding gradient
            i = 0
            while i < 48 {
                EMB_G[(c * 48 + i) as usize] = EMB_G[(c * 48 + i) as usize] + dH_next[i as usize]
                i = i + 1
            }
        }

        layer = layer - 1
    }
}

fn update(lr: f64) with Mut {
    var i = 0
    while i < 74496 { LW[i as usize] = LW[i as usize] - lr * LG[i as usize]; i = i + 1 }
    i = 0
    while i < 6144 {
        EMB[i as usize] = EMB[i as usize] - lr * EMB_G[i as usize]
        OW[i as usize] = OW[i as usize] - lr * OW_G[i as usize]
        i = i + 1
    }
}

fn train_step(seq: &[i64; 16], slen: i64, lr: f64) -> f64 with Mut, Div, Panic {
    zero_g()
    reset()
    var loss = 0.0
    var t = 0
    while t < slen - 1 {
        fwd(seq[t as usize])
        let p = PROBS[seq[(t + 1) as usize] as usize]
        var l = 0.0 - log_g(p)
        if l > 20.0 { l = 20.0 }
        loss = loss + l
        bwd(seq[(t + 1) as usize], seq[t as usize])
        t = t + 1
    }
    update(lr)
    loss
}

fn eval(seq: &[i64; 16], slen: i64) -> f64 with Mut, Div, Panic {
    reset()
    var loss = 0.0
    var t = 0
    while t < slen - 1 {
        fwd(seq[t as usize])
        let p = PROBS[seq[(t + 1) as usize] as usize]
        var l = 0.0 - log_g(p)
        if l > 20.0 { l = 20.0 }
        loss = loss + l
        t = t + 1
    }
    loss
}

fn predict() -> i64 with Mut {
    var b = 0
    var bp = PROBS[0]
    var j = 1
    while j < 128 { if PROBS[j as usize] > bp { bp = PROBS[j as usize]; b = j }; j = j + 1 }
    b
}

fn init() with Mut, Div, Panic {
    var i = 0
    while i < 16640 { LW[i as usize] = rng() * 0.12; i = i + 1 }
    i = 0
    while i < 4096 { EMB[i as usize] = rng() * 0.2; OW[i as usize] = rng() * 0.2; i = i + 1 }
}

fn zero_g() with Mut {
    var i = 0
    while i < 16640 { LG[i as usize] = 0.0; i = i + 1 }
    i = 0
    while i < 4096 { EMB_G[i as usize] = 0.0; OW_G[i as usize] = 0.0; i = i + 1 }
}

fn reset() with Mut {
    var i = 0
    while i < 128 { HS[i as usize] = 0.0; i = i + 1 }
}

fn fwd(c: i64) with Mut, Div, Panic {
    // Embed
    var i = 0
    while i < 32 { X_IN[i as usize] = EMB[(c * 32 + i) as usize]; i = i + 1 }

    // Process each layer
    var layer = 0
    while layer < 4 {
        let base = layer * 4160
        let h_off = layer * 32

        // Input to this layer: X_IN for layer 0, HS[(layer-1)*32..] for others
        // SSM step: h = sigmoid(A * h + B * input)
        i = 0
        while i < 32 {
            let a = LW[(base + i) as usize]
            let b = LW[(base + 32 + i) as usize]
            var inp = X_IN[i as usize]
            if layer > 0 { inp = HS[((layer - 1) * 32 + i) as usize] }
            let z = a * HS[(h_off + i) as usize] + b * inp
            Z_CACHE[(h_off + i) as usize] = z
            HS[(h_off + i) as usize] = sigmoid_g(z)
            i = i + 1
        }

        // Cache pre-FFN hidden
        i = 0
        while i < 32 { H_PRE[(h_off + i) as usize] = HS[(h_off + i) as usize]; i = i + 1 }

        // FFN: 32→64 (ReLU) →32, residual
        let w1_base = base + 64
        let w2_base = base + 2112
        let fh_off = layer * 64

        var j = 0
        while j < 64 {
            var s = 0.0
            i = 0
            while i < 32 { s = s + HS[(h_off + i) as usize] * LW[(w1_base + i * 64 + j) as usize]; i = i + 1 }
            FFZ[(fh_off + j) as usize] = s
            FFH[(fh_off + j) as usize] = relu_g(s)
            j = j + 1
        }

        j = 0
        while j < 32 {
            var s = 0.0
            i = 0
            while i < 64 { s = s + FFH[(fh_off + i) as usize] * LW[(w2_base + i * 32 + j) as usize]; i = i + 1 }
            HS[(h_off + j) as usize] = HS[(h_off + j) as usize] + s  // residual
            j = j + 1
        }

        layer = layer + 1
    }

    // Output: last layer hidden → logits
    let last_off = 3 * 32  // (N_LAYERS-1) * D
    var j = 0
    while j < 128 {
        var s = 0.0
        i = 0
        while i < 32 { s = s + HS[(last_off + i) as usize] * OW[(i * 128 + j) as usize]; i = i + 1 }
        LOGITS[j as usize] = s
        j = j + 1
    }

    // Softmax
    var mx = LOGITS[0]
    j = 1
    while j < 128 { if LOGITS[j as usize] > mx { mx = LOGITS[j as usize] }; j = j + 1 }
    var sm = 0.0
    j = 0
    while j < 128 { let e = exp_g(LOGITS[j as usize] - mx); PROBS[j as usize] = e; sm = sm + e; j = j + 1 }
    j = 0
    while j < 128 { PROBS[j as usize] = PROBS[j as usize] / sm; j = j + 1 }
}

fn update(lr: f64) with Mut {
    var i = 0
    while i < 16640 { LW[i as usize] = LW[i as usize] - lr * LG[i as usize]; i = i + 1 }
    i = 0
    while i < 4096 {
        EMB[i as usize] = EMB[i as usize] - lr * EMB_G[i as usize]
        OW[i as usize] = OW[i as usize] - lr * OW_G[i as usize]
        i = i + 1
    }
}

fn sqrt_b(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn exp_b(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_b(10.0) * exp_b(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var s = 1.0
    var t = 1.0
    var i = 1
    while i <= 20 { t = t * x / (i as f64); s = s + t; i = i + 1 }
    s
}

fn log_b(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 100.0 }
    var y = 0.0
    if x > 1.0 { y = x / 3.0 }
    var i = 0
    while i < 30 { let ey = exp_b(y); if ey > 0.0 { y = y + 2.0 * (x - ey) / (x + ey) }; i = i + 1 }
    y
}

fn init_model() with Mut, Div, Panic {
    var i = 0
    while i < 2048 { EMB[i as usize] = rand_b() * 0.2; OW[i as usize] = rand_b() * 0.2; i = i + 1 }
    i = 0
    while i < 16 { A1[i as usize] = rand_b() * 0.15; B1[i as usize] = rand_b() * 0.15; A2[i as usize] = rand_b() * 0.15; B2[i as usize] = rand_b() * 0.15; i = i + 1 }
    i = 0
    while i < 512 { F1W1[i as usize] = rand_b() * 0.18; F1W2[i as usize] = rand_b() * 0.18; F2W1[i as usize] = rand_b() * 0.18; F2W2[i as usize] = rand_b() * 0.18; i = i + 1 }
}

fn zero_grads() with Mut {
    var i = 0
    while i < 2048 { EMB_G[i as usize] = 0.0; OW_G[i as usize] = 0.0; i = i + 1 }
    i = 0
    while i < 16 { A1_G[i as usize] = 0.0; B1_G[i as usize] = 0.0; A2_G[i as usize] = 0.0; B2_G[i as usize] = 0.0; i = i + 1 }
    i = 0
    while i < 512 { F1W1_G[i as usize] = 0.0; F1W2_G[i as usize] = 0.0; F2W1_G[i as usize] = 0.0; F2W2_G[i as usize] = 0.0; i = i + 1 }
}

fn reset_state() with Mut {
    var i = 0
    while i < 16 { H1[i as usize] = 0.0; H2[i as usize] = 0.0; i = i + 1 }
}

fn forward(c: i64) with Mut, Div, Panic {
    var i = 0
    while i < 16 { X_CACHE[i as usize] = EMB[(c * 16 + i) as usize]; i = i + 1 }

    // Layer 1: h1 = sigmoid(A1 * h1 + B1 * x)
    i = 0
    while i < 16 {
        let z = A1[i as usize] * H1[i as usize] + B1[i as usize] * X_CACHE[i as usize]
        Z1[i as usize] = z
        H1[i as usize] = sigmoid_b(z)
        i = i + 1
    }

    // Cache H1 before FFN
    i = 0
    while i < 16 { H1_PRE[i as usize] = H1[i as usize]; i = i + 1 }

    // FFN1: 16→32→16 + residual
    var j = 0
    while j < 32 {
        var s = 0.0
        var k = 0
        while k < 16 { s = s + H1[k as usize] * F1W1[(k * 32 + j) as usize]; k = k + 1 }
        FF1_Z[j as usize] = s
        FF1_H[j as usize] = relu_b(s)
        j = j + 1
    }
    j = 0
    while j < 16 {
        var s = 0.0
        var k = 0
        while k < 32 { s = s + FF1_H[k as usize] * F1W2[(k * 16 + j) as usize]; k = k + 1 }
        H1[j as usize] = H1[j as usize] + s  // residual
        j = j + 1
    }

    // Layer 2: h2 = sigmoid(A2 * h2 + B2 * h1)
    i = 0
    while i < 16 {
        let z = A2[i as usize] * H2[i as usize] + B2[i as usize] * H1[i as usize]
        Z2[i as usize] = z
        H2[i as usize] = sigmoid_b(z)
        i = i + 1
    }
    i = 0
    while i < 16 { H2_PRE[i as usize] = H2[i as usize]; i = i + 1 }

    // FFN2 + residual
    j = 0
    while j < 32 {
        var s = 0.0
        var k = 0
        while k < 16 { s = s + H2[k as usize] * F2W1[(k * 32 + j) as usize]; k = k + 1 }
        FF2_Z[j as usize] = s
        FF2_H[j as usize] = relu_b(s)
        j = j + 1
    }
    j = 0
    while j < 16 {
        var s = 0.0
        var k = 0
        while k < 32 { s = s + FF2_H[k as usize] * F2W2[(k * 16 + j) as usize]; k = k + 1 }
        H2[j as usize] = H2[j as usize] + s
        j = j + 1
    }

    // Output: logits = H2 × OW
    j = 0
    while j < 128 {
        var s = 0.0
        i = 0
        while i < 16 { s = s + H2[i as usize] * OW[(i * 128 + j) as usize]; i = i + 1 }
        LOGITS[j as usize] = s
        j = j + 1
    }

    // Softmax
    var mx = LOGITS[0]
    j = 1
    while j < 128 { if LOGITS[j as usize] > mx { mx = LOGITS[j as usize] }; j = j + 1 }
    var sm = 0.0
    j = 0
    while j < 128 { let e = exp_b(LOGITS[j as usize] - mx); PROBS[j as usize] = e; sm = sm + e; j = j + 1 }
    j = 0
    while j < 128 { PROBS[j as usize] = PROBS[j as usize] / sm; j = j + 1 }
}

fn backward(target: i64, c: i64) with Mut, Div, Panic {
    // dL/d_logits = probs - one_hot(target)  (cross-entropy + softmax combined)
    var dlogits: [f64; 128] = [0.0; 128]
    var j = 0
    while j < 128 { dlogits[j as usize] = PROBS[j as usize]; j = j + 1 }
    dlogits[target as usize] = dlogits[target as usize] - 1.0

    // Output weight gradients: dOW[i,j] += H2[i] * dlogits[j]
    // dH2[i] += Σ_j dlogits[j] * OW[i,j]
    var dH2: [f64; 16] = [0.0; 16]
    var i = 0
    while i < 16 {
        j = 0
        while j < 128 {
            OW_G[(i * 128 + j) as usize] = OW_G[(i * 128 + j) as usize] + H2[i as usize] * dlogits[j as usize]
            dH2[i as usize] = dH2[i as usize] + dlogits[j as usize] * OW[(i * 128 + j) as usize]
            j = j + 1
        }
        i = i + 1
    }

    // FFN2 backward (residual: dH2 flows through both paths)
    // Path 1: FFN2 W2 backward
    var dFF2H: [f64; 32] = [0.0; 32]
    j = 0
    while j < 16 {
        var k = 0
        while k < 32 {
            F2W2_G[(k * 16 + j) as usize] = F2W2_G[(k * 16 + j) as usize] + FF2_H[k as usize] * dH2[j as usize]
            dFF2H[k as usize] = dFF2H[k as usize] + dH2[j as usize] * F2W2[(k * 16 + j) as usize]
            k = k + 1
        }
        j = j + 1
    }
    // ReLU backward
    var k = 0
    while k < 32 { if FF2_Z[k as usize] <= 0.0 { dFF2H[k as usize] = 0.0 }; k = k + 1 }
    // FFN2 W1 backward
    var dH2_pre: [f64; 16] = [0.0; 16]
    j = 0
    while j < 32 {
        i = 0
        while i < 16 {
            F2W1_G[(i * 32 + j) as usize] = F2W1_G[(i * 32 + j) as usize] + H2_PRE[i as usize] * dFF2H[j as usize]
            dH2_pre[i as usize] = dH2_pre[i as usize] + dFF2H[j as usize] * F2W1[(i * 32 + j) as usize]
            i = i + 1
        }
        j = j + 1
    }
    // Residual: add both paths
    i = 0
    while i < 16 { dH2_pre[i as usize] = dH2_pre[i as usize] + dH2[i as usize]; i = i + 1 }

    // Layer 2 sigmoid backward: dZ2 = dH2_pre * sigmoid'(Z2)
    var dH1: [f64; 16] = [0.0; 16]
    i = 0
    while i < 16 {
        let s = sigmoid_b(Z2[i as usize])
        let ds = s * (1.0 - s)
        let dz = dH2_pre[i as usize] * ds
        // A2 gradient: dA2[i] += dz * H2_old (≈ sigmoid(Z2))
        A2_G[i as usize] = A2_G[i as usize] + dz * H2[i as usize]
        // B2 gradient: dB2[i] += dz * H1[i]
        B2_G[i as usize] = B2_G[i as usize] + dz * H1[i as usize]
        // dH1[i] += dz * B2[i]
        dH1[i as usize] = dH1[i as usize] + dz * B2[i as usize]
        i = i + 1
    }

    // FFN1 backward (same pattern as FFN2)
    var dFF1H: [f64; 32] = [0.0; 32]
    j = 0
    while j < 16 {
        k = 0
        while k < 32 {
            F1W2_G[(k * 16 + j) as usize] = F1W2_G[(k * 16 + j) as usize] + FF1_H[k as usize] * dH1[j as usize]
            dFF1H[k as usize] = dFF1H[k as usize] + dH1[j as usize] * F1W2[(k * 16 + j) as usize]
            k = k + 1
        }
        j = j + 1
    }
    k = 0
    while k < 32 { if FF1_Z[k as usize] <= 0.0 { dFF1H[k as usize] = 0.0 }; k = k + 1 }
    var dH1_pre: [f64; 16] = [0.0; 16]
    j = 0
    while j < 32 {
        i = 0
        while i < 16 {
            F1W1_G[(i * 32 + j) as usize] = F1W1_G[(i * 32 + j) as usize] + H1_PRE[i as usize] * dFF1H[j as usize]
            dH1_pre[i as usize] = dH1_pre[i as usize] + dFF1H[j as usize] * F1W1[(i * 32 + j) as usize]
            i = i + 1
        }
        j = j + 1
    }
    i = 0
    while i < 16 { dH1_pre[i as usize] = dH1_pre[i as usize] + dH1[i as usize]; i = i + 1 }

    // Layer 1 sigmoid backward
    i = 0
    while i < 16 {
        let s = sigmoid_b(Z1[i as usize])
        let ds = s * (1.0 - s)
        let dz = dH1_pre[i as usize] * ds
        A1_G[i as usize] = A1_G[i as usize] + dz * H1[i as usize]
        B1_G[i as usize] = B1_G[i as usize] + dz * X_CACHE[i as usize]
        // Embedding gradient
        EMB_G[(c * 16 + i) as usize] = EMB_G[(c * 16 + i) as usize] + dz * B1[i as usize]
        i = i + 1
    }
}

fn sgd_step(lr: f64) with Mut {
    var i = 0
    while i < 2048 { EMB[i as usize] = EMB[i as usize] - lr * EMB_G[i as usize]; OW[i as usize] = OW[i as usize] - lr * OW_G[i as usize]; i = i + 1 }
    i = 0
    while i < 16 {
        A1[i as usize] = A1[i as usize] - lr * A1_G[i as usize]
        B1[i as usize] = B1[i as usize] - lr * B1_G[i as usize]
        A2[i as usize] = A2[i as usize] - lr * A2_G[i as usize]
        B2[i as usize] = B2[i as usize] - lr * B2_G[i as usize]
        i = i + 1
    }
    i = 0
    while i < 512 {
        F1W1[i as usize] = F1W1[i as usize] - lr * F1W1_G[i as usize]
        F1W2[i as usize] = F1W2[i as usize] - lr * F1W2_G[i as usize]
        F2W1[i as usize] = F2W1[i as usize] - lr * F2W1_G[i as usize]
        F2W2[i as usize] = F2W2[i as usize] - lr * F2W2_G[i as usize]
        i = i + 1
    }
}

fn train_epoch(seq: &[i64; 16], slen: i64, lr: f64) -> f64 with Mut, Div, Panic {
    zero_grads()
    reset_state()
    var total_loss = 0.0
    var t = 0
    while t < slen - 1 {
        forward(seq[t as usize])
        let p = PROBS[seq[(t + 1) as usize] as usize]
        var loss = 0.0 - log_b(p)
        if loss > 20.0 { loss = 20.0 }
        total_loss = total_loss + loss
        backward(seq[(t + 1) as usize], seq[t as usize])
        t = t + 1
    }
    sgd_step(lr)
    total_loss
}

fn eval_loss(seq: &[i64; 16], slen: i64) -> f64 with Mut, Div, Panic {
    reset_state()
    var total = 0.0
    var t = 0
    while t < slen - 1 {
        forward(seq[t as usize])
        let p = PROBS[seq[(t + 1) as usize] as usize]
        var loss = 0.0 - log_b(p)
        if loss > 20.0 { loss = 20.0 }
        total = total + loss
        t = t + 1
    }
    total
}

fn predict_next() -> i64 with Mut {
    var best = 0
    var bp = PROBS[0]
    var j = 1
    while j < 128 { if PROBS[j as usize] > bp { bp = PROBS[j as usize]; best = j }; j = j + 1 }
    best
}

fn sqrt_f(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn exp_f(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_f(10.0) * exp_f(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var sum = 1.0
    var term = 1.0
    var i = 1
    while i <= 20 { term = term * x / (i as f64); sum = sum + term; i = i + 1 }
    sum
}

fn log_f(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 100.0 }
    var v = (x - 1.0) / (x + 1.0)
    let v2 = v * v
    var sum = v
    var pow = v
    var i = 1
    while i <= 12 {
        pow = pow * v2
        sum = sum + pow / (2.0 * (i as f64) + 1.0)
        i = i + 1
    }
    2.0 * sum
}

fn read_training_data() with Mut, IO {
    // SYS_open = 2, O_RDONLY = 0
    let fd = syscall6(2, "/tmp/sounio_training_data.txt", 0, 0, 0, 0, 0)
    if fd < 0 {
        print("error: cannot open training data\n")
        return
    }
    // SYS_read = 0, read up to 1023 bytes
    let n = syscall6(0, fd, &FILE_BUF, 1023, 0, 0, 0)
    if n > 0 { FILE_LEN = n }
    // SYS_close = 3
    syscall6(3, fd, 0, 0, 0, 0, 0)
    print("read "); print_int(FILE_LEN); print(" bytes from file\n")
}

fn get_char(idx: i64) -> i64 {
    if idx >= FILE_LEN { return 0 }
    let c = FILE_BUF[idx]
    if c < 0 { return (c as i64) + 256 }
    c as i64
}

fn set_w(idx: i64, val: f64) with Mut {
    W[idx] = (val * 100000000.0) as i64
}

fn get_w(idx: i64) -> f64 with Div {
    (W[idx] as f64) / 100000000.0
}

fn rng_init() with Mut {
    RNG_A = 42424242
    RNG_B = 13131313
}

fn rand_xavier(fan_in: i64, fan_out: i64) -> f64 with Mut, Div, Panic {
    let r = rng_next()
    let u = (r % 10000) as f64 / 10000.0 - 0.5
    let scale = sqrt_f(6.0 / ((fan_in + fan_out) as f64))
    u * scale
}

fn init_weights() with Mut, Div, Panic {
    // Embedding
    var i = 0
    while i < 4096 { set_w(OFF_EMBED() + i, rand_xavier(128, 32)); i = i + 1 }

    // Layers
    var l = 0
    while l < N_LAYERS() {
        i = 0
        while i < 32 {
            set_w(OFF_SSM_A(l) + i, 0.9 + rand_xavier(32, 32) * 0.1)
            set_w(OFF_SSM_B(l) + i, rand_xavier(32, 32))
            i = i + 1
        }
        i = 0
        while i < 2048 { set_w(OFF_W1(l) + i, rand_xavier(32, 64)); i = i + 1 }
        i = 0
        while i < 2048 { set_w(OFF_W2(l) + i, rand_xavier(64, 32)); i = i + 1 }
        l = l + 1
    }

    // Output
    i = 0
    while i < 4096 { set_w(OFF_OUTPUT() + i, rand_xavier(32, 128)); i = i + 1 }
}

fn forward_step(char_idx: i64) with Mut, Div, Panic {
    // Embed
    var d = 0
    while d < D() {
        let e = get_w(OFF_EMBED() + char_idx * D() + d)
        H[d] = (e * 100000000.0) as i64
        d = d + 1
    }

    // Layers
    var l = 0
    while l < N_LAYERS() {
        // SSM: h[d] = a[d]*h[d] + b[d]*input[d]
        d = 0
        while d < D() {
            let hv = (H[d] as f64) / 100000000.0
            let a = get_w(OFF_SSM_A(l) + d)
            let b = get_w(OFF_SSM_B(l) + d)
            let inp = hv
            let new_h = a * hv + b * inp
            H[d] = (new_h * 100000000.0) as i64
            d = d + 1
        }

        // FFN: ReLU(x @ W1) @ W2 + residual
        // hidden → act (32→64)
        var j = 0
        while j < DFF() {
            var s = 0.0
            d = 0
            while d < D() {
                s = s + (H[d] as f64) / 100000000.0 * get_w(OFF_W1(l) + d * DFF() + j)
                d = d + 1
            }
            if s < 0.0 { s = 0.0 }  // ReLU
            ACT[j] = (s * 100000000.0) as i64
            j = j + 1
        }

        // act → hidden (64→32) + residual
        d = 0
        while d < D() {
            var s = (H[d] as f64) / 100000000.0  // residual
            j = 0
            while j < DFF() {
                s = s + (ACT[j] as f64) / 100000000.0 * get_w(OFF_W2(l) + j * D() + d)
                j = j + 1
            }
            H[d] = (s * 100000000.0) as i64
            d = d + 1
        }

        l = l + 1
    }

    // Output logits: hidden @ W_out → 128
    var v = 0
    while v < VOCAB() {
        var s = 0.0
        d = 0
        while d < D() {
            s = s + (H[d] as f64) / 100000000.0 * get_w(OFF_OUTPUT() + d * VOCAB() + v)
            d = d + 1
        }
        LOGITS[v] = (s * 100000000.0) as i64
        v = v + 1
    }

    // Softmax
    var max_l = (LOGITS[0] as f64) / 100000000.0
    v = 1
    while v < VOCAB() {
        let lv = (LOGITS[v] as f64) / 100000000.0
        if lv > max_l { max_l = lv }
        v = v + 1
    }

    var sum_exp = 0.0
    v = 0
    while v < VOCAB() {
        let e = exp_f((LOGITS[v] as f64) / 100000000.0 - max_l)
        PROBS[v] = (e * 100000000.0) as i64
        sum_exp = sum_exp + e
        v = v + 1
    }

    v = 0
    while v < VOCAB() {
        let p = (PROBS[v] as f64) / 100000000.0 / sum_exp
        PROBS[v] = (p * 100000000.0) as i64
        v = v + 1
    }
}

fn cross_entropy_loss(target: i64) -> f64 with Div, Panic, Mut {
    let p = (PROBS[target] as f64) / 100000000.0
    if p < 0.0000001 { return 16.0 }
    0.0 - log_f(p)
}

fn backward_output(target: i64) with Mut, Div, Panic {
    // dL/dlogit = prob - one_hot(target)
    // dL/dW_out[d][v] = h[d] * (prob[v] - target_v)
    var v = 0
    while v < VOCAB() {
        var grad_logit = (PROBS[v] as f64) / 100000000.0
        if v == target { grad_logit = grad_logit - 1.0 }

        var d = 0
        while d < D() {
            let hd = (H[d] as f64) / 100000000.0
            let g = hd * grad_logit
            GRAD_OUT[d * VOCAB() + v] = (g * 100000000.0) as i64
            d = d + 1
        }
        v = v + 1
    }
}

fn update_output_weights(lr: f64) with Mut, Div {
    var i = 0
    while i < 4096 {
        let w = get_w(OFF_OUTPUT() + i)
        let g = (GRAD_OUT[i] as f64) / 100000000.0
        set_w(OFF_OUTPUT() + i, w - lr * g)
        i = i + 1
    }
}

fn sqrt_s(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn exp_s(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_s(10.0) * exp_s(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var s = 1.0
    var t = 1.0
    var i = 1
    while i <= 20 { t = t * x / (i as f64); s = s + t; i = i + 1 }
    s
}

fn log_s(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 100.0 }
    var y = 0.0
    if x > 1.0 { y = x / 3.0 }
    var i = 0
    while i < 30 { let ey = exp_s(y); if ey > 0.0 { y = y + 2.0 * (x - ey) / (x + ey) }; i = i + 1 }
    y
}

fn reset_h() with Mut {
    var i = 0
    while i < 16 {
        H1[i as usize] = 0.0
        H1_U[i as usize] = 0.01
        H2[i as usize] = 0.0
        H2_U[i as usize] = 0.01
        i = i + 1
    }
}

fn ssm_step1(x: &[f64; 16], xu: &[f64; 16]) with Mut, Div, Panic {
    // A1 · H1 (component-wise, simpler than full oct mul for stability)
    var i = 0
    while i < 16 {
        let ah = A1[i as usize] * H1[i as usize]
        let bx = B1[i as usize] * x[i as usize]
        let combined = ah + bx
        let new_h = sigmoid_s(combined)
        let s = new_h
        let grad = abs_s(s * (1.0 - s))
        let var_ah = A1_U[i as usize] * A1_U[i as usize] * H1[i as usize] * H1[i as usize] + H1_U[i as usize] * H1_U[i as usize] * A1[i as usize] * A1[i as usize]
        let var_bx = B1_U[i as usize] * B1_U[i as usize] * x[i as usize] * x[i as usize] + xu[i as usize] * xu[i as usize] * B1[i as usize] * B1[i as usize]
        H1[i as usize] = new_h
        H1_U[i as usize] = grad * sqrt_s(var_ah + var_bx)
        i = i + 1
    }
}

fn ssm_step2() with Mut, Div, Panic {
    var i = 0
    while i < 16 {
        let ah = A2[i as usize] * H2[i as usize]
        let bx = B2[i as usize] * H1[i as usize]  // H1 feeds H2
        let combined = ah + bx
        let new_h = sigmoid_s(combined)
        let s = new_h
        let grad = abs_s(s * (1.0 - s))
        let var_ah = A2_U[i as usize] * A2_U[i as usize] * H2[i as usize] * H2[i as usize] + H2_U[i as usize] * H2_U[i as usize] * A2[i as usize] * A2[i as usize]
        let var_bx = B2_U[i as usize] * B2_U[i as usize] * H1[i as usize] * H1[i as usize] + H1_U[i as usize] * H1_U[i as usize] * B2[i as usize] * B2[i as usize]
        H2[i as usize] = new_h
        H2_U[i as usize] = grad * sqrt_s(var_ah + var_bx)
        i = i + 1
    }
}

fn forward_char_scaled(c: i64) with Mut, Div, Panic {
    // Embed
    var x: [f64; 16] = [0.0; 16]
    var xu: [f64; 16] = [0.0; 16]
    var i = 0
    while i < 16 { x[i as usize] = EMB[(c * 16 + i) as usize]; xu[i as usize] = EMB_U[(c * 16 + i) as usize]; i = i + 1 }

    // Layer 1: O-SSM (reads/writes H1 globals directly)
    ssm_step1(&x, &xu)

    // FFN 1: inline to avoid &! on globals
    // 16→32→16
    var fh1: [f64; 32] = [0.0; 32]
    var fhu1: [f64; 32] = [0.0; 32]
    var fj = 0
    while fj < 32 {
        var s = 0.0
        var vs = 0.0
        var fk = 0
        while fk < 16 {
            let w = F1_W1[(fk * 32 + fj) as usize]
            s = s + H1[fk as usize] * w
            vs = vs + H1[fk as usize] * H1[fk as usize] * F1_U1[(fk * 32 + fj) as usize] * F1_U1[(fk * 32 + fj) as usize] + w * w * H1_U[fk as usize] * H1_U[fk as usize]
            fk = fk + 1
        }
        fh1[fj as usize] = relu_s(s)
        if s > 0.0 { fhu1[fj as usize] = sqrt_s(vs) }
        fj = fj + 1
    }
    fj = 0
    while fj < 16 {
        var s = 0.0
        var vs = 0.0
        var fk = 0
        while fk < 32 {
            let w = F1_W2[(fk * 16 + fj) as usize]
            s = s + fh1[fk as usize] * w
            vs = vs + fh1[fk as usize] * fh1[fk as usize] * F1_U2[(fk * 16 + fj) as usize] * F1_U2[(fk * 16 + fj) as usize] + w * w * fhu1[fk as usize] * fhu1[fk as usize]
            fk = fk + 1
        }
        // Residual
        H1[fj as usize] = H1[fj as usize] + s
        H1_U[fj as usize] = sqrt_s(H1_U[fj as usize] * H1_U[fj as usize] + vs)
        fj = fj + 1
    }

    // Layer 2: O-SSM (reads H1, writes H2)
    ssm_step2()

    // FFN 2: inline
    var fh2: [f64; 32] = [0.0; 32]
    var fhu2: [f64; 32] = [0.0; 32]
    fj = 0
    while fj < 32 {
        var s = 0.0
        var vs = 0.0
        var fk = 0
        while fk < 16 {
            let w = F2_W1[(fk * 32 + fj) as usize]
            s = s + H2[fk as usize] * w
            vs = vs + H2[fk as usize] * H2[fk as usize] * F2_U1[(fk * 32 + fj) as usize] * F2_U1[(fk * 32 + fj) as usize] + w * w * H2_U[fk as usize] * H2_U[fk as usize]
            fk = fk + 1
        }
        fh2[fj as usize] = relu_s(s)
        if s > 0.0 { fhu2[fj as usize] = sqrt_s(vs) }
        fj = fj + 1
    }
    fj = 0
    while fj < 16 {
        var s = 0.0
        var vs = 0.0
        var fk = 0
        while fk < 32 {
            let w = F2_W2[(fk * 16 + fj) as usize]
            s = s + fh2[fk as usize] * w
            vs = vs + fh2[fk as usize] * fh2[fk as usize] * F2_U2[(fk * 16 + fj) as usize] * F2_U2[(fk * 16 + fj) as usize] + w * w * fhu2[fk as usize] * fhu2[fk as usize]
            fk = fk + 1
        }
        H2[fj as usize] = H2[fj as usize] + s
        H2_U[fj as usize] = sqrt_s(H2_U[fj as usize] * H2_U[fj as usize] + vs)
        fj = fj + 1
    }

    // Output projection: 16→128
    var j = 0
    while j < 128 {
        var sum = 0.0
        var vs = 0.0
        i = 0
        while i < 16 {
            let w = OUT_W[(i * 128 + j) as usize]
            sum = sum + H2[i as usize] * w
            vs = vs + H2[i as usize] * H2[i as usize] * OUT_U[(i * 128 + j) as usize] * OUT_U[(i * 128 + j) as usize] + w * w * H2_U[i as usize] * H2_U[i as usize]
            i = i + 1
        }
        LOGITS[j as usize] = sum
        LOGITS_U[j as usize] = sqrt_s(vs)
        j = j + 1
    }

    // Softmax
    var mx = LOGITS[0]
    j = 1
    while j < 128 { if LOGITS[j as usize] > mx { mx = LOGITS[j as usize] }; j = j + 1 }
    var sm = 0.0
    j = 0
    while j < 128 { let e = exp_s(LOGITS[j as usize] - mx); PROBS[j as usize] = e; sm = sm + e; j = j + 1 }
    j = 0
    while j < 128 { PROBS[j as usize] = PROBS[j as usize] / sm; j = j + 1 }
}

fn ce_loss_s(target: i64) -> f64 with Mut, Div, Panic {
    let p = PROBS[target as usize]
    if p < 0.0000001 { return 20.0 }
    0.0 - log_s(p)
}

fn predict_s() -> i64 with Mut {
    var best = 0
    var bp = PROBS[0]
    var j = 1
    while j < 128 { if PROBS[j as usize] > bp { bp = PROBS[j as usize]; best = j }; j = j + 1 }
    best
}

fn train_output_weights(seq: &[i64; 16], slen: i64, lr: f64) -> f64 with Mut, Div, Panic {
    // Base loss
    reset_h()
    var base_loss = 0.0
    var t = 0
    while t < slen - 1 {
        forward_char_scaled(seq[t as usize])
        base_loss = base_loss + ce_loss_s(seq[(t + 1) as usize])
        t = t + 1
    }

    // Perturb output weights (stride 16 for speed)
    let delta = 0.001
    var wi = 0
    while wi < 2048 {
        let orig = OUT_W[wi as usize]
        OUT_W[wi as usize] = orig + delta
        reset_h()
        var loss_p = 0.0
        t = 0
        while t < slen - 1 {
            forward_char_scaled(seq[t as usize])
            loss_p = loss_p + ce_loss_s(seq[(t + 1) as usize])
            t = t + 1
        }
        let grad = (loss_p - base_loss) / delta
        OUT_W[wi as usize] = orig - lr * grad
        let u = OUT_U[wi as usize]
        var un = u * (1.0 - 0.1 * abs_s(grad))
        if un < 0.001 { un = 0.001 }
        OUT_U[wi as usize] = un
        wi = wi + 16
    }
    base_loss
}

fn puct_epistemic(node: MCTSNode, c_exploration: f64, c_ignorance: f64) -> f64 {
    // Q term (exploitation)
    let q = node.value_mean

    // U term classic (PUCT exploration)
    let parent_sqrt = sqrt(node.parent_visits)
    let visit_factor = 1.0 + node.visits
    let u = node.prior_mean * parent_sqrt / visit_factor
    let exploitation_bonus = c_exploration * u

    // Epistemic bonus: sqrt(variance) for active inference
    // High variance = high ignorance = explore more
    let safe_variance = max(node.value_variance, 0.0001)  // avoid sqrt(0)
    let epistemic_bonus = c_ignorance * sqrt(safe_variance)

    // Total score: exploit + explore + epistemic
    q + exploitation_bonus + epistemic_bonus
}

fn max(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

fn sqrt(x: f64) -> f64 {
    if x <= 0.0 {
        return 0.0
    }
    // Initial guess
    var guess = x / 2.0
    // Newton-Raphson iterations (manual unroll for L0)
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess
}

fn beta_update(old_mean: f64, old_variance: f64, outcome: f64, weight: f64) -> BetaResult {
    // Approximate Beta update via moment matching
    // outcome in [0,1], weight controls learning rate

    // Current effective sample size (from variance)
    let safe_var = max(old_variance, 0.0001)
    let n_eff = old_mean * (1.0 - old_mean) / safe_var - 1.0
    let n_eff_safe = max(n_eff, 1.0)

    // Update mean (weighted average)
    let new_mean = (old_mean * n_eff_safe + outcome * weight) / (n_eff_safe + weight)

    // Update variance (shrinks with more observations)
    let new_n = n_eff_safe + weight
    let new_variance = new_mean * (1.0 - new_mean) / (new_n + 1.0)

    BetaResult { mean: new_mean, variance: new_variance }
}

fn backprop_node(node: MCTSNode, outcome: f64) -> MCTSNode {
    // Update visits
    let new_visits = node.visits + 1.0

    // Update value with Beta update
    let result = beta_update(
        node.value_mean,
        node.value_variance,
        outcome,
        1.0  // weight = 1 per visit
    )

    // Return updated node
    MCTSNode {
        prior_mean: node.prior_mean,
        value_mean: result.mean,
        value_variance: result.variance,
        visits: new_visits,
        parent_visits: node.parent_visits
    }
}

fn test_puct_scores() -> f64 {
