fn extract_pore_sizes(scaffold: &VoxelScaffold) -> Vec<f64> {
    var sizes: Vec<f64> = vec![]

    let nx = scaffold.size_x as usize
    let ny = scaffold.size_y as usize
    let nz = scaffold.size_z as usize

    for z in 0..nz {
        for y in 0..ny {
            for x in 0..nx {
                let idx = z * ny * nx + y * nx + x

                if idx < scaffold.data.len() && !scaffold.data[idx] {
                    // Count connected void voxels in small neighborhood
                    var pore_count: u64 = 0

                    for dz in 0..3 {
                        for dy in 0..3 {
                            for dx in 0..3 {
                                let nx2 = x + dx
                                let ny2 = y + dy
                                let nz2 = z + dz
                                if nx2 < nx && ny2 < ny && nz2 < nz {
                                    let idx2 = nz2 * ny * nx + ny2 * nx + nx2
                                    if idx2 < scaffold.data.len() && !scaffold.data[idx2] {
                                        pore_count = pore_count + 1
                                    }
                                }
                            }
                        }
                    }

                    if pore_count > 1 {
                        sizes.push(pore_count as f64)
                    }
                }
            }
        }
    }

    sizes
}

pub fn gliding_box_lacunarity(data: &Vec<f64>, box_size: u32) -> LacunarityValue {
    let n = data.len()
    let r = box_size as usize

    if n < r {
        return LacunarityValue { value: 0.0, std_dev: 1.0 }
    }

    let n_boxes = n - r + 1

    // Compute box sums
    var sum_m: f64 = 0.0
    var sum_m2: f64 = 0.0

    for i in 0..n_boxes {
        var mass = 0.0
        for j in 0..r {
            mass = mass + data[i + j]
        }
        sum_m = sum_m + mass
        sum_m2 = sum_m2 + mass * mass
    }

    let mean_m = sum_m / (n_boxes as f64)
    let mean_m2 = sum_m2 / (n_boxes as f64)

    let lac = if mean_m > 0.0 {
        mean_m2 / (mean_m * mean_m) - 1.0
    } else {
        0.0
    }

    let var_m = (mean_m2 - mean_m * mean_m) / (n_boxes as f64)
    let relative_var = if mean_m > 0.0 { 4.0 * var_m / (mean_m * mean_m) } else { 1.0 }
    let total_var = relative_var * lac * lac

    LacunarityValue {
        value: lac,
        std_dev: sqrt_f64(total_var),
    }
}

