fn codon_to_aa(b1: i32, b2: i32, b3: i32) -> i32 {
    // Bases: A=0, G=1, U=2, C=3
    // AA codes: 0=Ala 1=Arg 2=Asn 3=Asp 4=Cys 5=Gln 6=Glu 7=Gly
    //           8=His 9=Ile 10=Leu 11=Lys 12=Met 13=Phe 14=Pro 15=Ser
    //           16=Thr 17=Trp 18=Tyr 19=Val 20=Stop
    if b1 == 2 {
        if b2 == 2 { if b3 == 0 || b3 == 1 { return 10 } else { return 13 } }
        if b2 == 3 { return 15 }
        if b2 == 0 { if b3 == 2 || b3 == 3 { return 18 } else { return 20 } }
        if b2 == 1 {
            if b3 == 2 || b3 == 3 { return 4 }
            if b3 == 0 { return 20 }
            return 17
        }
    }
    if b1 == 3 {
        if b2 == 2 { return 10 }
        if b2 == 3 { return 14 }
        if b2 == 0 { if b3 == 2 || b3 == 3 { return 8 } else { return 5 } }
        if b2 == 1 { return 1 }
    }
    if b1 == 0 {
        if b2 == 2 { if b3 == 1 { return 12 } else { return 9 } }
        if b2 == 3 { return 16 }
        if b2 == 0 { if b3 == 2 || b3 == 3 { return 2 } else { return 11 } }
        if b2 == 1 { if b3 == 2 || b3 == 3 { return 15 } else { return 1 } }
    }
    if b1 == 1 {
        if b2 == 2 { return 19 }
        if b2 == 3 { return 0 }
        if b2 == 0 { if b3 == 2 || b3 == 3 { return 3 } else { return 6 } }
        if b2 == 1 { return 7 }
    }
    -1
}

fn build_table() -> [i32; 64] with Mut, Panic, Div {
    var t: [i32; 64] = [0; 64]
    var b1: i32 = 0
    while b1 < 4 {
        var b2: i32 = 0
        while b2 < 4 {
            var b3: i32 = 0
            while b3 < 4 {
                let idx = b1 + b2 * 4 + b3 * 16
                t[idx as usize] = codon_to_aa(b1, b2, b3)
                b3 = b3 + 1
            }
            b2 = b2 + 1
        }
        b1 = b1 + 1
    }
    t
}

fn hamming6(a: i32, b: i32) -> i32 {
    var x = a ^ b
    var count: i32 = 0
    var bit: i32 = 0
    while bit < 6 { if (x & 1) == 1 { count = count + 1 }; x = x >> 1; bit = bit + 1 }
    count
}

fn gf_abs(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

fn gf_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i: i32 = 0
    while i < 25 {
        y = 0.5 * (y + x / y)
        i = i + 1
    }
    y
}

fn gf_exp(x: f64) -> f64 with Mut, Div, Panic {
    if x > 15.0 { return 3269446.7 }
    if x < 0.0 - 15.0 { return 0.0 }
    let x2 = x * x
    let x3 = x2 * x
    let x4 = x2 * x2
    1.0 + x + x2/2.0 + x3/6.0 + x4/24.0 + x4*x/120.0 + x4*x2/720.0
}

fn gf_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 1e30 }
    // Range-reduce to [0.5, 2.0) → atanh series converges fast
    var y = x
    var k: i64 = 0
    while y >= 2.0 { y = y / 2.0; k = k + 1 }
    while y < 0.5  { y = y * 2.0; k = k - 1 }
    let u  = (y - 1.0) / (y + 1.0)
    let u2 = u * u
    let s  = u * (1.0 + u2/3.0 + u2*u2/5.0 + u2*u2*u2/7.0 + u2*u2*u2*u2/9.0)
    2.0 * s + (k as f64) * 0.6931471805599453
}

fn sigmoid(x: f64) -> f64 with Mut, Div, Panic {
    1.0 / (1.0 + gf_exp(0.0 - x))
}

fn lcg_u01(s: i64) -> f64 {
    let pos = if s < 0 { 0 - s } else { s }
    (pos % 1000000) as f64 / 1000000.0
}

fn bernoulli(state: i64, p: f64) -> i64 {
    if lcg_u01(state) < p { 1 } else { 0 }
}

fn gen_snp_mat() -> [f64; 200] with Mut, Div, Panic {
    var mat: [f64; 200] = [0.0; 200]
    var seed: i64 = 31415926
    var ind: i32 = 0
    while ind < 20 {
        let pop_b: i64 = if ind >= 10 { 1 } else { 0 }
        let causal_freq = if pop_b == 1 { 0.35 } else { 0.15 }
        let null_freq   = if pop_b == 1 { 0.30 } else { 0.10 }
        let base = ind as usize * 10
        var locus: i32 = 0
        while locus < 10 {
            let s1 = lcg(seed)
            let s2 = lcg(s1)
            seed = lcg(s2)
            let freq = if locus < 5 { causal_freq } else { null_freq }
            let g = (bernoulli(s1, freq) + bernoulli(s2, freq)) as f64
            mat[base + locus as usize] = g
            locus = locus + 1
        }
        ind = ind + 1
    }
    mat
}

fn gen_labels(mat: [f64; 200]) -> [f64; 20] with Mut, Div, Panic {
    var labels: [f64; 20] = [0.0; 20]
    var seed: i64 = 141421356
    var ind: i32 = 0
    while ind < 20 {
        let base = ind as usize * 10
        var causal_sum: f64 = 0.0
        var l: i32 = 0
        while l < 5 {
            causal_sum = causal_sum + mat[base + l as usize] * 0.6
            l = l + 1
        }
        let risk = sigmoid(causal_sum - 2.5)
        let s1 = lcg(seed)
        seed = lcg(s1)
        labels[ind as usize] = if lcg_u01(s1) < risk { 1.0 } else { 0.0 }
        ind = ind + 1
    }
    labels
}

