fn init_w1() -> [f64; 40] with Mut, Div, Panic {
    // W1: 4 neurons × 10 inputs = 40 weights
    let std: f64 = gf_sqrt(2.0 / 14.0)  // Xavier: 2/(fan_in + fan_out)
    var w: [f64; 40] = [0.0; 40]
    var seed: i64 = 271828182
    var i: i32 = 0
    while i < 40 {
        let s1 = lcg(seed)
        seed = lcg(s1)
        let u = lcg_u01(s1) - 0.5
        w[i as usize] = u * 2.0 * std
        i = i + 1
    }
    w
}

fn init_w2() -> [f64; 4] with Mut, Div, Panic {
    // W2: 1 output × 4 hidden = 4 weights
    let std: f64 = gf_sqrt(2.0 / 5.0)
    var w: [f64; 4] = [0.0; 4]
    var seed: i64 = 161803398
    var i: i32 = 0
    while i < 4 {
        let s1 = lcg(seed)
        seed = lcg(s1)
        let u = lcg_u01(s1) - 0.5
        w[i as usize] = u * 2.0 * std
        i = i + 1
    }
    w
}

fn get_features_10(mat: [f64; 200], ind: i32) -> [f64; 10] with Mut, Div, Panic {
    var x: [f64; 10] = [0.0; 10]
    let base = ind as usize * 10
    var k: i32 = 0
    while k < 10 {
        x[k as usize] = mat[base + k as usize]
        k = k + 1
    }
    x
}

fn mlp_forward(
    x:  [f64; 10],
    w1: [f64; 40],
    b1: f64,
    w2: [f64; 4],
    b2: f64
) -> f64 with Mut, Div, Panic {
    // Layer 1: h = ReLU(W1*x + b1), h ∈ R^4
    var h: [f64; 4] = [0.0; 4]
    var j: i32 = 0
    while j < 4 {
        var dot: f64 = b1
        var k: i32 = 0
        while k < 10 {
            dot = dot + w1[j as usize * 10 + k as usize] * x[k as usize]
            k = k + 1
        }
        h[j as usize] = if dot > 0.0 { dot } else { 0.0 }
        j = j + 1
    }
    // Layer 2: out = sigmoid(W2·h + b2)
    var dot2: f64 = b2
    var j2: i32 = 0
    while j2 < 4 {
        dot2 = dot2 + w2[j2 as usize] * h[j2 as usize]
        j2 = j2 + 1
    }
    sigmoid(dot2)
}

fn predict_all_20(
    mat: [f64; 200],
    w1:  [f64; 40],
    w2:  [f64; 4]
) -> [f64; 20] with Mut, Div, Panic {
    var preds: [f64; 20] = [0.0; 20]
    var i: i32 = 0
    while i < 20 {
        let x = get_features_10(mat, i)
        preds[i as usize] = mlp_forward(x, w1, 0.01, w2, 0.0 - 0.3)
        i = i + 1
    }
    preds
}

fn group_mean(preds: [f64; 20], groups: [i64; 20], g: i64) -> f64 with Mut, Div, Panic {
    var s: f64 = 0.0
    var n: i64 = 0
    var i: i32 = 0
    while i < 20 {
        if groups[i as usize] == g {
            s = s + preds[i as usize]
            n = n + 1
        }
        i = i + 1
    }
    if n == 0 { return 0.5 }
    s / (n as f64)
}

fn calibration_gap(preds: [f64; 20], labels: [f64; 20]) -> f64 with Mut, Div, Panic {
    var s1: f64 = 0.0   var c1: f64 = 0.0
    var s0: f64 = 0.0   var c0: f64 = 0.0
    var i: i32 = 0
    while i < 20 {
        if labels[i as usize] > 0.5 {
            s1 = s1 + preds[i as usize]; c1 = c1 + 1.0
        } else {
            s0 = s0 + preds[i as usize]; c0 = c0 + 1.0
        }
        i = i + 1
    }
    let m1 = if c1 > 0.0 { s1 / c1 } else { 0.5 }
    let m0 = if c0 > 0.0 { s0 / c0 } else { 0.5 }
    m1 - m0
}

fn laplace_noise(seed: i64, b: f64) -> f64 with Mut, Div, Panic {
    let u = lcg_u01(seed) - 0.5
    let sign_u = if u >= 0.0 { 1.0 } else { 0.0 - 1.0 }
    let abs_u = gf_abs(u)
    if abs_u < 1e-10 { return 0.0 }
    let arg = 1.0 - 2.0 * abs_u
    if arg < 1e-9 { return sign_u * b * 20.0 }
    0.0 - sign_u * b * gf_ln(arg)
}

fn allele_freq(mat: [f64; 200], locus: i32) -> f64 with Mut, Div, Panic {
    var s: f64 = 0.0
    var i: i32 = 0
    while i < 20 {
        s = s + mat[i as usize * 10 + locus as usize]
        i = i + 1
    }
    s / 40.0  // allele count / (2n)
}

fn gum_group_budget(mean_pred: f64, n_group: f64) -> f64 with Mut, Div, Panic {
    let u_a = gf_sqrt(mean_pred * (1.0 - mean_pred) / n_group)
    let u_b = mean_pred * 0.05 / gf_sqrt(3.0)
    gf_sqrt(u_a*u_a + u_b*u_b)
}

fn compute_fibonacci(n: i32) -> Knowledge<i32> {
    if n <= 1 {
        return Knowledge::new(n, uncertainty: 0.0, confidence: 1.0, source: "base_case")
    }

    // Esta operação repetitiva pode ser otimizada pelo GLM-4.7
    let fib_n_1 = compute_fibonacci(n - 1)
    let fib_n_2 = compute_fibonacci(n - 2)

    // O GLM pode sugerir loop unrolling ou memoization
    Knowledge::new(
        value: fib_n_1.value + fib_n_2.value,
        uncertainty: fib_n_1.uncertainty + fib_n_2.uncertainty,
        confidence: min(fib_n_1.confidence, fib_n_2.confidence),
        source: "recursive_calculation"
    )
}

fn matrix_multiply_optimized(a: Knowledge<f64>[10][10], b: Knowledge<f64>[10][10]) -> Knowledge<f64>[10][10] {
    var result = zero_matrix()

    // Loop com multiplicações por potências de 2 - GLM pode sugerir strength reduction
    for i in 0..10 {
        for j in 0..10 {
            var sum = Knowledge::new(0.0, 0.0, 1.0, "accumulator")

            for k in 0..10 {
                // O GLM pode identificar que esta é uma boa候选 para auto-vectorization
                sum = sum + (a[i][k] * b[k][j])
            }

            result[i][j] = sum
        }
    }

    result
}

fn constant_folding_demo(x: i32) -> Knowledge<i32> {
    let pi_approx = 3.14159  // Constante que pode ser propagada
    let two_pi = 2.0 * pi_approx  // O GLM pode sugerir calcular isso em tempo de compilação

    let measurement = Knowledge::new(x, 1.0, 0.95, "input_measurement")

    // Expressões que podem ser constant-folded
    let processed = measurement * Knowledge::new(two_pi, 0.0, 1.0, "derived_constant")

    // Código que pode ser eliminado como dead code se a condição for sempre falsa
    if false {  // Esta branch nunca é executada - GLM pode sugerir eliminá-la
        let dead_code = measurement + Knowledge::new(1000, 0.0, 1.0, "dead_branch")
        return dead_code
    }

    processed
}

fn cse_demo(x: Knowledge<f64>, y: Knowledge<f64>) -> Knowledge<f64> {
    let term1 = x * y + x * y  // Esta expressão se repete - GLM pode sugerir CSE
    let term2 = (x + y) * (x + y)  // Padrão similar

    let result = term1 + term2

    // Mais CSE opportunities
    let repeated = x.value.sin() + x.value.sin()  // GLM pode calcular apenas uma vez
    let with_repeated = result + Knowledge::new(repeated, 0.0, 1.0, "cse_optimized")

    with_repeated
}

fn epistemic_optimization_demo(measurements: Knowledge<f64>[]) -> Knowledge<f64> {
    var total = Knowledge::new(0.0, 0.0, 1.0, "accumulator")

    // O GLM pode sugerir otimizações específicas para operações epistêmicas
    for measurement in measurements {
        // Propagação de incerteza que pode ser otimizada
        total = total + measurement

        // O GLM pode sugerir usar approximações mais eficientes para operações epistêmicas
        if measurement.confidence > 0.9 {
            let high_confidence = measurement * Knowledge::new(1.0, 0.0, 0.99, "confidence_boost")
            total = total + high_confidence
        }
    }

    total
}

fn sqrt_nr(x: f64) -> f64 with Mut, Div {
    if x <= 0.0 { return 0.0 }
    var g = x * 0.5
    if x < 1.0 { g = 1.0 }
    var i: i64 = 0
    while i < 50 {
        g = 0.5 * (g + x / g)
        i = i + 1
    }
    g
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    abs_f64(a - b) < tol
}

fn gum_product(a: f64, u_a: f64, b: f64, u_b: f64) -> f64 with Mut, Div {
    sqrt_nr(b * b * u_a * u_a + a * a * u_b * u_b)
}

fn gum_quotient(a: f64, u_a: f64, b: f64, u_b: f64) -> f64 with Mut, Div {
    let term1 = u_a / b
    let term2 = a * u_b / (b * b)
    sqrt_nr(term1 * term1 + term2 * term2)
}

fn gum_sum(u_a: f64, u_b: f64) -> f64 with Mut, Div {
    sqrt_nr(u_a * u_a + u_b * u_b)
}

fn gum_weighted_mean_uncertainty(
    u_values: [f64; 8],
    count: i64
) -> f64 with Mut, Div {
    var w_sum = 0.0
    var i: i64 = 0
    while i < count && i < 8 {
        let u = u_values[i as usize]
        if u > 0.0 {
            w_sum = w_sum + 1.0 / (u * u)
        }
        i = i + 1
    }
    if w_sum > 0.0 {
        1.0 / sqrt_nr(w_sum)
    } else {
        0.0
    }
}

fn provenance_merge(prov_a: i64, prov_b: i64) -> i64 {
    prov_a ^ prov_b  // XOR hash: commutative, associative, invertible
}

fn provenance_tag(sensor_id: i64) -> i64 {
    // Each sensor gets a unique bit position in the provenance word
    if sensor_id < 64 {
        var bit: i64 = 1
        var shift: i64 = 0
        while shift < sensor_id {
            bit = bit * 2
            shift = shift + 1
        }
        bit
    } else {
        1  // Fallback for >64 sensors
    }
}

fn compute_epsilon_entropy(uncertainties: [f64; 8], count: i64) -> f64 with Mut, Div {
    // Simple 4-bin histogram of uncertainty values
    var bins: [i64; 4] = [0; 4]
    var min_u = 1.0e30
    var max_u = 0.0
    var i: i64 = 0

    // Find range
    while i < count && i < 8 {
        let u = uncertainties[i as usize]
        if u < min_u { min_u = u }
        if u > max_u { max_u = u }
        i = i + 1
    }

    let range = max_u - min_u
    if range < 1.0e-12 { return 0.0 }  // All same → zero entropy

    // Bin
    let bin_width = range / 4.0
    i = 0
    while i < count && i < 8 {
        let u = uncertainties[i as usize]
        var bin_idx = ((u - min_u) / bin_width) as i64
        if bin_idx >= 4 { bin_idx = 3 }
        bins[bin_idx as usize] = bins[bin_idx as usize] + 1
        i = i + 1
    }

    // H = -sum(p * log2(p))
    // Approximate log2(x) ≈ (x - 1) for x near 1 (first-order Taylor)
    // Better: use repeated halving
    var entropy = 0.0
    i = 0
    while i < 4 {
        let c = bins[i as usize]
        if c > 0 {
            // p = c / count
            var p_num = 0.0
            var j: i64 = 0
            while j < c { p_num = p_num + 1.0; j = j + 1 }
            var p_den = 0.0
            j = 0
            while j < count { p_den = p_den + 1.0; j = j + 1 }
            let p = p_num / p_den

            // log2(p) approximation via natural log / ln(2)
            // ln(p) ≈ 2 * ((p-1)/(p+1)) for 0 < p < 2
            let ratio = (p - 1.0) / (p + 1.0)
            let ln_p = 2.0 * ratio
            let log2_p = ln_p / 0.6931471805599453  // ln(2)

            entropy = entropy - p * log2_p
        }
        i = i + 1
    }
    entropy
}

fn select_kernel_variant(entropy: f64) -> i64 {
    // 0 = fast (skip shadow regs), 1 = adaptive, 2 = full GUM
    if entropy < 0.5 { 0 }
    else if entropy < 2.0 { 1 }
    else { 2 }
}

fn qmul(a: Quaternion, b: Quaternion) -> Quaternion {
    return Quaternion {
        w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
        x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
        y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
        z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w
    }
}

fn qnorm2(q: Quaternion) -> f64 {
    return q.w * q.w + q.x * q.x + q.y * q.y + q.z * q.z
}

fn centroid(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64) -> Point {
    Point { x: (ax + bx + cx) / 3.0, y: (ay + by + cy) / 3.0 }
}

fn circumcenter(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64) -> Point {
    let d = 2.0 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
    let a2 = ax * ax + ay * ay
    let b2 = bx * bx + by * by
    let c2 = cx * cx + cy * cy
    let ux = (a2 * (by - cy) + b2 * (cy - ay) + c2 * (ay - by)) / d
    let uy = (a2 * (cx - bx) + b2 * (ax - cx) + c2 * (bx - ax)) / d
    Point { x: ux, y: uy }
}

fn cross2d(ox: f64, oy: f64, px: f64, py: f64, qx: f64, qy: f64) -> f64 {
    (px - ox) * (qy - oy) - (py - oy) * (qx - ox)
}

fn simulate(dose: f64, vd: f64, ke: f64, dt: f64, t_end: f64) -> PKResult {
    var c: f64 = dose / vd
    var t: f64 = 0.0
    var cmax: f64 = c

    while t < t_end {
        c = c + (-ke * c * dt)
        if c > cmax {
            cmax = c
        }
        t = t + dt
    }

    PKResult { cmax: cmax, safe: cmax < 75.0 }
}

fn velocity_u(x: f64, y: f64) -> f64 {
    // u(x,y) = sin(x) * cos(y)  -- divergence-free field
    x * x - y * y
}

fn velocity_v(x: f64, y: f64) -> f64 {
    // v(x,y) = -cos(x) * sin(y) -- divergence-free field
    2.0 * x * y * -1.0
}

fn print_f64(x: f64) {
    // Simple print for debugging
    if x < 0.0 {
        print("-")
        print_f64(-x)
        return
    }
    let int_part = x as i64
    let frac = (x - (int_part as f64)) * 1000.0
    let frac_int = frac as i64
    print_i64(int_part)
    print(".")
    if frac_int < 100 { print("0") }
    if frac_int < 10 { print("0") }
    print_i64(frac_int)
}

fn print_i64(x: i64) {
    if x == 0 {
        print("0")
        return
    }
    if x < 0 {
        print("-")
        print_i64(-x)
        return
    }
    if x >= 10 {
        print_i64(x / 10)
    }
    let digit = (x % 10) as i32
    if digit == 0 { print("0") }
    else if digit == 1 { print("1") }
    else if digit == 2 { print("2") }
    else if digit == 3 { print("3") }
    else if digit == 4 { print("4") }
    else if digit == 5 { print("5") }
    else if digit == 6 { print("6") }
    else if digit == 7 { print("7") }
    else if digit == 8 { print("8") }
    else if digit == 9 { print("9") }
}

