fn abs(x: i32) -> i32 {
    if x < 0 {
        return 0 - x
    }
    return x
}

fn draw_line_segment(
    canvas: Canvas,
    x0: i32,
    y0: i32,
    x1: i32,
    y1: i32,
    color: i32,
    style: i32
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    let dx = abs(x1 - x0)
    let dy = abs(y1 - y0)
    let sx = if x0 < x1 { 1 } else { -1 }
    let sy = if y0 < y1 { 1 } else { -1 }
    var err = dx - dy

    var x = x0
    var y = y0
    var counter = 0

    while x != x1 || y != y1 {
        let should_draw = if style == LINE_STYLE_SOLID() {
            1
        } else {
            if counter % 5 < 3 { 1 } else { 0 }
        }

        if should_draw == 1 {
            result = canvas_set_pixel(result, x, y, 9608, color)
        }

        counter = counter + 1

        let e2 = 2 * err
        if e2 > 0 - dy {
            err = err - dy
            x = x + sx
        }
        if e2 < dx {
            err = err + dx
            y = y + sy
        }
    }

    result = canvas_set_pixel(result, x1, y1, 9608, color)
    return result
}

fn line_plot_simple(
    canvas: Canvas,
    vp: &Viewport,
    x_data: &[f64],
    y_data: &[f64],
    n_points: i32,
    color: i32,
    style: i32
) -> Canvas with Mut, Panic, Div {
    if n_points < 2 {
        return canvas
    }

    var result = canvas

    var i = 0
    while i < n_points - 1 {
        let x0 = world_to_canvas_x(vp, x_data[i])
        let y0 = world_to_canvas_y(vp, y_data[i])
        let x1 = world_to_canvas_x(vp, x_data[i + 1])
        let y1 = world_to_canvas_y(vp, y_data[i + 1])

        result = draw_line_segment(result, x0, y0, x1, y1, color, style)
        i = i + 1
    }

    return result
}

fn bar_chart_vertical_simple(
    canvas: Canvas,
    vp: &Viewport,
    values: &[f64],
    colors: &[i32],
    n_bars: i32,
    bar_width: f64
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    let x_range = vp.x_max - vp.x_min
    let spacing = x_range / ((n_bars + 1) as f64)

    var i = 0
    while i < n_bars {
        let x_center = vp.x_min + spacing * ((i + 1) as f64)
        let x_left = x_center - (bar_width / 2.0)
        let x_right = x_center + (bar_width / 2.0)

        let px_left = world_to_canvas_x(vp, x_left)
        let px_right = world_to_canvas_x(vp, x_right)
        let py_baseline = world_to_canvas_y(vp, 0.0)
        let py_value = world_to_canvas_y(vp, values[i])

        let rect_width = px_right - px_left
        let rect_height = if py_baseline > py_value {
            py_baseline - py_value
        } else {
            py_value - py_baseline
        }
        let rect_y = if py_baseline > py_value { py_value } else { py_baseline }

        result = fill_rect(result, px_left, rect_y, rect_width, rect_height, colors[i])
        i = i + 1
    }

    return result
}

fn compute_bins_simple(data: &[f64], n_data: i32, n_bins: i32, min_val: f64, max_val: f64) -> BinData with Mut, Panic, Div {
    var result = bin_data_empty()
    result.n_bins = n_bins

    let range = max_val - min_val

    var i = 0
    while i <= n_bins {
        result.bin_edges[i] = min_val + ((i as f64) / (n_bins as f64)) * range
        i = i + 1
    }

    var data_idx = 0
    while data_idx < n_data {
        let value = data[data_idx]

        var bin_idx = 0
        var found = 0
        while bin_idx < n_bins && found == 0 {
            let bin_left = result.bin_edges[bin_idx]
            let bin_right = result.bin_edges[bin_idx + 1]

            let in_bin = if bin_idx == n_bins - 1 {
                if value >= bin_left && value <= bin_right { 1 } else { 0 }
            } else {
                if value >= bin_left && value < bin_right { 1 } else { 0 }
            }

            if in_bin == 1 {
                result.bin_counts[bin_idx] = result.bin_counts[bin_idx] + 1
                result.total_count = result.total_count + 1
                found = 1
            }

            bin_idx = bin_idx + 1
        }

        data_idx = data_idx + 1
    }

    return result
}

fn histogram_simple(
    canvas: Canvas,
    vp: &Viewport,
    bin_data: &BinData,
    color: i32
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    var i = 0
    while i < bin_data.n_bins {
        let bin_left = bin_data.bin_edges[i]
        let bin_right = bin_data.bin_edges[i + 1]
        let count = bin_data.bin_counts[i]

        let px_left = world_to_canvas_x(vp, bin_left)
        let px_right = world_to_canvas_x(vp, bin_right)
        let py_baseline = world_to_canvas_y(vp, 0.0)
        let py_top = world_to_canvas_y(vp, count as f64)

        let bar_width = px_right - px_left
        let bar_height = py_baseline - py_top

        result = fill_rect(result, px_left, py_top, bar_width, bar_height, color)

        i = i + 1
    }

    return result
}

