            if idx < 1800 {
                d = density[idx]
            }

            if d == 0 {
                print(" ")
            } else { if d < 2 {
                print("\x1b[34m.\x1b[0m")
            } else { if d < 5 {
                print("\x1b[36m+\x1b[0m")
