fn demo_streamlines() with IO, Mut, Div, Panic {
    print("\x1b[2J\x1b[H")
    print("\x1b[1;36m╔══════════════════════════════════════════════════════════╗\x1b[0m\n")
    print("\x1b[1;36m║          PHASE 6: SCIENTIFIC CHARTS                      ║\x1b[0m\n")
    print("\x1b[1;36m║     Demo 4/4: Streamlines (Dipole Field)                 ║\x1b[0m\n")
    print("\x1b[1;36m╚══════════════════════════════════════════════════════════╝\x1b[0m\n\n")

    // Display buffer
    var display = [32; 1800]  // 60 x 30

    // Integrate streamlines from seed points
    var seed = 0
    while seed < 20 {
        // Seed positions (grid around y-axis)
        var sx = 0.0
        var sy = -2.5 + (seed as f64) * 0.26

        // Integrate forward
        var step = 0
        while step < 200 {
            // Check bounds
            if sx < -3.0 { step = 200 }
            else { if sx > 3.0 { step = 200 }
            else { if sy < -3.0 { step = 200 }
            else { if sy > 3.0 { step = 200 }
            else {
                // Plot point
                let gx = ((sx + 3.0) * 10.0) as i32
                let gy = ((sy + 3.0) * 5.0) as i32
                if gx >= 0 {
                    if gx < 60 {
                        if gy >= 0 {
                            if gy < 30 {
                                let idx = gy * 60 + gx

                                // Get dipole field direction
                                let r1x = sx + 1.0
                                let r1y = sy
                                let r1sq = r1x * r1x + r1y * r1y + 0.1
                                let r2x = sx - 1.0
                                let r2y = sy
                                let r2sq = r2x * r2x + r2y * r2y + 0.1

                                let vx = r1x / r1sq - r2x / r2sq
                                let vy = r1y / r1sq - r2y / r2sq

                                // Direction character
                                var ch = 45  // '-'
                                let abs_vx = vx
                                let abs_vy = vy
                                if abs_vx < 0.0 { let abs_vx = 0.0 - abs_vx }
                                if abs_vy < 0.0 { let abs_vy = 0.0 - abs_vy }

                                if abs_vy > abs_vx * 2.0 {
                                    ch = 124  // '|'
                                } else { if abs_vx > abs_vy * 2.0 {
                                    ch = 45  // '-'
                                } else {
                                    if vx * vy > 0.0 {
                                        ch = 92  // '\'
                                    } else {
                                        ch = 47  // '/'
                                    }
                                }}

                                if idx < 1800 {
                                    display[idx] = ch
                                }
                            }
                        }
                    }
                }

                // Euler step
                let r1x = sx + 1.0
                let r1y = sy
                let r1sq = r1x * r1x + r1y * r1y + 0.1
                let r2x = sx - 1.0
                let r2y = sy
                let r2sq = r2x * r2x + r2y * r2y + 0.1

                let vx = r1x / r1sq - r2x / r2sq
                let vy = r1y / r1sq - r2y / r2sq

                let vlen = sqrt_simple(vx * vx + vy * vy)
                if vlen > 0.01 {
                    sx = sx + vx * 0.03 / vlen
                    sy = sy + vy * 0.03 / vlen
                } else {
                    step = 200
                }
            }}}}

            step = step + 1
        }

        seed = seed + 1
    }

    // Mark source and sink
    let src_x = ((0.0 - 1.0 + 3.0) * 10.0) as i32
    let src_y = ((0.0 + 3.0) * 5.0) as i32
    let sink_x = ((1.0 + 3.0) * 10.0) as i32
    let sink_y = ((0.0 + 3.0) * 5.0) as i32

    if src_x >= 0 {
        if src_x < 60 {
            if src_y >= 0 {
                if src_y < 30 {
                    display[src_y * 60 + src_x] = 43  // '+'
                }
            }
        }
    }
    if sink_x >= 0 {
        if sink_x < 60 {
            if sink_y >= 0 {
                if sink_y < 30 {
                    display[sink_y * 60 + sink_x] = 45  // '-' for sink
                }
            }
        }
    }

    // Render
    print("   y\n")
    print("   ^\n")

    var y = 29
    while y >= 0 {
        print("   |")

        var x = 0
        while x < 60 {
            let idx = y * 60 + x
            var ch = 32
            if idx < 1800 {
                ch = display[idx]
            }

            // Color streamlines cyan, special points red
            if ch == 43 {
                print("\x1b[1;31m+\x1b[0m")  // Source
            } else { if ch == 45 {
                if x == sink_x {
                    if y == sink_y {
                        print("\x1b[1;31m-\x1b[0m")  // Sink
                    } else {
                        print("\x1b[36m-\x1b[0m")
                    }
                } else {
                    print("\x1b[36m-\x1b[0m")
                }
            } else { if ch == 32 {
                print(" ")
            } else {
                print("\x1b[36m")
                print_char_code(ch)
                print("\x1b[0m")
            }}}

            x = x + 1
        }
        print("\n")
        y = y - 1
    }

    print("   +-------------------------------------------------------------> x\n")
    print("    -3                           0                              3\n\n")

    print("   Electric dipole field: \x1b[1;31m+\x1b[0m source at (-1,0), \x1b[1;31m-\x1b[0m sink at (1,0)\n")
    print("   Field lines flow from positive to negative charge\n")
}

fn sqrt_simple(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    var g = x * 0.5
    if g < 1.0 { g = 1.0 }
    var i = 0
    while i < 8 {
        g = 0.5 * (g + x / g)
        i = i + 1
    }
    return g
}

fn print_char_code(code: i32) with IO {
    if code == 32 { print(" ") }
    else { if code == 45 { print("-") }
    else { if code == 47 { print("/") }
    else { if code == 92 { print("\\") }
    else { if code == 124 { print("|") }
    else { print(".") }
    }}}}
}

fn demo_social_network() with IO, Mut, Div, Panic {
    print("\x1b[2J\x1b[H")
    print("\x1b[1;36m=== Demo 1: Social Network Graph ===\x1b[0m\n\n")

    // Create nodes (6 people)
    var nodes: [Node; 20] = [Node {
        id: 0, x: 0.0, y: 0.0, label: 65, color: 37, fixed: 0
    }; 20]

    var edges: [Edge; 50] = [Edge {
        from_id: 0, to_id: 0, weight: 1.0, directed: 0
    }; 50]

    // Initialize positions and labels
    let n_nodes = 6
    var i = 0
    while i < n_nodes {
        nodes[i].id = i
        nodes[i].label = 65 + i
        nodes[i].x = ((i % 3) as f64) * 10.0 - 10.0
        nodes[i].y = ((i / 3) as f64) * 8.0 - 4.0
        i = i + 1
    }

    // Create friendships
    let n_edges = 8
    edges[0] = Edge { from_id: 0, to_id: 1, weight: 1.0, directed: 0 }  // A-B
    edges[1] = Edge { from_id: 0, to_id: 2, weight: 1.0, directed: 0 }  // A-C
    edges[2] = Edge { from_id: 1, to_id: 2, weight: 1.0, directed: 0 }  // B-C
    edges[3] = Edge { from_id: 1, to_id: 3, weight: 1.0, directed: 0 }  // B-D
    edges[4] = Edge { from_id: 2, to_id: 4, weight: 1.0, directed: 0 }  // C-E
    edges[5] = Edge { from_id: 3, to_id: 4, weight: 1.0, directed: 0 }  // D-E
    edges[6] = Edge { from_id: 3, to_id: 5, weight: 1.0, directed: 0 }  // D-F
    edges[7] = Edge { from_id: 4, to_id: 5, weight: 1.0, directed: 0 }  // E-F

    print("Social network with ")
    print_i32(n_nodes)
    print(" people and ")
    print_i32(n_edges)
    print(" friendships\n\n")

    // Apply force-directed layout
    print("Applying Fruchterman-Reingold layout...\n\n")

    var forces: [Force; 20] = [Force { fx: 0.0, fy: 0.0 }; 20]
    let k = 8.0  // Optimal distance
    var temperature = 10.0

    var iter = 0
    while iter < 50 {
        // Reset forces
        var f = 0
        while f < n_nodes {
            forces[f].fx = 0.0
            forces[f].fy = 0.0
            f = f + 1
        }

        // Repulsive forces
        i = 0
        while i < n_nodes {
            var j = 0
            while j < n_nodes {
                if i != j {
                    let dx = nodes[i].x - nodes[j].x
                    let dy = nodes[i].y - nodes[j].y
                    let dist = sqrt_approx(dx * dx + dy * dy) + 0.1
                    let force = (k * k) / dist
                    forces[i].fx = forces[i].fx + (dx / dist) * force
                    forces[i].fy = forces[i].fy + (dy / dist) * force
                }
                j = j + 1
            }
            i = i + 1
        }

        // Attractive forces
        var e = 0
        while e < n_edges {
            let from = edges[e].from_id
            let to = edges[e].to_id
            let dx = nodes[to].x - nodes[from].x
            let dy = nodes[to].y - nodes[from].y
            let dist = sqrt_approx(dx * dx + dy * dy) + 0.1
            let force = (dist * dist) / k

            forces[from].fx = forces[from].fx + (dx / dist) * force
            forces[from].fy = forces[from].fy + (dy / dist) * force
            forces[to].fx = forces[to].fx - (dx / dist) * force
            forces[to].fy = forces[to].fy - (dy / dist) * force

            e = e + 1
        }

        // Apply forces with temperature limiting
        i = 0
        while i < n_nodes {
            let mag = sqrt_approx(forces[i].fx * forces[i].fx + forces[i].fy * forces[i].fy)
            if mag > temperature {
                forces[i].fx = forces[i].fx * temperature / mag
                forces[i].fy = forces[i].fy * temperature / mag
            }
            nodes[i].x = nodes[i].x + forces[i].fx
            nodes[i].y = nodes[i].y + forces[i].fy
            i = i + 1
        }

        temperature = temperature * 0.95
        iter = iter + 1
    }

    // Display result
    print("Layout complete. Final positions:\n")
    i = 0
    while i < n_nodes {
        print("  ")
        print_node_label(nodes[i].label)
        print(": (")
        print_f64(nodes[i].x)
        print(", ")
        print_f64(nodes[i].y)
        print(")\n")
        i = i + 1
    }

    // Render ASCII visualization
    print("\n")
    render_graph_ascii(&nodes, n_nodes, &edges, n_edges, 50, 15)

    print("\nPress Enter for next demo...")
    wait_for_input()
}

