fn scale_x(x: f64, min: f64, max: f64, width: i32) -> i32 with Div, Panic {
    let range = max - min
    if range <= 0.0 { return 0 }
    let t = (x - min) / range
    return (t * ((width - 1) as f64)) as i32
}

fn scale_y(y: f64, min: f64, max: f64, height: i32) -> i32 with Div, Panic {
    let range = max - min
    if range <= 0.0 { return 0 }
    let t = (y - min) / range
    return ((1.0 - t) * ((height - 1) as f64)) as i32  // Flip Y
}

fn draw_line_buffer(
    buffer: &![i32],
    width: i32, height: i32,
    x0: i32, y0: i32,
    x1: i32, y1: i32,
    ch: i32
) with Mut {
    var dx = x1 - x0
    var dy = y1 - y0
    var abs_dx = dx
    var abs_dy = dy
    if dx < 0 { abs_dx = 0 - dx }
    if dy < 0 { abs_dy = 0 - dy }

    var sx = 1
    var sy = 1
    if dx < 0 { sx = -1 }
    if dy < 0 { sy = -1 }

    var err = abs_dx - abs_dy
    var x = x0
    var y = y0

    var steps = 0
    let max_steps = abs_dx + abs_dy + 1

    while steps < max_steps {
        if x >= 0 {
            if x < width {
                if y >= 0 {
                    if y < height {
                        let idx = y * width + x
                        if idx < 1200 {
                            if buffer[idx] == 32 {  // Only draw on empty
                                buffer[idx] = ch
                            }
                        }
                    }
                }
            }
        }

        if x == x1 {
            if y == y1 {
                return
            }
        }

        let e2 = 2 * err
        if e2 > 0 - abs_dy {
            err = err - abs_dy
            x = x + sx
        }
        if e2 < abs_dx {
            err = err + abs_dx
            y = y + sy
        }

        steps = steps + 1
    }
}

fn sqrt_approx(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    var guess = x * 0.5
    var i = 0
    while i < 10 {
        guess = (guess + x / guess) * 0.5
        i = i + 1
    }
    return guess
}

fn sin_approx(x: f64) -> f64 {
    var xx = x
    while xx > 3.14159 { xx = xx - 6.28318 }
    while xx < -3.14159 { xx = xx + 6.28318 }
    let x2 = xx * xx
    let x3 = x2 * xx
    let x5 = x3 * x2
    return xx - x3 * 0.16667 + x5 * 0.00833
}

fn cos_approx(x: f64) -> f64 {
    return sin_approx(x + 1.5708)
}

