fn draw_text_wrapped(
    canvas: Canvas,
    x: i32,
    y: i32,
    text: &[i32],
    max_len: i32,
    wrap_width: i32,
    style: TextStyle
) -> Canvas with Mut, Panic, Div {
    var result = canvas
    var i = 0
    var cur_x = x
    var cur_y = y
    var chars_in_line = 0

    while i < max_len {
        let ch = text[i]
        if ch == -1 {
            return result  // End of string
        }

        // Check if we need to wrap
        if chars_in_line >= wrap_width {
            cur_x = x
            cur_y = cur_y + 1
            chars_in_line = 0
        }

        result = canvas_set_char(result, cur_x, cur_y, ch, style)
        cur_x = cur_x + 1
        chars_in_line = chars_in_line + 1
        i = i + 1
    }

    return result
}

fn digit_to_char(digit: i32) -> i32 {
    return 48 + digit  // ASCII '0' = 48
}

fn format_int(value: i32, output: &![i32]) -> i32 with Mut, Panic, Div {
    if value == 0 {
        output[0] = 48  // '0'
        output[1] = -1  // Sentinel
        return 1
    }

    // Count digits
    var temp = value
    var digit_count = 0
    while temp > 0 {
        temp = temp / 10
        digit_count = digit_count + 1
    }

    // Extract digits (right to left)
    temp = value
    var i = digit_count - 1
    while i >= 0 {
        let digit = temp % 10
        output[i] = digit_to_char(digit)
        temp = temp / 10
        i = i - 1
    }

    output[digit_count] = -1  // Sentinel
    return digit_count
}

fn draw_label(
    canvas: Canvas,
    x: i32,
    y: i32,
    text: &[i32],
    max_len: i32,
    border_color: i32,
    text_style: TextStyle
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    // Calculate label dimensions
    let text_len = string_length(text, max_len)
    let box_width = text_len + 2  // Padding
    let box_height = 3

    // Draw border (simple box with +, -, |)
    // Top edge
    var bx = 0
    while bx < box_width {
        let border_ch = if bx == 0 { 43 } else { if bx == box_width - 1 { 43 } else { 45 } }  // + or -
        let border_style = text_style_new(border_color, 0, 0, 0)
        result = canvas_set_char(result, x + bx, y, border_ch, border_style)
        bx = bx + 1
    }

    // Middle (text) - left border, text, right border
    let left_border = text_style_new(border_color, 0, 0, 0)
    result = canvas_set_char(result, x, y + 1, 124, left_border)  // |
    result = draw_text_left(result, x + 1, y + 1, text, max_len, text_style)
    result = canvas_set_char(result, x + box_width - 1, y + 1, 124, left_border)

    // Bottom edge
    bx = 0
    while bx < box_width {
        let border_ch = if bx == 0 { 43 } else { if bx == box_width - 1 { 43 } else { 45 } }
        let border_style = text_style_new(border_color, 0, 0, 0)
        result = canvas_set_char(result, x + bx, y + 2, border_ch, border_style)
        bx = bx + 1
    }

    return result
}

fn canvas_to_world_x(vp: &Viewport, px: i32) -> f64 with Mut, Panic, Div {
    let pixel_offset = px - vp.canvas_x
    let normalized = (pixel_offset as f64) / (vp.canvas_width as f64)
    return vp.x_min + normalized * (vp.x_max - vp.x_min)
}

fn canvas_to_world_y(vp: &Viewport, py: i32) -> f64 with Mut, Panic, Div {
    let pixel_offset = vp.canvas_y + vp.canvas_height - py  // Flip Y
    let normalized = (pixel_offset as f64) / (vp.canvas_height as f64)
    return vp.y_min + normalized * (vp.y_max - vp.y_min)
}

