        i = i + 1
    }

    return result
}

fn bar_new(value: f64, error: f64, color: i32, label: i32) -> Bar {
    return Bar {
        value: value,
        error: error,
        color: color,
        label_code: label
    }
}

fn bar_segment_new(value: f64, color: i32) -> BarSegment {
    return BarSegment {
        value: value,
        color: color
    }
}

fn draw_vertical_bar(
    canvas: Canvas,
    vp: &Viewport,
    x_center: f64,
    bar_width: f64,
    value: f64,
    baseline: f64,
    color: i32
) -> Canvas with Mut, Panic, Div {
    let x_left = x_center - (bar_width / 2.0)
    let x_right = x_center + (bar_width / 2.0)

    let px_left = world_to_canvas_x(vp, x_left)
    let px_right = world_to_canvas_x(vp, x_right)
    let py_baseline = world_to_canvas_y(vp, baseline)
    let py_value = world_to_canvas_y(vp, value)

    let rect_width = px_right - px_left
    let rect_height = if py_baseline > py_value {
        py_baseline - py_value
    } else {
        py_value - py_baseline
    }
    let rect_y = if py_baseline > py_value { py_value } else { py_baseline }

    return fill_rect(canvas, px_left, rect_y, rect_width, rect_height, color)
}

fn bar_chart_vertical(
    canvas: Canvas,
    vp: &Viewport,
    values: &[f64],
    colors: &[i32],
    n_bars: i32,
    bar_width: f64,
    baseline: f64
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    // Calculate spacing between bars
    let x_range = vp.x_max - vp.x_min
    let spacing = x_range / ((n_bars + 1) as f64)

    var i = 0
    while i < n_bars {
        let x_center = vp.x_min + spacing * ((i + 1) as f64)
        result = draw_vertical_bar(result, vp, x_center, bar_width, values[i], baseline, colors[i])
        i = i + 1
    }

    return result
}

fn bar_chart_vertical_epistemic(
    canvas: Canvas,
    vp: &Viewport,
    bars: &[Bar],
    n_bars: i32,
    bar_width: f64,
    baseline: f64
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    let x_range = vp.x_max - vp.x_min
    let spacing = x_range / ((n_bars + 1) as f64)

    var i = 0
    while i < n_bars {
        let x_center = vp.x_min + spacing * ((i + 1) as f64)
        let bar = bars[i]

        // Draw bar
        result = draw_vertical_bar(result, vp, x_center, bar_width, bar.value, baseline, bar.color)

        // Draw error bar (if error > 0)
        if bar.error > 0.0 {
            let error_top = bar.value + bar.error
            let error_bottom = bar.value - bar.error

            let px_center = world_to_canvas_x(vp, x_center)
            let py_top = world_to_canvas_y(vp, error_top)
            let py_bottom = world_to_canvas_y(vp, error_bottom)
            let py_value = world_to_canvas_y(vp, bar.value)

            // Vertical error line
            result = draw_vline(result, px_center, py_bottom, py_top, bar.color)

            // Top cap
            let cap_width = 2
            result = draw_hline(result, px_center - cap_width, px_center + cap_width, py_top, bar.color)

            // Bottom cap
            result = draw_hline(result, px_center - cap_width, px_center + cap_width, py_bottom, bar.color)
        }

        i = i + 1
    }

    return result
}

fn draw_horizontal_bar(
    canvas: Canvas,
    vp: &Viewport,
    y_center: f64,
    bar_height: f64,
    value: f64,
    baseline: f64,
    color: i32
) -> Canvas with Mut, Panic, Div {
    let y_bottom = y_center - (bar_height / 2.0)
    let y_top = y_center + (bar_height / 2.0)

    let py_bottom = world_to_canvas_y(vp, y_bottom)
    let py_top = world_to_canvas_y(vp, y_top)
    let px_baseline = world_to_canvas_x(vp, baseline)
    let px_value = world_to_canvas_x(vp, value)

    let rect_height = py_bottom - py_top
    let rect_width = if px_value > px_baseline {
        px_value - px_baseline
    } else {
        px_baseline - px_value
    }
    let rect_x = if px_value > px_baseline { px_baseline } else { px_value }

    return fill_rect(canvas, rect_x, py_top, rect_width, rect_height, color)
}

fn bar_chart_horizontal(
