fn bar_chart_stacked_vertical(
    canvas: Canvas,
    vp: &Viewport,
    segments_array: &[[BarSegment; 10]],
    n_segments_per_bar: &[i32],
    n_bars: i32,
    bar_width: f64
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    let x_range = vp.x_max - vp.x_min
    let spacing = x_range / ((n_bars + 1) as f64)

    var bar_idx = 0
    while bar_idx < n_bars {
        let x_center = vp.x_min + spacing * ((bar_idx + 1) as f64)
        var cumulative_value = 0.0

        var seg_idx = 0
        let n_segs = n_segments_per_bar[bar_idx]
        while seg_idx < n_segs {
            let segment = segments_array[bar_idx][seg_idx]
            let bottom = cumulative_value
            let top = cumulative_value + segment.value

            result = draw_vertical_bar(result, vp, x_center, bar_width, top, bottom, segment.color)

            cumulative_value = top
            seg_idx = seg_idx + 1
        }

        bar_idx = bar_idx + 1
    }

    return result
}

fn find_min_max(data: &[f64], n_data: i32) -> (f64, f64) with Mut, Panic, Div {
    if n_data == 0 {
        return (0.0, 1.0)
    }

    var min_val = data[0]
    var max_val = data[0]

    var i = 1
    while i < n_data {
        if data[i] < min_val {
            min_val = data[i]
        }
        if data[i] > max_val {
            max_val = data[i]
        }
        i = i + 1
    }

    return (min_val, max_val)
}

fn compute_bins(data: &[f64], n_data: i32, n_bins: i32) -> BinData with Mut, Panic, Div {
    var result = bin_data_empty()
    result.n_bins = n_bins

    if n_data == 0 || n_bins == 0 {
        return result
    }

    // Find data range
    let min_max = find_min_max(data, n_data)
    let min_val = min_max.0
    let max_val = min_max.1
    let range = max_val - min_val

    // Handle edge case: all values are the same
    let actual_range = if range < 0.0001 { 1.0 } else { range }

    // Create bin edges
    var i = 0
    while i <= n_bins {
        result.bin_edges[i] = min_val + ((i as f64) / (n_bins as f64)) * actual_range
        i = i + 1
    }

    // Count data points in each bin
    var data_idx = 0
    while data_idx < n_data {
        let value = data[data_idx]

        // Find which bin this value belongs to
        var bin_idx = 0
        var found = 0
        while bin_idx < n_bins && found == 0 {
            let bin_left = result.bin_edges[bin_idx]
            let bin_right = result.bin_edges[bin_idx + 1]

            // Check if value is in this bin [left, right)
            // Last bin includes right edge
            let in_bin = if bin_idx == n_bins - 1 {
                if value >= bin_left && value <= bin_right { 1 } else { 0 }
            } else {
                if value >= bin_left && value < bin_right { 1 } else { 0 }
            }

            if in_bin == 1 {
                result.bin_counts[bin_idx] = result.bin_counts[bin_idx] + 1
                result.total_count = result.total_count + 1
                found = 1
            }

            bin_idx = bin_idx + 1
        }

        data_idx = data_idx + 1
    }

    return result
}

fn histogram(
    canvas: Canvas,
    vp: &Viewport,
    bin_data: &BinData,
    color: i32,
    fill: i32  // 0=outline, 1=filled
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    var i = 0
    while i < bin_data.n_bins {
        let bin_left = bin_data.bin_edges[i]
        let bin_right = bin_data.bin_edges[i + 1]
        let count = bin_data.bin_counts[i]

        // Convert to canvas coordinates
        let px_left = world_to_canvas_x(vp, bin_left)
        let px_right = world_to_canvas_x(vp, bin_right)
        let py_baseline = world_to_canvas_y(vp, 0.0)
        let py_top = world_to_canvas_y(vp, count as f64)

        let bar_width = px_right - px_left
        let bar_height = py_baseline - py_top

        if fill == 1 {
            result = fill_rect(result, px_left, py_top, bar_width, bar_height, color)
        } else {
            // Draw outline only
            result = draw_hline(result, px_left, px_right - 1, py_top, color)
            result = draw_vline(result, px_left, py_top, py_baseline, color)
            result = draw_vline(result, px_right - 1, py_top, py_baseline, color)
        }

        i = i + 1
    }

    return result
}

fn histogram_overlay(
    canvas: Canvas,
    vp: &Viewport,
    distributions: &[BinData],
    colors: &[i32],
    n_distributions: i32
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    // Draw each histogram as outline (not filled) so they're visible when overlapping
    var i = 0
    while i < n_distributions {
        result = histogram(result, vp, &distributions[i], colors[i], 0)
        i = i + 1
    }

    return result
}

fn value_to_grayscale(normalized: f64) -> i32 {
    if normalized < 0.25 {
        return COLOR_BLACK()
    }
    if normalized < 0.5 {
        return COLOR_BRIGHT_BLACK()
    }
    if normalized < 0.75 {
        return COLOR_WHITE()
    }
    return COLOR_BRIGHT_WHITE()
}

fn value_to_temperature(normalized: f64) -> i32 {
    if normalized < 0.2 {
        return COLOR_BLUE()           // Very cold
    }
    if normalized < 0.4 {
        return COLOR_CYAN()           // Cold
    }
    if normalized < 0.6 {
        return COLOR_GREEN()          // Warm
    }
    if normalized < 0.8 {
        return COLOR_YELLOW()         // Hot
    }
    return COLOR_RED()                 // Very hot
}

fn value_to_rainbow(normalized: f64) -> i32 {
    if normalized < 0.16 {
        return COLOR_MAGENTA()
    }
    if normalized < 0.33 {
        return COLOR_BLUE()
    }
    if normalized < 0.5 {
        return COLOR_CYAN()
    }
    if normalized < 0.66 {
        return COLOR_GREEN()
    }
    if normalized < 0.83 {
        return COLOR_YELLOW()
    }
    return COLOR_RED()
}

fn value_to_color(value: f64, min_val: f64, max_val: f64, colormap: i32) -> i32 with Div, Panic {
    let range = max_val - min_val
    let normalized = if range < 0.0001 {
        0.5
    } else {
        (value - min_val) / range
    }

    // Clamp to [0, 1]
    let clamped = if normalized < 0.0 {
        0.0
    } else { if normalized > 1.0 {
        1.0
    } else {
        normalized
    }}

    if colormap == COLORMAP_GRAYSCALE() {
        return value_to_grayscale(clamped)
    }
    if colormap == COLORMAP_TEMPERATURE() {
        return value_to_temperature(clamped)
    }
    if colormap == COLORMAP_RAINBOW() {
        return value_to_rainbow(clamped)
    }

    return COLOR_WHITE()
}

fn fill_rect(canvas: Canvas, x: i32, y: i32, width: i32, height: i32, ch: i32, color: i32) -> Canvas with Mut, Panic, Div {
    var result = canvas

    var row = 0
    while row < height {
        var col = 0
        while col < width {
            result = canvas_set_pixel(result, x + col, y + row, ch, color)
            col = col + 1
        }
        row = row + 1
    }

    return result
}

fn find_grid_min_max(grid: &[f64], size: i32) -> (f64, f64) with Mut, Panic, Div {
    if size == 0 {
        return (0.0, 1.0)
    }

    var min_val = grid[0]
    var max_val = grid[0]

    var i = 1
    while i < size {
        if grid[i] < min_val {
            min_val = grid[i]
        }
        if grid[i] > max_val {
            max_val = grid[i]
        }
        i = i + 1
    }

    return (min_val, max_val)
}

fn heatmap(
    canvas: Canvas,
    vp: &Viewport,
    grid: &[f64],
    grid_width: i32,
    grid_height: i32,
    min_val: f64,
    max_val: f64,
    colormap: i32
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    let canvas_width = vp.canvas_width
    let canvas_height = vp.canvas_height

    // Calculate cell sizes
    let cell_width = canvas_width / grid_width
    let cell_height = canvas_height / grid_height

    var row = 0
    while row < grid_height {
        var col = 0
        while col < grid_width {
            let grid_idx = row * grid_width + col
            let value = grid[grid_idx]
            let color = value_to_color(value, min_val, max_val, colormap)

            // Calculate canvas position
            let px = vp.canvas_x + col * cell_width
            let py = vp.canvas_y + row * cell_height

            // Draw filled rectangle for this cell
            result = fill_rect(result, px, py, cell_width, cell_height, 9608, color)

            col = col + 1
        }
        row = row + 1
    }

    return result
}

fn heatmap_auto(
    canvas: Canvas,
    vp: &Viewport,
    grid: &[f64],
    grid_width: i32,
    grid_height: i32,
    colormap: i32
) -> Canvas with Mut, Panic, Div {
    let total_size = grid_width * grid_height
    let min_max = find_grid_min_max(grid, total_size)
    let min_val = min_max.0
    let max_val = min_max.1

    return heatmap(canvas, vp, grid, grid_width, grid_height, min_val, max_val, colormap)
}

fn draw_colorbar(
    canvas: Canvas,
    x: i32,
    y: i32,
    width: i32,
    height: i32,
    min_val: f64,
    max_val: f64,
    colormap: i32
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    var i = 0
    while i < height {
        // Calculate normalized value for this row (bottom to top)
        let normalized = (i as f64) / (height as f64)
        let value = min_val + normalized * (max_val - min_val)
        let color = value_to_color(value, min_val, max_val, colormap)

        // Draw horizontal bar for this color level
        let bar_y = y + height - i - 1  // Flip Y to go bottom to top
        var j = 0
        while j < width {
            result = canvas_set_pixel(result, x + j, bar_y, 9608, color)
            j = j + 1
        }

        i = i + 1
    }

    return result
}

fn heatmap_with_colorbar(
    canvas: Canvas,
    vp: &Viewport,
    grid: &[f64],
    grid_width: i32,
    grid_height: i32,
    colormap: i32,
    colorbar_x: i32,
    colorbar_y: i32
) -> Canvas with Mut, Panic, Div {
    var result = canvas

    // Draw heatmap
    let total_size = grid_width * grid_height
    let min_max = find_grid_min_max(grid, total_size)
    let min_val = min_max.0
    let max_val = min_max.1

    result = heatmap(result, vp, grid, grid_width, grid_height, min_val, max_val, colormap)

    // Draw colorbar
    result = draw_colorbar(result, colorbar_x, colorbar_y, 3, 20, min_val, max_val, colormap)

    return result
}

fn vec3d_new(x: f64, y: f64, z: f64) -> Vec3D {
    return Vec3D { x: x, y: y, z: z }
}

fn vec3d_zero() -> Vec3D {
    return Vec3D { x: 0.0, y: 0.0, z: 0.0 }
}

fn vec3d_add(a: &Vec3D, b: &Vec3D) -> Vec3D {
    return Vec3D {
        x: a.x + b.x,
        y: a.y + b.y,
        z: a.z + b.z
    }
}

fn vec3d_sub(a: &Vec3D, b: &Vec3D) -> Vec3D {
    return Vec3D {
        x: a.x - b.x,
        y: a.y - b.y,
        z: a.z - b.z
    }
}

fn vec3d_scale(v: &Vec3D, s: f64) -> Vec3D {
    return Vec3D {
        x: v.x * s,
        y: v.y * s,
        z: v.z * s
    }
}

fn vec3d_dot(a: &Vec3D, b: &Vec3D) -> f64 {
    return a.x * b.x + a.y * b.y + a.z * b.z
}

fn vec3d_cross(a: &Vec3D, b: &Vec3D) -> Vec3D {
    return Vec3D {
        x: a.y * b.z - a.z * b.y,
        y: a.z * b.x - a.x * b.z,
        z: a.x * b.y - a.y * b.x
    }
}

fn vec3d_magnitude(v: &Vec3D) -> f64 with Panic {
    return sqrt(v.x * v.x + v.y * v.y + v.z * v.z)
}

fn vec3d_normalize(v: &Vec3D) -> Vec3D with Div, Panic {
    let mag = vec3d_magnitude(v)
    if mag < 0.0001 {
        return vec3d_zero()
    }
    return vec3d_scale(v, 1.0 / mag)
}

fn vec2d_new(x: f64, y: f64) -> Vec2D {
    return Vec2D { x: x, y: y }
}

fn isometric_project(p: &Vec3D) -> Vec2D {
    let cos30 = 0.866025403784  // sqrt(3)/2
    let sin30 = 0.5

    let screen_x = (p.x - p.y) * cos30
    let screen_y = (p.x + p.y) * sin30 - p.z

    return vec2d_new(screen_x, screen_y)
}

fn isometric_project_scaled(p: &Vec3D, scale: f64) -> Vec2D {
    let cos30 = 0.866025403784
    let sin30 = 0.5

    let screen_x = (p.x - p.y) * cos30 * scale
    let screen_y = ((p.x + p.y) * sin30 - p.z) * scale

    return vec2d_new(screen_x, screen_y)
}

fn perspective_project(p: &Vec3D, focal_length: f64) -> Vec2D with Div {
    let z_adjusted = focal_length + p.z

    // Avoid division by zero
    if z_adjusted < 0.1 {
        return vec2d_new(p.x * 10.0, p.y * 10.0)
    }

    let scale_factor = focal_length / z_adjusted
    return vec2d_new(p.x * scale_factor, p.y * scale_factor)
}

fn perspective_project_clipped(p: &Vec3D, focal_length: f64) -> Vec2D with Div, Panic {
    let z_adjusted = focal_length + p.z

    // Clip points behind camera
    if z_adjusted <= 0.0 {
        return vec2d_new(0.0, 0.0)
    }

    let scale_factor = focal_length / z_adjusted
    return vec2d_new(p.x * scale_factor, p.y * scale_factor)
}

fn rotate_x(p: &Vec3D, angle_rad: f64) -> Vec3D with Panic {
    let c = cos(angle_rad)
    let s = sin(angle_rad)

    return Vec3D {
        x: p.x,
        y: p.y * c - p.z * s,
        z: p.y * s + p.z * c
    }
}

fn rotate_y(p: &Vec3D, angle_rad: f64) -> Vec3D with Panic {
    let c = cos(angle_rad)
    let s = sin(angle_rad)

    return Vec3D {
        x: p.x * c + p.z * s,
        y: p.y,
        z: -p.x * s + p.z * c
    }
}

fn rotate_z(p: &Vec3D, angle_rad: f64) -> Vec3D with Panic {
    let c = cos(angle_rad)
    let s = sin(angle_rad)

    return Vec3D {
        x: p.x * c - p.y * s,
        y: p.x * s + p.y * c,
        z: p.z
    }
}

fn rotate_xyz(p: &Vec3D, rx: f64, ry: f64, rz: f64) -> Vec3D with Panic {
    var result = rotate_x(p, rx)
    result = rotate_y(&result, ry)
    result = rotate_z(&result, rz)
    return result
}

fn rotate_euler(p: &Vec3D, rx: f64, ry: f64, rz: f64, order: i32) -> Vec3D with Panic {
    if order == 0 {
        // XYZ
        var result = rotate_x(p, rx)
        result = rotate_y(&result, ry)
        result = rotate_z(&result, rz)
        return result
    } else { if order == 1 {
        // XZY
        var result = rotate_x(p, rx)
        result = rotate_z(&result, rz)
        result = rotate_y(&result, ry)
        return result
    } else { if order == 2 {
        // YXZ
        var result = rotate_y(p, ry)
        result = rotate_x(&result, rx)
        result = rotate_z(&result, rz)
        return result
    } else { if order == 3 {
        // YZX
        var result = rotate_y(p, ry)
        result = rotate_z(&result, rz)
        result = rotate_x(&result, rx)
        return result
    } else { if order == 4 {
        // ZXY
        var result = rotate_z(p, rz)
        result = rotate_x(&result, rx)
        result = rotate_y(&result, ry)
        return result
    } else {
        // ZYX (default)
        var result = rotate_z(p, rz)
        result = rotate_y(&result, ry)
        result = rotate_x(&result, rx)
        return result
    }}}}}
}

fn world_to_camera(
    p: &Vec3D,
    camera_pos: &Vec3D,
    camera_target: &Vec3D,
    camera_up: &Vec3D
) -> Vec3D with Div, Panic {
    // Compute camera basis vectors
    let forward = vec3d_normalize(&vec3d_sub(camera_target, camera_pos))
    let right = vec3d_normalize(&vec3d_cross(&forward, camera_up))
    let up = vec3d_cross(&right, &forward)

    // Translate point to camera space
    let translated = vec3d_sub(p, camera_pos)

    // Project onto camera basis
    return Vec3D {
        x: vec3d_dot(&translated, &right),
        y: vec3d_dot(&translated, &up),
        z: vec3d_dot(&translated, &forward)
    }
}

fn lambertian_shading(normal: &Vec3D, light_dir: &Vec3D) -> f64 {
    let intensity = vec3d_dot(normal, light_dir)

    // Clamp to [0, 1]
    if intensity < 0.0 {
        return 0.0
    }
    if intensity > 1.0 {
        return 1.0
    }
    return intensity
}

fn triangle_normal(p1: &Vec3D, p2: &Vec3D, p3: &Vec3D) -> Vec3D with Div, Panic {
    let edge1 = vec3d_sub(p2, p1)
    let edge2 = vec3d_sub(p3, p1)
    let normal = vec3d_cross(&edge1, &edge2)
    return vec3d_normalize(&normal)
}

fn deg_to_rad(deg: f64) -> f64 {
    return deg * 0.0174532925199  // deg * PI / 180
}

fn rad_to_deg(rad: f64) -> f64 {
    return rad * 57.2957795131  // rad * 180 / PI
}

fn vec3d_lerp(a: &Vec3D, b: &Vec3D, t: f64) -> Vec3D {
    return Vec3D {
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t,
        z: a.z + (b.z - a.z) * t
    }
}

fn vec3d_distance(a: &Vec3D, b: &Vec3D) -> f64 with Panic {
    let dx = b.x - a.x
    let dy = b.y - a.y
    let dz = b.z - a.z
    return sqrt(dx * dx + dy * dy + dz * dz)
}

fn print_f64(x: f64) with IO {
    // Simple conversion - just print the value
    // Note: Sounio doesn't have built-in f64 -> string conversion yet
    // This is a placeholder that will print the raw value
    if x < 0.0 {
        print("-")
        print_f64_unsigned(0.0 - x)
    } else {
        print_f64_unsigned(x)
    }
}

fn print_f64_unsigned(x: f64) with IO, Div, Panic {
    // Convert to integer part
    let int_part = x as i32
    print_i32(int_part)

    // Print decimal point
    print(".")

    // Get fractional part
    let frac = x - (int_part as f64)
    let scaled = (frac * 1000.0) as i32

    // Print 3 decimal places
    if scaled < 100 {
        print("0")
    }
    if scaled < 10 {
        print("0")
    }
    print_i32(scaled)
}

fn print_i32_unsigned(x: i32) with IO, Div, Panic {
    if x == 0 {
        return
    }

    let digit = x % 10
    let rest = x / 10

    if rest > 0 {
        print_i32_unsigned(rest)
    }

    // Print digit as character
    let ch = 48 + digit  // '0' is ASCII 48
    print_char(ch)
}

