    return c
}

fn animation_state_new(max_frames: i32, fps: i32) -> AnimationState with Panic, Div {
    let frame_delay = if fps > 0 {
        1000 / fps
    } else {
        33  // Default ~30 FPS
    }

    return AnimationState {
        frame: 0,
        max_frames: max_frames,
        frame_delay_ms: frame_delay,
        running: 1,
        loop_mode: 0,
        fps_target: fps,
        elapsed_frames: 0
    }
}

fn animation_state_infinite(fps: i32) -> AnimationState with Panic, Div {
    return animation_state_new(0, fps)
}

fn animation_state_looping(max_frames: i32, fps: i32) -> AnimationState with Panic, Div, Mut {
    var state = animation_state_new(max_frames, fps)
    state.loop_mode = 1
    return state
}

fn animation_init() with IO {
    print("\x1b[2J")      // Clear screen
    print("\x1b[H")       // Home cursor
    print("\x1b[?25l")    // Hide cursor
}

fn animation_cleanup() with IO {
    print("\x1b[?25h")    // Show cursor
    print("\x1b[0m")      // Reset colors
    print("\n")
}

fn animation_begin_frame() with IO {
    print("\x1b[H")       // Home cursor (don't clear to avoid flicker)
}

fn animation_end_frame(state: &!AnimationState) with Mut {
    state.frame = state.frame + 1
    state.elapsed_frames = state.elapsed_frames + 1

    // Check if animation should stop
    if state.max_frames > 0 {
        if state.frame >= state.max_frames {
            if state.loop_mode == 0 {
                // Stop after max frames
                state.running = 0
            } else { if state.loop_mode == 1 {
                // Loop mode: restart
                state.frame = 0
            } else {
                // Bounce mode: reverse (not implemented yet)
                state.running = 0
            }}
        }
    }

    // TODO: Sleep for frame_delay_ms
    // This requires FFI to platform sleep function
    // For now, terminal I/O provides natural throttling
}

fn animation_should_continue(state: &AnimationState) -> i32 {
    return state.running
}

fn animation_stop(state: &!AnimationState) with Mut {
    state.running = 0
}

fn animation_restart(state: &!AnimationState) with Mut {
    state.frame = 0
    state.running = 1
}

fn animation_get_t(state: &AnimationState) -> f64 with Div, Panic {
    if state.max_frames <= 0 {
        return 0.0
    }

    return (state.frame as f64) / (state.max_frames as f64)
}

fn animation_get_progress(state: &AnimationState) -> i32 with Div, Panic {
    if state.max_frames <= 0 {
        return 0
    }

    return (state.frame * 100) / state.max_frames
}

fn animation_oscillate(state: &AnimationState) -> f64 with Div, Panic {
    let t = animation_get_t(state)
    // sin((t * 2π)) maps to [-1, 1], we want [0, 1]
    // So use: (1 + sin(2π * t - π/2)) / 2
    // Simplified: (1 - cos(2π * t)) / 2

    // For now, use triangle wave approximation
    if t < 0.5 {
        return t * 2.0
    } else {
        return 2.0 - t * 2.0
    }
}

fn anim_lerp(a: f64, b: f64, t: f64) -> f64 {
    return a + t * (b - a)
}

fn ease_out(t: f64) -> f64 {
    return t * (2.0 - t)
}

fn ease_in_out(t: f64) -> f64 {
    if t < 0.5 {
        return 2.0 * t * t
    } else {
        let s = t - 0.5
        return 0.5 + 2.0 * s * (1.0 - s)
    }
}

fn ease_bounce(t: f64) -> f64 {
    if t < 0.5 {
        return 8.0 * t * t * t * t
    } else {
        let s = t - 1.0
        return 1.0 - 8.0 * s * s * s * s
    }
}

fn emit_particle(
    sys: &!ParticleSystem,
    direction: Vec3D,
    velocity: f64,
    color: i32,
    marker: i32
) with Mut, Panic {
    // Find dead particle slot
    var i = 0
    while i < sys.max_particles {
        if sys.particles[i].alive == 0 {
            let dir_norm = vec3d_normalize(&direction)
            let vel = vec3d_scale(&dir_norm, velocity)

            sys.particles[i] = particle_new(
                sys.emit_pos,
                vel,
                color,
                marker,
                sys.particle_lifetime,
                sys.particle_mass
            )

            sys.n_particles = sys.n_particles + 1
            return
        }
        i = i + 1
    }
}

fn emit_particles(sys: &!ParticleSystem, rng_seed: &!i32) with Mut, Panic, Div {
    var i = 0
    while i < sys.emit_rate {
        // Generate random direction within spread cone
        // Simple pseudo-random using LCG
        rng_seed.val = (rng_seed.val * 1103515245 + 12345) % 2147483648
        let theta = ((rng_seed.val % 1000) as f64 / 1000.0) * sys.emit_spread

        rng_seed.val = (rng_seed.val * 1103515245 + 12345) % 2147483648
        let phi = ((rng_seed.val % 1000) as f64 / 1000.0) * 6.28318530718

        // Spherical to Cartesian
        let x = sin(theta) * cos(phi)
        let y = cos(theta)
        let z = sin(theta) * sin(phi)

        let direction = vec3d_new(x, y, z)

        // Random color
        rng_seed.val = (rng_seed.val * 1103515245 + 12345) % 2147483648
        let color = (rng_seed.val % 6) + 2  // Colors 2-7 (avoid black/white)

        emit_particle(sys, direction, sys.emit_velocity, color as i32, 9679)  // ●
        i = i + 1
    }
}

fn apply_forces(particle: &!Particle, gravity: Vec3D, wind: Vec3D, drag: f64) with Mut {
    // Reset acceleration
    particle.acc = vec3d_zero()

    // Gravity (F = m * g)
    let gravity_force = vec3d_scale(&gravity, particle.mass)
    particle.acc = vec3d_add(&particle.acc, &gravity_force)

    // Wind (constant force)
    particle.acc = vec3d_add(&particle.acc, &wind)

    // Drag (F = -drag * v)
    let drag_force = vec3d_scale(&particle.vel, 0.0 - drag)
    particle.acc = vec3d_add(&particle.acc, &drag_force)
}

fn update_particle(
    particle: &!Particle,
    dt: f64,
    gravity: Vec3D,
    wind: Vec3D,
    drag: f64
) with Mut {
    if particle.alive == 0 {
        return
    }

    // Apply forces
    apply_forces(particle, gravity, wind, drag)

    // Update velocity: v = v + a * dt
    let dv = vec3d_scale(&particle.acc, dt)
    particle.vel = vec3d_add(&particle.vel, &dv)

    // Update position: p = p + v * dt
    let dp = vec3d_scale(&particle.vel, dt)
    particle.pos = vec3d_add(&particle.pos, &dp)

    // Update lifetime
    particle.life = particle.life - dt
    if particle.life <= 0.0 {
        particle.alive = 0
    }
}

fn particle_system_update(sys: &!ParticleSystem, dt: f64) with Mut, Panic {
    var i = 0
    var alive_count = 0

    while i < sys.max_particles {
        if sys.particles[i].alive == 1 {
            update_particle(
                &!sys.particles[i],
                dt,
                sys.gravity,
                sys.wind,
                sys.drag
            )

            if sys.particles[i].alive == 1 {
                alive_count = alive_count + 1
            }
        }
        i = i + 1
    }

    sys.n_particles = alive_count
}

fn particle_system_render_2d(
    canvas: Canvas,
    sys: &ParticleSystem,
    vp: &Viewport
) -> Canvas with Mut, Panic, Div {
    var c = canvas

    var i = 0
    while i < sys.max_particles {
        let p = &sys.particles[i]

        if p.alive == 1 {
            // Project 3D position to 2D (use x, y, ignore z for now)
            let px = world_to_canvas_x(vp, p.pos.x)
            let py = world_to_canvas_y(vp, p.pos.y)

            // Fade color with age if enabled
            let color = if sys.fade_with_age == 1 {
                let age_ratio = p.life / p.max_life
                if age_ratio < 0.33 {
                    8  // Dark gray (fading out)
                } else {
                    p.color
                }
            } else {
                p.color
            }

            // Draw particle
            c = canvas_set_char(c, px, py, p.marker, color)
        }

        i = i + 1
    }

    return c
}

fn particle_system_render_3d(
    canvas: Canvas,
    sys: &ParticleSystem,
    vp: &Viewport,
    scale: f64
) -> Canvas with Mut, Panic, Div {
    var c = canvas

    var i = 0
    while i < sys.max_particles {
        let p = &sys.particles[i]

        if p.alive == 1 {
            // Isometric projection
            let projected = isometric_project_scaled(&p.pos, scale)

            let px = world_to_canvas_x(vp, projected.x)
            let py = world_to_canvas_y(vp, projected.y)

            // Fade color with age
            let color = if sys.fade_with_age == 1 {
                let age_ratio = p.life / p.max_life
                if age_ratio < 0.25 {
                    8  // Dark gray
                } else { if age_ratio < 0.5 {
                    p.color + 8  // Bright version
                } else {
                    p.color
                }}
            } else {
                p.color
            }

            // Draw particle
            c = canvas_set_char(c, px, py, p.marker, color)
        }

        i = i + 1
    }

    return c
}

fn ix(x: i32, y: i32, width: i32) -> i32 with Panic {
    return y * width + x
}

fn get_cell(grid: &[f64], x: i32, y: i32, width: i32, height: i32) -> f64 with Panic {
    if x < 0 || x >= width || y < 0 || y >= height {
        return 0.0
    }
    return grid[ix(x, y, width)]
}

fn set_cell(grid: &![f64], x: i32, y: i32, width: i32, height: i32, value: f64) with Mut, Panic {
    if x >= 0 && x < width && y >= 0 && y < height {
        grid[ix(x, y, width)] = value
    }
}

fn set_bounds_scalar(field: &![f64], width: i32, height: i32) with Mut, Panic {
    // Left and right edges
    var y = 1
    while y < height - 1 {
        field[ix(0, y, width)] = field[ix(1, y, width)]
        field[ix(width - 1, y, width)] = field[ix(width - 2, y, width)]
        y = y + 1
    }

    // Top and bottom edges
    var x = 1
    while x < width - 1 {
        field[ix(x, 0, width)] = field[ix(x, 1, width)]
        field[ix(x, height - 1, width)] = field[ix(x, height - 2, width)]
        x = x + 1
    }

    // Corners
    field[ix(0, 0, width)] = (field[ix(1, 0, width)] + field[ix(0, 1, width)]) / 2.0
    field[ix(width - 1, 0, width)] = (field[ix(width - 2, 0, width)] + field[ix(width - 1, 1, width)]) / 2.0
    field[ix(0, height - 1, width)] = (field[ix(1, height - 1, width)] + field[ix(0, height - 2, width)]) / 2.0
    field[ix(width - 1, height - 1, width)] = (field[ix(width - 2, height - 1, width)] + field[ix(width - 1, height - 2, width)]) / 2.0
}

fn set_bounds_velocity(u: &![f64], v: &![f64], width: i32, height: i32) with Mut, Panic {
    // U velocity (horizontal): reverse at left/right walls
    var y = 1
    while y < height - 1 {
        u[ix(0, y, width)] = 0.0 - u[ix(1, y, width)]
        u[ix(width - 1, y, width)] = 0.0 - u[ix(width - 2, y, width)]
        y = y + 1
    }

    // V velocity (vertical): reverse at top/bottom walls
    var x = 1
    while x < width - 1 {
        v[ix(x, 0, width)] = 0.0 - v[ix(x, 1, width)]
        v[ix(x, height - 1, width)] = 0.0 - v[ix(x, height - 2, width)]
        x = x + 1
    }
}

fn diffuse(
    current: &![f64],
    prev: &[f64],
    diff_coeff: f64,
    dt: f64,
    width: i32,
    height: i32,
    iterations: i32
) with Mut, Panic, Div {
    let a = dt * diff_coeff * ((width - 2) * (height - 2)) as f64

    var iter = 0
    while iter < iterations {
        var y = 1
        while y < height - 1 {
            var x = 1
            while x < width - 1 {
                let idx = ix(x, y, width)

                let neighbors =
                    current[ix(x - 1, y, width)] +
                    current[ix(x + 1, y, width)] +
                    current[ix(x, y - 1, width)] +
                    current[ix(x, y + 1, width)]

                current[idx] = (prev[idx] + a * neighbors) / (1.0 + 4.0 * a)

                x = x + 1
            }
            y = y + 1
        }

        set_bounds_scalar(current, width, height)
        iter = iter + 1
    }
}

fn advect(
    current: &![f64],
    prev: &[f64],
    u: &[f64],
    v: &[f64],
    dt: f64,
    width: i32,
    height: i32
) with Mut, Panic, Div {
    let dt_x = dt * (width - 2) as f64
    let dt_y = dt * (height - 2) as f64

    var y = 1
    while y < height - 1 {
        var x = 1
        while x < width - 1 {
            let idx = ix(x, y, width)

            // Backtrack position
            let x_back = (x as f64) - dt_x * u[idx]
            let y_back = (y as f64) - dt_y * v[idx]

            // Clamp to grid bounds
            let x_clamp = if x_back < 0.5 {
                0.5
            } else { if x_back > (width as f64) - 1.5 {
                (width as f64) - 1.5
            } else {
                x_back
            }}

            let y_clamp = if y_back < 0.5 {
                0.5
            } else { if y_back > (height as f64) - 1.5 {
                (height as f64) - 1.5
            } else {
                y_back
            }}

            // Bilinear interpolation
            let i0 = x_clamp as i32
            let i1 = i0 + 1
            let j0 = y_clamp as i32
            let j1 = j0 + 1

            let s1 = x_clamp - (i0 as f64)
            let s0 = 1.0 - s1
            let t1 = y_clamp - (j0 as f64)
            let t0 = 1.0 - t1

            current[idx] =
                s0 * (t0 * prev[ix(i0, j0, width)] + t1 * prev[ix(i0, j1, width)]) +
                s1 * (t0 * prev[ix(i1, j0, width)] + t1 * prev[ix(i1, j1, width)])

            x = x + 1
        }
        y = y + 1
    }

    set_bounds_scalar(current, width, height)
}

fn project(
    u: &![f64],
    v: &![f64],
    p: &![f64],    // Pressure
    div: &![f64],  // Divergence
    width: i32,
    height: i32,
    iterations: i32
) with Mut, Panic, Div {
    // Compute divergence
    var y = 1
    while y < height - 1 {
        var x = 1
        while x < width - 1 {
            let idx = ix(x, y, width)

            div[idx] = -0.5 * (
                u[ix(x + 1, y, width)] - u[ix(x - 1, y, width)] +
                v[ix(x, y + 1, width)] - v[ix(x, y - 1, width)]
            ) / (width as f64)

            p[idx] = 0.0

            x = x + 1
        }
        y = y + 1
    }

    set_bounds_scalar(div, width, height)
    set_bounds_scalar(p, width, height)

    // Solve for pressure (Gauss-Seidel)
    var iter = 0
    while iter < iterations {
        y = 1
        while y < height - 1 {
            x = 1
            while x < width - 1 {
                let idx = ix(x, y, width)

                p[idx] = (
                    div[idx] +
                    p[ix(x - 1, y, width)] +
                    p[ix(x + 1, y, width)] +
                    p[ix(x, y - 1, width)] +
                    p[ix(x, y + 1, width)]
                ) / 4.0

                x = x + 1
            }
            y = y + 1
        }

        set_bounds_scalar(p, width, height)
        iter = iter + 1
    }

    // Subtract pressure gradient from velocity
    y = 1
    while y < height - 1 {
        x = 1
        while x < width - 1 {
            let idx = ix(x, y, width)

            u[idx] = u[idx] - 0.5 * (width as f64) * (p[ix(x + 1, y, width)] - p[ix(x - 1, y, width)])
            v[idx] = v[idx] - 0.5 * (height as f64) * (p[ix(x, y + 1, width)] - p[ix(x, y - 1, width)])

            x = x + 1
        }
        y = y + 1
    }

    set_bounds_velocity(u, v, width, height)
}

fn fluid_step(fluid: &!FluidGrid) with Mut, Panic, Div {
    let width = fluid.width
    let height = fluid.height
    let dt = fluid.dt
    let visc = fluid.viscosity
    let diff = fluid.diffusion

    // Temporary arrays for projection
    var p: [f64; 2500] = [0.0; 2500]
    var div: [f64; 2500] = [0.0; 2500]

    // ========================================================================
    // Velocity Step
    // ========================================================================

    // Diffusion (viscosity)
    if visc > 0.0001 {
        diffuse(&!fluid.u, &fluid.u_prev, visc, dt, width, height, 4)
        diffuse(&!fluid.v, &fluid.v_prev, visc, dt, width, height, 4)
    }

    // Projection (incompressibility)
    project(&!fluid.u, &!fluid.v, &!p, &!div, width, height, 4)

    // Save for advection
    fluid.u_prev = fluid.u
    fluid.v_prev = fluid.v

    // Advection (self-advection of velocity)
    advect(&!fluid.u, &fluid.u_prev, &fluid.u_prev, &fluid.v_prev, dt, width, height)
    advect(&!fluid.v, &fluid.v_prev, &fluid.u_prev, &fluid.v_prev, dt, width, height)

    // Final projection
    project(&!fluid.u, &!fluid.v, &!p, &!div, width, height, 4)

    // ========================================================================
    // Density Step
    // ========================================================================

    // Diffusion
    if diff > 0.0001 {
        diffuse(&!fluid.density, &fluid.density_prev, diff, dt, width, height, 4)
        fluid.density_prev = fluid.density
    }

    // Advection
    advect(&!fluid.density, &fluid.density_prev, &fluid.u, &fluid.v, dt, width, height)
}

fn add_density(fluid: &!FluidGrid, x: i32, y: i32, amount: f64) with Mut, Panic {
    if x >= 0 && x < fluid.width && y >= 0 && y < fluid.height {
        let idx = ix(x, y, fluid.width)
        fluid.density[idx] = fluid.density[idx] + amount
    }
}

fn add_velocity(fluid: &!FluidGrid, x: i32, y: i32, vx: f64, vy: f64) with Mut, Panic {
    if x >= 0 && x < fluid.width && y >= 0 && y < fluid.height {
        let idx = ix(x, y, fluid.width)
        fluid.u[idx] = fluid.u[idx] + vx
        fluid.v[idx] = fluid.v[idx] + vy
    }
}

fn clear_density(fluid: &!FluidGrid) with Mut {
    fluid.density = [0.0; 2500]
}

fn fade_density(fluid: &!FluidGrid, fade_rate: f64) with Mut, Panic {
    var i = 0
    while i < fluid.width * fluid.height {
        fluid.density[i] = fluid.density[i] * fade_rate
        i = i + 1
    }
}

fn fluid_render(
    canvas: Canvas,
    fluid: &FluidGrid,
    vp: &Viewport,
    colormap: i32
) -> Canvas with Mut, Panic, Div {
    // Find max density for normalization
    var max_density = 0.0
    var i = 0
    while i < fluid.width * fluid.height {
        if fluid.density[i] > max_density {
            max_density = fluid.density[i]
        }
        i = i + 1
    }

    // Render using heatmap
    return heatmap(
        canvas,
        vp,
        &fluid.density,
        fluid.width,
        fluid.height,
        0.0,
        max_density,
        colormap
    )
}

fn print_f64_unsigned(x: f64) with IO, Div, Panic {
