    }

    // Build offsets
    g.adj_offset[0] = 0
    var n = 0
    while n < g.n_nodes {
        g.adj_offset[n + 1] = g.adj_offset[n] + counts[n]
        n = n + 1
    }

    // Reset counts for filling
    var c = 0
    while c < 100 {
        counts[c] = 0
        c = c + 1
    }

    // Fill adjacency list
    e = 0
    while e < g.n_edges {
        let edge = g.edges[e]
        let from = edge.from_id
