fn format_uptime(seconds: i64) -> string {
    if seconds < 60 {
        int_to_string(seconds) + "s"
    } else if seconds < 3600 {
        int_to_string(seconds / 60) + "m " + int_to_string(seconds % 60) + "s"
    } else {
        int_to_string(seconds / 3600) + "h " + 
        int_to_string((seconds % 3600) / 60) + "m"
    }
}

fn int_to_string(n: i64) -> string with Mut, Panic, Div {
    if n == 0 {
        "0"
    } else {
        let negative = n < 0
        var num = if negative { -n } else { n }
        var result = ""
        while num > 0 {
            let digit = num % 10
            let ch = 48 + digit
            result = char_from_i64(ch) + result
            num = num / 10
        }
        if negative { "-" + result } else { result }
    }
}

fn char_from_i64(n: i64) -> string with Mut, Panic {
    str_substr("0123456789", n, 1)
}

fn sed_add(a: Sedenion, b: Sedenion) -> Sedenion {
    Sedenion {
        e0: a.e0 + b.e0, e1: a.e1 + b.e1, e2: a.e2 + b.e2, e3: a.e3 + b.e3,
        e4: a.e4 + b.e4, e5: a.e5 + b.e5, e6: a.e6 + b.e6, e7: a.e7 + b.e7,
        e8: a.e8 + b.e8, e9: a.e9 + b.e9, e10: a.e10 + b.e10, e11: a.e11 + b.e11,
        e12: a.e12 + b.e12, e13: a.e13 + b.e13, e14: a.e14 + b.e14, e15: a.e15 + b.e15
    }
}

fn sed_scale(s: Sedenion, k: f32) -> Sedenion {
    Sedenion {
        e0: s.e0 * k, e1: s.e1 * k, e2: s.e2 * k, e3: s.e3 * k,
        e4: s.e4 * k, e5: s.e5 * k, e6: s.e6 * k, e7: s.e7 * k,
        e8: s.e8 * k, e9: s.e9 * k, e10: s.e10 * k, e11: s.e11 * k,
        e12: s.e12 * k, e13: s.e13 * k, e14: s.e14 * k, e15: s.e15 * k
    }
}

fn sed_norm_sq(s: Sedenion) -> f32 {
    s.e0 * s.e0 + s.e1 * s.e1 + s.e2 * s.e2 + s.e3 * s.e3 +
    s.e4 * s.e4 + s.e5 * s.e5 + s.e6 * s.e6 + s.e7 * s.e7 +
    s.e8 * s.e8 + s.e9 * s.e9 + s.e10 * s.e10 + s.e11 * s.e11 +
    s.e12 * s.e12 + s.e13 * s.e13 + s.e14 * s.e14 + s.e15 * s.e15
}

fn layer_new(in_size: i32, out_size: i32) -> SedenionLayer {
    SedenionLayer {
        weights: [sed_one(); 16],  // Initialize with identity sedenions
        bias: sed_zero(),
        input_size: in_size,
        output_size: out_size,
    }
}

fn layer_forward(layer: SedenionLayer, input: Sedenion) -> Sedenion {
    // Simplified forward pass: weight * input + bias
    let weighted = sed_mul(layer.weights[0], input)
    sed_add(weighted, layer.bias)
}

fn layer_param_count(layer: SedenionLayer) -> i64 {
    // Each sedenion weight = 16 parameters, plus 16 for bias
    let weight_params = (layer.input_size as i64) * (layer.output_size as i64)
    let bias_params = layer.output_size as i64
    weight_params + bias_params
}

fn pixel_to_sedenion(pixel: HSIPixel) -> Sedenion {
    // Direct mapping: 16 spectral bands -> 16 sedenion components
    sed(pixel.bands[0], pixel.bands[1], pixel.bands[2], pixel.bands[3],
        pixel.bands[4], pixel.bands[5], pixel.bands[6], pixel.bands[7],
        pixel.bands[8], pixel.bands[9], pixel.bands[10], pixel.bands[11],
        pixel.bands[12], pixel.bands[13], pixel.bands[14], pixel.bands[15])
}

fn make_synthetic_pixel(class_id: i32, noise: f32) -> HSIPixel {
    // Generate synthetic spectral signatures for different tissue types
    var bands: [f32; 16] = [0.0; 16]

    // Base spectral signatures per tissue class
    if class_id == 0 {
        // Normal tissue: higher reflectance in near-IR
        bands = [0.3, 0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65,
                 0.7, 0.72, 0.74, 0.75, 0.76, 0.77, 0.78, 0.8]
    } else if class_id == 1 {
        // Tumor: characteristic absorption in specific bands
        bands = [0.25, 0.28, 0.32, 0.35, 0.38, 0.4, 0.42, 0.45,
                 0.48, 0.5, 0.52, 0.53, 0.54, 0.55, 0.56, 0.58]
    } else if class_id == 2 {
        // Necrosis: low overall reflectance
        bands = [0.15, 0.18, 0.2, 0.22, 0.24, 0.26, 0.28, 0.3,
                 0.32, 0.34, 0.35, 0.36, 0.37, 0.38, 0.39, 0.4]
    } else {
        // Edema: water absorption signature
        bands = [0.4, 0.42, 0.44, 0.46, 0.48, 0.5, 0.48, 0.45,
                 0.42, 0.4, 0.38, 0.36, 0.34, 0.32, 0.3, 0.28]
    }

    HSIPixel { bands: bands, class_label: class_id }
}

fn compute_vc_dimension(param_count: i64) -> i64 {
    // VC dimension approximation for neural networks
    // Using Bartlett et al. (1998): VC ≈ O(W * L * log(W))
    // Simplified: VC ≈ param_count / 16 (sedenion packing factor)
    if param_count < 16 { 1 } else { param_count / 16 }
}

fn pac_sample_complexity(vc_dim: i64, epsilon: f64, delta: f64) -> i64 {
    // Standard PAC sample complexity bound:
    // m ≥ (4/ε) * (VC * log(12/ε) + log(2/δ))
    let vc = vc_dim as f64
    let log_eps = 2.5  // log(12/0.05) ≈ 5.5, simplified
    let log_delta = 3.7  // log(2/0.05) ≈ 3.7
    let m = (4.0 / epsilon) * (vc * log_eps + log_delta)
    (m as i64) + 1
}

fn param_efficiency_ratio(sedenion_params: i64, real_params: i64) -> f64 {
    // Sedenions pack 16 real values per parameter
    // Real-valued network needs 16x more parameters for same capacity
    (real_params as f64) / (sedenion_params as f64)
}

fn sqrt_f64(x: f64) -> f64 with Panic, Mut {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    for i in 0..20 {
        guess = (guess + x / guess) / 2.0
    }
    guess
}

fn sedenion_layer_new_inline(
    input_size: i32,
    output_size: i32,
    activation: SedenionActivation
) -> SedenionLayer with Panic, Mut {
    let total_weights = input_size * output_size
    let scale = sqrt_f64(2.0 / ((input_size + output_size) as f64)) / 4.0

    var params: [Sedenion] = []

    // Add weights
    for i in 0..total_weights {
        params = params ++ [sedenion_scale(sedenion_one(), scale as f32)]
    }

    // Add biases
    for i in 0..output_size {
        params = params ++ [sedenion_zero()]
    }

    SedenionLayer {
        params: params,
        input_size: input_size,
        output_size: output_size,
        activation: activation,
    }
}

fn sedenion_mlp_new_inline(architecture: [i32]) -> SedenionMLP with Panic, Mut {
    var layers: [SedenionLayer] = []
    let n_layers = len(architecture) - 1

    for i in 0..(n_layers as i32) {
        let in_size = architecture[i]
        let out_size = architecture[i + 1]

        // ReLU for hidden layers, None for output
        let activation: SedenionActivation = if i < (n_layers as i32) - 1 {
            SedenionActivation::ActivationReLU
        } else {
            SedenionActivation::ActivationNone
        }

        let layer = sedenion_layer_new_inline(in_size, out_size, activation)
        layers = layers ++ [layer]
    }

    SedenionMLP {
        layers: layers,
        layer_count: n_layers as i32,
    }
}

fn sedenion_layer_param_count_inline(layer: SedenionLayer) -> i64 {
    let weight_params = layer.input_size * layer.output_size * 16
    let bias_params = layer.output_size * 16
    (weight_params + bias_params) as i64
}

fn sedenion_mlp_param_count_inline(mlp: SedenionMLP) -> i64 with Panic, Mut {
    var total: i64 = 0
    for i in 0..mlp.layer_count {
        total = total + sedenion_layer_param_count_inline(mlp.layers[i])
    }
    total
}

fn generate_synthetic_hsi_sedenions(
    width: i32,
    height: i32,
    num_classes: i32
) -> (SedenionHSI, [i32]) with Panic, Mut {
    var pixels: [Sedenion] = []
    var labels: [i32] = []

    let centroids = generate_class_centroids()

    for y in 0..height {
        for x in 0..width {
            let class_id = if x < width / 2 && y < height / 2 { 0 }
                          else if x >= width / 2 && y < height / 2 { 1 }
                          else if x < width / 2 && y >= height / 2 { 2 }
                          else { 3 % num_classes }

            let pixel = centroids[class_id]
            pixels = pixels ++ [pixel]
            labels = labels ++ [class_id]
        }
    }

    let img = SedenionHSI {
        width: width,
        height: height,
        pixels: pixels,
    }

    (img, labels)
}

fn generate_class_centroids() -> [Sedenion] with Panic, Mut {
    // Normal tissue
    let normal = Sedenion {
        e0: 0.7 as f32, e1: 0.3 as f32, e2: 0.5 as f32, e3: 0.4 as f32,
        e4: 0.5 as f32, e5: 0.6 as f32, e6: 0.4 as f32, e7: 0.3 as f32,
        e8: 0.5 as f32, e9: 0.4 as f32, e10: 0.2 as f32, e11: 0.3 as f32,
        e12: 0.5 as f32, e13: 0.2 as f32, e14: 0.3 as f32, e15: 0.2 as f32,
    }

    // Tumor
    let tumor = Sedenion {
        e0: 0.4 as f32, e1: 0.7 as f32, e2: 0.6 as f32, e3: 0.5 as f32,
        e4: 0.6 as f32, e5: 0.7 as f32, e6: 0.5 as f32, e7: 0.4 as f32,
        e8: 0.6 as f32, e9: 0.5 as f32, e10: 0.4 as f32, e11: 0.4 as f32,
        e12: 0.6 as f32, e13: 0.4 as f32, e14: 0.4 as f32, e15: 0.3 as f32,
    }

    // Necrosis
    let necrosis = Sedenion {
        e0: 0.2 as f32, e1: 0.2 as f32, e2: 0.3 as f32, e3: 0.3 as f32,
        e4: 0.4 as f32, e5: 0.5 as f32, e6: 0.3 as f32, e7: 0.6 as f32,
        e8: 0.4 as f32, e9: 0.3 as f32, e10: 0.7 as f32, e11: 0.5 as f32,
        e12: 0.4 as f32, e13: 0.8 as f32, e14: 0.6 as f32, e15: 0.7 as f32,
    }

    // Edema
    let edema = Sedenion {
        e0: 0.5 as f32, e1: 0.5 as f32, e2: 0.4 as f32, e3: 0.4 as f32,
        e4: 0.5 as f32, e5: 0.5 as f32, e6: 0.6 as f32, e7: 0.4 as f32,
        e8: 0.8 as f32, e9: 0.5 as f32, e10: 0.3 as f32, e11: 0.4 as f32,
        e12: 0.8 as f32, e13: 0.3 as f32, e14: 0.4 as f32, e15: 0.3 as f32,
    }

    var centroids: [Sedenion] = []
    centroids = centroids ++ [normal]
    centroids = centroids ++ [tumor]
    centroids = centroids ++ [necrosis]
    centroids = centroids ++ [edema]
    centroids
}

