fn compare_systems(
    results_a: EpistemicBenchmarkResult,
    results_b: EpistemicBenchmarkResult,
    name_a: string,
    name_b: string
) with IO {
    print(f"\nComparing {name_a} vs {name_b}:")

    let sr_a = results_a.solve_rate
    let sr_b = results_b.solve_rate

    // P(A > B) using Beta distributions
    let prob_a_better = beta_comparison_probability(sr_a, sr_b)

    print(f"  {name_a}: {sr_a.mean()*100:.1}% ± {sqrt(sr_a.variance())*100:.1}%")
    print(f"  {name_b}: {sr_b.mean()*100:.1}% ± {sqrt(sr_b.variance())*100:.1}%")
    print(f"  P({name_a} > {name_b}): {prob_a_better*100:.1}%")

    // Interpretation
    if prob_a_better > 0.95 {
        print(f"  Conclusion: {name_a} is statistically significantly better")
    } else if prob_a_better > 0.75 {
        print(f"  Conclusion: {name_a} is likely better, but more data needed")
    } else if prob_a_better > 0.25 {
        print(f"  Conclusion: No significant difference detected")
    } else {
        print(f"  Conclusion: {name_b} is likely better")
    }
}

fn beta_comparison_probability(a: BetaConfidence, b: BetaConfidence) -> f64 {
    let n_samples = 10000
    var count = 0

    for _ in 0..n_samples {
        let sample_a = a.sample()
        let sample_b = b.sample()
        if sample_a > sample_b {
            count += 1
        }
    }

    count as f64 / n_samples as f64
}

fn puct_score(
    q_value: Knowledge<f64>,
    prior: f64,
    visit_count: i32,
    parent_visits: i32,
    config: &EpistemicMCTSConfig,
) -> f64 {
    let exploitation = q_value.mean()
    let exploration = config.c_puct * prior * sqrt(parent_visits as f64) / (1.0 + visit_count as f64)

    // KEY INNOVATION: Variance bonus drives exploration of uncertain paths
    let ignorance_bonus = config.c_ignorance * sqrt(q_value.variance())

    exploitation + exploration + ignorance_bonus
}

fn compute_solve_rate(solved: i32, total: i32) -> BetaConfidence {
    let alpha = solved as f64 + 1.0
    let beta = (total - solved) as f64 + 1.0
    BetaConfidence::from_alpha_beta(alpha, beta)
}

fn solve_problem(
    problem: &IMOProblem,
    config: &EpistemicMCTSConfig,
    timeout: Duration,
) -> ProblemResult with IO {
    let start = now()

    // Initialize proof state
    var state = ProofState::from_problem(problem)
    var mcts = EpistemicMCTS::new(state, config)

    // Run MCTS with timeout
    var solved = false
    var steps = 0

    while elapsed(start) < timeout and not solved {
        // Select action using PUCT + variance bonus
        let action = mcts.select_action()

        // Apply action and update state
        state = state.apply(action)
        steps = steps + 1

        // Check if goal reached
        if state.goal_proven() {
            solved = true
        }

        // Run more simulations
        mcts.run_simulations(config.simulations / 10)
    }

    let time = elapsed(start)
    let confidence = if solved {
        state.proof_confidence()
    } else {
        Knowledge::uncertain(0.0, 1.0)  // Maximum uncertainty
    }

    ProblemResult {
        id: problem.id.clone(),
        solved: solved,
        solve_rate: if solved {
            BetaConfidence::from_alpha_beta(9.0, 1.0)  // High confidence
        } else {
            BetaConfidence::from_alpha_beta(1.0, 9.0)  // Low confidence
        },
        proof_length: steps,
        time: time,
        confidence: confidence,
    }
}

