fn load_concrete() with IO, Mut, Div {
    var buf: [i8; 4096] = [0; 4096]
    let fd = syscall6(2, "/tmp/concrete_data.txt", 0, 0, 0, 0, 0)
    if fd < 0 { return }
    let n = syscall6(0, fd, &buf, 4095, 0, 0, 0)
    syscall6(3, fd, 0, 0, 0, 0, 0)
    var pos: i64 = 0
    while pos < n {
        if buf[pos] == 45 && buf[pos + 1] == 45 && buf[pos + 2] == 45 && buf[pos + 3] == 68 {
            while pos < n && buf[pos] != 10 { pos = pos + 1 }
            if pos < n { pos = pos + 1 }
            break
        }
        pos = pos + 1
    }
    var si = 0
    while pos < n && si < 100 {
        var fi = 0
        while fi < 9 && pos < n {
            while pos < n && buf[pos] == 32 { pos = pos + 1 }
            var ip: i64 = 0
            while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                ip = ip * 10 + ((buf[pos] - 48) as i64)
                pos = pos + 1
            }
            var frac = 0.0
            var fs = 1.0
            if pos < n && buf[pos] == 46 {
                pos = pos + 1
                while pos < n && buf[pos] >= 48 && buf[pos] <= 57 {
                    frac = frac * 10.0 + ((buf[pos] - 48) as f64)
                    fs = fs * 10.0
                    pos = pos + 1
                }
            }
            let val = (ip as f64) + frac / fs
            if fi < 8 { DX[si * 8 + fi] = (val * 100000000.0) as i64 }
            else { DYY[si] = (val * 100000000.0) as i64 }
            fi = fi + 1
        }
        while pos < n && buf[pos] != 10 { pos = pos + 1 }
        if pos < n { pos = pos + 1 }
        si = si + 1
    }
    N_LOADED = si
    print("loaded "); print_int(si); println(" samples")
}

fn mlp_init() with Mut, Div, Panic {
    var i = 0
    while i < 80 { mw_set(i, rand_normal() * 0.05); i = i + 1 }
    i = 80
    while i < 90 { mw_set(i, 0.0); i = i + 1 }
    i = 90
    while i < 100 { mw_set(i, rand_normal() * 0.05); i = i + 1 }
    mw_set(100, 0.0)
}

fn mlp_forward(si: i64) -> f64 with Mut, Div, Panic {
    var j = 0
    while j < 10 {
        var s = mw_get(80 + j)
        var fi = 0
        while fi < 8 { s = s + get_x(si, fi) * mw_get(fi * 10 + j); fi = fi + 1 }
        MZ[j] = (s * 100000000.0) as i64
        if s < 0.0 { s = 0.0 }
        MH[j] = (s * 100000000.0) as i64
        j = j + 1
    }
    var out = mw_get(100)
    j = 0
    while j < 10 { out = out + (MH[j] as f64) / 100000000.0 * mw_get(90 + j); j = j + 1 }
    out
}

fn mlp_backprop(si: i64, lr: f64) with Mut, Div, Panic {
    let err = mlp_forward(si) - get_y(si)
    var ge = 2.0 * err
    if ge > 1.0 { ge = 1.0 }
    if ge < 0.0 - 1.0 { ge = 0.0 - 1.0 }

    var j = 0
    while j < 10 {
        mw_set(90 + j, mw_get(90 + j) - lr * ge * (MH[j] as f64) / 100000000.0)
        j = j + 1
    }
    mw_set(100, mw_get(100) - lr * ge)

    j = 0
    while j < 10 {
        let zj = (MZ[j] as f64) / 100000000.0
        var dh = ge * mw_get(90 + j)
        if zj <= 0.0 { dh = 0.0 }
        if dh > 1.0 { dh = 1.0 }
        if dh < 0.0 - 1.0 { dh = 0.0 - 1.0 }
        var fi = 0
        while fi < 8 {
            mw_set(fi * 10 + j, mw_get(fi * 10 + j) - lr * dh * get_x(si, fi))
            fi = fi + 1
        }
        mw_set(80 + j, mw_get(80 + j) - lr * dh)
        j = j + 1
    }
}

fn mlp_train(nt: i64, epochs: i64, lr: f64) with Mut, Div, Panic {
    var epoch = 0
    while epoch < epochs {
        var tl = 0.0
        var si = 0
        while si < nt {
            let p = mlp_forward(si)
            let e = p - get_y(si)
            tl = tl + e * e
            mlp_backprop(si, lr)
            si = si + 1
        }
        if epoch % 50 == 0 { print("  epoch "); print_int(epoch); print(" MSE="); print(tl / (nt as f64)); print("\n") }
        epoch = epoch + 1
    }
}

fn mlp_gum_sigma(si: i64, isig: f64) -> f64 with Mut, Div, Panic {
    let nom = mlp_forward(si)
    var vout = 0.0
    var fi = 0
    while fi < 8 {
        let orig = DX[si * 8 + fi]
        let ov = (orig as f64) / 100000000.0
        DX[si * 8 + fi] = ((ov + isig) * 100000000.0) as i64
        let plus = mlp_forward(si)
        DX[si * 8 + fi] = ((ov - isig) * 100000000.0) as i64
        let minus = mlp_forward(si)
        DX[si * 8 + fi] = orig
        let dc = (plus - minus) / (2.0 * isig)
        vout = vout + dc * dc * isig * isig
        fi = fi + 1
    }
    mlp_forward(si)
    sqrt_m(vout)
}

fn run_mlp_calibration(n_train: i64, n_test: i64) with Mut, Div, Panic {
    let isig = 0.02
    MC1 = 0; MC196 = 0; MC258 = 0
    ME1 = 0; ME196 = 0; ME258 = 0
    var gs_sum = 0.0
    var es_sum = 0.0

    mens_load(0)
    var i = 0
    while i < n_test {
        let si = n_train + i
        let yt = get_y(si)
        let gp = mlp_forward(si)
        let gs = mlp_gum_sigma(si, isig)
        let ge = abs_m(gp - yt)

        var es = 0.0
        var esq = 0.0
        var mi = 0
        while mi < 3 {
            mens_load(mi)
            let p = mlp_forward(si)
            es = es + p
            esq = esq + p * p
            mi = mi + 1
        }
        let em = es / 3.0
        let ev = esq / 3.0 - em * em
        let esig = sqrt_m(ev)
        let ee = abs_m(em - yt)
        mens_load(0)

        if ge < 1.0 * gs { MC1 = MC1 + 1 }
        if ge < 1.96 * gs { MC196 = MC196 + 1 }
        if ge < 2.58 * gs { MC258 = MC258 + 1 }
        if ee < 1.0 * esig { ME1 = ME1 + 1 }
        if ee < 1.96 * esig { ME196 = ME196 + 1 }
        if ee < 2.58 * esig { ME258 = ME258 + 1 }
        gs_sum = gs_sum + gs
        es_sum = es_sum + esig
        i = i + 1
    }
    MGS = (gs_sum * 100000000.0) as i64
    MES = (es_sum * 100000000.0) as i64
}

fn estimate_pi(num_samples: usize, seed: u64) -> (f64, f64) {
    var rng = RandomGenerator::new(seed);
    var inside: usize = 0;

    for _ in 0..num_samples {
        let x = rng.next_f64();
        let y = rng.next_f64();

        // Check if point is inside unit circle
        if x * x + y * y <= 1.0 {
            inside = inside + 1;
        }
    }

    let ratio = (inside as f64) / (num_samples as f64);
    let pi_estimate = 4.0 * ratio;

    // Estimated error (based on binomial distribution)
    let error = 4.0 * (ratio * (1.0 - ratio) / (num_samples as f64)).sqrt();

    (pi_estimate, error)
}

fn run_pi_estimation(num_samples: usize, num_trials: usize, base_seed: u64) -> (f64, f64, f64) {
    var estimates: Vec<f64> = Vec::new();

    for trial in 0..num_trials {
        let seed = base_seed + (trial as u64);
        let (estimate, _) = estimate_pi(num_samples, seed);
        estimates.push(estimate);
    }

    // Calculate mean
    var sum: f64 = 0.0;
    for e in estimates.iter() {
        sum = sum + *e;
    }
    let mean = sum / (num_trials as f64);

    // Calculate standard deviation
    var var_sum: f64 = 0.0;
    for e in estimates.iter() {
        let diff = *e - mean;
        var_sum = var_sum + diff * diff;
    }
    let std_dev = (var_sum / (num_trials as f64)).sqrt();

    // Error from true pi
    let error = (mean - PI).abs();

    (mean, std_dev, error)
}

fn black_scholes(params: &OptionParams) -> f64 {
    let s = params.spot;
    let k = params.strike;
    let r = params.rate;
    let sigma = params.volatility;
    let t = params.time;

    let d1 = ((s / k).ln() + (r + sigma * sigma / 2.0) * t) / (sigma * t.sqrt());
    let d2 = d1 - sigma * t.sqrt();

    match params.option_type {
        OptionType::Call => {
            s * norm_cdf(d1) - k * (-r * t).exp() * norm_cdf(d2)
        },
        OptionType::Put => {
            k * (-r * t).exp() * norm_cdf(-d2) - s * norm_cdf(-d1)
        },
    }
}

fn monte_carlo_option(params: &OptionParams, num_paths: usize, seed: u64) -> (f64, f64) {
    var rng = RandomGenerator::new(seed);
    var payoffs: Vec<f64> = Vec::new();

    let s0 = params.spot;
    let k = params.strike;
    let r = params.rate;
    let sigma = params.volatility;
    let t = params.time;

    // Drift-adjusted for risk-neutral pricing
    let drift = (r - 0.5 * sigma * sigma) * t;
    let diffusion = sigma * t.sqrt();

    for _ in 0..num_paths {
        // Generate terminal stock price
        let z = rng.normal();
        let st = s0 * (drift + diffusion * z).exp();

        // Calculate payoff
        let payoff = match params.option_type {
            OptionType::Call => (st - k).max(0.0),
            OptionType::Put => (k - st).max(0.0),
        };

        payoffs.push(payoff);
    }

    // Discount expected payoff
    let sum: f64 = payoffs.iter().fold(0.0, |acc, x| acc + *x);
    let mean_payoff = sum / (num_paths as f64);
    let option_price = mean_payoff * (-r * t).exp();

    // Calculate standard error
    var var_sum: f64 = 0.0;
    for p in payoffs.iter() {
        let diff = *p - mean_payoff;
        var_sum = var_sum + diff * diff;
    }
    let std_dev = (var_sum / (num_paths as f64)).sqrt();
    let std_error = (std_dev / (num_paths as f64).sqrt()) * (-r * t).exp();

    (option_price, std_error)
}

fn monte_carlo_option_antithetic(params: &OptionParams, num_paths: usize, seed: u64) -> (f64, f64) {
    var rng = RandomGenerator::new(seed);
    var payoffs: Vec<f64> = Vec::new();

    let s0 = params.spot;
    let k = params.strike;
    let r = params.rate;
    let sigma = params.volatility;
    let t = params.time;

    let drift = (r - 0.5 * sigma * sigma) * t;
    let diffusion = sigma * t.sqrt();

    // Use pairs of antithetic variates
    let num_pairs = num_paths / 2;
    for _ in 0..num_pairs {
        let z = rng.normal();

        // Path 1: use z
        let st1 = s0 * (drift + diffusion * z).exp();
        // Path 2: use -z (antithetic)
        let st2 = s0 * (drift + diffusion * (-z)).exp();

        let payoff1 = match params.option_type {
            OptionType::Call => (st1 - k).max(0.0),
            OptionType::Put => (k - st1).max(0.0),
        };

        let payoff2 = match params.option_type {
            OptionType::Call => (st2 - k).max(0.0),
            OptionType::Put => (k - st2).max(0.0),
        };

        // Average of antithetic pair
        payoffs.push((payoff1 + payoff2) / 2.0);
    }

    let sum: f64 = payoffs.iter().fold(0.0, |acc, x| acc + *x);
    let mean_payoff = sum / (num_pairs as f64);
    let option_price = mean_payoff * (-r * t).exp();

    var var_sum: f64 = 0.0;
    for p in payoffs.iter() {
        let diff = *p - mean_payoff;
        var_sum = var_sum + diff * diff;
    }
    let std_dev = (var_sum / (num_pairs as f64)).sqrt();
    let std_error = (std_dev / (num_pairs as f64).sqrt()) * (-r * t).exp();

    (option_price, std_error)
}

fn calculate_var(
    positions: &Vec<Position>,
    confidence_level: f64,
    holding_period: f64,  // in days
    num_simulations: usize,
    seed: u64,
) -> (f64, f64, f64) {
    var rng = RandomGenerator::new(seed);
    var portfolio_pnls: Vec<f64> = Vec::new();

    // Calculate initial portfolio value
    var initial_value: f64 = 0.0;
    for pos in positions.iter() {
        initial_value = initial_value + pos.size * pos.price;
    }

    // Simulate portfolio P&L
    for _ in 0..num_simulations {
        var pnl: f64 = 0.0;

        // Generate correlated returns (simplified - using single factor model)
        let market_shock = rng.normal();

        for pos in positions.iter() {
            // Factor model: return = correlation * market + sqrt(1-corr^2) * idiosyncratic
            let idio_shock = rng.normal();
            let return_shock = pos.correlation * market_shock +
                              (1.0 - pos.correlation * pos.correlation).sqrt() * idio_shock;

            // Scale by volatility and holding period
            let asset_return = return_shock * pos.volatility * holding_period.sqrt();
            let position_pnl = pos.size * pos.price * asset_return;
            pnl = pnl + position_pnl;
        }

        portfolio_pnls.push(pnl);
    }

    // Sort P&Ls for quantile calculation
    portfolio_pnls.sort();

    // Calculate VaR at confidence level
    let var_index = ((1.0 - confidence_level) * (num_simulations as f64)) as usize;
    let var = -portfolio_pnls[var_index];

    // Calculate Expected Shortfall (CVaR)
    var tail_sum: f64 = 0.0;
    for i in 0..var_index {
        tail_sum = tail_sum + portfolio_pnls[i];
    }
    let es = if var_index > 0 {
        -tail_sum / (var_index as f64)
    } else {
        var
    };

    // Calculate mean P&L
    var sum: f64 = 0.0;
    for pnl in portfolio_pnls.iter() {
        sum = sum + *pnl;
    }
    let mean_pnl = sum / (num_simulations as f64);

    (var, es, mean_pnl)
}

fn init_morse() with Mut {
    // A = dot dash = 1 2
    MORSE_CODE[0] = 1; MORSE_CODE[1] = 2; MORSE_CODE[2] = 0; MORSE_CODE[3] = 0
    MORSE_LEN[0] = 2
    // B = dash dot dot dot = 2 1 1 1
    MORSE_CODE[4] = 2; MORSE_CODE[5] = 1; MORSE_CODE[6] = 1; MORSE_CODE[7] = 1
    MORSE_LEN[1] = 4
    // C = dash dot dash dot = 2 1 2 1
    MORSE_CODE[8] = 2; MORSE_CODE[9] = 1; MORSE_CODE[10] = 2; MORSE_CODE[11] = 1
    MORSE_LEN[2] = 4
    // D = dash dot dot = 2 1 1
    MORSE_CODE[12] = 2; MORSE_CODE[13] = 1; MORSE_CODE[14] = 1; MORSE_CODE[15] = 0
    MORSE_LEN[3] = 3
    // E = dot = 1
    MORSE_CODE[16] = 1; MORSE_CODE[17] = 0; MORSE_CODE[18] = 0; MORSE_CODE[19] = 0
    MORSE_LEN[4] = 1
    // F = dot dot dash dot = 1 1 2 1
    MORSE_CODE[20] = 1; MORSE_CODE[21] = 1; MORSE_CODE[22] = 2; MORSE_CODE[23] = 1
    MORSE_LEN[5] = 4
}

fn emit_letter(letter: i64, pos: i64) -> i64 with Mut {
    let base = letter * 4
    let len = MORSE_LEN[letter]
    var i = 0
    var p = pos
    while i < len {
        SEQ[p] = MORSE_CODE[base + i]
        p = p + 1
        i = i + 1
    }
    p
}

fn generate_sample() -> i64 with Mut, Div {
    // First letter class (0-5)
    let first = (rng_next() / 100) % 6
    var pos = emit_letter(first, 0)

    // How many more letters (1 or 2)
    let extra = (rng_next() / 100) % 2 + 1
    var e = 0
    while e < extra {
        SEQ[pos] = 3  // separator
        pos = pos + 1
        let next_letter = (rng_next() / 100) % 6
        pos = emit_letter(next_letter, pos)
        e = e + 1
    }
    // Pad with silence to length 25
    while pos < 25 { SEQ[pos] = 0; pos = pos + 1 }
    SEQ_LEN = 25
    first
}

fn init_model(is_cross: i64) with Mut, Div, Panic {
    // Embedding 4×8
    var i = 0
    while i < 32 { ws(i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    // A matrix
    i = 0
    while i < 64 {
        var v = ((rng_next() % 2000) as f64 - 1000.0) / 10000.0
        let row = i / 8
        let col = i - row * 8
        if row == col { v = 0.95 }
        if is_cross == 0 { if row != col { v = 0.0 } }
        ws(32 + i, v)
        i = i + 1
    }
    // B
    i = 0
    while i < 8 { ws(96 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    // Output 8×6
    i = 0
    while i < 48 { ws(104 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 152 { MOM[i] = 0; i = i + 1 }
}

fn model_step(token: i64, is_cross: i64) with Mut, Div {
    // Embed: token*8 .. token*8+7
    var inp: [f64; 8] = [0.0; 8]
    var d = 0
    while d < 8 { inp[d] = wg(token * 8 + d); d = d + 1 }

    if is_cross == 1 {
        var new_h: [f64; 8] = [0.0; 8]
        d = 0
        while d < 8 {
            var s = 0.0
            var j = 0
            while j < 8 { s = s + wg(32 + d*8 + j) * hg(j); j = j + 1 }
            s = s + wg(96 + d) * inp[d]
            if s > 5.0 { s = 5.0 }
            if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
            new_h[d] = s
            d = d + 1
        }
        d = 0
        while d < 8 { hs(d, new_h[d]); d = d + 1 }
    } else {
        d = 0
        while d < 8 {
            var s = wg(32 + d) * hg(d) + wg(96 + d) * inp[d]
            if s > 5.0 { s = 5.0 }
            if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
            hs(d, s)
            d = d + 1
        }
    }
}

fn compute_logits() with Mut, Div {
    var c = 0
    while c < 6 {
        var s = 0.0
        var d = 0
        while d < 8 { s = s + hg(d) * wg(104 + d*6 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn get_pred() -> i64 with Div {
    var best = 0
    var bv = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 6 {
        let v = (L[i] as f64) / 100000000.0
        if v > bv { bv = v; best = i }
        i = i + 1
    }
    best
}

fn update_output(tgt: i64, lr: f64) with Mut, Div, Panic {
    var mx = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 6 {
        let v = (L[i] as f64) / 100000000.0
        if v > mx { mx = v }
        i = i + 1
    }
    var probs: [f64; 6] = [0.0; 6]
    var se = 0.0
    i = 0
    while i < 6 {
        probs[i] = exp_q((L[i] as f64) / 100000000.0 - mx)
        se = se + probs[i]
        i = i + 1
    }
    i = 0
    while i < 6 { probs[i] = probs[i] / se; i = i + 1 }
    probs[tgt] = probs[tgt] - 1.0
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var c = 0
        while c < 6 {
            let idx = 104 + d*6 + c
            var g = hd * probs[c]
            if g > 0.3 { g = 0.3 }
            if g < 0.0 - 0.3 { g = 0.0 - 0.3 }
            let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            c = c + 1
        }
        d = d + 1
    }
}

fn run_model(is_cross: i64, n_epochs: i64) -> f64 with IO, Mut, Div, Panic {
    let n_train = 300

    var ep = 0
    while ep < n_epochs {
        var correct = 0
        var s = 0
        while s < n_train {
            let cls = generate_sample()
            var d = 0
            while d < 8 { H[d] = 0; d = d + 1 }
            var t = 0
            while t < SEQ_LEN {
                model_step(SEQ[t], is_cross)
                t = t + 1
            }
            compute_logits()
            if get_pred() == cls { correct = correct + 1 }
            update_output(cls, 0.01)
            s = s + 1
        }
        if ep % 10 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }

    // Evaluate on 200 fresh samples
    rng_seed(99999, 11111)
    var correct = 0
    var s = 0
    while s < 200 {
        let cls = generate_sample()
        var d = 0
        while d < 8 { H[d] = 0; d = d + 1 }
        var t = 0
        while t < SEQ_LEN { model_step(SEQ[t], is_cross); t = t + 1 }
        compute_logits()
        if get_pred() == cls { correct = correct + 1 }
        s = s + 1
    }
    let acc = (correct as f64) / 200.0 * 100.0
    print("    Eval: "); print(acc); print("%\n")
    acc
}

fn run_config(idx: i64, pad: i64) with IO, Mut, Div, Panic {
    // pad: extra silence tokens appended to each sequence
    // (stretches the sequence, tests long-range memory)
    var dl = 0
    if idx == 0 { dl = 0 }
    if idx == 1 { dl = 10 }
    if idx == 2 { dl = 20 }
    print("  --- Padding="); print_int(dl); print(" ---\n")

    print("  O-SSM:\n")
    rng_seed(55555 + idx * 1000, 77777 + idx * 1000)
    init_model(1)
    rng_seed(12345 + idx * 100, 67890 + idx * 100)
    let c_acc = run_model(1, 40)
    RES_CROSS[idx] = (c_acc * 100000000.0) as i64

    print("  Diagonal:\n")
    rng_seed(55555 + idx * 1000, 77777 + idx * 1000)
    init_model(0)
    rng_seed(12345 + idx * 100, 67890 + idx * 100)
    let d_acc = run_model(0, 40)
    RES_DIAG[idx] = (d_acc * 100000000.0) as i64
    print("\n")
}

fn fused_linear_bn_relu(
    input: [Quaternion; 16],
    weights: [Quaternion; 512],  // 16*32 weights
    bias: [Quaternion; 32],
    bn_state: [BatchNormState; 32],
    sparsity: [SparsityPattern; 32],
    use_sparse: bool,
    use_fp16: bool
) -> [Quaternion; 32] {
    var output = [Quaternion::zero(); 32]

    // Compute linear layer output
    var linear_out = [Quaternion::zero(); 32]
    var i = 0
    while i < 32 {
        var sum = bias[i]
        var j = 0
        while j < 16 {
            let prod = input[j].hamilton_product(weights[i*16 + j])
            sum = sum.add(prod)
            j = j + 1
        }
        linear_out[i] = sum
        i = i + 1
    }

    // Mixed precision: convert to FP16 if enabled
    if use_fp16 {
        var i = 0
        while i < 32 {
            linear_out[i] = linear_out[i].fp16_quantize()
            i = i + 1
        }
    }

    // Fused BatchNorm + ReLU (applied per output)
    var i = 0
    while i < 32 {
        // Normalize
        let normalized_w = bn_state[i].normalize_value(linear_out[i].w)
        let normalized_x = bn_state[i].normalize_value(linear_out[i].x)
        let normalized_y = bn_state[i].normalize_value(linear_out[i].y)
        let normalized_z = bn_state[i].normalize_value(linear_out[i].z)

        let normalized = Quaternion::new(normalized_w, normalized_x, normalized_y, normalized_z)

        // ReLU
        let activated = normalized.relu()

        // Apply sparsity if enabled
        if use_sparse {
            output[i] = if sparsity[i].mask[0] { activated } else { Quaternion::zero() }
        } else {
            output[i] = activated
        }

        i = i + 1
    }

    output
}

fn sparse_quat_matmul(
    input: [Quaternion; 16],
    weights: [Quaternion; 512],
    sparsity_mask: [SparsityPattern; 32]
) -> [Quaternion; 32] {
    var output = [Quaternion; 32]

    var i = 0
    while i < 32 {
        var sum = Quaternion::zero()
        var j = 0
        while j < 16 {
            if sparsity_mask[i].mask[j % 32] {
                let w_idx = i * 16 + j
                let prod = input[j].hamilton_product(weights[w_idx])
                sum = sum.add(prod)
            }
            j = j + 1
        }
        output[i] = sum
        i = i + 1
    }

    output
}

fn fib(n: i64) -> i64 {
    if n <= 1 { n } else { fib(n - 1) + fib(n - 2) }
}

fn deriv(f: fn(f64) -> f64, x: f64) -> f64 with Mut, Panic, Div {
    let h = 0.00000001
    (f(x + h) - f(x - h)) / (2.0 * h)
}

fn integrate(f: fn(f64) -> f64, a: f64, b: f64) -> f64 with Mut, Panic, Div {
    let n: i64 = 100
    let h = (b - a) / 100.0
    var sum = f(a) + f(b)
    var i: i64 = 1
    var x = a + h
    while i < n {
        if i % 2 == 0 { sum = sum + 2.0 * f(x) }
        else { sum = sum + 4.0 * f(x) }
        i = i + 1
        x = x + h
    }
    sum * h / 3.0
}

fn minimize(f: fn(f64) -> f64, a: f64, b: f64) -> f64 with Mut, Panic, Div {
    let resphi = 0.3819660113
    var lo = a
    var hi = b
    var x1 = lo + resphi * (hi - lo)
    var x2 = hi - resphi * (hi - lo)
    var f1 = f(x1)
    var f2 = f(x2)
    var i: i64 = 0
    while i < 100 {
        if fc_abs(hi - lo) < 0.0000000001 { return 0.5 * (lo + hi) }
        if f1 < f2 {
            hi = x2
            x2 = x1
            f2 = f1
            x1 = lo + resphi * (hi - lo)
            f1 = f(x1)
        } else {
            lo = x1
            x1 = x2
            f1 = f2
            x2 = hi - resphi * (hi - lo)
            f2 = f(x2)
        }
        i = i + 1
    }
    0.5 * (lo + hi)
}

fn f2exit(x: f64) -> i64 with Mut, Panic, Div {
    var result: i64 = 0
    var rem = if x < 0.0 { 0.0 - x } else { x }
    while rem >= 1.0 {
        rem = rem - 1.0
        result = result + 1
    }
    if x < 0.0 { 0 - result } else { result }
}

fn pk_sqrt(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    var g = x * 0.5
    if x < 1.0 { g = 1.0 }
    var i: i64 = 0
    while i < 60 { g = 0.5 * (g + x / g)
        i = i + 1 }
    g
}

fn pk_conc(t: f64, ka: f64, ke: f64, dose: f64, vd: f64) -> f64 with Mut, Panic, Div {
    let diff = ka - ke
    if pk_abs(diff) < 0.0001 { return 0.0 }
    let factor = dose * ka / (vd * diff)
    let ek = 1.0 / pk_exp_pos(ke * t)
    let ea = 1.0 / pk_exp_pos(ka * t)
    factor * (ek - ea)
}

fn jac_ka(t: f64, ka: f64, ke: f64, d: f64, v: f64) -> f64 with Mut, Panic, Div {
    let h = 0.0001
    (pk_conc(t, ka + h, ke, d, v) - pk_conc(t, ka, ke, d, v)) / h
}

fn jac_ke(t: f64, ka: f64, ke: f64, d: f64, v: f64) -> f64 with Mut, Panic, Div {
    let h = 0.0001
    (pk_conc(t, ka, ke + h, d, v) - pk_conc(t, ka, ke, d, v)) / h
}

fn fisher_aa(ka: f64, ke: f64, d: f64, v: f64) -> f64 with Mut, Panic, Div {
    let j0 = jac_ka(0.5, ka, ke, d, v)
    let j1 = jac_ka(1.0, ka, ke, d, v)
    let j2 = jac_ka(2.0, ka, ke, d, v)
    let j3 = jac_ka(4.0, ka, ke, d, v)
    let j4 = jac_ka(8.0, ka, ke, d, v)
    let j5 = jac_ka(12.0, ka, ke, d, v)
    j0 * j0 + j1 * j1 + j2 * j2 + j3 * j3 + j4 * j4 + j5 * j5
}

fn fisher_ab(ka: f64, ke: f64, d: f64, v: f64) -> f64 with Mut, Panic, Div {
    let a0 = jac_ka(0.5, ka, ke, d, v)
    let b0 = jac_ke(0.5, ka, ke, d, v)
    let a1 = jac_ka(1.0, ka, ke, d, v)
    let b1 = jac_ke(1.0, ka, ke, d, v)
    let a2 = jac_ka(2.0, ka, ke, d, v)
    let b2 = jac_ke(2.0, ka, ke, d, v)
    let a3 = jac_ka(4.0, ka, ke, d, v)
    let b3 = jac_ke(4.0, ka, ke, d, v)
    let a4 = jac_ka(8.0, ka, ke, d, v)
    let b4 = jac_ke(8.0, ka, ke, d, v)
    let a5 = jac_ka(12.0, ka, ke, d, v)
    let b5 = jac_ke(12.0, ka, ke, d, v)
    a0 * b0 + a1 * b1 + a2 * b2 + a3 * b3 + a4 * b4 + a5 * b5
}

fn fisher_bb(ka: f64, ke: f64, d: f64, v: f64) -> f64 with Mut, Panic, Div {
    let j0 = jac_ke(0.5, ka, ke, d, v)
    let j1 = jac_ke(1.0, ka, ke, d, v)
    let j2 = jac_ke(2.0, ka, ke, d, v)
    let j3 = jac_ke(4.0, ka, ke, d, v)
    let j4 = jac_ke(8.0, ka, ke, d, v)
    let j5 = jac_ke(12.0, ka, ke, d, v)
    j0 * j0 + j1 * j1 + j2 * j2 + j3 * j3 + j4 * j4 + j5 * j5
}

fn pk_fit(dose: f64, vd: f64) -> i64 with Mut, Panic, Div {
    var ka = 0.6
    var ke = 0.25
    var converged: i64 = 0
    var iter: i64 = 0
    while iter < 40 {
        if pk_abs(ka - ke) < 0.001 { ke = ke + 0.01 }
        let a11 = fisher_aa(ka, ke, dose, vd)
        let a12 = fisher_ab(ka, ke, dose, vd)
        let a22 = fisher_bb(ka, ke, dose, vd)
        let g1 = grad_ka(ka, ke, dose, vd)
        let g2 = grad_ke(ka, ke, dose, vd)
        let det = a11 * a22 - a12 * a12
        if pk_abs(det) < 0.0000000001 { break }
        var dka = 0.0 - (a22 * g1 - a12 * g2) / det
        var dke = 0.0 - (a11 * g2 - a12 * g1) / det
        let delta = pk_sqrt(dka * dka + dke * dke)
        if delta > 0.3 { dka = dka * 0.3 / delta
            dke = dke * 0.3 / delta }
        ka = ka + dka
        ke = ke + dke
        if ka < 0.01 { ka = 0.01 }
        if ke < 0.01 { ke = 0.01 }
        if delta < 0.000001 { converged = 1
            break }
        iter = iter + 1
    }
    var result: i64 = 0
    if pk_abs(ka - 0.5) / 0.5 < 0.15 { result = result + 32 }
    if pk_abs(ke - 0.2) / 0.2 < 0.15 { result = result + 16 }
    if ka > 0.3 { result = result + 8 }
    if ke > 0.1 { result = result + 4 }
    if ka < 0.8 { result = result + 2 }
    result = result + converged
    result
}

fn apply_n(f: fn(i64) -> i64, x: i64, n: i64) -> i64 with Mut, Panic, Div {
    var result = x
    var i: i64 = 0
    while i < n {
        result = f(result)
        i = i + 1
    }
    result
}

fn select_op(which: i64) -> fn(i64) -> i64 with Mut, Panic, Div {
    if which == 0 { double }
    else if which == 1 { triple }
    else if which == 2 { negate }
    else { add_one }
}

fn clustering_coefficient(adj: &[Vec<usize>]) -> f64 with Alloc {
    if adj.len() < 3 {
        return 0.0
    }

    var triangles = 0
    var triplets = 0

    var i = 0
    while i < adj.len() {
        let ki = adj[i].len()

        if ki < 2 {
            i = i + 1
            continue
        }

        // Count triangles
        var j = 0
        while j < adj[i].len() {
            let neighbor_j = adj[i][j]

            var k = j + 1
            while k < adj[i].len() {
                let neighbor_k = adj[i][k]

                // Check if neighbor_j and neighbor_k are connected
                var connected = false
                var n = 0
                while n < adj[neighbor_j].len() {
                    if adj[neighbor_j][n] == neighbor_k {
                        connected = true
                        break
                    }
                    n = n + 1
                }

                if connected {
                    triangles = triangles + 1
                }

                k = k + 1
            }

            j = j + 1
        }

        // Count possible triplets
        triplets = triplets + ki * (ki - 1) / 2

        i = i + 1
    }

    if triplets == 0 {
        return 0.0
    }

    (triangles as f64) / (triplets as f64)
}

fn configuration_model_from_graph(adj: &[Vec<usize>]) -> Vec<Vec<usize>> with IO, Alloc {
    let degrees = get_degree_sequence_from_adj(adj)
    configuration_model_from_degrees(&degrees)
}

fn get_degree_sequence_from_adj(adj: &[Vec<usize>]) -> Vec<usize> with Alloc {
    var degrees = vec_new()
    var i = 0
    while i < adj.len() {
        vec_push(&!degrees, adj[i].len())
        i = i + 1
    }
    degrees
}

fn configuration_model_from_degrees(degrees: &[usize]) -> Vec<Vec<usize>> with IO, Alloc {
    let n = degrees.len()

    // Initialize adjacency list
    var adj = vec_new()
    var i = 0
    while i < n {
        vec_push(&!adj, vec_new())
        i = i + 1
    }

    // Calculate total degree
    var total_degree = 0
    var j = 0
    while j < degrees.len() {
        total_degree = total_degree + degrees[j]
        j = j + 1
    }

    if total_degree == 0 {
        return adj
    }

    // Chung-Lu probabilistic model
    i = 0
    while i < n {
        j = i + 1
        while j < n {
            let prob = (degrees[i] as f64 * degrees[j] as f64) / (total_degree as f64)
            if prob > 0.5 {
                vec_push(&!adj[i], j)
                vec_push(&!adj[j], i)
            }
            j = j + 1
        }
        i = i + 1
    }

    adj
}

fn cliffs_delta(data1: &[f64], data2: &[f64]) -> f64 {
    if data1.len() == 0 || data2.len() == 0 {
        return 0.0
    }

    var greater = 0i64
    var less = 0i64

    var i = 0
    while i < data1.len() {
        var j = 0
        while j < data2.len() {
            if data1[i] > data2[j] {
                greater = greater + 1
            } else if data1[i] < data2[j] {
                less = less + 1
            }
            j = j + 1
        }
        i = i + 1
    }

    let total = (data1.len() * data2.len()) as i64
    ((greater - less) as f64) / (total as f64)
}

fn normal_tail_probability(z: f64) -> f64 {
    if z > 6.0 {
        return 0.0
    }
    if z < -6.0 {
        return 1.0
    }

    let p = 0.47047
    let b1 = 0.3480242
    let b2 = -0.0958798
    let t = 1.0 / (1.0 + p * z)

    let tau = t * (b1 + b2 * t * t)
    let erf_approx = 1.0 - tau * (-z * z / 2.0).exp()

    (1.0 - erf_approx) / 2.0
}

