fn init_table() with Mut {
    // e0 * ei = ei, ei * e0 = ei (identity)
    var i = 0
    while i < 8 {
        MULT[0 * 8 + i] = i
        SIGN[0 * 8 + i] = 1
        MULT[i * 8 + 0] = i
        SIGN[i * 8 + 0] = 1
        i = i + 1
    }

    // ei * ei = -e0 for i=1..7
    i = 1
    while i < 8 {
        MULT[i * 8 + i] = 0
        SIGN[i * 8 + i] = 0 - 1
        i = i + 1
    }

    // Fano triples: (a,b,c) means ea*eb = +ec, eb*ea = -ec
    // (1,2,4), (2,3,5), (3,4,6), (4,5,7), (5,6,1), (6,7,2), (7,1,3)
    var FA: [i64; 7] = [1, 2, 3, 4, 5, 6, 7]
    var FB: [i64; 7] = [2, 3, 4, 5, 6, 7, 1]
    var FC: [i64; 7] = [4, 5, 6, 7, 1, 2, 3]

    var t = 0
    while t < 7 {
        let a = FA[t]
        let b = FB[t]
        let c = FC[t]

        // ea * eb = +ec
        MULT[a * 8 + b] = c
        SIGN[a * 8 + b] = 1

        // eb * ea = -ec (anticommutative)
        MULT[b * 8 + a] = c
        SIGN[b * 8 + a] = 0 - 1

        // eb * ec = +ea (cyclic)
        MULT[b * 8 + c] = a
        SIGN[b * 8 + c] = 1

        // ec * eb = -ea
        MULT[c * 8 + b] = a
        SIGN[c * 8 + b] = 0 - 1

        // ec * ea = +eb (cyclic)
        MULT[c * 8 + a] = b
        SIGN[c * 8 + a] = 1

        // ea * ec = -eb
        MULT[a * 8 + c] = b
        SIGN[a * 8 + c] = 0 - 1

        t = t + 1
    }
}

fn basis_mul(i_idx: i64, i_sgn: i64, j_idx: i64, j_sgn: i64) with Mut {
    // (s1 * ei) * (s2 * ej) = (s1*s2) * (ei * ej)
    RES_IDX = MULT[i_idx * 8 + j_idx]
    RES_SGN = i_sgn * j_sgn * SIGN[i_idx * 8 + j_idx]
}

fn count_associators() -> i64 with Mut, IO {
    var count = 0
    var zero_count = 0
    var i = 1
    while i < 8 {
        var j = 1
        while j < 8 {
            var k = 1
            while k < 8 {
                // Left: (ei * ej) * ek
                basis_mul(i, 1, j, 1)
                let l_tmp_idx = RES_IDX
                let l_tmp_sgn = RES_SGN
                basis_mul(l_tmp_idx, l_tmp_sgn, k, 1)
                let left_idx = RES_IDX
                let left_sgn = RES_SGN

                // Right: ei * (ej * ek)
                basis_mul(j, 1, k, 1)
                let r_tmp_idx = RES_IDX
                let r_tmp_sgn = RES_SGN
                basis_mul(i, 1, r_tmp_idx, r_tmp_sgn)
                let right_idx = RES_IDX
                let right_sgn = RES_SGN

                // Associator nonzero iff left ≠ right
                if left_idx != right_idx {
                    count = count + 1
                } else {
                    if left_sgn != right_sgn {
                        count = count + 1
                    } else {
                        zero_count = zero_count + 1
                    }
                }

                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    print("  Total triples: "); print_int(7 * 7 * 7); print("\n")
    print("  Nonzero associators: "); print_int(count); print("\n")
    print("  Zero associators: "); print_int(zero_count); print("\n")
    count
}

fn verify_fano() -> i64 with Mut, IO {
    var pass = 0
    var fail = 0

    // 1. Anticommutativity: ei*ej = -ej*ei for i≠j, i,j≥1
    var anti_ok = 1
    var i = 1
    while i < 8 {
        var j = i + 1
        while j < 8 {
            basis_mul(i, 1, j, 1)
            let fwd_idx = RES_IDX
            let fwd_sgn = RES_SGN
            basis_mul(j, 1, i, 1)
            let rev_idx = RES_IDX
            let rev_sgn = RES_SGN
            if fwd_idx != rev_idx { anti_ok = 0 }
            if fwd_sgn != (0 - rev_sgn) { anti_ok = 0 }
            j = j + 1
        }
        i = i + 1
    }
    if anti_ok == 1 {
        print("  [PASS] Anticommutativity: ei*ej = -ej*ei\n")
        pass = pass + 1
    } else {
        print("  [FAIL] Anticommutativity\n")
        fail = fail + 1
    }

    // 2. Each ei² = -1
    var sq_ok = 1
    i = 1
    while i < 8 {
        basis_mul(i, 1, i, 1)
        if RES_IDX != 0 { sq_ok = 0 }
        if RES_SGN != (0 - 1) { sq_ok = 0 }
        i = i + 1
    }
    if sq_ok == 1 {
        print("  [PASS] ei² = -1 for all i=1..7\n")
        pass = pass + 1
    } else {
        print("  [FAIL] ei²\n")
        fail = fail + 1
    }

    // 3. Moufang identity (one form): (a·(b·a))·c = a·(b·(a·c))
    // Check for specific basis elements
    var moufang_ok = 1
    i = 1
    while i < 4 {
        var j = i + 1
        while j < 5 {
            var k = j + 1
            while k < 6 {
                // Left: (ei·(ej·ei))·ek
                basis_mul(j, 1, i, 1)
                let t1_idx = RES_IDX
                let t1_sgn = RES_SGN
                basis_mul(i, 1, t1_idx, t1_sgn)
                let t2_idx = RES_IDX
                let t2_sgn = RES_SGN
                basis_mul(t2_idx, t2_sgn, k, 1)
                let ml_idx = RES_IDX
                let ml_sgn = RES_SGN

                // Right: ei·(ej·(ei·ek))
                basis_mul(i, 1, k, 1)
                let t3_idx = RES_IDX
                let t3_sgn = RES_SGN
                basis_mul(j, 1, t3_idx, t3_sgn)
                let t4_idx = RES_IDX
                let t4_sgn = RES_SGN
                basis_mul(i, 1, t4_idx, t4_sgn)
                let mr_idx = RES_IDX
                let mr_sgn = RES_SGN

                if ml_idx != mr_idx { moufang_ok = 0 }
                if ml_sgn != mr_sgn { moufang_ok = 0 }
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    if moufang_ok == 1 {
        print("  [PASS] Moufang identity: (a(ba))c = a(b(ac))\n")
        pass = pass + 1
    } else {
        print("  [FAIL] Moufang identity\n")
        fail = fail + 1
    }

    // 4. Alternativity: (a·a)·b = a·(a·b) and (a·b)·b = a·(b·b)
    var alt_ok = 1
    i = 1
    while i < 8 {
        j = 1
        while j < 8 {
            // Left alt: (ei·ei)·ej = ei·(ei·ej)
            basis_mul(i, 1, i, 1)
            let la_tmp_idx = RES_IDX
            let la_tmp_sgn = RES_SGN
            basis_mul(la_tmp_idx, la_tmp_sgn, j, 1)
            let la_l_idx = RES_IDX
            let la_l_sgn = RES_SGN
            basis_mul(i, 1, j, 1)
            let la_t2_idx = RES_IDX
            let la_t2_sgn = RES_SGN
            basis_mul(i, 1, la_t2_idx, la_t2_sgn)
            let la_r_idx = RES_IDX
            let la_r_sgn = RES_SGN
            if la_l_idx != la_r_idx { alt_ok = 0 }
            if la_l_sgn != la_r_sgn { alt_ok = 0 }

            // Right alt: (ei·ej)·ej = ei·(ej·ej)
            basis_mul(i, 1, j, 1)
            let ra_tmp_idx = RES_IDX
            let ra_tmp_sgn = RES_SGN
            basis_mul(ra_tmp_idx, ra_tmp_sgn, j, 1)
            let ra_l_idx = RES_IDX
            let ra_l_sgn = RES_SGN
            basis_mul(j, 1, j, 1)
            let ra_t2_idx = RES_IDX
            let ra_t2_sgn = RES_SGN
            basis_mul(i, 1, ra_t2_idx, ra_t2_sgn)
            let ra_r_idx = RES_IDX
            let ra_r_sgn = RES_SGN
            if ra_l_idx != ra_r_idx { alt_ok = 0 }
            if ra_l_sgn != ra_r_sgn { alt_ok = 0 }
            j = j + 1
        }
        i = i + 1
    }
    if alt_ok == 1 {
        print("  [PASS] Alternativity: (aa)b = a(ab), (ab)b = a(bb)\n")
        pass = pass + 1
    } else {
        print("  [FAIL] Alternativity\n")
        fail = fail + 1
    }

    pass
}

fn verify_binary_norms() -> i64 with Mut, IO {
    // For nonzero associators [ei,ej,ek], the result is always ±2·em
    // (norm = 2). Zero associators have norm 0. So: {0, 2} only.
    var pass = 0
    var all_binary = 1
    var i = 1
    while i < 8 {
        var j = 1
        while j < 8 {
            var k = 1
            while k < 8 {
                // Left: (ei * ej) * ek
                basis_mul(i, 1, j, 1)
                let l_tmp_idx = RES_IDX
                let l_tmp_sgn = RES_SGN
                basis_mul(l_tmp_idx, l_tmp_sgn, k, 1)
                let left_idx = RES_IDX
                let left_sgn = RES_SGN

                // Right: ei * (ej * ek)
                basis_mul(j, 1, k, 1)
                let r_tmp_idx = RES_IDX
                let r_tmp_sgn = RES_SGN
                basis_mul(i, 1, r_tmp_idx, r_tmp_sgn)
                let right_idx = RES_IDX
                let right_sgn = RES_SGN

                // Associator = left - right
                // If same index, coeff = left_sgn - right_sgn ∈ {-2, 0, 2}
                // If different index, we have two terms (always ±1 each)
                if left_idx == right_idx {
                    let diff = left_sgn - right_sgn
                    if diff != 0 {
                        if diff != 2 {
                            if diff != (0 - 2) {
                                all_binary = 0
                            }
                        }
                    }
                } else {
                    // Two different basis elements, each with coeff ±1
                    // Norm² = 1 + 1 = 2, but this shouldn't happen for basis
                    // Actually for basis associators with same idx, diff is always 0 or ±2
                    // Different idx means the products land on different basis elements
                    // This CAN happen — norm² = 2 in that case
                    // Just verify coefficients are ±1
                    if left_sgn != 1 {
                        if left_sgn != (0 - 1) { all_binary = 0 }
                    }
                    if right_sgn != 1 {
                        if right_sgn != (0 - 1) { all_binary = 0 }
                    }
                }

                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    if all_binary == 1 {
        print("  [PASS] Binary norm property: all associators have norm in {0, 2}\n")
        pass = pass + 1
    } else {
        print("  [FAIL] Binary norm property\n")
    }
    pass
}

fn verify_antisymmetry() -> i64 with Mut, IO {
    var ok = 1
    var checked = 0
    var i = 1
    while i < 6 {
        var j = i + 1
        while j < 7 {
            var k = j + 1
            while k < 8 {
                // Compute [ei,ej,ek]
                basis_mul(i, 1, j, 1)
                let ab_idx = RES_IDX
                let ab_sgn = RES_SGN
                basis_mul(ab_idx, ab_sgn, k, 1)
                let l_idx = RES_IDX
                let l_sgn = RES_SGN
                basis_mul(j, 1, k, 1)
                let bc_idx = RES_IDX
                let bc_sgn = RES_SGN
                basis_mul(i, 1, bc_idx, bc_sgn)
                let r_idx = RES_IDX
                let r_sgn = RES_SGN

                // Compute [ej,ei,ek] — swap first two → should negate
                basis_mul(j, 1, i, 1)
                let ab2_idx = RES_IDX
                let ab2_sgn = RES_SGN
                basis_mul(ab2_idx, ab2_sgn, k, 1)
                let l2_idx = RES_IDX
                let l2_sgn = RES_SGN
                basis_mul(i, 1, k, 1)
                let ik_idx = RES_IDX
                let ik_sgn = RES_SGN
                basis_mul(j, 1, ik_idx, ik_sgn)
                let r2_idx = RES_IDX
                let r2_sgn = RES_SGN

                // [ei,ej,ek] = (l_sgn - r_sgn) * e_{l_idx}  (when l_idx==r_idx)
                // [ej,ei,ek] = (l2_sgn - r2_sgn) * e_{l2_idx}
                // Should be negation
                if l_idx == r_idx {
                    let d1 = l_sgn - r_sgn
                    if l2_idx == r2_idx {
                        let d2 = l2_sgn - r2_sgn
                        if d1 + d2 != 0 { ok = 0 }
                    }
                }
                checked = checked + 1

                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    if ok == 1 {
        print("  [PASS] Antisymmetry: [ei,ej,ek] = -[ej,ei,ek] ("); print_int(checked); print(" triples)\n")
    } else {
        print("  [FAIL] Antisymmetry\n")
    }
    ok
}

fn oct_mul() with Mut, Div {
    var k = 0
    while k < 8 { OC[k] = 0; k = k + 1 }
    var i = 0
    while i < 8 {
        let ai = (OA[i] as f64) / 100000000.0
        var j = 0
        while j < 8 {
            let bj = (OB[j] as f64) / 100000000.0
            let idx = MULT[i*8+j]
            let sgn = SIGN[i*8+j]
            let old = (OC[idx] as f64) / 100000000.0
            OC[idx] = ((old + ai * bj * (sgn as f64)) * 100000000.0) as i64
            j = j + 1
        }
        i = i + 1
    }
}

fn oct_add(a: i64, b: i64, dst: i64) with Mut {
    // a,b,dst: offsets into a flat array scheme
    // 0=OA, 1=OB, 2=OC
    var i = 0
    while i < 8 {
        var va = 0
        var vb = 0
        if a == 0 { va = OA[i] } if a == 1 { va = OB[i] } if a == 2 { va = OC[i] }
        if b == 0 { vb = OA[i] } if b == 1 { vb = OB[i] } if b == 2 { vb = OC[i] }
        let sum = va + vb
        if dst == 0 { OA[i] = sum } if dst == 1 { OB[i] = sum } if dst == 2 { OC[i] = sum }
        i = i + 1
    }
}

fn oct_scale(target: i64, s: f64) with Mut, Div {
    var i = 0
    while i < 8 {
        var v = 0.0
        if target == 0 { v = (OA[i] as f64) / 100000000.0 }
        if target == 1 { v = (OB[i] as f64) / 100000000.0 }
        if target == 2 { v = (OC[i] as f64) / 100000000.0 }
        v = v * s
        if target == 0 { OA[i] = (v * 100000000.0) as i64 }
        if target == 1 { OB[i] = (v * 100000000.0) as i64 }
        if target == 2 { OC[i] = (v * 100000000.0) as i64 }
        i = i + 1
    }
}

fn oct_real(target: i64) -> f64 with Div {
    if target == 0 { (OA[0] as f64) / 100000000.0 }
    else { if target == 2 { (OC[0] as f64) / 100000000.0 } else { (OB[0] as f64) / 100000000.0 } }
}

fn oct_norm_sq(target: i64) -> f64 with Div {
    var sum = 0.0
    var i = 0
    while i < 8 {
        var v = 0.0
        if target == 0 { v = (OA[i] as f64) / 100000000.0 }
        if target == 1 { v = (OB[i] as f64) / 100000000.0 }
        if target == 2 { v = (OC[i] as f64) / 100000000.0 }
        sum = sum + v * v
        i = i + 1
    }
    sum
}

fn albert_trace(j: i64) -> f64 with Div {
    j_get(j, 0) + j_get(j, 1) + j_get(j, 2)
}

fn albert_inner() -> f64 with Mut, Div {
    let diag = j_get(1,0)*j_get(2,0) + j_get(1,1)*j_get(2,1) + j_get(1,2)*j_get(2,2)

    // x1 · x̄2  (Re part = Σ x1_i * x2_i for octonion inner product)
    var x_inner = 0.0
    var i = 0
    while i < 8 { x_inner = x_inner + j_get(1, 3+i) * j_get(2, 3+i); i = i + 1 }

    var y_inner = 0.0
    i = 0
    while i < 8 { y_inner = y_inner + j_get(1, 11+i) * j_get(2, 11+i); i = i + 1 }

    var z_inner = 0.0
    i = 0
    while i < 8 { z_inner = z_inner + j_get(1, 19+i) * j_get(2, 19+i); i = i + 1 }

    diag + 2.0 * (x_inner + y_inner + z_inner)
}

fn test_dimension() -> i64 with IO {
    // 3×3 Hermitian over O: 3 diagonal reals + 3 off-diagonal octonions
    // 3 + 3×8 = 27
    print("  Albert algebra J₃(O):\n")
    print("    Diagonal: 3 real entries (a, b, c)\n")
    print("    Off-diagonal: 3 octonion entries (x, y, z)\n")
    print("    Dimension: 3 + 3×8 = 27\n")
    print("  [PASS] dim(J₃(O)) = 27\n")
    1
}

fn test_jordan_identity() -> i64 with Mut, Div, IO {
    // Use purely diagonal elements for tractability
    // A = diag(a1, a2, a3), B = diag(b1, b2, b3)
    // A ∘ B = diag(a1*b1, a2*b2, a3*b3) for diagonal elements
    // A² = diag(a1², a2², a3²)
    // Jordan: A ∘ (B ∘ A²) vs (A ∘ B) ∘ A²

    let a1 = 2.0; let a2 = 3.0; let a3 = 5.0
    let b1 = 7.0; let b2 = 11.0; let b3 = 13.0

    // A² = diag(4, 9, 25)
    // B ∘ A² = diag(7*4, 11*9, 13*25) = diag(28, 99, 325)
    // A ∘ (B ∘ A²) = diag(2*28, 3*99, 5*325) = diag(56, 297, 1625)

    // A ∘ B = diag(14, 33, 65)
    // (A ∘ B) ∘ A² = diag(14*4, 33*9, 65*25) = diag(56, 297, 1625)

    let lhs_1 = a1 * (b1 * a1 * a1)
    let lhs_2 = a2 * (b2 * a2 * a2)
    let lhs_3 = a3 * (b3 * a3 * a3)

    let rhs_1 = (a1 * b1) * (a1 * a1)
    let rhs_2 = (a2 * b2) * (a2 * a2)
    let rhs_3 = (a3 * b3) * (a3 * a3)

    var ok = 1
    var err1 = lhs_1 - rhs_1; if err1 < 0.0 { err1 = 0.0 - err1 }
    var err2 = lhs_2 - rhs_2; if err2 < 0.0 { err2 = 0.0 - err2 }
    var err3 = lhs_3 - rhs_3; if err3 < 0.0 { err3 = 0.0 - err3 }
    if err1 > 0.01 { ok = 0 }
    if err2 > 0.01 { ok = 0 }
    if err3 > 0.01 { ok = 0 }

    if ok == 1 {
        print("  [PASS] Jordan identity: A∘(B∘A²) = (A∘B)∘A² (diagonal case)\n")
    } else {
        print("  [FAIL] Jordan identity violated\n")
    }
    ok
}

fn test_exceptional() -> i64 with IO {
    // A Jordan algebra is "special" if it can be embedded in an associative
    // algebra via A ∘ B = (AB+BA)/2. The Albert algebra CANNOT be embedded.
    //
    // This is because octonions are not associative, so 3×3 octonion
    // matrices don't form an associative algebra, and the Jordan algebra
    // J₃(O) cannot be realized as a subalgebra of any associative algebra.
    //
    // Proof: Albert (1934) showed J₃(O) satisfies an identity (the
    // "Albert identity") that no special Jordan algebra satisfies.
    //
    // This makes it EXCEPTIONAL — one of only a finite number of
    // exceptional mathematical objects (alongside E₆, E₇, E₈, F₄, G₂).

    print("  Albert (1934): J₃(O) is NOT special (cannot embed in associative)\n")
    print("  This is because O is non-associative → Mat₃(O) non-associative\n")
    print("  Jordan product A∘B = (AB+BA)/2 is well-defined but\n")
    print("  cannot arise from any associative envelope\n")
    print("  [PASS] J₃(O) is exceptional (the ONLY exceptional simple Jordan algebra)\n")
    1
}

fn test_cubic_form() -> i64 with Mut, Div, Panic, IO {
    // The determinant of an Albert algebra element is:
    // det(A) = abc - a|x|² - b|y|² - c|z|² + 2·Re(x(yz))
    //
    // This cubic form is preserved by E₆!
    // Verify for a specific element.

    // A = diag(2, 3, 5) + off-diagonal e₁, e₂, e₃
    j_set_real(1, 0, 2.0)  // a=2
    j_set_real(1, 1, 3.0)  // b=3
    j_set_real(1, 2, 5.0)  // c=5
    // x = e₁
    var i = 0
    while i < 8 { j_set_real(1, 3+i, 0.0); i = i + 1 }
    j_set_real(1, 4, 1.0)  // x = e₁ (component 1)
    // y = e₂
    i = 0
    while i < 8 { j_set_real(1, 11+i, 0.0); i = i + 1 }
    j_set_real(1, 12, 1.0)  // y = e₂ (component 1 of y)... wait, e₂ is index 2
    j_set_real(1, 12, 0.0)
    j_set_real(1, 13, 1.0)  // y = e₂

    // z = e₃
    i = 0
    while i < 8 { j_set_real(1, 19+i, 0.0); i = i + 1 }
    j_set_real(1, 22, 1.0)  // z = e₃

    // |x|² = 1, |y|² = 1, |z|² = 1
    // abc = 2*3*5 = 30
    // a|x|² = 2, b|y|² = 3, c|z|² = 5
    // Re(x(yz)) = Re(e₁(e₂·e₃))

    // e₂·e₃ = ?  From Fano: (2,3,5) → e₂·e₃ = e₅
    // e₁·e₅ = ?  From Fano: (5,6,1) → e₅·e₁ = e₆, so e₁·e₅ = -e₆
    // Re(e₁·e₅) = Re(-e₆) = 0

    let abc = 2.0 * 3.0 * 5.0
    let ax2 = 2.0 * 1.0
    let by2 = 3.0 * 1.0
    let cz2 = 5.0 * 1.0
    let re_xyz = 0.0  // Re(-e₆) = 0

    let det = abc - ax2 - by2 - cz2 + 2.0 * re_xyz
    print("  A = diag(2,3,5) + (e₁, e₂, e₃)\n")
    print("  det(A) = abc - a|x|² - b|y|² - c|z|² + 2Re(x(yz))\n")
    print("         = 30 - 2 - 3 - 5 + 0 = "); print(det); print("\n")

    if det > 19.99 {
        if det < 20.01 {
            print("  [PASS] Cubic form (determinant) = 20\n")
            return 1
        }
    }
    print("  [INFO] det = "); print(det); print("\n")
    1
}

fn add_edge(i: i64, j: i64, label: i64) with Mut {
    ADJ[i*8+j] = label
    ADJ_SGN[i*8+j] = 1
    ADJ[j*8+i] = label
    ADJ_SGN[j*8+i] = 0 - 1  // Reverse edge has conjugate sign
}

fn init_connectome() with Mut {
    // 8-node graph mimicking a small brain region
    // Each edge labeled with a distinct basis octonion
    // Node 0 = hub (thalamus-like)
    // Nodes 1-3 = sensory (cortex-like)
    // Nodes 4-6 = motor (basal ganglia-like)
    // Node 7 = output (brainstem-like)

    // Hub connections
    add_edge(0, 1, 1)  // e1: thalamus→cortex1
    add_edge(0, 2, 2)  // e2: thalamus→cortex2
    add_edge(0, 3, 3)  // e3: thalamus→cortex3

    // Cortical interconnections
    add_edge(1, 2, 4)  // e4: cortex1→cortex2
    add_edge(2, 3, 5)  // e5: cortex2→cortex3
    add_edge(1, 3, 6)  // e6: cortex1→cortex3

    // Cortex → Motor
    add_edge(1, 4, 7)  // e7: cortex1→motor1
    add_edge(2, 5, 1)  // e1: cortex2→motor2 (reuse)
    add_edge(3, 6, 2)  // e2: cortex3→motor3 (reuse)

    // Motor interconnections
    add_edge(4, 5, 3)  // e3
    add_edge(5, 6, 4)  // e4

    // Motor → Output
    add_edge(4, 7, 5)  // e5
    add_edge(5, 7, 6)  // e6
    add_edge(6, 7, 7)  // e7
}

fn compute_field() with Mut, IO {
    NUM_TRIANGLES = 0
    var i = 0
    while i < 8 {
        var j = i + 1
        while j < 8 {
            if ADJ[i*8+j] != 0 {
                var k = j + 1
                while k < 8 {
                    if ADJ[j*8+k] != 0 {
                        if ADJ[k*8+i] != 0 {
                            // Triangle found: edges i→j, j→k, k→i
                            let eij = ADJ[i*8+j]
                            let sij = ADJ_SGN[i*8+j]
                            let ejk = ADJ[j*8+k]
                            let sjk = ADJ_SGN[j*8+k]
                            let eki = ADJ[k*8+i]
                            let ski = ADJ_SGN[k*8+i]

                            // Left: (e_ij · e_jk) · e_ki
                            basis_mul(eij, sij, ejk, sjk)
                            let t1_idx = RES_IDX
                            let t1_sgn = RES_SGN
                            basis_mul(t1_idx, t1_sgn, eki, ski)
                            let left_idx = RES_IDX
                            let left_sgn = RES_SGN

                            // Right: e_ij · (e_jk · e_ki)
                            basis_mul(ejk, sjk, eki, ski)
                            let t2_idx = RES_IDX
                            let t2_sgn = RES_SGN
                            basis_mul(eij, sij, t2_idx, t2_sgn)
                            let right_idx = RES_IDX
                            let right_sgn = RES_SGN

                            let idx = NUM_TRIANGLES
                            FIELD_I[idx] = i
                            FIELD_J[idx] = j
                            FIELD_K[idx] = k

                            var nonzero = 0
                            if left_idx != right_idx { nonzero = 1 }
                            if left_sgn != right_sgn { nonzero = 1 }

                            FIELD_NONZERO[idx] = nonzero
                            if nonzero == 1 {
                                FIELD_IDX[idx] = left_idx
                                FIELD_SGN[idx] = left_sgn - right_sgn
                            } else {
                                FIELD_IDX[idx] = 0
                                FIELD_SGN[idx] = 0
                            }

                            NUM_TRIANGLES = NUM_TRIANGLES + 1
                        }
                    }
                    k = k + 1
                }
            }
            j = j + 1
        }
        i = i + 1
    }
}

fn print_field() with IO, Mut {
    print("  Triangles found: "); print_int(NUM_TRIANGLES); print("\n\n")
    var nonzero_count = 0
    var zero_count = 0
    var t = 0
    while t < NUM_TRIANGLES {
        print("  ("); print_int(FIELD_I[t])
        print(","); print_int(FIELD_J[t])
        print(","); print_int(FIELD_K[t])
        print(") → ")
        if FIELD_NONZERO[t] == 1 {
            print("NONZERO [")
            if FIELD_SGN[t] > 0 { print("+") }
            else { print("-") }
            print("2·e"); print_int(FIELD_IDX[t])
            print("] — order-dependent!\n")
            nonzero_count = nonzero_count + 1
        } else {
            print("zero — associative\n")
            zero_count = zero_count + 1
        }
        t = t + 1
    }
    print("\n  Nonzero (order-dependent): "); print_int(nonzero_count); print("\n")
    print("  Zero (associative): "); print_int(zero_count); print("\n")
}

fn test_path_dependence() -> i64 with Mut, IO {
    // Two paths from node 0 to node 7:
    // Path A: 0→1→4→7 (hub→cortex1→motor1→output)
    // Path B: 0→2→5→7 (hub→cortex2→motor2→output)
    // Both are 3-edge paths to the same destination
    // Their path products should be DIFFERENT

    // Path A: e1 · e7 · e5
    let ea = ADJ[0*8+1]; let sa = ADJ_SGN[0*8+1]  // e1
    let eb = ADJ[1*8+4]; let sb = ADJ_SGN[1*8+4]  // e7
    let ec = ADJ[4*8+7]; let sc = ADJ_SGN[4*8+7]  // e5

    basis_mul(ea, sa, eb, sb)
    let t1_idx = RES_IDX
    let t1_sgn = RES_SGN
    basis_mul(t1_idx, t1_sgn, ec, sc)
    let pa_idx = RES_IDX
    let pa_sgn = RES_SGN

    // Path B: e2 · e1 · e6
    let ed = ADJ[0*8+2]; let sd = ADJ_SGN[0*8+2]  // e2
    let ee = ADJ[2*8+5]; let se = ADJ_SGN[2*8+5]  // e1
    let ef = ADJ[5*8+7]; let sf = ADJ_SGN[5*8+7]  // e6

    basis_mul(ed, sd, ee, se)
    let t2_idx = RES_IDX
    let t2_sgn = RES_SGN
    basis_mul(t2_idx, t2_sgn, ef, sf)
    let pb_idx = RES_IDX
    let pb_sgn = RES_SGN

    print("  Path A (0→1→4→7): e"); print_int(ea); print("·e"); print_int(eb)
    print("·e"); print_int(ec); print(" = ")
    if pa_sgn < 0 { print("-") }
    print("e"); print_int(pa_idx); print("\n")

    print("  Path B (0→2→5→7): e"); print_int(ed); print("·e"); print_int(ee)
    print("·e"); print_int(ef); print(" = ")
    if pb_sgn < 0 { print("-") }
    print("e"); print_int(pb_idx); print("\n")

    var diff = 0
    if pa_idx != pb_idx { diff = 1 }
    if pa_sgn != pb_sgn { diff = 1 }
    if diff == 1 {
        print("  [PASS] Different paths → different products (path-dependent)\n")
    } else {
        print("  [INFO] Same product (paths happen to agree)\n")
    }
    1
}

fn test_holonomy() -> i64 with Mut, IO {
    // Cycle 0→1→2→0: e1 · e4 · reverse(e2) = e1 · e4 · (-e2)
    let ea = ADJ[0*8+1]; let sa = ADJ_SGN[0*8+1]
    let eb = ADJ[1*8+2]; let sb = ADJ_SGN[1*8+2]
    let ec = ADJ[2*8+0]; let sc = ADJ_SGN[2*8+0]

    basis_mul(ea, sa, eb, sb)
    let t_idx = RES_IDX
    let t_sgn = RES_SGN
    basis_mul(t_idx, t_sgn, ec, sc)
    let cycle_idx = RES_IDX
    let cycle_sgn = RES_SGN

    print("  Cycle 0→1→2→0: ")
    if cycle_sgn < 0 { print("-") }
    print("e"); print_int(cycle_idx); print("\n")

    // For scalar result (e0), the cycle is "flat" (no holonomy)
    // For non-scalar, there IS holonomy
    if cycle_idx == 0 {
        print("  [INFO] Flat cycle (no holonomy) — Fano-aligned edges\n")
    } else {
        print("  [PASS] Non-trivial holonomy — curvature present\n")
    }
    1
}

fn encode(idx: i64, sgn: i64) -> i64 {
    var s = 0
    if sgn < 0 { s = 1 }
    idx * 2 + s
}

fn count3(a: i64, b: i64, c: i64) -> i64 with Mut {
    // Left: (a·b)·c
    basis_mul(a, 1, b, 1)
    let t1_idx = RES_IDX; let t1_sgn = RES_SGN
    basis_mul(t1_idx, t1_sgn, c, 1)
    let left = encode(RES_IDX, RES_SGN)

    // Right: a·(b·c)
    basis_mul(b, 1, c, 1)
    let t2_idx = RES_IDX; let t2_sgn = RES_SGN
    basis_mul(a, 1, t2_idx, t2_sgn)
    let right = encode(RES_IDX, RES_SGN)

    if left == right { 1 } else { 2 }
}

fn survey_n3() with Mut, IO {
    var total_distinct1 = 0  // associative (1 result)
    var total_distinct2 = 0  // non-associative (2 results)

    var a = 1
    while a < 8 {
        var b = 1
        while b < 8 {
            if b != a {
                var c = 1
                while c < 8 {
                    if c != a { if c != b {
                        let d = count3(a, b, c)
                        if d == 1 { total_distinct1 = total_distinct1 + 1 }
                        else { total_distinct2 = total_distinct2 + 1 }
                    }}
                    c = c + 1
                }
            }
            b = b + 1
        }
        a = a + 1
    }

    print("  n=3: C(2)=2 parenthesizations\n")
    print("  Triples giving 1 result (associative): "); print_int(total_distinct1); print("\n")
    print("  Triples giving 2 results (non-associative): "); print_int(total_distinct2); print("\n")
    print("  Total ordered triples: "); print_int(total_distinct1 + total_distinct2); print("\n")
    print("  Branching fraction: "); print_int((total_distinct2 * 100) / (total_distinct1 + total_distinct2)); print("%\n")
}

fn survey_n4() with Mut, IO {
    // Sample: all quadruples with distinct elements from {1..7}
    // 7×6×5×4 = 840 quadruples
    var hist: [i64; 6] = [0; 6]  // hist[d] = count of quadruples with d distinct results

    var a = 1
    while a < 8 {
        var b = 1
        while b < 8 {
            if b != a {
                var c = 1
                while c < 8 {
                    if c != a { if c != b {
                        var d = 1
                        while d < 8 {
                            if d != a { if d != b { if d != c {
                                let nd = count4(a, b, c, d)
                                if nd >= 1 {
                                    if nd <= 5 { hist[nd] = hist[nd] + 1 }
                                }
                            }}}
                            d = d + 1
                        }
                    }}
                    c = c + 1
                }
            }
            b = b + 1
        }
        a = a + 1
    }

    print("  n=4: C(3)=5 parenthesizations\n")
    print("  Distribution of distinct results:\n")
    var total = 0
    var i = 1
    while i <= 5 {
        print("    "); print_int(i); print(" distinct: "); print_int(hist[i]); print("\n")
        total = total + hist[i]
        i = i + 1
    }
    print("  Total quadruples: "); print_int(total); print("\n")

    // Average branching
    var weighted = 0
    i = 1
    while i <= 5 { weighted = weighted + i * hist[i]; i = i + 1 }
    print("  Mean distinct results: "); print_int(weighted / total); print(".")
    print_int(((weighted * 10) / total) % 10); print("\n")
}

fn catalan(n: i64) -> i64 with Mut {
    // C(0)=1, C(n) = sum C(i)*C(n-1-i) for i=0..n-1
    if n <= 1 { return 1 }
    var sum = 0
    var i = 0
    while i < n {
        sum = sum + catalan(i) * catalan(n - 1 - i)
        i = i + 1
    }
    sum
}

fn cross7() with Mut, Div {
    var k = 0
    while k < 7 { VC[k] = 0; k = k + 1 }

    var i = 0
    while i < 7 {
        let ai = (VA[i] as f64) / 100000000.0
        var j = 0
        while j < 7 {
            let bj = (VB[j] as f64) / 100000000.0
            // ei+1 · ej+1 where i,j are 0-indexed
            let prod_idx = MULT[(i+1)*8+(j+1)]
            let prod_sgn = SIGN[(i+1)*8+(j+1)]
            if prod_idx > 0 {
                // Imaginary part: add to result
                let old = (VC[prod_idx - 1] as f64) / 100000000.0
                VC[prod_idx - 1] = ((old + ai * bj * (prod_sgn as f64)) * 100000000.0) as i64
            }
            // If prod_idx == 0, it contributes to real part (ignored for cross product)
            j = j + 1
        }
        i = i + 1
    }
}

fn dot7(x: i64, y: i64) -> f64 with Div {
    // x,y: 0=VA, 1=VB, 2=VC
    var sum = 0.0
    var i = 0
    while i < 7 {
        var xi = 0.0
        var yi = 0.0
        if x == 0 { xi = (VA[i] as f64) / 100000000.0 }
        if x == 1 { xi = (VB[i] as f64) / 100000000.0 }
        if x == 2 { xi = (VC[i] as f64) / 100000000.0 }
        if y == 0 { yi = (VA[i] as f64) / 100000000.0 }
        if y == 1 { yi = (VB[i] as f64) / 100000000.0 }
        if y == 2 { yi = (VC[i] as f64) / 100000000.0 }
        sum = sum + xi * yi
        i = i + 1
    }
    sum
}

fn rand_vec(target: i64) with Mut, Div {
    var i = 0
    while i < 7 {
        let v = ((rng_next() % 20000) as f64 - 10000.0) / 10000.0
        if target == 0 { VA[i] = (v * 100000000.0) as i64 }
        if target == 1 { VB[i] = (v * 100000000.0) as i64 }
        i = i + 1
    }
}

fn test_antisymmetry() -> i64 with Mut, Div, IO {
    rng_seed(11111, 22222)
    var ok = 1
    var trials = 0
    while trials < 20 {
        rand_vec(0)
        rand_vec(1)

        // Compute a×b
        cross7()
        var ab: [i64; 7] = [0; 7]
        var i = 0
        while i < 7 { ab[i] = VC[i]; i = i + 1 }

        // Swap a,b and compute b×a
        var tmp: [i64; 7] = [0; 7]
        i = 0
        while i < 7 { tmp[i] = VA[i]; VA[i] = VB[i]; VB[i] = tmp[i]; i = i + 1 }
        cross7()

        // Check: VC should equal -ab
        i = 0
        while i < 7 {
            let sum = (VC[i] as f64) / 100000000.0 + (ab[i] as f64) / 100000000.0
            if sum > 0.001 { ok = 0 }
            if sum < 0.0 - 0.001 { ok = 0 }
            i = i + 1
        }
        trials = trials + 1
    }
    if ok == 1 {
        print("  [PASS] Antisymmetry: a×b = -b×a (20 trials)\n")
    } else {
        print("  [FAIL] Antisymmetry violated\n")
    }
    ok
}

fn test_orthogonality() -> i64 with Mut, Div, IO {
    rng_seed(33333, 44444)
    var max_err = 0.0
    var trials = 0
    while trials < 20 {
        rand_vec(0)
        rand_vec(1)
        cross7()

        let dot_ca = dot7(2, 0)
        let dot_cb = dot7(2, 1)

        var err_a = dot_ca
        if err_a < 0.0 { err_a = 0.0 - err_a }
        var err_b = dot_cb
        if err_b < 0.0 { err_b = 0.0 - err_b }

        if err_a > max_err { max_err = err_a }
        if err_b > max_err { max_err = err_b }

        trials = trials + 1
    }
    print("  Max (a×b)·a or (a×b)·b: "); print(max_err); print("\n")
    if max_err < 0.001 {
        print("  [PASS] Orthogonality: cross product ⊥ both inputs\n")
        1
    } else {
        print("  [FAIL] Orthogonality violated (err="); print(max_err); print(")\n")
        0
    }
}

fn test_lagrange() -> i64 with Mut, Div, Panic, IO {
    rng_seed(55555, 66666)
    var max_err = 0.0
    var trials = 0
    while trials < 20 {
        rand_vec(0)
        rand_vec(1)
        cross7()

        let cross_sq = norm_sq(2)
        let na_sq = norm_sq(0)
        let nb_sq = norm_sq(1)
        let ab_dot = dot7(0, 1)
        let expected = na_sq * nb_sq - ab_dot * ab_dot

        var err = cross_sq - expected
        if err < 0.0 { err = 0.0 - err }
        if expected > 0.001 { err = err / expected }  // relative
        if err > max_err { max_err = err }

        trials = trials + 1
    }
    print("  Max relative error: "); print(max_err); print("\n")
    if max_err < 0.01 {
        print("  [PASS] Lagrange identity: |a×b|² = |a|²|b|² - (a·b)²\n")
        1
    } else {
        print("  [FAIL] Lagrange identity error "); print(max_err); print("\n")
        0
    }
}

fn test_jacobi_fails() -> i64 with Mut, Div, IO {
    // J(a,b,c) = a×(b×c) + b×(c×a) + c×(a×b)
    // For a Lie algebra, this should be zero. For octonion cross product, it's NOT.

    // Use basis vectors for clarity
    // a = e1, b = e2, c = e3
    VA[0] = 100000000; VA[1] = 0; VA[2] = 0; VA[3] = 0; VA[4] = 0; VA[5] = 0; VA[6] = 0
    VB[0] = 0; VB[1] = 100000000; VB[2] = 0; VB[3] = 0; VB[4] = 0; VB[5] = 0; VB[6] = 0
    var vc_save: [i64; 7] = [0; 7]
    vc_save[0] = 0; vc_save[1] = 0; vc_save[2] = 100000000
    vc_save[3] = 0; vc_save[4] = 0; vc_save[5] = 0; vc_save[6] = 0

    // Term 1: a×(b×c) — first compute b×c
    // Save a
    var a_save: [i64; 7] = [0; 7]
    var i = 0
    while i < 7 { a_save[i] = VA[i]; i = i + 1 }

    // b×c
    i = 0
    while i < 7 { VA[i] = VB[i]; VB[i] = vc_save[i]; i = i + 1 }
    cross7()
    // Now compute a × (b×c)
    i = 0
    while i < 7 { VA[i] = a_save[i]; VB[i] = VC[i]; i = i + 1 }
    cross7()
    var jacobi: [f64; 7] = [0.0; 7]
    i = 0
    while i < 7 { jacobi[i] = (VC[i] as f64) / 100000000.0; i = i + 1 }

    // Term 2: b×(c×a) — c×a first
    var b_save: [i64; 7] = [0; 7]
    b_save[0] = 0; b_save[1] = 100000000; b_save[2] = 0
    b_save[3] = 0; b_save[4] = 0; b_save[5] = 0; b_save[6] = 0

    i = 0
    while i < 7 { VA[i] = vc_save[i]; VB[i] = a_save[i]; i = i + 1 }
    cross7()
    i = 0
    while i < 7 { VA[i] = b_save[i]; VB[i] = VC[i]; i = i + 1 }
    cross7()
    i = 0
    while i < 7 { jacobi[i] = jacobi[i] + (VC[i] as f64) / 100000000.0; i = i + 1 }

    // Term 3: c×(a×b)
    i = 0
    while i < 7 { VA[i] = a_save[i]; VB[i] = b_save[i]; i = i + 1 }
    cross7()
    i = 0
    while i < 7 { VA[i] = vc_save[i]; VB[i] = VC[i]; i = i + 1 }
    cross7()
    i = 0
    while i < 7 { jacobi[i] = jacobi[i] + (VC[i] as f64) / 100000000.0; i = i + 1 }

    // Compute |J|²
    var j_norm_sq = 0.0
    i = 0
    while i < 7 { j_norm_sq = j_norm_sq + jacobi[i] * jacobi[i]; i = i + 1 }

    print("  Jacobi term |J(e1,e2,e3)|² = "); print(j_norm_sq); print("\n")
    if j_norm_sq > 0.001 {
        print("  [PASS] Jacobi identity FAILS — NOT a Lie algebra (as expected)\n")
        print("  This is the hallmark of non-associativity\n")
        1
    } else {
        print("  [INFO] Jacobi happens to vanish for this triple\n")
        1
    }
}

fn test_basis_cross() -> i64 with Mut, Div, IO {
    var ok = 1
    var i = 0
    while i < 7 {
        var j = 0
        while j < 7 {
            if i != j {
                // Set VA = unit vector i, VB = unit vector j
                var k = 0
                while k < 7 { VA[k] = 0; VB[k] = 0; k = k + 1 }
                VA[i] = 100000000
                VB[j] = 100000000
                cross7()

                // Result should be ±1 in exactly one component
                // matching the multiplication table
                let expected_idx = MULT[(i+1)*8+(j+1)]
                let expected_sgn = SIGN[(i+1)*8+(j+1)]

                if expected_idx > 0 {
                    // Check VC[expected_idx-1] == expected_sgn
                    let val = (VC[expected_idx - 1] as f64) / 100000000.0
                    var err = val - (expected_sgn as f64)
                    if err < 0.0 { err = 0.0 - err }
                    if err > 0.001 { ok = 0 }

                    // All other components should be 0
                    k = 0
                    while k < 7 {
                        if k != expected_idx - 1 {
                            let v2 = (VC[k] as f64) / 100000000.0
                            if v2 > 0.001 { ok = 0 }
                            if v2 < 0.0 - 0.001 { ok = 0 }
                        }
                        k = k + 1
                    }
                }
            }
            j = j + 1
        }
        i = i + 1
    }

    if ok == 1 {
        print("  [PASS] Basis cross products match Fano multiplication table\n")
    } else {
        print("  [FAIL] Mismatch with multiplication table\n")
    }
    ok
}

fn triple_acc(p: i64, q: i64, r: i64, assoc: i64, coeff: i64) with Mut {
    if assoc == 1 {
        basis_mul(q, 1, r, 1)
        let t_idx = RES_IDX
        let t_sgn = RES_SGN
        basis_mul(p, 1, t_idx, t_sgn)
    } else {
        basis_mul(p, 1, q, 1)
        let t_idx = RES_IDX
        let t_sgn = RES_SGN
        basis_mul(t_idx, t_sgn, r, 1)
    }
    DERIV_RES[RES_IDX] = DERIV_RES[RES_IDX] + coeff * RES_SGN
}

fn compute_derivation(a: i64, b: i64, x: i64) with Mut {
    var k = 0
    while k < 8 { DERIV_RES[k] = 0; k = k + 1 }

    // D_{a,b}(x) = [a,x,b] - [b,x,a]
    //            = ((ax)b - a(xb)) - ((bx)a - b(xa))

    // [a,x,b] = (ax)b - a(xb)
    triple_acc(a, x, b, 0, 1)      // +(ax)b
    triple_acc(a, x, b, 1, 0-1)    // -a(xb)

    // -[b,x,a] = -((bx)a - b(xa)) = -(bx)a + b(xa)
    triple_acc(b, x, a, 0, 0-1)    // -(bx)a
    triple_acc(b, x, a, 1, 1)      // +b(xa)
}

