                    basis_mul(t1_idx, t1_sgn, e3, s3)
                    let t2_idx = RES_IDX; let t2_sgn = RES_SGN
                    basis_mul(t2_idx, t2_sgn, e4, s4)

                    if RES_IDX == 0 { flat = flat + 1 }
                    else { curved = curved + 1 }
                    total = total + 1

                    d = d + 1
                }
                c = c + 1
            }
            b = b + 1
        }
        a = a + 1
    }
    print("  Quads in K7: "); print_int(total); print(" (C(7,4)=35)\n")
    print("  Flat: "); print_int(flat); print("  Curved: "); print_int(curved); print("\n")
}

fn init_magic_square() with Mut {
    // Row-major: MS[row*4 + col]
    // Tits' version (symmetrized):
    //           R    C    H    O
    // R    :    0    0    3   14
    // C    :    0    8    8   28     (A₁×A₁=3+3=6? Actually SL₂=3... hmm)
    // H    :    3    8   21   52
    // O    :   14   28   52  248

    // Actually the standard Freudenthal-Tits magic square is:
    //           R      C      H      O
    // R    :  A₁(3)  A₂(8)  C₃(21) F₄(52)
    // C    :  A₂(8)  A₂×A₂  A₅(35) E₆(78)
    // H    : C₃(21) A₅(35) D₆(66) E₇(133)
    // O    : F₄(52) E₆(78) E₇(133) E₈(248)

    MS_DIM[0] = 3;   // (R,R) = A₁
    MS_DIM[1] = 8;   // (R,C) = A₂
    MS_DIM[2] = 21;  // (R,H) = C₃
    MS_DIM[3] = 52;  // (R,O) = F₄
    MS_DIM[4] = 8;   // (C,R) = A₂
    MS_DIM[5] = 16;  // (C,C) = A₂×A₂ (8+8=16)
    MS_DIM[6] = 35;  // (C,H) = A₅
    MS_DIM[7] = 78;  // (C,O) = E₆
    MS_DIM[8] = 21;  // (H,R) = C₃
    MS_DIM[9] = 35;  // (H,C) = A₅
    MS_DIM[10] = 66; // (H,H) = D₆
    MS_DIM[11] = 133; // (H,O) = E₇
    MS_DIM[12] = 52;  // (O,R) = F₄
    MS_DIM[13] = 78;  // (O,C) = E₆
    MS_DIM[14] = 133; // (O,H) = E₇
    MS_DIM[15] = 248; // (O,O) = E₈
}

