fn test_conjugation() -> i64 with Mut, IO {
    // For imaginary units: conj(ei) = -ei
    // For path a→b: conj(e_ab) = -e_ab
    // Reverse path b→a should give conj = -e_ab (anticommutativity)
    // So: path(a→b→c) reversed = conj(e_bc) · conj(e_ab) = (-e_bc)·(-e_ab)

    // Forward: e1 · e2 = e4
    basis_mul(1, 1, 2, 1)
    let fwd_idx = RES_IDX
    let fwd_sgn = RES_SGN

    // Reverse: (-e2) · (-e1) = e2 · e1 = -e4 (anticommutativity)
    basis_mul(2, 1, 1, 1)
    let rev_idx = RES_IDX
    let rev_sgn = RES_SGN

    // conj(forward) should equal reverse
    // conj(e4) = -e4
    let conj_sgn = 0 - fwd_sgn

    print("  Forward e1·e2 = ")
    if fwd_sgn < 0 { print("-") }
    print("e"); print_int(fwd_idx); print("\n")
    print("  Reverse e2·e1 = ")
    if rev_sgn < 0 { print("-") }
    print("e"); print_int(rev_idx); print("\n")

    if fwd_idx == rev_idx {
        if conj_sgn == rev_sgn {
            print("  [PASS] Path reversal = conjugation\n")
            return 1
        }
    }
    print("  [FAIL] Reversal ≠ conjugation\n")
    0
}

fn get_p(which: i64, pos: i64) -> i64 {
    if which == 1 { P1[pos] }
    else { if which == 2 { P2[pos] } else { P3[pos] } }
}

fn test_idempotent() -> i64 with Mut, IO {
    var pass = 0
    var i = 1
    while i < 4 {
        // For diagonal P with entries 0 or 1: P² = P trivially
        // Trace = sum of diagonal entries
        let tr = get_p(i, 0) + get_p(i, 1) + get_p(i, 2)
        if tr == 1 { pass = pass + 1 }
        i = i + 1
    }
    if pass == 3 {
        print("  [PASS] P₁,P₂,P₃ are rank-1 idempotents: P²=P, Tr(P)=1\n")
    } else {
        print("  [FAIL] Idempotent check\n")
    }
    if pass == 3 { 1 } else { 0 }
}

fn test_incidence() -> i64 with Mut, IO {
    // Tr(P_i ∘ P_j) = delta_{ij} for diagonal idempotents
    var ok = 1
    var i = 1
    while i < 4 {
        var j = 1
        while j < 4 {
            var tr = 0
            var k = 0
            while k < 3 {
                tr = tr + get_p(i, k) * get_p(j, k)
                k = k + 1
            }
            if i == j {
                if tr != 1 { ok = 0 }
            } else {
                if tr != 0 { ok = 0 }
            }
            j = j + 1
        }
        i = i + 1
    }
    if ok == 1 {
        print("  [PASS] Incidence: Tr(P_i ∘ P_j) = delta_{ij}\n")
        print("         Orthogonal points → collinear on a line\n")
    } else {
        print("  [FAIL] Incidence\n")
    }
    ok
}

fn test_two_points_line() -> i64 with Mut, IO {
    // Line through P_i, P_j is L_ij = I - P_i - P_j = P_k (the third point)
    // This point-line duality is a defining property of OP²

    var ok = 1
    // L12 = I - P1 - P2 = diag(1,1,1) - diag(1,0,0) - diag(0,1,0) = diag(0,0,1) = P3
    var k = 0
    while k < 3 {
        let l12 = 1 - get_p(1, k) - get_p(2, k)
        if l12 != get_p(3, k) { ok = 0 }
        k = k + 1
    }

    // L13 = I - P1 - P3 = P2
    k = 0
    while k < 3 {
        let l13 = 1 - get_p(1, k) - get_p(3, k)
        if l13 != get_p(2, k) { ok = 0 }
        k = k + 1
    }

    // L23 = I - P2 - P3 = P1
    k = 0
    while k < 3 {
        let l23 = 1 - get_p(2, k) - get_p(3, k)
        if l23 != get_p(1, k) { ok = 0 }
        k = k + 1
    }

    if ok == 1 {
        print("  [PASS] Two points determine a unique line (L_ij = I - P_i - P_j)\n")
        print("         Point-line duality: each line IS the complementary point\n")
    } else {
        print("  [FAIL] Two points line\n")
    }
    ok
}

fn test_non_desarguesian() -> i64 with Mut, IO {
    // Desargues ⟺ coordinate ring is associative (Hilbert 1899)
    // Count non-associative triples among octonion basis elements:
    var non_assoc = 0
    var i = 1
    while i < 8 {
        var j = 1
        while j < 8 {
            var k = 1
            while k < 8 {
                basis_mul(i, 1, j, 1)
                let ab_idx = RES_IDX
                let ab_sgn = RES_SGN
                basis_mul(ab_idx, ab_sgn, k, 1)
                let left_idx = RES_IDX
                let left_sgn = RES_SGN

                basis_mul(j, 1, k, 1)
                let bc_idx = RES_IDX
                let bc_sgn = RES_SGN
                basis_mul(i, 1, bc_idx, bc_sgn)
                let right_idx = RES_IDX
                let right_sgn = RES_SGN

                var same = 1
                if left_idx != right_idx { same = 0 }
                if left_sgn != right_sgn { same = 0 }
                if same == 0 { non_assoc = non_assoc + 1 }

                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }

    print("  Hilbert (1899): Desargues ⟺ coordinate ring is associative\n")
    print("  Non-associative triples in O: "); print_int(non_assoc); print("/343\n")
    if non_assoc == 168 {
        print("  [PASS] OP² is NOT Desarguesian (168 non-associative triples)\n")
    } else {
        print("  [FAIL] Expected 168 non-associative triples\n")
    }
    if non_assoc == 168 { 1 } else { 0 }
}

