fn test_desarguesian_comparison() -> i64 with Mut, IO {
    // Verify all 21 pairs of imaginary octonion units anticommute
    var non_comm = 0
    var i = 1
    while i < 8 {
        var j = i + 1
        while j < 8 {
            basis_mul(i, 1, j, 1)
            let fwd_sgn = RES_SGN
            basis_mul(j, 1, i, 1)
            if fwd_sgn != RES_SGN { non_comm = non_comm + 1 }
            j = j + 1
        }
        i = i + 1
    }

    print("  Hierarchy of projective plane properties:\n")
    print("    Pappus => Desargues => projective plane\n")
    print("  \n")
    print("    RP²: Pappus YES, Desargues YES  (R commutative, associative)\n")
    print("    CP²: Pappus YES, Desargues YES  (C commutative, associative)\n")
    print("    HP²: Pappus NO,  Desargues YES  (H non-commutative, associative)\n")
    print("    OP²: Pappus NO,  Desargues NO   (O non-commutative, non-associative)\n")
    print("  \n")
    print("  Non-commutative pairs in O: "); print_int(non_comm); print("/21\n")

    if non_comm == 21 {
        print("  [PASS] All 21 pairs non-commutative -> Pappus fails\n")
    } else {
        print("  [FAIL] Expected 21 non-commutative pairs\n")
    }
