fn test_ossm_collinearity() -> i64 with Mut, IO {
    // Verify triangle incidence: point P on line L iff Tr(P*L) = 0
    // L12 = P3, L13 = P2, L23 = P1 (by point-line duality)
    var incidence_ok = 1

    // Tr(P1*P3) = 0: P1 is on line L12=P3
    var tr = 0
    var k = 0
    while k < 3 {
        tr = tr + get_p(1, k) * get_p(3, k)
        k = k + 1
    }
    if tr != 0 { incidence_ok = 0 }

    // Tr(P2*P3) = 0: P2 is on line L12=P3
    tr = 0
    k = 0
    while k < 3 {
        tr = tr + get_p(2, k) * get_p(3, k)
        k = k + 1
    }
    if tr != 0 { incidence_ok = 0 }

    // Tr(P3*P3) = 1: P3 is NOT on line L12=P3
    tr = 0
    k = 0
    while k < 3 {
        tr = tr + get_p(3, k) * get_p(3, k)
        k = k + 1
    }
    if tr != 1 { incidence_ok = 0 }

    // Tr(P1*P2) = 0: P1 is on line L13=P2... wait, L13 contains P1 and P3
    // Actually L13 = I - P1 - P3 = P2 (duality). P1 on L13? Tr(P1*P2) = 0 YES
    var tr2 = 0
    k = 0
    while k < 3 {
        tr2 = tr2 + get_p(1, k) * get_p(2, k)
        k = k + 1
    }
    if tr2 != 0 { incidence_ok = 0 }

    print("  O-SSM collinearity constraint from OP²:\n")
    print("    Triangle: 3 points (P₁,P₂,P₃), 3 lines (L₁₂,L₁₃,L₂₃)\n")
    print("    Incidence: P on L iff Tr(P*L) = 0\n")
    print("    Tr(P₁*L₁₂) = 0 (P₁ on L₁₂)\n")
    print("    Tr(P₂*L₁₂) = 0 (P₂ on L₁₂)\n")
    print("    Tr(P₃*L₁₂) = 1 (P₃ NOT on L₁₂)\n")
    print("  \n")
    print("  Non-transitive collinearity: consequence of O non-associativity\n")
    print("  This constrains O-SSM state transitions geometrically\n")
    if incidence_ok == 1 {
        print("  [PASS] OP² incidence verified for coordinate triangle\n")
    } else {
        print("  [FAIL] Incidence\n")
    }
    incidence_ok
}

fn sqrt_o(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn exp_o(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_o(10.0) * exp_o(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var s = 1.0
    var t = 1.0
    var i = 1
    while i <= 20 { t = t * x / (i as f64); s = s + t; i = i + 1 }
    s
}

fn oct_add(a: &Oct, b: &Oct) -> Oct with Mut {
    var o: [f64; 8] = [0.0; 8]
    var i = 0
    while i < 8 { o[i as usize] = a.e[i as usize] + b.e[i as usize]; i = i + 1 }
    Oct { e: o }
}

fn oct_scale(a: &Oct, s: f64) -> Oct with Mut {
    var o: [f64; 8] = [0.0; 8]
    var i = 0
    while i < 8 { o[i as usize] = a.e[i as usize] * s; i = i + 1 }
    Oct { e: o }
}

fn oct_norm(a: &Oct) -> f64 with Mut, Div, Panic {
    var s = 0.0
    var i = 0
    while i < 8 { s = s + a.e[i as usize] * a.e[i as usize]; i = i + 1 }
    sqrt_o(s)
}

fn oct_sigmoid(a: &Oct) -> Oct with Mut, Div, Panic {
    var o: [f64; 8] = [0.0; 8]
    var i = 0
    while i < 8 { o[i as usize] = sigmoid_o(a.e[i as usize]); i = i + 1 }
    Oct { e: o }
}

fn oct_associator(a: &Oct, b: &Oct, c: &Oct) -> Oct with Mut, Div, Panic {
    let ab = oct_mul(a, b)
    let bc = oct_mul(b, c)
    let ab_c = oct_mul(&ab, c)
    let a_bc = oct_mul(a, &bc)
    var o: [f64; 8] = [0.0; 8]
    var i = 0
    while i < 8 { o[i as usize] = ab_c.e[i as usize] - a_bc.e[i as usize]; i = i + 1 }
    Oct { e: o }
}

fn oct_mul_unc(a: &Oct, b: &Oct, au: &Oct, bu: &Oct) -> Oct with Mut, Div, Panic {
    var a_sq = 0.0
    var b_sq = 0.0
    var au_sq = 0.0
    var bu_sq = 0.0
    var i = 0
    while i < 8 {
        a_sq = a_sq + a.e[i as usize] * a.e[i as usize]
        b_sq = b_sq + b.e[i as usize] * b.e[i as usize]
        au_sq = au_sq + au.e[i as usize] * au.e[i as usize]
        bu_sq = bu_sq + bu.e[i as usize] * bu.e[i as usize]
        i = i + 1
    }
    let sigma = sqrt_o(b_sq * au_sq / 8.0 + a_sq * bu_sq / 8.0)
    var o: [f64; 8] = [0.0; 8]
    i = 0
    while i < 8 { o[i as usize] = sigma; i = i + 1 }
    Oct { e: o }
}

fn ossm_step(h: &Oct, x: f64, A: &Oct, B: &Oct, h_unc: &Oct, A_unc: &Oct, B_unc: &Oct) -> SSMState with Mut, Div, Panic {
    let Ah = oct_mul(A, h)
    let Ah_unc = oct_mul_unc(A, h, A_unc, h_unc)
    let Bx = oct_scale(B, x)
    var Bx_u: [f64; 8] = [0.0; 8]
    var i = 0
    while i < 8 { Bx_u[i as usize] = abs_o(x) * B_unc.e[i as usize]; i = i + 1 }
    let Bx_unc = Oct { e: Bx_u }
    let comb = oct_add(&Ah, &Bx)
    var cu: [f64; 8] = [0.0; 8]
    i = 0
    while i < 8 { cu[i as usize] = sqrt_o(Ah_unc.e[i as usize] * Ah_unc.e[i as usize] + Bx_unc.e[i as usize] * Bx_unc.e[i as usize]); i = i + 1 }
    let new_h = oct_sigmoid(&comb)
    var nu: [f64; 8] = [0.0; 8]
    i = 0
    while i < 8 {
        let s = new_h.e[i as usize]
        nu[i as usize] = abs_o(s * (1.0 - s)) * cu[i as usize]
        i = i + 1
    }
    let assoc = oct_associator(A, h, &Bx)
    SSMState { h: new_h, h_unc: Oct { e: nu }, assoc_norm: oct_norm(&assoc) }
}

fn ossm_forward(seq: &[f64; 8], A: &Oct, B: &Oct, C: &Oct, A_u: &Oct, B_u: &Oct, C_u: &Oct) with Mut, Div, Panic {
    var h = oct_zero()
    var hu = Oct { e: [0.01, 0.01, 0.01, 0.01, 0.01, 0.01, 0.01, 0.01] }
    var t = 0
    while t < 8 {
        // Inline the step to reduce call depth
        let Ah = oct_mul(A, &h)
        let Ah_u = oct_mul_unc(A, &h, A_u, &hu)
        let Bx = oct_scale(B, seq[t as usize])
        var bxu: [f64; 8] = [0.0; 8]
        var i = 0
        while i < 8 { bxu[i as usize] = abs_o(seq[t as usize]) * B_u.e[i as usize]; i = i + 1 }
        let comb = oct_add(&Ah, &Bx)
        let new_h = oct_sigmoid(&comb)

        // Uncertainty through sigmoid
        var nue: [f64; 8] = [0.0; 8]
        i = 0
        while i < 8 {
            let cu = sqrt_o(Ah_u.e[i as usize] * Ah_u.e[i as usize] + bxu[i as usize] * bxu[i as usize])
            let s = new_h.e[i as usize]
            nue[i as usize] = abs_o(s * (1.0 - s)) * cu
            i = i + 1
        }

        // Associator
        let assoc = oct_associator(A, &h, &Bx)
        SSM_ANORMS[t as usize] = oct_norm(&assoc)

        h = new_h
        hu = Oct { e: nue }

        // Output: Re(C ⊗ h)
        let Ch = oct_mul(C, &h)
        SSM_OUTS[t as usize] = Ch.e[0]
        let Cu = oct_mul_unc(C, &h, C_u, &hu)
        SSM_UNCS[t as usize] = Cu.e[0]

        t = t + 1
    }
}

fn oct_norm_sq(arr: i64) -> f64 with Div {
    var sum = 0.0
    var i = 0
    while i < 8 {
        var v = 0.0
        if arr == 0 { v = (OA[i] as f64) / 100000000.0 }
        if arr == 1 { v = (OB[i] as f64) / 100000000.0 }
        if arr == 2 { v = (OC[i] as f64) / 100000000.0 }
        sum = sum + v * v
        i = i + 1
    }
    sum
}

fn rand_unit_oct(target: i64) with Mut, Div, Panic {
    var i = 0
    while i < 8 {
        let v = ((rng_next() % 20000) as f64 - 10000.0) / 10000.0
        if target == 0 { OA[i] = (v * 100000000.0) as i64 }
        if target == 1 { OB[i] = (v * 100000000.0) as i64 }
        i = i + 1
    }
    // Normalize
    let n = sqrt_q(oct_norm_sq(target))
    if n > 0.001 {
        i = 0
        while i < 8 {
            if target == 0 { OA[i] = (((OA[i] as f64) / 100000000.0 / n) * 100000000.0) as i64 }
            if target == 1 { OB[i] = (((OB[i] as f64) / 100000000.0 / n) * 100000000.0) as i64 }
            i = i + 1
        }
    }
}

fn test_left_mult_orthogonal() -> i64 with Mut, Div, Panic, IO {
    rng_seed(11111, 22222)
    var max_err = 0.0
    var trials = 0
    while trials < 30 {
        rand_unit_oct(0)  // a (unit)
        // Save a
        var a_save: [i64; 8] = [0; 8]
