    var count_two = 0
    var count_other = 0

    var i: i32 = 1
    while i <= 7 {
        var j: i32 = 1
        while j <= 7 {
            var k: i32 = 1
            while k <= 7 {
                let ei = o_unit(i)
                let ej = o_unit(j)
                let ek = o_unit(k)

                // [e_i, e_j, e_k] = (e_i * e_j) * e_k - e_i * (e_j * e_k)
                let left = o_mul(o_mul(ei, ej), ek)
                let right = o_mul(ei, o_mul(ej, ek))
                let assoc = o_sub(left, right)
                let norm = sqrt_f(o_norm_sq(assoc))

                if norm < 0.1 {
                    count_zero = count_zero + 1
