fn lorentz_gamma(v: [f64; 8], c_sq: f64) -> f64 with Mut, Panic, Div {
    let v_sq = o_norm_sq(v)
    let ratio = v_sq / c_sq
    if ratio >= 1.0 { return 0.0 - 1.0 }  // beyond lightcone
    1.0 / sqrt_f(1.0 - ratio)
}

