    if diff < 0.001 {
        println("  PASS: gamma depends on ||v||, not direction.")
        println("  --> The Lorentz factor is isotropic in the 7D experience space.")
        println("  --> BUT: composition of boosts is ANISOTROPIC (non-associative).")
        1
    } else {
        println("  FAIL: Direction-dependent gamma.")
        0
    }
}

fn interval(de0: f64, de: [f64; 8], c_sq: f64) -> f64 with Mut, Panic, Div {
    // ds² = c²·de₀² - ||de||² (ignoring de[0] since that's the time component)
    var space_sq: f64 = 0.0
    var i: i32 = 1
    while i < 8 { space_sq = space_sq + de[i as usize] * de[i as usize]; i = i + 1 }
    c_sq * de0 * de0 - space_sq
}

fn max_f64(a: f64, b: f64) -> f64 {
    if a > b { return a }
    return b
}

fn min_f64(a: f64, b: f64) -> f64 {
    if a < b { return a }
    return b
}

fn exp_decay_analytical(u0: f64, k: f64, t: f64) -> f64 {
    return u0 * exp_approx(0.0 - k * t)
}

fn default_config() -> ODEConfig {
