fn setup_data() with Mut, Div, Panic {
    rng_seed(42424242, 13131313)
    SQ[0] = (rng_next() / 100) % 8
    SQ[1] = (rng_next() / 100) % 8
    var i = 2
    while i < 120 {
        SQ[i] = (3 * SQ[i-1] + SQ[i-2]) % 8
        i = i + 1
    }
}

fn r_init() with Mut, Div, Panic {
    var i = 0
    while i < 8 { ws(i, rand_normal() * 0.3); i = i + 1 }
    ws(8, 0.9)
    ws(9, rand_normal() * 0.3)
    i = 0
    while i < 8 { ws(10 + i, rand_normal() * 0.3); i = i + 1 }
}

fn r_forward(token: i64) with Mut, Div {
    let inp = wg(token)
    var new_h = wg(8) * hg(0) + wg(9) * inp
    if new_h > 4.0 { new_h = 4.0 }
    if new_h < 0.0 - 4.0 { new_h = 0.0 - 4.0 }
    hs(0, new_h)
    var v = 0
    while v < 8 { L[v] = (hg(0) * wg(10 + v) * 100000000.0) as i64; v = v + 1 }
}

fn c_init() with Mut, Div, Panic {
    var i = 0
    while i < 16 { ws(i, rand_normal() * 0.3); i = i + 1 }
    // A = rotation matrix: [[cos,-sin],[sin,cos]] ≈ [[0.9,-0.1],[0.1,0.9]]
    ws(16, 0.9); ws(17, 0.0 - 0.1); ws(18, 0.1); ws(19, 0.9)
    ws(20, rand_normal() * 0.3); ws(21, rand_normal() * 0.3)
    i = 0
    while i < 16 { ws(22 + i, rand_normal() * 0.3); i = i + 1 }
}

fn h_init() with Mut, Div, Panic {
    var i = 0
    while i < 32 { ws(i, rand_normal() * 0.3); i = i + 1 }
    // A: diagonal-dominant initialization
    i = 0
    while i < 16 {
        var v = rand_normal() * 0.1
        let row = i / 4
        let col = i - row * 4
        if row == col { v = 0.85 + rand_normal() * 0.05 }
        ws(32 + i, v)
        i = i + 1
    }
    i = 0
    while i < 4 { ws(48 + i, rand_normal() * 0.3); i = i + 1 }
    i = 0
    while i < 32 { ws(52 + i, rand_normal() * 0.3); i = i + 1 }
}

fn h_forward(token: i64) with Mut, Div {
    var inp: [f64; 4] = [0.0; 4]
    var d = 0
    while d < 4 { inp[d] = wg(token * 4 + d); d = d + 1 }
    var new_h: [f64; 4] = [0.0; 4]
    d = 0
    while d < 4 {
        var s = 0.0
        var j = 0
        while j < 4 { s = s + wg(32 + d*4 + j) * hg(j); j = j + 1 }
        s = s + wg(48 + d) * inp[d]
        if s > 4.0 { s = 4.0 } if s < 0.0-4.0 { s = 0.0-4.0 }
        new_h[d] = s
        d = d + 1
    }
    d = 0
    while d < 4 { hs(d, new_h[d]); d = d + 1 }
    var v = 0
    while v < 8 {
        var s = 0.0
        d = 0
        while d < 4 { s = s + hg(d) * wg(52 + d*8 + v); d = d + 1 }
        L[v] = (s * 100000000.0) as i64
        v = v + 1
    }
}

fn o_init() with Mut, Div, Panic {
    var i = 0
    while i < 64 { ws(i, rand_normal() * 0.3); i = i + 1 }
    i = 0
    while i < 64 {
        var v = rand_normal() * 0.1
        let row = i / 8
        let col = i - row * 8
        if row == col { v = 0.85 + rand_normal() * 0.05 }
        ws(64 + i, v)
        i = i + 1
    }
    i = 0
    while i < 8 { ws(128 + i, rand_normal() * 0.3); i = i + 1 }
    i = 0
    while i < 64 { ws(136 + i, rand_normal() * 0.3); i = i + 1 }
}

fn o_forward(token: i64) with Mut, Div {
    var d = 0
    while d < 8 { H_OLD[d] = H[d]; d = d + 1 }
    var inp: [f64; 8] = [0.0; 8]
    d = 0
    while d < 8 { inp[d] = wg(token * 8 + d); d = d + 1 }
    var new_h: [f64; 8] = [0.0; 8]
    d = 0
    while d < 8 {
        var s = 0.0
        var j = 0
        while j < 8 { s = s + wg(64 + d*8 + j) * ((H_OLD[j] as f64)/100000000.0); j = j + 1 }
        s = s + wg(128 + d) * inp[d]
        if s > 4.0 { s = 4.0 } if s < 0.0-4.0 { s = 0.0-4.0 }
        new_h[d] = s
        d = d + 1
    }
    d = 0
    while d < 8 { hs(d, new_h[d]); d = d + 1 }
    var v = 0
    while v < 8 {
        var s = 0.0
        d = 0
        while d < 8 { s = s + hg(d) * wg(136 + d*8 + v); d = d + 1 }
        L[v] = (s * 100000000.0) as i64
        v = v + 1
    }
}

fn compute_loss(tgt: i64) -> f64 with Mut, Div, Panic {
    // Softmax over 8 logits
    var mx = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 8 {
        let v = (L[i] as f64) / 100000000.0
        if v > mx { mx = v }
        i = i + 1
    }
    var sum_exp = 0.0
    i = 0
    while i < 8 {
        sum_exp = sum_exp + exp_q((L[i] as f64) / 100000000.0 - mx)
        i = i + 1
    }
    let p_tgt = exp_q((L[tgt] as f64) / 100000000.0 - mx) / sum_exp
    var pt = p_tgt
    if pt < 0.0000001 { pt = 0.0000001 }
    0.0 - log_q(pt)
}

fn update_output(tgt: i64, lr: f64, dim: i64, out_off: i64) with Mut, Div, Panic {
    // Gradient of cross-entropy w.r.t. output weights
    var mx = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 8 {
        let v = (L[i] as f64) / 100000000.0
        if v > mx { mx = v }
        i = i + 1
    }
    var probs: [f64; 8] = [0.0; 8]
    var sum_exp = 0.0
    i = 0
    while i < 8 {
        probs[i] = exp_q((L[i] as f64) / 100000000.0 - mx)
        sum_exp = sum_exp + probs[i]
        i = i + 1
    }
    i = 0
    while i < 8 { probs[i] = probs[i] / sum_exp; i = i + 1 }

    // grad[v] = p[v] - (v==tgt)
    var grads: [f64; 8] = [0.0; 8]
    i = 0
    while i < 8 { grads[i] = probs[i]; i = i + 1 }
    grads[tgt] = grads[tgt] - 1.0

    // Update output: W_out[d,v] -= lr * H[d] * grad[v]  (with momentum)
    var d = 0
    while d < dim {
        let hd = hg(d)
        var v = 0
        while v < 8 {
            let idx = out_off + d * 8 + v
            var g = hd * grads[v]
            if g > 0.5 { g = 0.5 }
            if g < 0.0 - 0.5 { g = 0.0 - 0.5 }
            let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            v = v + 1
        }
        d = d + 1
    }
}

fn save_weights() with Mut {
    var i = 0
    while i < 256 { W_SAVE[i] = W[i]; i = i + 1 }
}

fn train_model(model_id: i64) -> f64 with IO, Mut, Div, Panic {
    // model_id: 0=R, 1=C, 2=H, 3=O
    var dim = 1
    var out_off = 10
    if model_id == 1 { dim = 2; out_off = 22 }
    if model_id == 2 { dim = 4; out_off = 52 }
    if model_id == 3 { dim = 8; out_off = 136 }

    // Clear momentum
    var i = 0
    while i < 256 { MOM[i] = 0; i = i + 1 }

    var final_loss = 0.0
    var ep = 0
    while ep < 120 {
        // Reset hidden state
        i = 0
        while i < 8 { H[i] = 0; i = i + 1 }

        var tl = 0.0
        var ti = 0
        while ti < 80 {
            let tgt = SQ[ti + 1]
            if model_id == 0 { r_forward(SQ[ti]) }
            if model_id == 1 { c_forward(SQ[ti]) }
            if model_id == 2 { h_forward(SQ[ti]) }
            if model_id == 3 { o_forward(SQ[ti]) }
            tl = tl + compute_loss(tgt)
            update_output(tgt, 0.01, dim, out_off)
            ti = ti + 1
        }
        final_loss = tl / 80.0
        if ep % 30 == 0 {
            print("    ep "); print_int(ep); print(" loss="); print(final_loss); print("\n")
        }
        ep = ep + 1
    }
    final_loss
}

fn measure_order_sens(model_id: i64) -> f64 with Mut, Div {
    var dim = 1
    if model_id == 1 { dim = 2 }
    if model_id == 2 { dim = 4 }
    if model_id == 3 { dim = 8 }

    // Seq A: [0, 1, 2]
    var i = 0
    while i < 8 { H[i] = 0; i = i + 1 }
    if model_id == 0 { r_forward(0); r_forward(1); r_forward(2) }
    if model_id == 1 { c_forward(0); c_forward(1); c_forward(2) }
    if model_id == 2 { h_forward(0); h_forward(1); h_forward(2) }
    if model_id == 3 { o_forward(0); o_forward(1); o_forward(2) }
    var ha: [f64; 8] = [0.0; 8]
    i = 0
    while i < dim { ha[i] = hg(i); i = i + 1 }

    // Seq B: [2, 1, 0]
    i = 0
    while i < 8 { H[i] = 0; i = i + 1 }
    if model_id == 0 { r_forward(2); r_forward(1); r_forward(0) }
    if model_id == 1 { c_forward(2); c_forward(1); c_forward(0) }
    if model_id == 2 { h_forward(2); h_forward(1); h_forward(0) }
    if model_id == 3 { o_forward(2); o_forward(1); o_forward(0) }

    var dist = 0.0
    i = 0
    while i < dim {
        let dd = ha[i] - hg(i)
        dist = dist + dd * dd
        i = i + 1
    }
    dist
}

fn measure_spread(model_id: i64) -> f64 with Mut, Div {
    var dim = 1
    if model_id == 1 { dim = 2 }
    if model_id == 2 { dim = 4 }
    if model_id == 3 { dim = 8 }

    // Process 16 different 5-token sequences
    var s = 0
    while s < 16 {
        var i = 0
        while i < 8 { H[i] = 0; i = i + 1 }
        // Sequence: s encoded as 5 binary-ish tokens
        var t = 0
        while t < 5 {
            let tok = (s / (1 + t) + t * 3) % 8
            if model_id == 0 { r_forward(tok) }
            if model_id == 1 { c_forward(tok) }
            if model_id == 2 { h_forward(tok) }
            if model_id == 3 { o_forward(tok) }
            t = t + 1
        }
        i = 0
        while i < dim { SPREAD_STATES[s * 8 + i] = H[i]; i = i + 1 }
        s = s + 1
    }

    // Average pairwise L2
    var total = 0.0
    var count = 0
    var i = 0
    while i < 16 {
        var j = i + 1
        while j < 16 {
            var dist = 0.0
            var d = 0
            while d < dim {
                let di = (SPREAD_STATES[i*8+d] as f64) / 100000000.0
                let dj = (SPREAD_STATES[j*8+d] as f64) / 100000000.0
                let dd = di - dj
                dist = dist + dd * dd
                d = d + 1
            }
            total = total + dist
            count = count + 1
            j = j + 1
        }
        i = i + 1
    }
    if count > 0 { total / (count as f64) } else { 0.0 }
}

fn run_model(id: i64, name_len: i64) with IO, Mut, Div, Panic {
    // Initialize
    rng_seed(77777, 33333)
    if id == 0 { r_init() }
    if id == 1 { c_init() }
    if id == 2 { h_init() }
    if id == 3 { o_init() }

    let loss = train_model(id)
    RES_LOSS[id] = (loss * 100000000.0) as i64

    let order = measure_order_sens(id)
    RES_ORDER[id] = (order * 100000000.0) as i64

    let spread = measure_spread(id)
    RES_SPREAD[id] = (spread * 100000000.0) as i64
}

fn cross_step(token: i64) with Mut, Div {
    var inp: [f64; 4] = [0.0; 4]
    var d = 0
    while d < 4 { inp[d] = wg(token * 4 + d); d = d + 1 }
    var new_h: [f64; 4] = [0.0; 4]
    d = 0
    while d < 4 {
        var s = 0.0
        var j = 0
        while j < 4 { s = s + wg(8 + d*4 + j) * hg(j); j = j + 1 }
        s = s + wg(24 + d) * inp[d]
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        new_h[d] = s
        d = d + 1
    }
    d = 0
    while d < 4 { hs(d, new_h[d]); d = d + 1 }
}

fn diag_step(token: i64) with Mut, Div {
    var inp: [f64; 4] = [0.0; 4]
    var d = 0
    while d < 4 { inp[d] = wg(token * 4 + d); d = d + 1 }
    var new_h: [f64; 4] = [0.0; 4]
    d = 0
    while d < 4 {
        var s = wg(8 + d) * hg(d) + wg(24 + d) * inp[d]
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        new_h[d] = s
        d = d + 1
    }
    d = 0
    while d < 4 { hs(d, new_h[d]); d = d + 1 }
}

fn init_weights() with Mut, Div, Panic {
    var i = 0
    while i < 8 { ws(i, rand_normal() * 0.5); i = i + 1 }
    // A matrix
    i = 0
    while i < 16 {
        var v = rand_normal() * 0.2
        let row = i / 4
        let col = i - row * 4
        if row == col { v = 0.8 + rand_normal() * 0.1 }
        ws(8 + i, v)
        i = i + 1
    }
    i = 0
    while i < 4 { ws(24 + i, rand_normal() * 0.5); i = i + 1 }
    i = 0
    while i < 8 { ws(28 + i, rand_normal() * 0.3); i = i + 1 }
}

fn run_sequence(seq_bits: i64, length: i64, use_cross: i64) with Mut, Div {
    H[0] = 0; H[1] = 0; H[2] = 0; H[3] = 0
    var t = 0
    while t < length {
        // Extract bit t from seq_bits
        let shift = length - 1 - t
        var bit = 0
        if shift > 0 {
            bit = (seq_bits >> shift) % 2
        } else {
            bit = seq_bits % 2
        }
        if bit < 0 { bit = 0 - bit }
        if use_cross == 1 { cross_step(bit) }
        else { diag_step(bit) }
        t = t + 1
    }
}

fn count_distinct(num_seqs: i64) -> i64 with Mut, Div {
    // Count distinct states using brute-force pairwise comparison
    // Two states are "same" if L2 distance < threshold
    let threshold = 0.0001
    var distinct = 0
    var i = 0
    while i < num_seqs {
        var is_dup = 0
        var j = 0
        while j < i {
            var dist = 0.0
            var d = 0
            while d < 4 {
                let di = (STATES[i*4 + d] as f64) / 100000000.0
                let dj = (STATES[j*4 + d] as f64) / 100000000.0
                let dd = di - dj
                dist = dist + dd * dd
                d = d + 1
            }
            if dist < threshold { is_dup = 1 }
            j = j + 1
        }
        if is_dup == 0 { distinct = distinct + 1 }
        i = i + 1
    }
    distinct
}

fn compute_spread(num_seqs: i64) -> f64 with Mut, Div {
    // Average pairwise L2 distance — how spread out are the states?
    var total = 0.0
    var count = 0
    var i = 0
    while i < num_seqs {
        var j = i + 1
        while j < num_seqs {
            var dist = 0.0
            var d = 0
            while d < 4 {
                let di = (STATES[i*4 + d] as f64) / 100000000.0
                let dj = (STATES[j*4 + d] as f64) / 100000000.0
                let dd = di - dj
                dist = dist + dd * dd
                d = d + 1
            }
            total = total + dist
            count = count + 1
            j = j + 1
        }
        i = i + 1
    }
    if count > 0 { total / (count as f64) } else { 0.0 }
}

fn test_permutation_sensitivity() with IO, Mut, Div {
    print("\n--- Permutation Sensitivity ---\n")
    // Sequences with same # of 1s but different order
    // [0,0,1,1,1] vs [1,0,1,0,1] vs [1,1,1,0,0]
    var seqs: [i64; 3] = [7, 21, 28]
    // 00111 = 7, 10101 = 21, 11100 = 28

    // Cross-dim
    var cross_dists: [f64; 3] = [0.0; 3]
    var si = 0
    while si < 3 {
        run_sequence(seqs[si], 5, 1)
        var d = 0
        while d < 4 { STATES[si*4 + d] = H[d]; d = d + 1 }
        si = si + 1
    }
    // Pairwise distances
    var pair = 0
    var pi = 0
    while pi < 3 {
        var pj = pi + 1
        while pj < 3 {
            var dist = 0.0
            var d = 0
            while d < 4 {
                let di = (STATES[pi*4+d] as f64) / 100000000.0
                let dj = (STATES[pj*4+d] as f64) / 100000000.0
                let dd = di - dj
                dist = dist + dd * dd
                d = d + 1
            }
            cross_dists[pair] = dist
            pair = pair + 1
            pj = pj + 1
        }
        pi = pi + 1
    }

    // Diagonal
    var diag_dists: [f64; 3] = [0.0; 3]
    si = 0
    while si < 3 {
        run_sequence(seqs[si], 5, 0)
        var d = 0
        while d < 4 { STATES[si*4 + d] = H[d]; d = d + 1 }
        si = si + 1
    }
    pair = 0
    pi = 0
    while pi < 3 {
        var pj = pi + 1
        while pj < 3 {
            var dist = 0.0
            var d = 0
            while d < 4 {
                let di = (STATES[pi*4+d] as f64) / 100000000.0
                let dj = (STATES[pj*4+d] as f64) / 100000000.0
                let dd = di - dj
                dist = dist + dd * dd
                d = d + 1
            }
            diag_dists[pair] = dist
            pair = pair + 1
            pj = pj + 1
        }
        pi = pi + 1
    }

    // Average permutation distance
    var cross_avg = (cross_dists[0] + cross_dists[1] + cross_dists[2]) / 3.0
    var diag_avg = (diag_dists[0] + diag_dists[1] + diag_dists[2]) / 3.0

    print("  Cross-dim perm distance (avg): "); print(cross_avg); print("\n")
    print("  Diagonal perm distance (avg):  "); print(diag_avg); print("\n")
    if cross_avg > diag_avg {
        print("  CROSS-DIM "); print(cross_avg / diag_avg); print("x more permutation-sensitive\n")
    } else {
        if diag_avg > 0.0001 {
            print("  DIAGONAL "); print(diag_avg / cross_avg); print("x more permutation-sensitive\n")
        }
    }
}

fn fano_step(token: i64, alpha: f64) with Mut, Div {
    // Embed
    var inp: [f64; 7] = [0.0; 7]
    var d = 0
    while d < 7 { inp[d] = wg(token * 7 + d); d = d + 1 }

    // State update: h_new[d] = A_diag[d]*h[d] + B[d]*inp[d]
    //                         + A_fano * (coupling along Fano lines)
    //                         + α * A_cross * (cross-Fano coupling)
    var new_h: [f64; 7] = [0.0; 7]

    // Diagonal decay
    d = 0
    while d < 7 { new_h[d] = wg(21 + d) * hg(d) + wg(35 + d) * inp[d]; d = d + 1 }

    // Fano coupling: for each triple (a,b,c), couple h[a]→h[c] and h[b]→h[c]
    // This is the associative part — stable, like quaternion subalgebras
    var t = 0
    while t < 7 {
        let a = FANO_A[t]
        let b = FANO_B[t]
        let c = FANO_C[t]
        let strength = wg(14 + t)
        // Fano coupling: c gets info from a and b (like the product ea·eb = ec)
        new_h[c] = new_h[c] + strength * (hg(a) * hg(b))
        t = t + 1
    }

    // Cross-Fano coupling: couple dimensions NOT in the same Fano triple
    // This is the non-associative part — creates order dependence
    t = 0
    while t < 7 {
        let cross_str = alpha * wg(28 + t)
        // Cross coupling: each dim gets input from 2 dims away (non-Fano)
        let src1 = (t + 2) % 7
        let src2 = (t + 4) % 7
        new_h[t] = new_h[t] + cross_str * (hg(src1) - hg(src2))
        t = t + 1
    }

    // Clamp and store
    d = 0
    while d < 7 {
        var v = new_h[d]
        if v > 3.0 { v = 3.0 }
        if v < 0.0 - 3.0 { v = 0.0 - 3.0 }
        hs(d, v)
        d = d + 1
    }

    // Output
    var v = 0
    while v < 2 {
        var s = 0.0
        d = 0
        while d < 7 { s = s + hg(d) * wg(42 + d*2 + v); d = d + 1 }
        L[v] = (s * 100000000.0) as i64
        v = v + 1
    }
}

fn step_loss(tgt: i64, lr: f64) -> f64 with Mut, Div, Panic {
    let l0 = (L[0] as f64) / 100000000.0
    let l1 = (L[1] as f64) / 100000000.0
    var mx = l0
    if l1 > l0 { mx = l1 }
    let e0 = exp_q(l0 - mx)
    let e1 = exp_q(l1 - mx)
    let sm = e0 + e1
    let p0 = e0 / sm
    let p1 = e1 / sm
    var pt = p1
    if tgt == 0 { pt = p0 }
    if pt < 0.0000001 { pt = 0.0000001 }

    var g0 = p0
    var g1 = p1
    if tgt == 0 { g0 = g0 - 1.0 } else { g1 = g1 - 1.0 }

    // Update output weights
    var d = 0
    while d < 7 {
        let hd = hg(d)
        ws(42+d*2, wg(42+d*2) - lr*hd*g0)
        ws(42+d*2+1, wg(42+d*2+1) - lr*hd*g1)
        d = d + 1
    }

    // Update B and A_diag
    d = 0
    while d < 7 {
        var dh = wg(42+d*2)*g0 + wg(42+d*2+1)*g1
        if dh > 1.0 { dh = 1.0 }
        if dh < 0.0 - 1.0 { dh = 0.0 - 1.0 }
        ws(35 + d, wg(35 + d) - lr * dh * 0.3)
        ws(21 + d, wg(21 + d) - lr * dh * hg(d) * 0.1)
        d = d + 1
    }

    0.0 - log_q(pt)
}

