    while i < 160 { MOM[i] = 0; i = i + 1 }
}

fn forward_step(token: i64, step: i64, is_cross: i64) with Mut, Div {
    // Save current hidden state BEFORE update
    var d = 0
    while d < 8 { H_SAVE[step * 8 + d] = H[d]; d = d + 1 }

    // Embed input
    var inp: [f64; 8] = [0.0; 8]
    d = 0
    while d < 8 {
        inp[d] = wg(token * 8 + d)
        X_SAVE[step * 8 + d] = (inp[d] * 100000000.0) as i64
        d = d + 1
    }

    // State update
    if is_cross == 1 {
        var new_h: [f64; 8] = [0.0; 8]
        d = 0
        while d < 8 {
            var s = 0.0
            var j = 0
            while j < 8 { s = s + wg(64 + d*8 + j) * hg(j); j = j + 1 }
            s = s + wg(128 + d) * inp[d]
            if s > 5.0 { s = 5.0 } if s < 0.0-5.0 { s = 0.0-5.0 }
            new_h[d] = s; d = d + 1
        }
        d = 0
        while d < 8 { hs(d, new_h[d]); d = d + 1 }
    } else {
        d = 0
        while d < 8 {
            var s = wg(64 + d*8 + d) * hg(d) + wg(128 + d) * inp[d]
            if s > 5.0 { s = 5.0 } if s < 0.0-5.0 { s = 0.0-5.0 }
            hs(d, s); d = d + 1
        }
    }
}

fn compute_logits_3() with Mut, Div {
    var c = 0
    while c < 3 {
        var s = 0.0
        var d = 0
        while d < 8 { s = s + hg(d) * wg(136 + d*3 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn get_pred() -> i64 with Div {
    var best = 0; var bv = (L[0] as f64)/100000000.0
    var i = 1
    while i < 3 { let v = (L[i] as f64)/100000000.0; if v > bv { bv = v; best = i }; i = i + 1 }
    best
}

fn bptt_backward(tgt: i64, is_cross: i64, lr: f64) with Mut, Div, Panic {
    // Step 1: Compute softmax and output gradient
    var mx = (L[0] as f64)/100000000.0
    var i = 1
    while i < 3 { let v = (L[i] as f64)/100000000.0; if v > mx { mx = v }; i = i + 1 }
    var probs: [f64; 3] = [0.0; 3]
    var se = 0.0
    i = 0
    while i < 3 { probs[i] = exp_q((L[i] as f64)/100000000.0 - mx); se = se + probs[i]; i = i + 1 }
    i = 0
    while i < 3 { probs[i] = probs[i] / se; i = i + 1 }
    probs[tgt] = probs[tgt] - 1.0

    // Step 2: Gradient w.r.t. output weights and hidden state
    // ∂L/∂W_out[d,c] = h[d] * grad[c]
    // ∂L/∂h[d] = Σ_c W_out[d,c] * grad[c]
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var dh_d = 0.0
        var c = 0
        while c < 3 {
            let idx = 136 + d*3 + c
            var g = hd * probs[c]
            if g > 0.5 { g = 0.5 } if g < 0.0-0.5 { g = 0.0-0.5 }
            let m = (MOM[idx] as f64)/100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            dh_d = dh_d + wg(136 + d*3 + c) * probs[c]
            c = c + 1
        }
        DH[d] = (dh_d * 100000000.0) as i64
        d = d + 1
    }

    // Step 3: Clear A and B gradients
    i = 0
    while i < 64 { DA[i] = 0; i = i + 1 }
    i = 0
    while i < 8 { DB[i] = 0; i = i + 1 }
    i = 0
    while i < 64 { DE[i] = 0; i = i + 1 }

    // Step 4: BPTT — propagate gradient backward through time
    var t = N_STEPS - 1
    while t >= 0 {
        // ∂L/∂A[d,j] += ∂L/∂h_{t+1}[d] * h_t[j]
        d = 0
        while d < 8 {
            let dh_d = (DH[d] as f64) / 100000000.0
            // Clip gradient
            var dh_clip = dh_d
            if dh_clip > 0.5 { dh_clip = 0.5 }
            if dh_clip < 0.0 - 0.5 { dh_clip = 0.0 - 0.5 }

            if is_cross == 1 {
                var j = 0
                while j < 8 {
                    let ht_j = (H_SAVE[t*8+j] as f64) / 100000000.0
                    DA[d*8+j] = DA[d*8+j] + (dh_clip * ht_j * 100000000.0) as i64
                    j = j + 1
                }
            } else {
                let ht_d = (H_SAVE[t*8+d] as f64) / 100000000.0
                DA[d*8+d] = DA[d*8+d] + (dh_clip * ht_d * 100000000.0) as i64
            }

            // ∂L/∂B[d] += ∂L/∂h_{t+1}[d] * x_t[d]
            let xt_d = (X_SAVE[t*8+d] as f64) / 100000000.0
            DB[d] = DB[d] + (dh_clip * xt_d * 100000000.0) as i64

            d = d + 1
        }

        // Propagate gradient to previous timestep: ∂L/∂h_t = A^T · ∂L/∂h_{t+1}
        var new_dh: [f64; 8] = [0.0; 8]
        d = 0
        while d < 8 {
            if is_cross == 1 {
                var j = 0
                while j < 8 {
                    new_dh[d] = new_dh[d] + wg(64 + j*8 + d) * ((DH[j] as f64)/100000000.0)
                    j = j + 1
                }
            } else {
                new_dh[d] = wg(64 + d*8 + d) * ((DH[d] as f64)/100000000.0)
            }
            // Clip to prevent explosion
            if new_dh[d] > 1.0 { new_dh[d] = 1.0 }
            if new_dh[d] < 0.0 - 1.0 { new_dh[d] = 0.0 - 1.0 }
            d = d + 1
        }
        d = 0
        while d < 8 { DH[d] = (new_dh[d] * 100000000.0) as i64; d = d + 1 }

        t = t - 1
    }

    // Step 5: Apply accumulated gradients with momentum
    i = 0
    while i < 64 {
        let g = (DA[i] as f64) / 100000000.0 / (N_STEPS as f64)
        var gc = g
        if gc > 0.3 { gc = 0.3 } if gc < 0.0-0.3 { gc = 0.0-0.3 }
        let idx = 64 + i
        let m = (MOM[idx] as f64)/100000000.0 * 0.9 + gc
        MOM[idx] = (m * 100000000.0) as i64
        ws(idx, wg(idx) - lr * m)
        i = i + 1
    }
    i = 0
    while i < 8 {
        let g = (DB[i] as f64) / 100000000.0 / (N_STEPS as f64)
        var gc = g
        if gc > 0.3 { gc = 0.3 } if gc < 0.0-0.3 { gc = 0.0-0.3 }
        let idx = 128 + i
        let m = (MOM[idx] as f64)/100000000.0 * 0.9 + gc
        MOM[idx] = (m * 100000000.0) as i64
        ws(idx, wg(idx) - lr * m)
        i = i + 1
    }
}

fn gen_sorted_asc(k: i64) with Mut, Div {
    var i = 0
    while i < k { SQ[i] = (rng_next() / 100) % 100; i = i + 1 }
    i = 0
    while i < k {
        var j = 0
        while j < k-1-i {
            if SQ[j] > SQ[j+1] { let tmp = SQ[j]; SQ[j] = SQ[j+1]; SQ[j+1] = tmp }
            j = j + 1
        }
        i = i + 1
    }
}

fn gen_sample(k: i64) -> i64 with Mut, Div {
    let cls = (rng_next() / 100) % 3
    if cls == 0 { gen_sorted_asc(k) }
    if cls == 1 {
        gen_sorted_asc(k)
        var i = 0
        while i < k/2 { let tmp = SQ[i]; SQ[i] = SQ[k-1-i]; SQ[k-1-i] = tmp; i = i + 1 }
    }
    if cls == 2 {
        var i = 0
        while i < k { SQ[i] = (rng_next() / 100) % 100; i = i + 1 }
        var ia = 1; var id = 1
        i = 0
        while i < k-1 { if SQ[i] > SQ[i+1] { ia = 0 }; if SQ[i] < SQ[i+1] { id = 0 }; i = i + 1 }
        if ia == 1 { let tmp = SQ[0]; SQ[0] = SQ[1]; SQ[1] = tmp }
        if id == 1 { let tmp = SQ[0]; SQ[0] = SQ[1]; SQ[1] = tmp }
    }
    cls
}

fn train_sorting_fullbp(is_cross: i64, k: i64, delay: i64, n_epochs: i64) -> f64 with IO, Mut, Div, Panic {
    let n_train = 300
    var ep = 0
    while ep < n_epochs {
        var correct = 0
        var s = 0
        while s < n_train {
            let cls = gen_sample(k)
            var d = 0
            while d < 8 { H[d] = 0; d = d + 1 }
            N_STEPS = 0

            // Forward: process values as continuous input via embedding token 0
            var t = 0
            while t < k {
                // Use token = SQ[t] % 8 to index embedding
                forward_step(SQ[t] % 8, N_STEPS, is_cross)
                N_STEPS = N_STEPS + 1
                t = t + 1
            }
            // Delay
            t = 0
            while t < delay {
                forward_step(0, N_STEPS, is_cross)
                N_STEPS = N_STEPS + 1
                t = t + 1
            }

            compute_logits_3()
            if get_pred() == cls { correct = correct + 1 }

            // Phase 1 (first 20 epochs): output-only
            // Phase 2 (remaining): full BPTT with tiny A learning rate
            if ep < 20 {
                // Output-only update (no BPTT)
                var mx2 = (L[0] as f64)/100000000.0
                var i2 = 1
                while i2 < 3 { let v2 = (L[i2] as f64)/100000000.0; if v2 > mx2 { mx2 = v2 }; i2 = i2 + 1 }
                var probs2: [f64; 3] = [0.0; 3]
                var se2 = 0.0
                i2 = 0
                while i2 < 3 { probs2[i2] = exp_q((L[i2] as f64)/100000000.0 - mx2); se2 = se2 + probs2[i2]; i2 = i2 + 1 }
                i2 = 0
                while i2 < 3 { probs2[i2] = probs2[i2] / se2; i2 = i2 + 1 }
                probs2[cls] = probs2[cls] - 1.0
                var d2 = 0
                while d2 < 8 {
                    let hd2 = hg(d2)
                    var c2 = 0
                    while c2 < 3 {
                        let idx2 = 136 + d2*3 + c2
                        var g2 = hd2 * probs2[c2]
                        if g2 > 0.3 { g2 = 0.3 } if g2 < 0.0-0.3 { g2 = 0.0-0.3 }
                        let m2 = (MOM[idx2] as f64)/100000000.0 * 0.9 + g2
                        MOM[idx2] = (m2 * 100000000.0) as i64
                        ws(idx2, wg(idx2) - 0.01 * m2)
                        c2 = c2 + 1
                    }
                    d2 = d2 + 1
                }
            } else {
                // Full BPTT with tiny A learning rate
                bptt_backward(cls, is_cross, 0.001)
            }
            s = s + 1
        }
        if ep % 10 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }

    // Eval
    rng_seed(99999, 11111)
    var correct = 0
    var s = 0
    while s < 200 {
        let cls = gen_sample(k)
        var d = 0
        while d < 8 { H[d] = 0; d = d + 1 }
        N_STEPS = 0
        var t = 0
        while t < k {
            forward_step(SQ[t] % 8, N_STEPS, is_cross)
            N_STEPS = N_STEPS + 1
            t = t + 1
        }
        t = 0
        while t < delay {
            forward_step(0, N_STEPS, is_cross)
            N_STEPS = N_STEPS + 1
            t = t + 1
        }
        compute_logits_3()
        if get_pred() == cls { correct = correct + 1 }
        s = s + 1
    }
    (correct as f64) / 200.0 * 100.0
}

fn gen_sorted_asc(k: i64) with Mut, Div {
    var i = 0
    while i < k { SQ[i] = (rng_next() / 100) % 100; i = i + 1 }
    i = 0
    while i < k {
        var j = 0
        while j < k - 1 - i {
            if SQ[j] > SQ[j+1] {
                let tmp = SQ[j]
                SQ[j] = SQ[j+1]
                SQ[j+1] = tmp
            }
            j = j + 1
        }
        i = i + 1
    }
}

fn gen_sorted_desc(k: i64) with Mut, Div {
    gen_sorted_asc(k)
    var i = 0
    while i < k / 2 {
        let tmp = SQ[i]
        SQ[i] = SQ[k - 1 - i]
        SQ[k - 1 - i] = tmp
        i = i + 1
    }
}

fn gen_unsorted(k: i64) with Mut, Div {
    var i = 0
    while i < k { SQ[i] = (rng_next() / 100) % 100; i = i + 1 }
    var ia = 1
    var id = 1
    i = 0
    while i < k - 1 {
        if SQ[i] > SQ[i+1] { ia = 0 }
        if SQ[i] < SQ[i+1] { id = 0 }
        i = i + 1
    }
    if ia == 1 { let tmp = SQ[0]; SQ[0] = SQ[1]; SQ[1] = tmp }
    if id == 1 { let tmp = SQ[0]; SQ[0] = SQ[1]; SQ[1] = tmp }
}

fn gen_sample(k: i64) -> i64 with Mut, Div {
    let cls = (rng_next() / 100) % 3
    if cls == 0 { gen_sorted_asc(k) }
    if cls == 1 { gen_sorted_desc(k) }
    if cls == 2 { gen_unsorted(k) }
    cls
}

fn init_embed() with Mut, Div {
    var i = 0
    while i < 8 {
        ws(i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0)
        i = i + 1
    }
}

fn init_A_cross() with Mut, Div {
    var i = 0
    while i < 64 {
        var v = ((rng_next() % 2000) as f64 - 1000.0) / 10000.0
        let row = i / 8
        let col = i - row * 8
        if row == col { v = 0.95 }
        ws(8 + i, v)
        i = i + 1
    }
}

fn init_A_diag() with Mut, Div {
    var i = 0
    while i < 64 { ws(8 + i, 0.0); i = i + 1 }
    i = 0
    while i < 8 { ws(8 + i * 8 + i, 0.95); i = i + 1 }
}

fn init_B_and_out() with Mut, Div {
    var i = 0
    while i < 8 {
        ws(72 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0)
        i = i + 1
    }
    i = 0
    while i < 24 {
        ws(80 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0)
        i = i + 1
    }
}

fn init_model(is_cross: i64) with Mut, Div {
    init_embed()
    if is_cross == 1 { init_A_cross() } else { init_A_diag() }
    init_B_and_out()
    var i = 0
    while i < 104 { MOM[i] = 0; i = i + 1 }
}

fn save_h(step: i64) with Mut {
    var d = 0
    while d < 8 { H_SAVE[step * 8 + d] = H[d]; d = d + 1 }
}

fn save_x(step: i64, val: f64) with Mut, Div {
    var d = 0
    while d < 8 {
        let inp = wg(d) * val
        X_SAVE[step * 8 + d] = (inp * 100000000.0) as i64
        d = d + 1
    }
}

fn fwd_step_cross(val: f64) with Mut, Div {
    var new_h: [f64; 8] = [0.0; 8]
    var d = 0
    while d < 8 {
        let inp = wg(d) * val
        var s = 0.0
        var j = 0
        while j < 8 { s = s + wg(8 + d * 8 + j) * hg(j); j = j + 1 }
        s = s + wg(72 + d) * inp
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        new_h[d] = s
        d = d + 1
    }
    d = 0
    while d < 8 { hs(d, new_h[d]); d = d + 1 }
}

fn fwd_step_diag(val: f64) with Mut, Div {
    var d = 0
    while d < 8 {
        let inp = wg(d) * val
        var s = wg(8 + d * 8 + d) * hg(d) + wg(72 + d) * inp
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        hs(d, s)
        d = d + 1
    }
}

fn model_step_save(val: f64, step: i64, is_cross: i64) with Mut, Div {
    save_h(step)
    save_x(step, val)
    if is_cross == 1 { fwd_step_cross(val) } else { fwd_step_diag(val) }
}

fn model_step(val: f64, is_cross: i64) with Mut, Div {
    if is_cross == 1 { fwd_step_cross(val) } else { fwd_step_diag(val) }
}

fn compute_logits() with Mut, Div {
    var c = 0
    while c < 3 {
        var s = 0.0
        var d = 0
        while d < 8 { s = s + hg(d) * wg(80 + d * 3 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn get_pred() -> i64 with Div {
    var best = 0
    var bv = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 3 {
        let v = (L[i] as f64) / 100000000.0
        if v > bv { bv = v; best = i }
        i = i + 1
    }
    best
}

fn compute_probs(tgt: i64) with Mut, Div, Panic {
    var mx = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 3 {
        let v = (L[i] as f64) / 100000000.0
        if v > mx { mx = v }
        i = i + 1
    }
    var se = 0.0
    i = 0
    while i < 3 {
        PROBS[i] = exp_q((L[i] as f64) / 100000000.0 - mx)
        se = se + PROBS[i]
        i = i + 1
    }
    i = 0
    while i < 3 { PROBS[i] = PROBS[i] / se; i = i + 1 }
    PROBS[tgt] = PROBS[tgt] - 1.0
}

fn update_output_only(tgt: i64, lr: f64) with Mut, Div, Panic {
    compute_probs(tgt)
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var c = 0
        while c < 3 {
            let idx = 80 + d * 3 + c
            var g = hd * PROBS[c]
            if g > 0.3 { g = 0.3 }
            if g < 0.0 - 0.3 { g = 0.0 - 0.3 }
            let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            c = c + 1
        }
        d = d + 1
    }
}

fn bptt_output_grad(tgt: i64, lr_out: f64) with Mut, Div, Panic {
    compute_probs(tgt)
    // Update output weights + compute dL/dh
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var dh_d = 0.0
        var c = 0
        while c < 3 {
            let idx = 80 + d * 3 + c
            var g = hd * PROBS[c]
            if g > 0.5 { g = 0.5 }
            if g < 0.0 - 0.5 { g = 0.0 - 0.5 }
            let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr_out * m)
            dh_d = dh_d + wg(80 + d * 3 + c) * PROBS[c]
            c = c + 1
        }
        DH[d] = (dh_d * 100000000.0) as i64
        d = d + 1
    }
}

fn bptt_accum_cross(t: i64) with Mut, Div {
    var d = 0
    while d < 8 {
        var dh_clip = (DH[d] as f64) / 100000000.0
        if dh_clip > 0.5 { dh_clip = 0.5 }
        if dh_clip < 0.0 - 0.5 { dh_clip = 0.0 - 0.5 }
        // dA[d,j] += dh_clip * h_t[j]
        var j = 0
        while j < 8 {
            let ht_j = (H_SAVE[t * 8 + j] as f64) / 100000000.0
            DA[d * 8 + j] = DA[d * 8 + j] + (dh_clip * ht_j * 100000000.0) as i64
            j = j + 1
        }
        // dB[d] += dh_clip * x_t[d]
        let xt_d = (X_SAVE[t * 8 + d] as f64) / 100000000.0
        DB[d] = DB[d] + (dh_clip * xt_d * 100000000.0) as i64
        d = d + 1
    }
}

fn bptt_accum_diag(t: i64) with Mut, Div {
    var d = 0
    while d < 8 {
        var dh_clip = (DH[d] as f64) / 100000000.0
        if dh_clip > 0.5 { dh_clip = 0.5 }
        if dh_clip < 0.0 - 0.5 { dh_clip = 0.0 - 0.5 }
        let ht_d = (H_SAVE[t * 8 + d] as f64) / 100000000.0
        DA[d * 8 + d] = DA[d * 8 + d] + (dh_clip * ht_d * 100000000.0) as i64
        let xt_d = (X_SAVE[t * 8 + d] as f64) / 100000000.0
        DB[d] = DB[d] + (dh_clip * xt_d * 100000000.0) as i64
        d = d + 1
    }
}

fn bptt_prop_cross() with Mut, Div {
    var new_dh: [f64; 8] = [0.0; 8]
    var d = 0
    while d < 8 {
        var j = 0
        while j < 8 {
            // A^T[d,j] = A[j,d] = wg(8 + j*8 + d)
            new_dh[d] = new_dh[d] + wg(8 + j * 8 + d) * ((DH[j] as f64) / 100000000.0)
            j = j + 1
        }
        if new_dh[d] > 1.0 { new_dh[d] = 1.0 }
        if new_dh[d] < 0.0 - 1.0 { new_dh[d] = 0.0 - 1.0 }
        d = d + 1
    }
    d = 0
    while d < 8 { DH[d] = (new_dh[d] * 100000000.0) as i64; d = d + 1 }
}

fn bptt_prop_diag() with Mut, Div {
    var d = 0
    while d < 8 {
        var nd = wg(8 + d * 8 + d) * ((DH[d] as f64) / 100000000.0)
        if nd > 1.0 { nd = 1.0 }
        if nd < 0.0 - 1.0 { nd = 0.0 - 1.0 }
        DH[d] = (nd * 100000000.0) as i64
        d = d + 1
    }
}

fn bptt_apply_A(lr_A: f64) with Mut, Div {
    let inv_t = 1.0 / (N_STEPS as f64)
    var i = 0
    while i < 64 {
        let g = (DA[i] as f64) / 100000000.0 * inv_t
        var gc = g
        if gc > 0.3 { gc = 0.3 }
        if gc < 0.0 - 0.3 { gc = 0.0 - 0.3 }
        let idx = 8 + i
        let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + gc
        MOM[idx] = (m * 100000000.0) as i64
        ws(idx, wg(idx) - lr_A * m)
        i = i + 1
    }
}

fn bptt_apply_B(lr_B: f64) with Mut, Div {
    let inv_t = 1.0 / (N_STEPS as f64)
    var i = 0
    while i < 8 {
        let g = (DB[i] as f64) / 100000000.0 * inv_t
        var gc = g
        if gc > 0.3 { gc = 0.3 }
        if gc < 0.0 - 0.3 { gc = 0.0 - 0.3 }
        let idx = 72 + i
        let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + gc
        MOM[idx] = (m * 100000000.0) as i64
        ws(idx, wg(idx) - lr_B * m)
        i = i + 1
    }
}

fn bptt_backward(tgt: i64, is_cross: i64, lr_A: f64, lr_out: f64) with Mut, Div, Panic {
    // Step 1: Output gradient + dL/dh_final
    bptt_output_grad(tgt, lr_out)

    // Step 2: Clear gradient accumulators
    var i = 0
    while i < 64 { DA[i] = 0; i = i + 1 }
    i = 0
    while i < 8 { DB[i] = 0; i = i + 1 }

    // Step 3: BPTT loop t = N_STEPS-1 down to 0
    var t = N_STEPS - 1
    while t >= 0 {
        if is_cross == 1 { bptt_accum_cross(t) } else { bptt_accum_diag(t) }
        if is_cross == 1 { bptt_prop_cross() } else { bptt_prop_diag() }
        t = t - 1
    }

    // Step 4: Apply gradients
    bptt_apply_A(lr_A)
    bptt_apply_B(lr_A)
}

fn forward_sample(k: i64, delay: i64, is_cross: i64, save: i64) with Mut, Div {
    var d = 0
    while d < 8 { H[d] = 0; d = d + 1 }
    N_STEPS = 0
    var t = 0
    while t < k {
        let val = (SQ[t] as f64) / 100.0
        if save == 1 {
            model_step_save(val, N_STEPS, is_cross)
        } else {
            model_step(val, is_cross)
        }
        N_STEPS = N_STEPS + 1
        t = t + 1
    }
    // Delay with zero input
    t = 0
    while t < delay {
        if save == 1 {
            model_step_save(0.0, N_STEPS, is_cross)
        } else {
            model_step(0.0, is_cross)
        }
        N_STEPS = N_STEPS + 1
        t = t + 1
    }
}

fn train_epoch_p1(k: i64, delay: i64, is_cross: i64, n_train: i64) -> i64 with Mut, Div, Panic {
    var correct = 0
    var s = 0
    while s < n_train {
        let cls = gen_sample(k)
        forward_sample(k, delay, is_cross, 0)
        compute_logits()
        if get_pred() == cls { correct = correct + 1 }
        update_output_only(cls, 0.01)
        s = s + 1
    }
    correct
}

fn train_epoch_p2(k: i64, delay: i64, is_cross: i64, n_train: i64) -> i64 with Mut, Div, Panic {
    var correct = 0
    var s = 0
    while s < n_train {
        let cls = gen_sample(k)
        forward_sample(k, delay, is_cross, 1)
        compute_logits()
        if get_pred() == cls { correct = correct + 1 }
        bptt_backward(cls, is_cross, 0.0005, 0.005)
        s = s + 1
    }
    correct
}

fn eval_model(k: i64, delay: i64, is_cross: i64) -> f64 with Mut, Div {
    rng_seed(99999 + k, 11111 + delay)
    var correct = 0
    var s = 0
    while s < 200 {
        let cls = gen_sample(k)
        forward_sample(k, delay, is_cross, 0)
        compute_logits()
        if get_pred() == cls { correct = correct + 1 }
        s = s + 1
    }
    (correct as f64) / 200.0 * 100.0
}

fn train_two_phase(is_cross: i64, k: i64, delay: i64) -> f64 with IO, Mut, Div, Panic {
    let n_train = 300
    let p1_epochs = 30
    let p2_epochs = 50
    var ep = 0

    // Phase 1: output-only
    while ep < p1_epochs {
        let correct = train_epoch_p1(k, delay, is_cross, n_train)
        if ep % 10 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    [P1] ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }

    // Phase 2: full BPTT
    var ep2 = 0
    while ep2 < p2_epochs {
        let correct = train_epoch_p2(k, delay, is_cross, n_train)
        if ep2 % 10 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    [P2] ep "); print_int(ep + ep2); print(" acc="); print(acc); print("%\n")
        }
        ep2 = ep2 + 1
    }

    let acc = eval_model(k, delay, is_cross)
    print("    Eval: "); print(acc); print("%\n")
    acc
}

fn train_output_only(is_cross: i64, k: i64, delay: i64) -> f64 with IO, Mut, Div, Panic {
    let n_train = 300
    let n_epochs = 50
    var ep = 0
    while ep < n_epochs {
        let correct = train_epoch_p1(k, delay, is_cross, n_train)
        if ep % 15 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }
    let acc = eval_model(k, delay, is_cross)
    print("    Eval: "); print(acc); print("%\n")
    acc
}

fn init_patterns() with Mut {
    // 6 permutations of {1,2,3}
    PAT[0]=1; PAT[1]=2; PAT[2]=3    // class 0
    PAT[3]=1; PAT[4]=3; PAT[5]=2    // class 1
    PAT[6]=2; PAT[7]=1; PAT[8]=3    // class 2
    PAT[9]=2; PAT[10]=3; PAT[11]=1  // class 3
    PAT[12]=3; PAT[13]=1; PAT[14]=2 // class 4
    PAT[15]=3; PAT[16]=2; PAT[17]=1 // class 5
    // 4 patterns with token 4
    PAT[18]=4; PAT[19]=1; PAT[20]=2 // class 6
    PAT[21]=1; PAT[22]=4; PAT[23]=3 // class 7
    PAT[24]=2; PAT[25]=4; PAT[26]=1 // class 8
    PAT[27]=4; PAT[28]=3; PAT[29]=1 // class 9
}

fn build_seq(pi: i64, delay: i64) with Mut {
    SEQ_LEN = 3 + delay
    SEQ_LABEL = pi
    let b = pi * 3
    SEQ[0] = PAT[b]
    SEQ[1] = PAT[b + 1]
    SEQ[2] = PAT[b + 2]
    var i = 3
    while i < SEQ_LEN { SEQ[i] = 0; i = i + 1 }
}

fn init_embed() with Mut, Div, Panic {
    var i = 0
    while i < 40 { ws(i, rand_normal() * 0.3); i = i + 1 }
}

fn init_cross_a() with Mut, Div, Panic {
    var i = 0
    while i < 64 {
        var v = rand_normal() * 0.12
        let row = i / 8
        let col = i - row * 8
        if row == col { v = 0.95 + rand_normal() * 0.01 }
        ws(40 + i, v)
        i = i + 1
    }
}

fn init_diag_a() with Mut, Div, Panic {
    var i = 0
    while i < 8 { ws(40 + i, 0.95 + rand_normal() * 0.01); i = i + 1 }
    i = 8
    while i < 64 { ws(40 + i, 0.0); i = i + 1 }
}

fn init_b_out() with Mut, Div, Panic {
    var i = 0
    while i < 8 { ws(104 + i, rand_normal() * 0.3); i = i + 1 }
    i = 0
    while i < 80 { ws(112 + i, rand_normal() * 0.3); i = i + 1 }
}

fn cross_step(tok: i64) with Mut, Div {
    // Save old H
    var d = 0
    while d < 8 { OLD_H[d] = H[d]; d = d + 1 }
    // h_new[d] = sum_j A[d,j]*h_old[j] + B[d]*embed[tok,d]
    d = 0
    while d < 8 {
        var s = 0.0
        var j = 0
        while j < 8 {
            s = s + wg(40 + d * 8 + j) * ((OLD_H[j] as f64) / 100000000.0)
            j = j + 1
        }
        s = s + wg(104 + d) * wg(tok * 8 + d)
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        hs(d, s)
        d = d + 1
    }
}

fn diag_step(tok: i64) with Mut, Div {
    var d = 0
    while d < 8 { OLD_H[d] = H[d]; d = d + 1 }
    d = 0
    while d < 8 {
        var s = wg(40 + d) * ((OLD_H[d] as f64) / 100000000.0) + wg(104 + d) * wg(tok * 8 + d)
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        hs(d, s)
        d = d + 1
    }
}

fn compute_logits_10() with Mut, Div {
    var c = 0
    while c < 10 {
        var s = 0.0
        var d = 0
        while d < 8 { s = s + hg(d) * wg(112 + d * 10 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn cross_forward(delay: i64, pi: i64) with Mut, Div {
    build_seq(pi, delay)
    reset_h()
    var t = 0
    while t < SEQ_LEN { cross_step(SEQ[t]); t = t + 1 }
    compute_logits_10()
}

fn diag_forward(delay: i64, pi: i64) with Mut, Div {
    build_seq(pi, delay)
    reset_h()
    var t = 0
    while t < SEQ_LEN { diag_step(SEQ[t]); t = t + 1 }
    compute_logits_10()
}

fn compute_grads_10(tgt: i64) with Mut, Div, Panic {
    var mx = (L[0] as f64) / 100000000.0
    var c = 1
    while c < 10 {
        let lc = (L[c] as f64) / 100000000.0
        if lc > mx { mx = lc }
        c = c + 1
    }
    var sm = 0.0
    c = 0
    while c < 10 { sm = sm + exp_q((L[c] as f64) / 100000000.0 - mx); c = c + 1 }
    c = 0
    while c < 10 {
        let p = exp_q((L[c] as f64) / 100000000.0 - mx) / sm
        var g = p
        if c == tgt { g = g - 1.0 }
        GRAD_L[c] = (g * 100000000.0) as i64
        c = c + 1
    }
}

fn update_output_10(lr: f64) with Mut, Div {
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var c = 0
        while c < 10 {
            let gl = (GRAD_L[c] as f64) / 100000000.0
            ws(112 + d * 10 + c, wg(112 + d * 10 + c) - lr * hd * gl)
            c = c + 1
        }
        d = d + 1
    }
}

fn update_cross_ab(lr: f64) with Mut, Div {
    var d = 0
    while d < 8 {
        var dh = 0.0
        var c = 0
        while c < 10 {
            dh = dh + wg(112 + d * 10 + c) * ((GRAD_L[c] as f64) / 100000000.0)
            c = c + 1
        }
        if dh > 0.3 { dh = 0.3 }
        if dh < 0.0 - 0.3 { dh = 0.0 - 0.3 }
        // B update
        ws(104 + d, wg(104 + d) - lr * dh * 0.5)
        // A update (cross: full matrix row d)
        var j = 0
        while j < 8 {
            let oh = (OLD_H[j] as f64) / 100000000.0
            ws(40 + d * 8 + j, wg(40 + d * 8 + j) - lr * dh * oh * 0.08)
            j = j + 1
        }
        d = d + 1
    }
}

fn update_diag_ab(lr: f64) with Mut, Div {
    var d = 0
    while d < 8 {
        var dh = 0.0
        var c = 0
        while c < 10 {
            dh = dh + wg(112 + d * 10 + c) * ((GRAD_L[c] as f64) / 100000000.0)
            c = c + 1
        }
        if dh > 0.3 { dh = 0.3 }
        if dh < 0.0 - 0.3 { dh = 0.0 - 0.3 }
        ws(104 + d, wg(104 + d) - lr * dh * 0.5)
        let oh = (OLD_H[d] as f64) / 100000000.0
        ws(40 + d, wg(40 + d) - lr * dh * oh * 0.08)
        d = d + 1
    }
}

fn epoch_cross(delay: i64, lr: f64) with Mut, Div, Panic {
    var pi = 0
    while pi < 10 {
        cross_forward(delay, pi)
        compute_grads_10(pi)
        update_output_10(lr)
        update_cross_ab(lr)
        pi = pi + 1
    }
}

fn epoch_diag(delay: i64, lr: f64) with Mut, Div, Panic {
    var pi = 0
    while pi < 10 {
        diag_forward(delay, pi)
        compute_grads_10(pi)
        update_output_10(lr)
        update_diag_ab(lr)
        pi = pi + 1
    }
}

fn eval_cross(delay: i64) -> i64 with Mut, Div, Panic {
    var correct = 0
    var pi = 0
    while pi < 10 {
        cross_forward(delay, pi)
        var best = 0
        var bv = (L[0] as f64)
        var c = 1
        while c < 10 {
            if (L[c] as f64) > bv { bv = (L[c] as f64); best = c }
            c = c + 1
        }
        if best == pi { correct = correct + 1 }
        pi = pi + 1
    }
    correct
}

fn eval_diag(delay: i64) -> i64 with Mut, Div, Panic {
    var correct = 0
    var pi = 0
    while pi < 10 {
        diag_forward(delay, pi)
        var best = 0
        var bv = (L[0] as f64)
        var c = 1
        while c < 10 {
            if (L[c] as f64) > bv { bv = (L[c] as f64); best = c }
            c = c + 1
        }
        if best == pi { correct = correct + 1 }
        pi = pi + 1
    }
    correct
}

fn train_cross_full(delay: i64, epochs: i64, lr: f64) with Mut, Div, Panic {
    // Phase 1: warmup at D=2 (learn embeddings + output)
    var e = 0
    while e < 150 { epoch_cross(2, lr * 2.0); e = e + 1 }
    // Phase 2: bridge at D=delay/2
    let half = delay / 2
    e = 0
    while e < 100 { epoch_cross(half, lr * 1.5); e = e + 1 }
    // Phase 3: main training at target delay
    e = 0
    while e < epochs { epoch_cross(delay, lr); e = e + 1 }
}

fn train_diag_full(delay: i64, epochs: i64, lr: f64) with Mut, Div, Panic {
    var e = 0
    while e < 150 { epoch_diag(2, lr * 2.0); e = e + 1 }
    let half = delay / 2
    e = 0
    while e < 100 { epoch_diag(half, lr * 1.5); e = e + 1 }
    e = 0
    while e < epochs { epoch_diag(delay, lr); e = e + 1 }
}

fn run_exp(delay: i64, ri: i64, epochs: i64, lr: f64) with IO, Mut, Div, Panic {
    print("\n── Delay D="); print_int(delay); print(" (150+100 curriculum + "); print_int(epochs); print(" main) ──\n")

    rng_seed(77777, 33333)
    init_cross()
    train_cross_full(delay, epochs, lr)
    let cc = eval_cross(delay)
    RESULTS[ri] = cc
    print("  O-SSM: "); print_int(cc); print("/10 = "); print((cc as f64) * 10.0); print("%\n")

    rng_seed(77777, 33333)
    init_diag()
    train_diag_full(delay, epochs, lr)
    let dc = eval_diag(delay)
    RESULTS[ri + 1] = dc
    print("  Diag:  "); print_int(dc); print("/10 = "); print((dc as f64) * 10.0); print("%\n")

    if cc > dc { print("  >> O-SSM WINS\n") }
    else { if cc == dc { print("  >> TIE\n") }
    else { print("  >> Diag wins\n") } }
}

