fn verify_moufang_exhaustive() -> i64 with Mut, IO {
    var pass_count = 0
    var fail_count = 0

    var x = 1
    while x < 8 {
        var y = 1
        while y < 8 {
            var z = 1
            while z < 8 {
                // LHS: (x·y)·(z·x)
                basis_mul(x, 1, y, 1)
                let xy_idx = RES_IDX
                let xy_sgn = RES_SGN
                basis_mul(z, 1, x, 1)
                let zx_idx = RES_IDX
                let zx_sgn = RES_SGN
                basis_mul(xy_idx, xy_sgn, zx_idx, zx_sgn)
                let lhs_idx = RES_IDX
                let lhs_sgn = RES_SGN

                // RHS: x·((y·z)·x)
                basis_mul(y, 1, z, 1)
                let yz_idx = RES_IDX
                let yz_sgn = RES_SGN
                basis_mul(yz_idx, yz_sgn, x, 1)
                let yzx_idx = RES_IDX
                let yzx_sgn = RES_SGN
                basis_mul(x, 1, yzx_idx, yzx_sgn)
                let rhs_idx = RES_IDX
                let rhs_sgn = RES_SGN

                if lhs_idx == rhs_idx {
                    if lhs_sgn == rhs_sgn {
                        pass_count = pass_count + 1
                    } else {
                        fail_count = fail_count + 1
                    }
                } else {
                    fail_count = fail_count + 1
                }

                z = z + 1
            }
            y = y + 1
        }
        x = x + 1
    }

    print("  Checked "); print_int(pass_count + fail_count); print(" triples\n")
    print("  Moufang identity satisfied: "); print_int(pass_count); print("\n")
    print("  Moufang identity violated: "); print_int(fail_count); print("\n")

    if fail_count == 0 {
        print("  [PASS] Moufang identity holds for ALL 343 basis triples\n")
        1
    } else {
        print("  [FAIL] Moufang violations found\n")
        0
    }
}

