fn test_order() with IO, Mut, Div {
    // Feed [0,1] vs [1,0] and compare hidden states
    print("\n--- Order Sensitivity Test ---\n")

    // Sequence A: [0, 1]
    H[0] = 0; H[1] = 0; H[2] = 0; H[3] = 0
    cross_fwd(0)
    cross_fwd(1)
    let ha0 = hg(0)
    let ha1 = hg(1)
    let ha2 = hg(2)
    let ha3 = hg(3)

    // Sequence B: [1, 0]
    H[0] = 0; H[1] = 0; H[2] = 0; H[3] = 0
    cross_fwd(1)
    cross_fwd(0)
    let hb0 = hg(0)
    let hb1 = hg(1)
    let hb2 = hg(2)
    let hb3 = hg(3)

    // Compute L2 distance
    let d0 = ha0 - hb0
    let d1 = ha1 - hb1
    let d2 = ha2 - hb2
    let d3 = ha3 - hb3
    let cross_dist = d0*d0 + d1*d1 + d2*d2 + d3*d3

    print("  Cross-dim [0,1] vs [1,0] state distance: "); print(cross_dist); print("\n")

    // Now diagonal
    H[0] = 0; H[1] = 0; H[2] = 0; H[3] = 0
    diag_fwd(0)
    diag_fwd(1)
    let da0 = hg(0)
    let da1 = hg(1)
    let da2 = hg(2)
    let da3 = hg(3)

    H[0] = 0; H[1] = 0; H[2] = 0; H[3] = 0
    diag_fwd(1)
    diag_fwd(0)
    let db0 = hg(0)
    let db1 = hg(1)
    let db2 = hg(2)
    let db3 = hg(3)

    let dd0 = da0 - db0
    let dd1 = da1 - db1
    let dd2 = da2 - db2
    let dd3 = da3 - db3
    let diag_dist = dd0*dd0 + dd1*dd1 + dd2*dd2 + dd3*dd3

    print("  Diagonal [0,1] vs [1,0] state distance: "); print(diag_dist); print("\n")

    if cross_dist > diag_dist {
        print("  CROSS-DIM more order-sensitive (ratio: ")
        // Avoid div by zero
        if diag_dist > 0.0001 {
            print(cross_dist / diag_dist)
        } else {
            print("inf")
        }
        print("x)\n")
    } else {
        print("  DIAGONAL more order-sensitive\n")
    }
}

