}

fn exp_o(x: f64) -> f64 with Mut, Div, Panic {
    if x > 15.0 { return exp_o(7.5) * exp_o(x - 7.5) }
    if x < 0.0 - 15.0 { return 0.0 }
    var sum = 1.0
    var term = 1.0
    var i = 1
    while i <= 20 { term = term * x / (i as f64); sum = sum + term; i = i + 1 }
    sum
}

fn log_o(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 50.0 }
    var v = (x - 1.0) / (x + 1.0)
    let v2 = v * v
    var sum = v
    var pow = v
    var i = 1
    while i <= 10 { pow = pow * v2; sum = sum + pow / (2.0 * (i as f64) + 1.0); i = i + 1 }
    2.0 * sum
}

fn init_weights() with Mut, Div, Panic {
    var i = 0
    while i < 200 { w_set(i, rand_normal() * 0.15); i = i + 1 }
    // SSM_A (offset 80..87): initialize near 0.9 for stable recurrence
    i = 0
    while i < 8 { w_set(80 + i, 0.9 + rand_normal() * 0.05); i = i + 1 }
}

fn oct_mul() with Mut {
    // Full octonion product using Fano plane
    // a = OCT_A, b = OCT_B, result in OCT_R
    let a0 = OCT_A[0]; let a1 = OCT_A[1]; let a2 = OCT_A[2]; let a3 = OCT_A[3]
    let a4 = OCT_A[4]; let a5 = OCT_A[5]; let a6 = OCT_A[6]; let a7 = OCT_A[7]
    let b0 = OCT_B[0]; let b1 = OCT_B[1]; let b2 = OCT_B[2]; let b3 = OCT_B[3]
    let b4 = OCT_B[4]; let b5 = OCT_B[5]; let b6 = OCT_B[6]; let b7 = OCT_B[7]

    // Real part
    OCT_R[0] = a0*b0 - a1*b1 - a2*b2 - a3*b3 - a4*b4 - a5*b5 - a6*b6 - a7*b7
    // Imaginary parts (Fano plane structure)
    OCT_R[1] = a0*b1 + a1*b0 + a2*b4 - a4*b2 + a3*b7 - a7*b3 - a6*b5 + a5*b6
    OCT_R[2] = a0*b2 + a2*b0 + a3*b5 - a5*b3 + a4*b1 - a1*b4 - a7*b6 + a6*b7
    OCT_R[3] = a0*b3 + a3*b0 + a4*b6 - a6*b4 + a5*b2 - a2*b5 - a1*b7 + a7*b1
    OCT_R[4] = a0*b4 + a4*b0 + a5*b7 - a7*b5 + a6*b3 - a3*b6 - a2*b1 + a1*b2
    OCT_R[5] = a0*b5 + a5*b0 + a6*b1 - a1*b6 + a7*b4 - a4*b7 - a3*b2 + a2*b3
    OCT_R[6] = a0*b6 + a6*b0 + a7*b2 - a2*b7 + a1*b5 - a5*b1 - a4*b3 + a3*b4
    OCT_R[7] = a0*b7 + a7*b0 + a1*b3 - a3*b1 + a2*b6 - a6*b2 - a5*b4 + a4*b5
}

fn ossm_step(char_idx: i64) with Mut, Div, Panic {
    // Embed: lookup 10→8
    var d = 0
    while d < 8 {
        OCT_B[d] = w_get(char_idx * 8 + d)
        d = d + 1
    }

    // SSM: h = oct_mul(A*h, B*input)
    // Load A-scaled state into OCT_A
    d = 0
    while d < 8 {
        OCT_A[d] = w_get(80 + d) * H_STATE[d]
        d = d + 1
    }
    // Scale input by SSM_B
    d = 0
    while d < 8 {
        OCT_B[d] = w_get(88 + d) * OCT_B[d]
        d = d + 1
    }
    // Octonion multiply (NON-ASSOCIATIVE)
    oct_mul()
    // Update state: h = result + residual
    d = 0
    while d < 8 {
        H_STATE[d] = OCT_R[d] + OCT_B[d] * 0.1  // small residual
        d = d + 1
    }

    // Output: 8→10 linear
    var v = 0
    while v < 10 {
        var s = 0.0
        d = 0
        while d < 8 { s = s + H_STATE[d] * w_get(96 + d * 10 + v); d = d + 1 }
        LOGITS[v] = (s * 100000000.0) as i64
        v = v + 1
    }
}

fn qssm_step(char_idx: i64) with Mut, Div, Panic {
    // Embed
    var d = 0
    var inp: [f64; 8] = [0.0; 8]
    while d < 8 {
        inp[d] = w_get(char_idx * 8 + d)
        d = d + 1
    }

    // SSM: h = A*h + B*input (ASSOCIATIVE — element-wise, no cross-dim interaction)
    d = 0
    while d < 8 {
        H_STATE[d] = w_get(80 + d) * H_STATE[d] + w_get(88 + d) * inp[d]
        d = d + 1
    }

    // Output: 8→10 linear
    var v = 0
    while v < 10 {
        var s = 0.0
        d = 0
        while d < 8 { s = s + H_STATE[d] * w_get(96 + d * 10 + v); d = d + 1 }
        LOGITS[v] = (s * 100000000.0) as i64
        v = v + 1
    }
}

fn compute_loss(target: i64) -> f64 with Mut, Div, Panic {
    // Softmax
    var max_l = (LOGITS[0] as f64) / 100000000.0
    var v = 1
    while v < 10 {
        let lv = (LOGITS[v] as f64) / 100000000.0
        if lv > max_l { max_l = lv }
        v = v + 1
    }
    var sum_exp = 0.0
    v = 0
    while v < 10 {
        sum_exp = sum_exp + exp_o((LOGITS[v] as f64) / 100000000.0 - max_l)
        v = v + 1
    }
    let p = exp_o((LOGITS[target] as f64) / 100000000.0 - max_l) / sum_exp
    if p < 0.0000001 { return 16.0 }
    0.0 - log_o(p)
}

fn train_output_layer(target: i64, lr: f64) with Mut, Div, Panic {
    // Softmax probs
    var max_l = (LOGITS[0] as f64) / 100000000.0
    var v = 1
    while v < 10 {
        let lv = (LOGITS[v] as f64) / 100000000.0
        if lv > max_l { max_l = lv }
        v = v + 1
    }
    var sum_exp = 0.0
    var probs: [f64; 10] = [0.0; 10]
    v = 0
    while v < 10 {
        probs[v] = exp_o((LOGITS[v] as f64) / 100000000.0 - max_l)
        sum_exp = sum_exp + probs[v]
        v = v + 1
    }
    v = 0
    while v < 10 { probs[v] = probs[v] / sum_exp; v = v + 1 }

    // Gradient: dL/dW_out[d][v] = h[d] * (prob[v] - target_v)
    v = 0
    while v < 10 {
        var g = probs[v]
        if v == target { g = g - 1.0 }
        var d = 0
        while d < 8 {
            let idx = 96 + d * 10 + v
            w_set(idx, w_get(idx) - lr * H_STATE[d] * g)
            d = d + 1
        }
        v = v + 1
    }
}

fn run_model(use_oct: i64, label_str: i64) -> f64 with IO, Mut, Div, Panic {
    rng_seed(77777777, 33333333)
    init_weights()

    // Reset state
    var d = 0
    while d < 8 { H_STATE[d] = 0.0; d = d + 1 }

    // Training: 20 epochs over the sequence
    let lr = 0.02
    let train_len = 40  // first 40 bigrams
    var ep = 0
    var init_loss = 0.0
    var final_loss = 0.0

    while ep < 20 {
        var total_loss = 0.0
        // Reset state each epoch
        d = 0
        while d < 8 { H_STATE[d] = 0.0; d = d + 1 }

        var ti = 0
        while ti < train_len {
            let c = SEQ[ti]
            let next_c = SEQ[ti + 1]
            if use_oct == 1 { ossm_step(c) }
            else { qssm_step(c) }
            total_loss = total_loss + compute_loss(next_c)
            train_output_layer(next_c, lr)
            ti = ti + 1
        }

        let avg = total_loss / (train_len as f64)
        if ep == 0 { init_loss = avg }
        if ep == 19 { final_loss = avg }
        if ep % 5 == 0 {
            print("  ep "); print_int(ep); print(" loss="); print(avg); print("\n")
        }
        ep = ep + 1
    }

    let decrease = (init_loss - final_loss) / init_loss * 100.0
    if use_oct == 1 { print("  O-SSM") } else { print("  Q-SSM") }
    print(": loss "); print(init_loss); print(" → "); print(final_loss)
    print(" ("); print(decrease); println("% decrease)")

    final_loss
}

fn diag_step(c: i64) with Mut, Div {
    // Element-wise (diagonal, no coupling)
    var d = 0
    while d < 4 {
        let inp = wg(c * 4 + d)
        let hv = (H[d] as f64) / 100000000.0
        H[d] = ((wg(8+d)*hv + wg(12+d)*inp) * 100000000.0) as i64
        d = d + 1
    }
    var v = 0
    while v < 2 {
        var s = 0.0
        d = 0
        while d < 4 { s = s + (H[d] as f64) / 100000000.0 * wg(16 + d*2 + v); d = d + 1 }
        L[v] = (s * 100000000.0) as i64
        v = v + 1
    }
}

fn setup() with Mut, Div, Panic {
    // Binary sequence
    rng_seed(42424242, 13131313)
    var i = 0
    while i < 60 { SQ[i] = (rng_next() / 100) % 2; i = i + 1 }
    TG[0] = SQ[0]
    i = 1
    while i < 60 {
        var x = SQ[i] + SQ[i - 1]
        if x == 2 { x = 0 }
        TG[i] = x
        i = i + 1
    }
}

fn init_model() with Mut, Div, Panic {
    var i = 0
    while i < 8 { ws(i, rand_normal() * 0.3); i = i + 1 }
    i = 0
    while i < 4 { ws(8+i, 0.9 + rand_normal()*0.05); i = i + 1 }
    i = 0
    while i < 4 { ws(12+i, rand_normal() * 0.3); i = i + 1 }
    i = 0
    while i < 8 { ws(16+i, rand_normal() * 0.3); i = i + 1 }
}

fn train_cross() -> f64 with IO, Mut, Div, Panic {
    var final_loss = 0.0
    var ep = 0
    while ep < 50 {
        H[0]=0; H[1]=0; H[2]=0; H[3]=0
        var tl = 0.0
        var ti = 0
        while ti < 50 { cross_step(SQ[ti]); tl = tl + step_loss(TG[ti], 0.05); ti = ti + 1 }
        final_loss = tl / 50.0
        if ep % 10 == 0 { print("  ep "); print_int(ep); print(" loss="); print(final_loss); print("\n") }
        ep = ep + 1
    }
    final_loss
}

fn train_diag() -> f64 with IO, Mut, Div, Panic {
    var final_loss = 0.0
    var ep = 0
    while ep < 50 {
        H[0]=0; H[1]=0; H[2]=0; H[3]=0
        var tl = 0.0
        var ti = 0
        while ti < 50 { diag_step(SQ[ti]); tl = tl + step_loss(TG[ti], 0.05); ti = ti + 1 }
        final_loss = tl / 50.0
        if ep % 10 == 0 { print("  ep "); print_int(ep); print(" loss="); print(final_loss); print("\n") }
        ep = ep + 1
    }
    final_loss
}

fn is_palindrome_check(k: i64) -> i64 {
    var i = 0
    while i < k / 2 {
        if SEQ[i] != SEQ[k - 1 - i] { return 0 }
        i = i + 1
    }
    1
}

fn generate_palindrome(k: i64) with Mut, Div {
    // Generate first half, mirror to second half
    let half = k / 2
    var i = 0
    while i < half {
        SEQ[i] = (rng_next() / 100) % 6 + 1
        i = i + 1
    }
    // Mirror
    i = 0
    while i < half {
        SEQ[k - 1 - i] = SEQ[i]
        i = i + 1
    }
    // If odd length, fill center
    if k - half * 2 > 0 {
        SEQ[half] = (rng_next() / 100) % 6 + 1
    }
}

fn generate_non_palindrome(k: i64) with Mut, Div {
    // Random sequence, reject if accidentally palindrome
    var attempts = 0
    var done = 0
    while done == 0 {
        var i = 0
        while i < k { SEQ[i] = (rng_next() / 100) % 6 + 1; i = i + 1 }
        if is_palindrome_check(k) == 0 { done = 1 }
        attempts = attempts + 1
        if attempts > 20 {
            // Force non-palindrome by flipping last token
            if SEQ[0] == SEQ[k - 1] {
                var nv = SEQ[k - 1] + 1
                if nv > 6 { nv = 1 }
                SEQ[k - 1] = nv
            }
            done = 1
        }
    }
}

fn generate_sample(k: i64) -> i64 with Mut, Div {
    let cls = (rng_next() / 100) % 2
    if cls == 1 { generate_palindrome(k) }
    if cls == 0 { generate_non_palindrome(k) }
    SEQ_LEN = k
    cls
}

fn init_embed() with Mut, Div {
    var i = 0
    while i < 56 { ws(i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
}

fn init_b_out() with Mut, Div {
    var i = 0
    while i < 8 { ws(120 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 16 { ws(128 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
}

fn init_model(is_cross: i64) with Mut, Div {
    init_embed()
    init_a_matrix(is_cross)
    init_b_out()
    var i = 0
    while i < 144 { MOM[i] = 0; i = i + 1 }
}

fn model_step_diag(token: i64) with Mut, Div {
    var d = 0
    while d < 8 {
        var s = wg(56 + d) * hg(d) + wg(120 + d) * wg(token * 8 + d)
        if s > 5.0 { s = 5.0 } if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        hs(d, s); d = d + 1
    }
}

fn compute_logits() with Mut, Div {
    var c = 0
    while c < 2 {
        var s = 0.0
        var d = 0
        while d < 8 { s = s + hg(d) * wg(128 + d*2 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn run_config(is_cross: i64, k: i64) -> f64 with IO, Mut, Div, Panic {
    rng_seed(55555 + k * 100, 77777 + k * 100)
    init_model(is_cross)

    let n_train = 300
    let n_epochs = 50
    rng_seed(12345 + k * 10, 67890 + k * 10)

    var ep = 0
    while ep < n_epochs {
        var correct = 0
        var s = 0
        while s < n_train {
            let cls = generate_sample(k)
            var d = 0
            while d < 8 { H[d] = 0; d = d + 1 }
            var t = 0
            while t < SEQ_LEN {
                model_step(SEQ[t], is_cross)
                t = t + 1
            }
            compute_logits()
            if get_pred() == cls { correct = correct + 1 }
            update_output(cls, 0.01)
            s = s + 1
        }
        if ep % 15 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }

    // Evaluate
    rng_seed(99999 + k, 11111 + k)
    var correct = 0
    var s = 0
    while s < 200 {
        let cls = generate_sample(k)
        var d = 0
        while d < 8 { H[d] = 0; d = d + 1 }
        var t = 0
        while t < SEQ_LEN { model_step(SEQ[t], is_cross); t = t + 1 }
        compute_logits()
        if get_pred() == cls { correct = correct + 1 }
        s = s + 1
    }
    let acc = (correct as f64) / 200.0 * 100.0
    print("    Eval: "); print(acc); print("%\n")
    acc
}

fn ld_exp(x: f64) -> f64 {
    var arg = x
    if arg > 500.0 { return 1.0e200 }
    if arg < 0.0 - 500.0 { return 0.0 }
    var halvings = 0
    while arg > 1.0 { arg = arg * 0.5; halvings = halvings + 1 }
    while arg < 0.0 - 1.0 { arg = arg * 0.5; halvings = halvings + 1 }
    var sum = 1.0
    var term = 1.0
    var i = 1
    while i <= 30 { term = term * arg / (i as f64); sum = sum + term; i = i + 1 }
    i = 0
    while i < halvings { sum = sum * sum; i = i + 1 }
    return sum
}

fn ld_sqrt(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    var g = x * 0.5
    if g < 0.001 { g = 0.001 }
    var i = 0
    while i < 20 { g = (g + x / g) * 0.5; i = i + 1 }
    return g
}

fn ld_log(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    var y = 0.0
    var tmp = x
    while tmp > 2.718281828 { y = y + 1.0; tmp = tmp / 2.718281828 }
    while tmp < 1.0 { y = y - 1.0; tmp = tmp * 2.718281828 }
    var i = 0
    while i < 20 {
        let ey = ld_exp(y)
        if ey < 1.0e-300 { return y }
        let correction = 2.0 * (x - ey) / (x + ey)
        y = y + correction
        i = i + 1
    }
    return y
}

fn ld_pow(base: f64, exponent: f64) -> f64 {
    if base <= 0.0 { return 0.0 }
    return ld_exp(exponent * ld_log(base))
}

fn css_avg(ke: f64) -> f64 {
    // C_ss_avg = F * dose / (Vd * ke * tau)
    // F=0.95, dose=5, Vd=10, tau=24
    return 0.95 * 5.0 / (10.0 * ke * 24.0)
}

fn inr_linear(ke: f64) -> f64 {
    // INR = 1.0 + 2.7 * C_ss
    return 1.0 + 2.7 * css_avg(ke)
}

fn inr_emax(ke: f64, ec50: f64, gamma: f64, inr_max: f64) -> f64 {
    let c = css_avg(ke)
    let cg = ld_pow(c, gamma)
    let eg = ld_pow(ec50, gamma)
    return 1.0 + inr_max * cg / (eg + cg)
}

fn calibrate_inr_max(ec50: f64, gamma: f64) -> f64 {
    let c_ref = css_avg(0.035)
    let target_inr_increment = inr_linear(0.035) - 1.0  // ~1.527
    let frac = ld_pow(c_ref, gamma) / (ld_pow(ec50, gamma) + ld_pow(c_ref, gamma))
    return target_inr_increment / frac
}

fn simulate_pbpk_dt(ke: f64, dose: f64, dt: f64, n_steps: i32) -> Sed16 {
    var state = sed_zero()
    state.e5 = dose / 1.0  // all drug in gut
    let ka = 1.5
    var step = 0
    while step < n_steps {
        let rates = sed_pbpk_rates(state, ke, ka)
        // Euler step: state += rates * dt
        state = Sed16 {
            e0: state.e0 + rates.e0 * dt, e1: state.e1 + rates.e1 * dt,
            e2: state.e2 + rates.e2 * dt, e3: state.e3 + rates.e3 * dt,
            e4: state.e4 + rates.e4 * dt, e5: state.e5 + rates.e5 * dt,
            e6: state.e6 + rates.e6 * dt, e7: state.e7 + rates.e7 * dt,
            e8: state.e8 + rates.e8 * dt, e9: state.e9 + rates.e9 * dt,
            e10: 0.0, e11: 0.0, e12: 0.0, e13: 0.0, e14: 0.0, e15: 0.0
        }
        state = clamp_neg(state)
        step = step + 1
    }
    return state
}

