fn calculate_fu_mic(fu_plasma: f64, logp: f64) -> f64 {
    let log_fu_mic_fu_inc = 0.53 * logp - 0.49
    let fu_mic_fu_inc = pow(10.0, log_fu_mic_fu_inc)
    let fu_mic = 1.0 / (1.0 + fu_mic_fu_inc * (1.0 / fu_plasma - 1.0))

    if fu_mic < 0.001 { return 0.001 }
    if fu_mic > 1.0 { return 1.0 }
    return fu_mic
}

fn scale_clint_ivive(
    clint_in_vitro: f64,
    fu_mic: f64,
    fu_plasma: f64,
    isef: f64,
    physiology: Physiology
) -> f64 {
    let mppgl = physiology.mppgl
    let liver_weight = physiology.liver_weight_g

    // Correct for microsomal binding
    let clint_unbound = clint_in_vitro / fu_mic

    // Scale to whole liver
    let clint_liver = clint_unbound * mppgl * liver_weight * isef

    // Convert mL/min to L/h
    let clint_lph = clint_liver * 0.06

    // Apply plasma binding
    let clint_plasma = clint_lph * fu_plasma

    return clint_plasma
}

fn hepatic_clearance_well_stirred(
    clint_lph: f64,
    qh_lph: f64,
    fu_blood: f64,
    rb: f64
) -> f64 {
    let fu_b = fu_blood / rb
    let clh = (qh_lph * fu_b * clint_lph) / (qh_lph + fu_b * clint_lph)
    return clh
}

fn competitive_inhibition(i_unbound_um: f64, ki_um: f64) -> f64 {
    return 1.0 + i_unbound_um / ki_um
}

fn noncompetitive_inhibition(i_unbound_um: f64, ki_um: f64) -> f64 {
    return 1.0 + i_unbound_um / ki_um
}

fn mixed_inhibition(i_unbound_um: f64, ki_um: f64, alpha: f64) -> f64 {
    let ki_prime = ki_um * alpha
    return (1.0 + i_unbound_um / ki_um) / (1.0 + i_unbound_um / ki_prime)
}

fn mechanism_based_inhibition(
    i_unbound_um: f64,
    kinact_per_min: f64,
    ki_mbi_um: f64,
    kdeg_per_h: f64
) -> f64 {
    let kdeg_per_min = kdeg_per_h / 60.0
    let r_mbi = 1.0 + (kinact_per_min * i_unbound_um) / (kdeg_per_min * (ki_mbi_um + i_unbound_um))
    return r_mbi
}

fn get_kdeg(enzyme_id: i32, halflife: CYPHalfLife) -> f64 {
    let t_half = if enzyme_id == CYP3A4() { halflife.cyp3a4 }
                 else if enzyme_id == CYP2D6() { halflife.cyp2d6 }
                 else if enzyme_id == CYP2C9() { halflife.cyp2c9 }
                 else if enzyme_id == CYP2C19() { halflife.cyp2c19 }
                 else if enzyme_id == CYP1A2() { halflife.cyp1a2 }
                 else { 36.0 }
    return 0.693 / t_half
}

fn calculate_r_value(
    inhibitor: InhibitorParams,
    enzyme_id: i32,
    halflife: CYPHalfLife
) -> f64 {
    let i_unbound = inhibitor.cmax_unbound_um
    let ki = inhibitor.ki_um

    if inhibitor.inhibition_type == COMPETITIVE() {
        return competitive_inhibition(i_unbound, ki)
    } else if inhibitor.inhibition_type == NONCOMPETITIVE() {
        return noncompetitive_inhibition(i_unbound, ki)
    } else if inhibitor.inhibition_type == MIXED() {
        return mixed_inhibition(i_unbound, ki, 1.0)
    } else if inhibitor.inhibition_type == MECHANISM_BASED() {
        let kdeg = get_kdeg(enzyme_id, halflife)
        return mechanism_based_inhibition(i_unbound, inhibitor.kinact_per_min, inhibitor.ki_mbi_um, kdeg)
    }
    return 1.0
}

fn is_enzyme_targeted(inhibitor: InhibitorParams, enzyme_id: i32) -> bool {
    if enzyme_id == CYP3A4() { return inhibitor.target_cyp3a4 }
    if enzyme_id == CYP2D6() { return inhibitor.target_cyp2d6 }
    if enzyme_id == CYP2C9() { return inhibitor.target_cyp2c9 }
    if enzyme_id == CYP2C19() { return inhibitor.target_cyp2c19 }
    if enzyme_id == CYP1A2() { return inhibitor.target_cyp1a2 }
    return false
}

fn classify_ddi_severity(auc_ratio: f64) -> i32 {
    if auc_ratio < 1.25 { return SEVERITY_NONE() }
    if auc_ratio < 2.0 { return SEVERITY_WEAK() }
    if auc_ratio < 5.0 { return SEVERITY_MODERATE() }
    if auc_ratio < 10.0 { return SEVERITY_STRONG() }
    return SEVERITY_CONTRAINDICATED()
}

fn severity_name(severity: i32) -> i32 {
    return severity
}

fn sqrt_approx(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    var i = 0
    while i < 10 {
        guess = (guess + x / guess) / 2.0
        i = i + 1
    }
    return guess
}

fn pow(base: f64, exp: f64) -> f64 {
    if exp == 0.0 { return 1.0 }
    var result = 1.0
    var i = 0
    let n = if exp > 0.0 { exp } else { 0.0 - exp }
    while i < 100 {
        if i >= n { break }
        result = result * base
        i = i + 1
    }
    if exp < 0.0 { return 1.0 / result }
    return result
}

fn predict_ddi_single_pathway(
    fm: f64,
    r_value: f64
) -> f64 {
    // AUC ratio = 1 / ((fm/R) + (1-fm))
    let denominator = (fm / r_value) + (1.0 - fm)
    return 1.0 / denominator
}

fn predict_ddi_multi_pathway(
    kinetics_cyp3a4_fm: f64,
    kinetics_cyp2d6_fm: f64,
    kinetics_cyp2c9_fm: f64,
    inhibitor: InhibitorParams,
    halflife: CYPHalfLife
) -> DDIPredictionResult {
    var total_inhibited_clearance = 0.0
    var total_fm = kinetics_cyp3a4_fm + kinetics_cyp2d6_fm + kinetics_cyp2c9_fm

    // CYP3A4 contribution
    if kinetics_cyp3a4_fm > 0.0 {
        if is_enzyme_targeted(inhibitor, CYP3A4()) {
            let r = calculate_r_value(inhibitor, CYP3A4(), halflife)
            total_inhibited_clearance = total_inhibited_clearance + kinetics_cyp3a4_fm / r
        } else {
            total_inhibited_clearance = total_inhibited_clearance + kinetics_cyp3a4_fm
        }
    }

    // CYP2D6 contribution
    if kinetics_cyp2d6_fm > 0.0 {
        if is_enzyme_targeted(inhibitor, CYP2D6()) {
            let r = calculate_r_value(inhibitor, CYP2D6(), halflife)
            total_inhibited_clearance = total_inhibited_clearance + kinetics_cyp2d6_fm / r
        } else {
            total_inhibited_clearance = total_inhibited_clearance + kinetics_cyp2d6_fm
        }
    }

    // CYP2C9 contribution
    if kinetics_cyp2c9_fm > 0.0 {
        if is_enzyme_targeted(inhibitor, CYP2C9()) {
            let r = calculate_r_value(inhibitor, CYP2C9(), halflife)
            total_inhibited_clearance = total_inhibited_clearance + kinetics_cyp2c9_fm / r
        } else {
            total_inhibited_clearance = total_inhibited_clearance + kinetics_cyp2c9_fm
        }
    }

    // Non-CYP clearance
    let non_cyp_fm = 1.0 - total_fm
    total_inhibited_clearance = total_inhibited_clearance + non_cyp_fm

    // AUC ratio
    let auc_ratio = 1.0 / total_inhibited_clearance

    // Confidence from inputs
    let base_conf = inhibitor.ki_confidence
    let confidence = base_conf * 0.90

    // Severity classification
    let severity = classify_ddi_severity(auc_ratio)

    return DDIPredictionResult {
        auc_ratio: auc_ratio,
        auc_confidence: confidence,
        cmax_ratio: sqrt_approx(auc_ratio),
        cl_ratio: 1.0 / auc_ratio,
        severity: severity,
        mean_ratio: auc_ratio,
        sd_ratio: auc_ratio * 0.25,
        ci_90_lower: auc_ratio * 0.7,
        ci_90_upper: auc_ratio * 1.4,
        p_exceeds_2fold: if auc_ratio > 2.0 { 0.8 } else { 0.1 },
        p_exceeds_5fold: if auc_ratio > 5.0 { 0.6 } else { 0.05 }
    }
}

fn calc_kp_tissue(fu: f64, uptake_factor: f64) -> f64 {
    let kp = 0.745 * fu * uptake_factor;
    return kp
}

fn calc_pk_metrics(dose: f64@mg, params: PBPKParams) -> PKResults {
    let dose_absorbed = dose * params.bioavail;
    let ke = params.cl / params.vd;
    let t_half = 0.693 / ke;
    let tmax = 2.5;
    let cmax = (dose_absorbed / params.vd) * 0.6;
    let auc = dose_absorbed / params.cl;

    return PKResults {
        cmax: cmax,
        tmax: tmax,
        auc: auc,
        t_half: t_half
    }
}

fn calculate_auc(times: &[h], conc: &[Knowledge[mg/L]]) -> Knowledge[mg*h/L] {
    var auc = 0.0 : mg*h/L;
    var min_conf = 1.0;

    for i in 1..times.len() {
        let dt = times[i] - times[i-1];
        let avg_conc = (conc[i].value + conc[i-1].value) / 2.0;
        auc += avg_conc * dt;
        min_conf = min_conf.min(conc[i].confidence);
    }

    Knowledge::new(
        value: auc,
        confidence: min_conf * 0.98,  // Integration slightly degrades confidence
        provenance: Provenance::derived("trapezoidal_auc"),
    )
}

fn interpolate_concentration(
    result: &SimulationResult,
    time: h
) -> Knowledge[mg/L, ε >= 0.80] {
    // Find bracketing time points
    let idx = result.times.iter()
        .position(|t| *t >= time)
        .unwrap_or(result.times.len() - 1);

    if idx == 0 {
        return result.concentrations[0][0];
    }

    let t0 = result.times[idx - 1];
    let t1 = result.times[idx];
    let c0 = result.concentrations[idx - 1][0];
    let c1 = result.concentrations[idx][0];

    // Linear interpolation
    let frac = (time - t0) / (t1 - t0);
    let value = c0.value + frac * (c1.value - c0.value);
    let conf = c0.confidence.min(c1.confidence) * 0.99;  // Interpolation degrades

    Knowledge::new(
        value: value,
        confidence: conf,
        provenance: Provenance::derived("linear_interpolation"),
    )
}

fn tanh_activation(x: f64) -> f64 {
    let exp_2x = exp(2.0 * x)
    return (exp_2x - 1.0) / (exp_2x + 1.0)
}

fn softplus(x: f64) -> f64 {
    return ln(1.0 + exp(x))
}

fn sigmoid(x: f64) -> f64 {
    return 1.0 / (1.0 + exp(0.0 - x))
}

fn relu(x: f64) -> f64 {
    if x > 0.0 { return x }
    return 0.0
}

fn exp(x: f64) -> f64 {
    if x > 20.0 { return 485165195.0 }
    if x < -20.0 { return 0.0 }
    // Taylor series approximation
    var result = 1.0
    var term = 1.0
    var i = 1
    while i <= 20 {
        term = term * x / (i as f64)
        result = result + term
        i = i + 1
    }
    return result
}

fn ln(x: f64) -> f64 {
    if x <= 0.0 { return -1000.0 }
    if x == 1.0 { return 0.0 }
    // Newton-Raphson for e^y = x
    var y = x - 1.0
    var i = 0
    while i < 20 {
        let ey = exp(y)
        y = y - (ey - x) / ey
        i = i + 1
    }
    return y
}

fn encode_time(t: f64) -> TimeEncoding {
    let pi = 3.14159265358979
    return TimeEncoding {
        sin_t: sin_approx(t),
        cos_t: cos_approx(t),
        sin_t_10: sin_approx(t / 10.0),
        cos_t_10: cos_approx(t / 10.0)
    }
}

fn sin_approx(x: f64) -> f64 {
    // Reduce x to [-pi, pi] range
    let pi = 3.14159265358979
    var y = x
    while y > pi { y = y - 2.0 * pi }
    while y < 0.0 - pi { y = y + 2.0 * pi }
    // Taylor series
    let y2 = y * y
    let y3 = y2 * y
    let y5 = y3 * y2
    let y7 = y5 * y2
    return y - y3 / 6.0 + y5 / 120.0 - y7 / 5040.0
}

fn cos_approx(x: f64) -> f64 {
    let pi = 3.14159265358979
    var y = x
    while y > pi { y = y - 2.0 * pi }
    while y < 0.0 - pi { y = y + 2.0 * pi }
    let y2 = y * y
    let y4 = y2 * y2
    let y6 = y4 * y2
    return 1.0 - y2 / 2.0 + y4 / 24.0 - y6 / 720.0
}

fn create_default_config() -> NeuralODEConfig {
    return NeuralODEConfig {
        hidden_dim: 128,
        use_physics: true,
        physics_weight: 0.7,
        dt: 0.1,
        rtol: 0.001,
        atol: 0.000001
    }
}

fn physics_dynamics(conc: Concentrations, phys: PhysicsData) -> ConcDerivatives {
    // Blood concentration
    let c_blood = conc.c_blood / phys.v_blood_l

    // Hepatic elimination
    let hepatic_elim = phys.cl_hepatic_lph * c_blood

    // Renal elimination
    let renal_elim = phys.cl_renal_lph * c_blood

    // Tissue exchange rates
    let c_liver = conc.c_liver / phys.v_liver_l
    let c_kidney = conc.c_kidney / phys.v_kidney_l
    let c_gut = conc.c_gut / phys.v_gut_l
    let c_peripheral = conc.c_peripheral / phys.v_peripheral_l

    let rate_liver = phys.q_liver_lph * (c_blood - c_liver)
    let rate_kidney = phys.q_kidney_lph * (c_blood - c_kidney)
    let rate_gut = phys.q_gut_lph * (c_blood - c_gut)
    let rate_peripheral = phys.q_peripheral_lph * (c_blood - c_peripheral)

    // Gut absorption
    let absorption = phys.ka_per_h * conc.c_gut

    // Compute derivatives
    let dc_blood = 0.0 - hepatic_elim - renal_elim - rate_liver - rate_kidney - rate_gut - rate_peripheral + absorption
    let dc_liver = rate_liver
    let dc_kidney = rate_kidney
    let dc_gut = rate_gut - absorption
    let dc_peripheral = rate_peripheral

    return ConcDerivatives {
        dc_blood: dc_blood,
        dc_liver: dc_liver,
        dc_kidney: dc_kidney,
        dc_gut: dc_gut,
        dc_peripheral: dc_peripheral
    }
}

fn neural_dynamics(conc: Concentrations, t: f64, hidden_dim: i32) -> ConcDerivatives {
    let t_enc = encode_time(t)

    // Simplified neural network output (placeholder)
    // In production, this would use actual learned weights
    let scale = 0.1

    let dc_blood = scale * tanh_activation(conc.c_blood * 0.01 + t_enc.sin_t)
    let dc_liver = scale * tanh_activation(conc.c_liver * 0.01 + t_enc.cos_t)
    let dc_kidney = scale * tanh_activation(conc.c_kidney * 0.01 + t_enc.sin_t_10)
    let dc_gut = scale * tanh_activation(conc.c_gut * 0.01 + t_enc.cos_t_10)
    let dc_peripheral = scale * tanh_activation(conc.c_peripheral * 0.01)

    return ConcDerivatives {
        dc_blood: dc_blood,
        dc_liver: dc_liver,
        dc_kidney: dc_kidney,
        dc_gut: dc_gut,
        dc_peripheral: dc_peripheral
    }
}

fn hybrid_dynamics(
    conc: Concentrations,
    t: f64,
    phys: PhysicsData,
    config: NeuralODEConfig
) -> ConcDerivatives {
    let physics = physics_dynamics(conc, phys)
    let neural = neural_dynamics(conc, t, config.hidden_dim)

    let w = config.physics_weight

    return ConcDerivatives {
        dc_blood: w * physics.dc_blood + (1.0 - w) * neural.dc_blood,
        dc_liver: w * physics.dc_liver + (1.0 - w) * neural.dc_liver,
        dc_kidney: w * physics.dc_kidney + (1.0 - w) * neural.dc_kidney,
        dc_gut: w * physics.dc_gut + (1.0 - w) * neural.dc_gut,
        dc_peripheral: w * physics.dc_peripheral + (1.0 - w) * neural.dc_peripheral
    }
}

fn add_concs(s1: Concentrations, s2: ConcDerivatives, scale: f64) -> Concentrations {
    return Concentrations {
        c_blood: s1.c_blood + scale * s2.dc_blood,
        c_liver: s1.c_liver + scale * s2.dc_liver,
        c_kidney: s1.c_kidney + scale * s2.dc_kidney,
        c_gut: s1.c_gut + scale * s2.dc_gut,
        c_peripheral: s1.c_peripheral + scale * s2.dc_peripheral
    }
}

fn clamp_conc(conc: Concentrations) -> Concentrations {
    let min_val = 0.0
    return Concentrations {
        c_blood: if conc.c_blood > min_val { conc.c_blood } else { min_val },
        c_liver: if conc.c_liver > min_val { conc.c_liver } else { min_val },
        c_kidney: if conc.c_kidney > min_val { conc.c_kidney } else { min_val },
        c_gut: if conc.c_gut > min_val { conc.c_gut } else { min_val },
        c_peripheral: if conc.c_peripheral > min_val { conc.c_peripheral } else { min_val }
    }
}

fn rk4_step(
    conc: Concentrations,
    t: f64,
    dt: f64,
    phys: PhysicsData,
    config: NeuralODEConfig
) -> Concentrations {
    // k1
    let k1 = hybrid_dynamics(conc, t, phys, config)

    // k2
    let s2 = add_concs(conc, k1, 0.5 * dt)
    let k2 = hybrid_dynamics(s2, t + 0.5 * dt, phys, config)

    // k3
    let s3 = add_concs(conc, k2, 0.5 * dt)
    let k3 = hybrid_dynamics(s3, t + 0.5 * dt, phys, config)

    // k4
    let s4 = add_concs(conc, k3, dt)
    let k4 = hybrid_dynamics(s4, t + dt, phys, config)

    // Combine
    let dc_blood = (k1.dc_blood + 2.0 * k2.dc_blood + 2.0 * k3.dc_blood + k4.dc_blood) / 6.0
    let dc_liver = (k1.dc_liver + 2.0 * k2.dc_liver + 2.0 * k3.dc_liver + k4.dc_liver) / 6.0
    let dc_kidney = (k1.dc_kidney + 2.0 * k2.dc_kidney + 2.0 * k3.dc_kidney + k4.dc_kidney) / 6.0
    let dc_gut = (k1.dc_gut + 2.0 * k2.dc_gut + 2.0 * k3.dc_gut + k4.dc_gut) / 6.0
    let dc_peripheral = (k1.dc_peripheral + 2.0 * k2.dc_peripheral + 2.0 * k3.dc_peripheral + k4.dc_peripheral) / 6.0

    let new_conc = Concentrations {
        c_blood: conc.c_blood + dt * dc_blood,
        c_liver: conc.c_liver + dt * dc_liver,
        c_kidney: conc.c_kidney + dt * dc_kidney,
        c_gut: conc.c_gut + dt * dc_gut,
        c_peripheral: conc.c_peripheral + dt * dc_peripheral
    }

    return clamp_conc(new_conc)
}

fn find_cmax_and_metrics(
    dose_mg: f64,
    duration_h: f64,
    dt: f64,
    phys: PhysicsData,
    config: NeuralODEConfig
) -> SimulationResult {
    // Initialize state (dose in gut for oral)
    var curr = Concentrations {
        c_blood: 0.0,
        c_liver: 0.0,
        c_kidney: 0.0,
        c_gut: dose_mg,
        c_peripheral: 0.0
    }

    var t = 0.0
    var cmax = 0.0
    var tmax = 0.0
    var auc = 0.0
    let n_steps = (duration_h / dt) as i32

    var i = 0
    while i <= n_steps {
        let c_plasma = curr.c_blood / phys.v_blood_l

        // Track Cmax
        if c_plasma > cmax {
            cmax = c_plasma
            tmax = t
        }

        // Trapezoidal AUC
        if i > 0 {
            auc = auc + c_plasma * dt
        }

        // Advance
        if i < n_steps {
            curr = rk4_step(curr, t, dt, phys, config)
        }

        t = t + dt
        i = i + 1
    }

    // Estimate half-life
    let half_life = if cmax > 0.0 { 0.693 * auc / cmax } else { 0.0 }

    let metrics = PKMetrics {
        cmax_mg_l: cmax,
        cmax_confidence: 0.85,
        tmax_h: tmax,
        auc_0_24_mg_h_l: auc,
        auc_confidence: 0.80,
        half_life_h: half_life
    }

    return SimulationResult {
        final_c_blood: curr.c_blood,
        final_c_liver: curr.c_liver,
        final_c_kidney: curr.c_kidney,
        metrics: metrics,
        mean_confidence: 0.82
    }
}

fn euler_step(state: ODEState, params: PKParams, dt: f64) -> ODEState {
    let dA_dt = -params.k_el * state.amount
    let new_amount = state.amount + dA_dt * dt
    let new_time = state.time + dt
    ODEState { time: new_time, amount: new_amount, }
}

fn compute_derivative(amount: f64, k_el: f64) -> f64 {
    -k_el * amount
}

fn rk4_step(state: ODEState, params: PKParams, dt: f64) -> ODEState {
    let a = state.amount
    let k = params.k_el
    let k1 = compute_derivative(a, k)
    let k2 = compute_derivative(a + 0.5 * dt * k1, k)
    let k3 = compute_derivative(a + 0.5 * dt * k2, k)
    let k4 = compute_derivative(a + dt * k3, k)
    let new_amount = a + (dt / 6.0) * (k1 + 2.0 * k2 + 2.0 * k3 + k4)
    let new_time = state.time + dt
    ODEState { time: new_time, amount: new_amount, }
}

fn calculate_concentration(amount: f64, volume: f64) -> f64 {
    amount / volume
}

fn analytical_solution(initial_amount: f64, k_el: f64, time: f64) -> f64 {
    let exponent = -k_el * time
    initial_amount * exp(exponent)
}

fn calculate_kp(logp: f64, fu: f64) -> f64 {
    let base_kp = 1.0 + logp
    return base_kp / fu
}

fn validate_vd(vd: f64) -> bool {
    if vd > 0.0 {
        if vd < 2000.0 {
            return true
        }
    }
    return false
}

fn calculate_cmax(dose: f64, vd: f64, f: f64, bp: f64) -> f64 {
    let numerator = dose * f
    let denominator = vd * bp
    return numerator / denominator
}

fn calculate_auc(dose: f64, cl: f64, f: f64) -> f64 {
    return dose * f / cl
}

fn epo_production_rate(
    hemoglobin: f64,
    renal_factor: f64,
    baseline_hgb: f64
) -> f64 {
    let hgb_ratio = hemoglobin / baseline_hgb
    let hypoxia_stimulus = exp_approx(-2.5 * (hgb_ratio - 1.0))

    // Scale by renal function (CKD reduces EPO production)
    let rate = 100.0 * hypoxia_stimulus * renal_factor

    // Clamp to reasonable range
    if rate < 1.0 { return 1.0 }
    if rate > 10000.0 { return 10000.0 }
    return rate
}

fn epo_effect(epo_miu_ml: f64, kinetics: MarrowKinetics) -> f64 {
    // Fold increase in progenitor proliferation
    return 1.0 + (kinetics.epo_emax - 1.0) * epo_miu_ml / (kinetics.epo_ec50_miu_ml + epo_miu_ml)
}

fn progenitor_ode(
    pools: ProgenitorPools,
    epo_miu_ml: f64,
    drug_effect: f64,
    kinetics: MarrowKinetics
) -> ProgenitorDerivatives {
    let epo_stim = epo_effect(epo_miu_ml, kinetics)

    // BFU-E dynamics: production - transit - apoptosis
    let bfu_e_production = 1.0e10 * epo_stim * drug_effect
    let bfu_e_transit_out = pools.bfu_e / kinetics.bfu_e_transit_days
    let bfu_e_apoptosis = pools.bfu_e * kinetics.bfu_e_apoptosis_per_day
    let d_bfu_e = bfu_e_production - bfu_e_transit_out - bfu_e_apoptosis

    // CFU-E dynamics: amplified input from BFU-E - transit
    let cfu_e_input = bfu_e_transit_out * kinetics.bfu_e_amplification * epo_stim
    let cfu_e_transit_out = pools.cfu_e / kinetics.cfu_e_transit_days
    let cfu_e_apoptosis = pools.cfu_e * kinetics.cfu_e_apoptosis_per_day * (1.0 / drug_effect)
    let d_cfu_e = cfu_e_input - cfu_e_transit_out - cfu_e_apoptosis

    // Proerythroblast dynamics
    let proeryth_input = cfu_e_transit_out * kinetics.cfu_e_amplification
    let proeryth_transit = pools.proerythroblast / 1.0
    let d_proerythroblast = proeryth_input - proeryth_transit

    // Erythroblast dynamics (multiple stages combined)
    let eryth_input = proeryth_transit
    let eryth_transit = pools.erythroblast / kinetics.erythroblast_transit_days
    let d_erythroblast = eryth_input - eryth_transit

    // Marrow reticulocyte dynamics
    let retic_input = eryth_transit * kinetics.erythroblast_amplification
    let retic_release = pools.marrow_retic / kinetics.retic_maturation_days
    let d_marrow_retic = retic_input - retic_release

    return ProgenitorDerivatives {
        d_bfu_e: d_bfu_e,
        d_cfu_e: d_cfu_e,
        d_proerythroblast: d_proerythroblast,
        d_erythroblast: d_erythroblast,
        d_marrow_retic: d_marrow_retic,
        retic_release: retic_release
    }
}

fn drug_concentration_in_rbc(c_plasma: f64, bp_ratio: f64, hematocrit: f64) -> f64 {
    // C_blood = C_plasma * BP_ratio
    // C_RBC = (C_blood - C_plasma * (1-Hct)) / Hct
    let c_blood = c_plasma * bp_ratio
    let c_rbc = (c_blood - c_plasma * (1.0 - hematocrit)) / hematocrit
    if c_rbc < 0.0 { return 0.0 }
    return c_rbc
}

fn classify_anemia(hemoglobin: f64) -> i32 {
    if hemoglobin >= 10.0 { return GRADE_NONE() }
    if hemoglobin >= 9.0 { return GRADE_1() }
    if hemoglobin >= 8.0 { return GRADE_2() }
    if hemoglobin >= 6.5 { return GRADE_3() }
    return GRADE_4()
}

fn grade_name(grade: i32) -> i32 {
    return grade
}

fn calculate_hemoglobin(rbc_count: f64, mch_pg: f64) -> f64 {
    // Hgb (g/dL) = RBC (cells/L) × MCH (pg) × 1e-13
    let hgb = rbc_count * mch_pg * 1.0e-13
    if hgb < 3.0 { return 3.0 }
    if hgb > 25.0 { return 25.0 }
    return hgb
}

fn calculate_hematocrit(rbc_count: f64, mcv_fl: f64) -> f64 {
    // Hct = RBC (cells/L) × MCV (fL) × 1e-15
    let hct = rbc_count * mcv_fl * 1.0e-15
    if hct < 0.10 { return 0.10 }
    if hct > 0.70 { return 0.70 }
    return hct
}

fn clamp_positive(x: f64) -> f64 {
    if x < 0.0 { return 0.0 }
    return x
}

fn simulate_erythropoiesis(
    is_male: bool,
    drug_myelotoxicity: f64,
    duration_days: f64,
    dt_days: f64
) -> SimulationTimeCourse {
    let hema_ref = create_hematology_ref()
    let kinetics = create_marrow_kinetics()

    // Initialize based on sex
    let baseline_hgb = if is_male { hema_ref.hgb_male } else { hema_ref.hgb_female }
    let baseline_rbc = if is_male { hema_ref.rbc_count_male } else { hema_ref.rbc_count_female }
    let baseline_hct = if is_male { hema_ref.hct_male } else { hema_ref.hct_female }

    // Initialize EPO state
    var epo = EPOConc {
        concentration_miu_ml: hema_ref.epo_baseline_miu_ml,
        confidence: 0.85,
        production_rate: 100.0,
        exogenous: 0.0,
        renal_factor: 1.0
    }

    // Initialize progenitors
    var progenitors = ProgenitorPools {
        bfu_e: 1.0e10,
        cfu_e: 2.0e10,
        proerythroblast: 5.0e10,
        erythroblast: 1.0e11,
        marrow_retic: 5.0e10
    }

    // Initialize RBC population (uniform distribution)
    let rbc_per_bin = baseline_rbc / 12.0
    var rbc_pop = RBCPopulation {
        bin_0: rbc_per_bin,
        bin_1: rbc_per_bin,
        bin_2: rbc_per_bin,
        bin_3: rbc_per_bin,
        bin_4: rbc_per_bin,
        bin_5: rbc_per_bin,
        bin_6: rbc_per_bin,
        bin_7: rbc_per_bin,
        bin_8: rbc_per_bin,
        bin_9: rbc_per_bin,
        bin_10: rbc_per_bin,
        bin_11: rbc_per_bin,
        total_rbc: baseline_rbc,
        reticulocytes: baseline_rbc * hema_ref.retic_fraction,
        mean_age_days: 60.0
    }

    var hemoglobin = baseline_hgb
    var hematocrit = baseline_hct

    var nadir_hgb = baseline_hgb
    var nadir_time = 0.0

    let n_steps = (duration_days / dt_days) as i32
    var step = 0

    while step <= n_steps {
        let t = (step as f64) * dt_days

        // Track nadir
        if hemoglobin < nadir_hgb {
            nadir_hgb = hemoglobin
            nadir_time = t
        }

        if step < n_steps {
            // Update EPO (fast dynamics, steady-state approximation)
            let epo_prod = epo_production_rate(hemoglobin, epo.renal_factor, baseline_hgb)
            epo.concentration_miu_ml = epo_prod * 0.1

            // Progenitor dynamics with drug effect
            let derivs = progenitor_ode(progenitors, epo.concentration_miu_ml, drug_myelotoxicity, kinetics)

            // Update progenitors
            progenitors.bfu_e = clamp_positive(progenitors.bfu_e + derivs.d_bfu_e * dt_days)
            progenitors.cfu_e = clamp_positive(progenitors.cfu_e + derivs.d_cfu_e * dt_days)
            progenitors.proerythroblast = clamp_positive(progenitors.proerythroblast + derivs.d_proerythroblast * dt_days)
            progenitors.erythroblast = clamp_positive(progenitors.erythroblast + derivs.d_erythroblast * dt_days)
            progenitors.marrow_retic = clamp_positive(progenitors.marrow_retic + derivs.d_marrow_retic * dt_days)

            // Update RBC population
            rbc_pop = update_rbc_population(rbc_pop, derivs.retic_release, 0.0, dt_days)

            // Update Hgb and Hct
            hemoglobin = calculate_hemoglobin(rbc_pop.total_rbc, hema_ref.mch_pg)
            hematocrit = calculate_hematocrit(rbc_pop.total_rbc, 90.0)
        }

        step = step + 1
    }

    let nadir_grade = classify_anemia(nadir_hgb)
    let final_grade = classify_anemia(hemoglobin)

    return SimulationTimeCourse {
        final_hemoglobin: hemoglobin,
        final_rbc_count: rbc_pop.total_rbc,
        nadir_hemoglobin: nadir_hgb,
        nadir_time_days: nadir_time,
        nadir_grade: nadir_grade,
        final_grade: final_grade
    }
}

fn sqrt_d(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn rng_init() with Mut {
    RNG_A = 123456789
    RNG_B = 362436069
}

fn rng_next() -> i64 with Mut {
    // xorshift128-style using two state vars
    var x = RNG_A
    let y = RNG_B
    RNG_A = y
    x = x ^ (x << 23)
    x = x ^ (x >> 17)
    x = x ^ (y ^ (y >> 26))
    RNG_B = x
    let r = x + y
    if r < 0 { 0 - r } else { r }
}

fn rand_uniform() -> f64 with Mut, Div {
    let r = rng_next()
    let d = (r % 10000) as f64 / 10000.0
    d
}

fn pbpk_dy0(y0: f64, ka: f64) -> f64 {
    0.0 - ka * y0
}

fn pbpk_dy1(y0: f64, y1: f64, y2: f64, ka: f64, ke: f64, k12: f64, k21: f64, vd: f64, fb: f64) -> f64 with Div {
    ka * fb * y0 / vd - ke * y1 - k12 * y1 + k21 * y2
}

fn run_pbpk(ka: f64, ke: f64, k12: f64, k21: f64, vd: f64, fb: f64) with Mut, Div, Panic {
    var gut = 2000.0     // 2mg = 2000 μg
    var plasma = 0.0
    var tissue = 0.0

    let dt = 0.1
    var t = 0.0
    var cmax = 0.0
    var auc = 0.0
    var step = 0

    while step < 240 {
        let prev_p = plasma

        // RK4 inlined
        let k1_0 = pbpk_dy0(gut, ka)
        let k1_1 = pbpk_dy1(gut, plasma, tissue, ka, ke, k12, k21, vd, fb)
        let k1_2 = pbpk_dy2(plasma, tissue, k12, k21)

        let g2 = gut + 0.5 * dt * k1_0
        let p2 = plasma + 0.5 * dt * k1_1
        let t2 = tissue + 0.5 * dt * k1_2
        let k2_0 = pbpk_dy0(g2, ka)
        let k2_1 = pbpk_dy1(g2, p2, t2, ka, ke, k12, k21, vd, fb)
        let k2_2 = pbpk_dy2(p2, t2, k12, k21)

        let g3 = gut + 0.5 * dt * k2_0
        let p3 = plasma + 0.5 * dt * k2_1
        let t3 = tissue + 0.5 * dt * k2_2
        let k3_0 = pbpk_dy0(g3, ka)
        let k3_1 = pbpk_dy1(g3, p3, t3, ka, ke, k12, k21, vd, fb)
        let k3_2 = pbpk_dy2(p3, t3, k12, k21)

        let g4 = gut + dt * k3_0
        let p4 = plasma + dt * k3_1
        let t4 = tissue + dt * k3_2
        let k4_0 = pbpk_dy0(g4, ka)
        let k4_1 = pbpk_dy1(g4, p4, t4, ka, ke, k12, k21, vd, fb)
        let k4_2 = pbpk_dy2(p4, t4, k12, k21)

        gut = gut + dt / 6.0 * (k1_0 + 2.0 * k2_0 + 2.0 * k3_0 + k4_0)
        plasma = plasma + dt / 6.0 * (k1_1 + 2.0 * k2_1 + 2.0 * k3_1 + k4_1)
        tissue = tissue + dt / 6.0 * (k1_2 + 2.0 * k2_2 + 2.0 * k3_2 + k4_2)

        t = t + dt
        if plasma > cmax { cmax = plasma }
        auc = auc + 0.5 * dt * (prev_p + plasma)
        step = step + 1
    }

    // Store as scaled integers (multiply by 1e9 to preserve precision)
    RES_CMAX_I = (cmax * 1000000000.0) as i64
    RES_AUC_I = (auc * 1000000000.0) as i64
}

fn get_cmax() -> f64 with Div {
    (RES_CMAX_I as f64) / 1000000000.0
}

fn get_auc() -> f64 with Div {
    (RES_AUC_I as f64) / 1000000000.0
}

fn calculate_derivatives(state: &ModelState, params: &TwoCompartmentParams) -> Derivatives {
    // Rate constants derived from clearances and volumes
    let k10 = params.cl / params.vc;   // Elimination rate constant
    let k12 = params.q / params.vc;     // Central to peripheral rate
    let k21 = params.q / params.vp;     // Peripheral to central rate

    // Absorption from gut
    let absorption = params.ka * state.a_gut;

    // Transfer between compartments
    let central_to_peripheral = k12 * state.a_central;
    let peripheral_to_central = k21 * state.a_peripheral;

    // Elimination from central
    let elimination = k10 * state.a_central;

    Derivatives {
        d_gut: -absorption,
        d_central: absorption - central_to_peripheral + peripheral_to_central - elimination,
        d_peripheral: central_to_peripheral - peripheral_to_central,
    }
}

fn rk4_step(state: &ModelState, params: &TwoCompartmentParams, dt: f64@h) -> ModelState {
    // k1 = f(t, y)
    let k1 = calculate_derivatives(state, params);

    // k2 = f(t + dt/2, y + dt/2 * k1)
    let state2 = ModelState {
        a_gut: state.a_gut + 0.5 * dt * k1.d_gut,
        a_central: state.a_central + 0.5 * dt * k1.d_central,
        a_peripheral: state.a_peripheral + 0.5 * dt * k1.d_peripheral,
        time: state.time + 0.5 * dt,
    };
    let k2 = calculate_derivatives(&state2, params);

    // k3 = f(t + dt/2, y + dt/2 * k2)
    let state3 = ModelState {
        a_gut: state.a_gut + 0.5 * dt * k2.d_gut,
        a_central: state.a_central + 0.5 * dt * k2.d_central,
        a_peripheral: state.a_peripheral + 0.5 * dt * k2.d_peripheral,
        time: state.time + 0.5 * dt,
    };
    let k3 = calculate_derivatives(&state3, params);

    // k4 = f(t + dt, y + dt * k3)
    let state4 = ModelState {
        a_gut: state.a_gut + dt * k3.d_gut,
        a_central: state.a_central + dt * k3.d_central,
        a_peripheral: state.a_peripheral + dt * k3.d_peripheral,
        time: state.time + dt,
    };
    let k4 = calculate_derivatives(&state4, params);

    // y(t+dt) = y(t) + dt/6 * (k1 + 2*k2 + 2*k3 + k4)
    ModelState {
        a_gut: state.a_gut + dt / 6.0 * (k1.d_gut + 2.0 * k2.d_gut + 2.0 * k3.d_gut + k4.d_gut),
        a_central: state.a_central + dt / 6.0 * (k1.d_central + 2.0 * k2.d_central + 2.0 * k3.d_central + k4.d_central),
        a_peripheral: state.a_peripheral + dt / 6.0 * (k1.d_peripheral + 2.0 * k2.d_peripheral + 2.0 * k3.d_peripheral + k4.d_peripheral),
        time: state.time + dt,
    }
}

fn simulate(
    dose: f64@mg,
    params: &TwoCompartmentParams,
    duration: f64@h,
    dt: f64@h,
) -> Vec<TimePoint> {
    var state = ModelState::initial(dose);
    var results: Vec<TimePoint> = Vec::new();

    // Record initial state
    results.push(TimePoint {
        time: state.time,
        concentration: state.concentration(params.vc),
        amount_gut: state.a_gut,
        amount_central: state.a_central,
        amount_peripheral: state.a_peripheral,
    });

    // Integrate over time
    while state.time < duration {
        state = rk4_step(&state, params, dt);

        results.push(TimePoint {
            time: state.time,
            concentration: state.concentration(params.vc),
            amount_gut: state.a_gut,
            amount_central: state.a_central,
            amount_peripheral: state.a_peripheral,
        });
    }

    results
}

fn calculate_metrics(results: &Vec<TimePoint>, params: &TwoCompartmentParams) -> PKMetrics {
    // Find Cmax and Tmax
    var cmax: f64@mg_per_L = 0.0;
    var tmax: f64@h = 0.0;

    for point in results.iter() {
        if point.concentration > cmax {
            cmax = point.concentration;
            tmax = point.time;
        }
    }

    // Calculate AUC using trapezoidal rule
    var auc: f64 = 0.0;
    var i: usize = 1;
    while i < results.len() {
        let prev = &results[i - 1];
        let curr = &results[i];
        let dt = (curr.time - prev.time) as f64;
        let avg_conc = ((prev.concentration + curr.concentration) / 2.0) as f64;
        auc = auc + avg_conc * dt;
        i = i + 1;
    }

    // Calculate terminal half-life from elimination rate constant
    let k10 = params.cl / params.vc;
    let t_half = 0.693 / k10;

    // Mean residence time (simplified for two-compartment)
    let mrt = auc / cmax * 1.0;  // Simplified approximation

    PKMetrics {
        cmax: cmax,
        tmax: tmax,
        auc: auc,
        t_half: t_half,
        mrt: mrt,
    }
}

fn scale_parameters(
    base_params: &TwoCompartmentParams,
    patient: &PatientParams,
) -> TwoCompartmentParams {
    // Allometric scaling (simplified)
    let weight_factor = (patient.weight / 70.0).powf(0.75);

    // Renal function adjustment
    let renal_factor = patient.clcr / 120.0;

    // Metabolizer status adjustment
    let metabolic_factor = if patient.is_pm { 0.5 } else { 1.0 };

    TwoCompartmentParams {
        ka: base_params.ka,  // Usually not scaled
        vc: base_params.vc * weight_factor,
        vp: base_params.vp * weight_factor,
        cl: base_params.cl * weight_factor * renal_factor * metabolic_factor,
        q: base_params.q * weight_factor,
    }
}

fn concentration(dose_mg: KnowledgeF64, volume_l: KnowledgeF64) -> KnowledgeF64 {
    let c = dose_mg.value / volume_l.value

    // First-order linearized uncertainty for division:
    // dc ≈ |∂c/∂dose| u_dose + |∂c/∂vol| u_vol
    let d_cdose = 1.0 / volume_l.value
    let d_cvol = -dose_mg.value / (volume_l.value * volume_l.value)

    let u = (if d_cdose < 0.0 { -d_cdose } else { d_cdose }) * dose_mg.uncertainty
          + (if d_cvol < 0.0 { -d_cvol } else { d_cvol }) * volume_l.uncertainty

    return KnowledgeF64 {
        value: c,
        uncertainty: u
    }
}

fn concentration_at_time(
    dose: Knowledge[Dose],
    time: Knowledge[Time]
) -> Knowledge[Concentration] with Div, Exp {
    // Cálculo do termo principal
    let numerator = BIOAVAILABILITY * dose * ABSORPTION_RATE
    let denominator = VOLUME_DISTRIBUTION * (ABSORPTION_RATE - ELIMINATION_RATE)

    // Propagação automática de incerteza através das operações
    let term1 = numerator / denominator

    // Cálculo dos termos exponenciais
    let exp_elim = exp(-ELIMINATION_RATE * time)
    let exp_abs = exp(-ABSORPTION_RATE * time)

    // Concentração no tempo t
    term1 * (exp_elim - exp_abs)
}

fn calculate_auc(dose: Knowledge[Dose]) -> Knowledge[Concentration * Time] with Div {
    let numerator = BIOAVAILABILITY * dose
    let denominator = VOLUME_DISTRIBUTION * ELIMINATION_RATE
    numerator / denominator
}

fn elimination_half_life() -> Knowledge[Time] with Div {
    let ln2: Knowledge[f64] = Knowledge(value: 0.693147 ε: 1.0 prov: "math_constant")
    ln2 / ELIMINATION_RATE
}

fn peak_concentration_and_time(
    dose: Knowledge[Dose]
) -> (Knowledge[Concentration], Knowledge[Time]) with Div, Log, Exp {
    // Cálculo de Tmax
    let ratio = ABSORPTION_RATE / ELIMINATION_RATE
    let log_ratio = log(ratio)
    let rate_diff = ABSORPTION_RATE - ELIMINATION_RATE
    let tmax = log_ratio / rate_diff

    // Cálculo de Cmax no tempo Tmax
    let cmax = concentration_at_time(dose, tmax)

    (cmax, tmax)
}

fn is_dose_safe(
    dose: Knowledge[Dose],
    min_therapeutic: Concentration,
    max_toxic: Concentration
) -> Knowledge[bool] with IO {
    let (cmax, _) = peak_concentration_and_time(dose)

    // Verificação com margem de segurança
    let safety_margin: f64 = 0.8  // 80% do limite
    let toxic_threshold = max_toxic * safety_margin

    // Retorna conhecimento sobre segurança
    Knowledge(
        value: cmax.value >= min_therapeutic && cmax.value <= toxic_threshold
        ε: cmax.ε * 0.95   // Confiança reduzida pela verificação
        prov: "safety_check"
    )
}

fn check_confidence(
    param: Knowledge[f64],
    threshold: f64
) -> bool with IO {
    if param.ε < threshold {
        println("⚠️  Alerta: Confiança baixa no parâmetro (ε = " + str(param.ε) + ")")
        println("   Considere medições mais precisas")
        false
    } else {
        true
    }
}

