fn test_spinor_boost_even() -> bool with Mut, Panic, Div {
    let psi = make_dirac_spinor(1.0, 0.5, 0.3, 0.2, 0.1, 0.4, 0.6, 0.15)
    let r = make_boost(0.5, 1.0, 0.0, 0.0)
