}

fn qml_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i: i32 = 0
    while i < 30 {
        y = 0.5 * (y + x / y)
        i = i + 1
    }
    y
}

