fn epistemic_conf_mean(k: EpistemicValue) -> f64 {
    return k.conf_alpha / (k.conf_alpha + k.conf_beta)
}

fn kalman_update(
    prior: EpistemicValue,
    measurement: f64,
    meas_variance: f64
) -> EpistemicValue {
    // Calculate precisions (inverse variances)
    let prior_prec = 1.0 / max_f64(prior.variance, 0.0001)
    let meas_prec = 1.0 / max_f64(meas_variance, 0.0001)

    // Total precision = sum of individual precisions
    let total_prec = prior_prec + meas_prec

    // Posterior mean: precision-weighted average
    // More precise measurements get more weight
    let posterior_mean = (prior_prec * prior.value + meas_prec * measurement) / total_prec

    // Posterior variance: inverse of total precision
    // Always less than both prior and measurement variance
    let posterior_var = 1.0 / total_prec

    return EpistemicValue {
        value: posterior_mean,
        variance: posterior_var,
        conf_alpha: prior.conf_alpha + 1.0,
        conf_beta: prior.conf_beta
    }
}

fn fp_mul(a: i64, b: i64) -> i64 {
    return (a * b) / 1000
}

fn fp_div(a: i64, b: i64) -> i64 {
    if b == 0 { return 0 }
    return (a * 1000) / b
}

fn approx_exp_neg_fp(x_fp: i64) -> i64 {
    // For large arguments, use halving to keep Taylor accurate
    if x_fp > 2000 {
        // exp(-x) = exp(-x/2) * exp(-x/2)
        let half = approx_exp_neg_fp(x_fp / 2)
        return fp_mul(half, half)
    }

    // All values scaled by 1000
    let one = 1000
    let x2 = fp_mul(x_fp, x_fp)
    let x3 = fp_mul(x2, x_fp)
    let x4 = fp_mul(x3, x_fp)
    let x5 = fp_mul(x4, x_fp)
    let x6 = fp_mul(x5, x_fp)

    // Taylor: 1 - x + x²/2 - x³/6 + x⁴/24 - x⁵/120 + x⁶/720
    var result = one - x_fp + x2 / 2 - x3 / 6 + x4 / 24 - x5 / 120 + x6 / 720

    // Clamp to [0, 1000]
    if result < 0 { result = 0 }
    if result > 1000 { result = 1000 }
    return result
}

fn print_digit(d: i64) {
    if d == 0 { print("0") }
    if d == 1 { print("1") }
    if d == 2 { print("2") }
    if d == 3 { print("3") }
    if d == 4 { print("4") }
    if d == 5 { print("5") }
    if d == 6 { print("6") }
    if d == 7 { print("7") }
    if d == 8 { print("8") }
    if d == 9 { print("9") }
}

fn print_int_inline(n: i64) {
    var v = n
    if v < 0 {
        print("-")
        v = 0 - v
    }
    if v == 0 {
        print("0")
        return
    }
    // Extract digits (max ~18 digits for i64)
    // We'll handle up to 6 digits for our use case
    if v >= 100000 { print_digit(v / 100000 % 10) }
    if v >= 10000 { print_digit(v / 10000 % 10) }
    if v >= 1000 { print_digit(v / 1000 % 10) }
    if v >= 100 { print_digit(v / 100 % 10) }
    if v >= 10 { print_digit(v / 10 % 10) }
    print_digit(v % 10)
}

fn print_fp(val: i64) {
    var v = val
    if v < 0 {
        print("-")
        v = 0 - v
    }
    let integer_part = v / 1000
    let frac = (v - integer_part * 1000) / 100
    print_int_inline(integer_part)
    print(".")
    print_digit(frac)
}

