    if v < 0 { return 0 }
    if v > 255 { return 255 }
    v
}

fn rasterize_rect(
    x0: i64, y0: i64, rw: i64, rh: i64,
    r: i64, g: i64, b: i64,
    fb_r: &![i64; 65536], fb_g: &![i64; 65536], fb_b: &![i64; 65536],
    fb_w: i64, fb_h: i64
) with Mut, Panic, Div {
    var dy: i64 = 0
    while dy < rh {
        var dx: i64 = 0
        while dx < rw {
            let px = x0 + dx
            let py = y0 + dy
            if px >= 0 && px < fb_w && py >= 0 && py < fb_h {
                let idx = py * fb_w + px;
                (*fb_r)[idx] = r;
                (*fb_g)[idx] = g;
                (*fb_b)[idx] = b;
            }
            dx = dx + 1
        }
        dy = dy + 1
    }
}

fn rasterize_line(
    x0: i64, y0: i64, x1: i64, y1: i64,
    r: i64, g: i64, b: i64,
    fb_r: &![i64; 65536], fb_g: &![i64; 65536], fb_b: &![i64; 65536],
    fb_w: i64, fb_h: i64
) with Mut, Panic, Div {
    var cx: i64 = x0
    var cy: i64 = y0
    var dx: i64 = x1 - x0
    var dy: i64 = y1 - y0
    if dx < 0 { dx = 0 - dx }
    if dy < 0 { dy = 0 - dy }
    let sx: i64 = if x0 < x1 { 1 } else { 0 - 1 }
    let sy: i64 = if y0 < y1 { 1 } else { 0 - 1 }
    var err: i64 = dx - dy

    loop {
        if cx >= 0 && cx < fb_w && cy >= 0 && cy < fb_h {
            let idx = cy * fb_w + cx;
            (*fb_r)[idx] = r;
            (*fb_g)[idx] = g;
            (*fb_b)[idx] = b;
        }
        if cx == x1 && cy == y1 { return }
        let e2 = err * 2
        if e2 > (0 - dy) {
            err = err - dy
            cx = cx + sx
        }
        if e2 < dx {
            err = err + dx
            cy = cy + sy
        }
    }
}

