) with IO, Mut, Panic, Div {
    print("P3\n")
    print_int(w)
    print(" ")
    print_int(h)
    print("\n255\n")
    var i: i64 = 0
    while i < w * h {
        print_int(clamp_byte((*fb_r)[i]))
        print(" ")
