fn rotate_y(v: Vec3) -> Vec3 {
    let c = 0.819152
    let s = 0.573576
    Vec3 {
        x: v.x * c + v.z * s,
        y: v.y,
        z: (0.0 - v.x) * s + v.z * c,
    }
}

fn rotate_x(v: Vec3) -> Vec3 {
    let c = 0.906308
    let s = 0.422618
    Vec3 {
        x: v.x,
        y: v.y * c + (0.0 - v.z) * s,
        z: v.y * s + v.z * c,
    }
}

fn project_point(v: Vec3, width: i64, height: i64, focal: f64) -> ScreenPoint with Div, Panic {
    let z_cam = v.z + 4.8
    let scale = focal / z_cam
    ScreenPoint {
        x: (v.x * scale + ((width as f64) * 0.5)) as i64,
        y: ((0.0 - v.y) * scale + ((height as f64) * 0.5)) as i64,
        z: z_cam,
    }
}

fn set_pixel(
    fb_r: &![i64; 65536], fb_g: &![i64; 65536], fb_b: &![i64; 65536],
    width: i64, height: i64, x: i64, y: i64, r: i64, g: i64, b: i64
) with Mut, Panic {
    if x < 0 || x >= width || y < 0 || y >= height { return }
    let idx = y * width + x;
    (*fb_r)[idx] = clamp_byte(r);
    (*fb_g)[idx] = clamp_byte(g);
    (*fb_b)[idx] = clamp_byte(b);
}

fn draw_point(
    fb_r: &![i64; 65536], fb_g: &![i64; 65536], fb_b: &![i64; 65536],
    width: i64, height: i64, x: i64, y: i64, r: i64, g: i64, b: i64
) with Mut, Panic {
    set_pixel(fb_r, fb_g, fb_b, width, height, x, y, r, g, b)
    set_pixel(fb_r, fb_g, fb_b, width, height, x - 1, y, r, g, b)
    set_pixel(fb_r, fb_g, fb_b, width, height, x + 1, y, r, g, b)
    set_pixel(fb_r, fb_g, fb_b, width, height, x, y - 1, r, g, b)
    set_pixel(fb_r, fb_g, fb_b, width, height, x, y + 1, r, g, b)
}

fn rasterize_line(
    fb_r: &![i64; 65536], fb_g: &![i64; 65536], fb_b: &![i64; 65536],
    width: i64, height: i64,
    x0: i64, y0: i64, x1: i64, y1: i64,
    r: i64, g: i64, b: i64
) with Mut, Panic, Div {
    var cx = x0
    var cy = y0
    var dx = x1 - x0
    var dy = y1 - y0
    if dx < 0 { dx = 0 - dx }
    if dy < 0 { dy = 0 - dy }
    let sx = if x0 < x1 { 1 } else { 0 - 1 }
    let sy = if y0 < y1 { 1 } else { 0 - 1 }
    var err = dx - dy

    loop {
        set_pixel(fb_r, fb_g, fb_b, width, height, cx, cy, r, g, b)
        if cx == x1 && cy == y1 { return }
        let e2 = err * 2
        if e2 > (0 - dy) {
            err = err - dy
            cx = cx + sx
        }
        if e2 < dx {
            err = err + dx
            cy = cy + sy
        }
    }
}

fn edge_a(idx: i64) -> i64 {
    if idx == 0 { return 0 }
    if idx == 1 { return 1 }
    if idx == 2 { return 2 }
    if idx == 3 { return 3 }
    if idx == 4 { return 4 }
    if idx == 5 { return 5 }
    if idx == 6 { return 6 }
    if idx == 7 { return 7 }
    if idx == 8 { return 0 }
    if idx == 9 { return 1 }
    if idx == 10 { return 2 }
    3
}

fn edge_b(idx: i64) -> i64 {
    if idx == 0 { return 1 }
    if idx == 1 { return 2 }
    if idx == 2 { return 3 }
    if idx == 3 { return 0 }
    if idx == 4 { return 5 }
    if idx == 5 { return 6 }
    if idx == 6 { return 7 }
    if idx == 7 { return 4 }
    if idx == 8 { return 4 }
    if idx == 9 { return 5 }
    if idx == 10 { return 6 }
    7
}

fn quat_from_axis_angle(ax: f64, ay: f64, az: f64, angle: f64) -> Quaternion with Div {
    // half_angle = angle / 2; sin_ha ≈ angle/2 for small angles (placeholder)
    let ha = angle * 0.5
    let sha = ha  // sin approximation for small angles
    let cha = 1.0 - ha * ha * 0.5  // cos approximation
    Quaternion { w: cha, x: ax * sha, y: ay * sha, z: az * sha }
}

fn quat_multiply(a: Quaternion, b: Quaternion) -> Quaternion {
    Quaternion {
        w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
        x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
        y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
        z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
    }
}

fn quat_rotate_point(q: Quaternion, p: Vec3) -> Vec3 {
    // p' = q * p * q^-1 (simplified for unit quaternion)
    let qp = Quaternion { w: 0.0, x: p.x, y: p.y, z: p.z }
    let q_conj = Quaternion { w: q.w, x: 0.0 - q.x, y: 0.0 - q.y, z: 0.0 - q.z }
    let tmp = quat_multiply(q, qp)
    let result = quat_multiply(tmp, q_conj)
    Vec3 { x: result.x, y: result.y, z: result.z }
}

fn project_pt(v: Vec3, focal: f64, z_offset: f64, fb_w: i64, fb_h: i64) -> ScreenPt with Div, Panic {
    let z_cam = v.z + z_offset
    let scale = focal / z_cam
    ScreenPt {
        sx: (v.x * scale + ((fb_w as f64) * 0.5)) as i64,
        sy: ((0.0 - v.y) * scale + ((fb_h as f64) * 0.5)) as i64,
        depth: z_cam,
    }
}

fn vertex(x: f64, y: f64, z: f64, r: f64, g: f64, b: f64) -> Vertex {
    Vertex {
        pos: Vec3 { x: x, y: y, z: z },
        col: Color { r: r, g: g, b: b, a: 1.0 },
    }
}

fn edge_fn(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64) -> f64 {
    (cx - ax) * (by - ay) - (cy - ay) * (bx - ax)
}

fn project_vertex(v: Vertex, width: i64, height: i64) -> Vertex2D {
    let px = ((v.pos.x + 1.0) * 0.5) * ((width - 1) as f64)
    let py = (1.0 - ((v.pos.y + 1.0) * 0.5)) * ((height - 1) as f64)
    Vertex2D {
        x: px,
        y: py,
        z: v.pos.z,
        r: v.col.r,
        g: v.col.g,
        b: v.col.b,
    }
}

fn fill_background(
    width: i64,
    height: i64,
    fb_r: &![i64; 65536],
    fb_g: &![i64; 65536],
    fb_b: &![i64; 65536]
) with Mut, Panic, Div {
    var py: i64 = 0
    while py < height {
        var px: i64 = 0
        while px < width {
            let idx = py * width + px
            (*fb_r)[idx] = 12 + py / 10 + px / 32
            (*fb_g)[idx] = 16 + py / 8
            (*fb_b)[idx] = 28 + py / 5
            px = px + 1
        }
        py = py + 1
    }
}

fn rasterize_triangle(
    width: i64,
    height: i64,
    v0: Vertex2D,
    v1: Vertex2D,
    v2: Vertex2D,
    area: f64,
    fb_r: &![i64; 65536],
    fb_g: &![i64; 65536],
    fb_b: &![i64; 65536]
) with Mut, Panic, Div {
    var py: i64 = 0
    while py < height {
        var px: i64 = 0
        while px < width {
            let cx = (px as f64) + 0.5
            let cy = (py as f64) + 0.5

            let w0 = edge_fn(v1.x, v1.y, v2.x, v2.y, cx, cy)
            let w1 = edge_fn(v2.x, v2.y, v0.x, v0.y, cx, cy)
            let w2 = edge_fn(v0.x, v0.y, v1.x, v1.y, cx, cy)

            let inside = if area > 0.0 {
                w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0
            } else {
                w0 <= 0.0 && w1 <= 0.0 && w2 <= 0.0
            }

            if inside {
                let b0 = w0 / area
                let b1 = w1 / area
                let b2 = w2 / area

                let r = b0 * v0.r + b1 * v1.r + b2 * v2.r
                let g = b0 * v0.g + b1 * v1.g + b2 * v2.g
                let b_col = b0 * v0.b + b1 * v1.b + b2 * v2.b
                let shade = 0.82 + (1.0 - (b0 * v0.z + b1 * v1.z + b2 * v2.z)) * 0.2

                let idx = py * width + px
                (*fb_r)[idx] = clamp_byte((r * shade * 255.0) as i64)
                (*fb_g)[idx] = clamp_byte((g * shade * 255.0) as i64)
                (*fb_b)[idx] = clamp_byte((b_col * shade * 255.0) as i64)
            }
            px = px + 1
        }
        py = py + 1
    }
}

//@ run-pass
// Software-rasterized triangle output as PPM P3
//
// Run: souc run examples/render/triangle_ppm.sio > triangle.ppm
// View: display triangle.ppm  (or open in any image viewer)
//
// Barycentric coordinate interpolation with per-vertex colors:
//   v0 (top, red), v1 (bottom-left, green), v2 (bottom-right, blue)

struct Vertex2D { x: f64, y: f64, z: f64, r: f64, g: f64, b: f64 }

fn edge_fn(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64) -> f64 {
    (cx - ax) * (by - ay) - (cy - ay) * (bx - ax)
}

fn min_i64(a: i64, b: i64) -> i64 { if a < b { a } else { b } }
fn max_i64(a: i64, b: i64) -> i64 { if a > b { a } else { b } }
fn min_f64(a: f64, b: f64) -> f64 { if a < b { a } else { b } }
fn max_f64(a: f64, b: f64) -> f64 { if a > b { a } else { b } }

fn clamp_byte(v: i64) -> i64 {
    if v < 0 { return 0 }
    if v > 255 { return 255 }
    v
}

fn main() with IO, Mut, Div, Panic {
    let w: i64 = 128
    let h: i64 = 128

    // Framebuffer (128x128 = 16384 pixels)
    var fb_r: [i64; 16384] = [20; 16384]
    var fb_g: [i64; 16384] = [20; 16384]
    var fb_b: [i64; 16384] = [30; 16384]

    // Triangle vertices in pixel coordinates
    let v0 = Vertex2D { x: 64.0, y: 10.0, z: 0.0, r: 1.0, g: 0.0, b: 0.0 }
    let v1 = Vertex2D { x: 20.0, y: 110.0, z: 0.0, r: 0.0, g: 1.0, b: 0.0 }
    let v2 = Vertex2D { x: 108.0, y: 110.0, z: 0.0, r: 0.0, g: 0.0, b: 1.0 }

    let area = edge_fn(v0.x, v0.y, v1.x, v1.y, v2.x, v2.y)

    // Rasterize
    var py: i64 = 0
    while py < h {
        var px: i64 = 0
        while px < w {
            let cx = (px as f64) + 0.5
            let cy = (py as f64) + 0.5

            let w0 = edge_fn(v1.x, v1.y, v2.x, v2.y, cx, cy)
            let w1 = edge_fn(v2.x, v2.y, v0.x, v0.y, cx, cy)
            let w2 = edge_fn(v0.x, v0.y, v1.x, v1.y, cx, cy)

            let inside = if area > 0.0 {
                w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0
            } else {
                w0 <= 0.0 && w1 <= 0.0 && w2 <= 0.0
            }

            if inside {
                let b0 = w0 / area
                let b1 = w1 / area
                let b2 = w2 / area

                let r = b0 * v0.r + b1 * v1.r + b2 * v2.r
                let g = b0 * v0.g + b1 * v1.g + b2 * v2.g
                let b_col = b0 * v0.b + b1 * v1.b + b2 * v2.b

                let idx = py * w + px
                fb_r[idx] = clamp_byte((r * 255.0) as i64)
                fb_g[idx] = clamp_byte((g * 255.0) as i64)
                fb_b[idx] = clamp_byte((b_col * 255.0) as i64)
            }
            px = px + 1
        }
        py = py + 1
    }

    // Emit PPM P3
    print("P3\n")
    print_int(w)
    print(" ")
    print_int(h)
    print("\n255\n")
    var i: i64 = 0
    while i < w * h {
        print_int(fb_r[i])
        print(" ")
        print_int(fb_g[i])
        print(" ")
        print_int(fb_b[i])
        print("\n")
        i = i + 1
    }

}

fn uncertainty_to_alpha_1000(eps_1000: i64) -> i64 with Div {
    let clamped = if eps_1000 > 1000 { 1000 } else { eps_1000 }
    1000 - clamped * 700 / 1000
}

fn value_to_color(v_1000: i64, eps_1000: i64) -> Color with Div {
    let t_1000 = if v_1000 > 1000 { 1000 } else { if v_1000 < 0 { 0 } else { v_1000 } }
    Color {
        r: t_1000,
        g: 200,
        b: 1000 - t_1000,
        a: uncertainty_to_alpha_1000(eps_1000),
    }
}

fn fill_channel(
    x0: i64, y0: i64, rw: i64, rh: i64,
    v: i64,
    fb: &![i64; 65536],
    fb_w: i64, fb_h: i64
) with Mut, Panic, Div {
    var dy: i64 = 0
    while dy < rh {
        var dx: i64 = 0
        while dx < rw {
            let px = x0 + dx
            let py = y0 + dy
            if px >= 0 && px < fb_w && py >= 0 && py < fb_h {
                let idx = py * fb_w + px;
                (*fb)[idx] = v;
            }
            dx = dx + 1
        }
        dy = dy + 1
    }
}

fn get_channel(fb: &[i64; 65536], i: i64) -> i64 with Panic {
    (*fb)[i]
}

fn char_from_i64(n: i64) -> string with Mut, Panic {
    if n == 0 { "0" }
    else if n == 1 { "1" }
    else if n == 2 { "2" }
    else if n == 3 { "3" }
    else if n == 4 { "4" }
    else if n == 5 { "5" }
    else if n == 6 { "6" }
    else if n == 7 { "7" }
    else if n == 8 { "8" }
    else if n == 9 { "9" }
    else { "?" }
}

fn i64_to_digits_no_div(rem: i64, idx: i64, started: bool) -> string with Mut, Panic {
    if idx >= 19 { return "" }
    let power = pow10_idx(idx)
    let digit = digit_for_power(rem, power)
    let rem_next = rem + (digit * power)
    let emit = started || digit > 0 || idx == 18
    let head = if emit { char_from_i64(digit) } else { "" }
    head + i64_to_digits_no_div(rem_next, idx + 1, emit)
}

fn int_to_string(n: i64) -> string with Mut, Panic, Div {
    if n == 0 { return "0" }
    let negative = n < 0
    let rem = if negative { n } else { 0 - n }
    let digits = i64_to_digits_no_div(rem, 0, false)
    if negative { "-" + digits } else { digits }
}

fn parse_i64_decimal(raw: string) -> (bool, i64) with Mut, Div {
    if str_len(raw) == 0 { return (false, 0) }
    var idx: i64 = 0
    var negative = false
    if str_char_at(raw, 0) == "-" {
        negative = true
        idx = 1
        if idx >= str_len(raw) { return (false, 0) }
    }
    var value: i64 = 0
    while idx < str_len(raw) {
        let ch = str_char_at(raw, idx)
        if ch < "0" || ch > "9" { return (false, 0) }
        value = value * 10 + ((ch as i64) - ("0" as i64))
        idx = idx + 1
    }
    if negative { (true, 0 - value) } else { (true, value) }
}

fn cd_sigma(a: i32, b: i32) -> i32 with Mut, Panic, Div {
    // Full recursive CD sign function (same as T_7 verification)
    if a == 0 || b == 0 { return 1 }
    if a == b { return 0 - 1 }  // e_i * e_i = -1 for all imaginary units

    // Recurse using CD doubling: bits=3 for octonions
    cd_sigma_rec(a, b, 3)
}

fn generate_reverse(k: i64, delay: i64) with Mut, Div {
    var i = 0
    while i < k {
        let tok = (rng_next() / 100) % 4 + 1
        SEQ[i] = tok
        TGT[k - 1 - i] = tok  // REVERSED targets
        i = i + 1
    }
    i = k
    while i < k + delay { SEQ[i] = 0; i = i + 1 }
    SEQ[k + delay] = 5  // GO signal
}

fn init_model(is_cross: i64) with Mut, Div, Panic {
    var i = 0
    while i < 48 { ws(i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 64 {
        var v = ((rng_next() % 2000) as f64 - 1000.0) / 10000.0
        let row = i / 8; let col = i - row * 8
        if row == col { v = 0.98 }
        if is_cross == 0 { if row != col { v = 0.0 } }
        ws(48 + i, v); i = i + 1
    }
    i = 0
    while i < 8 { ws(112 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 40 { ws(120 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 160 { MOM[i] = 0; i = i + 1 }
}

fn model_step(token: i64, is_cross: i64) with Mut, Div {
    var d = 0
    if is_cross == 1 {
        var new_h: [f64; 8] = [0.0; 8]
        while d < 8 {
            let inp = wg(token * 8 + d)
            var s = 0.0
            var j = 0
            while j < 8 { s = s + wg(48 + d*8 + j) * hg(j); j = j + 1 }
            s = s + wg(112 + d) * inp
            if s > 5.0 { s = 5.0 } if s < 0.0-5.0 { s = 0.0-5.0 }
            new_h[d] = s; d = d + 1
        }
        d = 0
        while d < 8 { hs(d, new_h[d]); d = d + 1 }
    } else {
        while d < 8 {
            var s = wg(48 + d) * hg(d) + wg(112 + d) * wg(token * 8 + d)
            if s > 5.0 { s = 5.0 } if s < 0.0-5.0 { s = 0.0-5.0 }
            hs(d, s); d = d + 1
        }
    }
    var c = 0
    while c < 5 {
        var s = 0.0
        d = 0
        while d < 8 { s = s + hg(d) * wg(120 + d*5 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn update_target(tgt_tok: i64, lr: f64) with Mut, Div, Panic {
    let tc = tgt_tok - 1
    var mx = (L[0] as f64)/100000000.0
    var i = 1
    while i < 5 { let v = (L[i] as f64)/100000000.0; if v > mx { mx = v }; i = i + 1 }
    var probs: [f64; 5] = [0.0; 5]
    var se = 0.0
    i = 0
    while i < 5 { probs[i] = exp_q((L[i] as f64)/100000000.0 - mx); se = se + probs[i]; i = i + 1 }
    i = 0
    while i < 5 { probs[i] = probs[i] / se; i = i + 1 }
    probs[tc] = probs[tc] - 1.0
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var c = 0
        while c < 5 {
            let idx = 120 + d*5 + c
            var g = hd * probs[c]
            if g > 0.3 { g = 0.3 } if g < 0.0-0.3 { g = 0.0-0.3 }
            let m = (MOM[idx] as f64)/100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            c = c + 1
        }
        d = d + 1
    }
}

fn get_pred() -> i64 with Div {
    var best = 0; var bv = (L[0] as f64)/100000000.0
    var i = 1
    while i < 5 { let v = (L[i] as f64)/100000000.0; if v > bv { bv = v; best = i }; i = i + 1 }
    best + 1
}

fn run_benchmark(is_cross: i64, k: i64, delay: i64, n_epochs: i64) -> f64 with IO, Mut, Div, Panic {
    let n_train = 300
    var ep = 0
    while ep < n_epochs {
        var correct = 0
        var total = 0
        var s = 0
        while s < n_train {
            generate_reverse(k, delay)
            var d = 0
            while d < 8 { H[d] = 0; d = d + 1 }
            var t = 0
            let total_in = k + delay + 1
            while t < total_in { model_step(SEQ[t], is_cross); t = t + 1 }
            var ki = 0
            while ki < k {
                if ki > 0 { model_step(TGT[ki-1], is_cross) }
                let pred = get_pred()
                if pred == TGT[ki] { correct = correct + 1 }
                update_target(TGT[ki], 0.005)
                total = total + 1
                ki = ki + 1
            }
            s = s + 1
        }
        if ep % 10 == 0 {
            let acc = (correct as f64) / (total as f64) * 100.0
            print("    ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }
    // Eval
    var correct = 0
    var seq_correct = 0
    var s = 0
    while s < 100 {
        generate_reverse(k, delay)
        var d = 0
        while d < 8 { H[d] = 0; d = d + 1 }
        var t = 0
        let total_in = k + delay + 1
        while t < total_in { model_step(SEQ[t], is_cross); t = t + 1 }
        var sok = 1
        var ki = 0
        while ki < k {
            if ki > 0 { model_step(TGT[ki-1], is_cross) }
            let pred = get_pred()
            if pred == TGT[ki] { correct = correct + 1 } else { sok = 0 }
            ki = ki + 1
        }
        if sok == 1 { seq_correct = seq_correct + 1 }
        s = s + 1
    }
    let tacc = (correct as f64) / 300.0 * 100.0
    let sacc = (seq_correct as f64) / 100.0 * 100.0
    print("    Eval token="); print(tacc); print("% seq="); print(sacc); print("%\n")
    sacc
}

