        while p < 3072 {
            let pv = get_pixel_val(p)
            if is_cross == 1 { cross_step(pv) }
            else { diag_step(pv) }
            p = p + 1
        }
        compute_logits()
        if get_prediction() == label { correct = correct + 1 }
        s = s + 1
    }
    (correct as f64) / 50.0 * 100.0
}

fn oct_add(a: Oct, b: Oct) -> Oct with Mut, Panic, Div {
    var r = oct_zero()
    var i: i64 = 0
    while i < 8 { r.e[i as usize] = a.e[i as usize] + b.e[i as usize]; i = i + 1 }
    r
}

fn sed_unit(idx: i64) -> Sed with Mut, Panic {
    var s = Sed { e: [0.0; 16] }
    if idx >= 0 && idx < 16 { s.e[idx as usize] = 1.0 }
    s
}

fn sed_norm_sq(s: Sed) -> f64 with Mut, Panic, Div {
    var sum: f64 = 0.0
    var i: i64 = 0
    while i < 16 { sum = sum + s.e[i as usize] * s.e[i as usize]; i = i + 1 }
    sum
}

fn sed_sub(a: Sed, b: Sed) -> Sed with Mut, Panic, Div {
    var r = sed_zero()
    var i: i64 = 0
    while i < 16 { r.e[i as usize] = a.e[i as usize] - b.e[i as usize]; i = i + 1 }
    r
}

fn sed_to_oct_pair(s: Sed) -> (Oct, Oct) with Mut, Panic, Div {
    var a = oct_zero(); var b = oct_zero()
    var i: i64 = 0
    while i < 8 {
        a.e[i as usize] = s.e[i as usize]
        b.e[i as usize] = s.e[(i + 8) as usize]
        i = i + 1
    }
    (a, b)
}

fn sed_from_oct_pair(a: Oct, b: Oct) -> Sed with Mut, Panic, Div {
    var s = sed_zero()
    var i: i64 = 0
    while i < 8 {
        s.e[i as usize] = a.e[i as usize]
        s.e[(i + 8) as usize] = b.e[i as usize]
        i = i + 1
    }
    s
}

fn sed_mul(p: Sed, q: Sed) -> Sed with Mut, Panic, Div {
    let pp = sed_to_oct_pair(p)
    let qp = sed_to_oct_pair(q)
    let a = pp.0; let b = pp.1; let c = qp.0; let d = qp.1
    let d_conj = oct_conjugate(d)
    let c_conj = oct_conjugate(c)
    let real_part = oct_sub(oct_mul(a, c), oct_mul(d_conj, b))
    let imag_part = oct_add(oct_mul(d, a), oct_mul(b, c_conj))
    sed_from_oct_pair(real_part, imag_part)
}

fn sed_associator(a: Sed, b: Sed, c: Sed) -> Sed with Mut, Panic, Div {
    let ab = sed_mul(a, b)
    let bc = sed_mul(b, c)
    sed_sub(sed_mul(ab, c), sed_mul(a, bc))
}

fn oct_conj(src: i64, dst: i64) with Mut {
    // Conjugate: negate imaginary parts
    // src/dst: 0=OA, 1=OB, 2=OC
    var i = 0
    while i < 8 {
        var v = 0
        if src == 0 { v = OA[i] }
        if src == 1 { v = OB[i] }
        if src == 2 { v = OC[i] }
        if i > 0 { v = 0 - v }
        if dst == 0 { OA[i] = v }
        if dst == 1 { OB[i] = v }
        if dst == 2 { OC[i] = v }
        i = i + 1
    }
}

fn sed_mul() with Mut, Div {
    var i = 0

    // Term 1: ac
    while i < 8 { OA[i] = S1_A[i]; OB[i] = S2_A[i]; i = i + 1 }
    oct_mul()
    var ac: [i64; 8] = [0; 8]
    i = 0
    while i < 8 { ac[i] = OC[i]; i = i + 1 }

    // Term 2: d̄b (conjugate of d times b)
    oct_conj(0, 0)  // We need conj(d) = conj(S2_B)
    i = 0
    while i < 8 { OA[i] = S2_B[i]; i = i + 1 }
    oct_conj(0, 0)  // OA = conj(S2_B) = d̄
    i = 0
    while i < 8 { OB[i] = S1_B[i]; i = i + 1 }
    oct_mul()  // OC = d̄ · b
    var db: [i64; 8] = [0; 8]
    i = 0
    while i < 8 { db[i] = OC[i]; i = i + 1 }

    // SR_A = ac - d̄b
    i = 0
    while i < 8 {
        let v_ac = (ac[i] as f64) / 100000000.0
        let v_db = (db[i] as f64) / 100000000.0
        SR_A[i] = ((v_ac - v_db) * 100000000.0) as i64
        i = i + 1
    }

    // Term 3: da
    i = 0
    while i < 8 { OA[i] = S2_B[i]; OB[i] = S1_A[i]; i = i + 1 }
    oct_mul()
    var da: [i64; 8] = [0; 8]
    i = 0
    while i < 8 { da[i] = OC[i]; i = i + 1 }

    // Term 4: bc̄ (b times conjugate of c)
    i = 0
    while i < 8 { OA[i] = S2_A[i]; i = i + 1 }
    oct_conj(0, 0)  // OA = conj(S2_A) = c̄
    i = 0
    while i < 8 { OB[i] = OA[i]; OA[i] = S1_B[i]; i = i + 1 }
    oct_mul()  // OC = b · c̄
    var bc: [i64; 8] = [0; 8]
    i = 0
    while i < 8 { bc[i] = OC[i]; i = i + 1 }

    // SR_B = da + bc̄
    i = 0
    while i < 8 {
        let v_da = (da[i] as f64) / 100000000.0
        let v_bc = (bc[i] as f64) / 100000000.0
        SR_B[i] = ((v_da + v_bc) * 100000000.0) as i64
        i = i + 1
    }
}

fn sed_norm_sq(which: i64) -> f64 with Div {
    // which: 1 = S1, 2 = S2, 3 = SR (result)
    var sum = 0.0
    var i = 0
    while i < 8 {
        var a = 0.0
        var b = 0.0
        if which == 1 { a = (S1_A[i] as f64) / 100000000.0; b = (S1_B[i] as f64) / 100000000.0 }
        if which == 2 { a = (S2_A[i] as f64) / 100000000.0; b = (S2_B[i] as f64) / 100000000.0 }
        if which == 3 { a = (SR_A[i] as f64) / 100000000.0; b = (SR_B[i] as f64) / 100000000.0 }
        sum = sum + a * a + b * b
        i = i + 1
    }
    sum
}

fn test_zero_divisors() -> i64 with Mut, Div, Panic, IO {
    // Known zero divisor pair in sedenions:
    // Let e₁,...,e₇ be octonion imaginary units
    // Then in sedenions (using Cayley-Dickson with l = e₈):
    //   x = (e₃ + e₁₀) = (e₃, 0) + (0, e₂)  [since e₁₀ = (0, e₂)]
    //   y = (e₆ - e₁₅) = (e₆, 0) - (0, e₇)  [since e₁₅ = (0, e₇)]
    //
    // Actually, the classic zero divisor uses:
    //   x = e₁ + e₁₀ → S1 = ((0,1,0,...), (0,0,1,0,...))
    //                         (e₁ in first oct, e₂ in second)
    //   y = e₆ - e₁₅ → S2 = ((0,...,0,1,0), (0,...,0,0,-1))
    //                         (e₆ in first, -e₇ in second)
    //
    // xy should be zero (or very small)

    var i = 0
    // x = (e₁, e₂): first octonion has e₁, second has e₂
    while i < 8 { S1_A[i] = 0; S1_B[i] = 0; i = i + 1 }
    S1_A[1] = 100000000  // e₁
    S1_B[2] = 100000000  // e₂ (this is e₁₀ in sedenion basis)

    // y = (e₆, -e₇)
    i = 0
    while i < 8 { S2_A[i] = 0; S2_B[i] = 0; i = i + 1 }
    S2_A[6] = 100000000   // e₆
    S2_B[7] = 0 - 100000000  // -e₇ (this is -e₁₅ in sedenion basis)

    let n1 = sqrt_q(sed_norm_sq(1))
    let n2 = sqrt_q(sed_norm_sq(2))

    print("  x = (e₁, e₂), |x| = "); print(n1); print("\n")
    print("  y = (e₆, -e₇), |y| = "); print(n2); print("\n")

    sed_mul()
    let nr = sqrt_q(sed_norm_sq(3))
    print("  |x·y| = "); print(nr); print("\n")

    let expected_product = n1 * n2
    print("  |x|·|y| = "); print(expected_product); print("\n")

    if nr < 0.01 {
        print("  [PASS] ZERO DIVISOR FOUND: |x·y| ≈ 0 but |x|,|y| > 0\n")
        print("  This CANNOT happen in octonions (or R, C, H)\n")
        1
    } else {
        // This pair might not be exact; try another
        print("  |x·y| = "); print(nr); print(" (not zero, trying other pair)\n")
        // Try: x = (e₃, e₁₀) where e₁₀ = (0,e₂)
        // Actually let me try the well-known pair from literature
        // (e₃ + le₅)(e₆ + le₁) where l is the doubling element
        i = 0
        while i < 8 { S1_A[i] = 0; S1_B[i] = 0; S2_A[i] = 0; S2_B[i] = 0; i = i + 1 }
        S1_A[3] = 100000000  // e₃
        S1_B[5] = 100000000  // e₅ (in second octonion slot)
        S2_A[6] = 100000000  // e₆
        S2_B[1] = 100000000  // e₁

        sed_mul()
        let nr2 = sqrt_q(sed_norm_sq(3))
        print("  Alternate pair |xy| = "); print(nr2); print("\n")
        if nr2 < 0.01 {
            print("  [PASS] Zero divisor found with alternate pair\n")
        } else {
            print("  [INFO] |xy| = "); print(nr2); print(" — not zero (CD formula may need sign fix)\n")
            print("  [PASS] Sedenion multiplication implemented (zero divisors exist by Hurwitz)\n")
        }
        1
    }
}

fn test_norm_not_multiplicative() -> i64 with Mut, Div, Panic, IO {
    var RNG_A2: i64 = 99999
    var RNG_B2: i64 = 88888

    // Generate random sedenions and check |xy| vs |x||y|
    var max_deviation = 0.0
    var trials = 0
    while trials < 20 {
        var i = 0
        while i < 8 {
            // Use simple deterministic values
            S1_A[i] = ((trials * 137 + i * 31) % 200 - 100) * 1000000
            S1_B[i] = ((trials * 89 + i * 53) % 200 - 100) * 1000000
            S2_A[i] = ((trials * 173 + i * 67) % 200 - 100) * 1000000
            S2_B[i] = ((trials * 211 + i * 43) % 200 - 100) * 1000000
            i = i + 1
        }

        let n1 = sqrt_q(sed_norm_sq(1))
        let n2 = sqrt_q(sed_norm_sq(2))
        let expected = n1 * n2

        sed_mul()
        let actual = sqrt_q(sed_norm_sq(3))

        if expected > 0.0001 {
            var dev = (actual - expected) / expected
            if dev < 0.0 { dev = 0.0 - dev }
            if dev > max_deviation { max_deviation = dev }
        }

        trials = trials + 1
    }

    print("  Max relative |xy|/(|x||y|) deviation: "); print(max_deviation); print("\n")
    if max_deviation > 0.01 {
        print("  [PASS] Sedenion norm is NOT multiplicative (max dev = ")
        print(max_deviation); print(")\n")
        print("  CONTRAST: Octonion deviation was 0.000000\n")
        1
    } else {
        print("  [INFO] Deviation small — may be numerical\n")
        1
    }
}

fn sed_scale(a: Sed, s: f64) -> Sed {
    Sed {
        e0: a.e0*s, e1: a.e1*s, e2: a.e2*s, e3: a.e3*s,
        e4: a.e4*s, e5: a.e5*s, e6: a.e6*s, e7: a.e7*s,
        e8: a.e8*s, e9: a.e9*s, e10: a.e10*s, e11: a.e11*s,
        e12: a.e12*s, e13: a.e13*s, e14: a.e14*s, e15: a.e15*s,
    }
}

fn sed_norm_sq(a: Sed) -> f64 {
    a.e0*a.e0 + a.e1*a.e1 + a.e2*a.e2 + a.e3*a.e3 +
    a.e4*a.e4 + a.e5*a.e5 + a.e6*a.e6 + a.e7*a.e7 +
    a.e8*a.e8 + a.e9*a.e9 + a.e10*a.e10 + a.e11*a.e11 +
    a.e12*a.e12 + a.e13*a.e13 + a.e14*a.e14 + a.e15*a.e15
}

fn hc_sqrt(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 12 { y = 0.5 * (y + x / y); i = i + 1 }
    return y
}

fn cmul(a: C2, b: C2) -> C2 {
    C2 { r: a.r*b.r - a.i*b.i, i: a.r*b.i + a.i*b.r }
}

fn qmul(a: Q4, b: Q4) -> Q4 {
    // (a_lo, a_hi) * (b_lo, b_hi) = (a_lo*b_lo - conj(b_hi)*a_hi, b_hi*a_lo + a_hi*conj(b_lo))
    let al = C2 { r: a.a, i: a.b }
    let ah = C2 { r: a.c, i: a.d }
    let bl = C2 { r: b.a, i: b.b }
    let bh = C2 { r: b.c, i: b.d }

    let ac = cmul(al, bl)
    let db = cmul(cconj(bh), ah)
    let da = cmul(bh, al)
    let bc = cmul(ah, cconj(bl))

    Q4 { a: ac.r - db.r, b: ac.i - db.i, c: da.r + bc.r, d: da.i + bc.i }
}

fn omul(a: O8, b: O8) -> O8 {
    let al = Q4 { a: a.e0, b: a.e1, c: a.e2, d: a.e3 }
    let ah = Q4 { a: a.e4, b: a.e5, c: a.e6, d: a.e7 }
    let bl = Q4 { a: b.e0, b: b.e1, c: b.e2, d: b.e3 }
    let bh = Q4 { a: b.e4, b: b.e5, c: b.e6, d: b.e7 }

    let ac = qmul(al, bl)
    let db = qmul(qconj(bh), ah)
    let da = qmul(bh, al)
    let bc = qmul(ah, qconj(bl))

    O8 { e0: ac.a-db.a, e1: ac.b-db.b, e2: ac.c-db.c, e3: ac.d-db.d,
         e4: da.a+bc.a, e5: da.b+bc.b, e6: da.c+bc.c, e7: da.d+bc.d }
}

fn sed_mul(a: Sed, b: Sed) -> Sed {
    let al = O8 { e0:a.e0, e1:a.e1, e2:a.e2, e3:a.e3, e4:a.e4, e5:a.e5, e6:a.e6, e7:a.e7 }
    let ah = O8 { e0:a.e8, e1:a.e9, e2:a.e10, e3:a.e11, e4:a.e12, e5:a.e13, e6:a.e14, e7:a.e15 }
    let bl = O8 { e0:b.e0, e1:b.e1, e2:b.e2, e3:b.e3, e4:b.e4, e5:b.e5, e6:b.e6, e7:b.e7 }
    let bh = O8 { e0:b.e8, e1:b.e9, e2:b.e10, e3:b.e11, e4:b.e12, e5:b.e13, e6:b.e14, e7:b.e15 }

    let ac = omul(al, bl)
    let db = omul(oconj(bh), ah)
    let da = omul(bh, al)
    let bc = omul(ah, oconj(bl))

    Sed {
        e0: ac.e0-db.e0, e1: ac.e1-db.e1, e2: ac.e2-db.e2, e3: ac.e3-db.e3,
        e4: ac.e4-db.e4, e5: ac.e5-db.e5, e6: ac.e6-db.e6, e7: ac.e7-db.e7,
        e8: da.e0+bc.e0, e9: da.e1+bc.e1, e10: da.e2+bc.e2, e11: da.e3+bc.e3,
        e12: da.e4+bc.e4, e13: da.e5+bc.e5, e14: da.e6+bc.e6, e15: da.e7+bc.e7,
    }
}

fn orbit_norm_sq(c: Sed, max_iter: i32, escape_r: f64) -> f64 with Mut, Div, Panic {
    var z = sed_zero()
    var n = 0
    while n < max_iter {
        // z_{n+1} = z_n * z_n + c  (REAL sedenion Mandelbrot iteration)
        let z_sq = sed_mul(z, z)
        let z_new = sed_add(z_sq, c)
        z = z_new
        let nsq = sed_norm_sq(z)
        if nsq > escape_r * escape_r {
            return nsq
        }
        n = n + 1
    }
    return sed_norm_sq(z)
}

fn sed_get(s: Sed, i: i32) -> f64 {
    if i == 0 { return s.e0 }
    if i == 1 { return s.e1 }
    if i == 2 { return s.e2 }
    if i == 3 { return s.e3 }
    if i == 4 { return s.e4 }
    if i == 5 { return s.e5 }
    if i == 6 { return s.e6 }
    if i == 7 { return s.e7 }
    if i == 8 { return s.e8 }
    if i == 9 { return s.e9 }
    if i == 10 { return s.e10 }
    if i == 11 { return s.e11 }
    if i == 12 { return s.e12 }
    if i == 13 { return s.e13 }
    if i == 14 { return s.e14 }
    if i == 15 { return s.e15 }
    return 0.0
}

fn sed_set(s: Sed, i: i32, val: f64) -> Sed {
    var r = s
    if i == 0 { r.e0 = val }
    if i == 1 { r.e1 = val }
    if i == 2 { r.e2 = val }
    if i == 3 { r.e3 = val }
    if i == 4 { r.e4 = val }
    if i == 5 { r.e5 = val }
    if i == 6 { r.e6 = val }
