fn sqrt_f64(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    var g = x / 2.0
    if g < 1.0 { g = 1.0 }
    var i = 0
    while i < 60 { g = (g + x / g) / 2.0; i = i + 1 }
    g
}

fn empty_metrics() -> StageMetrics {
    StageMetrics {
        items_processed: 0,
        items_filtered: 0,
        total_time_ms: 0.0,
        avg_quality: 0.0
    }
}

fn stage_validate(items: [DataItem], count: i32) -> [DataItem] with Mut, Panic, Div {
    var out = items  // copy
    var i = 0
    while i < count {
        let item = items[i]
        // Validate: value must be in reasonable range
        if item.value < -1000.0 || item.value > 1000.0 {
            out[i] = DataItem {
                id: item.id,
                value: item.value,
                processed: false,
                quality: 0.0
            }
        } else {
            out[i] = DataItem {
                id: item.id,
                value: item.value,
                processed: true,
                quality: 0.5  // base quality after validation
            }
        }
        i = i + 1
    }
    out
}

fn stage_normalize(items: [DataItem], count: i32) -> [DataItem] with Mut, Panic, Div {
    // Find min/max of valid items
    var min_val = 1e10
    var max_val = -1e10
    var i = 0
    while i < count {
        if items[i].processed {
            if items[i].value < min_val { min_val = items[i].value }
            if items[i].value > max_val { max_val = items[i].value }
        }
        i = i + 1
    }

    let range = max_val - min_val
    var out = items
    i = 0
    while i < count {
        if items[i].processed && range > 0.001 {
            let normalized = (items[i].value - min_val) / range
            out[i] = DataItem {
                id: items[i].id,
                value: normalized,
                processed: true,
                quality: 0.7  // higher quality after normalization
            }
        }
        i = i + 1
    }
    out
}

fn stage_enrich(items: [DataItem], count: i32) -> [DataItem] with Mut, Panic, Div {
    var out = items
    var i = 0
    while i < count {
        if items[i].processed {
            // Squared transform (feature engineering)
            let enriched_val = items[i].value * items[i].value
            out[i] = DataItem {
                id: items[i].id,
                value: enriched_val,
                processed: true,
                quality: 0.85
            }
        }
        i = i + 1
    }
    out
}

fn stage_score(items: [DataItem], count: i32) -> [DataItem] with Mut, Panic, Div {
    // Compute mean and stddev of processed values
    var sum = 0.0
    var sum_sq = 0.0
    var n = 0
    var i = 0
    while i < count {
        if items[i].processed {
            sum = sum + items[i].value
            sum_sq = sum_sq + items[i].value * items[i].value
            n = n + 1
        }
        i = i + 1
    }

    let mean = if n > 0 { sum / (n as f64) } else { 0.0 }
    let variance = if n > 1 { (sum_sq - sum * sum / (n as f64)) / ((n - 1) as f64) } else { 0.0 }
    let stddev = sqrt_f64(abs_f64(variance))

    var out = items
    i = 0
    while i < count {
        if items[i].processed {
            // Quality based on distance from mean (z-score)
            let z = if stddev > 0.001 { abs_f64(items[i].value - mean) / stddev } else { 0.0 }
            let quality = if z < 1.0 { 0.95 }
                         else if z < 2.0 { 0.80 }
                         else if z < 3.0 { 0.60 }
                         else { 0.30 }
            out[i] = DataItem {
                id: items[i].id,
                value: items[i].value,
                processed: true,
                quality: quality
            }
        }
        i = i + 1
    }
    out
}

fn compute_metrics(items: [DataItem], count: i32) -> StageMetrics with Mut, Panic, Div {
    var processed = 0
    var filtered = 0
    var quality_sum = 0.0
    var i = 0
    while i < count {
        if items[i].processed {
            processed = processed + 1
            quality_sum = quality_sum + items[i].quality
        } else {
            filtered = filtered + 1
        }
        i = i + 1
    }
    let avg_q = if processed > 0 { quality_sum / (processed as f64) } else { 0.0 }
    StageMetrics {
        items_processed: processed,
        items_filtered: filtered,
        total_time_ms: 0.0,
        avg_quality: avg_q
    }
}

fn exp_decay(x: f64) -> f64 with Mut, Panic, Div {
    // e^(-x) for positive x via Taylor series
    let neg_x = 0.0 - x
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 30 {
        term = term * neg_x / (n as f64)
        sum = sum + term
        n = n + 1
    }
    if sum < 0.0 { return 0.0 }
    sum
}

fn pk_derivatives(state: PKState, ka: f64, ke: f64, k12: f64, k21: f64) -> PKState {
    // dGut/dt = -ka * Gut
    let d_gut = 0.0 - ka * state.gut

    // dCentral/dt = ka*Gut - ke*Central - k12*Central + k21*Peripheral
    let d_central = ka * state.gut - ke * state.central
                  - k12 * state.central + k21 * state.peripheral

    // dPeripheral/dt = k12*Central - k21*Peripheral
    let d_peripheral = k12 * state.central - k21 * state.peripheral

    PKState {
        gut: d_gut,
        central: d_central,
        peripheral: d_peripheral
    }
}

fn euler_step(state: PKState, ka: f64, ke: f64, k12: f64, k21: f64, dt: f64) -> PKState {
    let deriv = pk_derivatives(state, ka, ke, k12, k21)
    PKState {
        gut:        max_f64(0.0, state.gut + dt * deriv.gut),
        central:    max_f64(0.0, state.central + dt * deriv.central),
        peripheral: max_f64(0.0, state.peripheral + dt * deriv.peripheral)
    }
}

fn simulate_pk(params: TwoCompartmentParams, t_end: f64, dt: f64, report_dt: f64) with IO, Mut, Panic, Div {
    // Nominal parameters
    let ka = params.ka.value
    let ke = params.ke.value
    let k12 = params.k12.value
    let k21 = params.k21.value
    let vc = params.v_central.value
    let dose = params.dose.value

    // Perturbed parameters (±1 sigma)
    let ka_lo = params.ka.value - params.ka.uncertainty
    let ke_lo = params.ke.value - params.ke.uncertainty
    let k12_lo = params.k12.value - params.k12.uncertainty
    let k21_lo = params.k21.value - params.k21.uncertainty
    let vc_hi = params.v_central.value + params.v_central.uncertainty
    let dose_lo = params.dose.value - params.dose.uncertainty

    let ka_hi = params.ka.value + params.ka.uncertainty
    let ke_hi = params.ke.value + params.ke.uncertainty
    let k12_hi = params.k12.value + params.k12.uncertainty
    let k21_hi = params.k21.value + params.k21.uncertainty
    let vc_lo = params.v_central.value - params.v_central.uncertainty
    let dose_hi = params.dose.value + params.dose.uncertainty

    // Initial states
    var state_nom = PKState { gut: dose, central: 0.0, peripheral: 0.0 }
    var state_lo = PKState { gut: dose_lo, central: 0.0, peripheral: 0.0 }
    var state_hi = PKState { gut: dose_hi, central: 0.0, peripheral: 0.0 }

    var t = 0.0
    var next_report = 0.0
    let total_steps = ((t_end / dt) as i32) + 1
    var step = 0

    println("Time(h) | Conc_nom(mg/L) | Conc_lo | Conc_hi | Confidence")
    println("--------|----------------|---------|---------|----------")

    while step < total_steps && t <= t_end {
        if t >= next_report - dt * 0.5 {
            let c_nom = state_nom.central / vc
            let c_lo = min_f64(state_lo.central / vc_hi, state_hi.central / vc_hi)
            let c_hi = max_f64(state_lo.central / vc_lo, state_hi.central / vc_lo)

            // Confidence: high when band is narrow relative to value
            let band_width = abs_f64(c_hi - c_lo)
            let conf = if c_nom > 0.01 {
                let relative_width = band_width / c_nom
                if relative_width < 0.1 { 0.95 }
                else if relative_width < 0.3 { 0.80 }
                else if relative_width < 0.5 { 0.60 }
                else { 0.40 }
            } else { 0.20 }

            println(t)
            println(c_nom)
            println(c_lo)
            println(c_hi)
            println(conf)
            println("---")

            next_report = next_report + report_dt
        }

        state_nom = euler_step(state_nom, ka, ke, k12, k21, dt)
        state_lo = euler_step(state_lo, ka_lo, ke_lo, k12_lo, k21_lo, dt)
        state_hi = euler_step(state_hi, ka_hi, ke_hi, k12_hi, k21_hi, dt)

        t = t + dt
        step = step + 1
    }
}

fn check_therapeutic_window(params: TwoCompartmentParams, min_conc: f64, max_conc: f64) with IO, Mut, Panic, Div {
    let ka = params.ka.value
    let ke = params.ke.value
    let k12 = params.k12.value
    let k21 = params.k21.value
    let vc = params.v_central.value
    let dose = params.dose.value

    var state = PKState { gut: dose, central: 0.0, peripheral: 0.0 }
    let dt = 0.01
    var t = 0.0
    var t_above_min = -1.0
    var t_below_max = -1.0
    var peak_conc = 0.0
    var peak_time = 0.0

    var step = 0
    while step < 4800 {  // 48 hours
        state = euler_step(state, ka, ke, k12, k21, dt)
        let conc = state.central / vc

        if conc > peak_conc {
            peak_conc = conc
            peak_time = t
        }

        if conc >= min_conc && t_above_min < 0.0 {
            t_above_min = t
        }

        if conc > max_conc && t_below_max < 0.0 {
            t_below_max = t
        }

        t = t + dt
        step = step + 1
    }

    println("")
    println("=== Therapeutic Window Analysis ===")
    println("Minimum effective concentration (mg/L):")
    println(min_conc)
    println("Maximum safe concentration (mg/L):")
    println(max_conc)
    println("Peak concentration (mg/L):")
    println(peak_conc)
    println("Time to peak (h):")
    println(peak_time)

    if peak_conc > max_conc {
        println("WARNING: Peak exceeds maximum safe concentration!")
    }
    if peak_conc < min_conc {
        println("WARNING: Drug never reaches therapeutic levels!")
    }
    if peak_conc >= min_conc && peak_conc <= max_conc {
        println("Drug remains within therapeutic window at peak.")
    }
}

fn new_capture() -> LogCapture {
    // Pre-allocate entries array
    let empty = LogEntry { level: 0, message: 0 }
    LogCapture {
        entries: [empty, empty, empty, empty, empty,
                  empty, empty, empty, empty, empty],
        count: 0,
        max_entries: 10
    }
}

fn capture_log(capture: LogCapture, level: i32, msg: i32) -> LogCapture with Mut, Panic {
    if capture.count >= capture.max_entries {
        return capture
    }
    var new_capture_val = capture
    new_capture_val.entries[capture.count] = LogEntry { level: level, message: msg }
    new_capture_val.count = capture.count + 1
    new_capture_val
}

fn level_name(level: i32) -> i32 {
    level  // simplified
}

fn validate_item(item: Item) -> bool {
    // Business rule: value must be positive and less than 10000
    item.value > 0.0 && item.value < 10000.0
}

fn process_items(items: [Item], count: i32) -> ProcessResult with Mut, Panic, Div {
    var log = new_capture()
    var accepted = 0
    var rejected = 0
    var total = 0.0

    // Log start
    log = capture_log(log, 1, 100)  // info: processing started

    var i = 0
    while i < count {
        let item = items[i]
        if validate_item(item) {
            accepted = accepted + 1
            total = total + item.value
            log = capture_log(log, 0, 101)  // debug: item validated
        } else {
            rejected = rejected + 1
            if item.value < 0.0 {
                log = capture_log(log, 3, 400)  // error: negative value
            } else {
                log = capture_log(log, 2, 300)  // warn: invalid item
            }
            log = capture_log(log, 1, 102)  // info: item rejected
        }
        i = i + 1
    }

    // Log completion
    log = capture_log(log, 1, 200)  // info: processing complete

    ProcessResult {
        accepted: accepted,
        rejected: rejected,
        total_value: total,
        log: log
    }
}

fn assert_eq_i32(actual: i32, expected: i32, result: TestResult) -> TestResult {
    if actual == expected {
        TestResult {
            name: result.name,
            passed: result.passed,
            checks: result.checks + 1,
            failures: result.failures
        }
    } else {
        TestResult {
            name: result.name,
            passed: false,
            checks: result.checks + 1,
            failures: result.failures + 1
        }
    }
}

fn assert_true(condition: bool, result: TestResult) -> TestResult {
    if condition {
        TestResult {
            name: result.name,
            passed: result.passed,
            checks: result.checks + 1,
            failures: result.failures
        }
    } else {
        TestResult {
            name: result.name,
            passed: false,
            checks: result.checks + 1,
            failures: result.failures + 1
        }
    }
}

