fn ln_approx(x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return -100.0 }  // sentinel for log(0)
    var y = x - 1.0
    if abs_f64(y) < 0.5 {
        // Series around x=1: ln(1+y) = y - y^2/2 + y^3/3 - ...
        var sum = 0.0
        var term = y
        var n = 1
        while n <= 30 {
            sum = sum + term / (n as f64)
            term = 0.0 - term * y
            n = n + 1
        }
        return sum
    }
    // Newton iteration on e^y = x
    var guess = 0.0
    if x > 1.0 { guess = x / 2.0 }
    if guess > 10.0 { guess = 10.0 }
    var iter = 0
    while iter < 50 {
        let eg = exp_approx(guess)
        if abs_f64(eg) < 1e-30 { break }
        guess = guess - (eg - x) / eg
        iter = iter + 1
    }
    guess
}

fn exp_approx(x: f64) -> f64 with Mut, Panic, Div {
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 30 {
        term = term * x / (n as f64)
        sum = sum + term
        n = n + 1
    }
    sum
}

fn log2_approx(x: f64) -> f64 with Mut, Panic, Div {
    let ln2 = 0.6931471805599453
    ln_approx(x) / ln2
}

fn base_to_idx(base: i32) -> i32 {
    // ASCII: A=65, C=67, G=71, T=84
    if base == 65 { return 0 }  // A
    if base == 67 { return 1 }  // C
    if base == 71 { return 2 }  // G
    if base == 84 { return 3 }  // T
    return -1
}

fn idx_to_base(idx: i32) -> i32 {
    if idx == 0 { return 65 }
    if idx == 1 { return 67 }
    if idx == 2 { return 71 }
    if idx == 3 { return 84 }
    return 78  // N
}

fn column_information(pwm: PWM, col: i32) -> f64 with Mut, Panic, Div {
    var ic = 2.0  // max entropy for 4 bases
    var base = 0
    while base < 4 {
        let p = pwm.weights[col * 4 + base]
        if p > 0.001 {
            ic = ic + p * log2_approx(p)
        }
        base = base + 1
    }
    if ic < 0.0 { ic = 0.0 }
    ic
}

fn total_information(pwm: PWM) -> f64 with Mut, Panic, Div {
    var total = 0.0
    var pos = 0
    while pos < pwm.length {
        total = total + column_information(pwm, pos)
        pos = pos + 1
    }
    total
}

fn score_window(pwm: PWM, sequence: [i32], start: i32) -> f64 with Mut, Panic, Div {
    var score = 0.0
    var pos = 0
    while pos < pwm.length {
        let base_idx = base_to_idx(sequence[start + pos])
        if base_idx >= 0 {
            let freq = pwm.weights[pos * 4 + base_idx]
            if freq > 0.001 {
                score = score + log2_approx(freq / 0.25)
            } else {
                score = score - 10.0  // heavy penalty for near-zero
            }
        }
        pos = pos + 1
    }
    score
}

fn hit_confidence(score: f64, threshold: f64, max_possible: f64) -> f64 with Panic, Div {
    if score < threshold { return 0.0 }
    let normalized = (score - threshold) / (max_possible - threshold + 0.001)
    if normalized > 1.0 { return 0.95 }
    if normalized < 0.0 { return 0.0 }
    // Sigmoid-like mapping to confidence
    normalized * 0.9 + 0.05
}

fn scan_sequence(
    pwm: PWM,
    sequence: [i32],
    seq_len: i32,
    threshold: f64
) -> [ScoredHit] with Mut, Panic, Div {
    // Pre-compute max possible score
    var max_score = 0.0
    var pos = 0
    while pos < pwm.length {
        var max_col = -100.0
        var b = 0
        while b < 4 {
            let w = pwm.weights[pos * 4 + b]
            if w > 0.001 {
                let s = log2_approx(w / 0.25)
                if s > max_col { max_col = s }
            }
            b = b + 1
        }
        max_score = max_score + max_col
        pos = pos + 1
    }

    // Scan all windows
    let sentinel = ScoredHit { position: -1, score: 0.0, confidence: 0.0 }
    var hits = [sentinel, sentinel, sentinel, sentinel, sentinel,
                sentinel, sentinel, sentinel, sentinel, sentinel]
    var hit_count = 0
    let max_start = seq_len - pwm.length

    var i = 0
    while i <= max_start && hit_count < 10 {
        let score = score_window(pwm, sequence, i)
        if score >= threshold {
            let conf = hit_confidence(score, threshold, max_score)
            hits[hit_count] = ScoredHit {
                position: i,
                score: score,
                confidence: conf
            }
            hit_count = hit_count + 1
        }
        i = i + 1
    }

    hits
}

fn sqrt_f64(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var g = x / 2.0
    if g < 1.0 { g = 1.0 }
    var i = 0
    while i < 60 { g = (g + x / g) / 2.0; i = i + 1 }
    g
}

fn hash_init(seed: i32, idx: i32) -> f64 with Div, Panic {
    let raw = seed + idx * 7 + 13
    let h = (raw * 31 + 17) % 997
    (h as f64) / 997.0 * 0.2 - 0.1
}

fn sed_init(seed: i32) -> Sed16 with Div, Panic {
    Sed16 { c: [
        hash_init(seed, 0),  hash_init(seed, 1),  hash_init(seed, 2),  hash_init(seed, 3),
        hash_init(seed, 4),  hash_init(seed, 5),  hash_init(seed, 6),  hash_init(seed, 7),
        hash_init(seed, 8),  hash_init(seed, 9),  hash_init(seed, 10), hash_init(seed, 11),
        hash_init(seed, 12), hash_init(seed, 13), hash_init(seed, 14), hash_init(seed, 15)
    ] }
}

fn sed_dot(a: Sed16, b: Sed16) -> f64 with Mut, Panic, Div {
    var sum = 0.0
    var i = 0
    while i < 16 {
        sum = sum + a.c[i] * b.c[i]
        i = i + 1
    }
    sum
}

fn sed_norm(a: Sed16) -> f64 with Mut, Div, Panic {
    sqrt_f64(sed_dot(a, a))
}

fn distmult_score(h: Sed16, r: Sed16, t: Sed16) -> f64 with Mut, Panic, Div {
    var sum = 0.0
    var i = 0
    while i < 16 {
        sum = sum + h.c[i] * r.c[i] * t.c[i]
        i = i + 1
    }
    sum
}

fn init_embeddings(num_e: i32, num_r: i32) -> Embeddings with Div, Panic {
    // Initialize with deterministic pseudo-random values
    Embeddings {
        entities: [
            sed_init(100), sed_init(200), sed_init(300),
            sed_init(400), sed_init(500)
        ],
        relations: [
            sed_init(1000), sed_init(2000), sed_init(3000)
        ],
        num_entities: num_e,
        num_relations: num_r
    }
}

fn margin_loss(pos_score: f64, neg_score: f64, margin: f64) -> f64 {
    let loss = margin - pos_score + neg_score
    if loss > 0.0 { loss } else { 0.0 }
}

fn train_step(
    emb: Embeddings,
    triple: Triple,
    neg_tail: i32,
    lr: f64,
    margin: f64
) -> Embeddings with Mut, Panic, Div {
    let h = emb.entities[triple.h]
    let r = emb.relations[triple.r]
    let t = emb.entities[triple.t]
    let t_neg = emb.entities[neg_tail]

    let pos_score = distmult_score(h, r, t)
    let neg_score = distmult_score(h, r, t_neg)

    let loss = margin_loss(pos_score, neg_score, margin)

    if loss <= 0.0 {
        return emb  // no update needed
    }

    // Gradient: positive triple gets pushed up, negative gets pushed down
    // d_loss/d_h = r*t_neg - r*t  (simplified gradient direction)
    var grad_h = sed_zero()
    var grad_t = sed_zero()
    var grad_tn = sed_zero()
    var i = 0
    while i < 16 {
        grad_h.c[i] = r.c[i] * (t_neg.c[i] - t.c[i])
        grad_t.c[i] = 0.0 - h.c[i] * r.c[i]
        grad_tn.c[i] = h.c[i] * r.c[i]
        i = i + 1
    }

    // Update embeddings (SGD)
    var new_emb = emb
    new_emb.entities[triple.h] = sed_sub(h, sed_scale(lr, grad_h))
    new_emb.entities[triple.t] = sed_sub(t, sed_scale(lr, grad_t))
    new_emb.entities[neg_tail] = sed_sub(t_neg, sed_scale(lr, grad_tn))

    new_emb
}

fn evaluate_rank(emb: Embeddings, triple: Triple) -> i32 with Mut, Panic, Div {
    let h = emb.entities[triple.h]
    let r = emb.relations[triple.r]
    let true_score = distmult_score(h, r, emb.entities[triple.t])

    // Rank among all entities as tail
    var rank = 1
    var e = 0
    while e < emb.num_entities {
        if e != triple.t {
            let score = distmult_score(h, r, emb.entities[e])
            if score > true_score {
                rank = rank + 1
            }
        }
        e = e + 1
    }
    return rank
}

fn file_open(path: i32) -> FileHandle with IO {
    println("  [OPEN] file descriptor allocated")
    FileHandle { fd: 42, path: path, is_open: true }
}

fn file_write(handle: FileHandle, data: i32) -> WriteResult with IO {
    if !handle.is_open {
        println("  [ERROR] write to closed handle!")
        return WriteResult { bytes_written: 0, handle: handle }
    }
    println("  [WRITE] data written")
    WriteResult {
        bytes_written: 4,
        handle: FileHandle { fd: handle.fd, path: handle.path, is_open: true }
    }
}

fn file_read(handle: FileHandle) -> ReadResult with IO {
    if !handle.is_open {
        println("  [ERROR] read from closed handle!")
        return ReadResult { data: 0, bytes_read: 0, handle: handle }
    }
    println("  [READ] data read")
    ReadResult {
        data: 12345,
        bytes_read: 4,
        handle: FileHandle { fd: handle.fd, path: handle.path, is_open: true }
    }
}

fn file_close(handle: FileHandle) with IO {
    if handle.is_open {
        println("  [CLOSE] file descriptor released")
    } else {
        println("  [WARN] closing already-closed handle")
    }
    // Handle is consumed here — it cannot be used again
}

fn pool_create(size: i32) -> Pool with IO {
    println("  [POOL] created with capacity:")
    println(size)
    Pool { size: size, available: size }
}

fn pool_acquire(pool: Pool) -> Connection with IO {
    if pool.available <= 0 {
        println("  [POOL] exhausted! No connections available")
        return Connection { id: -1, active: false }
    }
    let conn_id = pool.size - pool.available + 1
    println("  [POOL] connection acquired, id:")
    println(conn_id)
    Connection { id: conn_id, active: true }
}

fn pool_release(conn: Connection) with IO {
    if conn.active {
        println("  [POOL] connection released, id:")
        println(conn.id)
    }
    // Connection is consumed here
}

fn process_file() with IO, Mut {
    println("--- File Processing Pipeline ---")
    println("")

    // 1. Open the file (creates linear resource)
    var handle = file_open(1)

    // 2. Write data (handle transferred in, transferred out)
    let w1 = file_write(handle, 100)
    handle = w1.handle
    println("  Bytes written:")
    println(w1.bytes_written)

    // 3. Write more data
    let w2 = file_write(handle, 200)
    handle = w2.handle
    println("  Bytes written:")
    println(w2.bytes_written)

    // 4. Read data back
    let r1 = file_read(handle)
    handle = r1.handle
    println("  Data read:")
    println(r1.data)

    // 5. MUST close — linear types enforce this!
    file_close(handle)

    // At this point, `handle` is consumed.
    // Any attempt to use it again would be a compile error:
    //   file_write(handle, 300)  // ERROR: use after move
    //   file_close(handle)       // ERROR: double close

    println("")
    println("File handle properly consumed.")
    println("No resource leak possible!")
    println("")
}

fn use_connections() with IO {
    println("--- Connection Pool (Affine Types) ---")
    println("")

    let pool = pool_create(3)

    // Acquire connections
    let c1 = pool_acquire(pool)
    // Note: pool is consumed here — can't double-acquire

    // Use the connection
    println("  Using connection:")
    println(c1.id)

    // Release it (affine: we choose to release, but could also drop)
    pool_release(c1)

    println("")
    println("Connection properly returned to pool.")
    println("")
}

fn guard_enter(name: i32) -> ScopeGuard with IO {
    println("  [GUARD] entering scope")
    ScopeGuard { name: name, active: true }
}

fn guard_exit(g: ScopeGuard) with IO {
    println("  [GUARD] exiting scope, cleanup performed")
    // Guard is consumed — cleanup guaranteed
}

fn scoped_operation() with IO {
    println("--- Scope Guard Pattern ---")
    println("")

    let guard = guard_enter(1)

    // Do some work...
    println("  Doing critical work...")
    println("  More work...")

    // Must exit the guard (linear consumption)
    guard_exit(guard)

    println("  Scope guard ensures cleanup happened!")
    println("")
}

fn measurement(val: f64, u: f64) -> Measurement {
    Measurement { value: val, std_uncertainty: u, source: 0 }
}

fn derived(val: f64, u: f64) -> Measurement {
    Measurement { value: val, std_uncertainty: u, source: 1 }
}

fn gum_add(a: Measurement, b: Measurement) -> Measurement with Mut, Panic, Div {
    let val = a.value + b.value
    let u = sqrt_f64(a.std_uncertainty * a.std_uncertainty
                   + b.std_uncertainty * b.std_uncertainty)
    derived(val, u)
}

fn gum_sub(a: Measurement, b: Measurement) -> Measurement with Mut, Panic, Div {
    let val = a.value - b.value
    let u = sqrt_f64(a.std_uncertainty * a.std_uncertainty
                   + b.std_uncertainty * b.std_uncertainty)
    derived(val, u)
}

fn gum_mul(a: Measurement, b: Measurement) -> Measurement with Mut, Panic, Div {
    let val = a.value * b.value
    let rel_a = if abs_f64(a.value) > 1e-15 { a.std_uncertainty / abs_f64(a.value) } else { 0.0 }
    let rel_b = if abs_f64(b.value) > 1e-15 { b.std_uncertainty / abs_f64(b.value) } else { 0.0 }
    let u = abs_f64(val) * sqrt_f64(rel_a * rel_a + rel_b * rel_b)
    derived(val, u)
}

fn gum_div(a: Measurement, b: Measurement) -> Measurement with Mut, Panic, Div {
    let val = a.value / b.value
    let rel_a = if abs_f64(a.value) > 1e-15 { a.std_uncertainty / abs_f64(a.value) } else { 0.0 }
    let rel_b = if abs_f64(b.value) > 1e-15 { b.std_uncertainty / abs_f64(b.value) } else { 0.0 }
    let u = abs_f64(val) * sqrt_f64(rel_a * rel_a + rel_b * rel_b)
    derived(val, u)
}

fn gum_scale(c: f64, x: Measurement) -> Measurement {
    derived(c * x.value, abs_f64(c) * x.std_uncertainty)
}

fn expanded_uncertainty(m: Measurement, k: f64) -> f64 {
    k * m.std_uncertainty
}

fn confidence_interval_lo(m: Measurement, k: f64) -> f64 {
    m.value - k * m.std_uncertainty
}

fn confidence_interval_hi(m: Measurement, k: f64) -> f64 {
    m.value + k * m.std_uncertainty
}

fn sensitivity_linear(x: Measurement, a: f64, b: f64) -> f64 {
    // For f(x) = a*x + b, df/dx = a
    abs_f64(a)
}

fn contribution_index(u_component: f64, u_total: f64) -> f64 with Panic, Div {
    if u_total > 1e-15 {
        (u_component * u_component) / (u_total * u_total) * 100.0
    } else {
        0.0
    }
}

fn ohms_law_example() with IO, Mut, Panic, Div {
    println("=== Ohm's Law: R = V / I ===")
    println("")

    // Voltage measurement: 12.34 V ± 0.02 V
    let voltage = measurement(12.34, 0.02)
    // Current measurement: 0.256 A ± 0.005 A
    let current = measurement(0.256, 0.005)

    // Resistance = V / I
    let resistance = gum_div(voltage, current)

    let k95 = 2.0  // coverage factor for ~95% confidence
    let u_expanded = expanded_uncertainty(resistance, k95)

    println("Voltage:    12.34 V +/- 0.02 V")
    println("Current:    0.256 A +/- 0.005 A")
    println("Resistance (R = V/I):")
    println(resistance.value)
    println("Standard uncertainty u(R):")
    println(resistance.std_uncertainty)
    println("Expanded uncertainty U(R), k=2 (95%):")
    println(u_expanded)
    println("95% confidence interval:")
    println(confidence_interval_lo(resistance, k95))
    println(confidence_interval_hi(resistance, k95))

    // Contribution analysis
    let rel_v = voltage.std_uncertainty / voltage.value
    let rel_i = current.std_uncertainty / current.value
    let u_from_v = abs_f64(resistance.value) * rel_v
    let u_from_i = abs_f64(resistance.value) * rel_i
    let ci_v = contribution_index(u_from_v, resistance.std_uncertainty)
    let ci_i = contribution_index(u_from_i, resistance.std_uncertainty)
    println("")
    println("Contribution from voltage (%):")
    println(ci_v)
    println("Contribution from current (%):")
    println(ci_i)
    println("")
}

fn power_example() with IO, Mut, Panic, Div {
    println("=== Power Dissipation: P = V^2 / R ===")
    println("")

    let voltage = measurement(5.00, 0.01)
    let resistance = measurement(100.0, 0.5)

    // P = V * V / R
    let v_squared = gum_mul(voltage, voltage)
    let power = gum_div(v_squared, resistance)

    let k95 = 2.0
    println("Voltage:    5.00 V +/- 0.01 V")
    println("Resistance: 100.0 ohm +/- 0.5 ohm")
    println("Power (P = V^2/R):")
    println(power.value)
    println("Standard uncertainty u(P):")
    println(power.std_uncertainty)
    println("Expanded uncertainty U(P), k=2:")
    println(expanded_uncertainty(power, k95))
    println("")
}

fn thermal_expansion_example() with IO, Mut, Panic, Div {
    println("=== Thermal Expansion: L = L0 * (1 + alpha * dT) ===")
    println("")

    // Steel bar: L0 = 1.0000 m ± 0.0001 m
    let l0 = measurement(1.0000, 0.0001)
    // Thermal expansion coefficient: 12e-6 /K ± 0.5e-6 /K
    let alpha = measurement(12.0e-6, 0.5e-6)
    // Temperature change: 80 K ± 2 K
    let dt = measurement(80.0, 2.0)

    // expansion = alpha * dT
    let expansion = gum_mul(alpha, dt)
    // one_plus_expansion = 1 + alpha*dT ≈ 1.00096
    let factor = gum_add(measurement(1.0, 0.0), expansion)
    // final length
    let length = gum_mul(l0, factor)

    let k95 = 2.0
    println("L0:    1.0000 m +/- 0.0001 m")
    println("alpha: 12e-6 /K +/- 0.5e-6 /K")
    println("dT:    80 K +/- 2 K")
    println("Final length L:")
    println(length.value)
    println("Standard uncertainty u(L):")
    println(length.std_uncertainty)
    println("Expanded uncertainty U(L), k=2:")
    println(expanded_uncertainty(length, k95))

    // Dominant uncertainty source
    let u_from_alpha = abs_f64(l0.value * dt.value) * alpha.std_uncertainty
    let u_from_dt = abs_f64(l0.value * alpha.value) * dt.std_uncertainty
    let u_from_l0 = abs_f64(1.0 + alpha.value * dt.value) * l0.std_uncertainty
    println("")
    println("Uncertainty contributions:")
    println("  From L0:")
    println(u_from_l0)
    println("  From alpha:")
    println(u_from_alpha)
    println("  From dT:")
    println(u_from_dt)
    println("")
}

fn nominal_params(p: UncertainParams) -> LotkaParams {
    LotkaParams {
        alpha: p.alpha.value,
        beta: p.beta.value,
        delta: p.delta.value,
        gamma: p.gamma.value
    }
}

fn perturbed_params(p: UncertainParams, sign: f64) -> LotkaParams {
    LotkaParams {
        alpha: p.alpha.value + sign * p.alpha.uncertainty,
        beta: p.beta.value + sign * p.beta.uncertainty,
        delta: p.delta.value + sign * p.delta.uncertainty,
        gamma: p.gamma.value + sign * p.gamma.uncertainty
    }
}

fn lotka_volterra(state: PopState, params: LotkaParams) -> PopState {
    let x = state.prey
    let y = state.predator
    PopState {
        prey:     params.alpha * x - params.beta * x * y,
        predator: params.delta * x * y - params.gamma * y
    }
}

fn rk4_step(state: PopState, params: LotkaParams, dt: f64) -> PopState with Div, Panic {
    // k1
    let k1 = lotka_volterra(state, params)

    // k2
    let s2 = PopState {
        prey:     state.prey     + 0.5 * dt * k1.prey,
        predator: state.predator + 0.5 * dt * k1.predator
    }
    let k2 = lotka_volterra(s2, params)

    // k3
    let s3 = PopState {
        prey:     state.prey     + 0.5 * dt * k2.prey,
        predator: state.predator + 0.5 * dt * k2.predator
    }
    let k3 = lotka_volterra(s3, params)

    // k4
    let s4 = PopState {
        prey:     state.prey     + dt * k3.prey,
        predator: state.predator + dt * k3.predator
    }
    let k4 = lotka_volterra(s4, params)

    // Combine
    PopState {
        prey:     state.prey     + dt / 6.0 * (k1.prey     + 2.0 * k2.prey     + 2.0 * k3.prey     + k4.prey),
        predator: state.predator + dt / 6.0 * (k1.predator + 2.0 * k2.predator + 2.0 * k3.predator + k4.predator)
    }
}

fn simulate(
    initial: PopState,
    params: UncertainParams,
    t_end: f64,
    dt: f64,
    report_interval: f64
) with IO, Mut, Div, Panic {
    let nom = nominal_params(params)
    let lo = perturbed_params(params, -1.0)
    let hi = perturbed_params(params, 1.0)

    var state_nom = initial
    var state_lo = initial
    var state_hi = initial

    var t = 0.0
    var next_report = 0.0
    var step = 0
    let max_steps = ((t_end / dt) as i32) + 1

    println("  t     | prey_nom  pred_nom | prey_lo   pred_lo  | prey_hi   pred_hi")
    println("  ------+--------------------+--------------------+-------------------")

    while step < max_steps && t <= t_end {
        if t >= next_report - dt * 0.5 {
            println(t)
            println(state_nom.prey)
            println(state_nom.predator)
            println(state_lo.prey)
            println(state_lo.predator)
            println(state_hi.prey)
            println(state_hi.predator)
            println("---")
            next_report = next_report + report_interval
        }

        state_nom = rk4_step(state_nom, nom, dt)
        state_lo = rk4_step(state_lo, lo, dt)
        state_hi = rk4_step(state_hi, hi, dt)

        // Clamp populations to non-negative
        if state_nom.prey < 0.0 { state_nom = PopState { prey: 0.0, predator: state_nom.predator } }
        if state_nom.predator < 0.0 { state_nom = PopState { prey: state_nom.prey, predator: 0.0 } }
        if state_lo.prey < 0.0 { state_lo = PopState { prey: 0.0, predator: state_lo.predator } }
        if state_lo.predator < 0.0 { state_lo = PopState { prey: state_lo.prey, predator: 0.0 } }
        if state_hi.prey < 0.0 { state_hi = PopState { prey: 0.0, predator: state_hi.predator } }
        if state_hi.predator < 0.0 { state_hi = PopState { prey: state_hi.prey, predator: 0.0 } }

        t = t + dt
        step = step + 1
    }
}

fn check_conservation(initial: PopState, final_state: PopState, params: LotkaParams) -> f64 with Mut, Div, Panic {
    // The Lotka-Volterra system conserves:
    //   H(x,y) = delta*x - gamma*ln(x) + beta*y - alpha*ln(y)
    // We check ln via series approximation

    let ln_xi = ln_approx(initial.prey)
    let ln_yi = ln_approx(initial.predator)
    let ln_xf = ln_approx(final_state.prey)
    let ln_yf = ln_approx(final_state.predator)

    let h_initial = params.delta * initial.prey - params.gamma * ln_xi
                  + params.beta * initial.predator - params.alpha * ln_yi
    let h_final = params.delta * final_state.prey - params.gamma * ln_xf
                + params.beta * final_state.predator - params.alpha * ln_yf

    abs_f64(h_final - h_initial)
}

fn ln_approx(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    // ln(x) via Newton iteration on e^y = x
    var y = 0.0
    if x > 1.0 { y = x - 1.0 }
    if y > 5.0 { y = 5.0 }

    var iter = 0
    while iter < 40 {
        let ey = exp_approx(y)
        y = y - (ey - x) / ey
        iter = iter + 1
    }
    y
}

fn exp_approx(x: f64) -> f64 with Mut, Div, Panic {
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 30 {
        term = term * x / (n as f64)
        sum = sum + term
        n = n + 1
    }
    sum
}

fn floor_f64(x: f64) -> f64 with Panic {
    let i = x as i32
    let f = i as f64
    if x < 0.0 && f != x { f - 1.0 } else { f }
}

fn sin_f64(x: f64) -> f64 with Mut, Div, Panic {
    let pi = 3.141592653589793
    let two_pi = 6.283185307179586
    var t = x - floor_f64(x / two_pi) * two_pi
    if t > pi { t = t - two_pi }
    if t < 0.0 - pi { t = t + two_pi }
    var sum = t
    var term = t
    var n = 1
    while n <= 20 {
        term = 0.0 - term * t * t / (((2 * n) as f64) * ((2 * n + 1) as f64))
        sum = sum + term
        n = n + 1
    }
    sum
}

fn cos_f64(x: f64) -> f64 with Mut, Div, Panic {
    sin_f64(x + 1.5707963267948966)
}

fn noise(seed: i32) -> f64 with Div, Panic {
    let h = ((seed * 2654435761) % 1000000) as f64
    (h / 1000000.0 - 0.5) * 0.3  // noise amplitude ±0.15
}

fn c_add(a: Complex, b: Complex) -> Complex {
    Complex { re: a.re + b.re, im: a.im + b.im }
}

fn c_mul(a: Complex, b: Complex) -> Complex {
    Complex {
        re: a.re * b.re - a.im * b.im,
        im: a.re * b.im + a.im * b.re
    }
}

fn c_magnitude(a: Complex) -> f64 with Mut, Div, Panic {
    sqrt_f64(a.re * a.re + a.im * a.im)
}

fn dft(signal: [f64], n: i32) -> [Complex] with Mut, Div, Panic {
    let pi2 = 6.283185307179586
    // Pre-allocate output
    let zero = Complex { re: 0.0, im: 0.0 }
    var spectrum = [zero, zero, zero, zero, zero, zero, zero, zero,
                    zero, zero, zero, zero, zero, zero, zero, zero,
                    zero, zero, zero, zero, zero, zero, zero, zero,
                    zero, zero, zero, zero, zero, zero, zero, zero]

    var k = 0
    while k < n {
        var sum_re = 0.0
        var sum_im = 0.0
        var j = 0
        while j < n {
            let angle = pi2 * (k as f64) * (j as f64) / (n as f64)
            sum_re = sum_re + signal[j] * cos_f64(angle)
            sum_im = sum_im - signal[j] * sin_f64(angle)
            j = j + 1
        }
        spectrum[k] = Complex { re: sum_re / (n as f64), im: sum_im / (n as f64) }
        k = k + 1
    }
    spectrum
}

fn find_peaks(
    spectrum: [Complex],
    n: i32,
    sample_rate: f64,
    noise_floor: f64
) -> [SpectralPeak] with Mut, Div, Panic {
    let sentinel = SpectralPeak {
        bin: -1, frequency: 0.0, magnitude: 0.0, snr: 0.0, confidence: 0.0
    }
    var peaks = [sentinel, sentinel, sentinel, sentinel, sentinel]
    var peak_count = 0
    let half_n = n / 2

    var k = 1  // skip DC
    while k < half_n && peak_count < 5 {
        let mag = c_magnitude(spectrum[k])
        let prev_mag = if k > 0 { c_magnitude(spectrum[k - 1]) } else { 0.0 }
        let next_mag = if k < half_n - 1 { c_magnitude(spectrum[k + 1]) } else { 0.0 }

        // Peak: local maximum above noise floor
        if mag > prev_mag && mag > next_mag && mag > noise_floor * 2.0 {
            let freq = (k as f64) * sample_rate / (n as f64)
            let snr = mag / max_f64(noise_floor, 0.001)

            // Epistemic confidence from SNR
            // High SNR → high confidence, low SNR → low confidence
            let conf = if snr > 10.0 { 0.95 }
                       else if snr > 5.0 { 0.80 }
                       else if snr > 3.0 { 0.60 }
                       else if snr > 2.0 { 0.40 }
                       else { 0.20 }

            peaks[peak_count] = SpectralPeak {
                bin: k,
                frequency: freq,
                magnitude: mag,
                snr: snr,
                confidence: conf
            }
            peak_count = peak_count + 1
        }
        k = k + 1
    }
    peaks
}

fn dim_eq(a: Dim, b: Dim) -> bool {
    a.mass == b.mass && a.length == b.length && a.time == b.time
}

fn q_add(a: Quantity, b: Quantity) -> Quantity with IO, Div, Panic {
    if !dim_eq(a.dim, b.dim) {
        println("DIMENSION ERROR: cannot add incompatible units!")
        return Quantity { value: 0.0 / 0.0, dim: dimensionless() }
    }
    Quantity { value: a.value + b.value, dim: a.dim }
}

fn q_sub(a: Quantity, b: Quantity) -> Quantity with IO, Div, Panic {
    if !dim_eq(a.dim, b.dim) {
        println("DIMENSION ERROR: cannot subtract incompatible units!")
        return Quantity { value: 0.0 / 0.0, dim: dimensionless() }
    }
    Quantity { value: a.value - b.value, dim: a.dim }
}

fn q_mul(a: Quantity, b: Quantity) -> Quantity {
    Quantity {
        value: a.value * b.value,
        dim: Dim {
            mass: a.dim.mass + b.dim.mass,
            length: a.dim.length + b.dim.length,
            time: a.dim.time + b.dim.time
        }
    }
}

fn q_div(a: Quantity, b: Quantity) -> Quantity with Div, Panic {
    Quantity {
        value: a.value / b.value,
        dim: Dim {
            mass: a.dim.mass - b.dim.mass,
            length: a.dim.length - b.dim.length,
            time: a.dim.time - b.dim.time
        }
    }
}

fn q_scale(c: f64, q: Quantity) -> Quantity {
    Quantity { value: c * q.value, dim: q.dim }
}

fn dim_name(d: Dim) -> i32 {
    // Return a code for the dimension name
    if dim_eq(d, dimensionless()) { return 0 }
    if dim_eq(d, dim_mass()) { return 1 }
    if dim_eq(d, dim_length()) { return 2 }
    if dim_eq(d, dim_time()) { return 3 }
    if dim_eq(d, dim_velocity()) { return 4 }
    if dim_eq(d, dim_acceleration()) { return 5 }
    if dim_eq(d, dim_force()) { return 6 }
    if dim_eq(d, dim_energy()) { return 7 }
    if dim_eq(d, dim_power()) { return 8 }
    return 99
}

fn simulate_projectile(
    v0: f64,
    angle_deg: f64,
    dt_val: f64,
    steps: i32
) -> ProjectileState with IO, Mut, Div, Panic {
    let pi = 3.141592653589793
    let angle_rad = angle_deg * pi / 180.0

    // sin/cos via Taylor series
    var sin_a = angle_rad
    var cos_a = 1.0
    var term_s = angle_rad
    var term_c = 1.0
    var n = 1
    while n <= 15 {
        term_s = 0.0 - term_s * angle_rad * angle_rad / (((2 * n) as f64) * ((2 * n + 1) as f64))
        sin_a = sin_a + term_s
        term_c = 0.0 - term_c * angle_rad * angle_rad / (((2 * n - 1) as f64) * ((2 * n) as f64))
        cos_a = cos_a + term_c
        n = n + 1
    }

    let g = mps2(9.81)
    var state = ProjectileState {
        x:  meters(0.0),
        y:  meters(0.0),
        vx: mps(v0 * cos_a),
        vy: mps(v0 * sin_a),
        t:  seconds(0.0)
    }

    let dt = seconds(dt_val)

    var step = 0
    while step < steps {
        // v_y = v_y - g * dt  (dimension check: m/s - m/s^2 * s = m/s)
        let dvy = q_mul(g, dt)                // m/s^2 * s = m/s
        state.vy = q_sub(state.vy, dvy)       // m/s - m/s = m/s

        // x = x + vx * dt  (dimension check: m + m/s * s = m)
        let dx = q_mul(state.vx, dt)          // m/s * s = m
        state.x = q_add(state.x, dx)          // m + m = m

        // y = y + vy * dt
        let dy = q_mul(state.vy, dt)
        state.y = q_add(state.y, dy)

        // t = t + dt
        state.t = q_add(state.t, dt)

        // Stop when projectile hits ground
        if state.y.value < 0.0 && step > 0 {
            break
        }

        step = step + 1
    }

    state
}

