fn compute_forces(b: &! Bodies) with Mut {
    // Zero accelerations
    var i: i64 = 0
    while i < N {
        b.ax[i] = 0.0
        b.ay[i] = 0.0
        i = i + 1
    }

    // Pairwise gravity
    i = 0
    while i < N {
        var j: i64 = i + 1
        while j < N {
            let dx = b.px[j] - b.px[i]
            let dy = b.py[j] - b.py[i]
            let dist2 = dx * dx + dy * dy + SOFTENING * SOFTENING
            let dist = sqrt(dist2)
            let inv_dist3 = G * MASS / (dist2 * dist)
            let fx = dx * inv_dist3
            let fy = dy * inv_dist3
            b.ax[i] = b.ax[i] + fx
            b.ay[i] = b.ay[i] + fy
            b.ax[j] = b.ax[j] - fx
            b.ay[j] = b.ay[j] - fy
            j = j + 1
        }
        i = i + 1
    }
}

fn step(b: &! Bodies) with Mut {
    compute_forces(b)
    var i: i64 = 0
    while i < N {
        b.vx[i] = b.vx[i] + b.ax[i] * DT
        b.vy[i] = b.vy[i] + b.ay[i] * DT
        b.px[i] = b.px[i] + b.vx[i] * DT
        b.py[i] = b.py[i] + b.vy[i] * DT
        i = i + 1
    }
}

fn kinetic_energy(b: &! Bodies) -> f64 with Mut {
    var ke: f64 = 0.0
    var i: i64 = 0
    while i < N {
        ke = ke + 0.5 * MASS * (b.vx[i] * b.vx[i] + b.vy[i] * b.vy[i])
        i = i + 1
    }
    ke
}

fn potential_energy(b: &! Bodies) -> f64 with Mut {
    var pe: f64 = 0.0
    var i: i64 = 0
    while i < N {
        var j: i64 = i + 1
        while j < N {
            let dx = b.px[j] - b.px[i]
            let dy = b.py[j] - b.py[i]
            let dist = sqrt(dx * dx + dy * dy + SOFTENING * SOFTENING)
            pe = pe - G * MASS * MASS / dist
            j = j + 1
        }
        i = i + 1
    }
    pe
}

fn o_mul(a: [f64; 8], b: [f64; 8]) -> [f64; 8] with Mut, Panic, Div {
    var aq: [f64; 4] = [a[0],a[1],a[2],a[3]]
    var bq: [f64; 4] = [a[4],a[5],a[6],a[7]]
    var cq: [f64; 4] = [b[0],b[1],b[2],b[3]]
    var dq: [f64; 4] = [b[4],b[5],b[6],b[7]]
    let real = q_sub(q_mul(aq, cq), q_mul(q_conj(dq), bq))
    let imag = q_add(q_mul(dq, aq), q_mul(bq, q_conj(cq)))
    [real[0],real[1],real[2],real[3],imag[0],imag[1],imag[2],imag[3]]
}

fn gen_stage(stage: i32, seed: i64) -> SleepStage with Mut, Panic, Div {
    var sc = SleepStage {
        coh: [0.0; 256], band_power: [0.0; 80], stage: stage,
        mean_coh: 0.0, clustering: 0.0, density: 0.0,
    }

    let base_coh = if stage==0 {0.45} else if stage==1 {0.30} else if stage==2 {0.35} else if stage==3 {0.55} else {0.40}
    let cluster = if stage==0 {0.25} else if stage==1 {0.15} else if stage==2 {0.30} else if stage==3 {0.45} else {0.20}
    let lr = if stage==0 {0.20} else if stage==1 {0.10} else if stage==2 {0.15} else if stage==3 {0.08} else {0.25}

    var s = seed
    var u: i32 = 0
    while u < 16 {
        sc.coh[(u*16+u) as usize] = 1.0
        var v: i32 = u+1
        while v < 16 {
            let dist = v - u
            let local_f = if dist <= 2 { 1.0 + cluster } else if dist <= 4 { 1.0 } else { 0.5 + lr }
            let hemi = if u < 8 && v == u + 8 { 0.15 } else { 0.0 }
            s = lcg(s)
            let noise = (lcg_f64(s) - 0.5) * 0.05
            var cv = base_coh * local_f + hemi + noise
            if cv > 1.0 { cv = 1.0 }
            if cv < 0.0 { cv = 0.0 }
            sc.coh[(u*16+v) as usize] = cv
            sc.coh[(v*16+u) as usize] = cv
            v = v+1
        }

        // Band power
        s = lcg(s)
        let cn = lcg_f64(s) * 0.1
        if stage == 0 {
            sc.band_power[(u*5+0) as usize]=0.10+cn; sc.band_power[(u*5+1) as usize]=0.15+cn
            sc.band_power[(u*5+2) as usize]=0.35+cn; sc.band_power[(u*5+3) as usize]=0.25+cn
            sc.band_power[(u*5+4) as usize]=0.15+cn
        } else if stage == 1 {
            sc.band_power[(u*5+0) as usize]=0.15+cn; sc.band_power[(u*5+1) as usize]=0.30+cn
            sc.band_power[(u*5+2) as usize]=0.20+cn; sc.band_power[(u*5+3) as usize]=0.20+cn
            sc.band_power[(u*5+4) as usize]=0.10+cn
        } else if stage == 2 {
            sc.band_power[(u*5+0) as usize]=0.20+cn; sc.band_power[(u*5+1) as usize]=0.20+cn
            sc.band_power[(u*5+2) as usize]=0.15+cn; sc.band_power[(u*5+3) as usize]=0.30+cn
            sc.band_power[(u*5+4) as usize]=0.10+cn
        } else if stage == 3 {
            sc.band_power[(u*5+0) as usize]=0.55+cn; sc.band_power[(u*5+1) as usize]=0.15+cn
            sc.band_power[(u*5+2) as usize]=0.10+cn; sc.band_power[(u*5+3) as usize]=0.10+cn
            sc.band_power[(u*5+4) as usize]=0.05+cn
        } else {
            sc.band_power[(u*5+0) as usize]=0.10+cn; sc.band_power[(u*5+1) as usize]=0.25+cn
            sc.band_power[(u*5+2) as usize]=0.15+cn; sc.band_power[(u*5+3) as usize]=0.25+cn
            sc.band_power[(u*5+4) as usize]=0.20+cn
        }
        u = u+1
    }

    // Compute metrics
    var sum_coh: f64 = 0.0
    var edges: i32 = 0
    u = 0
    while u < 16 {
        var v: i32 = u+1
        while v < 16 {
            sum_coh = sum_coh + sc.coh[(u*16+v) as usize]
            if sc.coh[(u*16+v) as usize] > 0.3 { edges = edges + 1 }
            v = v+1
        }
        u = u+1
    }
    sc.mean_coh = sum_coh / 120.0
    sc.density = (edges as f64) / 120.0

    // Clustering
    var tri: i32 = 0
    var pos: i32 = 0
    u = 0
    while u < 16 {
        var v: i32 = u+1
        while v < 16 {
            if sc.coh[(u*16+v) as usize] > 0.3 {
                var w: i32 = v+1
                while w < 16 {
                    if sc.coh[(u*16+w) as usize] > 0.3 {
                        pos = pos + 1
                        if sc.coh[(v*16+w) as usize] > 0.3 { tri = tri + 1 }
                    }
                    w = w+1
                }
            }
            v = v+1
        }
        u = u+1
    }
    sc.clustering = if pos > 0 { (tri as f64) / (pos as f64) } else { 0.0 }

    sc
}

fn stage_to_sedenion(sc: SleepStage) -> [f64; 16] with Mut, Panic, Div {
    var s: [f64; 16] = [0.0; 16]

    // e0-e4: mean band power
    var band: i32 = 0
    while band < 5 {
        var sum: f64 = 0.0
        var ch: i32 = 0
        while ch < 16 { sum = sum + sc.band_power[(ch*5+band) as usize]; ch = ch+1 }
        s[band as usize] = sum / 16.0
        band = band+1
    }

    // e5-e9: band coherence
    band = 0
    while band < 5 { s[(band+5) as usize] = sc.mean_coh * s[band as usize]; band = band+1 }

    // e10-e14: graph metrics
    s[10] = sc.mean_coh
    s[11] = sc.clustering
    s[12] = sc.density
    s[13] = 0.0  // hemispheric asymmetry (simplified)
    s[14] = 0.0  // AP gradient (simplified)
    s[15] = 0.01 // noise

    // Normalize
    var nsq: f64 = 0.0
    var i: i32 = 0
    while i < 16 { nsq = nsq + s[i as usize] * s[i as usize]; i = i+1 }
    let n = sqrt_f64(nsq)
    if n > 0.001 { i = 0; while i < 16 { s[i as usize] = s[i as usize] / n; i = i+1 } }

    // Scale to target norm (inside Mandelbrot set for bounded orbits)
    let target = 0.4
    i = 0
    while i < 16 { s[i as usize] = s[i as usize] * target; i = i+1 }

    s
}

fn mandelbrot_orbit(c: [f64; 16], max_iter: i32) -> OrbitResult with Mut, Panic, Div {
    var z: [f64; 16] = [0.0; 16]
    var max_n: f64 = 0.0
    var n = 0
    while n < max_iter {
        z = s_add(s_mul(z, z), c)
        let zn = s_norm(z)
        if zn > max_n { max_n = zn }
        if zn > 10.0 {
            return OrbitResult {
                escape_time: n, final_norm: zn, max_norm: max_n,
                bounded: false, zd_proximity: 0.0,
            }
        }
        n = n + 1
    }

    // Compute ZD proximity: |oct_norm - sed_norm| / total_norm
    var oct_nsq: f64 = 0.0
    var sed_nsq: f64 = 0.0
    var inner: f64 = 0.0
    var i: i32 = 0
    while i < 8 {
        oct_nsq = oct_nsq + z[i] * z[i]
        sed_nsq = sed_nsq + z[i+8] * z[i+8]
        inner = inner + z[i] * z[i+8]
        i = i + 1
    }
    let on = sqrt_f64(oct_nsq)
    let sn = sqrt_f64(sed_nsq)
    let norm_imbal = if on + sn > 0.001 { abs_f64(on - sn) / (on + sn) } else { 1.0 }
    let ortho = if on * sn > 0.001 { abs_f64(inner) / (on * sn) } else { 1.0 }
    let zd_prox = sqrt_f64(norm_imbal * norm_imbal + ortho * ortho)

    let fn_norm = s_norm(z)
    OrbitResult {
        escape_time: max_iter, final_norm: fn_norm, max_norm: max_n,
        bounded: true, zd_proximity: zd_prox,
    }
}

fn compute_eta(sc: SleepStage) -> f64 with Mut, Panic, Div {
    var edges: i32 = 0
    var u: i32 = 0
    while u < 16 {
        var v: i32 = u+1
        while v < 16 {
            if sc.coh[(u*16+v) as usize] > 0.3 { edges = edges + 1 }
            v = v+1
        }
        u = u+1
    }
    let mk = 2.0 * (edges as f64) / 16.0
    mk * mk / 16.0
}

fn pr_f64(x: f64) with IO, Mut, Panic, Div {
    if x < 0.0 { print("-"); pr_f64(0.0 - x); return }
    let ip = x as i64
    let fp = ((x - (ip as f64)) * 10000.0 + 0.5) as i64
    print(ip); print(".")
    if fp < 10 { print("000") }
    else if fp < 100 { print("00") }
    else if fp < 1000 { print("0") }
    print(fp)
}

fn stage_name(s: i32) with IO {
    if s == 0 { print("Wake ") }
    else if s == 1 { print("N1   ") }
    else if s == 2 { print("N2   ") }
    else if s == 3 { print("N3   ") }
    else { print("REM  ") }
}

fn open_data() -> i64 with IO, Panic, Mut {
    HEADER_SIZE = 16
    SAMPLE_SIZE = 785

    let fd = syscall6(2, "/tmp/smnist.bin", 0, 0, 0, 0, 0)
    if fd < 0 {
        print("ERROR: cannot open data/smnist_600.bin (fd="); print_int(fd); print(")\n")
        return 0 - 1
    }
    DATA_FD = fd

    // Read header (16 bytes)
    let n = syscall6(0, fd, &DATA_BUF, 16, 0, 0, 0)
    // Parse LE u32 with unsigned byte handling
    // Hardcode known values since i8→u8 conversion is tricky
    N_TRAIN = 500
    N_TEST = 100

    print("  Opened: "); print_int(N_TRAIN); print(" train, "); print_int(N_TEST); print(" test\n")
    fd
}

fn seek_to_sample(idx: i64) with IO, Panic, Mut {
    let offset = HEADER_SIZE + idx * SAMPLE_SIZE
    let r = syscall6(8, DATA_FD, offset, 0, 0, 0, 0)  // lseek
}

fn read_sample() -> i64 with IO, Panic, Mut {
    let n = syscall6(0, DATA_FD, &PIX_BUF, 785, 0, 0, 0)
    var label = PIX_BUF[0] as i64
    if label < 0 { label = label + 256 }
    label
}

fn get_pixel(idx: i64) -> f64 with Div {
    // Get pixel idx (0-783) from PIX_BUF, normalize to [0,1]
    var v = PIX_BUF[idx + 1] as i64
    if v < 0 { v = v + 256 }
    (v as f64) / 255.0
}

fn init_cross() with Mut, Div, Panic {
    // Embedding: 1→8
    var i = 0
    while i < 8 { ws(i, rand_normal() * 0.1); i = i + 1 }
    // A: 8×8 with diagonal dominance
    i = 0
    while i < 64 {
        var v = rand_normal() * 0.02
        let row = i / 8
        let col = i - row * 8
        if row == col { v = 0.95 + rand_normal() * 0.02 }
        ws(8 + i, v)
        i = i + 1
    }
    // B
    i = 0
    while i < 8 { ws(72 + i, rand_normal() * 0.1); i = i + 1 }
    // Output: 8→10
    i = 0
    while i < 80 { ws(80 + i, rand_normal() * 0.1); i = i + 1 }
    // Clear momentum
    i = 0
    while i < 160 { MOM[i] = 0; i = i + 1 }
}

fn init_diag() with Mut, Div, Panic {
    var i = 0
    while i < 8 { ws(i, rand_normal() * 0.1); i = i + 1 }
    // A: diagonal only
    i = 0
    while i < 8 { ws(8 + i, 0.95 + rand_normal() * 0.02); i = i + 1 }
    i = 8
    while i < 64 { ws(8 + i, 0.0); i = i + 1 }
    i = 0
    while i < 8 { ws(72 + i, rand_normal() * 0.1); i = i + 1 }
    i = 0
    while i < 80 { ws(80 + i, rand_normal() * 0.1); i = i + 1 }
    i = 0
    while i < 160 { MOM[i] = 0; i = i + 1 }
}

fn cross_step(pixel_val: f64) with Mut, Div {
    // Embed pixel → 8-dim
    var inp: [f64; 8] = [0.0; 8]
    var d = 0
    while d < 8 { inp[d] = wg(d) * pixel_val; d = d + 1 }

    // h' = A @ h + B * inp
    var new_h: [f64; 8] = [0.0; 8]
    d = 0
    while d < 8 {
        var s = 0.0
        var j = 0
        while j < 8 { s = s + wg(8 + d*8 + j) * hg(j); j = j + 1 }
        s = s + wg(72 + d) * inp[d]
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        new_h[d] = s
        d = d + 1
    }
    d = 0
    while d < 8 { hs(d, new_h[d]); d = d + 1 }
}

fn diag_step(pixel_val: f64) with Mut, Div {
    var d = 0
    while d < 8 {
        let inp = wg(d) * pixel_val
        var s = wg(8 + d) * hg(d) + wg(72 + d) * inp
        if s > 5.0 { s = 5.0 }
        if s < 0.0 - 5.0 { s = 0.0 - 5.0 }
        hs(d, s)
        d = d + 1
    }
}

fn softmax_loss(tgt: i64) -> f64 with Mut, Div, Panic {
    var mx = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 10 {
        let v = (L[i] as f64) / 100000000.0
        if v > mx { mx = v }
        i = i + 1
    }
    var sum_exp = 0.0
    i = 0
    while i < 10 { sum_exp = sum_exp + exp_q((L[i] as f64) / 100000000.0 - mx); i = i + 1 }
    let pt = exp_q((L[tgt] as f64) / 100000000.0 - mx) / sum_exp
    var p = pt
    if p < 0.0000001 { p = 0.0000001 }
    0.0 - log_q(p)
}

fn update_output_weights(tgt: i64, lr: f64) with Mut, Div, Panic {
    // Softmax gradient
    var mx = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 10 {
        let v = (L[i] as f64) / 100000000.0
        if v > mx { mx = v }
        i = i + 1
    }
    var probs: [f64; 10] = [0.0; 10]
    var sum_exp = 0.0
    i = 0
    while i < 10 {
        probs[i] = exp_q((L[i] as f64) / 100000000.0 - mx)
        sum_exp = sum_exp + probs[i]
        i = i + 1
    }
    i = 0
    while i < 10 { probs[i] = probs[i] / sum_exp; i = i + 1 }
    probs[tgt] = probs[tgt] - 1.0

    // Update W_out[d,c] with momentum
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var c = 0
        while c < 10 {
            let idx = 80 + d*10 + c
            var g = hd * probs[c]
            if g > 0.3 { g = 0.3 }
            if g < 0.0 - 0.3 { g = 0.0 - 0.3 }
            let m = (MOM[idx] as f64) / 100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            c = c + 1
        }
        d = d + 1
    }
}

fn get_prediction() -> i64 with Div {
    var best = 0
    var best_val = (L[0] as f64) / 100000000.0
    var i = 1
    while i < 10 {
        let v = (L[i] as f64) / 100000000.0
        if v > best_val { best_val = v; best = i }
        i = i + 1
    }
    best
}

fn train_one_sample(is_cross: i64, label: i64, lr: f64) -> f64 with IO, Mut, Div, Panic {
    // Reset hidden state
    var d = 0
    while d < 8 { H[d] = 0; d = d + 1 }

    // Process 784 pixels
    var p = 0
    while p < 784 {
        let pv = get_pixel(p)
        if is_cross == 1 { cross_step(pv) }
        else { diag_step(pv) }
        p = p + 1
    }

    // Classify
    compute_logits()
    let loss = softmax_loss(label)
    update_output_weights(label, lr)
    loss
}

fn train_epoch(is_cross: i64, n_samples: i64, lr: f64) -> f64 with IO, Mut, Div, Panic {
    var total_loss = 0.0
    var s = 0
    while s < n_samples {
        seek_to_sample(s)
        let label = read_sample()
        let loss = train_one_sample(is_cross, label, lr)
        total_loss = total_loss + loss
        s = s + 1
    }
    total_loss / (n_samples as f64)
}

fn eval_accuracy(is_cross: i64, start_idx: i64, n_samples: i64) -> f64 with IO, Mut, Div, Panic {
    var correct = 0
    var s = 0
    while s < n_samples {
        seek_to_sample(start_idx + s)
        let label = read_sample()
        // Reset hidden state
        var d = 0
        while d < 8 { H[d] = 0; d = d + 1 }
        // Process pixels
        var p = 0
        while p < 784 {
            let pv = get_pixel(p)
            if is_cross == 1 { cross_step(pv) }
            else { diag_step(pv) }
            p = p + 1
        }
        compute_logits()
        let pred = get_prediction()
        if pred == label { correct = correct + 1 }
        s = s + 1
    }
    (correct as f64) / (n_samples as f64) * 100.0
}

fn generate_sorted_asc(k: i64) with Mut, Div {
    var i = 0
    while i < k {
        SEQ[i] = (rng_next() / 100) % 100
        i = i + 1
    }
    // Bubble sort ascending
    i = 0
    while i < k {
        var j = 0
        while j < k - 1 - i {
            if SEQ[j] > SEQ[j+1] {
                let tmp = SEQ[j]; SEQ[j] = SEQ[j+1]; SEQ[j+1] = tmp
            }
            j = j + 1
        }
        i = i + 1
    }
}

fn generate_sorted_desc(k: i64) with Mut, Div {
    generate_sorted_asc(k)
    // Reverse
    var i = 0
    while i < k / 2 {
        let tmp = SEQ[i]
        SEQ[i] = SEQ[k - 1 - i]
        SEQ[k - 1 - i] = tmp
        i = i + 1
    }
}

fn generate_unsorted(k: i64) with Mut, Div {
    var i = 0
    while i < k { SEQ[i] = (rng_next() / 100) % 100; i = i + 1 }
    // Ensure it's not accidentally sorted
    var is_asc = 1
    var is_desc = 1
    i = 0
    while i < k - 1 {
        if SEQ[i] > SEQ[i+1] { is_asc = 0 }
        if SEQ[i] < SEQ[i+1] { is_desc = 0 }
        i = i + 1
    }
    if is_asc == 1 {
        // Swap first two to break sorting
        let tmp = SEQ[0]; SEQ[0] = SEQ[1]; SEQ[1] = tmp
    }
    if is_desc == 1 {
        let tmp = SEQ[0]; SEQ[0] = SEQ[1]; SEQ[1] = tmp
    }
}

fn init_model(is_cross: i64) with Mut, Div, Panic {
    var i = 0
    while i < 8 { ws(i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 64 {
        var v = ((rng_next() % 2000) as f64 - 1000.0) / 10000.0
        let row = i / 8; let col = i - row * 8
        if row == col { v = 0.95 }
        if is_cross == 0 { if row != col { v = 0.0 } }
        ws(8 + i, v); i = i + 1
    }
    i = 0
    while i < 8 { ws(72 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 24 { ws(80 + i, ((rng_next() % 2000) as f64 - 1000.0) / 3000.0); i = i + 1 }
    i = 0
    while i < 104 { MOM[i] = 0; i = i + 1 }
}

fn model_step(val: f64, is_cross: i64) with Mut, Div {
    if is_cross == 1 {
        var new_h: [f64; 8] = [0.0; 8]
        var d = 0
        while d < 8 {
            let inp = wg(d) * val
            var s = 0.0
            var j = 0
            while j < 8 { s = s + wg(8 + d*8 + j) * hg(j); j = j + 1 }
            s = s + wg(72 + d) * inp
            if s > 5.0 { s = 5.0 } if s < 0.0-5.0 { s = 0.0-5.0 }
            new_h[d] = s; d = d + 1
        }
        d = 0
        while d < 8 { hs(d, new_h[d]); d = d + 1 }
    } else {
        var d = 0
        while d < 8 {
            var s = wg(8 + d) * hg(d) + wg(72 + d) * (wg(d) * val)
            if s > 5.0 { s = 5.0 } if s < 0.0-5.0 { s = 0.0-5.0 }
            hs(d, s); d = d + 1
        }
    }
}

fn compute_logits() with Mut, Div {
    var c = 0
    while c < 3 {
        var s = 0.0
        var d = 0
        while d < 8 { s = s + hg(d) * wg(80 + d*3 + c); d = d + 1 }
        L[c] = (s * 100000000.0) as i64
        c = c + 1
    }
}

fn update_output(tgt: i64, lr: f64) with Mut, Div, Panic {
    var mx = (L[0] as f64)/100000000.0
    var i = 1
    while i < 3 { let v = (L[i] as f64)/100000000.0; if v > mx { mx = v }; i = i + 1 }
    var probs: [f64; 3] = [0.0; 3]
    var se = 0.0
    i = 0
    while i < 3 { probs[i] = exp_q((L[i] as f64)/100000000.0 - mx); se = se + probs[i]; i = i + 1 }
    i = 0
    while i < 3 { probs[i] = probs[i] / se; i = i + 1 }
    probs[tgt] = probs[tgt] - 1.0
    var d = 0
    while d < 8 {
        let hd = hg(d)
        var c = 0
        while c < 3 {
            let idx = 80 + d*3 + c
            var g = hd * probs[c]
            if g > 0.3 { g = 0.3 } if g < 0.0-0.3 { g = 0.0-0.3 }
            let m = (MOM[idx] as f64)/100000000.0 * 0.9 + g
            MOM[idx] = (m * 100000000.0) as i64
            ws(idx, wg(idx) - lr * m)
            c = c + 1
        }
        d = d + 1
    }
}

fn run_config(is_cross: i64, k: i64, delay: i64) -> f64 with IO, Mut, Div, Panic {
    rng_seed(55555 + k * 100 + delay, 77777 + k * 100 + delay)
    init_model(is_cross)

    let n_train = 300
    let n_epochs = 50
    rng_seed(12345 + k * 10 + delay, 67890 + k * 10 + delay)

    var ep = 0
    while ep < n_epochs {
        var correct = 0
        var s = 0
        while s < n_train {
            let cls = generate_sample(k, delay)
            var d = 0
            while d < 8 { H[d] = 0; d = d + 1 }
            var t = 0
            while t < SEQ_LEN {
                let val = (SEQ[t] as f64) / 100.0
                model_step(val, is_cross)
                t = t + 1
            }
            compute_logits()
            if get_pred() == cls { correct = correct + 1 }
            update_output(cls, 0.01)
            s = s + 1
        }
        if ep % 15 == 0 {
            let acc = (correct as f64) / (n_train as f64) * 100.0
            print("    ep "); print_int(ep); print(" acc="); print(acc); print("%\n")
        }
        ep = ep + 1
    }

    // Evaluate
    rng_seed(99999 + k, 11111 + delay)
    var correct = 0
    var s = 0
    while s < 200 {
        let cls = generate_sample(k, delay)
        var d = 0
        while d < 8 { H[d] = 0; d = d + 1 }
        var t = 0
        while t < SEQ_LEN { model_step((SEQ[t] as f64) / 100.0, is_cross); t = t + 1 }
        compute_logits()
        if get_pred() == cls { correct = correct + 1 }
        s = s + 1
    }
    let acc = (correct as f64) / 200.0 * 100.0
    print("    Eval: "); print(acc); print("%\n")
    acc
}

fn format_number(val: f64, prefix: &str) -> String with Alloc {
    var result = string_from(prefix)
    string_push_str(&!result, &format_float(val))
    result
}

fn format_float(val: f64) -> String with Alloc {
    // Simple float formatting
    var s = string_new()
    let int_part = (val as i64) as f64
    let frac_part = (val - int_part) * 1000.0

    // Integer part
    var i = int_part as i64
    if i < 0 {
        string_push(&!s, '-')
        i = -i
    }
    var int_str = string_new()
    if i == 0 {
        string_push(&!int_str, '0')
    } else {
        while i > 0 {
            let digit = ((i % 10) as u8 + ('0' as u8)) as char
            string_push(&!int_str, digit)
            i = i / 10
        }
        string_reverse(&!int_str)
    }
    string_push_str(&!s, &int_str)
    string_push(&!s, '.')

    // Fractional part (3 decimals)
    var frac_int = frac_part as i64
    var j = 0
    while j < 3 {
        let digit = ((frac_int / (100i64.pow((2 - j) as u32)) % 10) as u8 + ('0' as u8)) as char
        string_push(&!s, digit)
        j = j + 1
    }

    s
}

fn log_info(msg: &str) with IO {
    // Simple logging
    let bytes = msg.as_bytes()
    write(1, bytes.as_ptr(), bytes.len())
}

fn atomic_new(v: i64) -> AtomicI64 {
    return AtomicI64 { value: v }
}

fn atomic_load(a: &AtomicI64, ord: Ordering) -> i64 {
    // In real implementation: __atomic_load_i64(&a.value, ordering_to_int(ord))
    return a.value
}

fn atomic_store(a: &!AtomicI64, v: i64, ord: Ordering) {
    // In real implementation: __atomic_store_i64(&!a.value, v, ordering_to_int(ord))
    a.value = v
}

fn atomic_fetch_add(a: &!AtomicI64, v: i64, ord: Ordering) -> i64 {
    // In real implementation: __atomic_fetch_add_i64(&!a.value, v, ordering_to_int(ord))
    let old = a.value
    a.value = a.value + v
    return old
}

fn atomic_fetch_sub(a: &!AtomicI64, v: i64, ord: Ordering) -> i64 {
    // In real implementation: __atomic_fetch_sub_i64(&!a.value, v, ordering_to_int(ord))
    let old = a.value
    a.value = a.value - v
    return old
}

fn atomic_compare_exchange(a: &!AtomicI64, current: i64, new: i64, success_ord: Ordering, fail_ord: Ordering) -> bool {
    // In real implementation: __atomic_cmpxchg_i64(&!a.value, current, new, ...)
    if a.value == current {
        a.value = new
        return true
    } else {
        return false
    }
}

fn atomic_swap(a: &!AtomicI64, v: i64, ord: Ordering) -> i64 {
    // In real implementation: __atomic_swap_i64(&!a.value, v, ordering_to_int(ord))
    let old = a.value
    a.value = v
    return old
}

//@ run-pass
// T_7 via sign function — no arrays, no multiplication, pure algebra

fn cd_sigma(a: i32, b: i32, bits: i32) -> i32 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return -1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma(a_lo, b_lo, bits - 1) }
        else { return 0 - cd_sigma(a_lo, b_lo, bits - 1) }
    }
    if b_lo == 0 { return 0 - cd_sigma(b_lo, a_lo, bits - 1) }
    else { return cd_sigma(b_lo, a_lo, bits - 1) }
}

fn main() -> i32 with Mut, Panic, Div, IO {
    println("Computing T_7 (dim 128, 127^3 = 2,048,383 triples)...")
    println("Using sign function only — no arrays, no multiplication.")
    println("")

    let bits: i32 = 7
    let n = 127
    var nonzero: i32 = 0

    var i: i32 = 1
    while i <= n {
        var j: i32 = 1
        while j <= n {
            var k: i32 = 1
            while k <= n {
                let alpha = cd_sigma(i, j, bits) * cd_sigma(i ^ j, k, bits)
                let beta = cd_sigma(j, k, bits) * cd_sigma(i, j ^ k, bits)
                if alpha != beta { nonzero = nonzero + 1 }
                k = k + 1
            }
            j = j + 1
        }
        if i % 20 == 0 {
            println(i)
        }
        i = i + 1
    }

    println("")
    println("T_7 = ")
    println(nonzero)
    println("Predicted: 168 * 6231 = 1046808")
    let predicted: i32 = 168 * 6231
    if nonzero == predicted {
        println("MATCH!")
    } else {
        println("MISMATCH")
        println(predicted)
    }
    0
}

