}

fn beta_mean(beta: Beta) -> f64 {
    return beta.alpha / (beta.alpha + beta.b)
}

fn beta_variance(beta: Beta) -> f64 {
    let s = beta.alpha + beta.b
    return (beta.alpha * beta.b) / (s * s * (s + 1.0))
}

