fn compute_std(values: [f64], mean: f64) -> f64 {
    var sum_sq_dev = 0.0;
    for i in 0..len(values) {
        let dev = values[i] - mean;
        sum_sq_dev = sum_sq_dev + dev * dev;
    }
    let variance = sum_sq_dev / (len(values) as f64);
    return sqrt(variance);
}

