fn test_full_metric() -> bool with Mut, Panic, Div {
    let e0_sq = geo_product(mv_basis(1), mv_basis(1))
    let e1_sq = geo_product(mv_basis(2), mv_basis(2))
    let e2_sq = geo_product(mv_basis(4), mv_basis(4))
    let e3_sq = geo_product(mv_basis(8), mv_basis(8))
    return approx_eq(e0_sq[0], 1.0, 1.0e-10)
        && approx_eq(e1_sq[0], 0.0 - 1.0, 1.0e-10)
        && approx_eq(e2_sq[0], 0.0 - 1.0, 1.0e-10)
        && approx_eq(e3_sq[0], 0.0 - 1.0, 1.0e-10)
}

fn test_full_associativity() -> bool with Mut, Panic, Div {
    // Test a representative sample: (e0*e1)*e2 vs e0*(e1*e2) and others
    let ab = geo_product(mv_basis(1), mv_basis(2))
    let lhs1 = geo_product(ab, mv_basis(4))
    let bc = geo_product(mv_basis(2), mv_basis(4))
    let rhs1 = geo_product(mv_basis(1), bc)
    if !mv_eq(lhs1, rhs1, 1.0e-10) { return false }

    // (e1*e2)*e3 vs e1*(e2*e3)
    let ab2 = geo_product(mv_basis(2), mv_basis(4))
    let lhs2 = geo_product(ab2, mv_basis(8))
    let bc2 = geo_product(mv_basis(4), mv_basis(8))
    let rhs2 = geo_product(mv_basis(2), bc2)
    if !mv_eq(lhs2, rhs2, 1.0e-10) { return false }

    // (e01*e23)*e3 vs e01*(e23*e3)
    let e01 = geo_product(mv_basis(1), mv_basis(2))
    let e23 = geo_product(mv_basis(4), mv_basis(8))
    let lhs3 = geo_product(geo_product(e01, e23), mv_basis(8))
    let rhs3 = geo_product(e01, geo_product(e23, mv_basis(8)))
    return mv_eq(lhs3, rhs3, 1.0e-10)
}

fn test_non_commutativity() -> bool with Mut, Panic, Div {
    let ab = geo_product(mv_basis(1), mv_basis(2))
    let ba = geo_product(mv_basis(2), mv_basis(1))
    // They should differ in sign: ab[3] = +1, ba[3] = -1
    return approx_eq(ab[3], 1.0, 1.0e-10) && approx_eq(ba[3], 0.0 - 1.0, 1.0e-10)
}

fn test_cl30_metric() -> bool with Mut, Panic, Div {
    // For Cl(3,0): e1^2=+1, e2^2=+1, e3^2=+1
    // We simulate by using geo_sign with metric (+,+,+,unused)
    // But our geo_sign is hardcoded for Cl(1,3).
    // Instead, verify that Cl(1,3) and Cl(3,0) differ:
    // In Cl(1,3): e1*e1 = -1. In Cl(3,0) it would be +1.
    // This test confirms Cl(1,3) is NOT Cl(3,0)
    let e1_sq = geo_product(mv_basis(2), mv_basis(2))
    return approx_eq(e1_sq[0], 0.0 - 1.0, 1.0e-10)  // -1, NOT +1
}

fn test_grade_structure() -> bool with Mut, Panic, Div {
    let e0e1 = geo_product(mv_basis(1), mv_basis(2))
    // Result should be pure grade-2: only index 3 (=e01) is nonzero
    var ok = true
    var i = 0
    while i < 16 {
        if i == 3 {
            if !approx_eq(e0e1[i], 1.0, 1.0e-10) { ok = false }
        } else {
            if abs_f64(e0e1[i]) > 1.0e-10 { ok = false }
        }
        i = i + 1
    }
    return ok
}

fn test_pseudoscalar_sign() -> bool with Mut, Panic, Div {
    let i_ps = mv_basis(15)
    let r = geo_product(i_ps, i_ps)
    return approx_eq(r[0], 0.0 - 1.0, 1.0e-10)
}

