fn cg_sqrt(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn confidence_gate(confidences: &[f64; 64], n: i64, min_confidence: f64) -> bool {
    var i = 0
    while i < n {
        if i < 64 { if confidences[i] < min_confidence { return false } }
        i = i + 1
    }
    true
}

fn my_sqrt(x: f32) -> f32 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i: i32 = 0
    while i < 30 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn vec8_get(v: Vec8, i: i32) -> f32 {
    if i == 0 { return v.v0 }
    if i == 1 { return v.v1 }
    if i == 2 { return v.v2 }
    if i == 3 { return v.v3 }
    if i == 4 { return v.v4 }
    if i == 5 { return v.v5 }
    if i == 6 { return v.v6 }
    v.v7
}

fn vec8_set(v: Vec8, i: i32, val: f32) -> Vec8 {
    Vec8 {
        v0: if i == 0 { val } else { v.v0 },
        v1: if i == 1 { val } else { v.v1 },
        v2: if i == 2 { val } else { v.v2 },
        v3: if i == 3 { val } else { v.v3 },
        v4: if i == 4 { val } else { v.v4 },
        v5: if i == 5 { val } else { v.v5 },
        v6: if i == 6 { val } else { v.v6 },
        v7: if i == 7 { val } else { v.v7 },
    }
}

fn vec8_dot(a: Vec8, b: Vec8) -> f32 {
    a.v0*b.v0 + a.v1*b.v1 + a.v2*b.v2 + a.v3*b.v3 +
    a.v4*b.v4 + a.v5*b.v5 + a.v6*b.v6 + a.v7*b.v7
}

fn vec8_norm(v: Vec8) -> f32 with Mut {
    my_sqrt(vec8_dot(v, v))
}

fn vec8_normalize(v: Vec8) -> Vec8 with Mut {
    let n = vec8_norm(v)
    if n < 0.00001 { return v }
    Vec8 {
        v0: v.v0 / n, v1: v.v1 / n, v2: v.v2 / n, v3: v.v3 / n,
        v4: v.v4 / n, v5: v.v5 / n, v6: v.v6 / n, v7: v.v7 / n,
    }
}

fn vec8_sub_proj(v: Vec8, u: Vec8) -> Vec8 {
    // v - (v·u)*u
    let d = vec8_dot(v, u)
    Vec8 {
        v0: v.v0 - d * u.v0, v1: v.v1 - d * u.v1,
        v2: v.v2 - d * u.v2, v3: v.v3 - d * u.v3,
        v4: v.v4 - d * u.v4, v5: v.v5 - d * u.v5,
        v6: v.v6 - d * u.v6, v7: v.v7 - d * u.v7,
    }
}

fn vec8_project_orth_ones(v: Vec8) -> Vec8 {
    let mean = (v.v0 + v.v1 + v.v2 + v.v3 + v.v4 + v.v5 + v.v6 + v.v7) / 8.0
    Vec8 {
        v0: v.v0 - mean, v1: v.v1 - mean, v2: v.v2 - mean, v3: v.v3 - mean,
        v4: v.v4 - mean, v5: v.v5 - mean, v6: v.v6 - mean, v7: v.v7 - mean,
    }
}

fn evecs7_get(e: Evecs7, k: i32) -> Vec8 {
    if k == 0 { return e.e0 }
    if k == 1 { return e.e1 }
    if k == 2 { return e.e2 }
    if k == 3 { return e.e3 }
    if k == 4 { return e.e4 }
    if k == 5 { return e.e5 }
    e.e6
}

fn evecs7_set(e: Evecs7, k: i32, v: Vec8) -> Evecs7 {
    Evecs7 {
        e0: if k == 0 { v } else { e.e0 },
        e1: if k == 1 { v } else { e.e1 },
        e2: if k == 2 { v } else { e.e2 },
        e3: if k == 3 { v } else { e.e3 },
        e4: if k == 4 { v } else { e.e4 },
        e5: if k == 5 { v } else { e.e5 },
        e6: if k == 6 { v } else { e.e6 },
        l0: e.l0, l1: e.l1, l2: e.l2, l3: e.l3, l4: e.l4, l5: e.l5, l6: e.l6,
    }
}

fn evecs7_get_eval(e: Evecs7, k: i32) -> f32 {
    if k == 0 { return e.l0 }
    if k == 1 { return e.l1 }
    if k == 2 { return e.l2 }
    if k == 3 { return e.l3 }
    if k == 4 { return e.l4 }
    if k == 5 { return e.l5 }
    e.l6
}

fn evecs7_set_eval(e: Evecs7, k: i32, val: f32) -> Evecs7 {
    Evecs7 {
        e0: e.e0, e1: e.e1, e2: e.e2, e3: e.e3, e4: e.e4, e5: e.e5, e6: e.e6,
        l0: if k == 0 { val } else { e.l0 },
        l1: if k == 1 { val } else { e.l1 },
        l2: if k == 2 { val } else { e.l2 },
        l3: if k == 3 { val } else { e.l3 },
        l4: if k == 4 { val } else { e.l4 },
        l5: if k == 5 { val } else { e.l5 },
        l6: if k == 6 { val } else { e.l6 },
    }
}

fn c8_extract_eigenvectors() -> Evecs7 with Mut {
    var result = Evecs7 {
        e0: vec8_zero(), e1: vec8_zero(), e2: vec8_zero(), e3: vec8_zero(),
        e4: vec8_zero(), e5: vec8_zero(), e6: vec8_zero(),
        l0: 0.0, l1: 0.0, l2: 0.0, l3: 0.0, l4: 0.0, l5: 0.0, l6: 0.0,
    }

    var ek: i32 = 0
    while ek < 7 {
        // Initialize with different starting vectors
        var v = vec8_zero()
        if ek == 0 { v = Vec8 { v0: 1.0, v1: 0.0-1.0, v2: 1.0, v3: 0.0-1.0, v4: 1.0, v5: 0.0-1.0, v6: 1.0, v7: 0.0-1.0 } }
        if ek == 1 { v = Vec8 { v0: 1.0, v1: 1.0, v2: 0.0-1.0, v3: 0.0-1.0, v4: 1.0, v5: 1.0, v6: 0.0-1.0, v7: 0.0-1.0 } }
        if ek == 2 { v = Vec8 { v0: 1.0, v1: 0.0, v2: 0.0-1.0, v3: 0.0, v4: 1.0, v5: 0.0, v6: 0.0-1.0, v7: 0.0 } }
        if ek == 3 { v = Vec8 { v0: 0.0, v1: 1.0, v2: 0.0, v3: 0.0-1.0, v4: 0.0, v5: 1.0, v6: 0.0, v7: 0.0-1.0 } }
        if ek == 4 { v = Vec8 { v0: 1.0, v1: 0.7, v2: 0.0, v3: 0.0-0.7, v4: 0.0-1.0, v5: 0.0-0.7, v6: 0.0, v7: 0.7 } }
        if ek == 5 { v = Vec8 { v0: 0.7, v1: 1.0, v2: 0.7, v3: 0.0, v4: 0.0-0.7, v5: 0.0-1.0, v6: 0.0-0.7, v7: 0.0 } }
        if ek == 6 { v = Vec8 { v0: 1.0, v1: 0.0-0.5, v2: 0.0-0.5, v3: 1.0, v4: 0.0-1.0, v5: 0.5, v6: 0.5, v7: 0.0-1.0 } }

        // Project out constant and previous eigenvectors
        v = vec8_project_orth_ones(v)
        var prev: i32 = 0
        while prev < ek {
            v = vec8_sub_proj(v, evecs7_get(result, prev))
            prev = prev + 1
        }
        v = vec8_normalize(v)

        // Power iteration on shifted matrix (200 iterations)
        var iter: i32 = 0
        while iter < 200 {
            var w = c8_shifted_mul(v)
            w = vec8_project_orth_ones(w)
            prev = 0
            while prev < ek {
                w = vec8_sub_proj(w, evecs7_get(result, prev))
                prev = prev + 1
            }
            w = vec8_normalize(w)
            v = w
            iter = iter + 1
        }

        // Rayleigh quotient on L
        let lv = c8_lap_mul(v)
        let eigenval = vec8_dot(v, lv)

        result = evecs7_set(result, ek, v)
        result = evecs7_set_eval(result, ek, eigenval)

        ek = ek + 1
    }
    result
}

fn co_sqrt(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn quadratic(x: &[f64; 64], n: i64) -> f64 {
    let a = x[0] - 3.0
    let b = x[1] - 5.0
    a * a + b * b
}

fn sum_squares(x: &[f64; 64], n: i64) -> f64 with Mut {
    var s = 0.0
    var i: i64 = 0
    while i < n { s = s + x[i] * x[i]; i = i + 1 }
    s
}

fn eval_obj(obj_id: i64, x: &[f64; 64], n: i64) -> f64 with Mut {
    if obj_id == 0 { return quadratic(x, n) }
    return sum_squares(x, n)
}

fn box_project(x: &![f64; 64], n: i64, lo: f64, hi: f64) with Mut {
    var i: i64 = 0
    while i < n {
        if x[i] < lo { x[i] = lo }
        if x[i] > hi { x[i] = hi }
        i = i + 1
    }
}

fn minimize_box(slot: i64, obj_id: i64, x0: &[f64; 64], n: i64, lo: f64, hi: f64,
                max_iter: i64, step_size: f64) with Mut, Div {
    var x:     [f64; 64] = [0.0; 64]
    var grad:  [f64; 64] = [0.0; 64]
    var x_pert:[f64; 64] = [0.0; 64]
    var x_trial:[f64;64] = [0.0; 64]

    var i: i64 = 0
    while i < n { x[i] = x0[i]; i = i + 1 }
    box_project(&!x, n, lo, hi)
    var f_val = eval_obj(obj_id, &x, n)
    var func_evals: i64 = 1
    var converged: i64 = 0

    var iter: i64 = 0
    while iter < max_iter {
        // Copy x into x_pert
        i = 0
        while i < n { x_pert[i] = x[i]; i = i + 1 }

        // Compute gradient via finite differences
        i = 0
        while i < n {
            let h = co_max(1.0e-7 * co_abs(x[i]), 1.0e-7)
            x_pert[i] = x[i] + h
            let fp = eval_obj(obj_id, &x_pert, n)
            x_pert[i] = x[i] - h
            let fm = eval_obj(obj_id, &x_pert, n)
            x_pert[i] = x[i]
            grad[i] = (fp - fm) / (2.0 * h)
            func_evals = func_evals + 2
            i = i + 1
        }

        // Projected gradient norm
        var grad_norm_sq = 0.0
        i = 0
        while i < n {
            var gi = grad[i]
            if x[i] <= lo + 1.0e-10 && gi > 0.0 { gi = 0.0 }
            if x[i] >= hi - 1.0e-10 && gi < 0.0 { gi = 0.0 }
            grad_norm_sq = grad_norm_sq + gi * gi
            i = i + 1
        }
        if co_sqrt(grad_norm_sq) < 1.0e-5 { converged = 1; break }

        // Backtracking line search with projection
        var alpha = step_size
        var ls: i64 = 0
        var stepped: i64 = 0
        while ls < 30 && stepped == 0 {
            i = 0
            while i < n { x_trial[i] = x[i] - alpha * grad[i]; i = i + 1 }
            box_project(&!x_trial, n, lo, hi)
            let ft = eval_obj(obj_id, &x_trial, n)
            func_evals = func_evals + 1
            if ft < f_val - 1.0e-4 * alpha * grad_norm_sq {
                i = 0
                while i < n { x[i] = x_trial[i]; i = i + 1 }
                f_val = ft
                stepped = 1
            } else {
                alpha = alpha * 0.5
            }
            ls = ls + 1
        }
        if stepped == 0 { break }
        iter = iter + 1
    }

    // Write results to globals
    let base = slot * 64
    i = 0
    while i < 64 { G_PARAMS[base + i] = x[i]; i = i + 1 }
    G_VALUE[slot] = f_val
    G_ITERS[slot] = iter
    G_CONV[slot] = converged
}

