fn rp3_add(a: Rp3St, b: Rp3St) -> Rp3St {
    return Rp3St {
        blood: a.blood + b.blood,
        brain: a.brain + b.brain,
        periph: a.periph + b.periph,
    }
}

fn rp3_scale(s: Rp3St, f: f64) -> Rp3St {
    return Rp3St {
        blood: s.blood * f,
        brain: s.brain * f,
        periph: s.periph * f,
    }
}

fn rp3_ode(st: Rp3St, p: Rp3Prm) -> Rp3St {
    let cl_eff = p.cl_hepatic * p.fu_plasma

    let inflow_brain = p.q_brain / p.v_blood * st.brain / p.kp_brain
    let inflow_periph = p.q_periph / p.v_blood * st.periph / p.kp_periph
    let outflow = (p.q_brain + p.q_periph) / p.v_blood * st.blood
    let clearance = cl_eff / p.v_blood * st.blood

    let d_blood = inflow_brain + inflow_periph - outflow - clearance
    let d_brain = (p.q_brain / p.v_brain) * (st.blood - st.brain / p.kp_brain)
    let d_periph = (p.q_periph / p.v_periph) * (st.blood - st.periph / p.kp_periph)

    return Rp3St { blood: d_blood, brain: d_brain, periph: d_periph }
}

fn rk4_advance(st: Rp3St, p: Rp3Prm, dt: f64) -> Rp3St {
    let k1 = rp3_ode(st, p)
    let s2 = rp3_add(st, rp3_scale(k1, dt * 0.5))
    let k2 = rp3_ode(s2, p)
    let s3 = rp3_add(st, rp3_scale(k2, dt * 0.5))
    let k3 = rp3_ode(s3, p)
    let s4 = rp3_add(st, rp3_scale(k3, dt))
    let k4 = rp3_ode(s4, p)

    let w = rp3_add(k1, rp3_add(rp3_scale(k2, 2.0), rp3_add(rp3_scale(k3, 2.0), k4)))
    return rp3_add(st, rp3_scale(w, dt / 6.0))
}

fn run_sim(prm: Rp3Prm, dose_mg: f64, t_end: f64) -> Metrics {
    let c0 = dose_mg / prm.v_blood
    var st = Rp3St { blood: c0, brain: 0.0, periph: 0.0 }
    var t = 0.0
    let dt = 0.1
    var cmax = c0
    var auc = 0.0
    var c_prev = c0

    while t < t_end {
        var dt_use = dt
        if t + dt > t_end { dt_use = t_end - t }
        st = rk4_advance(st, prm, dt_use)
        if st.blood > cmax { cmax = st.blood }
        auc = auc + (c_prev + st.blood) * 0.5 * dt_use
        c_prev = st.blood
        t = t + dt_use
    }

    return Metrics { cmax: cmax, auc: auc, brain_final: st.brain, blood_final: st.blood }
}

fn mean_params() -> Rp3Prm {
    return Rp3Prm {
        v_blood: 5.0,
        v_brain: 1.4,
        v_periph: 50.0,
        q_brain: 0.05,
        q_periph: 87.0,
        kp_brain: 0.08,
        kp_periph: 0.5,
        cl_hepatic: 12.4,
        fu_plasma: 0.08,
    }
}

fn get_priors() -> EpPriors {
    return EpPriors {
        cl_mean: 12.4,    cl_var: 54.76,     cl_conf: 0.65,
        kp_mean: 0.08,    kp_var: 0.000625,  kp_conf: 0.55,
        fu_mean: 0.08,    fu_var: 0.0004,    fu_conf: 0.72,
    }
}

fn run_epistemic(priors: EpPriors, dose: f64, t_end: f64) -> EpResult {
    let prm_ref = mean_params()
    let ref_m = run_sim(prm_ref, dose, t_end)
    let auc_ref = ref_m.auc
    var bpr_ref = 0.0
    if ref_m.blood_final > 0.000000000001 {
        bpr_ref = ref_m.brain_final / ref_m.blood_final
    }

    // Perturbation 1: CL
    let h_cl = fdiff_h(priors.cl_mean, priors.cl_var)
    var prm_cl = mean_params()
    prm_cl.cl_hepatic = prm_ref.cl_hepatic + h_cl
    let m_cl = run_sim(prm_cl, dose, t_end)
    let dauc_dcl = (m_cl.auc - auc_ref) / h_cl

    // Perturbation 2: kp_brain
    let h_kp = fdiff_h(priors.kp_mean, priors.kp_var)
    var prm_kp = mean_params()
    prm_kp.kp_brain = prm_ref.kp_brain + h_kp
    let m_kp = run_sim(prm_kp, dose, t_end)
    let dauc_dkp = (m_kp.auc - auc_ref) / h_kp

    // Perturbation 3: fu_plasma
    let h_fu = fdiff_h(priors.fu_mean, priors.fu_var)
    var prm_fu = mean_params()
    prm_fu.fu_plasma = prm_ref.fu_plasma + h_fu
    let m_fu = run_sim(prm_fu, dose, t_end)
    let dauc_dfu = (m_fu.auc - auc_ref) / h_fu

    // GUM variance propagation
    let var_auc = dauc_dcl * dauc_dcl * priors.cl_var
               + dauc_dkp * dauc_dkp * priors.kp_var
               + dauc_dfu * dauc_dfu * priors.fu_var

    // BPR variance (finite diff)
    var bpr_cl = 0.0
    if m_cl.blood_final > 0.000000000001 { bpr_cl = m_cl.brain_final / m_cl.blood_final }
    var bpr_kp = 0.0
    if m_kp.blood_final > 0.000000000001 { bpr_kp = m_kp.brain_final / m_kp.blood_final }
    let dbpr_dcl = (bpr_cl - bpr_ref) / h_cl
    let dbpr_dkp = (bpr_kp - bpr_ref) / h_kp

    let var_bpr = dbpr_dcl * dbpr_dcl * priors.cl_var
               + dbpr_dkp * dbpr_dkp * priors.kp_var

    // Sensitivity fractions
    var s_cl = 0.0
    var s_kp = 0.0
    var s_fu = 0.0
    if var_auc > 0.0000000000000000000000000000001 {
        s_cl = dauc_dcl * dauc_dcl * priors.cl_var / var_auc
        s_kp = dauc_dkp * dauc_dkp * priors.kp_var / var_auc
        s_fu = dauc_dfu * dauc_dfu * priors.fu_var / var_auc
    }

    // Evidence-weighted confidence
    let conf_auc = priors.cl_conf * s_cl + priors.kp_conf * s_kp + priors.fu_conf * s_fu

    return EpResult {
        auc_mean: auc_ref,
        auc_var: var_auc,
        auc_conf: conf_auc,
        bpr_mean: bpr_ref,
        bpr_var: var_bpr,
        s_cl: s_cl,
        s_kp: s_kp,
        s_fu: s_fu,
    }
}

fn rxn_merkle_mix(a: i64, b: i64, c: i64, salt: i64) -> i64 {
    ((a ^ b) + c + salt) ^ (a << 5) ^ (b >> 7)
}

fn rxn_merkle_root_lane_l64(
    p0: i64, p1: i64, p2: i64, p3: i64, p4: i64
) -> i64 {
    let h0 = rxn_merkle_mix(p0, p1, p2, RXN_MERKLE_SALT_A)
    let h1 = rxn_merkle_mix(p3, p4, h0, RXN_MERKLE_SALT_B)
    let h2 = rxn_merkle_mix(h0, h1, p0 ^ p3, RXN_MERKLE_SALT_C)
    rxn_merkle_mix(h1, h2, p1 ^ p2, RXN_MERKLE_SALT_D)
}

fn rxn_metabolite_hash(symbol: i64) -> i64 {
    var hash: i64 = 5381
    hash = hash * 33 + symbol
    hash & 9223372036854775807
}

fn rxn_provenance_seed(item_hash: i64) -> i64 {
    rxn_merkle_root_lane_l64(0, item_hash, 0, 0, 1)
}

fn rxn_provenance_merge(
    existing_root_l64: i64,
    item_hash: i64,
    variance_q32_32: i64,
    confidence_beta: i64
) -> i64 {
    rxn_merkle_root_lane_l64(
        existing_root_l64,
        item_hash,
        variance_q32_32,
        confidence_beta,
        existing_root_l64 ^ item_hash
    )
}

fn rxn_delta_32(fidelity: i64, provenance: i64, quantum: i64) -> i64 {
    let frac_f = fidelity - (fidelity / 8) * 8
    let frac_p = provenance - (provenance / 16) * 16
    let frac_q = quantum - (quantum / 32) * 32
    frac_f * 4 + frac_p * 2 + frac_q
}

fn rxn_add_reactant(
    r: EpistemicReaction, prov_l64: i64, variance: i64, confidence: i64
) -> EpistemicReaction with Mut, Panic {
    var rxn = r
    if rxn.reactant_count >= RXN_MAX_SPECIES {
        return rxn
    }
    let id = rxn.reactant_count
    rxn.reactant_prov_l64[id] = prov_l64
    rxn.reactant_variance_q32_32[id] = variance
    rxn.reactant_confidence_beta[id] = confidence
    rxn.reactant_count = rxn.reactant_count + 1
    rxn
}

fn rxn_add_product(
    r: EpistemicReaction, product_hash: i64, variance: i64, confidence: i64
) -> EpistemicReaction with Mut, Panic {
    var rxn = r
    if rxn.product_count >= RXN_MAX_SPECIES {
        return rxn
    }
    let id = rxn.product_count
    rxn.product_prov_l64[id] = rxn_provenance_seed(product_hash)
    rxn.product_variance_q32_32[id] = variance
    rxn.product_confidence_beta[id] = confidence
    rxn.product_count = rxn.product_count + 1
    rxn
}

fn rxn_set_enzyme(r: EpistemicReaction, enzyme_prov: i64) -> EpistemicReaction {
    var rxn = r
    rxn.enzyme_prov_l64 = enzyme_prov
    rxn
}

fn rxn_product_provenance(r: EpistemicReaction, idx: i64) -> i64 with Panic, Div {
    if idx < 0 || idx >= r.product_count { return 0 }
    r.product_prov_l64[idx]
}

fn rxn_product_variance(r: EpistemicReaction, idx: i64) -> i64 with Panic, Div {
    if idx < 0 || idx >= r.product_count { return 0 }
    r.product_variance_q32_32[idx]
}

fn rxn_product_confidence(r: EpistemicReaction, idx: i64) -> i64 with Panic, Div {
    if idx < 0 || idx >= r.product_count { return 0 }
    r.product_confidence_beta[idx]
}

fn rxn_apply(r: EpistemicReaction) -> EpistemicReaction with Mut, Panic, Div {
    var rxn = r

    // Phase 1: fold reactant provenance into reaction root
    var root: i64 = 0
    var i: i64 = 0
    while i < rxn.reactant_count {
        root = rxn_merkle_mix(
            root,
            rxn.reactant_prov_l64[i],
            rxn.reactant_variance_q32_32[i],
            RXN_MERKLE_SALT_A
        )
        i = i + 1
    }

    // Include enzyme if present
    if rxn.enzyme_prov_l64 >= 0 {
        root = rxn_merkle_mix(root, rxn.enzyme_prov_l64, 0, RXN_MERKLE_SALT_B)
    }

    rxn.rxn_provenance_l64 = root
    rxn.rxn_variance_q32_32 = rxn.rxn_variance_q32_32 + 1
    rxn.rxn_confidence_beta = rxn.rxn_confidence_beta + 1

    // Phase 2: merge reaction root into each product's provenance
    var j: i64 = 0
    while j < rxn.product_count {
        let merged = rxn_provenance_merge(
            rxn.product_prov_l64[j],
            root,
            rxn.product_variance_q32_32[j] + 1,
            rxn.product_confidence_beta[j] + 1
        )
        rxn.product_prov_l64[j] = merged
        rxn.product_variance_q32_32[j] = rxn.product_variance_q32_32[j] + 1
        rxn.product_confidence_beta[j] = rxn.product_confidence_beta[j] + 1
        j = j + 1
    }

    rxn.applied = 1
    rxn
}

fn rxn_verify_conservation(r: EpistemicReaction) -> bool with Mut, Panic, Div {
    if r.applied != 1 { return false }
    if r.rxn_provenance_l64 == 0 { return false }

    let rxn_delta = rxn_delta_32(r.rxn_variance_q32_32, 0, r.rxn_confidence_beta)
    if rxn_delta < 0 || rxn_delta >= 96 { return false }

    var i: i64 = 0
    while i < r.product_count {
        if r.product_prov_l64[i] == 0 { return false }
        let pdelta = rxn_delta_32(r.product_variance_q32_32[i], 0, r.product_confidence_beta[i])
        if pdelta < 0 || pdelta >= 96 { return false }
        i = i + 1
    }
    true
}

