fn main() -> i32 {
    var sum: i64 = 0
    for i in 0..5 {
        sum = sum + i
    }
    if sum != 10 { return 1 }

    var sum2: i64 = 0
    for i in 0..=5 {
        sum2 = sum2 + i
    }
    if sum2 != 15 { return 2 }

    return 0
}

fn fano_a(line: i32) -> i32 {
    if line == 0 { return 0 }
    if line == 1 { return 0 }
    if line == 2 { return 0 }
    if line == 3 { return 1 }
    if line == 4 { return 1 }
    if line == 5 { return 2 }
    2
}

fn fano_b(line: i32) -> i32 {
    if line == 0 { return 1 }
    if line == 1 { return 3 }
    if line == 2 { return 5 }
    if line == 3 { return 3 }
    if line == 4 { return 4 }
    if line == 5 { return 3 }
    4
}

fn fano_c(line: i32) -> i32 {
    if line == 0 { return 2 }
    if line == 1 { return 4 }
    if line == 2 { return 6 }
    if line == 3 { return 5 }
    if line == 4 { return 6 }
    if line == 5 { return 6 }
    5
}

fn triple_a(idx: i32) -> i32 {
    // 35 triples of {0..6} with a<b<c
    if idx < 15 { // a=0
        if idx < 10 { return 0 }
        return 0
    }
    if idx < 25 { return 1 } // a=1
    if idx < 31 { return 2 } // a=2
    if idx < 34 { return 3 } // a=3
    4 // a=4
}

fn triple_index(a: i32, b: i32, c: i32) -> i32 with Mut {
    var idx: i32 = 0
    while idx < 35 {
        if triple_a(idx) == a && triple_b(idx) == b && triple_c(idx) == c {
            return idx
        }
        idx = idx + 1
    }
    0
}

fn is_fano(a: i32, b: i32, c: i32) -> bool with Mut {
    var line: i32 = 0
    while line < 7 {
        let fa = fano_a(line)
        let fb = fano_b(line)
        let fc = fano_c(line)
        if (a == fa && b == fb && c == fc) { return true }
        line = line + 1
    }
    false
}

fn perm7_get(p: Perm7, i: i32) -> i32 {
    if i == 0 { return p.p0 }
    if i == 1 { return p.p1 }
    if i == 2 { return p.p2 }
    if i == 3 { return p.p3 }
    if i == 4 { return p.p4 }
    if i == 5 { return p.p5 }
    p.p6
}

fn perm7_identity() -> Perm7 {
    Perm7 { p0: 0, p1: 1, p2: 2, p3: 3, p4: 4, p5: 5, p6: 6 }
}

fn perm7_set(p: Perm7, i: i32, v: i32) -> Perm7 {
    Perm7 {
        p0: if i == 0 { v } else { p.p0 },
        p1: if i == 1 { v } else { p.p1 },
        p2: if i == 2 { v } else { p.p2 },
        p3: if i == 3 { v } else { p.p3 },
        p4: if i == 4 { v } else { p.p4 },
        p5: if i == 5 { v } else { p.p5 },
        p6: if i == 6 { v } else { p.p6 },
    }
}

fn perm7_swap(p: Perm7, i: i32, j: i32) -> Perm7 {
    let vi = perm7_get(p, i)
    let vj = perm7_get(p, j)
    perm7_set(perm7_set(p, i, vj), j, vi)
}

fn perm7_next(p: Perm7) -> Perm7 with Mut {
    // Find largest i with p[i] < p[i+1]
    var i: i32 = 5
    while i >= 0 && perm7_get(p, i) >= perm7_get(p, i + 1) { i = i - 1 }
    if i < 0 { return Perm7 { p0: 0-1, p1: 0, p2: 0, p3: 0, p4: 0, p5: 0, p6: 0 } } // sentinel: done
    // Find largest j with p[j] > p[i]
    var j: i32 = 6
    while perm7_get(p, j) <= perm7_get(p, i) { j = j - 1 }
    var r = perm7_swap(p, i, j)
    // Reverse suffix from i+1 to 6
    var lo = i + 1
    var hi: i32 = 6
    while lo < hi { r = perm7_swap(r, lo, hi); lo = lo + 1; hi = hi - 1 }
    r
}

fn perm7_inv(p: Perm7) -> Perm7 with Mut {
    var inv = perm7_identity()
    var k: i32 = 0
    while k < 7 {
        inv = perm7_set(inv, perm7_get(p, k), k)
        k = k + 1
    }
    inv
}

fn fano_energy(tp_sq: &[f64; 35], perm: Perm7) -> f64 with Mut {
    let inv = perm7_inv(perm)
    var sum: f64 = 0.0
    var line: i32 = 0
    while line < 7 {
        // Fano triple in basis space
        let bi = fano_a(line)
        let bj = fano_b(line)
        let bk = fano_c(line)
        // Map to eigenvector indices via inverse perm
        let ei = perm7_get(inv, bi)
        let ej = perm7_get(inv, bj)
        let ek = perm7_get(inv, bk)
        // Sort
        var a = ei
        var b = ej
        var c = ek
        if a > b { let t = a; a = b; b = t }
        if b > c { let t = b; b = c; c = t }
        if a > b { let t = a; a = b; b = t }
        let idx = triple_index(a, b, c)
        sum = sum + tp_sq[idx]
        line = line + 1
    }
    sum / 7.0
}

fn optimal_fano_energy(tp_sq: &[f64; 35]) -> f64 with Mut {
    var best: f64 = 0.0 - 1.0
    var perm = perm7_identity()
    var count: i32 = 0
    var done: bool = false
    while !done {
        let fe = fano_energy(tp_sq, perm)
        if fe > best { best = fe }
        count = count + 1
        perm = perm7_next(perm)
        if perm.p0 < 0 { done = true }
    }
    best
}

fn rng_next(state: i64) -> i64 with Div {
    let a: i64 = 16807
    let m: i64 = 2147483647
    let q: i64 = 127773
    let r: i64 = 2836
    let hi = state / q
    let lo = state - hi * q
    let t = a * lo - r * hi
    if t > 0 { t } else { t + m }
}

fn sqrt_f32(x: f32) -> f32 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i: i32 = 0
    while i < 30 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn rng_next(r: Rng) -> Rng {
    let a = 16807
    let m = 2147483647
    let q = 127773
    let rem = 2836
    let hi = r.state / q
    let lo = r.state - hi * q
    let t = a * lo - rem * hi
    Rng { state: if t > 0 { t } else { t + m } }
}

fn rng_angle(r: Rng) -> f32 {
    let frac = (r.state / 100) as f32 / 21474836.0
    (frac - 0.5) * 6.2831853
}

fn vec8_normalize(v: Vec8) -> Vec8 with Mut {
    let n = vec8_norm(v)
    if n < 0.00001 { return v }
    Vec8 { v0: v.v0/n, v1: v.v1/n, v2: v.v2/n, v3: v.v3/n,
           v4: v.v4/n, v5: v.v5/n, v6: v.v6/n, v7: v.v7/n }
}

fn vec8_sub_proj(v: Vec8, u: Vec8) -> Vec8 {
    let d = vec8_dot(v, u)
    Vec8 { v0: v.v0-d*u.v0, v1: v.v1-d*u.v1, v2: v.v2-d*u.v2, v3: v.v3-d*u.v3,
           v4: v.v4-d*u.v4, v5: v.v5-d*u.v5, v6: v.v6-d*u.v6, v7: v.v7-d*u.v7 }
}

fn vec8_project_orth_ones(v: Vec8) -> Vec8 {
    let mean = (v.v0+v.v1+v.v2+v.v3+v.v4+v.v5+v.v6+v.v7) / 8.0
    Vec8 { v0: v.v0-mean, v1: v.v1-mean, v2: v.v2-mean, v3: v.v3-mean,
           v4: v.v4-mean, v5: v.v5-mean, v6: v.v6-mean, v7: v.v7-mean }
}

fn evecs7_set(e: Evecs7, k: i32, v: Vec8) -> Evecs7 {
    Evecs7 {
        e0: if k == 0 { v } else { e.e0 }, e1: if k == 1 { v } else { e.e1 },
        e2: if k == 2 { v } else { e.e2 }, e3: if k == 3 { v } else { e.e3 },
        e4: if k == 4 { v } else { e.e4 }, e5: if k == 5 { v } else { e.e5 },
        e6: if k == 6 { v } else { e.e6 },
        l0: e.l0, l1: e.l1, l2: e.l2, l3: e.l3, l4: e.l4, l5: e.l5, l6: e.l6,
    }
}

fn evecs7_set_eval(e: Evecs7, k: i32, val: f32) -> Evecs7 {
    Evecs7 {
        e0: e.e0, e1: e.e1, e2: e.e2, e3: e.e3, e4: e.e4, e5: e.e5, e6: e.e6,
        l0: if k == 0 { val } else { e.l0 }, l1: if k == 1 { val } else { e.l1 },
        l2: if k == 2 { val } else { e.l2 }, l3: if k == 3 { val } else { e.l3 },
        l4: if k == 4 { val } else { e.l4 }, l5: if k == 5 { val } else { e.l5 },
        l6: if k == 6 { val } else { e.l6 },
    }
}

fn synth_lap_mul(v: Vec8) -> Vec8 with Mut {
    let w = 0.3   // inter-community weight
    // Degree: nodes 0,1,2 have deg=3+w=3.3, node 3 has deg=3, nodes 4,5,6 have deg=3+w=3.3, node 7 has deg=3
    let d03 = 3.0
    let d_inter = 3.0 + w
    Vec8 {
        v0: d_inter*v.v0 - v.v1 - v.v2 - v.v3 - w*v.v4,
        v1: d_inter*v.v1 - v.v0 - v.v2 - v.v3 - w*v.v5,
        v2: d_inter*v.v2 - v.v0 - v.v1 - v.v3 - w*v.v6,
        v3: d03*v.v3 - v.v0 - v.v1 - v.v2,
        v4: d_inter*v.v4 - v.v5 - v.v6 - v.v7 - w*v.v0,
        v5: d_inter*v.v5 - v.v4 - v.v6 - v.v7 - w*v.v1,
        v6: d_inter*v.v6 - v.v4 - v.v5 - v.v7 - w*v.v2,
        v7: d03*v.v7 - v.v4 - v.v5 - v.v6,
    }
}

fn synth_shifted_mul(v: Vec8) -> Vec8 with Mut {
    let lv = synth_lap_mul(v)
    let lmax = 5.0  // safe overestimate
    Vec8 {
        v0: lmax*v.v0 - lv.v0, v1: lmax*v.v1 - lv.v1,
        v2: lmax*v.v2 - lv.v2, v3: lmax*v.v3 - lv.v3,
        v4: lmax*v.v4 - lv.v4, v5: lmax*v.v5 - lv.v5,
        v6: lmax*v.v6 - lv.v6, v7: lmax*v.v7 - lv.v7,
    }
}

fn synth_extract_eigenvectors() -> Evecs7 with Mut {
    var result = Evecs7 {
        e0: vec8_zero(), e1: vec8_zero(), e2: vec8_zero(), e3: vec8_zero(),
        e4: vec8_zero(), e5: vec8_zero(), e6: vec8_zero(),
        l0: 0.0, l1: 0.0, l2: 0.0, l3: 0.0, l4: 0.0, l5: 0.0, l6: 0.0,
    }
    var ek: i32 = 0
    while ek < 7 {
        // Different starting vectors
        var v = vec8_zero()
        if ek == 0 { v = Vec8 { v0: 1.0, v1: 1.0, v2: 1.0, v3: 1.0, v4: 0.0-1.0, v5: 0.0-1.0, v6: 0.0-1.0, v7: 0.0-1.0 } }
        if ek == 1 { v = Vec8 { v0: 1.0, v1: 0.0-1.0, v2: 1.0, v3: 0.0-1.0, v4: 1.0, v5: 0.0-1.0, v6: 1.0, v7: 0.0-1.0 } }
        if ek == 2 { v = Vec8 { v0: 1.0, v1: 1.0, v2: 0.0-1.0, v3: 0.0-1.0, v4: 1.0, v5: 1.0, v6: 0.0-1.0, v7: 0.0-1.0 } }
        if ek == 3 { v = Vec8 { v0: 1.0, v1: 0.0-1.0, v2: 0.0, v3: 0.0, v4: 1.0, v5: 0.0-1.0, v6: 0.0, v7: 0.0 } }
        if ek == 4 { v = Vec8 { v0: 0.0, v1: 0.0, v2: 1.0, v3: 0.0-1.0, v4: 0.0, v5: 0.0, v6: 1.0, v7: 0.0-1.0 } }
        if ek == 5 { v = Vec8 { v0: 1.0, v1: 0.5, v2: 0.0-0.5, v3: 0.0-1.0, v4: 0.0-1.0, v5: 0.0-0.5, v6: 0.5, v7: 1.0 } }
        if ek == 6 { v = Vec8 { v0: 0.5, v1: 1.0, v2: 0.0-1.0, v3: 0.5, v4: 0.0-0.5, v5: 0.0-1.0, v6: 1.0, v7: 0.0-0.5 } }

        v = vec8_project_orth_ones(v)
        var prev: i32 = 0
        while prev < ek { v = vec8_sub_proj(v, evecs7_get(result, prev)); prev = prev + 1 }
        v = vec8_normalize(v)

        var iter: i32 = 0
        while iter < 300 {
            var w = synth_shifted_mul(v)
            w = vec8_project_orth_ones(w)
            prev = 0
            while prev < ek { w = vec8_sub_proj(w, evecs7_get(result, prev)); prev = prev + 1 }
            w = vec8_normalize(w)
            v = w
            iter = iter + 1
        }

        let lv = synth_lap_mul(v)
        let eigenval = vec8_dot(v, lv)
        result = evecs7_set(result, ek, v)
        result = evecs7_set_eval(result, ek, eigenval)
        ek = ek + 1
    }
    result
}

fn fano_line_i(n: i32) -> i32 {
    if n == 0 { return 1 } if n == 1 { return 1 } if n == 2 { return 1 }
    if n == 3 { return 2 } if n == 4 { return 2 } if n == 5 { return 3 }
    3
}

fn fano_line_j(n: i32) -> i32 {
    if n == 0 { return 2 } if n == 1 { return 4 } if n == 2 { return 7 }
    if n == 3 { return 4 } if n == 4 { return 5 } if n == 5 { return 4 }
    6
}

fn fano_line_k(n: i32) -> i32 {
    if n == 0 { return 3 } if n == 1 { return 5 } if n == 2 { return 6 }
    if n == 3 { return 6 } if n == 4 { return 7 } if n == 5 { return 7 }
    5
}

fn gram_get(g: Gram49, i: i32, j: i32) -> f32 {
    let idx = i * 7 + j
    if idx == 0 { return g.g00 } if idx == 1 { return g.g01 } if idx == 2 { return g.g02 }
    if idx == 3 { return g.g03 } if idx == 4 { return g.g04 } if idx == 5 { return g.g05 }
    if idx == 6 { return g.g06 } if idx == 7 { return g.g10 } if idx == 8 { return g.g11 }
    if idx == 9 { return g.g12 } if idx == 10 { return g.g13 } if idx == 11 { return g.g14 }
    if idx == 12 { return g.g15 } if idx == 13 { return g.g16 } if idx == 14 { return g.g20 }
    if idx == 15 { return g.g21 } if idx == 16 { return g.g22 } if idx == 17 { return g.g23 }
    if idx == 18 { return g.g24 } if idx == 19 { return g.g25 } if idx == 20 { return g.g26 }
    if idx == 21 { return g.g30 } if idx == 22 { return g.g31 } if idx == 23 { return g.g32 }
    if idx == 24 { return g.g33 } if idx == 25 { return g.g34 } if idx == 26 { return g.g35 }
    if idx == 27 { return g.g36 } if idx == 28 { return g.g40 } if idx == 29 { return g.g41 }
    if idx == 30 { return g.g42 } if idx == 31 { return g.g43 } if idx == 32 { return g.g44 }
    if idx == 33 { return g.g45 } if idx == 34 { return g.g46 } if idx == 35 { return g.g50 }
    if idx == 36 { return g.g51 } if idx == 37 { return g.g52 } if idx == 38 { return g.g53 }
    if idx == 39 { return g.g54 } if idx == 40 { return g.g55 } if idx == 41 { return g.g56 }
    if idx == 42 { return g.g60 } if idx == 43 { return g.g61 } if idx == 44 { return g.g62 }
    if idx == 45 { return g.g63 } if idx == 46 { return g.g64 } if idx == 47 { return g.g65 }
    g.g66
}

fn g2_3form_gram(g: Gram49) -> f32 with Mut, Div {
    var phi: f32 = 0.0
    var line: i32 = 0
    while line < 7 {
        let ii = fano_line_i(line) - 1  // to 0-indexed
        let jj = fano_line_j(line) - 1
        let kk = fano_line_k(line) - 1
        let g11 = gram_get(g, ii, ii)
        let g12 = gram_get(g, ii, jj)
        let g13 = gram_get(g, ii, kk)
        let g21 = gram_get(g, jj, ii)
        let g22 = gram_get(g, jj, jj)
        let g23 = gram_get(g, jj, kk)
        let g31 = gram_get(g, kk, ii)
        let g32 = gram_get(g, kk, jj)
        let g33 = gram_get(g, kk, kk)
        let det = g11*(g22*g33 - g23*g32) - g12*(g21*g33 - g23*g31) + g13*(g21*g32 - g22*g31)
        let sign = cd_sigma(fano_line_i(line), fano_line_j(line))
        if sign > 0 { phi = phi + det } else { phi = phi - det }
        line = line + 1
    }
    phi
}

fn su3_quality_gram(g: Gram49) -> f32 with Mut {
    var total: f32 = 0.0
    var off: f32 = 0.0
    var i: i32 = 0
    while i < 7 {
        var j: i32 = 0
        while j < 7 {
            let val = gram_get(g, i, j)
            let v2 = val * val
            total = total + v2
            if su3_block(i) != su3_block(j) { off = off + v2 }
            j = j + 1
        }
        i = i + 1
    }
    if total < 0.000001 { return 0.0 }
    1.0 - off / total
}

fn frame7_givens(f: Frame7, i: i32, j: i32, theta: f32) -> Frame7 with Mut {
    let c = cos_f32(theta)
    let s = sin_f32(theta)
    let vi = frame7_get(f, i)
    let vj = frame7_get(f, j)
    let vi_new = Vec7 {
        v0: c*vi.v0+s*vj.v0, v1: c*vi.v1+s*vj.v1, v2: c*vi.v2+s*vj.v2,
        v3: c*vi.v3+s*vj.v3, v4: c*vi.v4+s*vj.v4, v5: c*vi.v5+s*vj.v5, v6: c*vi.v6+s*vj.v6,
    }
    let vj_new = Vec7 {
        v0: 0.0-s*vi.v0+c*vj.v0, v1: 0.0-s*vi.v1+c*vj.v1, v2: 0.0-s*vi.v2+c*vj.v2,
        v3: 0.0-s*vi.v3+c*vj.v3, v4: 0.0-s*vi.v4+c*vj.v4, v5: 0.0-s*vi.v5+c*vj.v5,
        v6: 0.0-s*vi.v6+c*vj.v6,
    }
    frame7_set(frame7_set(f, i, vi_new), j, vj_new)
}

fn run_pipeline() -> G2Result with Mut, Div {
    // Step 1-3: Extract eigenvectors
    let evecs = synth_extract_eigenvectors()

    // Step 4-5: Compute G₂ invariants
    let gram = build_gram(evecs)
    let phi = g2_3form_gram(gram)
    let q = su3_quality_gram(gram)
    let phi_abs = abs_f32(phi)

    // Step 6-7: Null model (30 random SO(7) rotations)
    let n_null = 30
    var sum_null_phi: f32 = 0.0
    var count_ge: i32 = 0
    var r = rng_new(12345)
    var trial: i32 = 0
    while trial < n_null {
        r = rng_next(r)
        let rot = frame7_random_so7(frame7_identity(), r)
        r = rot.rng
        let null_phi = abs_f32(g2_3form_frame(rot.frame))
        sum_null_phi = sum_null_phi + null_phi
        if null_phi >= phi_abs { count_ge = count_ge + 1 }
        trial = trial + 1
    }

    G2Result {
        phi: phi,
        su3_quality: q,
        null_mean_phi: sum_null_phi / n_null as f32,
        p_value: count_ge as f32 / n_null as f32,
    }
}

