        prev_val = val
        t = t + step
        count = count + 1
    }

    print("  max_jump=")
    println(max_jump)
    print("  n_points=")
    println(count)

    // For step=0.01 on quadratic data, jumps should be small (no discontinuities)
    return max_jump < 0.5
}

