fn sqrt_f64(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 }
    var y = x;
    var i = 0
    while i < 20 {
        y = 0.5 * (y + x / y)
        i = i + 1
    }
    y
}

fn ln_f64(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if x == 1.0 { return 0.0 }

    var m = x
    var e = 0
    while m >= 2.0 { m = m / 2.0; e = e + 1 }
    while m < 0.5 { m = m * 2.0; e = e - 1 }

    let t = (m - 1.0) / (m + 1.0)
    let t2 = t * t
    var sum = t
    var term = t
    var k = 1
    while k < 30 {
        term = term * t2
        sum = sum + term / ((2 * k + 1) as f64)
        k = k + 1
    }
    return 2.0 * sum + (e as f64) * 0.6931471805599453
}

fn cos_approx(x: f64) -> f64 {
    var a = x
    let twopi = 2.0 * pi_val()
    while a >= twopi { a = a - twopi }
    while a < 0.0 { a = a + twopi }
    if a > pi_val() { a = a - twopi }
    let a2 = a * a
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 15 {
        term = 0.0 - term * a2 / ((2 * n - 1) * 2 * n) as f64
        sum = sum + term
        n = n + 1
    }
    return sum
}

fn frac(x: f64) -> f64 {
    var v = x
    while v >= 1.0 { v = v - 1.0 }
    while v < 0.0 { v = v + 1.0 }
    return v
}

fn mcmc_normal_proposal(current: f64, step_size: f64, rng: &!RngState) -> f64 {
    var u1 = lcg_next(rng)
    if u1 < 1.0e-10 { u1 = 1.0e-10 }
    let u2 = lcg_next(rng)
    let z = sqrt_f64(0.0 - 2.0 * ln_f64(u1)) * cos_approx(2.0 * pi_val() * u2)
    return current + step_size * z
}

fn mcmc_chain_new() -> MCMCChain {
    return MCMCChain {
        samples: [0.0; 5000],
        n_stored: 0,
        n_accepted: 0,
        n_total: 0
    }
}

fn mcmc_store_sample(chain: &!MCMCChain, value: f64) {
    if chain.n_stored < 5000 {
        chain.samples[chain.n_stored] = value
        chain.n_stored = chain.n_stored + 1
    }
}

fn mcmc_chain_mean(chain: &MCMCChain) -> f64 {
    if chain.n_stored == 0 { return 0.0 }
    var sum: f64 = 0.0
    var i: i32 = 0
    while i < chain.n_stored {
        sum = sum + chain.samples[i]
        i = i + 1
    }
    return sum / (chain.n_stored as f64)
}

fn mcmc_chain_variance(chain: &MCMCChain) -> f64 {
    if chain.n_stored < 2 { return 0.0 }
    let mean = mcmc_chain_mean(chain)
    var sum_sq: f64 = 0.0
    var i: i32 = 0
    while i < chain.n_stored {
        let diff = chain.samples[i] - mean
        sum_sq = sum_sq + diff * diff
        i = i + 1
    }
    return sum_sq / ((chain.n_stored - 1) as f64)
}

fn mcmc_chain_std(chain: &MCMCChain) -> f64 {
    return sqrt_f64(mcmc_chain_variance(chain))
}

fn mcmc_autocorrelation(chain: &MCMCChain, lag: i32) -> f64 {
    if chain.n_stored < lag + 2 { return 0.0 }
    let mean = mcmc_chain_mean(chain)
    var cov: f64 = 0.0
    var var_sum: f64 = 0.0
    let n = chain.n_stored - lag
    var i: i32 = 0
    while i < n {
        let d1 = chain.samples[i] - mean
        let d2 = chain.samples[i + lag] - mean
        cov = cov + d1 * d2
        var_sum = var_sum + d1 * d1
        i = i + 1
    }
    if var_sum < 1.0e-30 { return 0.0 }
    return cov / var_sum
}

fn mcmc_effective_sample_size(chain: &MCMCChain) -> f64 {
    if chain.n_stored < 10 { return chain.n_stored as f64 }
    let n = chain.n_stored as f64

    var sum_rho: f64 = 0.0
    var max_check = chain.n_stored / 2
    if max_check > 100 { max_check = 100 }

    var lag: i32 = 1
    while lag < max_check {
        let rho = mcmc_autocorrelation(chain, lag)
        if rho < 0.05 {
            lag = max_check
        } else {
            sum_rho = sum_rho + rho
            lag = lag + 1
        }
    }

    let tau = 1.0 + 2.0 * sum_rho
    if tau < 1.0 { return n }
    return n / tau
}

fn normal_log_density(x: f64, mu: f64, sigma: f64) -> f64 {
    if sigma <= 0.0 { return 0.0 - 1.0e30 }
    let z = (x - mu) / sigma
    let log_2pi = 1.8378770664093453
    return 0.0 - 0.5 * log_2pi - ln_f64(sigma) - 0.5 * z * z
}

fn uniform_log_density(x: f64, lo: f64, hi: f64) -> f64 {
    if x < lo { return 0.0 - 1.0e30 }
    if x > hi { return 0.0 - 1.0e30 }
    if hi <= lo { return 0.0 - 1.0e30 }
    return 0.0 - ln_f64(hi - lo)
}

fn gamma_log_density(x: f64, alpha: f64, beta: f64) -> f64 {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if alpha <= 0.0 { return 0.0 - 1.0e30 }
    if beta <= 0.0 { return 0.0 - 1.0e30 }
    return alpha * ln_f64(beta) - lgamma_f64(alpha) + (alpha - 1.0) * ln_f64(x) - beta * x
}

fn sort_partial(arr: &![f64; 5000], n: i32) {
    // Insertion sort
    var i: i32 = 1
    while i < n {
        let key = arr[i]
        var j = i - 1
        while j >= 0 {
            if arr[j] > key {
                arr[j + 1] = arr[j]
                j = j - 1
            } else {
                j = 0 - 1
            }
        }
        arr[j + 1] = key
        i = i + 1
    }
}

fn compute_quantile(chain: &MCMCChain, q: f64) -> f64 {
    if chain.n_stored == 0 { return 0.0 }
    if chain.n_stored == 1 { return chain.samples[0] }

    var sorted: [f64; 5000] = [0.0; 5000]
    var i: i32 = 0
    while i < chain.n_stored {
        sorted[i] = chain.samples[i]
        i = i + 1
    }
    sort_partial(&!sorted, chain.n_stored)

    let pos = q * ((chain.n_stored - 1) as f64)
    var lo_idx = pos as i32
    if lo_idx < 0 { lo_idx = 0 }
    if lo_idx >= chain.n_stored - 1 { lo_idx = chain.n_stored - 2 }
    let hi_idx = lo_idx + 1
    let frac_val = pos - (lo_idx as f64)
    return sorted[lo_idx] * (1.0 - frac_val) + sorted[hi_idx] * frac_val
}

fn convergence_confidence(ess: f64, r_hat: f64) -> f64 {
    if ess >= 400.0 {
        if r_hat < 1.05 {
            let base = 0.95
            let bonus = min_f64(0.04, (ess - 400.0) / 10000.0)
            return base + bonus
        }
    }
    if ess >= 100.0 {
        if r_hat < 1.10 {
            let base = 0.80
            let bonus = min_f64(0.14, (ess - 100.0) / 3000.0)
            return base + bonus
        }
    }
    return max_f64(0.5, ess / 1000.0)
}

fn chain_to_knowledge(chain: &MCMCChain) -> BayesianKnowledge {
    let mean = mcmc_chain_mean(chain)
    let std_dev = mcmc_chain_std(chain)
    let ci = compute_credible_interval(chain, 0.95)
    let ess = mcmc_effective_sample_size(chain)
    let r_hat = mcmc_split_rhat(chain)
    let conf = convergence_confidence(ess, r_hat)
    return BayesianKnowledge {
        mean: mean,
        std_dev: std_dev,
        ci_lower: ci[0],
        ci_upper: ci[1],
        confidence: conf,
        n_effective: ess
    }
}

fn exp_approx(x: f64) -> f64 with Panic, Mut, Div {
    // Taylor series approximation of exp(x) with range reduction
    let ln2 = 0.6931471805599453
    var v = x
    if v > 700.0 { v = 700.0 }
    if v < 0.0 - 700.0 { return 0.0 }
    let k = (v / ln2) as i64
    let r = v - (k as f64) * ln2
    var result = 1.0
    var term = 1.0
    var i: i64 = 1
    while i <= 15 {
        term = term * r / (i as f64)
        result = result + term
        i = i + 1
    }
    if k >= 0 {
        var j: i64 = 0
        while j < k { result = result * 2.0; j = j + 1 }
    } else {
        var j: i64 = 0
        while j < 0 - k { result = result / 2.0; j = j + 1 }
    }
    result
}

