    eta: &EtaVec,
    n_theta: i64,
    n_eta: i64,
    out: &!ParamVec
) with Mut, Div, Panic {
    var i: i64 = 0
    while i < n_theta {
        if i < n_eta {
            out.data[i] = theta.data[i] * t_exp(eta.data[i])
        } else {
            out.data[i] = theta.data[i]
        }
        i = i + 1
    }
}

