                   approx_eq_f32(left.c, o.c, tol) && approx_eq_f32(left.d, o.d, tol) &&
                   approx_eq_f32(left.e, o.e, tol) && approx_eq_f32(left.f, o.f, tol) &&
                   approx_eq_f32(left.g, o.g, tol) && approx_eq_f32(left.h, o.h, tol)
    let ok_right = approx_eq_f32(right.a, o.a, tol) && approx_eq_f32(right.b, o.b, tol) &&
