                   approx_eq_f32(right.e, o.e, tol) && approx_eq_f32(right.f, o.f, tol) &&
                   approx_eq_f32(right.g, o.g, tol) && approx_eq_f32(right.h, o.h, tol)
    return ok_left && ok_right
}

fn cds(a: i64, b: i64, bits: i64) -> i64 with Mut, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let ahi = if a >= half { 1 } else { 0 }
    let bhi = if b >= half { 1 } else { 0 }
    let alo = a & (half - 1)
    let blo = b & (half - 1)
    if ahi == 0 && bhi == 0 { return cds(alo, blo, bits - 1) }
    if ahi == 0 && bhi == 1 { return cds(blo, alo, bits - 1) }
    if ahi == 1 && bhi == 0 {
        if blo == 0 { return cds(alo, blo, bits - 1) }
        return 0 - cds(alo, blo, bits - 1)
    }
    if blo == 0 { return 0 - cds(blo, alo, bits - 1) }
    cds(blo, alo, bits - 1)
}

fn clear8(arr: &![f64; 64]) with Mut {
    var k: i64 = 0
    while k < 8 { arr[k] = 0.0; k = k + 1 }
}

fn set_basis(arr: &![f64; 64], idx: i64) with Mut {
    var k: i64 = 0
    while k < 8 { arr[k] = 0.0; k = k + 1 }
    arr[idx] = 1.0
}

fn oct_mul_global() with Mut, Div {
    var k: i64 = 0
    while k < 8 { OC[k] = 0.0; k = k + 1 }
    var i: i64 = 0
    while i < 8 {
        var j: i64 = 0
        while j < 8 {
            let s = sigma(i, j)
            var tgt: i64 = 0
            if i == 0 { tgt = j }
            else if j == 0 { tgt = i }
            else { tgt = xor3(i, j) }
            var sf: f64 = 1.0
            if s < 0 { sf = 0.0 - 1.0 }
            let v = sf * OA[i]
            let w = v * OB[j]
            OC[tgt] = OC[tgt] + w
            j = j + 1
        }
        i = i + 1
    }
}

fn oct_norm_global_c() -> f64 with Mut {
    var s: f64 = 0.0
    var i: i64 = 0
    while i < 8 { let v = OC[i]; s = s + v * v; i = i + 1 }
    s
}

fn assoc_norm(ai: i64, bi: i64, ci: i64) -> f64 with Mut, Div {
    // (ea*eb)*ec
    set_oa_basis(ai)
    set_ob_basis(bi)
    oct_mul_global()
    // OC = ea*eb. Copy to OA for next multiply.
    var k: i64 = 0
    while k < 8 { OA[k] = OC[k]; k = k + 1 }
    set_ob_basis(ci)
    oct_mul_global()
    // OC = (ea*eb)*ec. Save in OE.
    k = 0
    while k < 8 { OE[k] = OC[k]; k = k + 1 }

    // ea*(eb*ec)
    set_oa_basis(bi)
    set_ob_basis(ci)
    oct_mul_global()
    // OC = eb*ec. Copy to OB.
    k = 0
    while k < 8 { OB[k] = OC[k]; k = k + 1 }
    set_oa_basis(ai)
    oct_mul_global()
    // OC = ea*(eb*ec) = rhs

    // |assoc|² = |OE - OC|²
    var norm: f64 = 0.0
    k = 0
    while k < 8 {
        let d = OE[k] - OC[k]
        norm = norm + d * d
        k = k + 1
    }
    norm
}

//@ run-pass
// Test: ODE bridge with user-defined RHS function
// Solves dy/dt = -y with y(0) = 1.0 using inline RK4
// Analytical solution: y(t) = exp(-t)
//
// Rewritten to avoid dynamic arrays and solve_ode builtin
// (lean_single only supports fixed-size arrays)

fn ode_abs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }

fn main() -> i64 with IO, Mut, Div, Panic {
    // RK4 for dy/dt = -y, y(0)=1.0, from t=0 to t=2.0 with dt=0.01
    // 200 steps
    let dt = 0.01
    var y = 1.0
    var t = 0.0
    var step = 0
    while step < 200 {
        // k1 = f(t, y) = -y
        let k1 = 0.0 - y
        // k2 = f(t + dt/2, y + dt/2 * k1)
        let k2 = 0.0 - (y + 0.5 * dt * k1)
        // k3 = f(t + dt/2, y + dt/2 * k2)
        let k3 = 0.0 - (y + 0.5 * dt * k2)
        // k4 = f(t + dt, y + dt * k3)
        let k4 = 0.0 - (y + dt * k3)
        y = y + (dt / 6.0) * (k1 + 2.0 * k2 + 2.0 * k3 + k4)
        t = t + dt
        step = step + 1
    }

    // y(2.0) should be exp(-2) ≈ 0.1353352832366127
    let expected = 0.1353352832366127
    let error = ode_abs(y - expected)

    // RK4 should be accurate to ~1e-8 with dt=0.01
    if error > 0.001 {
        println("FAIL: ODE bridge test failed")
        return 1
    }
    println("ODE bridge test passed: y(2) correct")
    return 0
}

fn og_sqrt(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 15 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn rk4_step_generic(
    rhs: fn(f64, &EState, &ODEParams, &!EState) -> (),
    t: f64, state: &!EState, p: &ODEParams, dt: f64
) with Mut, Div, Panic {
    let n = state.n
    var k1 = estate_new(n); var k2 = estate_new(n)
    var k3 = estate_new(n); var k4 = estate_new(n)
    var tmp = estate_new(n)

    rhs(t, state, p, &!k1)
    estate_axpy(&!tmp, state, 0.5 * dt, &k1)
    rhs(t + 0.5 * dt, &tmp, p, &!k2)
    estate_axpy(&!tmp, state, 0.5 * dt, &k2)
    rhs(t + 0.5 * dt, &tmp, p, &!k3)
    estate_axpy(&!tmp, state, dt, &k3)
    rhs(t + dt, &tmp, p, &!k4)

    var i = 0
    while i < n {
        if i < 64 {
            let dy = (k1.values[i] + 2.0 * k2.values[i] + 2.0 * k3.values[i] + k4.values[i]) / 6.0
            state.values[i] = state.values[i] + dt * dy
        }
        i = i + 1
    }
}

fn solve_generic(
    rhs: fn(f64, &EState, &ODEParams, &!EState) -> (),
    n_dims: i64, y0: EState, p: ODEParams,
    t_start: f64, t_end: f64, dt: f64, max_steps: i64
) -> EState with Mut, Div, Panic {
    var state = y0
    state.n = n_dims
    var t = t_start
    var step = 0
    while t < t_end && step < max_steps {
        let h = og_min(dt, t_end - t)
        if h <= 1.0e-15 { t = t_end }
        else {
            rk4_step_generic(rhs, t, &!state, &p, h)
            t = t + h
            step = step + 1
        }
    }
    state
}

fn rhs_decay(t: f64, y: &EState, p: &ODEParams, out: &!EState) with Mut, Div, Panic {
    let k = p.params[0]
    out.values[0] = (0.0 - k) * y.values[0]
    out.n = 1
}

fn exp_approx(x: f64) -> f64 with Mut, Panic, Div {
    // Taylor series for e^x, good for small |x|
    // Split large x: e^x = e^(x/2) * e^(x/2)
    if x > 10.0 {
        let half = exp_approx(x / 2.0)
        return half * half
    }
    if x < 0.0 - 10.0 { return 1.0 / exp_approx(0.0 - x) }
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 25 {
        term = term * x / (n as f64)
        sum = sum + term
        n = n + 1
    }
    return sum
}

fn sin_approx(x: f64) -> f64 with Mut, Panic, Div {
    let pi = 3.141592653589793
    let two_pi = 6.283185307179586
    var a = x
    // Range reduction
    if a > two_pi || a < 0.0 - two_pi {
        let n = (a / two_pi) as i32
        a = a - (n as f64) * two_pi
    }
    while a > pi { a = a - two_pi }
    while a < 0.0 - pi { a = a + two_pi }
    let a2 = a * a
    var sum = a
    var term = a
    var n = 1
    while n < 18 {
        term = 0.0 - term * a2 / ((2 * n) * (2 * n + 1)) as f64
        sum = sum + term
        n = n + 1
    }
    return sum
}

fn cos_approx(x: f64) -> f64 with Mut, Panic, Div {
    return sin_approx(x + 1.5707963267948966)
}

fn exp_decay_deriv(u: f64) -> f64 {
    return 0.0 - 0.1 * u
}

fn rk4_step_exp_decay(s: ScalarState, dt: f64) -> ScalarState {
    let k1 = exp_decay_deriv(s.u)
    let k2 = exp_decay_deriv(s.u + 0.5 * dt * k1)
    let k3 = exp_decay_deriv(s.u + 0.5 * dt * k2)
    let k4 = exp_decay_deriv(s.u + dt * k3)
    ScalarState {
        u: s.u + dt / 6.0 * (k1 + 2.0 * k2 + 2.0 * k3 + k4),
        t: s.t + dt,
    }
}

fn solve_exp_decay(u0: f64, t_end: f64, n_steps: i32) -> ScalarState with Mut, Panic, Div {
    let dt = t_end / (n_steps as f64)
    var s = ScalarState { u: u0, t: 0.0 }
    var i = 0
    while i < n_steps {
        s = rk4_step_exp_decay(s, dt)
        i = i + 1
    }
    return s
}

fn harmonic_deriv(x: f64, v: f64) -> HarmDerivs {
    HarmDerivs { dx: v, dv: 0.0 - x }
}

fn rk4_step_harmonic(s: Vec2State, dt: f64) -> Vec2State {
    let k1 = harmonic_deriv(s.x, s.y)
    let k2 = harmonic_deriv(s.x + 0.5 * dt * k1.dx, s.y + 0.5 * dt * k1.dv)
    let k3 = harmonic_deriv(s.x + 0.5 * dt * k2.dx, s.y + 0.5 * dt * k2.dv)
    let k4 = harmonic_deriv(s.x + dt * k3.dx, s.y + dt * k3.dv)
    Vec2State {
        x: s.x + dt / 6.0 * (k1.dx + 2.0 * k2.dx + 2.0 * k3.dx + k4.dx),
        y: s.y + dt / 6.0 * (k1.dv + 2.0 * k2.dv + 2.0 * k3.dv + k4.dv),
        t: s.t + dt,
    }
}

fn solve_harmonic(x0: f64, v0: f64, t_end: f64, n_steps: i32) -> Vec2State with Mut, Panic, Div {
    let dt = t_end / (n_steps as f64)
    var s = Vec2State { x: x0, y: v0, t: 0.0 }
    var i = 0
    while i < n_steps {
        s = rk4_step_harmonic(s, dt)
        i = i + 1
    }
    return s
}

fn logistic_deriv(u: f64) -> f64 {
    return 1.0 * u * (1.0 - u / 10.0)
}

fn rk4_step_logistic(s: ScalarState, dt: f64) -> ScalarState {
    let k1 = logistic_deriv(s.u)
    let k2 = logistic_deriv(s.u + 0.5 * dt * k1)
    let k3 = logistic_deriv(s.u + 0.5 * dt * k2)
    let k4 = logistic_deriv(s.u + dt * k3)
    ScalarState {
        u: s.u + dt / 6.0 * (k1 + 2.0 * k2 + 2.0 * k3 + k4),
        t: s.t + dt,
    }
}

fn solve_logistic(u0: f64, t_end: f64, n_steps: i32) -> ScalarState with Mut, Panic, Div {
    let dt = t_end / (n_steps as f64)
    var s = ScalarState { u: u0, t: 0.0 }
    var i = 0
    while i < n_steps {
        s = rk4_step_logistic(s, dt)
        i = i + 1
    }
    return s
}

fn logistic_exact(u0: f64, t: f64) -> f64 with Mut, Panic, Div {
    // u(t) = K / (1 + (K/u0 - 1)*exp(-r*t))
    let k = 10.0
    let r = 1.0
    let ratio = k / u0 - 1.0
    return k / (1.0 + ratio * exp_approx(0.0 - r * t))
}

fn stiff_decay_deriv(u: f64) -> f64 {
    return 0.0 - 50.0 * u
}

fn rk4_step_stiff(s: ScalarState, dt: f64) -> ScalarState {
    let k1 = stiff_decay_deriv(s.u)
    let k2 = stiff_decay_deriv(s.u + 0.5 * dt * k1)
    let k3 = stiff_decay_deriv(s.u + 0.5 * dt * k2)
    let k4 = stiff_decay_deriv(s.u + dt * k3)
    ScalarState {
        u: s.u + dt / 6.0 * (k1 + 2.0 * k2 + 2.0 * k3 + k4),
        t: s.t + dt,
    }
}

fn solve_stiff(u0: f64, t_end: f64, n_steps: i32) -> ScalarState with Mut, Panic, Div {
    let dt = t_end / (n_steps as f64)
    var s = ScalarState { u: u0, t: 0.0 }
    var i = 0
    while i < n_steps {
        s = rk4_step_stiff(s, dt)
        i = i + 1
    }
    return s
}

fn rk4_step_zero(s: ScalarState, dt: f64) -> ScalarState {
    // k1=k2=k3=k4=0, so u unchanged
    ScalarState { u: s.u, t: s.t + dt }
}

fn solve_zero(u0: f64, t_end: f64, n_steps: i32) -> ScalarState with Mut, Panic, Div {
    let dt = t_end / (n_steps as f64)
    var s = ScalarState { u: u0, t: 0.0 }
    var i = 0
    while i < n_steps {
        s = rk4_step_zero(s, dt)
        i = i + 1
    }
    return s
}

fn rk4_step_linear(s: ScalarState, dt: f64) -> ScalarState {
    // k1=k2=k3=k4=1, so u += dt
    ScalarState { u: s.u + dt, t: s.t + dt }
}

fn solve_linear(u0: f64, t_end: f64, n_steps: i32) -> ScalarState with Mut, Panic, Div {
    let dt = t_end / (n_steps as f64)
    var s = ScalarState { u: u0, t: 0.0 }
    var i = 0
    while i < n_steps {
        s = rk4_step_linear(s, dt)
        i = i + 1
    }
    return s
}

fn test_exp_decay_accuracy() -> bool with IO, Mut, Panic, Div {
    let result = solve_exp_decay(1.0, 10.0, 1000)
    let exact = exp_approx(0.0 - 1.0)  // exp(-0.1*10) = exp(-1)
    let err = abs_f64(result.u - exact)
    // RK4 with 1000 steps on this simple ODE should be very accurate
    return err < 1.0e-8
}

fn test_exp_decay_stability() -> bool with IO, Mut, Panic, Div {
    let result = solve_exp_decay(1.0, 10.0, 1000)
    return result.u > 0.0
}

fn test_exp_decay_convergence() -> bool with IO, Mut, Panic, Div {
    let exact = exp_approx(0.0 - 1.0)
    let r_coarse = solve_exp_decay(1.0, 10.0, 100)
    let r_fine = solve_exp_decay(1.0, 10.0, 200)
    let err_coarse = abs_f64(r_coarse.u - exact)
    let err_fine = abs_f64(r_fine.u - exact)
    // Finer should be more accurate
    return err_fine < err_coarse
}

