fn p3d_emit_scatter_data(data: &Scatter3D) with IO, Mut, Panic, Div {
    if data.n <= 0 { return }
    var x_min = data.x[0]
    var x_max = data.x[0]
    var y_min = data.y[0]
    var y_max = data.y[0]
    var z_min = data.z[0]
    var z_max = data.z[0]
    var i: i64 = 1
    while i < data.n {
        if data.x[i as usize] < x_min { x_min = data.x[i as usize] }
        if data.x[i as usize] > x_max { x_max = data.x[i as usize] }
        if data.y[i as usize] < y_min { y_min = data.y[i as usize] }
        if data.y[i as usize] > y_max { y_max = data.y[i as usize] }
        if data.z[i as usize] < z_min { z_min = data.z[i as usize] }
        if data.z[i as usize] > z_max { z_max = data.z[i as usize] }
        i = i + 1
    }
    let x_range = if x_max > x_min { x_max - x_min } else { 1.0 }
    let y_range = if y_max > y_min { y_max - y_min } else { 1.0 }
    let z_range = if z_max > z_min { z_max - z_min } else { 1.0 }
    println("const scatterPts = [")
    i = 0
    while i < data.n {
        let nx = (data.x[i as usize] - x_min) / x_range * 2.0 - 1.0
        let ny = (data.y[i as usize] - y_min) / y_range * 2.0 - 1.0
        let nz = (data.z[i as usize] - z_min) / z_range * 2.0 - 1.0
        print("  [")
        p3d_print_f64(nx, 4)
        print(",")
        p3d_print_f64(ny, 4)
        print(",")
        p3d_print_f64(nz, 4)
        print("]")
        if i < data.n - 1 { print(",") }
        println("")
        i = i + 1
    }
    println("];")
    print("const scatterColor = '")
    print(data.color)
    println("';")
    print("const scatterSize = ")
    p3d_print_f64(data.point_size, 1)
    println(";")
}

fn p3d_emit_surface_data(surf: &Surface3D) with IO, Mut, Panic, Div {
    if surf.nx <= 0 || surf.ny <= 0 { return }
    var z_min = surf.z_grid[0]
    var z_max = surf.z_grid[0]
    var idx: i64 = 1
    let total = surf.nx * surf.ny
    while idx < total {
        if idx < 4096 {
            if surf.z_grid[idx as usize] < z_min { z_min = surf.z_grid[idx as usize] }
            if surf.z_grid[idx as usize] > z_max { z_max = surf.z_grid[idx as usize] }
        }
        idx = idx + 1
    }
    let z_range = if z_max > z_min { z_max - z_min } else { 1.0 }
    print("const surfNX = ")
    p3d_print_int(surf.nx)
    print(", surfNY = ")
    p3d_print_int(surf.ny)
    println(";")
    println("const surfGrid = [")
    var iy: i64 = 0
    while iy < surf.ny {
        print("  [")
        var ix: i64 = 0
        while ix < surf.nx {
            let gi = iy * surf.nx + ix
            let nx = if surf.nx > 1 { ix as f64 / (surf.nx - 1) as f64 * 2.0 - 1.0 } else { 0.0 }
            let ny = if surf.ny > 1 { iy as f64 / (surf.ny - 1) as f64 * 2.0 - 1.0 } else { 0.0 }
            let nz = if gi < 4096 { (surf.z_grid[gi as usize] - z_min) / z_range * 2.0 - 1.0 } else { 0.0 }
            print("[")
            p3d_print_f64(nx, 4)
            print(",")
            p3d_print_f64(ny, 4)
            print(",")
            p3d_print_f64(nz, 4)
            print("]")
            if ix < surf.nx - 1 { print(",") }
            ix = ix + 1
        }
        print("]")
        if iy < surf.ny - 1 { print(",") }
        println("")
        iy = iy + 1
    }
    println("];")
}

fn poly_zero() -> Polynomial with Mut, Panic {
    var coeffs: [f64; 64] = [0.0; 64]
    Polynomial { coeffs: coeffs, degree: -1 }
}

fn poly_constant(c: f64) -> Polynomial with Mut, Panic {
    var coeffs: [f64; 64] = [0.0; 64]
    coeffs[0] = c
    let deg = if c == 0.0 { -1 } else { 0 }
    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_linear(a: f64, b: f64) -> Polynomial with Mut, Panic {
    var coeffs: [f64; 64] = [0.0; 64]
    coeffs[0] = b
    coeffs[1] = a
    let deg = if a != 0.0 { 1 } else { if b != 0.0 { 0 } else { -1 } }
    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_quadratic(a: f64, b: f64, c: f64) -> Polynomial with Mut, Panic {
    var coeffs: [f64; 64] = [0.0; 64]
    coeffs[0] = c
    coeffs[1] = b
    coeffs[2] = a
    let deg = if a != 0.0 { 2 } else { if b != 0.0 { 1 } else { if c != 0.0 { 0 } else { -1 } } }
    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_monomial(c: f64, n: i32) -> Polynomial with Mut, Panic {
    var coeffs: [f64; 64] = [0.0; 64]
    if n >= 0 && n < 64 {
        coeffs[n] = c
    }
    let deg = if c == 0.0 { -1 } else { n }
    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_eval(p: Polynomial, x: f64) -> f64 with Mut, Panic, Div {
    if p.degree < 0 {
        return 0.0
    }
    var result = p.coeffs[p.degree]
    var i = p.degree - 1
    while i >= 0 {
        result = result * x + p.coeffs[i]
        i = i - 1
    }
    return result
}

fn poly_coeff(p: Polynomial, i: i32) -> f64 with Panic {
    if i < 0 || i > p.degree {
        return 0.0
    }
    return p.coeffs[i]
}

fn poly_degree(p: Polynomial) -> i32 {
    return p.degree
}

fn poly_is_zero(p: Polynomial) -> bool {
    return p.degree < 0
}

fn poly_add(a: Polynomial, b: Polynomial) -> Polynomial with Mut, Panic, Div {
    let max_deg = if a.degree > b.degree { a.degree } else { b.degree }
    if max_deg < 0 {
        return poly_zero()
    }

    var coeffs: [f64; 64] = [0.0; 64]
    var i = 0
    while i <= max_deg {
        let ca = if i <= a.degree { a.coeffs[i] } else { 0.0 }
        let cb = if i <= b.degree { b.coeffs[i] } else { 0.0 }
        coeffs[i] = ca + cb
        i = i + 1
    }

    // Trim leading zeros
    var deg = max_deg
    while deg > 0 && coeffs[deg] == 0.0 {
        deg = deg - 1
    }
    if deg == 0 && coeffs[0] == 0.0 {
        deg = -1
    }

    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_sub(a: Polynomial, b: Polynomial) -> Polynomial with Mut, Panic, Div {
    let max_deg = if a.degree > b.degree { a.degree } else { b.degree }
    if max_deg < 0 {
        return poly_zero()
    }

    var coeffs: [f64; 64] = [0.0; 64]
    var i = 0
    while i <= max_deg {
        let ca = if i <= a.degree { a.coeffs[i] } else { 0.0 }
        let cb = if i <= b.degree { b.coeffs[i] } else { 0.0 }
        coeffs[i] = ca - cb
        i = i + 1
    }

    // Trim leading zeros
    var deg = max_deg
    while deg > 0 && coeffs[deg] == 0.0 {
        deg = deg - 1
    }
    if deg == 0 && coeffs[0] == 0.0 {
        deg = -1
    }

    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_mul(a: Polynomial, b: Polynomial) -> Polynomial with Mut, Panic, Div {
    if a.degree < 0 || b.degree < 0 {
        return poly_zero()
    }

    let result_deg = a.degree + b.degree
    let max_deg = if result_deg > 63 { 63 } else { result_deg }

    var coeffs: [f64; 64] = [0.0; 64]
    var i = 0
    while i <= a.degree {
        var j = 0
        while j <= b.degree {
            let k = i + j
            if k <= max_deg {
                coeffs[k] = coeffs[k] + a.coeffs[i] * b.coeffs[j]
            }
            j = j + 1
        }
        i = i + 1
    }

    // Trim leading zeros
    var deg = max_deg
    while deg > 0 && coeffs[deg] == 0.0 {
        deg = deg - 1
    }
    if deg == 0 && coeffs[0] == 0.0 {
        deg = -1
    }

    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_scale(p: Polynomial, c: f64) -> Polynomial with Mut, Panic, Div {
    if c == 0.0 || p.degree < 0 {
        return poly_zero()
    }

    var coeffs: [f64; 64] = [0.0; 64]
    var i = 0
    while i <= p.degree {
        coeffs[i] = p.coeffs[i] * c
        i = i + 1
    }

    Polynomial { coeffs: coeffs, degree: p.degree }
}

fn poly_neg(p: Polynomial) -> Polynomial with Mut, Panic, Div {
    return poly_scale(p, 0.0 - 1.0)
}

fn poly_derivative(p: Polynomial) -> Polynomial with Mut, Panic, Div {
    if p.degree <= 0 {
        return poly_zero()
    }

    let new_deg = p.degree - 1
    var coeffs: [f64; 64] = [0.0; 64]
    var i = 0
    while i <= new_deg {
        coeffs[i] = (i + 1) as f64 * p.coeffs[i + 1]
        i = i + 1
    }

    // Trim leading zeros
    var deg = new_deg
    while deg > 0 && coeffs[deg] == 0.0 {
        deg = deg - 1
    }
    if deg == 0 && coeffs[0] == 0.0 {
        deg = -1
    }

    Polynomial { coeffs: coeffs, degree: deg }
}

fn poly_integral(p: Polynomial, c: f64) -> Polynomial with Mut, Panic, Div {
    if p.degree < 0 {
        return poly_constant(c)
    }

    let new_deg = if p.degree < 63 { p.degree + 1 } else { 63 }
    var coeffs: [f64; 64] = [0.0; 64]
    coeffs[0] = c

    var i = 0
    while i <= p.degree && i < 63 {
        coeffs[i + 1] = p.coeffs[i] / ((i + 1) as f64)
        i = i + 1
    }

    Polynomial { coeffs: coeffs, degree: new_deg }
}

fn poly_roots_quadratic(a: f64, b: f64, c: f64) -> QuadraticRoots with Mut, Panic, Div {
    if a == 0.0 {
        if b == 0.0 {
            return QuadraticRoots { r1: 0.0, r2: 0.0, discriminant: 0.0, has_real_roots: false }
        }
        let r = 0.0 - c / b
        return QuadraticRoots { r1: r, r2: r, discriminant: 0.0, has_real_roots: true }
    }
    let disc = b * b - 4.0 * a * c
    if disc < 0.0 {
        return QuadraticRoots { r1: 0.0, r2: 0.0, discriminant: disc, has_real_roots: false }
    }
    let sqrt_disc = sqrt_f64(disc)
    let r1 = (0.0 - b + sqrt_disc) / (2.0 * a)
    let r2 = (0.0 - b - sqrt_disc) / (2.0 * a)
    QuadraticRoots { r1: r1, r2: r2, discriminant: disc, has_real_roots: true }
}

fn test_zero() -> bool with IO, Mut, Panic, Div {
    let z = poly_zero()
    let deg_ok = poly_degree(z) == -1
    let is_zero_ok = poly_is_zero(z)
    let eval_ok = approx_eq(poly_eval(z, 42.0), 0.0, 1.0e-12)
    return deg_ok && is_zero_ok && eval_ok
}

fn test_constant() -> bool with IO, Mut, Panic, Div {
    let c = poly_constant(5.0)
    let ok1 = approx_eq(poly_eval(c, 0.0), 5.0, 1.0e-12)
    let ok2 = approx_eq(poly_eval(c, 100.0), 5.0, 1.0e-12)
    let ok3 = approx_eq(poly_eval(c, 0.0 - 7.0), 5.0, 1.0e-12)
    let ok4 = poly_degree(c) == 0
    return ok1 && ok2 && ok3 && ok4
}

