fn trapezoid(a: f64, b: f64, n: i32, f: fn(f64) -> f64) -> f64 with Mut, Panic, Div {
    let h = (b - a) / (n as f64)
    var sum = 0.5 * (f(a) + f(b))
    var i: i32 = 1
    while i < n {
        let x = a + (i as f64) * h
        sum = sum + f(x)
        i = i + 1
    }
    return sum * h
}

fn simpson(a: f64, b: f64, n: i32, f: fn(f64) -> f64) -> f64 with Mut, Panic, Div {
    var nn = n
    if nn < 2 { nn = 2 }
    let rem = nn - 2 * (nn / 2)
    if rem != 0 { nn = nn + 1 }

    let h = (b - a) / (nn as f64)
    var sum = f(a) + f(b)

    var i: i32 = 1
    while i < nn {
        let x = a + (i as f64) * h
        let rem_i = i - 2 * (i / 2)
        if rem_i != 0 {
            sum = sum + 4.0 * f(x)
        } else {
            sum = sum + 2.0 * f(x)
        }
        i = i + 1
    }
    return sum * h / 3.0
}

fn simpson38(a: f64, b: f64, n: i32, f: fn(f64) -> f64) -> f64 with Mut, Panic, Div {
    var nn = n
    if nn < 3 { nn = 3 }
    let r = nn - 3 * (nn / 3)
    if r != 0 { nn = nn + (3 - r) }

    let h = (b - a) / (nn as f64)
    var sum = f(a) + f(b)

    var i: i32 = 1
    while i < nn {
        let x = a + (i as f64) * h
        let r3 = i - 3 * (i / 3)
        if r3 == 0 {
            sum = sum + 2.0 * f(x)
        } else {
            sum = sum + 3.0 * f(x)
        }
        i = i + 1
    }
    return sum * 3.0 * h / 8.0
}

fn midpoint(a: f64, b: f64, n: i32, f: fn(f64) -> f64) -> f64 with Mut, Panic, Div {
    let h = (b - a) / (n as f64)
