fn test_matmul_identity() -> bool with Mut, Panic {
    // I = 2x2 identity
    var eye: [f64; 4096] = [0.0; 4096]
    eye[0] = 1.0   // (0,0)
    eye[3] = 1.0   // (1,1)

    // B = [[1,2],[3,4]]
    var b_mat: [f64; 4096] = [0.0; 4096]
    b_mat[0] = 1.0
    b_mat[1] = 2.0
    b_mat[2] = 3.0
    b_mat[3] = 4.0

    var c_mat: [f64; 4096] = [0.0; 4096]
    slop_matmul(&eye, &b_mat, &!c_mat, 2, 2, 2)

    let ok0 = approx_eq(c_mat[0], 1.0, 1.0e-10)
    let ok1 = approx_eq(c_mat[1], 2.0, 1.0e-10)
    let ok2 = approx_eq(c_mat[2], 3.0, 1.0e-10)
    let ok3 = approx_eq(c_mat[3], 4.0, 1.0e-10)
    ok0 && ok1 && ok2 && ok3
}

fn test_matvec_identity() -> bool with Mut, Panic {
    var eye: [f64; 4096] = [0.0; 4096]
    eye[0] = 1.0   // (0,0)
    eye[3] = 1.0   // (1,1)

    var x: [f64; 64] = [0.0; 64]
    x[0] = 5.0
    x[1] = 7.0

    var out: [f64; 64] = [0.0; 64]
    slop_matvec(&eye, &x, &!out, 2, 2)

    let ok0 = approx_eq(out[0], 5.0, 1.0e-10)
    let ok1 = approx_eq(out[1], 7.0, 1.0e-10)
    ok0 && ok1
}

fn test_transpose() -> bool with Mut, Panic {
    // A = 2x3: [[1,2,3],[4,5,6]]
    var a_mat: [f64; 4096] = [0.0; 4096]
    a_mat[0] = 1.0
    a_mat[1] = 2.0
    a_mat[2] = 3.0
    a_mat[3] = 4.0
    a_mat[4] = 5.0
    a_mat[5] = 6.0

    var b_mat: [f64; 4096] = [0.0; 4096]
    slop_transpose(&a_mat, &!b_mat, 2, 3)

    // Expected B = 3x2: [[1,4],[2,5],[3,6]]
    // Row 0: b[0]=1, b[1]=4
    // Row 1: b[2]=2, b[3]=5
    // Row 2: b[4]=3, b[5]=6
    let ok0 = approx_eq(b_mat[0], 1.0, 1.0e-10)
    let ok1 = approx_eq(b_mat[1], 4.0, 1.0e-10)
    let ok2 = approx_eq(b_mat[2], 2.0, 1.0e-10)
    let ok3 = approx_eq(b_mat[3], 5.0, 1.0e-10)
    let ok4 = approx_eq(b_mat[4], 3.0, 1.0e-10)
    let ok5 = approx_eq(b_mat[5], 6.0, 1.0e-10)
    ok0 && ok1 && ok2 && ok3 && ok4 && ok5
}

fn reverse_bits(n: i64) -> f64 {
    var result: f64 = 0.0
    var v = n
    var b: f64 = 0.5
    while v > 0 {
        if (v % 2) == 1 {
            result = result + b
        }
        v = v / 2
        b = b / 2.0
    }
    return result
}

fn saltelli_dim_prime(d: i32) -> i64 {
    if d == 0 { return 2 }
    if d == 1 { return 3 }
    if d == 2 { return 5 }
    if d == 3 { return 7 }
    if d == 4 { return 11 }
    if d == 5 { return 13 }
    if d == 6 { return 17 }
    if d == 7 { return 19 }
    if d == 8 { return 23 }
    return 29
}

fn saltelli_generate(n_samples: i32, n_dims: i32, seed: i64) -> SaltelliSamples {
    var result = SaltelliSamples {
        matrix_a: [0.0; 5000],
        matrix_b: [0.0; 5000],
        n_samples: n_samples,
        n_dims: n_dims,
    }

    var actual_samples = n_samples
    if n_dims > 0 {
        let max_rows = 5000 / n_dims
        if actual_samples > max_rows {
            actual_samples = max_rows
        }
    }
    result.n_samples = actual_samples

    var i: i32 = 0
    while i < actual_samples {
        let base_idx: i64 = (i as i64) + 1 + seed
        var d: i32 = 0
        while d < n_dims {
            let dim_mult = saltelli_dim_prime(d)
            let idx_a: i64 = base_idx * dim_mult + (d as i64)
            let idx_b: i64 = base_idx * dim_mult + (d as i64) + (actual_samples as i64) * 7 + 131

            let flat = i * n_dims + d
            result.matrix_a[flat] = reverse_bits(idx_a)
            result.matrix_b[flat] = reverse_bits(idx_b)

            d = d + 1
        }
        i = i + 1
    }

    return result
}

fn saltelli_build_ci(samples: &SaltelliSamples, dim_i: i32) -> [f64; 5000] {
    var ci: [f64; 5000] = [0.0; 5000]
    var i: i32 = 0
    while i < samples.n_samples {
        var d: i32 = 0
        while d < samples.n_dims {
            let flat = i * samples.n_dims + d
            if d == dim_i {
                ci[flat] = samples.matrix_b[flat]
            } else {
                ci[flat] = samples.matrix_a[flat]
            }
            d = d + 1
        }
        i = i + 1
    }
    return ci
}

fn saltelli_build_cij(samples: &SaltelliSamples, dim_i: i32, dim_j: i32) -> [f64; 5000] {
    var cij: [f64; 5000] = [0.0; 5000]
    var r: i32 = 0
    while r < samples.n_samples {
        var d: i32 = 0
        while d < samples.n_dims {
            let flat = r * samples.n_dims + d
            if d == dim_i || d == dim_j {
                cij[flat] = samples.matrix_b[flat]
            } else {
                cij[flat] = samples.matrix_a[flat]
            }
            d = d + 1
        }
        r = r + 1
    }
    return cij
}

fn saltelli_eval_row(matrix: &[f64; 5000], row: i32, n_dims: i32, model: fn([f64; 10]) -> f64) -> f64 {
    var input: [f64; 10] = [0.0; 10]
    var d: i32 = 0
    while d < n_dims {
        if d < 10 {
            input[d] = matrix[row * n_dims + d]
        }
        d = d + 1
    }
    return model(input)
}

fn saltelli_first_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_b: &[f64; 1000],
    model_outputs_ci: &[f64; 1000]
) -> f64 {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_all: f64 = 0.0
    var sum_sq_all: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_all = sum_all + model_outputs_a[k] + model_outputs_b[k]
        sum_sq_all = sum_sq_all + model_outputs_a[k] * model_outputs_a[k]
                                + model_outputs_b[k] * model_outputs_b[k]
        k = k + 1
    }
    let mean_y = sum_all / (2.0 * nf)
    let var_y = sum_sq_all / (2.0 * nf) - mean_y * mean_y
    if var_y < 1.0e-15 { return 0.0 }

    var numerator: f64 = 0.0
    k = 0
    while k < n {
        numerator = numerator + model_outputs_b[k] * (model_outputs_ci[k] - model_outputs_a[k])
        k = k + 1
    }
    numerator = numerator / nf
    let si = numerator / var_y
    return max_f64(0.0, min_f64(1.0, si))
}

fn saltelli_total_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_ci: &[f64; 1000]
) -> f64 {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_a: f64 = 0.0
    var sum_sq_a: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_a = sum_a + model_outputs_a[k]
        sum_sq_a = sum_sq_a + model_outputs_a[k] * model_outputs_a[k]
        k = k + 1
    }
    let mean_a = sum_a / nf
    let var_y = sum_sq_a / nf - mean_a * mean_a
    if var_y < 1.0e-15 { return 0.0 }

    var numerator: f64 = 0.0
    k = 0
    while k < n {
        let diff = model_outputs_a[k] - model_outputs_ci[k]
        numerator = numerator + diff * diff
        k = k + 1
    }
    numerator = numerator / (2.0 * nf)
    let sti = numerator / var_y
    return max_f64(0.0, min_f64(1.0, sti))
}

fn saltelli_second_order(
    samples: &SaltelliSamples,
    model_outputs_a: &[f64; 1000],
    model_outputs_b: &[f64; 1000],
    model_outputs_ci: &[f64; 1000],
    model_outputs_cj: &[f64; 1000],
    model_outputs_cij: &[f64; 1000],
    s_i: f64,
    s_j: f64
) -> f64 {
    let n = samples.n_samples
    if n < 2 { return 0.0 }
    let nf = n as f64

    var sum_all: f64 = 0.0
    var sum_sq_all: f64 = 0.0
    var k: i32 = 0
    while k < n {
        sum_all = sum_all + model_outputs_a[k] + model_outputs_b[k]
        sum_sq_all = sum_sq_all + model_outputs_a[k] * model_outputs_a[k]
                                + model_outputs_b[k] * model_outputs_b[k]
        k = k + 1
    }
    let mean_y = sum_all / (2.0 * nf)
    let var_y = sum_sq_all / (2.0 * nf) - mean_y * mean_y
    if var_y < 1.0e-15 { return 0.0 }

    var numerator_ij: f64 = 0.0
    k = 0
    while k < n {
        numerator_ij = numerator_ij + model_outputs_b[k] * (model_outputs_cij[k] - model_outputs_a[k])
        k = k + 1
    }
    let s_ij_closed = (numerator_ij / nf) / var_y
    let s_ij = s_ij_closed - s_i - s_j
    return max_f64(-0.05, min_f64(1.0, s_ij))
}

fn saltelli_expected_evals(n_samples: i32, n_dims: i32) -> i32 {
    let base = n_samples * (n_dims + 2)
    let n_pairs = n_dims * (n_dims - 1) / 2
    let second = n_samples * n_pairs
    return base + second
}

fn linear_model(x: [f64; 10]) -> f64 {
    return 2.0 * x[0] + x[1]
}

fn test_linear_model() -> bool {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 2, 42)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    // Evaluate on A and B
    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 2, linear_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 2, linear_model)
        k = k + 1
    }

    // C_0: A with column 0 from B
    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 2, linear_model)
        k = k + 1
    }

    // C_1: A with column 1 from B
    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 2, linear_model)
        k = k + 1
    }

    // C_01: A with columns 0 and 1 from B (= B itself for 2D)
    let c01 = saltelli_build_cij(&samples, 0, 1)
    var out_c01: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c01[k] = saltelli_eval_row(&c01, k, 2, linear_model)
        k = k + 1
    }

    // Compute indices
    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)

    let s12 = saltelli_second_order(
        &samples, &out_a, &out_b, &out_c0, &out_c1, &out_c01, s1, s2
    )

    // Check S1 ~ 0.8 within 15% tolerance
    let tol: f64 = 0.15
    var ok = true

    if abs_f64(s1 - 0.8) > tol { ok = false }
    if abs_f64(s2 - 0.2) > tol { ok = false }

    // Total order should approximately equal first order for linear model
    if abs_f64(st1 - 0.8) > tol { ok = false }
    if abs_f64(st2 - 0.2) > tol { ok = false }

    // Interaction should be near zero
    if abs_f64(s12) > 0.1 { ok = false }

    return ok
}

fn interaction_model(x: [f64; 10]) -> f64 {
    return x[0] * x[1]
}

fn test_interaction_model() -> bool {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 2, 137)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 2, interaction_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 2, interaction_model)
        k = k + 1
    }

    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 2, interaction_model)
        k = k + 1
    }

    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 2, interaction_model)
        k = k + 1
    }

    let c01 = saltelli_build_cij(&samples, 0, 1)
    var out_c01: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c01[k] = saltelli_eval_row(&c01, k, 2, interaction_model)
        k = k + 1
    }

    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)

    let s12 = saltelli_second_order(
        &samples, &out_a, &out_b, &out_c0, &out_c1, &out_c01, s1, s2
    )

    // Analytical: S1 = S2 = 3/7 ~ 0.4286
    let tol: f64 = 0.15
    var ok = true

    // First-order indices should be moderate (not zero)
    if s1 < 0.15 { ok = false }
    if s2 < 0.15 { ok = false }

    // Total-order should be larger than first-order (interactions present)
    if st1 < s1 - 0.05 { ok = false }
    if st2 < s2 - 0.05 { ok = false }

    // Second-order interaction should be positive (some interaction variance)
    // Analytical S12 = 1/7 ~ 0.143
    // Allow wide tolerance due to quasi-random noise
    if s12 < -0.05 { ok = false }

    return ok
}

fn ishigami_model(x: [f64; 10]) -> f64 {
    // Map [0,1] -> [-pi, pi]
    let pi = 3.14159265358979323846
    let x1 = x[0] * 2.0 * pi - pi
    let x2 = x[1] * 2.0 * pi - pi
    let x3 = x[2] * 2.0 * pi - pi

    let sin_x1 = sin(x1)
    let sin_x2 = sin(x2)
    let x3_4 = x3 * x3 * x3 * x3

    return sin_x1 + 7.0 * sin_x2 * sin_x2 + 0.1 * x3_4 * sin_x1
}

fn test_ishigami() -> bool {
    let n_samples: i32 = 800
    let samples = saltelli_generate(n_samples, 3, 271)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    // Evaluate on A and B
    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 3, ishigami_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 3, ishigami_model)
        k = k + 1
    }

    // Build C_i outputs for each dimension
    let c0 = saltelli_build_ci(&samples, 0)
    var out_c0: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 3, ishigami_model)
        k = k + 1
    }

    let c1 = saltelli_build_ci(&samples, 1)
    var out_c1: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c1[k] = saltelli_eval_row(&c1, k, 3, ishigami_model)
        k = k + 1
    }

    let c2 = saltelli_build_ci(&samples, 2)
    var out_c2: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c2[k] = saltelli_eval_row(&c2, k, 3, ishigami_model)
        k = k + 1
    }

    // First-order indices
    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let s3 = saltelli_first_order(&samples, &out_a, &out_b, &out_c2)

    // Total-order indices
    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)
    let st3 = saltelli_total_order(&samples, &out_a, &out_c2)

    // Validate with 15% tolerance (Monte Carlo variance)
    let tol: f64 = 0.15
    var ok = true

    // S1 ~ 0.314: x1 has moderate first-order influence
    if abs_f64(s1 - 0.314) > tol { ok = false }

    // S2 ~ 0.442: x2 has the largest first-order influence
    if abs_f64(s2 - 0.442) > tol { ok = false }

    // S3 ~ 0.0: x3 has negligible first-order effect
    if s3 > 0.15 { ok = false }

    // S_T1 ~ 0.558: x1 has large total effect (via interaction with x3)
    if abs_f64(st1 - 0.558) > tol { ok = false }

    // S_T2 ~ 0.442: x2 total = first (no interactions)
    if abs_f64(st2 - 0.442) > tol { ok = false }

    // S_T3 ~ 0.244: x3 only acts through interaction with x1
    if abs_f64(st3 - 0.244) > tol { ok = false }

    return ok
}

fn test_n2d2_efficiency() -> bool {
    let n: i32 = 100
    let d: i32 = 3

    // Expected: N * (d + 2) + N * d*(d-1)/2 = 100*5 + 100*3 = 800
    let expected = saltelli_expected_evals(n, d)

    // N(2d+2) = 100 * 8 = 800
    let canonical = n * (2 * d + 2)

    // For d=3, the exact formula and the N(2d+2) approximation match exactly
    if expected != canonical { return false }

    // Also check d=2: N*(2+2) + N*1 = 5N; N(2*2+2) = 6N
    // These differ because N(2d+2) is an approximation
    let expected_2d = saltelli_expected_evals(n, 2)
    let exact_2d = n * (2 + 2) + n * 1  // = 500
    if expected_2d != exact_2d { return false }

    // Check d=1: N*(1+2) + N*0 = 3N
    let expected_1d = saltelli_expected_evals(n, 1)
    if expected_1d != n * 3 { return false }

    return true
}

fn test_matrix_construction() -> bool {
    // Small test: 3 samples, 3 dims
    let samples = saltelli_generate(3, 3, 99)

    // Build C_1: should equal A everywhere except column 1
    let c1 = saltelli_build_ci(&samples, 1)

    var ok = true
    var i: i32 = 0
    while i < 3 {
        var d: i32 = 0
        while d < 3 {
            let flat = i * 3 + d
            if d == 1 {
                // Column 1 should come from B
                if abs_f64(c1[flat] - samples.matrix_b[flat]) > 1.0e-12 { ok = false }
            } else {
                // Other columns should come from A
                if abs_f64(c1[flat] - samples.matrix_a[flat]) > 1.0e-12 { ok = false }
            }
            d = d + 1
        }
        i = i + 1
    }

    // Build C_02: should equal A everywhere except columns 0 and 2
    let c02 = saltelli_build_cij(&samples, 0, 2)

    i = 0
    while i < 3 {
        var d: i32 = 0
        while d < 3 {
            let flat = i * 3 + d
            if d == 0 || d == 2 {
                if abs_f64(c02[flat] - samples.matrix_b[flat]) > 1.0e-12 { ok = false }
            } else {
                if abs_f64(c02[flat] - samples.matrix_a[flat]) > 1.0e-12 { ok = false }
            }
            d = d + 1
        }
        i = i + 1
    }

    return ok
}

fn test_sample_range() -> bool {
    let samples = saltelli_generate(100, 4, 7)

    var ok = true
    var i: i32 = 0
    while i < 100 {
        var d: i32 = 0
        while d < 4 {
            let flat = i * 4 + d
            if samples.matrix_a[flat] < 0.0 || samples.matrix_a[flat] > 1.0 { ok = false }
            if samples.matrix_b[flat] < 0.0 || samples.matrix_b[flat] > 1.0 { ok = false }
            d = d + 1
        }
        i = i + 1
    }

    return ok
}

fn additive_model(x: [f64; 10]) -> f64 {
    return x[0] + 2.0 * x[1] + 3.0 * x[2]
}

fn test_additive_model() -> bool {
    let n_samples: i32 = 512
    let samples = saltelli_generate(n_samples, 3, 53)

    var n_eval = n_samples
    if n_eval > 1000 { n_eval = 1000 }

    var out_a: [f64; 1000] = [0.0; 1000]
    var out_b: [f64; 1000] = [0.0; 1000]
    var k: i32 = 0
    while k < n_eval {
        out_a[k] = saltelli_eval_row(&samples.matrix_a, k, 3, additive_model)
        out_b[k] = saltelli_eval_row(&samples.matrix_b, k, 3, additive_model)
        k = k + 1
    }

    // C_i for each dimension
    let c0 = saltelli_build_ci(&samples, 0)
    let c1 = saltelli_build_ci(&samples, 1)
    let c2 = saltelli_build_ci(&samples, 2)

    var out_c0: [f64; 1000] = [0.0; 1000]
    var out_c1: [f64; 1000] = [0.0; 1000]
    var out_c2: [f64; 1000] = [0.0; 1000]
    k = 0
    while k < n_eval {
        out_c0[k] = saltelli_eval_row(&c0, k, 3, additive_model)
        out_c1[k] = saltelli_eval_row(&c1, k, 3, additive_model)
        out_c2[k] = saltelli_eval_row(&c2, k, 3, additive_model)
        k = k + 1
    }

    let s1 = saltelli_first_order(&samples, &out_a, &out_b, &out_c0)
    let s2 = saltelli_first_order(&samples, &out_a, &out_b, &out_c1)
    let s3 = saltelli_first_order(&samples, &out_a, &out_b, &out_c2)

    let st1 = saltelli_total_order(&samples, &out_a, &out_c0)
    let st2 = saltelli_total_order(&samples, &out_a, &out_c1)
    let st3 = saltelli_total_order(&samples, &out_a, &out_c2)

    let tol: f64 = 0.15
    var ok = true

    // S1 ~ 1/14 ~ 0.071
    if abs_f64(s1 - 0.071) > tol { ok = false }

    // S2 ~ 4/14 ~ 0.286
    if abs_f64(s2 - 0.286) > tol { ok = false }

    // S3 ~ 9/14 ~ 0.643
    if abs_f64(s3 - 0.643) > tol { ok = false }

    // For an additive model, total order should equal first order
    if abs_f64(st1 - s1) > 0.1 { ok = false }
    if abs_f64(st2 - s2) > 0.1 { ok = false }
    if abs_f64(st3 - s3) > 0.1 { ok = false }

    // Sum of first-order indices should be close to 1 (no interactions)
    let s_sum = s1 + s2 + s3
    if abs_f64(s_sum - 1.0) > 0.2 { ok = false }

    return ok
}

fn vec_dot(a: [f64; 128], b: [f64; 128], n: i32) -> f64 with Mut, Panic, Div {
    var sum = 0.0
    var i = 0
    while i < n {
        sum = sum + a[i] * b[i]
        i = i + 1
    }
    return sum
}

fn vec_copy(src: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var dst: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        dst[i] = src[i]
        i = i + 1
    }
    return dst
}

fn vec_sub(a: [f64; 128], b: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var result: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        result[i] = a[i] - b[i]
        i = i + 1
    }
    return result
}

fn vec_norm(x: [f64; 128], n: i32) -> f64 with Mut, Panic, Div {
    var sum = 0.0
    var i = 0
    while i < n {
        sum = sum + x[i] * x[i]
        i = i + 1
    }
    return sqrt_f64(sum)
}

fn sparse_new(nrows: i32, ncols: i32) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: nrows,
        ncols: ncols,
        nnz: 0
    }
    var i = 0
    while i <= nrows {
        result.row_ptr[i] = 0
        i = i + 1
    }
    return result
}

fn sparse_from_triplets(
    rows: [i32; 1024],
    cols: [i32; 1024],
    vals: [f64; 1024],
    count: i32,
    nrows: i32,
    ncols: i32
) -> SparseCSR with Mut, Panic, Div {
    var s_rows: [i32; 1024] = rows
    var s_cols: [i32; 1024] = cols
    var s_vals: [f64; 1024] = vals

    // Insertion sort by (row, col)
    var i = 1
    while i < count {
        let r = s_rows[i]
        let c = s_cols[i]
        let v = s_vals[i]
        var j = i - 1
        var done = false
        while j >= 0 && !done {
            let should_shift = s_rows[j] > r || (s_rows[j] == r && s_cols[j] > c)
            if should_shift {
                s_rows[j + 1] = s_rows[j]
                s_cols[j + 1] = s_cols[j]
                s_vals[j + 1] = s_vals[j]
                j = j - 1
            } else {
                done = true
            }
        }
        s_rows[j + 1] = r
        s_cols[j + 1] = c
        s_vals[j + 1] = v
        i = i + 1
    }

    // Merge duplicates
    var m_rows: [i32; 1024] = [0; 1024]
    var m_cols: [i32; 1024] = [0; 1024]
    var m_vals: [f64; 1024] = [0.0; 1024]
    var m_count = 0

    if count > 0 {
        m_rows[0] = s_rows[0]
        m_cols[0] = s_cols[0]
        m_vals[0] = s_vals[0]
        m_count = 1

        i = 1
        while i < count {
            if s_rows[i] == m_rows[m_count - 1] && s_cols[i] == m_cols[m_count - 1] {
                m_vals[m_count - 1] = m_vals[m_count - 1] + s_vals[i]
            } else {
                m_rows[m_count] = s_rows[i]
                m_cols[m_count] = s_cols[i]
                m_vals[m_count] = s_vals[i]
                m_count = m_count + 1
            }
            i = i + 1
        }
    }

    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: nrows,
        ncols: ncols,
        nnz: m_count
    }

    var row_count: [i32; 129] = [0; 129]
    i = 0
    while i < m_count {
        row_count[m_rows[i]] = row_count[m_rows[i]] + 1
        i = i + 1
    }

    result.row_ptr[0] = 0
    i = 0
    while i < nrows {
        result.row_ptr[i + 1] = result.row_ptr[i] + row_count[i]
        i = i + 1
    }

    i = 0
    while i < m_count {
        result.values[i] = m_vals[i]
        result.col_idx[i] = m_cols[i]
        i = i + 1
    }

    return result
}

fn sparse_identity(n: i32) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: n,
        ncols: n,
        nnz: n
    }
    var i = 0
    while i < n {
        result.values[i] = 1.0
        result.col_idx[i] = i
        result.row_ptr[i] = i
        i = i + 1
    }
    result.row_ptr[n] = n
    return result
}

fn sparse_diagonal(diag: [f64; 128], n: i32) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: n,
        ncols: n,
        nnz: n
    }
    var i = 0
    while i < n {
        result.values[i] = diag[i]
        result.col_idx[i] = i
        result.row_ptr[i] = i
        i = i + 1
    }
    result.row_ptr[n] = n
    return result
}

fn sparse_tridiagonal(
    lower: [f64; 128],
    main: [f64; 128],
    upper: [f64; 128],
    n: i32
) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: n,
        ncols: n,
        nnz: 0
    }

    var pos = 0

    // Row 0
    result.row_ptr[0] = 0
    if n >= 1 {
        result.values[pos] = main[0]
        result.col_idx[pos] = 0
        pos = pos + 1
        if n > 1 {
            result.values[pos] = upper[0]
            result.col_idx[pos] = 1
            pos = pos + 1
        }
    }

    // Middle rows
    var i = 1
    while i < n - 1 {
        result.row_ptr[i] = pos
        result.values[pos] = lower[i - 1]
        result.col_idx[pos] = i - 1
        pos = pos + 1
        result.values[pos] = main[i]
        result.col_idx[pos] = i
        pos = pos + 1
        result.values[pos] = upper[i]
        result.col_idx[pos] = i + 1
        pos = pos + 1
        i = i + 1
    }

    // Last row
    if n > 1 {
        result.row_ptr[n - 1] = pos
        result.values[pos] = lower[n - 2]
        result.col_idx[pos] = n - 2
        pos = pos + 1
        result.values[pos] = main[n - 1]
        result.col_idx[pos] = n - 1
        pos = pos + 1
    }

    result.row_ptr[n] = pos
    result.nnz = pos

    return result
}

fn sparse_get(a: SparseCSR, i: i32, j: i32) -> f64 with Mut, Panic, Div {
    let row_start = a.row_ptr[i]
    let row_end = a.row_ptr[i + 1]
    var k = row_start
    while k < row_end {
        if a.col_idx[k] == j {
            return a.values[k]
        }
        k = k + 1
    }
    return 0.0
}

fn sparse_nnz(a: SparseCSR) -> i32 {
    return a.nnz
}

fn sparse_row_nnz(a: SparseCSR, row: i32) -> i32 with Panic {
    return a.row_ptr[row + 1] - a.row_ptr[row]
}

fn sparse_matvec(a: SparseCSR, x: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var y: [f64; 128] = [0.0; 128]
    var i = 0
    while i < a.nrows {
        var sum = 0.0
        var k = a.row_ptr[i]
        let row_end = a.row_ptr[i + 1]
        while k < row_end {
            let col = a.col_idx[k]
            sum = sum + a.values[k] * x[col]
            k = k + 1
        }
        y[i] = sum
        i = i + 1
    }
    return y
}

fn sparse_matvec_add(
    a: SparseCSR,
    x: [f64; 128],
    y: [f64; 128],
    alpha: f64,
    beta: f64,
    n: i32
) -> [f64; 128] with Mut, Panic, Div {
    var result: [f64; 128] = [0.0; 128]
    var i = 0
    while i < a.nrows {
        var sum = 0.0
        var k = a.row_ptr[i]
        let row_end = a.row_ptr[i + 1]
        while k < row_end {
            let col = a.col_idx[k]
            sum = sum + a.values[k] * x[col]
            k = k + 1
        }
        result[i] = alpha * sum + beta * y[i]
        i = i + 1
    }
    return result
}

fn sparse_add(a: SparseCSR, b: SparseCSR) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: a.nrows,
        ncols: a.ncols,
        nnz: 0
    }

    var pos = 0
    var i = 0
    while i < a.nrows {
        result.row_ptr[i] = pos

        var ka = a.row_ptr[i]
        let ka_end = a.row_ptr[i + 1]
        var kb = b.row_ptr[i]
        let kb_end = b.row_ptr[i + 1]

        while ka < ka_end && kb < kb_end {
            if a.col_idx[ka] < b.col_idx[kb] {
                result.values[pos] = a.values[ka]
                result.col_idx[pos] = a.col_idx[ka]
                pos = pos + 1
                ka = ka + 1
            } else if a.col_idx[ka] > b.col_idx[kb] {
                result.values[pos] = b.values[kb]
                result.col_idx[pos] = b.col_idx[kb]
                pos = pos + 1
                kb = kb + 1
            } else {
                let sum = a.values[ka] + b.values[kb]
                if abs_f64(sum) > 1e-30 {
                    result.values[pos] = sum
                    result.col_idx[pos] = a.col_idx[ka]
                    pos = pos + 1
                }
                ka = ka + 1
                kb = kb + 1
            }
        }
        while ka < ka_end {
            result.values[pos] = a.values[ka]
            result.col_idx[pos] = a.col_idx[ka]
            pos = pos + 1
            ka = ka + 1
        }
        while kb < kb_end {
            result.values[pos] = b.values[kb]
            result.col_idx[pos] = b.col_idx[kb]
            pos = pos + 1
            kb = kb + 1
        }

        i = i + 1
    }
    result.row_ptr[a.nrows] = pos
    result.nnz = pos
    return result
}

fn sparse_scale(a: SparseCSR, alpha: f64) -> SparseCSR with Mut, Panic, Div {
    var result = a
    var i = 0
    while i < a.nnz {
        result.values[i] = alpha * a.values[i]
        i = i + 1
    }
    return result
}

fn sparse_transpose(a: SparseCSR) -> SparseCSR with Mut, Panic, Div {
    var result = SparseCSR {
        values: [0.0; 1024],
        col_idx: [0; 1024],
        row_ptr: [0; 129],
        nrows: a.ncols,
        ncols: a.nrows,
        nnz: a.nnz
    }

    var col_count: [i32; 129] = [0; 129]
    var k = 0
    while k < a.nnz {
        col_count[a.col_idx[k]] = col_count[a.col_idx[k]] + 1
        k = k + 1
    }

    result.row_ptr[0] = 0
    var i = 0
    while i < a.ncols {
        result.row_ptr[i + 1] = result.row_ptr[i] + col_count[i]
        i = i + 1
    }

    var pos: [i32; 129] = [0; 129]
    i = 0
    while i < a.ncols {
        pos[i] = result.row_ptr[i]
        i = i + 1
    }

    i = 0
    while i < a.nrows {
        k = a.row_ptr[i]
        let row_end = a.row_ptr[i + 1]
        while k < row_end {
            let col = a.col_idx[k]
            let dest = pos[col]
            result.values[dest] = a.values[k]
            result.col_idx[dest] = i
            pos[col] = pos[col] + 1
            k = k + 1
        }
        i = i + 1
    }

    return result
}

fn sparse_lower_solve(l: SparseCSR, b: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var x: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        x[i] = b[i]
        var k = l.row_ptr[i]
        let row_end = l.row_ptr[i + 1]
        var diag_val = 1.0

        while k < row_end {
            let col = l.col_idx[k]
            if col < i {
                x[i] = x[i] - l.values[k] * x[col]
            } else if col == i {
                diag_val = l.values[k]
            }
            k = k + 1
        }
        x[i] = x[i] / diag_val
        i = i + 1
    }
    return x
}

fn sparse_upper_solve(u: SparseCSR, b: [f64; 128], n: i32) -> [f64; 128] with Mut, Panic, Div {
    var x: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        x[i] = b[i]
        i = i + 1
    }

    i = n - 1
    while i >= 0 {
        var k = u.row_ptr[i]
        let row_end = u.row_ptr[i + 1]
        var diag_val = 1.0

        while k < row_end {
            let col = u.col_idx[k]
            if col > i {
                x[i] = x[i] - u.values[k] * x[col]
            } else if col == i {
                diag_val = u.values[k]
            }
            k = k + 1
        }
        x[i] = x[i] / diag_val
        i = i - 1
    }
    return x
}

fn sparse_frobenius_norm(a: SparseCSR) -> f64 with Mut, Panic, Div {
    var sum = 0.0
    var i = 0
    while i < a.nnz {
        sum = sum + a.values[i] * a.values[i]
        i = i + 1
    }
    return sqrt_f64(sum)
}

fn sparse_is_symmetric(a: SparseCSR, tol: f64) -> bool with Mut, Panic, Div {
    if a.nrows != a.ncols {
        return false
    }
    var i = 0
    while i < a.nrows {
        var k = a.row_ptr[i]
        let row_end = a.row_ptr[i + 1]
        while k < row_end {
            let j = a.col_idx[k]
            let aij = a.values[k]
            let aji = sparse_get(a, j, i)
            if abs_f64(aij - aji) > tol {
                return false
            }
            k = k + 1
        }
        i = i + 1
    }
    return true
}

fn cg_solve(
    a: SparseCSR,
    b: [f64; 128],
    x0: [f64; 128],
    n: i32,
    tol: f64,
    max_iter: i32
) -> CGResult with Mut, Panic, Div {
    var x: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        x[i] = x0[i]
        i = i + 1
    }

    let ax = sparse_matvec(a, x, n)
    var r = vec_sub(b, ax, n)
    var p = vec_copy(r, n)
    var rsold = vec_dot(r, r, n)

    if sqrt_f64(rsold) < tol {
        return CGResult {
            x: x,
            iterations: 0,
            residual: sqrt_f64(rsold),
            converged: true
        }
    }

    var iter = 0
    var converged = false
    var done = false
    while iter < max_iter && !done {
        let ap = sparse_matvec(a, p, n)
        let pap = vec_dot(p, ap, n)
        if abs_f64(pap) < 1e-30 {
            // Breakdown
            done = true
        } else {
            let alpha = rsold / pap

            i = 0
            while i < n {
                x[i] = x[i] + alpha * p[i]
                i = i + 1
            }

            i = 0
            while i < n {
                r[i] = r[i] - alpha * ap[i]
                i = i + 1
            }

            let rsnew = vec_dot(r, r, n)

            if sqrt_f64(rsnew) < tol {
                converged = true
                done = true
            } else {
                let beta = rsnew / rsold
                i = 0
                while i < n {
                    p[i] = r[i] + beta * p[i]
                    i = i + 1
                }

                rsold = rsnew
            }
        }
        iter = iter + 1
    }

    let final_res = sqrt_f64(vec_dot(r, r, n))

    return CGResult {
        x: x,
        iterations: iter,
        residual: final_res,
        converged: converged
    }
}

fn test_identity_matvec() -> bool with IO, Mut, Panic, Div {
