    print("  residual=")
    println(result.residual)

    return result.converged && max_err < 1e-6
}

fn test_cg_poisson() -> bool with IO, Mut, Panic, Div {
    let n = 20
    let h = 1.0 / ((n + 1) as f64)
    let pi = 3.14159265358979323846

    // Build SPD tridiagonal: (1/h^2) * [2, -1; -1, 2, -1; ...; -1, 2]
    var lower: [f64; 128] = [0.0; 128]
    var main: [f64; 128] = [0.0; 128]
    var upper: [f64; 128] = [0.0; 128]

    let h2_inv = 1.0 / (h * h)
    var i = 0
    while i < n {
        main[i] = 2.0 * h2_inv
        i = i + 1
    }
    i = 0
    while i < n - 1 {
        lower[i] = 0.0 - h2_inv
        upper[i] = 0.0 - h2_inv
        i = i + 1
    }

    let a = sparse_tridiagonal(lower, main, upper, n)

    // RHS: f(x_i) = pi^2 * sin(pi * x_i)
    // Use Taylor series for sin(x) near small arguments
    // sin(x) = x - x^3/6 + x^5/120 - x^7/5040 + x^9/362880
    var b: [f64; 128] = [0.0; 128]
    i = 0
    while i < n {
        let xi = (i + 1) as f64 * h
        let arg = pi * xi
        // Compute sin(arg) via Taylor series (sufficient for arg in [0, pi])
        // Reduce to [0, pi/2]: sin(pi - x) = sin(x)
        var t = arg
        if t > pi / 2.0 {
            t = pi - t
        }
        let t2 = t * t
        let t3 = t2 * t
        let t5 = t3 * t2
        let t7 = t5 * t2
        let t9 = t7 * t2
        let t11 = t9 * t2
        let sin_t = t - t3 / 6.0 + t5 / 120.0 - t7 / 5040.0 + t9 / 362880.0 - t11 / 39916800.0
        b[i] = pi * pi * sin_t
        i = i + 1
    }

    var x0: [f64; 128] = [0.0; 128]
    let result = cg_solve(a, b, x0, n, 1e-10, 500)

    // Check against exact solution u(x_i) = sin(pi * x_i)
    var max_err = 0.0
    i = 0
    while i < n {
        let xi = (i + 1) as f64 * h
        let arg = pi * xi
        var t = arg
        if t > pi / 2.0 {
            t = pi - t
        }
        let t2 = t * t
        let t3 = t2 * t
        let t5 = t3 * t2
        let t7 = t5 * t2
        let t9 = t7 * t2
        let t11 = t9 * t2
        let exact = t - t3 / 6.0 + t5 / 120.0 - t7 / 5040.0 + t9 / 362880.0 - t11 / 39916800.0
        let diff = abs_f64(result.x[i] - exact)
        if diff > max_err {
            max_err = diff
        }
        i = i + 1
    }

    print("  iters=")
    println(result.iterations)
    print("  max_err=")
    println(max_err)
    print("  converged=")
    if result.converged { println("true") } else { println("false") }

    // The discretization error is O(h^2) ~ 1/(21^2) ~ 0.002
    // So we expect the CG solution to match the exact solution within O(h^2)
    return result.converged && max_err < 0.01
}

fn pow_f64(base: f64, exponent: f64) -> f64 with Mut, Panic, Div {
    if exponent == 0.0 { return 1.0 }
    if base == 0.0 {
        if exponent > 0.0 { return 0.0 }
        return 1.0e30
    }
    if base == 1.0 { return 1.0 }
    if base > 0.0 {
        return exp_f64(exponent * ln_f64(base))
    }
    let abs_base = abs_f64(base)
    let iexp = floor_f64(exponent)
    if abs_f64(exponent - iexp) < 1.0e-12 {
        let result = exp_f64(exponent * ln_f64(abs_base))
        let half = iexp / 2.0
        let half_floor = floor_f64(half)
        if abs_f64(half - half_floor) > 0.25 {
            return 0.0 - result
        }
        return result
    }
    return 0.0 - 1.0e30
}

fn sp_beta(a: f64, b: f64) -> f64 with Mut, Panic, Div {
    return exp_f64(sp_lgamma(a) + sp_lgamma(b) - sp_lgamma(a + b))
}

fn sp_erf(x: f64) -> f64 with Mut, Panic, Div {
    if x < 0.0 {
        return 0.0 - sp_erf(0.0 - x)
    }
    if x == 0.0 { return 0.0 }
    if x > 6.0 { return 1.0 }

    let p = 0.3275911
    let a1 = 0.254829592
    let a2 = 0.0 - 0.284496736
    let a3 = 1.421413741
    let a4 = 0.0 - 1.453152027
    let a5 = 1.061405429

    let t = 1.0 / (1.0 + p * x)
    let t2 = t * t
    let t3 = t2 * t
    let t4 = t3 * t
    let t5 = t4 * t

    let poly = a1 * t + a2 * t2 + a3 * t3 + a4 * t4 + a5 * t5
    return 1.0 - poly * exp_f64(0.0 - x * x)
}

fn sp_erfc(x: f64) -> f64 with Mut, Panic, Div {
    if x < 0.0 {
        return 2.0 - sp_erfc(0.0 - x)
    }
    if x == 0.0 { return 1.0 }
    if x > 6.0 { return 0.0 }

    let p = 0.3275911
    let a1 = 0.254829592
    let a2 = 0.0 - 0.284496736
    let a3 = 1.421413741
    let a4 = 0.0 - 1.453152027
    let a5 = 1.061405429

    let t = 1.0 / (1.0 + p * x)
    let t2 = t * t
    let t3 = t2 * t
    let t4 = t3 * t
    let t5 = t4 * t

    let poly = a1 * t + a2 * t2 + a3 * t3 + a4 * t4 + a5 * t5
    return poly * exp_f64(0.0 - x * x)
}

fn sp_gamma_inc_series(a: f64, x: f64) -> f64 with Mut, Panic, Div {
    var ap = a
    var sum = 1.0 / a
    var term = 1.0 / a
    var n = 0
    while n < 200 {
        ap = ap + 1.0
        term = term * x / ap
        sum = sum + term
        if abs_f64(term) < abs_f64(sum) * 1.0e-12 {
            return sum * exp_f64(0.0 - x + a * ln_f64(x) - sp_lgamma(a))
        }
        n = n + 1
    }
    return sum * exp_f64(0.0 - x + a * ln_f64(x) - sp_lgamma(a))
}

fn sp_gamma_inc_cf(a: f64, x: f64) -> f64 with Mut, Panic, Div {
    let tiny = 1.0e-30
    let b0 = x + 1.0 - a
    var f = b0
    if abs_f64(b0) < tiny { f = tiny }
    var c = f
    var d = 0.0

    var n = 1
    while n < 200 {
        let an = (n as f64) * ((n as f64) - a)
        let bn = x + 2.0 * (n as f64) + 1.0 - a

        d = bn + an * d
        if abs_f64(d) < tiny { d = tiny }
        d = 1.0 / d

        c = bn + an / c
        if abs_f64(c) < tiny { c = tiny }

        let delta = c * d
        f = f * delta

        if abs_f64(delta - 1.0) < 1.0e-12 {
            n = 200
        } else {
            n = n + 1
        }
    }

    let log_prefix = 0.0 - x + a * ln_f64(x) - sp_lgamma(a)
    return exp_f64(log_prefix) / f
}

fn sp_gamma_inc_p(a: f64, x: f64) -> f64 with Mut, Panic, Div {
    if x < 0.0 { return 0.0 }
    if x == 0.0 { return 0.0 }
    if a <= 0.0 { return 1.0 }

    if x < a + 1.0 {
        return sp_gamma_inc_series(a, x)
    } else {
        return 1.0 - sp_gamma_inc_cf(a, x)
    }
}

fn sp_beta_inc_cf(a: f64, b: f64, x: f64) -> f64 with Mut, Panic, Div {
    let tiny = 1.0e-30

    var d = 1.0 - (a + b) * x / (a + 1.0)
    if abs_f64(d) < tiny { d = tiny }
    d = 1.0 / d
    var f = d
    var c = 1.0

    var m = 1
    while m < 200 {
        let mf = m as f64

        let num_even = mf * (b - mf) * x / ((a + 2.0 * mf - 1.0) * (a + 2.0 * mf))

        d = 1.0 + num_even * d
        if abs_f64(d) < tiny { d = tiny }
        d = 1.0 / d

        c = 1.0 + num_even / c
        if abs_f64(c) < tiny { c = tiny }

        f = f * d * c

        let num_odd = 0.0 - (a + mf) * (a + b + mf) * x / ((a + 2.0 * mf) * (a + 2.0 * mf + 1.0))

        d = 1.0 + num_odd * d
        if abs_f64(d) < tiny { d = tiny }
        d = 1.0 / d

        c = 1.0 + num_odd / c
        if abs_f64(c) < tiny { c = tiny }

        let delta = d * c
        f = f * delta

        if abs_f64(delta - 1.0) < 1.0e-12 {
            m = 200
        } else {
            m = m + 1
        }
    }

    return f
}

fn sp_beta_inc(a: f64, b: f64, x: f64) -> f64 with Mut, Panic, Div {
    if x <= 0.0 { return 0.0 }
    if x >= 1.0 { return 1.0 }

    let pivot = (a + 1.0) / (a + b + 2.0)
    if x > pivot {
        return 1.0 - sp_beta_inc(b, a, 1.0 - x)
    }

    let log_prefix = a * ln_f64(x) + b * ln_f64(1.0 - x) - ln_f64(a) - sp_lgamma(a) - sp_lgamma(b) + sp_lgamma(a + b)
    let prefix = exp_f64(log_prefix)

    let cf = sp_beta_inc_cf(a, b, x)
    return prefix * cf
}

fn sp_digamma(x: f64) -> f64 with Mut, Panic, Div {
    if x < 0.0 {
        let s = sin_f64(pi_val() * x)
        if abs_f64(s) < 1.0e-15 { return 1.0e30 }
        return sp_digamma(1.0 - x) - pi_val() * cos_f64(pi_val() * x) / s
    }

    if x == 0.0 { return 0.0 - 1.0e30 }

    var val = x
    var shift = 0.0
    while val < 7.0 {
        shift = shift - 1.0 / val
        val = val + 1.0
    }

    let inv_v = 1.0 / val
    let inv_v2 = inv_v * inv_v

    var result = ln_f64(val) - 0.5 * inv_v
    result = result - inv_v2 / 12.0
    result = result + inv_v2 * inv_v2 / 120.0
    result = result - inv_v2 * inv_v2 * inv_v2 / 252.0
    result = result + inv_v2 * inv_v2 * inv_v2 * inv_v2 / 240.0
    result = result - 5.0 * inv_v2 * inv_v2 * inv_v2 * inv_v2 * inv_v2 / 660.0

    return result + shift
}

