fn exp_neg(x: f64) -> f64 with Mut, Div, Panic {
    // For larger x, use repeated squaring: exp(-x) = exp(-x/n)^n
    var val = x
    var squarings: i64 = 0
    while val > 1.0 {
        val = val / 2.0
        squarings = squarings + 1
    }

    // Taylor for small |val|
    var result = 1.0
    var term = 1.0
    var k: i64 = 1
    while k <= 12 {
        term = term * (0.0 - val) / k as f64
        result = result + term
        k = k + 1
    }

    // Square back
    var s: i64 = 0
    while s < squarings {
        result = result * result
        s = s + 1
    }
    result
}

fn svg_print_f64(value: f64, decimals: i64) with IO, Mut, Panic, Div {
    if value < 0.0 {
        print("-")
    }
    let abs_val = if value < 0.0 { 0.0 - value } else { value }
    let int_part = abs_val as i64
    print_i64(int_part)

    if decimals > 0 {
        print(".")
        var frac = abs_val - int_part as f64
        var d: i64 = 0
        while d < decimals {
            frac = frac * 10.0
            let digit = frac as i64
            print_i64(digit)
            frac = frac - digit as f64
            d = d + 1
        }
    }
}

