        print(" * ")
        let a3 = expr_print(a2, arena.right[node_idx])
        print(")")
        return a3
    }
    if ntype == 5 {
        print("(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(" / ")
        let a3 = expr_print(a2, arena.right[node_idx])
        print(")")
        return a3
    }
    if ntype == 6 {
        print("(-")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 7 {
        print("sin(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 8 {
        print("cos(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
    if ntype == 9 {
        print("exp(")
        let a2 = expr_print(arena, arena.left[node_idx])
        print(")")
        return a2
    }
