    prox_simplex(&v, 4, &!out)
    // Check sum = 1
    let s = cv_sum(&out, 4)
    let sum_ok = approx_eq(s, 1.0, 1.0e-6)
    // Check all non-negative
    var all_nonneg = true
    var i = 0
    while i < 4 {
        if out[i] < 0.0 - 1.0e-10 { all_nonneg = false }
        i = i + 1
    }
    sum_ok && all_nonneg
}

fn test_lasso_sparsity() -> bool with Mut, Div, Panic {
    // A is 4x3 identity-like: A = [1 0 0; 0 1 0; 0 0 1; 0 0 0]
    // b = [5.0, 3.0, 0.1, 0.0]
    // With large lambda, solution should be sparse
    var A: [f64; 4096] = [0.0; 4096]
    A[0] = 1.0   // row 0, col 0
    A[4] = 1.0   // row 1, col 1
    A[8] = 1.0   // row 2, col 2
    var b: [f64; 64] = [0.0; 64]
    b[0] = 5.0
    b[1] = 3.0
    b[2] = 0.1
    b[3] = 0.0

    var result: LassoResult = LassoResult {
        x: [0.0; 64], obj_val: 0.0, iterations: 0, converged: false, n_dim: 0
    }
    // Large lambda = 4.0 should zero out small entries
    proxgrad_lasso(&A, &b, 4, 3, 4.0, 2000, 1.0e-8, &!result)

    // x[2] should be zeroed (b[2]=0.1 is too small vs lambda=4.0)
    let sparse_ok = approx_eq(result.x[2], 0.0, 1.0e-4)
    // x[0] should be shrunken: x[0] = max(5.0 - 4.0, 0) = 1.0
    let x0_ok = approx_eq(result.x[0], 1.0, 1.0e-4)
    // Count nonzero entries; x[2] should be zero
    let nnz = cv_count_nonzero(&result.x, 3, 1.0e-4)
    let nnz_ok = nnz < 3
    sparse_ok && x0_ok && nnz_ok
}

fn test_lasso_zero_lambda() -> bool with Mut, Div, Panic {
    // A is 3x3 identity, b = [2.0, 3.0, 4.0]
    // With lambda ~ 0, LASSO solution ~ OLS = b
    var A: [f64; 4096] = [0.0; 4096]
    A[0] = 1.0
    A[4] = 1.0
    A[8] = 1.0
    var b: [f64; 64] = [0.0; 64]
    b[0] = 2.0
    b[1] = 3.0
    b[2] = 4.0

    var result: LassoResult = LassoResult {
        x: [0.0; 64], obj_val: 0.0, iterations: 0, converged: false, n_dim: 0
    }
    // lambda = 1e-12 (near zero)
    proxgrad_lasso(&A, &b, 3, 3, 1.0e-12, 2000, 1.0e-8, &!result)

    let ok0 = approx_eq(result.x[0], 2.0, 1.0e-4)
    let ok1 = approx_eq(result.x[1], 3.0, 1.0e-4)
    let ok2 = approx_eq(result.x[2], 4.0, 1.0e-4)
    ok0 && ok1 && ok2
}

fn test_proxgrad_quadratic() -> bool with Mut, Div, Panic {
    // A = identity, b = 0, lambda ~ 0 -> solution = 0
    var A: [f64; 4096] = [0.0; 4096]
    A[0] = 1.0
    A[4] = 1.0
    A[8] = 1.0
    var b: [f64; 64] = [0.0; 64]

    var result: LassoResult = LassoResult {
        x: [0.0; 64], obj_val: 0.0, iterations: 0, converged: false, n_dim: 0
    }
    proxgrad_lasso(&A, &b, 3, 3, 1.0e-15, 2000, 1.0e-10, &!result)

    let ok0 = approx_eq(result.x[0], 0.0, 1.0e-4)
    let ok1 = approx_eq(result.x[1], 0.0, 1.0e-4)
    let ok2 = approx_eq(result.x[2], 0.0, 1.0e-4)
    ok0 && ok1 && ok2
}

fn test_fista_converges() -> bool with Mut, Div, Panic {
    // A is 4x3 matrix with correlated columns
    var A: [f64; 4096] = [0.0; 4096]
    A[0] = 1.0; A[1] = 0.5; A[2] = 0.0    // row 0
    A[3] = 0.5; A[4] = 1.0; A[5] = 0.5    // row 1
    A[6] = 0.0; A[7] = 0.5; A[8] = 1.0    // row 2
    A[9] = 0.3; A[10] = 0.3; A[11] = 0.3  // row 3
    var b: [f64; 64] = [0.0; 64]
    b[0] = 2.0
    b[1] = 3.0
    b[2] = 1.0
    b[3] = 1.0

    let lambda = 0.1
    let max_iter = 500
    let tol = 1.0e-6

    var pg_result: LassoResult = LassoResult {
        x: [0.0; 64], obj_val: 0.0, iterations: 0, converged: false, n_dim: 0
    }
    proxgrad_lasso(&A, &b, 4, 3, lambda, max_iter, tol, &!pg_result)

    var fista_result: LassoResult = LassoResult {
        x: [0.0; 64], obj_val: 0.0, iterations: 0, converged: false, n_dim: 0
    }
    fista(&A, &b, 4, 3, lambda, max_iter, tol, &!fista_result)

    // Both should converge and produce similar objective values
    let obj_close = approx_eq(pg_result.obj_val, fista_result.obj_val, 1.0e-2)
    obj_close
}

fn test_moreau_envelope() -> bool with Mut, Div, Panic {
    // Moreau envelope of ||.||_1 at 0 should be 0
    var zero_vec: [f64; 64] = [0.0; 64]
    let m0 = moreau_envelope(&zero_vec, 3, 1.0)
    let at_zero_ok = approx_eq(m0, 0.0, 1.0e-10)

    // At x = [2.0, 0, 0], lambda = 1.0:
    // prox_l1([2.0,0,0], 1.0) = [1.0, 0, 0]
    // Moreau = ||prox||_1 + ||prox - x||^2 / (2*lambda)
    //        = 1.0 + (1.0)^2 / 2.0 = 1.5
    var v: [f64; 64] = [0.0; 64]
    v[0] = 2.0
    let m1 = moreau_envelope(&v, 3, 1.0)
    let at_two_ok = approx_eq(m1, 1.5, 1.0e-10)

    // Moreau envelope should be <= f(x) = ||x||_1 (it is a smoothed lower bound)
    // For x = [2.0, 0, 0]: f(x) = 2.0, M(x) = 1.5 <= 2.0
    let smooth_ok = m1 <= 2.0 + 1.0e-10

    at_zero_ok && at_two_ok && smooth_ok
}

fn dg_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 24 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn dg_sin(x: f64) -> f64 with Mut, Div, Panic {
    var a = x
    let tp = 6.28318530717958647692
    while a >= tp { a = a - tp }
    while a < 0.0 { a = a + tp }
    if a > 3.14159265358979323846 { a = a - tp }
    let a2 = a * a
    var sum = a
    var term = a
    var n = 1
    while n < 20 { term = 0.0 - term * a2 / ((2 * n) * (2 * n + 1)) as f64; sum = sum + term; n = n + 1 }
    sum
}

fn dg_cos(x: f64) -> f64 with Mut, Div, Panic {
    dg_sin(x + 1.57079632679489661923)
}

fn dg_exp(x: f64) -> f64 with Mut, Div, Panic {
    if x > 500.0 { return 1.0e200 }
    if x < -500.0 { return 0.0 }
    let ln2 = 0.6931471805599453
    var kf = x / ln2
    var k: i32 = 0
    if kf >= 0.0 { k = kf as i32 } else { k = (kf as i32) - 1 }
    let r = x - (k as f64) * ln2
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 25 { term = term * r / (n as f64); sum = sum + term; n = n + 1 }
    var result = sum
    if k >= 0 { var i = 0; while i < k { result = result * 2.0; i = i + 1 } }
    else { var i = 0; while i < (0 - k) { result = result / 2.0; i = i + 1 } }
    result
}

fn dg_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if x == 1.0 { return 0.0 }
    var m = x
    var e = 0
    while m >= 2.0 { m = m / 2.0; e = e + 1 }
    while m < 0.5 { m = m * 2.0; e = e - 1 }
    let t = (m - 1.0) / (m + 1.0)
    let t2 = t * t
    var sum = t
    var term = t
    var k = 1
    while k < 30 { term = term * t2; sum = sum + term / ((2 * k + 1) as f64); k = k + 1 }
    2.0 * sum + (e as f64) * 0.6931471805599453
}

fn metric_inverse(g: &[f64; 16], dim: i32, g_inv: &![f64; 16]) with Mut, Div, Panic {
    var work: [f64; 32] = [0.0; 32]

    var i = 0
    while i < dim {
        var j = 0
        while j < dim {
            work[i * 2 * dim + j] = g[i * dim + j]
            j = j + 1
        }
        work[i * 2 * dim + dim + i] = 1.0
        i = i + 1
    }

    var col = 0
    while col < dim {
        var max_val = dg_abs(work[col * 2 * dim + col])
        var max_row = col
        var row = col + 1
        while row < dim {
            let v = dg_abs(work[row * 2 * dim + col])
            if v > max_val { max_val = v; max_row = row }
            row = row + 1
        }

        if max_row != col {
            var j = 0
            while j < 2 * dim {
                let tmp = work[col * 2 * dim + j]
                work[col * 2 * dim + j] = work[max_row * 2 * dim + j]
                work[max_row * 2 * dim + j] = tmp
                j = j + 1
            }
        }

        let pivot = work[col * 2 * dim + col]
        if dg_abs(pivot) < 1.0e-30 {
            i = 0
            while i < 16 { g_inv[i] = 0.0; i = i + 1 }
            i = 0
            while i < dim { g_inv[i * dim + i] = 1.0; i = i + 1 }
            return
        }

        let inv_pivot = 1.0 / pivot
        var j = 0
        while j < 2 * dim {
            work[col * 2 * dim + j] = work[col * 2 * dim + j] * inv_pivot
            j = j + 1
        }

        row = 0
        while row < dim {
            if row != col {
                let factor = work[row * 2 * dim + col]
                j = 0
                while j < 2 * dim {
                    work[row * 2 * dim + j] = work[row * 2 * dim + j] - factor * work[col * 2 * dim + j]
                    j = j + 1
                }
            }
            row = row + 1
        }
        col = col + 1
    }

    i = 0
    while i < 16 { g_inv[i] = 0.0; i = i + 1 }
    i = 0
    while i < dim {
        var j = 0
        while j < dim {
            g_inv[i * dim + j] = work[i * 2 * dim + dim + j]
            j = j + 1
        }
        i = i + 1
    }
}

fn metric_det(g: &[f64; 16], dim: i32) -> f64 with Mut, Div, Panic {
    if dim == 1 { return g[0] }

    if dim == 2 {
        return g[0] * g[3] - g[1] * g[2]
    }

    if dim == 3 {
        let a = g[0]; let b = g[1]; let c = g[2]
        let d = g[3]; let e = g[4]; let f = g[5]
        let h = g[6]; let i = g[7]; let j = g[8]
        return a * (e * j - f * i) - b * (d * j - f * h) + c * (d * i - e * h)
    }

    var A: [f64; 16] = [0.0; 16]
    var k = 0
    while k < 16 { A[k] = g[k]; k = k + 1 }

    var det = 1.0
    var col = 0
    while col < dim {
        var max_val = dg_abs(A[col * dim + col])
        var max_row = col
        var row = col + 1
        while row < dim {
            let v = dg_abs(A[row * dim + col])
            if v > max_val { max_val = v; max_row = row }
            row = row + 1
        }
        if max_row != col {
            var j = 0
            while j < dim {
                let tmp = A[col * dim + j]
                A[col * dim + j] = A[max_row * dim + j]
                A[max_row * dim + j] = tmp
                j = j + 1
            }
            det = 0.0 - det
        }

        let pivot = A[col * dim + col]
        if dg_abs(pivot) < 1.0e-30 { return 0.0 }
        det = det * pivot

        row = col + 1
        while row < dim {
            let factor = A[row * dim + col] / pivot
            var j = col + 1
            while j < dim {
                A[row * dim + j] = A[row * dim + j] - factor * A[col * dim + j]
                j = j + 1
            }
            row = row + 1
        }
        col = col + 1
    }
    det
}

fn metric_raise_index(g_inv: &[f64; 16], v_lower: &[f64; 4], dim: i32, v_upper: &![f64; 4]) with Mut, Div, Panic {
    var i = 0
    while i < dim {
        var s = 0.0
        var j = 0
        while j < dim {
            s = s + g_inv[i * dim + j] * v_lower[j]
            j = j + 1
        }
        v_upper[i] = s
        i = i + 1
    }
    while i < 4 { v_upper[i] = 0.0; i = i + 1 }
}

fn metric_lower_index(g: &[f64; 16], v_upper: &[f64; 4], dim: i32, v_lower: &![f64; 4]) with Mut, Div, Panic {
    var i = 0
    while i < dim {
        var s = 0.0
        var j = 0
        while j < dim {
            s = s + g[i * dim + j] * v_upper[j]
            j = j + 1
        }
        v_lower[i] = s
        i = i + 1
    }
    while i < 4 { v_lower[i] = 0.0; i = i + 1 }
}

fn christoffel_from_metric(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                           x: &[f64; 4], dim: i32,
                           gamma: &!Christoffel4) with Mut, Div, Panic {
    let h = 1.0e-6
    gamma.c4_dim = dim

    var idx = 0
    while idx < 64 { gamma.gamma[idx] = 0.0; idx = idx + 1 }

    var g0: [f64; 16] = [0.0; 16]
    metric_fn(x, dim, &!g0)

    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g0, dim, &!g_inv)

    var dg: [f64; 256] = [0.0; 256]

    var m = 0
    while m < dim {
        var xp: [f64; 4] = [0.0; 4]
        var xm: [f64; 4] = [0.0; 4]
        var c = 0
        while c < 4 { xp[c] = x[c]; xm[c] = x[c]; c = c + 1 }
        xp[m] = x[m] + h
        xm[m] = x[m] - h

        var gp: [f64; 16] = [0.0; 16]
        var gm: [f64; 16] = [0.0; 16]
        metric_fn(&xp, dim, &!gp)
        metric_fn(&xm, dim, &!gm)

        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                dg[m * dim * dim + i * dim + j] = (gp[i * dim + j] - gm[i * dim + j]) / (2.0 * h)
                j = j + 1
            }
            i = i + 1
        }
        m = m + 1
    }

    var k = 0
    while k < dim {
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                var s = 0.0
                var l = 0
                while l < dim {
                    let term1 = dg[j * dim * dim + l * dim + i]
                    let term2 = dg[i * dim * dim + l * dim + j]
                    let term3 = dg[l * dim * dim + i * dim + j]
                    s = s + g_inv[k * dim + l] * (term1 + term2 - term3)
                    l = l + 1
                }
                gamma.gamma[k * dim * dim + i * dim + j] = 0.5 * s
                j = j + 1
            }
            i = i + 1
        }
        k = k + 1
    }
}

fn riemann_tensor(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                  x: &[f64; 4], dim: i32,
                  R: &!RiemannTensor) with Mut, Div, Panic {
    let h = 1.0e-5
    R.rt_dim = dim

    var idx = 0
    while idx < 256 { R.R[idx] = 0.0; idx = idx + 1 }

    var gamma0: Christoffel4 = Christoffel4 { gamma: [0.0; 64], c4_dim: dim }
    christoffel_from_metric(metric_fn, x, dim, &!gamma0)

    var d_gamma: [f64; 256] = [0.0; 256]

    var m = 0
    while m < dim {
        var xp: [f64; 4] = [0.0; 4]
        var xm: [f64; 4] = [0.0; 4]
        var c = 0
        while c < 4 { xp[c] = x[c]; xm[c] = x[c]; c = c + 1 }
        xp[m] = x[m] + h
        xm[m] = x[m] - h

        var gp: Christoffel4 = Christoffel4 { gamma: [0.0; 64], c4_dim: dim }
        var gm: Christoffel4 = Christoffel4 { gamma: [0.0; 64], c4_dim: dim }
        christoffel_from_metric(metric_fn, &xp, dim, &!gp)
        christoffel_from_metric(metric_fn, &xm, dim, &!gm)

        var k = 0
        while k < dim {
            var a = 0
            while a < dim {
                var b = 0
                while b < dim {
                    let gp_val = gp.gamma[k * dim * dim + a * dim + b]
                    let gm_val = gm.gamma[k * dim * dim + a * dim + b]
                    d_gamma[m * dim * dim * dim + k * dim * dim + a * dim + b] = (gp_val - gm_val) / (2.0 * h)
                    b = b + 1
                }
                a = a + 1
            }
            k = k + 1
        }
        m = m + 1
    }

    var k = 0
    while k < dim {
        var l = 0
        while l < dim {
            var i = 0
            while i < dim {
                var j = 0
                while j < dim {
                    let di_Gkjl = d_gamma[i * dim * dim * dim + k * dim * dim + j * dim + l]
                    let dj_Gkil = d_gamma[j * dim * dim * dim + k * dim * dim + i * dim + l]

                    var quad1 = 0.0
                    var quad2 = 0.0
                    var mm = 0
                    while mm < dim {
                        quad1 = quad1 + gamma0.gamma[k * dim * dim + i * dim + mm] * gamma0.gamma[mm * dim * dim + j * dim + l]
                        quad2 = quad2 + gamma0.gamma[k * dim * dim + j * dim + mm] * gamma0.gamma[mm * dim * dim + i * dim + l]
                        mm = mm + 1
                    }

                    R.R[k * dim * dim * dim + l * dim * dim + i * dim + j] = di_Gkjl - dj_Gkil + quad1 - quad2
                    j = j + 1
                }
                i = i + 1
            }
            l = l + 1
        }
        k = k + 1
    }
}

fn ricci_tensor(R_in: &RiemannTensor, result: &!RicciTensor) with Mut, Div, Panic {
    let dim = R_in.rt_dim
    result.ric_dim = dim
    result.scalar = 0.0

    var i = 0
    while i < 16 { result.Ric[i] = 0.0; i = i + 1 }

    i = 0
    while i < dim {
        var j = 0
        while j < dim {
            var s = 0.0
            var k = 0
            while k < dim {
                s = s + R_in.R[k * dim * dim * dim + i * dim * dim + k * dim + j]
                k = k + 1
            }
            result.Ric[i * dim + j] = s
            j = j + 1
        }
        i = i + 1
    }
}

fn ricci_with_scalar(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                     x: &[f64; 4], dim: i32,
                     result: &!RicciTensor) with Mut, Div, Panic {
    var Riem: RiemannTensor = RiemannTensor { R: [0.0; 256], rt_dim: dim }
    riemann_tensor(metric_fn, x, dim, &!Riem)

    ricci_tensor(&Riem, result)

    var g0: [f64; 16] = [0.0; 16]
    metric_fn(x, dim, &!g0)
    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g0, dim, &!g_inv)

    var scalar = 0.0
    var i = 0
    while i < dim {
        var j = 0
        while j < dim {
            scalar = scalar + g_inv[i * dim + j] * result.Ric[i * dim + j]
            j = j + 1
        }
        i = i + 1
    }
    result.scalar = scalar
}

fn gauss_curvature_2d(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                      x: &[f64; 4]) -> f64 with Mut, Div, Panic {
    let dim = 2
    var ric: RicciTensor = RicciTensor { Ric: [0.0; 16], scalar: 0.0, ric_dim: dim }
    ricci_with_scalar(metric_fn, x, dim, &!ric)
    ric.scalar / 2.0
}

fn geodesic_rhs(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                st: &GeodesicState,
                dx: &![f64; 4], dv: &![f64; 4]) with Mut, Div, Panic {
    let dim = st.gs_dim

    var i = 0
    while i < 4 { dx[i] = 0.0; dv[i] = 0.0; i = i + 1 }
    i = 0
    while i < dim { dx[i] = st.v[i]; i = i + 1 }

    var gamma: Christoffel4 = Christoffel4 { gamma: [0.0; 64], c4_dim: dim }
    christoffel_from_metric(metric_fn, &st.x, dim, &!gamma)

    var k = 0
    while k < dim {
        var s = 0.0
        i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * st.v[i] * st.v[j]
                j = j + 1
            }
            i = i + 1
        }
        dv[k] = 0.0 - s
        k = k + 1
    }
}

fn geodesic_step(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                 st: &!GeodesicState, dtau: f64) with Mut, Div, Panic {
    let dim = st.gs_dim

    var dx1: [f64; 4] = [0.0; 4]
    var dv1: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, st, &!dx1, &!dv1)

    var s2: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], gs_dim: dim, tau: st.tau + dtau / 2.0 }
    var c = 0
    while c < dim {
        s2.x[c] = st.x[c] + 0.5 * dtau * dx1[c]
        s2.v[c] = st.v[c] + 0.5 * dtau * dv1[c]
        c = c + 1
    }

    var dx2: [f64; 4] = [0.0; 4]
    var dv2: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s2, &!dx2, &!dv2)

    var s3: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], gs_dim: dim, tau: st.tau + dtau / 2.0 }
    c = 0
    while c < dim {
        s3.x[c] = st.x[c] + 0.5 * dtau * dx2[c]
        s3.v[c] = st.v[c] + 0.5 * dtau * dv2[c]
        c = c + 1
    }

    var dx3: [f64; 4] = [0.0; 4]
    var dv3: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s3, &!dx3, &!dv3)

    var s4: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], gs_dim: dim, tau: st.tau + dtau }
    c = 0
    while c < dim {
        s4.x[c] = st.x[c] + dtau * dx3[c]
        s4.v[c] = st.v[c] + dtau * dv3[c]
        c = c + 1
    }

    var dx4: [f64; 4] = [0.0; 4]
    var dv4: [f64; 4] = [0.0; 4]
    geodesic_rhs(metric_fn, &s4, &!dx4, &!dv4)

    c = 0
    while c < dim {
        st.x[c] = st.x[c] + dtau / 6.0 * (dx1[c] + 2.0 * dx2[c] + 2.0 * dx3[c] + dx4[c])
        st.v[c] = st.v[c] + dtau / 6.0 * (dv1[c] + 2.0 * dv2[c] + 2.0 * dv3[c] + dv4[c])
        c = c + 1
    }
    st.tau = st.tau + dtau
}

fn geodesic_integrate(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                      x0: &[f64; 4], v0: &[f64; 4], dim: i32,
                      tau_end: f64, n_steps: i32,
                      path: &!GeodesicPath) with Mut, Div, Panic {
    path.gp_dim = dim
    path.n_steps = n_steps

    var z = 0
    while z < 256 { path.x[z] = 0.0; path.gp_v[z] = 0.0; z = z + 1 }
    z = 0
    while z < 128 { path.gp_tau[z] = 0.0; z = z + 1 }

    let dtau = tau_end / (n_steps as f64)

    var state: GeodesicState = GeodesicState { x: [0.0; 4], v: [0.0; 4], gs_dim: dim, tau: 0.0 }
    var c = 0
    while c < dim { state.x[c] = x0[c]; state.v[c] = v0[c]; c = c + 1 }

    c = 0
    while c < dim {
        path.x[0 * dim + c] = state.x[c]
        path.gp_v[0 * dim + c] = state.v[c]
        c = c + 1
    }
    path.gp_tau[0] = 0.0

    var step = 1
    while step <= n_steps {
        geodesic_step(metric_fn, &!state, dtau)

        if step < 128 {
            path.gp_tau[step] = state.tau
            c = 0
            while c < dim {
                path.x[step * dim + c] = state.x[c]
                path.gp_v[step * dim + c] = state.v[c]
                c = c + 1
            }
        }
        step = step + 1
    }
}

fn parallel_transport_step(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                           x: &[f64; 4], v: &[f64; 4],
                           w: &![f64; 4], dim: i32, dtau: f64) with Mut, Div, Panic {
    var gamma: Christoffel4 = Christoffel4 { gamma: [0.0; 64], c4_dim: dim }
    christoffel_from_metric(metric_fn, x, dim, &!gamma)

    var k1: [f64; 4] = [0.0; 4]
    var k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w[j]
                j = j + 1
            }
            i = i + 1
        }
        k1[k] = 0.0 - s
        k = k + 1
    }

    var w2: [f64; 4] = [0.0; 4]
    var c = 0
    while c < dim { w2[c] = w[c] + 0.5 * dtau * k1[c]; c = c + 1 }
    var k2: [f64; 4] = [0.0; 4]
    k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w2[j]
                j = j + 1
            }
            i = i + 1
        }
        k2[k] = 0.0 - s
        k = k + 1
    }

    var w3: [f64; 4] = [0.0; 4]
    c = 0
    while c < dim { w3[c] = w[c] + 0.5 * dtau * k2[c]; c = c + 1 }
    var k3: [f64; 4] = [0.0; 4]
    k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w3[j]
                j = j + 1
            }
            i = i + 1
        }
        k3[k] = 0.0 - s
        k = k + 1
    }

    var w4: [f64; 4] = [0.0; 4]
    c = 0
    while c < dim { w4[c] = w[c] + dtau * k3[c]; c = c + 1 }
    var k4: [f64; 4] = [0.0; 4]
    k = 0
    while k < dim {
        var s = 0.0
        var i = 0
        while i < dim {
            var j = 0
            while j < dim {
                s = s + gamma.gamma[k * dim * dim + i * dim + j] * v[i] * w4[j]
                j = j + 1
            }
            i = i + 1
        }
        k4[k] = 0.0 - s
        k = k + 1
    }

    c = 0
    while c < dim {
        w[c] = w[c] + dtau / 6.0 * (k1[c] + 2.0 * k2[c] + 2.0 * k3[c] + k4[c])
        c = c + 1
    }
}

fn parallel_transport_along(metric_fn: fn(&[f64; 4], i32, &![f64; 16]) with Mut, Div, Panic,
                            path: &GeodesicPath,
                            w0: &[f64; 4],
                            w_final: &![f64; 4]) with Mut, Div, Panic {
    let dim = path.gp_dim
    let n = path.n_steps

    var c = 0
    while c < 4 { w_final[c] = 0.0; c = c + 1 }
    c = 0
    while c < dim { w_final[c] = w0[c]; c = c + 1 }

    var step = 0
    while step < n {
        var x_cur: [f64; 4] = [0.0; 4]
        var v_cur: [f64; 4] = [0.0; 4]
        c = 0
        while c < dim {
            x_cur[c] = path.x[step * dim + c]
            v_cur[c] = path.gp_v[step * dim + c]
            c = c + 1
        }

        var dtau = 0.0
        if step + 1 < 128 {
            dtau = path.gp_tau[step + 1] - path.gp_tau[step]
        }

        if dg_abs(dtau) > 1.0e-30 {
            parallel_transport_step(metric_fn, &x_cur, &v_cur, w_final, dim, dtau)
        }
        step = step + 1
    }
}

fn metric_euclidean_3d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }
    g[0] = 1.0
    g[4] = 1.0
    g[8] = 1.0
}

fn metric_sphere_2d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }
    let theta = x[0]
    let sth = dg_sin(theta)
    g[0] = 1.0
    g[3] = sth * sth
}

fn metric_schwarzschild(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }

    let r = x[1]
    let theta = x[2]
    let sth = dg_sin(theta)

    var r_safe = r
    if dg_abs(r_safe) < 1.0e-10 { r_safe = 1.0e-10 }
    let f = 1.0 - 2.0 / r_safe

    if dg_abs(f) < 1.0e-30 {
        g[0] = -1.0e-30
        g[5] = 1.0e30
    } else {
        g[0] = 0.0 - f
        g[5] = 1.0 / f
    }
    g[10] = r_safe * r_safe
    g[15] = r_safe * r_safe * sth * sth
}

fn metric_hyperbolic_2d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }

    var y = x[1]
    if y < 1.0e-10 { y = 1.0e-10 }
    let inv_y2 = 1.0 / (y * y)

    g[0] = inv_y2
    g[3] = inv_y2
}

fn metric_euclidean_2d(x: &[f64; 4], dim: i32, g: &![f64; 16]) with Mut, Div, Panic {
    var i = 0
    while i < 16 { g[i] = 0.0; i = i + 1 }
    g[0] = 1.0
    g[3] = 1.0
}

fn test_euclidean_metric_identity() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_euclidean_3d(&x, 3, &!g)

    let tol = 1.0e-12

    // Check diagonal elements are 1
    if dg_abs(g[0] - 1.0) > tol { return false }
    if dg_abs(g[4] - 1.0) > tol { return false }
    if dg_abs(g[8] - 1.0) > tol { return false }

    // Check off-diagonal elements are 0
    if dg_abs(g[1]) > tol { return false }
    if dg_abs(g[2]) > tol { return false }
    if dg_abs(g[3]) > tol { return false }
    if dg_abs(g[5]) > tol { return false }
    if dg_abs(g[6]) > tol { return false }
    if dg_abs(g[7]) > tol { return false }

    true
}

fn test_euclidean_metric_inverse() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_euclidean_3d(&x, 3, &!g)

    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g, 3, &!g_inv)

    let tol = 1.0e-12

    // Inverse of identity is identity
    if dg_abs(g_inv[0] - 1.0) > tol { return false }
    if dg_abs(g_inv[4] - 1.0) > tol { return false }
    if dg_abs(g_inv[8] - 1.0) > tol { return false }

    if dg_abs(g_inv[1]) > tol { return false }
    if dg_abs(g_inv[2]) > tol { return false }
    if dg_abs(g_inv[3]) > tol { return false }
    if dg_abs(g_inv[5]) > tol { return false }
    if dg_abs(g_inv[6]) > tol { return false }
    if dg_abs(g_inv[7]) > tol { return false }

    true
}

fn test_flat_christoffel_zero() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var gamma: Christoffel4 = Christoffel4 { gamma: [0.0; 64], c4_dim: 3 }
    christoffel_from_metric(metric_euclidean_3d, &x, 3, &!gamma)

    let tol = 1.0e-4

    // All 27 Christoffel symbols should be zero for flat space
    var k = 0
    while k < 3 {
        var i = 0
        while i < 3 {
            var j = 0
            while j < 3 {
                if dg_abs(gamma.gamma[k * 9 + i * 3 + j]) > tol { return false }
                j = j + 1
            }
            i = i + 1
        }
        k = k + 1
    }

    true
}

fn test_flat_riemann_zero() -> bool with Mut, Div, Panic {
    var x: [f64; 4] = [1.0, 2.0, 3.0, 0.0]
    var Riem: RiemannTensor = RiemannTensor { R: [0.0; 256], rt_dim: 3 }
    riemann_tensor(metric_euclidean_3d, &x, 3, &!Riem)

    let tol = 1.0e-4

    // All 81 components R^k_{lij} should be zero
    var k = 0
    while k < 3 {
        var l = 0
        while l < 3 {
            var i = 0
            while i < 3 {
                var j = 0
                while j < 3 {
                    if dg_abs(Riem.R[k * 27 + l * 9 + i * 3 + j]) > tol { return false }
                    j = j + 1
                }
                i = i + 1
            }
            l = l + 1
        }
        k = k + 1
    }

    true
}

fn test_sphere_gauss_curvature() -> bool with Mut, Div, Panic {
    // Evaluate at theta = pi/3, phi = pi/4 (away from poles)
    let theta = dg_pi() / 3.0
    let phi = dg_pi() / 4.0
    var x: [f64; 4] = [theta, phi, 0.0, 0.0]

    let K = gauss_curvature_2d(metric_sphere_2d, &x)

    let tol = 1.0e-4
    dg_abs(K - 1.0) < tol
}

fn test_sphere_metric_equator() -> bool with Mut, Div, Panic {
    let theta = dg_pi() / 2.0
    var x: [f64; 4] = [theta, 0.0, 0.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_sphere_2d(&x, 2, &!g)

    let tol = 1.0e-10

    // g_{theta theta} = 1
    if dg_abs(g[0] - 1.0) > tol { return false }
    // g_{phi phi} = sin^2(pi/2) = 1
    if dg_abs(g[3] - 1.0) > tol { return false }
    // off-diagonal = 0
    if dg_abs(g[1]) > tol { return false }
    if dg_abs(g[2]) > tol { return false }

    true
}

fn test_schwarzschild_r10() -> bool with Mut, Div, Panic {
    // x = (t, r, theta, phi) = (0, 10, pi/2, 0)
    let theta = dg_pi() / 2.0
    var x: [f64; 4] = [0.0, 10.0, theta, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_schwarzschild(&x, 4, &!g)

    let tol = 1.0e-10

    // g_tt = -(1 - 2/10) = -0.8
    let expected_gtt = 0.0 - 0.8
    if dg_abs(g[0] - expected_gtt) > tol { return false }

    // g_rr = 1/(1 - 2/10) = 1.25
    let expected_grr = 1.25
    if dg_abs(g[5] - expected_grr) > tol { return false }

    // g_{theta theta} = r^2 = 100
    if dg_abs(g[10] - 100.0) > tol { return false }

    // g_{phi phi} = r^2 sin^2(pi/2) = 100
    if dg_abs(g[15] - 100.0) > tol { return false }

    true
}

fn test_geodesic_flat_straight_line() -> bool with Mut, Div, Panic {
    let dim = 2
    var x0: [f64; 4] = [0.0, 0.0, 0.0, 0.0]
    var v0: [f64; 4] = [1.0, 2.0, 0.0, 0.0]

    let tau_end = 1.0
    let n_steps = 100

    var path: GeodesicPath = GeodesicPath {
        x: [0.0; 256], gp_v: [0.0; 256], gp_tau: [0.0; 128],
        n_steps: 0, gp_dim: 0
    }
    geodesic_integrate(metric_euclidean_2d, &x0, &v0, dim, tau_end, n_steps, &!path)

    let tol = 1.0e-4

    // Check final position: should be (1.0, 2.0)
    let final_x = path.x[n_steps * dim + 0]
    let final_y = path.x[n_steps * dim + 1]

    if dg_abs(final_x - 1.0) > tol { return false }
    if dg_abs(final_y - 2.0) > tol { return false }

    // Check intermediate point at step 50: should be (0.5, 1.0)
    let mid_x = path.x[50 * dim + 0]
    let mid_y = path.x[50 * dim + 1]

    if dg_abs(mid_x - 0.5) > tol { return false }
    if dg_abs(mid_y - 1.0) > tol { return false }

    true
}

fn test_parallel_transport_preserves_norm() -> bool with Mut, Div, Panic {
    let dim = 2
    var x0: [f64; 4] = [0.0, 0.0, 0.0, 0.0]
    var v0: [f64; 4] = [1.0, 0.0, 0.0, 0.0]

    let tau_end = 1.0
    let n_steps = 100

    var path: GeodesicPath = GeodesicPath {
        x: [0.0; 256], gp_v: [0.0; 256], gp_tau: [0.0; 128],
        n_steps: 0, gp_dim: 0
    }
    geodesic_integrate(metric_euclidean_2d, &x0, &v0, dim, tau_end, n_steps, &!path)

    // Transport w0 = (3, 4) along this geodesic
    var w0: [f64; 4] = [3.0, 4.0, 0.0, 0.0]
    var w_final: [f64; 4] = [0.0; 4]
    parallel_transport_along(metric_euclidean_2d, &path, &w0, &!w_final)

    // Initial norm: sqrt(9 + 16) = 5
    let norm0 = dg_sqrt(w0[0] * w0[0] + w0[1] * w0[1])
    let norm_final = dg_sqrt(w_final[0] * w_final[0] + w_final[1] * w_final[1])

    let tol = 1.0e-4
    dg_abs(norm_final - norm0) < tol
}

fn test_hyperbolic_curvature() -> bool with Mut, Div, Panic {
    // Evaluate at (x, y) = (1.0, 2.0) -- well inside the half-plane
    var x: [f64; 4] = [1.0, 2.0, 0.0, 0.0]

    let K = gauss_curvature_2d(metric_hyperbolic_2d, &x)

    let tol = 1.0e-4
    let expected = 0.0 - 1.0
    dg_abs(K - expected) < tol
}

fn test_sphere_metric_determinant() -> bool with Mut, Div, Panic {
    let theta = dg_pi() / 4.0
    var x: [f64; 4] = [theta, 0.0, 0.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_sphere_2d(&x, 2, &!g)

    let det = metric_det(&g, 2)

    // sin^2(pi/4) = (sqrt(2)/2)^2 = 0.5
    let expected = 0.5
    let tol = 1.0e-10

    dg_abs(det - expected) < tol
}

fn test_raise_lower_roundtrip() -> bool with Mut, Div, Panic {
    // Non-trivial test: sphere metric at theta = pi/3
    let theta = dg_pi() / 3.0
    var x: [f64; 4] = [theta, 0.0, 0.0, 0.0]
    var g: [f64; 16] = [0.0; 16]
    metric_sphere_2d(&x, 2, &!g)

    var g_inv: [f64; 16] = [0.0; 16]
    metric_inverse(&g, 2, &!g_inv)

    // Original vector v^i = (1.0, 2.0)
    var v_upper: [f64; 4] = [1.0, 2.0, 0.0, 0.0]

    // Lower: v_i = g_{ij} v^j
    var v_lower: [f64; 4] = [0.0; 4]
    metric_lower_index(&g, &v_upper, 2, &!v_lower)

    // Raise back: v'^i = g^{ij} v_j
    var v_raised: [f64; 4] = [0.0; 4]
    metric_raise_index(&g_inv, &v_lower, 2, &!v_raised)

    let tol = 1.0e-10

    // v_raised should equal v_upper
    if dg_abs(v_raised[0] - v_upper[0]) > tol { return false }
    if dg_abs(v_raised[1] - v_upper[1]) > tol { return false }

    true
}

fn fe_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn fem_1d_stiffness(x1: f64, x2: f64, EA: f64, ke: &![f64; 4]) with Mut, Div, Panic {
    let L = fe_abs(x2 - x1)
    let k = EA / L
    ke[0] = k
    ke[1] = 0.0 - k
    ke[2] = 0.0 - k
    ke[3] = k
}

fn fem_1d_mass(x1: f64, x2: f64, rho_A: f64, me: &![f64; 4]) with Mut, Div, Panic {
    let L = fe_abs(x2 - x1)
    let c = rho_A * L / 6.0
    me[0] = 2.0 * c
    me[1] = c
    me[2] = c
    me[3] = 2.0 * c
}

fn fem_1d_load(x1: f64, x2: f64, q: f64, fe: &![f64; 2]) with Mut, Div, Panic {
    let L = fe_abs(x2 - x1)
    let c = q * L / 2.0
    fe[0] = c
    fe[1] = c
}

fn fem_tri_area(x1: f64, y1: f64, x2: f64, y2: f64, x3: f64, y3: f64) -> f64 with Mut, Div {
    let det = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)
    0.5 * fe_abs(det)
}

fn fem_tri_stiffness(x1: f64, y1: f64, x2: f64, y2: f64, x3: f64, y3: f64,
                     D: &[f64; 9], thickness: f64, ke: &![f64; 36]) with Mut, Div, Panic {
    let A = fem_tri_area(x1, y1, x2, y2, x3, y3)

    var B: [f64; 18] = [0.0; 18]
    fem_tri_grad(x1, y1, x2, y2, x3, y3, &!B)

    var DB: [f64; 18] = [0.0; 18]
    var i = 0
    while i < 3 {
        var j = 0
        while j < 6 {
            var s = 0.0
            var k = 0
            while k < 3 {
                s = s + D[i * 3 + k] * B[k * 6 + j]
                k = k + 1
            }
            DB[i * 6 + j] = s
            j = j + 1
        }
        i = i + 1
    }

    let scale = thickness * A
    i = 0
    while i < 6 {
        var j = 0
        while j < 6 {
            var s = 0.0
            var k = 0
            while k < 3 {
                s = s + B[k * 6 + i] * DB[k * 6 + j]
                k = k + 1
            }
            ke[i * 6 + j] = scale * s
            j = j + 1
        }
        i = i + 1
    }
}

fn fem_apply_dirichlet_penalty(K: &![f64; 4096], F: &![f64; 256],
                               n_dof: i32, dof: i32, value: f64) with Mut, Panic {
    let penalty = 1.0e20
    K[dof * n_dof + dof] = K[dof * n_dof + dof] + penalty
    F[dof] = F[dof] + penalty * value
}

fn fem_solve_direct(K: &[f64; 4096], F: &[f64; 256], n_dof: i32,
                    u: &![f64; 256]) with Mut, Div, Panic {
    var A: [f64; 4096] = [0.0; 4096]
    var b: [f64; 256] = [0.0; 256]

    var idx = 0
    while idx < n_dof * n_dof { A[idx] = K[idx]; idx = idx + 1 }
    idx = 0
    while idx < n_dof { b[idx] = F[idx]; idx = idx + 1 }

    var col = 0
    while col < n_dof {
        var max_val = fe_abs(A[col * n_dof + col])
        var max_row = col
        var row = col + 1
        while row < n_dof {
            let v = fe_abs(A[row * n_dof + col])
            if v > max_val {
                max_val = v
                max_row = row
            }
            row = row + 1
        }

        if max_row != col {
            var j = 0
            while j < n_dof {
                let temp = A[col * n_dof + j]
                A[col * n_dof + j] = A[max_row * n_dof + j]
                A[max_row * n_dof + j] = temp
                j = j + 1
            }
            let temp_b = b[col]
            b[col] = b[max_row]
            b[max_row] = temp_b
        }

        let pivot = A[col * n_dof + col]
        if fe_abs(pivot) < 1.0e-30 {
            u[col] = 0.0
            col = col + 1
            var skip = col
            while skip < n_dof {
                A[skip * n_dof + (col - 1)] = 0.0
                skip = skip + 1
            }
        }

        row = col + 1
        while row < n_dof {
            let pivot_val = A[col * n_dof + col]
            if fe_abs(pivot_val) > 1.0e-30 {
                let factor = A[row * n_dof + col] / pivot_val
                var j = col
                while j < n_dof {
                    A[row * n_dof + j] = A[row * n_dof + j] - factor * A[col * n_dof + j]
                    j = j + 1
                }
                b[row] = b[row] - factor * b[col]
            }
            row = row + 1
        }

        col = col + 1
    }

    var i = n_dof - 1
    while i >= 0 {
        var s = b[i]
        var j = i + 1
        while j < n_dof {
            s = s - A[i * n_dof + j] * u[j]
            j = j + 1
        }
        let diag = A[i * n_dof + i]
        if fe_abs(diag) > 1.0e-30 {
            u[i] = s / diag
        } else {
            u[i] = 0.0
        }
        i = i - 1
    }
}

fn fe_matvec(K: &[f64; 4096], x: &[f64; 256], n: i32, y: &![f64; 256]) with Mut, Div, Panic {
    var i = 0
    while i < n {
        var s = 0.0
        var j = 0
        while j < n {
            s = s + K[i * n + j] * x[j]
            j = j + 1
        }
        y[i] = s
        i = i + 1
    }
}

fn fe_dot(a: &[f64; 256], b: &[f64; 256], n: i32) -> f64 with Mut, Div, Panic {
    var s = 0.0
    var i = 0
    while i < n {
        s = s + a[i] * b[i]
        i = i + 1
    }
    s
}

fn fem_solve_cg(K: &[f64; 4096], F: &[f64; 256], n_dof: i32,
                u: &![f64; 256], max_iter: i32, tol: f64) -> bool with Mut, Div, Panic {
    var i = 0
    while i < n_dof { u[i] = 0.0; i = i + 1 }

    var r: [f64; 256] = [0.0; 256]
    i = 0
    while i < n_dof { r[i] = F[i]; i = i + 1 }

    var p: [f64; 256] = [0.0; 256]
    i = 0
    while i < n_dof { p[i] = r[i]; i = i + 1 }

    var rr_old = fe_dot(&r, &r, n_dof)

    let F_norm = fe_sqrt(fe_dot(F, F, n_dof))
    let abs_tol = if F_norm > 1.0e-30 { tol * F_norm } else { tol }

    var Kp: [f64; 256] = [0.0; 256]

    var iter = 0
    while iter < max_iter {
        let r_norm = fe_sqrt(rr_old)
        if r_norm < abs_tol {
            return true
        }

        fe_matvec(K, &p, n_dof, &!Kp)

        let pKp = fe_dot(&p, &Kp, n_dof)
        if fe_abs(pKp) < 1.0e-30 {
            return false
        }
        let alpha = rr_old / pKp

        i = 0
        while i < n_dof {
            u[i] = u[i] + alpha * p[i]
            r[i] = r[i] - alpha * Kp[i]
            i = i + 1
        }

        let rr_new = fe_dot(&r, &r, n_dof)
        let beta = rr_new / rr_old

        i = 0
        while i < n_dof {
            p[i] = r[i] + beta * p[i]
            i = i + 1
        }

        rr_old = rr_new
        iter = iter + 1
    }

    false
}

fn fem_mesh_1d_uniform(x_start: f64, x_end: f64, n_elem: i32,
                       mesh: &!FEMesh1D) with Mut, Div, Panic {
    let n_nodes = n_elem + 1
    mesh.n_nodes = n_nodes
    mesh.n_elem = n_elem
    mesh.nodes_per_elem = 2

    let h = (x_end - x_start) / (n_elem as f64)
    var i = 0
    while i < n_nodes {
        mesh.nodes[i] = x_start + (i as f64) * h
        i = i + 1
    }

    var e = 0
    while e < n_elem {
        mesh.elements[2 * e] = e
        mesh.elements[2 * e + 1] = e + 1
        e = e + 1
    }
}

fn fem_mesh_2d_rect(x0: f64, y0: f64, x1: f64, y1: f64, nx: i32, ny: i32,
                    mesh: &!FEMesh2D) with Mut, Div, Panic {
    let n_nodes = (nx + 1) * (ny + 1)
    let n_elem = 2 * nx * ny
    mesh.n_nodes = n_nodes
    mesh.n_elem = n_elem
    mesh.nodes_per_elem = 3

    let dx = (x1 - x0) / (nx as f64)
    let dy = (y1 - y0) / (ny as f64)

    var iy = 0
    while iy <= ny {
        var ix = 0
        while ix <= nx {
            let node_id = iy * (nx + 1) + ix
            mesh.nodes_x[node_id] = x0 + (ix as f64) * dx
            mesh.nodes_y[node_id] = y0 + (iy as f64) * dy
            ix = ix + 1
        }
        iy = iy + 1
    }

    var elem_id = 0
    iy = 0
    while iy < ny {
        var ix = 0
        while ix < nx {
            let bl = iy * (nx + 1) + ix
            let br = iy * (nx + 1) + ix + 1
            let tl = (iy + 1) * (nx + 1) + ix
            let tr = (iy + 1) * (nx + 1) + ix + 1

            mesh.elements[3 * elem_id] = bl
            mesh.elements[3 * elem_id + 1] = br
            mesh.elements[3 * elem_id + 2] = tl
            elem_id = elem_id + 1

            mesh.elements[3 * elem_id] = br
            mesh.elements[3 * elem_id + 1] = tr
            mesh.elements[3 * elem_id + 2] = tl
            elem_id = elem_id + 1

            ix = ix + 1
        }
        iy = iy + 1
    }
}

fn fem_system_init(n_dof: i32, sys: &!FESystem) with Mut, Div, Panic {
    sys.n_dof = n_dof

    var i = 0
    while i < n_dof * n_dof { sys.K[i] = 0.0; i = i + 1 }

    i = 0
    while i < n_dof * n_dof { sys.M[i] = 0.0; i = i + 1 }

    i = 0
    while i < n_dof { sys.rhs[i] = 0.0; i = i + 1 }

    i = 0
    while i < n_dof { sys.solution[i] = 0.0; i = i + 1 }
}

fn test_1d_stiffness_symmetry() -> bool with Mut, Div, Panic {
    let tol = 1.0e-6
    let EA = 200.0e3
    let x1 = 0.0
    let x2 = 2.5

    var ke: [f64; 4] = [0.0; 4]
    fem_1d_stiffness(x1, x2, EA, &!ke)

    // ke is 2x2 row-major: ke[1] = K(0,1), ke[2] = K(1,0)
    let diff = fe_abs(ke[1] - ke[2])
    if diff > tol { return false }
    true
}

fn test_1d_stiffness_trace() -> bool with Mut, Div, Panic {
    let tol = 1.0e-6
    let EA = 150.0e3
    let x1 = 1.0
    let x2 = 4.0
    let L = fe_abs(x2 - x1)

    var ke: [f64; 4] = [0.0; 4]
    fem_1d_stiffness(x1, x2, EA, &!ke)

    let trace = ke[0] + ke[3]
    let expected = 2.0 * EA / L
    let diff = fe_abs(trace - expected)
    if diff > tol { return false }
    true
}

fn test_1d_mass_positive() -> bool with Mut, Div, Panic {
