    let E = 200.0e9
    let nu = 0.3

    var D: [f64; 9] = [0.0; 9]
    fem_plane_stress(E, nu, &!D)

    // D is 3x3 row-major: D[1] = D(0,1), D[3] = D(1,0)
    let diff01 = fe_abs(D[1] - D[3])
    if diff01 > tol { return false }

    // Also check D(0,2) = D(2,0) and D(1,2) = D(2,1)
    let diff02 = fe_abs(D[2] - D[6])
    if diff02 > tol { return false }

    let diff12 = fe_abs(D[5] - D[7])
    if diff12 > tol { return false }

    true
}

fn test_1d_bar_exact() -> bool with Mut, Div, Panic {
    let tol = 1.0e-6
    let L = 10.0
    let EA = 1.0e5
    let q = 100.0
    let n_elem = 4

    // Create mesh
    var mesh: FEMesh1D = FEMesh1D {
        nodes: [0.0; 256], n_nodes: 0,
        elements: [0; 512], n_elem: 0, nodes_per_elem: 2
    }
    fem_mesh_1d_uniform(0.0, L, n_elem, &!mesh)

    let n = mesh.n_nodes

    // Assemble K and F
    var K: [f64; 4096] = [0.0; 4096]
    var F: [f64; 256] = [0.0; 256]
    fem_assemble_stiffness_1d(&mesh, EA, &!K)
    fem_assemble_load_1d(&mesh, q, &!F)

    // Apply Dirichlet BC: u(0) = 0 via penalty
    fem_apply_dirichlet_penalty(&!K, &!F, n, 0, 0.0)

    // Solve
    var u: [f64; 256] = [0.0; 256]
    fem_solve_direct(&K, &F, n, &!u)

    // Compare each node to analytical solution: u(x) = q*x*(2L - x) / (2*EA)
    var ok = true
    var i = 0
    while i < n {
        let x = mesh.nodes[i]
        let u_exact = q * x * (2.0 * L - x) / (2.0 * EA)
        let diff = fe_abs(u[i] - u_exact)
        // Use relative tolerance for non-zero values
        if fe_abs(u_exact) > 1.0e-12 {
            if diff / fe_abs(u_exact) > tol { ok = false }
        } else {
            if diff > tol { ok = false }
        }
        i = i + 1
    }

    ok
}

fn test_2d_patch_test() -> bool with Mut, Div, Panic {
    let tol = 1.0e-4
    let E = 1.0e6
    let nu = 0.25
    let thickness = 1.0
    let exx = 0.001

    // Create 1x1 mesh (2 elements, 4 nodes)
    var mesh: FEMesh2D = FEMesh2D {
        nodes_x: [0.0; 256], nodes_y: [0.0; 256], n_nodes: 0,
        elements: [0; 1536], n_elem: 0, nodes_per_elem: 3
    }
    fem_mesh_2d_rect(0.0, 0.0, 1.0, 1.0, 1, 1, &!mesh)

    // Constitutive matrix
    var D: [f64; 9] = [0.0; 9]
    fem_plane_stress(E, nu, &!D)

    // Prescribed displacement: u_x = exx * x, u_y = 0
    // Nodes from fem_mesh_2d_rect(0,0,1,1,1,1):
    //   node 0 = (0,0), node 1 = (1,0), node 2 = (0,1), node 3 = (1,1)
    // DOF: [u_x0, u_y0, u_x1, u_y1, u_x2, u_y2, u_x3, u_y3]
    var u_disp: [f64; 256] = [0.0; 256]
    var nd = 0
    while nd < mesh.n_nodes {
        u_disp[2 * nd] = exx * mesh.nodes_x[nd]
        u_disp[2 * nd + 1] = 0.0
        nd = nd + 1
    }

    // Expected stress
    let c = E / (1.0 - nu * nu)
    let sxx_expected = c * exx
    let syy_expected = c * nu * exx
    let sxy_expected = 0.0

    // Check stress in each element
    var ok = true
    var e = 0
    while e < mesh.n_elem {
        var sr: StressResult = StressResult {
            sxx: 0.0, syy: 0.0, sxy: 0.0, von_mises: 0.0
        }
        fem_stress_at_centroid(&mesh, &u_disp, &D, e, &!sr)

        if fe_abs(sr.sxx - sxx_expected) > tol * fe_abs(sxx_expected) { ok = false }
        if fe_abs(sr.syy - syy_expected) > tol * fe_abs(syy_expected) { ok = false }
        if fe_abs(sr.sxy - sxy_expected) > tol { ok = false }

        e = e + 1
    }

    ok
}

fn test_cg_matches_direct() -> bool with Mut, Div, Panic {
    // Use a well-conditioned 4x4 tridiagonal SPD system:
    //   K = [[2,-1,0,0],[-1,2,-1,0],[0,-1,2,-1],[0,0,-1,2]]
    //   F = [1,1,1,1]
    // Condition number ~16 → CG converges in ≤4 iterations (exact)
    let tol = 1.0e-8
    let n = 4

    var K: [f64; 4096] = [0.0; 4096]
    var F: [f64; 256] = [0.0; 256]

    // Build tridiagonal K
    var i = 0
    while i < n {
        K[i * n + i] = 2.0
        if i > 0 { K[i * n + (i - 1)] = -1.0 }
        if i < n - 1 { K[i * n + (i + 1)] = -1.0 }
        F[i] = 1.0
        i = i + 1
    }

    // Direct solve
    var u_direct: [f64; 256] = [0.0; 256]
    fem_solve_direct(&K, &F, n, &!u_direct)

    // CG solve
    var u_cg: [f64; 256] = [0.0; 256]
    let cg_converged = fem_solve_cg(&K, &F, n, &!u_cg, 100, 1.0e-12)

    if !cg_converged { return false }

    // Compare solutions
    var ok = true
    i = 0
    while i < n {
        let diff = fe_abs(u_direct[i] - u_cg[i])
        if fe_abs(u_direct[i]) > 1.0e-12 {
            if diff / fe_abs(u_direct[i]) > tol { ok = false }
        } else {
            if diff > tol { ok = false }
        }
        i = i + 1
    }
    ok
}

fn test_dirichlet_penalty() -> bool with Mut, Div, Panic {
    let n = 4
    // Build a small stiffness matrix (identity-like for simplicity)
    var K: [f64; 4096] = [0.0; 4096]
    var F: [f64; 256] = [0.0; 256]
    var i = 0
    while i < n {
        K[i * n + i] = 1.0e3
        F[i] = 100.0
        i = i + 1
    }

    // Apply Dirichlet at DOF 1 with value 0.0
    fem_apply_dirichlet_penalty(&!K, &!F, n, 1, 0.0)

    // K[1][1] should now be 1e3 + 1e20 ~ 1e20
    let diag = K[1 * n + 1]

    // Check that the diagonal is orders of magnitude larger than off-diags
    var ok = true
    var j = 0
    while j < n {
        if j != 1 {
            let off = fe_abs(K[1 * n + j])
            // The penalty-augmented diagonal should dominate
            if off > 0.0 {
                if diag / off < 1.0e10 { ok = false }
            }
        }
        j = j + 1
    }

    // Also check the diagonal is at least 1e15 (penalty = 1e20)
    if diag < 1.0e15 { ok = false }

    ok
}

fn test_mesh_1d_counts() -> bool with Mut, Div, Panic {
    let n_elem = 8

    var mesh: FEMesh1D = FEMesh1D {
        nodes: [0.0; 256], n_nodes: 0,
        elements: [0; 512], n_elem: 0, nodes_per_elem: 2
    }
    fem_mesh_1d_uniform(0.0, 10.0, n_elem, &!mesh)

    // n_nodes should be n_elem + 1 = 9
    if mesh.n_nodes != n_elem + 1 { return false }

    // n_elem should be 8
    if mesh.n_elem != n_elem { return false }

    // nodes_per_elem should be 2
    if mesh.nodes_per_elem != 2 { return false }

    // Check first and last node positions
    let tol = 1.0e-6
    if fe_abs(mesh.nodes[0] - 0.0) > tol { return false }
    if fe_abs(mesh.nodes[n_elem] - 10.0) > tol { return false }

    // Check uniform spacing: h = 10/8 = 1.25
    let h = 10.0 / (n_elem as f64)
    var i = 0
    while i < mesh.n_nodes {
        let expected = (i as f64) * h
        if fe_abs(mesh.nodes[i] - expected) > tol { return false }
        i = i + 1
    }

    true
}

fn fa_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    // Start from a good initial guess: scale down to near sqrt(x) by halving
    var y = x
    while y * y > x * 4.0 { y = y * 0.5 }
    var i = 0
    while i < 60 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn fa_exp(x: f64) -> f64 with Mut, Div, Panic {
    if x > 500.0 { return 1.0e200 }
    if x < -500.0 { return 0.0 }
    var kf = x / 0.6931471805599453
    var k: i32 = 0
    if kf >= 0.0 { k = kf as i32 } else { k = (kf as i32) - 1 }
    let r = x - (k as f64) * 0.6931471805599453
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 25 { term = term * r / (n as f64); sum = sum + term; n = n + 1 }
    var result = sum
    if k >= 0 { var i = 0; while i < k { result = result * 2.0; i = i + 1 } }
    else { var i = 0; while i < (0 - k) { result = result / 2.0; i = i + 1 } }
    result
}

fn fa_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if x == 1.0 { return 0.0 }
    var m = x
    var e = 0
    while m >= 2.0 { m = m / 2.0; e = e + 1 }
    while m < 0.5 { m = m * 2.0; e = e - 1 }
    let t = (m - 1.0) / (m + 1.0)
    let t2 = t * t
    var sum = t
    var term = t
    var k = 1
    while k < 30 { term = term * t2; sum = sum + term / ((2 * k + 1) as f64); k = k + 1 }
    2.0 * sum + (e as f64) * 0.6931471805599453
}

fn fa_sin(x: f64) -> f64 with Mut, Div, Panic {
    var a = x
    let tp = 6.28318530717958647692
    while a >= tp { a = a - tp }
    while a < 0.0 { a = a + tp }
    if a > 3.14159265358979323846 { a = a - tp }
    let a2 = a * a
    var sum = a
    var term = a
    var n = 1
    while n < 18 { term = 0.0 - term * a2 / ((2 * n) * (2 * n + 1)) as f64; sum = sum + term; n = n + 1 }
    sum
}

fn fa_cos(x: f64) -> f64 with Mut, Div, Panic {
    fa_sin(x + 1.57079632679489661923)
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    fa_abs(a - b) < tol
}

fn approx_rel(a: f64, b: f64, tol: f64) -> bool {
    let denom = fa_max(fa_abs(a), fa_abs(b))
    if denom < 1.0e-30 { return fa_abs(a - b) < tol }
    fa_abs(a - b) / denom < tol
}

fn fa_dot(a: &[f64; 4096], b: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var sum = 0.0
    var i = 0
    while i < n { sum = sum + a[i] * b[i]; i = i + 1 }
    sum
}

fn fa_norm2(v: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var sum = 0.0
    var i = 0
    while i < n { sum = sum + v[i] * v[i]; i = i + 1 }
    fa_sqrt(sum)
}

fn fa_matvec(A: &[f64; 4096], x: &[f64; 4096], n: i32, out: &![f64; 4096]) with Mut, Div, Panic {
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < n {
            sum = sum + A[i * n + j] * x[j]
            j = j + 1
        }
        out[i] = sum
        i = i + 1
    }
}

fn fa_gauss_solve(A: &[f64; 4096], b: &[f64; 4096], n: i32, x: &![f64; 4096]) with Mut, Div, Panic {
    var work: [f64; 4096] = [0.0; 4096]
    let nc = n + 1
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            work[i * nc + j] = A[i * n + j]
            j = j + 1
        }
        work[i * nc + n] = b[i]
        i = i + 1
    }

    var col = 0
    while col < n {
        var max_val = fa_abs(work[col * nc + col])
        var max_row = col
        var row = col + 1
        while row < n {
            let v = fa_abs(work[row * nc + col])
            if v > max_val { max_val = v; max_row = row }
            row = row + 1
        }
        if max_row != col {
            var j = 0
            while j < nc {
                let tmp = work[col * nc + j]
                work[col * nc + j] = work[max_row * nc + j]
                work[max_row * nc + j] = tmp
                j = j + 1
            }
        }
        let pivot = work[col * nc + col]
        if fa_abs(pivot) < 1.0e-30 {
            x[col] = 0.0
        } else {
            row = col + 1
            while row < n {
                let factor = work[row * nc + col] / pivot
                var j = col
                while j < nc {
                    work[row * nc + j] = work[row * nc + j] - factor * work[col * nc + j]
                    j = j + 1
                }
                row = row + 1
            }
        }
        col = col + 1
    }

    i = n - 1
    while i >= 0 {
        var sum = work[i * nc + n]
        var j = i + 1
        while j < n {
            sum = sum - work[i * nc + j] * x[j]
            j = j + 1
        }
        let diag = work[i * nc + i]
        if fa_abs(diag) < 1.0e-30 { x[i] = 0.0 }
        else { x[i] = sum / diag }
        i = i - 1
    }
}

fn op_norm_1(A: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var best = 0.0
    var j = 0
    while j < n {
        var col_sum = 0.0
        var i = 0
        while i < n {
            col_sum = col_sum + fa_abs(A[i * n + j])
            i = i + 1
        }
        if col_sum > best { best = col_sum }
        j = j + 1
    }
    best
}

fn op_norm_inf(A: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var best = 0.0
    var i = 0
    while i < n {
        var row_sum = 0.0
        var j = 0
        while j < n {
            row_sum = row_sum + fa_abs(A[i * n + j])
            j = j + 1
        }
        if row_sum > best { best = row_sum }
        i = i + 1
    }
    best
}

fn op_norm_frobenius(A: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var sum = 0.0
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            let v = A[i * n + j]
            sum = sum + v * v
            j = j + 1
        }
        i = i + 1
    }
    fa_sqrt(sum)
}

fn op_norm_2(A: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var B: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            var sum = 0.0
            var k = 0
            while k < n {
                sum = sum + A[k * n + i] * A[k * n + j]
                k = k + 1
            }
            B[i * n + j] = sum
            j = j + 1
        }
        i = i + 1
    }

    var v: [f64; 4096] = [0.0; 4096]
    let inv_sqrtn = 1.0 / fa_sqrt(n as f64)
    i = 0
    while i < n { v[i] = inv_sqrtn; i = i + 1 }

    var w: [f64; 4096] = [0.0; 4096]
    var eigenvalue = 0.0

    var iter = 0
    while iter < 500 {
        fa_matvec(&B, &v, n, &!w)
        eigenvalue = fa_dot(&v, &w, n)
        let nrm = fa_norm2(&w, n)
        if nrm < 1.0e-30 { return 0.0 }
        i = 0
        while i < n { v[i] = w[i] / nrm; i = i + 1 }
        iter = iter + 1
    }

    if eigenvalue < 0.0 { return 0.0 }
    fa_sqrt(eigenvalue)
}

fn spectral_radius(A: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var v: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i < n {
        v[i] = 1.0 / ((i + 1) as f64)
        i = i + 1
    }
    let init_norm = fa_norm2(&v, n)
    if init_norm > 0.0 {
        i = 0
        while i < n { v[i] = v[i] / init_norm; i = i + 1 }
    }

    var w: [f64; 4096] = [0.0; 4096]
    var lambda = 0.0

    var iter = 0
    while iter < 500 {
        fa_matvec(A, &v, n, &!w)
        lambda = fa_dot(&v, &w, n)
        let nrm = fa_norm2(&w, n)
        if nrm < 1.0e-30 { return 0.0 }
        i = 0
        while i < n { v[i] = w[i] / nrm; i = i + 1 }
        iter = iter + 1
    }

    fa_abs(lambda)
}

fn condition_number(A: &[f64; 4096], n: i32) -> f64 with Mut, Div, Panic {
    var B: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            var sum = 0.0
            var k = 0
            while k < n {
                sum = sum + A[k * n + i] * A[k * n + j]
                k = k + 1
            }
            B[i * n + j] = sum
            j = j + 1
        }
        i = i + 1
    }

    // Largest eigenvalue via power iteration
    var v: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n { v[i] = 1.0 / ((i + 1) as f64); i = i + 1 }
    let init_n = fa_norm2(&v, n)
    if init_n > 0.0 {
        i = 0
        while i < n { v[i] = v[i] / init_n; i = i + 1 }
    }

    var w: [f64; 4096] = [0.0; 4096]
    var lambda_max = 0.0
    var iter = 0
    while iter < 300 {
        fa_matvec(&B, &v, n, &!w)
        lambda_max = fa_dot(&v, &w, n)
        let nrm = fa_norm2(&w, n)
        if nrm < 1.0e-30 { return 1.0e30 }
        i = 0
        while i < n { v[i] = w[i] / nrm; i = i + 1 }
        iter = iter + 1
    }

    // Smallest eigenvalue via inverse iteration
    i = 0
    while i < n { v[i] = 1.0 / ((i + 1) as f64); i = i + 1 }
    let init_n2 = fa_norm2(&v, n)
    if init_n2 > 0.0 {
        i = 0
        while i < n { v[i] = v[i] / init_n2; i = i + 1 }
    }

    var lambda_min = lambda_max
    iter = 0
    while iter < 300 {
        fa_gauss_solve(&B, &v, n, &!w)
        let nrm = fa_norm2(&w, n)
        if nrm < 1.0e-30 { return 1.0e30 }
        var bw: [f64; 4096] = [0.0; 4096]
        fa_matvec(&B, &w, n, &!bw)
        let rq = fa_dot(&w, &bw, n) / (nrm * nrm)
        lambda_min = rq
        i = 0
        while i < n { v[i] = w[i] / nrm; i = i + 1 }
        iter = iter + 1
    }

    if lambda_min < 1.0e-30 { return 1.0e30 }
    if lambda_max < 0.0 { return 1.0e30 }
    if lambda_min < 0.0 { return 1.0e30 }
    fa_sqrt(lambda_max / lambda_min)
}

fn fa_simpson(vals: &[f64; 4096], a: f64, b: f64, n_quad: i32) -> f64 with Mut, Div, Panic {
    let h = (b - a) / (n_quad as f64)
    var sum = vals[0] + vals[n_quad]
    var i = 1
    while i < n_quad {
        let rem = i - (i / 2) * 2
        if rem == 1 {
            sum = sum + 4.0 * vals[i]
        } else {
            sum = sum + 2.0 * vals[i]
        }
        i = i + 1
    }
    sum * h / 3.0
}

fn l2_inner_product(f: fn(f64) -> f64 with Mut, Div, Panic,
                    g: fn(f64) -> f64 with Mut, Div, Panic,
                    a: f64, b: f64, n_quad: i32) -> f64 with Mut, Div, Panic {
    var nq = n_quad
    let rem = nq - (nq / 2) * 2
    if rem != 0 { nq = nq + 1 }

    let h = (b - a) / (nq as f64)
    var vals: [f64; 4096] = [0.0; 4096]

    var i = 0
    while i <= nq {
        let x = a + (i as f64) * h
        vals[i] = f(x) * g(x)
        i = i + 1
    }

    fa_simpson(&vals, a, b, nq)
}

fn l2_norm(f: fn(f64) -> f64 with Mut, Div, Panic,
           a: f64, b: f64, n_quad: i32) -> f64 with Mut, Div, Panic {
    let ip = l2_inner_product(f, f, a, b, n_quad)
    if ip < 0.0 { return 0.0 }
    fa_sqrt(ip)
}

fn fa_kernel_rbf(x: f64, y: f64, length_scale: f64) -> f64 with Mut, Div, Panic {
    let d = x - y
    let l2 = length_scale * length_scale
    fa_exp(0.0 - (d * d) / (2.0 * l2))
}

fn fa_kernel_eval(x: f64, y: f64, length_scale: f64, kernel_type: i32) -> f64 with Mut, Div, Panic {
    // Only RBF (type 0) used in tests
    fa_kernel_rbf(x, y, length_scale)
}

fn rkhs_train(x_train: &[f64; 128], y_train: &[f64; 128], n: i32,
              length_scale: f64, kernel_type: i32, reg: f64,
              model: &!RKHSModel) with Mut, Div, Panic {
    var i = 0
    while i < n {
        model.x_train[i] = x_train[i]
        i = i + 1
    }
    model.n_train = n
    model.length_scale = length_scale
    model.kernel_type = kernel_type

    var K: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n {
        var j = 0
        while j < n {
            K[i * n + j] = fa_kernel_eval(x_train[i], x_train[j], length_scale, kernel_type)
            j = j + 1
        }
        K[i * n + i] = K[i * n + i] + reg
        i = i + 1
    }

    var rhs: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n { rhs[i] = y_train[i]; i = i + 1 }

    var alpha_buf: [f64; 4096] = [0.0; 4096]
    fa_gauss_solve(&K, &rhs, n, &!alpha_buf)

    i = 0
    while i < n {
        model.alpha[i] = alpha_buf[i]
        i = i + 1
    }
}

fn rkhs_eval(model: &RKHSModel, x: f64) -> f64 with Mut, Div, Panic {
    var sum = 0.0
    var i = 0
    while i < model.n_train {
        let kval = fa_kernel_eval(x, model.x_train[i], model.length_scale, model.kernel_type)
        sum = sum + model.alpha[i] * kval
        i = i + 1
    }
    sum
}

fn rkhs_norm(model: &RKHSModel) -> f64 with Mut, Div, Panic {
    var sum = 0.0
    var i = 0
    while i < model.n_train {
        var j = 0
        while j < model.n_train {
            let kval = fa_kernel_eval(model.x_train[i], model.x_train[j],
                                      model.length_scale, model.kernel_type)
            sum = sum + model.alpha[i] * kval * model.alpha[j]
            j = j + 1
        }
        i = i + 1
    }
    if sum < 0.0 { return 0.0 }
    fa_sqrt(sum)
}

fn compact_op_spectrum(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                       a: f64, b: f64, n_quad: i32, n_eig: i32,
                       eigenvalues: &![f64; 64]) with Mut, Div, Panic {
    var nq = n_quad
    let rem = nq - (nq / 2) * 2
    if rem != 0 { nq = nq + 1 }

    let h = (b - a) / (nq as f64)

    var nodes: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i <= nq {
        nodes[i] = a + (i as f64) * h
        i = i + 1
    }
    let nn = nq + 1

    var weights: [f64; 4096] = [0.0; 4096]
    weights[0] = h / 3.0
    weights[nq] = h / 3.0
    i = 1
    while i < nq {
        let r2 = i - (i / 2) * 2
        if r2 == 1 {
            weights[i] = 4.0 * h / 3.0
        } else {
            weights[i] = 2.0 * h / 3.0
        }
        i = i + 1
    }

    var mat_n = nn
    if mat_n > 64 { mat_n = 64 }

    var M: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < mat_n {
        var j = 0
        while j < mat_n {
            M[i * mat_n + j] = weights[j] * K(nodes[i], nodes[j])
            j = j + 1
        }
        i = i + 1
    }

    var ne = n_eig
    if ne > mat_n { ne = mat_n }
    if ne > 64 { ne = 64 }

    var eig_idx = 0
    while eig_idx < ne {
        var v: [f64; 4096] = [0.0; 4096]
        i = 0
        while i < mat_n { v[i] = 1.0 / ((i + 1) as f64); i = i + 1 }
        let v_norm_init = fa_norm2(&v, mat_n)
        if v_norm_init > 0.0 {
            i = 0
            while i < mat_n { v[i] = v[i] / v_norm_init; i = i + 1 }
        }

        var w: [f64; 4096] = [0.0; 4096]
        var eigenvalue = 0.0
        var prev_eigenvalue = 0.0

        var iter = 0
        while iter < 500 {
            fa_matvec(&M, &v, mat_n, &!w)
            eigenvalue = fa_dot(&v, &w, mat_n)
            let nrm = fa_norm2(&w, mat_n)
            if nrm < 1.0e-30 {
                eigenvalue = 0.0
                i = 0
                while i < mat_n { v[i] = 0.0; i = i + 1 }
                iter = 500
            } else {
                i = 0
                while i < mat_n { v[i] = w[i] / nrm; i = i + 1 }
                if iter > 0 {
                    if fa_abs(eigenvalue - prev_eigenvalue) < 1.0e-12 * fa_abs(eigenvalue) + 1.0e-30 {
                        iter = 500
                    }
                }
                prev_eigenvalue = eigenvalue
            }
            iter = iter + 1
        }

        eigenvalues[eig_idx] = eigenvalue

        i = 0
        while i < mat_n {
            var j = 0
            while j < mat_n {
                M[i * mat_n + j] = M[i * mat_n + j] - eigenvalue * v[i] * v[j]
                j = j + 1
            }
            i = i + 1
        }

        eig_idx = eig_idx + 1
    }
}

fn fredholm_alternative(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                        a: f64, b: f64, lambda: f64,
                        n_quad: i32) -> bool with Mut, Div, Panic {
    var nq = n_quad
    let rem = nq - (nq / 2) * 2
    if rem != 0 { nq = nq + 1 }

    let h = (b - a) / (nq as f64)

    var nodes: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i <= nq {
        nodes[i] = a + (i as f64) * h
        i = i + 1
    }
    let nn = nq + 1

    var weights: [f64; 4096] = [0.0; 4096]
    weights[0] = h / 3.0
    weights[nq] = h / 3.0
    i = 1
    while i < nq {
        let r2 = i - (i / 2) * 2
        if r2 == 1 {
            weights[i] = 4.0 * h / 3.0
        } else {
            weights[i] = 2.0 * h / 3.0
        }
        i = i + 1
    }

    var mat_n = nn
    if mat_n > 64 { mat_n = 64 }

    var A: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < mat_n {
        var j = 0
        while j < mat_n {
            let m_ij = weights[j] * K(nodes[i], nodes[j])
            A[i * mat_n + j] = 0.0 - lambda * m_ij
            j = j + 1
        }
        A[i * mat_n + i] = A[i * mat_n + i] + 1.0
        i = i + 1
    }

    var det_sign = 1.0
    var log_det = 0.0

    var col = 0
    while col < mat_n {
        var max_val = fa_abs(A[col * mat_n + col])
        var max_row = col
        var row = col + 1
        while row < mat_n {
            let v = fa_abs(A[row * mat_n + col])
            if v > max_val { max_val = v; max_row = row }
            row = row + 1
        }
        if max_row != col {
            var j = 0
            while j < mat_n {
                let tmp = A[col * mat_n + j]
                A[col * mat_n + j] = A[max_row * mat_n + j]
                A[max_row * mat_n + j] = tmp
                j = j + 1
            }
            det_sign = 0.0 - det_sign
        }
        let pivot = A[col * mat_n + col]
        if fa_abs(pivot) < 1.0e-30 {
            return false
        }
        if pivot < 0.0 { det_sign = 0.0 - det_sign }
        log_det = log_det + fa_ln(fa_abs(pivot))
        row = col + 1
        while row < mat_n {
            let factor = A[row * mat_n + col] / pivot
            var j = col + 1
            while j < mat_n {
                A[row * mat_n + j] = A[row * mat_n + j] - factor * A[col * mat_n + j]
                j = j + 1
            }
            A[row * mat_n + col] = 0.0
            row = row + 1
        }
        col = col + 1
    }

    // Threshold: det < 1e-5 (log_det < -11.5) signals near-singular.
    // For lambda=2: det ~ 1/3, log_det ~ -1.1 (not singular).
    // For lambda=3: det ~ machine_eps, log_det ~ -37 (singular).
    let det_threshold = (0.0 - 5.0) * fa_ln(10.0)
    if log_det < det_threshold {
        return false
    }
    true
}

fn fn_sin(x: f64) -> f64 with Mut, Div, Panic {
    fa_sin(x)
}

fn fn_const_one(x: f64) -> f64 with Mut, Div, Panic {
    1.0
}

fn kernel_xt(x: f64, t: f64) -> f64 with Mut, Div, Panic {
    x * t
}

fn test_identity_norms() -> bool with Mut, Div, Panic {
    let n = 3
    var I: [f64; 4096] = [0.0; 4096]
    I[0] = 1.0    // (0,0)
    I[4] = 1.0    // (1,1)
    I[8] = 1.0    // (2,2)

    let n1 = op_norm_1(&I, n)
    let ni = op_norm_inf(&I, n)
    let nf = op_norm_frobenius(&I, n)
    let n2 = op_norm_2(&I, n)

    let expected_fro = fa_sqrt(3.0)

    let ok_1 = approx_eq(n1, 1.0, 1.0e-6)
    let ok_inf = approx_eq(ni, 1.0, 1.0e-6)
    let ok_fro = approx_eq(nf, expected_fro, 1.0e-6)
    let ok_2 = approx_eq(n2, 1.0, 1.0e-6)
    ok_1 && ok_inf && ok_fro && ok_2
}

fn test_norm_inequality() -> bool with Mut, Div, Panic {
    let n = 3
    // A = [[2, 1, 0], [1, 3, 1], [0, 1, 2]]
    var A: [f64; 4096] = [0.0; 4096]
    A[0] = 2.0; A[1] = 1.0; A[2] = 0.0
    A[3] = 1.0; A[4] = 3.0; A[5] = 1.0
    A[6] = 0.0; A[7] = 1.0; A[8] = 2.0

    let nf = op_norm_frobenius(&A, n)
    let n2 = op_norm_2(&A, n)

    // Frobenius norm must be >= spectral norm
    nf >= n2 - 1.0e-10
}

fn test_frobenius_known() -> bool with Mut, Div, Panic {
    let n = 2
    var A: [f64; 4096] = [0.0; 4096]
    A[0] = 1.0; A[1] = 2.0
    A[2] = 3.0; A[3] = 4.0

    let nf = op_norm_frobenius(&A, n)
    let expected = fa_sqrt(30.0)
    approx_eq(nf, expected, 1.0e-6)
}

fn test_spectral_radius_diag() -> bool with Mut, Div, Panic {
    let n = 3
    var D: [f64; 4096] = [0.0; 4096]
    D[0] = 1.0    // (0,0)
    D[4] = 3.0    // (1,1)
    D[8] = 2.0    // (2,2)

    let rho = spectral_radius(&D, n)
    approx_eq(rho, 3.0, 1.0e-4)
}

fn test_condition_identity() -> bool with Mut, Div, Panic {
    let n = 3
    var I: [f64; 4096] = [0.0; 4096]
    I[0] = 1.0
    I[4] = 1.0
    I[8] = 1.0

    let kappa = condition_number(&I, n)
    approx_eq(kappa, 1.0, 1.0e-4)
}

fn test_condition_ill() -> bool with Mut, Div, Panic {
    let n = 2
    var A: [f64; 4096] = [0.0; 4096]
    A[0] = 1.0      // (0,0)
    A[3] = 1000.0    // (1,1)

    let kappa = condition_number(&A, n)
    // Should be close to 1000
