}

fn test_l2_inner_product_sin() -> bool with Mut, Div, Panic {
    let pi = fa_pi()
    let ip = l2_inner_product(fn_sin, fn_sin, 0.0, pi, 200)
    let expected = pi / 2.0
    approx_eq(ip, expected, 1.0e-4)
}

fn test_l2_norm_constant() -> bool with Mut, Div, Panic {
    let nm = l2_norm(fn_const_one, 0.0, 1.0, 200)
    approx_eq(nm, 1.0, 1.0e-4)
}

fn test_rkhs_interp_exact() -> bool with Mut, Div, Panic {
    var x_train: [f64; 128] = [0.0; 128]
    var y_train: [f64; 128] = [0.0; 128]
    x_train[0] = 0.0; y_train[0] = 1.0
    x_train[1] = 0.5; y_train[1] = 2.0
    x_train[2] = 1.0; y_train[2] = 0.5
    x_train[3] = 1.5; y_train[3] = 3.0
    let n_pts = 4

    var model: RKHSModel = RKHSModel {
        x_train: [0.0; 128],
        alpha: [0.0; 128],
        n_train: 0,
        length_scale: 0.0,
        kernel_type: 0
    }
    rkhs_train(&x_train, &y_train, n_pts, 1.0, 0, 1.0e-10, &!model)

    // Evaluate at each training point
    let e0 = fa_abs(rkhs_eval(&model, 0.0) - 1.0)
    let e1 = fa_abs(rkhs_eval(&model, 0.5) - 2.0)
    let e2 = fa_abs(rkhs_eval(&model, 1.0) - 0.5)
    let e3 = fa_abs(rkhs_eval(&model, 1.5) - 3.0)

    let ok0 = e0 < 1.0e-4
    let ok1 = e1 < 1.0e-4
    let ok2 = e2 < 1.0e-4
    let ok3 = e3 < 1.0e-4
    ok0 && ok1 && ok2 && ok3
}

fn test_fredholm_alternative() -> bool with Mut, Div, Panic {
    // lambda=2 is not an eigenvalue of K(x,t)=x*t -> should return true
    let not_eig = fredholm_alternative(kernel_xt, 0.0, 1.0, 2.0, 60)

    // lambda=3 IS the reciprocal of eigenvalue 1/3 -> should return false
    let is_eig = fredholm_alternative(kernel_xt, 0.0, 1.0, 3.0, 60)

    not_eig && !is_eig
}

fn gp_h_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 25 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn gp_h_exp(x: f64) -> f64 with Mut, Div, Panic {
    let ln2 = 0.6931471805599453
    let inv_ln2 = 1.4426950408889634

    if x > 709.0 { return 1.0e308 }
    if x < -709.0 { return 0.0 }

    var k_f = x * inv_ln2
    var k: i64 = 0
    if k_f >= 0.0 { k = (k_f + 0.5) as i64 } else { k = (k_f - 0.5) as i64 }

    let r = x - (k as f64) * ln2

    var sum = 1.0
    var term = 1.0
    var n = 1
    while n <= 20 {
        term = term * r / (n as f64)
        sum = sum + term
        n = n + 1
    }

    var result = sum
    var kabs = k
    if kabs < 0 { kabs = 0 - kabs }
    var pow2 = 2.0
    var ka = kabs
    var acc = 1.0
    while ka > 0 {
        if ka - (ka / 2) * 2 != 0 { acc = acc * pow2 }
        pow2 = pow2 * pow2
        ka = ka / 2
    }
    if k >= 0 { result = result * acc } else { result = result / acc }
    result
}

fn gp_h_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return -1.0e30 }
    if x == 1.0 { return 0.0 }

    var y = 0.0
    var a = x
    let ln2 = 0.6931471805599453
    while a > 2.0 { a = a * 0.5; y = y + ln2 }
    while a < 0.5 { a = a * 2.0; y = y - ln2 }

    let t = (a - 1.0) / (a + 1.0)
    let t2 = t * t
    var sum = t
    var power = t
    var n = 1
    while n <= 30 {
        power = power * t2
        sum = sum + power / (2.0 * (n as f64) + 1.0)
        n = n + 1
    }
    y + 2.0 * sum
}

fn gp_h_sin(x: f64) -> f64 with Mut, Div, Panic {
    var a = x
    let tp = 6.28318530717958647692
    while a >= tp { a = a - tp }
    while a < 0.0 { a = a + tp }
    if a > 3.14159265358979323846 { a = a - tp }
    let a2 = a * a
    var sum = a
    var term = a
    var n = 1
    while n < 18 {
        term = 0.0 - term * a2 / ((2 * n) * (2 * n + 1)) as f64
        sum = sum + term
        n = n + 1
    }
    sum
}

fn gp_h_cos(x: f64) -> f64 with Mut, Div, Panic {
    gp_h_sin(x + 1.57079632679489661923)
}

fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
    gp_h_abs(a - b) < tol
}

fn kernel_rbf(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let d = x - y
    let l = hyper.length_scale
    hyper.signal_var * gp_h_exp(0.0 - 0.5 * d * d / (l * l))
}

fn kernel_matern32(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let r = gp_h_abs(x - y)
    let l = hyper.length_scale
    let sqrt3 = 1.7320508075688772
    let z = sqrt3 * r / l
    hyper.signal_var * (1.0 + z) * gp_h_exp(0.0 - z)
}

fn kernel_matern52(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let r = gp_h_abs(x - y)
    let l = hyper.length_scale
    let sqrt5 = 2.2360679774997896
    let z = sqrt5 * r / l
    let z2 = 5.0 * r * r / (3.0 * l * l)
    hyper.signal_var * (1.0 + z + z2) * gp_h_exp(0.0 - z)
}

fn kernel_periodic(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    let r = gp_h_abs(x - y)
    let l = hyper.length_scale
    let p = hyper.extra_param
    let s = gp_h_sin(gp_h_pi() * r / p)
    hyper.signal_var * gp_h_exp(0.0 - 2.0 * s * s / (l * l))
}

fn kernel_eval(x: f64, y: f64, hyper: &GPHyper) -> f64 with Mut, Div, Panic {
    if hyper.kernel_type == 0 { return kernel_rbf(x, y, hyper) }
    if hyper.kernel_type == 1 { return kernel_matern32(x, y, hyper) }
    if hyper.kernel_type == 2 { return kernel_matern52(x, y, hyper) }
    if hyper.kernel_type == 3 { return kernel_periodic(x, y, hyper) }
    kernel_rbf(x, y, hyper)
}

fn gp_cholesky(K: &[f64; 4096], n: i32, L: &![f64; 4096]) -> bool with Mut, Div, Panic {
    var idx = 0
    while idx < n * n { L[idx] = 0.0; idx = idx + 1 }

    var j = 0
    while j < n {
        var sum_diag = 0.0
        var k = 0
        while k < j {
            let ljk = L[j * n + k]
            sum_diag = sum_diag + ljk * ljk
            k = k + 1
        }
        let diag_val = K[j * n + j] - sum_diag
        if diag_val <= 0.0 { return false }
        L[j * n + j] = gp_h_sqrt(diag_val)

        var i = j + 1
        while i < n {
            var sum_off = 0.0
            k = 0
            while k < j {
                sum_off = sum_off + L[i * n + k] * L[j * n + k]
                k = k + 1
            }
            L[i * n + j] = (K[i * n + j] - sum_off) / L[j * n + j]
            i = i + 1
        }
        j = j + 1
    }
    true
}

fn gp_cholesky_solve(L: &[f64; 4096], b: &[f64; 128], n: i32, x: &![f64; 128]) with Mut, Div, Panic {
    var z: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + L[i * n + j] * z[j]
            j = j + 1
        }
        z[i] = (b[i] - sum) / L[i * n + i]
        i = i + 1
    }

    i = n - 1
    while i >= 0 {
        var sum = 0.0
        var j = i + 1
        while j < n {
            sum = sum + L[j * n + i] * x[j]
            j = j + 1
        }
        x[i] = (z[i] - sum) / L[i * n + i]
        i = i - 1
    }
}

fn gp_forward_solve(L: &[f64; 4096], b: &[f64; 128], n: i32, v: &![f64; 128]) with Mut, Div, Panic {
    var i = 0
    while i < n {
        var sum = 0.0
        var j = 0
        while j < i {
            sum = sum + L[i * n + j] * v[j]
            j = j + 1
        }
        v[i] = (b[i] - sum) / L[i * n + i]
        i = i + 1
    }
}

fn gp_train(data: &GPData, hyper: &GPHyper, model: &!GPModel) -> bool with Mut, Div, Panic {
    let n = data.n_train

    var i = 0
    while i < n {
        model.mx[i] = data.x_train[i]
        model.my[i] = data.y_train[i]
        i = i + 1
    }
    model.mn = n
    var local_hyper: GPHyper = GPHyper {
        signal_var: hyper.signal_var,
        length_scale: hyper.length_scale,
        noise_var: hyper.noise_var,
        kernel_type: hyper.kernel_type,
        extra_param: hyper.extra_param
    }
    model.hyper = local_hyper

    var K: [f64; 4096] = [0.0; 4096]
    i = 0
    while i < n {
        var j = 0
        while j < n {
            let kval = kernel_eval(data.x_train[i], data.x_train[j], hyper)
            if i == j {
                K[i * n + j] = kval + hyper.noise_var
            } else {
                K[i * n + j] = kval
            }
            j = j + 1
        }
        i = i + 1
    }

    var local_L: [f64; 4096] = [0.0; 4096]
    let ok = gp_cholesky(&K, n, &!local_L)
    if !ok { return false }
    var li: i32 = 0
    while li < n * n { model.L[li] = local_L[li]; li = li + 1 }

    var local_alpha: [f64; 128] = [0.0; 128]
    gp_cholesky_solve(&local_L, data.y_train, n, &!local_alpha)
    var ai: i32 = 0
    while ai < n { model.alpha[ai] = local_alpha[ai]; ai = ai + 1 }

    var data_fit = 0.0
    i = 0
    while i < n {
        data_fit = data_fit + data.y_train[i] * model.alpha[i]
        i = i + 1
    }
    data_fit = 0.0 - 0.5 * data_fit

    var complexity = 0.0
    i = 0
    while i < n {
        complexity = complexity + gp_h_ln(model.L[i * n + i])
        i = i + 1
    }
    complexity = 0.0 - complexity

    let norm_const = 0.0 - 0.5 * (n as f64) * gp_h_ln(2.0 * gp_h_pi())

    model.log_ml = data_fit + complexity + norm_const
    true
}

fn gp_predict(model: &GPModel, x_star: f64, pred: &!GPPrediction) with Mut, Div, Panic {
    let n = model.mn

    var k_star: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        k_star[i] = kernel_eval(x_star, model.mx[i], model.hyper)
        i = i + 1
    }

    var mean = 0.0
    i = 0
    while i < n {
        mean = mean + k_star[i] * model.alpha[i]
        i = i + 1
    }
    pred.mean = mean

    var v: [f64; 128] = [0.0; 128]
    gp_forward_solve(model.L, &k_star, n, &!v)

    let k_ss = kernel_eval(x_star, x_star, model.hyper)
    var v_dot_v = 0.0
    i = 0
    while i < n {
        v_dot_v = v_dot_v + v[i] * v[i]
        i = i + 1
    }
    var variance = k_ss - v_dot_v
    if variance < 0.0 { variance = 0.0 }
    pred.variance = variance
    pred.std_dev = gp_h_sqrt(variance)
}

fn gp_log_marginal(model: &GPModel) -> f64 {
    model.log_ml
}

fn make_rbf_hyper() -> GPHyper {
    GPHyper {
        signal_var: 1.0,
        length_scale: 1.0,
        noise_var: 0.01,
        kernel_type: 0,
        extra_param: 0.0
    }
}

fn make_zero_model() -> GPModel {
    GPModel {
        L: [0.0; 4096],
        alpha: [0.0; 128],
        mx: [0.0; 128],
        my: [0.0; 128],
        mn: 0,
        hyper: GPHyper {
            signal_var: 0.0,
            length_scale: 0.0,
            noise_var: 0.0,
            kernel_type: 0,
            extra_param: 0.0
        },
        log_ml: 0.0
    }
}

fn test_rbf_same_point() -> bool with Mut, Div, Panic {
    let hyper = make_rbf_hyper()
    let val = kernel_rbf(2.5, 2.5, &hyper)
    // k(x,x) = signal_var * exp(0) = signal_var = 1.0
    approx_eq(val, 1.0, 1.0e-6)
}

fn test_rbf_symmetry() -> bool with Mut, Div, Panic {
    let hyper = make_rbf_hyper()
    let k_xy = kernel_rbf(1.0, 3.0, &hyper)
    let k_yx = kernel_rbf(3.0, 1.0, &hyper)
    approx_eq(k_xy, k_yx, 1.0e-12)
}

fn test_rbf_decay() -> bool with Mut, Div, Panic {
    let hyper = make_rbf_hyper()
    let k_self = kernel_rbf(2.0, 2.0, &hyper)
    let k_near = kernel_rbf(2.0, 2.5, &hyper)
    let k_far = kernel_rbf(2.0, 5.0, &hyper)
    // k(x,x) > k(x,x+0.5) > k(x,x+3)
    if k_self <= k_near { return false }
    if k_near <= k_far { return false }
    true
}

fn test_cholesky_known() -> bool with Mut, Div, Panic {
    // K = [[4,2],[2,3]]
    // Expected L = [[2,0],[1,sqrt(2)]]
    // L * L^T should reconstruct K
    var K: [f64; 4096] = [0.0; 4096]
    K[0] = 4.0
    K[1] = 2.0
    K[2] = 2.0
    K[3] = 3.0

    var L: [f64; 4096] = [0.0; 4096]
    let ok = gp_cholesky(&K, 2, &!L)
    if !ok { return false }

    // Verify L[0,0] = 2.0
    if !approx_eq(L[0], 2.0, 1.0e-6) { return false }
    // Verify L[1,0] = 1.0
    if !approx_eq(L[2], 1.0, 1.0e-6) { return false }
    // Verify L[1,1] = sqrt(2) ~ 1.41421
    if !approx_eq(L[3], 1.41421356237, 1.0e-4) { return false }
    // Verify L[0,1] = 0.0 (upper triangle is zero)
    if !approx_eq(L[1], 0.0, 1.0e-12) { return false }

    // Roundtrip: L * L^T should give back K
    // (L*L^T)[0,0] = L[0,0]^2 = 4.0
    let r00 = L[0] * L[0]
    if !approx_eq(r00, 4.0, 1.0e-6) { return false }
    // (L*L^T)[1,0] = L[1,0]*L[0,0] = 1*2 = 2
    let r10 = L[2] * L[0]
    if !approx_eq(r10, 2.0, 1.0e-6) { return false }
    // (L*L^T)[1,1] = L[1,0]^2 + L[1,1]^2 = 1 + 2 = 3
    let r11 = L[2] * L[2] + L[3] * L[3]
    if !approx_eq(r11, 3.0, 1.0e-6) { return false }

    true
}

fn test_gp_predict_at_train() -> bool with Mut, Div, Panic {
    var data: GPData = GPData {
        x_train: [0.0; 128],
        y_train: [0.0; 128],
        n_train: 0,
        noise_var: 0.01
    }
    build_quad_data(&!data)

    let hyper = make_rbf_hyper()
    var model = make_zero_model()

    let ok = gp_train(&data, &hyper, &!model)
    if !ok { return false }

    // Predict at each training point: mean should be close to y_train
    var max_err = 0.0
    var i = 0
    while i < 5 {
        var pred: GPPrediction = GPPrediction { mean: 0.0, variance: 0.0, std_dev: 0.0 }
        gp_predict(&model, data.x_train[i], &!pred)
        let err = gp_h_abs(pred.mean - data.y_train[i])
        if err > max_err { max_err = err }
        i = i + 1
    }
    // With noise_var=0.01, predictions should be within ~0.5 of training values
    max_err < 1.0e-1
}

fn test_gp_variance_at_train() -> bool with Mut, Div, Panic {
    var data: GPData = GPData {
        x_train: [0.0; 128],
        y_train: [0.0; 128],
        n_train: 0,
        noise_var: 0.01
    }
    build_quad_data(&!data)

    let hyper = make_rbf_hyper()
    var model = make_zero_model()

    let ok = gp_train(&data, &hyper, &!model)
    if !ok { return false }

    // Variance at training points should be near noise_var (0.01)
    var all_small = true
    var i = 0
    while i < 5 {
        var pred: GPPrediction = GPPrediction { mean: 0.0, variance: 0.0, std_dev: 0.0 }
        gp_predict(&model, data.x_train[i], &!pred)
        // Posterior variance at training point should be <= noise_var
        if pred.variance > 0.1 { all_small = false }
        i = i + 1
    }
    all_small
}

fn test_gp_variance_away() -> bool with Mut, Div, Panic {
    var data: GPData = GPData {
        x_train: [0.0; 128],
        y_train: [0.0; 128],
        n_train: 0,
        noise_var: 0.01
    }
    build_quad_data(&!data)

    let hyper = make_rbf_hyper()
    var model = make_zero_model()

    let ok = gp_train(&data, &hyper, &!model)
    if !ok { return false }

    // Variance at training point x=2.0
    var pred_near: GPPrediction = GPPrediction { mean: 0.0, variance: 0.0, std_dev: 0.0 }
    gp_predict(&model, 2.0, &!pred_near)

    // Variance far from training data at x=10.0
    var pred_far: GPPrediction = GPPrediction { mean: 0.0, variance: 0.0, std_dev: 0.0 }
    gp_predict(&model, 10.0, &!pred_far)

    // Variance far away should be larger than at training point
    pred_far.variance > pred_near.variance
}

fn test_gp_log_ml_finite() -> bool with Mut, Div, Panic {
    var data: GPData = GPData {
        x_train: [0.0; 128],
        y_train: [0.0; 128],
        n_train: 0,
        noise_var: 0.01
    }
    build_quad_data(&!data)

    let hyper = make_rbf_hyper()
    var model = make_zero_model()

    let ok = gp_train(&data, &hyper, &!model)
    if !ok { return false }

    let lml = gp_log_marginal(&model)
    // Should be a finite, reasonable number (not extremely large magnitude)
    // A valid log ML for 5 points is typically in range [-100, 100]
    if lml > 1.0e30 { return false }
    if lml < -1.0e30 { return false }
    // Check it is not zero (which would be suspicious for non-trivial data)
    if gp_h_abs(lml) < 1.0e-20 { return false }
    true
}

fn test_gp_interpolation() -> bool with Mut, Div, Panic {
    // Use very small noise so predictions should closely match training values
    var data: GPData = GPData {
        x_train: [0.0; 128],
        y_train: [0.0; 128],
        n_train: 0,
        noise_var: 1.0e-6
    }
    // 4 training points: simple linear function y = 2*x + 1
    data.n_train = 4
    data.x_train[0] = 0.0; data.y_train[0] = 1.0
    data.x_train[1] = 1.0; data.y_train[1] = 3.0
    data.x_train[2] = 2.0; data.y_train[2] = 5.0
    data.x_train[3] = 3.0; data.y_train[3] = 7.0

    var hyper: GPHyper = GPHyper {
        signal_var: 10.0,
        length_scale: 2.0,
        noise_var: 1.0e-6,
        kernel_type: 0,
        extra_param: 0.0
    }

    var model = make_zero_model()
    let ok = gp_train(&data, &hyper, &!model)
    if !ok { return false }

    // Predictions at training points should almost exactly match
    var max_err = 0.0
    var i = 0
    while i < 4 {
        var pred: GPPrediction = GPPrediction { mean: 0.0, variance: 0.0, std_dev: 0.0 }
        gp_predict(&model, data.x_train[i], &!pred)
        let err = gp_h_abs(pred.mean - data.y_train[i])
        if err > max_err { max_err = err }
        i = i + 1
    }
    // With noise_var = 1e-6, interpolation error should be tiny
    max_err < 1.0e-3
}

fn test_matern32_positive() -> bool with Mut, Div, Panic {
    var hyper: GPHyper = GPHyper {
        signal_var: 2.0,
        length_scale: 1.5,
        noise_var: 0.01,
        kernel_type: 1,
        extra_param: 0.0
    }

    // Test a range of point pairs
    var all_pos = true
    var i = 0
    while i < 10 {
        let x = (i as f64) * 0.7
        var j = 0
        while j < 10 {
            let y = (j as f64) * 0.7
            let kval = kernel_matern32(x, y, &hyper)
            if kval <= 0.0 { all_pos = false }
            j = j + 1
        }
        i = i + 1
    }
    all_pos
}

fn test_periodic_kernel() -> bool with Mut, Div, Panic {
    let period = 2.0
    var hyper: GPHyper = GPHyper {
        signal_var: 1.0,
        length_scale: 1.0,
        noise_var: 0.01,
        kernel_type: 3,
        extra_param: period
    }

    // k(x, x) = signal_var (distance 0)
    let k_self = kernel_periodic(1.0, 1.0, &hyper)

    // k(x, x + period) should be approximately k(x, x)
    // since the periodic kernel has period p, sin(pi * p / p) = sin(pi) = 0
    let k_period = kernel_periodic(1.0, 1.0 + period, &hyper)

    // Both should be approximately signal_var = 1.0
    if !approx_eq(k_self, 1.0, 1.0e-6) { return false }
    if !approx_eq(k_period, 1.0, 1.0e-6) { return false }

    // Also verify that at half-period it is NOT equal to k(x,x) (it should be smaller)
    let k_half = kernel_periodic(1.0, 1.0 + period * 0.5, &hyper)
    if k_half >= k_self { return false }

    true
}

fn ie_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn ie_exp(x: f64) -> f64 with Mut, Div, Panic {
    if x > 500.0 { return 1.0e200 }
    if x < -500.0 { return 0.0 }
    var kf = x / 0.6931471805599453
    var k: i32 = 0
    if kf >= 0.0 { k = kf as i32 } else { k = (kf as i32) - 1 }
    let r = x - (k as f64) * 0.6931471805599453
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 25 { term = term * r / (n as f64); sum = sum + term; n = n + 1 }
    var result = sum
    if k >= 0 { var i = 0; while i < k { result = result * 2.0; i = i + 1 } }
    else { var i = 0; while i < (0 - k) { result = result / 2.0; i = i + 1 } }
    result
}

fn ie_sin(x: f64) -> f64 with Mut, Div, Panic {
    var a = x
    let tp = 6.28318530717958647692
    while a >= tp { a = a - tp }
    while a < 0.0 { a = a + tp }
    if a > 3.14159265358979323846 { a = a - tp }
    let a2 = a * a
    var sum = a
    var term = a
    var n = 1
    while n < 18 { term = 0.0 - term * a2 / ((2 * n) * (2 * n + 1)) as f64; sum = sum + term; n = n + 1 }
    sum
}

fn ie_cos(x: f64) -> f64 with Mut, Div, Panic {
    ie_sin(x + 1.57079632679489661923)
}

fn ie_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    if x == 1.0 { return 0.0 }
    var m = x
    var e = 0
    while m >= 2.0 { m = m / 2.0; e = e + 1 }
    while m < 0.5 { m = m * 2.0; e = e - 1 }
    let t = (m - 1.0) / (m + 1.0)
    let t2 = t * t
    var sum = t
    var term = t
    var k = 1
    while k < 30 { term = term * t2; sum = sum + term / ((2 * k + 1) as f64); k = k + 1 }
    2.0 * sum + (e as f64) * 0.6931471805599453
}

fn ie_pow(base: f64, exp_val: f64) -> f64 with Mut, Div, Panic {
    if base <= 0.0 { return 0.0 }
    ie_exp(exp_val * ie_ln(base))
}

fn ie_dot(a: &[f64; 128], b: &[f64; 128], n: i32) -> f64 with Mut, Div, Panic {
    var sum = 0.0
    var i = 0
    while i < n { sum = sum + a[i] * b[i]; i = i + 1 }
    sum
}

fn ie_mat_vec(A: &[f64; 512], x: &[f64; 128], y: &![f64; 128], m: i32, n: i32) with Mut, Div, Panic {
    var i = 0
    while i < m {
        var sum = 0.0
        var j = 0
        while j < n { sum = sum + A[i * n + j] * x[j]; j = j + 1 }
        y[i] = sum
        i = i + 1
    }
}

fn ie_gauss_solve(A: &![f64; 512], b: &![f64; 128], x: &![f64; 128], n: i32) with Mut, Div, Panic {
    var col = 0
    while col < n {
        var max_val = ie_abs(A[col * n + col])
        var max_row = col
        var row = col + 1
        while row < n {
            let v = ie_abs(A[row * n + col])
            if v > max_val { max_val = v; max_row = row }
            row = row + 1
        }
        if max_row != col {
            var j = 0
            while j < n {
                let tmp = A[col * n + j]
                A[col * n + j] = A[max_row * n + j]
                A[max_row * n + j] = tmp
                j = j + 1
            }
            let tmp_b = b[col]
            b[col] = b[max_row]
            b[max_row] = tmp_b
        }
        let pivot = A[col * n + col]
        if ie_abs(pivot) < 1.0e-30 {
            col = col + 1
        } else {
            row = col + 1
            while row < n {
                let factor = A[row * n + col] / pivot
                var j = col + 1
                while j < n {
                    A[row * n + j] = A[row * n + j] - factor * A[col * n + j]
                    j = j + 1
                }
                A[row * n + col] = 0.0
                b[row] = b[row] - factor * b[col]
                row = row + 1
            }
            col = col + 1
        }
    }
    var k = n - 1
    while k >= 0 {
        var s = b[k]
        var j = k + 1
        while j < n { s = s - A[k * n + j] * x[j]; j = j + 1 }
        if ie_abs(A[k * n + k]) > 1.0e-30 {
            x[k] = s / A[k * n + k]
        } else {
            x[k] = 0.0
        }
        k = k - 1
    }
}

fn ie_gauss_legendre(n: i32, nodes: &![f64; 128], weights: &![f64; 128]) with Mut, Div, Panic {
    let n_half = (n + 1) / 2
    var i = 0
    while i < n_half {
        var x = ie_cos(ie_pi() * ((i as f64) + 0.75) / ((n as f64) + 0.5))
        var iter = 0
        while iter < 50 {
            var p0 = 1.0
            var p1 = x
            var k = 1
            while k < n {
                let p2 = ((2 * k + 1) as f64 * x * p1 - (k as f64) * p0) / ((k + 1) as f64)
                p0 = p1
                p1 = p2
                k = k + 1
            }
            let dp = (n as f64) * (x * p1 - p0) / (x * x - 1.0)
            let dx = p1 / dp
            x = x - dx
            if ie_abs(dx) < 1.0e-15 { iter = 50 }
            iter = iter + 1
        }
        nodes[i] = 0.0 - x
        nodes[n - 1 - i] = x
        var p0w = 1.0
        var p1w = x
        var k = 1
        while k < n {
            let p2 = ((2 * k + 1) as f64 * x * p1w - (k as f64) * p0w) / ((k + 1) as f64)
            p0w = p1w
            p1w = p2
            k = k + 1
        }
        let dpw = (n as f64) * (x * p1w - p0w) / (x * x - 1.0)
        let w = 2.0 / ((1.0 - x * x) * dpw * dpw)
        weights[i] = w
        weights[n - 1 - i] = w
        i = i + 1
    }
}

fn ie_gauss_legendre_ab(a: f64, b: f64, n: i32,
                        nodes: &![f64; 128], weights: &![f64; 128]) with Mut, Div, Panic {
    ie_gauss_legendre(n, nodes, weights)
    let half_len = 0.5 * (b - a)
    let midpoint = 0.5 * (a + b)
    var i = 0
    while i < n {
        nodes[i] = half_len * nodes[i] + midpoint
        weights[i] = weights[i] * half_len
        i = i + 1
    }
}

fn ie_residual_fredholm2_internal(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                                  f: fn(f64) -> f64 with Mut, Div, Panic,
                                  lambda: f64, result: &IEResult) -> f64 with Mut, Div, Panic {
    var max_res = 0.0
    var i = 0
    while i < result.n {
        var ku_i = 0.0
        var j = 0
        while j < result.n {
            ku_i = ku_i + result.weights[j] * K(result.nodes[i], result.nodes[j]) * result.u[j]
            j = j + 1
        }
        let expected = f(result.nodes[i]) + lambda * ku_i
        let res_i = ie_abs(result.u[i] - expected)
        if res_i > max_res { max_res = res_i }
        i = i + 1
    }
    max_res
}

fn fredholm2_nystrom(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                     f: fn(f64) -> f64 with Mut, Div, Panic,
                     a: f64, b: f64, lambda: f64, n: i32,
                     result: &!IEResult) with Mut, Div, Panic {
    ie_gauss_legendre_ab(a, b, n, &!result.nodes, &!result.weights)
    result.n = n
    var mat: [f64; 512] = [0.0; 512]
    var rhs: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        rhs[i] = f(result.nodes[i])
        var j = 0
        while j < n {
            let kval = K(result.nodes[i], result.nodes[j])
            mat[i * n + j] = 0.0 - lambda * result.weights[j] * kval
            if i == j {
                mat[i * n + j] = mat[i * n + j] + 1.0
            }
            j = j + 1
        }
        i = i + 1
    }
    var sol: [f64; 128] = [0.0; 128]
    ie_gauss_solve(&!mat, &!rhs, &!sol, n)
    i = 0
    while i < n { result.u[i] = sol[i]; i = i + 1 }
    result.residual = ie_residual_fredholm2_internal(K, f, lambda, result)
    result.converged = result.residual < 1.0e-10
}

fn fredholm2_eval(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                  f: fn(f64) -> f64 with Mut, Div, Panic,
                  lambda: f64, result: &IEResult, x: f64) -> f64 with Mut, Div, Panic {
    var sum = 0.0
    var j = 0
    while j < result.n {
        sum = sum + result.weights[j] * K(x, result.nodes[j]) * result.u[j]
        j = j + 1
    }
    f(x) + lambda * sum
}

fn fredholm1_tikhonov(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                      f: fn(f64) -> f64 with Mut, Div, Panic,
                      a: f64, b: f64, alpha: f64, n: i32,
                      result: &!IEResult) with Mut, Div, Panic {
    ie_gauss_legendre_ab(a, b, n, &!result.nodes, &!result.weights)
    result.n = n
    var kmat: [f64; 512] = [0.0; 512]
    var fvec: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n {
        fvec[i] = f(result.nodes[i])
        var j = 0
        while j < n {
            kmat[i * n + j] = result.weights[j] * K(result.nodes[i], result.nodes[j])
            j = j + 1
        }
        i = i + 1
    }
    var ata: [f64; 512] = [0.0; 512]
    var atf: [f64; 128] = [0.0; 128]
    var j = 0
    while j < n {
        var k = 0
        while k < n {
            var sum = 0.0
            i = 0
            while i < n {
                sum = sum + kmat[i * n + j] * kmat[i * n + k] * result.weights[i]
                i = i + 1
            }
            ata[j * n + k] = sum
            k = k + 1
        }
        var sumf = 0.0
        i = 0
        while i < n {
            sumf = sumf + kmat[i * n + j] * fvec[i] * result.weights[i]
            i = i + 1
        }
        atf[j] = sumf
        j = j + 1
    }
    i = 0
    while i < n {
        ata[i * n + i] = ata[i * n + i] + alpha
        i = i + 1
    }
    var sol: [f64; 128] = [0.0; 128]
    ie_gauss_solve(&!ata, &!atf, &!sol, n)
    i = 0
    while i < n { result.u[i] = sol[i]; i = i + 1 }
    var max_res = 0.0
    i = 0
    while i < n {
        var ku_i = 0.0
        j = 0
        while j < n {
            ku_i = ku_i + kmat[i * n + j] * sol[j]
            j = j + 1
        }
        let res_i = ie_abs(ku_i - fvec[i])
        if res_i > max_res { max_res = res_i }
        i = i + 1
    }
    result.residual = max_res
    result.converged = max_res < 1.0e-6
}

fn volterra2_solve(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                   f: fn(f64) -> f64 with Mut, Div, Panic,
                   a: f64, b: f64, n: i32,
                   result: &!IEResult) with Mut, Div, Panic {
    result.n = n
    let h = (b - a) / ((n - 1) as f64)
    var i = 0
    while i < n {
        result.nodes[i] = a + (i as f64) * h
        result.weights[i] = h
        i = i + 1
    }
    result.u[0] = f(a)
    i = 1
    while i < n {
        let xi = result.nodes[i]
        var sum = 0.5 * K(xi, result.nodes[0]) * result.u[0]
        var j = 1
        while j < i {
            sum = sum + K(xi, result.nodes[j]) * result.u[j]
            j = j + 1
        }
        let kii = K(xi, xi)
        let denom = 1.0 - 0.5 * h * kii
        let numer = f(xi) + h * sum
        if ie_abs(denom) < 1.0e-30 {
            result.u[i] = numer
        } else {
            result.u[i] = numer / denom
        }
        i = i + 1
    }
    var max_res = 0.0
    i = 1
    while i < n {
        let xi = result.nodes[i]
        var integral = 0.5 * K(xi, result.nodes[0]) * result.u[0]
        var j = 1
        while j < i {
            integral = integral + K(xi, result.nodes[j]) * result.u[j]
            j = j + 1
        }
        integral = integral + 0.5 * K(xi, result.nodes[i]) * result.u[i]
        integral = integral * h
        let res_i = ie_abs(result.u[i] - f(xi) - integral)
        if res_i > max_res { max_res = res_i }
        i = i + 1
    }
    result.residual = max_res
    result.converged = max_res < 1.0e-8
}

fn greens_poisson_1d(x: f64, t: f64, a: f64, b: f64) -> f64 with Mut, Div, Panic {
    let l = b - a
    if x <= t {
        (b - t) * (x - a) / l
    } else {
        (b - x) * (t - a) / l
    }
}

fn bvp_via_greens(G: fn(f64, f64) -> f64 with Mut, Div, Panic,
                  f: fn(f64) -> f64 with Mut, Div, Panic,
                  a: f64, b: f64, n: i32,
                  result: &!IEResult) with Mut, Div, Panic {
    ie_gauss_legendre_ab(a, b, n, &!result.nodes, &!result.weights)
    result.n = n
    var i = 0
    while i < n {
        let xi = result.nodes[i]
        var sum = 0.0
        var j = 0
        while j < n {
            sum = sum + result.weights[j] * G(xi, result.nodes[j]) * f(result.nodes[j])
            j = j + 1
        }
        result.u[i] = sum
        i = i + 1
    }
    result.residual = 0.0
    result.converged = true
}

fn ie_eigenvalues(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                  a: f64, b: f64, n_quad: i32, n_eig: i32,
                  result: &!IEEigenResult) with Mut, Div, Panic {
    result.n_quad = n_quad
    result.n_found = 0
    var nodes: [f64; 128] = [0.0; 128]
    var weights: [f64; 128] = [0.0; 128]
    ie_gauss_legendre_ab(a, b, n_quad, &!nodes, &!weights)
    var bmat: [f64; 512] = [0.0; 512]
    var sqrt_w: [f64; 128] = [0.0; 128]
    var i = 0
    while i < n_quad {
        sqrt_w[i] = ie_sqrt(weights[i])
        i = i + 1
    }
    i = 0
    while i < n_quad {
        var j = 0
        while j < n_quad {
            bmat[i * n_quad + j] = sqrt_w[i] * K(nodes[i], nodes[j]) * sqrt_w[j]
            j = j + 1
        }
        i = i + 1
    }
    var eig_idx = 0
    while eig_idx < n_eig {
        if eig_idx >= n_quad { eig_idx = n_eig }
        else {
            var v: [f64; 128] = [0.0; 128]
            i = 0
            while i < n_quad {
                let seed_val = (i as f64) * 0.618033988749895 + (eig_idx as f64) * 1.324717957244746
                v[i] = ie_sin(seed_val * 17.0 + 3.7)
                i = i + 1
            }
            var norm = 0.0
            i = 0
            while i < n_quad { norm = norm + v[i] * v[i]; i = i + 1 }
            norm = ie_sqrt(norm)
            if norm > 1.0e-30 {
                i = 0
                while i < n_quad { v[i] = v[i] / norm; i = i + 1 }
            }
            var lambda_est = 0.0
            var iter = 0
            while iter < 500 {
                var w: [f64; 128] = [0.0; 128]
                i = 0
                while i < n_quad {
                    var s = 0.0
                    var j = 0
                    while j < n_quad { s = s + bmat[i * n_quad + j] * v[j]; j = j + 1 }
                    w[i] = s
                    i = i + 1
                }
                var d = 0
                while d < eig_idx {
                    var proj = 0.0
                    i = 0
                    while i < n_quad {
                        proj = proj + w[i] * result.eigenvectors[d * n_quad + i]
                        i = i + 1
                    }
                    i = 0
                    while i < n_quad {
                        w[i] = w[i] - proj * result.eigenvectors[d * n_quad + i]
                        i = i + 1
                    }
                    d = d + 1
                }
                var lambda_new = 0.0
                i = 0
                while i < n_quad { lambda_new = lambda_new + v[i] * w[i]; i = i + 1 }
                norm = 0.0
                i = 0
                while i < n_quad { norm = norm + w[i] * w[i]; i = i + 1 }
                norm = ie_sqrt(norm)
                if norm < 1.0e-30 {
                    iter = 500
                } else {
                    i = 0
                    while i < n_quad { v[i] = w[i] / norm; i = i + 1 }
                }
                if ie_abs(lambda_new - lambda_est) < 1.0e-12 * ie_max(ie_abs(lambda_new), 1.0) {
                    lambda_est = lambda_new
                    iter = 500
                }
                lambda_est = lambda_new
                iter = iter + 1
            }
            result.eigenvalues[eig_idx] = lambda_est
            i = 0
            while i < n_quad {
                result.eigenvectors[eig_idx * n_quad + i] = v[i]
                i = i + 1
            }
            result.n_found = eig_idx + 1
            eig_idx = eig_idx + 1
        }
    }
}

fn fredholm2_neumann(K: fn(f64, f64) -> f64 with Mut, Div, Panic,
                     f: fn(f64) -> f64 with Mut, Div, Panic,
                     a: f64, b: f64, lambda: f64, n: i32,
                     max_iter: i32, tol: f64,
                     result: &!IEResult) with Mut, Div, Panic {
    ie_gauss_legendre_ab(a, b, n, &!result.nodes, &!result.weights)
    result.n = n
    var i = 0
    while i < n { result.u[i] = f(result.nodes[i]); i = i + 1 }
    var prev: [f64; 128] = [0.0; 128]
    i = 0
    while i < n { prev[i] = result.u[i]; i = i + 1 }
    var iter = 0
    result.converged = false
    while iter < max_iter {
        var max_diff = 0.0
        i = 0
        while i < n {
            var sum = 0.0
            var j = 0
            while j < n {
                sum = sum + result.weights[j] * K(result.nodes[i], result.nodes[j]) * prev[j]
                j = j + 1
            }
            result.u[i] = f(result.nodes[i]) + lambda * sum
            let diff = ie_abs(result.u[i] - prev[i])
            if diff > max_diff { max_diff = diff }
            i = i + 1
        }
        i = 0
        while i < n { prev[i] = result.u[i]; i = i + 1 }
        if max_diff < tol {
            result.converged = true
            result.residual = max_diff
            return
        }
        iter = iter + 1
    }
    result.residual = ie_residual_fredholm2_internal(K, f, lambda, result)
}

fn greens_01(x: f64, t: f64) -> f64 with Mut, Div, Panic {
    greens_poisson_1d(x, t, 0.0, 1.0)
}

fn kernel_exp_xt(x: f64, t: f64) -> f64 with Mut, Div, Panic {
    ie_exp(x * t)
}

fn rhs_tikhonov(x: f64) -> f64 with Mut, Div, Panic {
    if ie_abs(x) < 1.0e-10 { return 1.0 }
    (ie_exp(x) - 1.0) / x
}

fn test_gl_nodes_symmetric() -> bool with Mut, Div, Panic {
    let n = 8
    var nodes: [f64; 128] = [0.0; 128]
    var weights: [f64; 128] = [0.0; 128]
    ie_gauss_legendre(n, &!nodes, &!weights)
    var ok = true
    var i = 0
    while i < n {
        let diff = ie_abs(nodes[i] + nodes[n - 1 - i])
        if diff > 1.0e-12 { ok = false }
        i = i + 1
    }
    ok
}

fn test_gl_weights_sum() -> bool with Mut, Div, Panic {
    let n = 12
    var nodes: [f64; 128] = [0.0; 128]
    var weights: [f64; 128] = [0.0; 128]
    ie_gauss_legendre(n, &!nodes, &!weights)
    var sum = 0.0
    var i = 0
    while i < n { sum = sum + weights[i]; i = i + 1 }
    ie_abs(sum - 2.0) < 1.0e-12
}

fn test_gl_integrates_x2() -> bool with Mut, Div, Panic {
    let n = 4
    var nodes: [f64; 128] = [0.0; 128]
    var weights: [f64; 128] = [0.0; 128]
    ie_gauss_legendre(n, &!nodes, &!weights)
    var sum = 0.0
    var i = 0
    while i < n {
        sum = sum + weights[i] * nodes[i] * nodes[i]
        i = i + 1
    }
    // 2-point GL is exact for polynomials up to degree 2n-1=3, so 4-point is exact for degree 7
    ie_abs(sum - 2.0 / 3.0) < 1.0e-12
}

fn test_fredholm2_known_solution() -> bool with Mut, Div, Panic {
    let lambda = 0.5
    let n = 16
    var result = IEResult {
        u: [0.0; 128], nodes: [0.0; 128], weights: [0.0; 128],
        n: 0, residual: 0.0, converged: false
    }
    fredholm2_nystrom(kernel_xt, rhs_one, 0.0, 1.0, lambda, n, &!result)

    // Analytical: u(x) = 1 + 3*0.5*x / (2*(3-0.5)) = 1 + 1.5*x / 5.0 = 1 + 0.3*x
    var max_err = 0.0
    var i = 0
    while i < n {
        let x = result.nodes[i]
        let analytical = 1.0 + 0.3 * x
        let err = ie_abs(result.u[i] - analytical)
        if err > max_err { max_err = err }
        i = i + 1
    }
    max_err < 1.0e-10
}

fn test_fredholm2_residual_small() -> bool with Mut, Div, Panic {
    let lambda = 0.5
    let n = 16
    var result = IEResult {
        u: [0.0; 128], nodes: [0.0; 128], weights: [0.0; 128],
        n: 0, residual: 0.0, converged: false
    }
    fredholm2_nystrom(kernel_xt, rhs_one, 0.0, 1.0, lambda, n, &!result)
    result.residual < 1.0e-6
}

fn test_volterra2_exp() -> bool with Mut, Div, Panic {
    let n = 64
    var result = IEResult {
        u: [0.0; 128], nodes: [0.0; 128], weights: [0.0; 128],
        n: 0, residual: 0.0, converged: false
    }
    volterra2_solve(kernel_one, rhs_volterra_one, 0.0, 1.0, n, &!result)

    // Check at several interior nodes
    var max_err = 0.0
    var i = 0
    while i < n {
        let x = result.nodes[i]
        let exact = ie_exp(x)
        let err = ie_abs(result.u[i] - exact) / exact
        if err > max_err { max_err = err }
        i = i + 1
    }
    // Trapezoidal rule is O(h^2) so with 64 points on [0,1], h ~ 0.016, error ~ 2.5e-4
    max_err < 1.0e-2
}

fn test_volterra_n_steps() -> bool with Mut, Div, Panic {
    let n = 32
    var result = IEResult {
        u: [0.0; 128], nodes: [0.0; 128], weights: [0.0; 128],
        n: 0, residual: 0.0, converged: false
    }
    volterra2_solve(kernel_one, rhs_volterra_one, 0.0, 1.0, n, &!result)
    result.n == 32
}

fn test_greens_symmetry() -> bool with Mut, Div, Panic {
    var ok = true
    // Test several pairs (x,t)
    var i = 1
    while i < 10 {
        let x = (i as f64) * 0.1
        var j = 1
        while j < 10 {
            let t = (j as f64) * 0.1
            let gxt = greens_poisson_1d(x, t, 0.0, 1.0)
            let gtx = greens_poisson_1d(t, x, 0.0, 1.0)
            if ie_abs(gxt - gtx) > 1.0e-14 { ok = false }
            j = j + 1
        }
        i = i + 1
    }
    ok
}

fn test_bvp_greens() -> bool with Mut, Div, Panic {
    let n = 20
    var result = IEResult {
        u: [0.0; 128], nodes: [0.0; 128], weights: [0.0; 128],
        n: 0, residual: 0.0, converged: false
    }
    bvp_via_greens(greens_01, source_one, 0.0, 1.0, n, &!result)

    var max_err = 0.0
    var i = 0
    while i < n {
        let x = result.nodes[i]
        let exact = x * (1.0 - x) / 2.0
        let err = ie_abs(result.u[i] - exact)
        if err > max_err { max_err = err }
        i = i + 1
    }
    max_err < 1.0e-10
}

