fn ode_exp_decay(u: f64, t: f64) -> f64 {
    let k = 0.1
    return 0.0 - k * u
}

fn rk4_step(u: f64, t: f64, dt: f64) -> f64 with Panic {
    let k1 = ode_exp_decay(u, t)
    let k2 = ode_exp_decay(u + 0.5 * dt * k1, t + 0.5 * dt)
    let k3 = ode_exp_decay(u + 0.5 * dt * k2, t + 0.5 * dt)
    let k4 = ode_exp_decay(u + dt * k3, t + dt)
    return u + (dt / 6.0) * (k1 + 2.0 * k2 + 2.0 * k3 + k4)
}

fn test_rk4_solver() -> bool with Panic, Div, Mut {
    let u0 = 100.0
    let t_end = 10.0
    let n_steps: i64 = 100
    let dt = t_end / (n_steps as f64)

    var u = u0
    var t = 0.0
    var i: i64 = 0

    while i < n_steps {
        u = rk4_step(u, t, dt)
        t = t + dt
        i = i + 1
    }

    // Analytical solution: u(t) = u0 * exp(-k*t) = 100 * exp(-1) ~ 36.79
    let analytical = u0 * exp_f64(0.0 - 0.1 * t_end)
    let rel_err = abs_f64(u - analytical) / analytical

    return rel_err < 0.0001
}

fn dual_var(val: f64) -> Dual {
    return Dual { val: val, dot: 1.0 }
}

fn dual_const(val: f64) -> Dual {
    return Dual { val: val, dot: 0.0 }
}

fn dual_local_mul(a: Dual, b: Dual) -> Dual {
    return Dual {
        val: a.val * b.val,
        dot: a.dot * b.val + a.val * b.dot
    }
}

fn dual_local_add(a: Dual, b: Dual) -> Dual {
    return Dual { val: a.val + b.val, dot: a.dot + b.dot }
}

fn dual_local_sub(a: Dual, b: Dual) -> Dual {
    return Dual { val: a.val - b.val, dot: a.dot - b.dot }
}

fn test_autodiff_simple() -> bool {
    // Test d/dx(x^2) at x=3
    let x = dual_var(3.0)
    let y = dual_local_mul(x, x)

    // f(3) = 9, f'(3) = 6
    let val_err = abs_f64(y.val - 9.0)
    let dot_err = abs_f64(y.dot - 6.0)

    return val_err < 0.0001 && dot_err < 0.0001
}

fn test_autodiff_chain() -> bool {
    // Test d/dx((x-1)^2) at x=3
    // f(x) = (x-1)^2, f'(x) = 2*(x-1)
    // f(3) = 4, f'(3) = 4
    let x = dual_var(3.0)
    let one = dual_const(1.0)
    let diff = dual_local_sub(x, one)
    let y = dual_local_mul(diff, diff)

    let val_err = abs_f64(y.val - 4.0)
    let dot_err = abs_f64(y.dot - 4.0)

    return val_err < 0.0001 && dot_err < 0.0001
}

fn rng_uniform(rng: RNG) -> RNGResult with Panic {
    let a: i64 = 1103515245
    let c: i64 = 12345
    let m: i64 = 2147483648
    let new_seed = (a * rng.seed + c) % m
    let u = (new_seed as f64) / (m as f64)
    return RNGResult { rng: RNG { seed: new_seed }, value: u }
}

fn test_rng_uniform() -> bool with Panic, Div, Mut {
    var rng = RNG { seed: 12345 }
    var sum = 0.0
    let n: i64 = 1000
    var i: i64 = 0

    while i < n {
        let r = rng_uniform(rng)
        rng = r.rng
        sum = sum + r.value
        i = i + 1
    }

    let mean = sum / (n as f64)
    // Mean of Uniform(0,1) should be ~0.5
    return abs_f64(mean - 0.5) < 0.1
}

fn test_beta_moments() -> bool with Panic {
    // For Beta(2, 5):
    // Mean = alpha / (alpha + beta) = 2/7 = 0.286
    // Variance = (alpha*beta) / ((alpha+beta)^2 * (alpha+beta+1))
    //          = 10 / (49 * 8) = 0.0255
    let alpha = 2.0
    let b = 5.0

    let mean = alpha / (alpha + b)
    let variance = (alpha * b) / ((alpha + b) * (alpha + b) * (alpha + b + 1.0))

    let mean_expected = 2.0 / 7.0
    let var_expected = 10.0 / 392.0

    let mean_err = abs_f64(mean - mean_expected)
    let var_err = abs_f64(variance - var_expected)

    return mean_err < 0.0001 && var_err < 0.0001
}

fn dual_local_pow(a: Dual, n: f64) -> Dual {
    // Simple case for n=2
    if abs_f64(n - 2.0) < 0.001 {
        return dual_local_mul(a, a)
    }
    // For other powers, use approximation
    return Dual { val: 0.0, dot: 0.0 }
}

fn rosenbrock_dual(x: Dual, y: Dual) -> Dual {
    // f(x,y) = (1-x)^2 + 100*(y-x^2)^2
    let one = dual_const(1.0)
    let hundred = dual_const(100.0)
    let term1 = dual_local_sub(one, x)
    let term1_sq = dual_local_mul(term1, term1)
    let x_sq = dual_local_mul(x, x)
    let term2 = dual_local_sub(y, x_sq)
    let term2_sq = dual_local_mul(term2, term2)
    return dual_local_add(term1_sq, dual_local_mul(hundred, term2_sq))
}

fn test_rosenbrock_gradient() -> bool {
    // At minimum (1, 1), gradient should be (0, 0)
    let fx_dx = rosenbrock_dual(dual_var(1.0), dual_const(1.0))
    let fx_dy = rosenbrock_dual(dual_const(1.0), dual_var(1.0))

    let val_err = abs_f64(fx_dx.val)  // f(1,1) = 0
    let dx_err = abs_f64(fx_dx.dot)   // df/dx(1,1) = 0
    let dy_err = abs_f64(fx_dy.dot)   // df/dy(1,1) = 0

    return val_err < 0.0001 && dx_err < 0.0001 && dy_err < 0.0001
}

fn test_normal_normal_posterior() -> bool with Panic {
    // Prior: mu ~ N(0, 10^2)
    // Likelihood: x_i ~ N(mu, 1^2), with data mean = 5, n = 10
    // Posterior: mu | data ~ N(mu_post, sigma_post^2)
    // mu_post = (prior_prec * prior_mean + lik_prec * data_mean) / (prior_prec + lik_prec)

    let prior_mean = 0.0
    let prior_var = 100.0
    let data_mean = 5.0
    let data_var = 1.0
    let n: i64 = 10

    let prior_prec = 1.0 / prior_var
    let lik_prec = (n as f64) / data_var

    let post_prec = prior_prec + lik_prec
    let post_var = 1.0 / post_prec
    let post_mean = post_var * (prior_prec * prior_mean + lik_prec * data_mean)

    // Expected: post_prec = 0.01 + 10 = 10.01
    // post_mean = (0.01 * 0 + 10 * 5) / 10.01 = 50 / 10.01 = 4.995
    let expected_mean = 50.0 / 10.01

    let err = abs_f64(post_mean - expected_mean)
    return err < 0.001
}

fn sp_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x
    var i = 0
    while i < 20 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}

fn sp_cos(x: f64) -> f64 with Mut, Div, Panic {
    sp_sin(x + 1.57079632679489661923)
}

fn sp_exp(x: f64) -> f64 with Mut, Div, Panic {
    let ln2 = 0.6931471805599453
    var k_f = x / ln2
    var k: i32 = 0
    if k_f >= 0.0 { k = k_f as i32 } else { k = (k_f as i32) - 1 }
    let r = x - (k as f64) * ln2
    var sum = 1.0
    var term = 1.0
    var n = 1
    while n < 25 { term = term * r / (n as f64); sum = sum + term; n = n + 1 }
    var result = sum
    if k >= 0 {
        var i = 0
        while i < k { result = result * 2.0; i = i + 1 }
    } else {
        var i = 0
        while i < (0 - k) { result = result * 0.5; i = i + 1 }
    }
    result
}

fn sp_ln(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 - 1.0e30 }
    let ln2 = 0.6931471805599453
    var m = x
    var e: i32 = 0
    while m >= 2.0 { m = m * 0.5; e = e + 1 }
    while m < 1.0 { m = m * 2.0; e = e - 1 }
    let t = (m - 1.0) / (m + 1.0)
    let t2 = t * t
    var sum = t
    var power = t
    var k = 1
    while k < 30 { power = power * t2; sum = sum + power / (2 * k + 1) as f64; k = k + 1 }
    2.0 * sum + (e as f64) * ln2
}

fn sp_sinh(x: f64) -> f64 with Mut, Div, Panic {
    let ep = sp_exp(x)
    let em = sp_exp(0.0 - x)
    (ep - em) / 2.0
}

fn sp_gauss_solve(A: &![f64; 4096], b: &![f64; 256], x: &![f64; 256], n: i32) with Mut, Div, Panic {
    var col = 0
    while col < n {
        var max_val = sp_abs(A[col * n + col])
        var max_row = col
        var row = col + 1
        while row < n {
            let val = sp_abs(A[row * n + col])
            if val > max_val { max_val = val; max_row = row }
            row = row + 1
        }

        if max_row != col {
            var j = 0
            while j < n {
                let tmp = A[col * n + j]
                A[col * n + j] = A[max_row * n + j]
                A[max_row * n + j] = tmp
                j = j + 1
            }
            let tmp_b = b[col]
            b[col] = b[max_row]
            b[max_row] = tmp_b
        }

        let pivot = A[col * n + col]
        if sp_abs(pivot) < 1.0e-30 {
            col = col + 1
        } else {
            row = col + 1
            while row < n {
                let factor = A[row * n + col] / pivot
                var j = col + 1
                while j < n {
                    A[row * n + j] = A[row * n + j] - factor * A[col * n + j]
                    j = j + 1
                }
                A[row * n + col] = 0.0
                b[row] = b[row] - factor * b[col]
                row = row + 1
            }
            col = col + 1
        }
    }

    var i = n - 1
    while i >= 0 {
        var sum = b[i]
        var j = i + 1
        while j < n { sum = sum - A[i * n + j] * x[j]; j = j + 1 }
        if sp_abs(A[i * n + i]) < 1.0e-30 {
            x[i] = 0.0
        } else {
            x[i] = sum / A[i * n + i]
        }
        i = i - 1
    }
}

fn cheb_nodes(n: i32, x: &![f64; 256]) with Mut, Div, Panic {
    var j = 0
    while j <= n {
        x[j] = sp_cos((j as f64) * sp_pi() / (n as f64))
        j = j + 1
    }
}

fn cheb_nodes_ab(n: i32, a: f64, b: f64, x: &![f64; 256]) with Mut, Div, Panic {
    let mid = 0.5 * (a + b)
    let half = 0.5 * (b - a)
    var j = 0
    while j <= n {
        x[j] = mid + half * sp_cos((j as f64) * sp_pi() / (n as f64))
        j = j + 1
    }
}

fn cheb_diffmat(n: i32, D: &![f64; 4096]) with Mut, Div, Panic {
    let np = n + 1

    var x: [f64; 256] = [0.0; 256]
    var j = 0
    while j <= n { x[j] = sp_cos((j as f64) * sp_pi() / (n as f64)); j = j + 1 }

    var c: [f64; 256] = [0.0; 256]
    var i = 0
    while i <= n { c[i] = 1.0; i = i + 1 }
    c[0] = 2.0
    c[n] = 2.0

    i = 0
    while i <= n {
        j = 0
        while j <= n {
            if i != j {
                var sign = 1.0
                if (i + j) - ((i + j) / 2) * 2 != 0 { sign = 0.0 - 1.0 }
                D[i * np + j] = c[i] * sign / (c[j] * (x[i] - x[j]))
            }
            j = j + 1
        }
        i = i + 1
    }

    i = 1
    while i < n {
        D[i * np + i] = 0.0 - x[i] / (2.0 * (1.0 - x[i] * x[i]))
        i = i + 1
    }

    let n2 = (n as f64) * (n as f64)
    D[0] = (2.0 * n2 + 1.0) / 6.0
    D[n * np + n] = 0.0 - (2.0 * n2 + 1.0) / 6.0
}

fn cheb_diffmat2(n: i32, D2: &![f64; 4096]) with Mut, Div, Panic {
    let np = n + 1

    var D1: [f64; 4096] = [0.0; 4096]
    cheb_diffmat(n, &!D1)

    var i = 0
    while i < np {
        var j = 0
        while j < np {
            var sum = 0.0
            var k = 0
            while k < np {
                sum = sum + D1[i * np + k] * D1[k * np + j]
                k = k + 1
            }
            D2[i * np + j] = sum
            j = j + 1
        }
        i = i + 1
    }
}

fn cheb_diffmat_ab(n: i32, a: f64, b: f64, D: &![f64; 4096]) with Mut, Div, Panic {
    let np = n + 1
    cheb_diffmat(n, D)
    let scale = 2.0 / (b - a)
    var i = 0
    while i < np {
        var j = 0
        while j < np {
            D[i * np + j] = D[i * np + j] * scale
            j = j + 1
        }
        i = i + 1
    }
}

fn cheb_diffmat2_ab(n: i32, a: f64, b: f64, D2: &![f64; 4096]) with Mut, Div, Panic {
    let np = n + 1
    cheb_diffmat2(n, D2)
    let scale = 2.0 / (b - a)
    let scale2 = scale * scale
    var i = 0
    while i < np {
        var j = 0
        while j < np {
            D2[i * np + j] = D2[i * np + j] * scale2
            j = j + 1
        }
        i = i + 1
    }
}

fn spectral_bvp_2nd(n: i32, a: f64, b: f64,
                    p_fn: fn(f64) -> f64 with Mut, Div, Panic,
                    q_fn: fn(f64) -> f64 with Mut, Div, Panic,
                    f_fn: fn(f64) -> f64 with Mut, Div, Panic,
                    alpha: f64, beta: f64,
                    u: &![f64; 256]) with Mut, Div, Panic {
    let np = n + 1

    var x: [f64; 256] = [0.0; 256]
    cheb_nodes_ab(n, a, b, &!x)

    var D1: [f64; 4096] = [0.0; 4096]
    var D2: [f64; 4096] = [0.0; 4096]
    cheb_diffmat_ab(n, a, b, &!D1)
    cheb_diffmat2_ab(n, a, b, &!D2)

    var L: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i < np {
        let p_val = p_fn(x[i])
        let q_val = q_fn(x[i])
        var j = 0
        while j < np {
            L[i * np + j] = 0.0 - D2[i * np + j] + p_val * D1[i * np + j]
            j = j + 1
        }
        L[i * np + i] = L[i * np + i] + q_val
        i = i + 1
    }

    var rhs: [f64; 256] = [0.0; 256]
    i = 0
    while i < np { rhs[i] = f_fn(x[i]); i = i + 1 }

    // BC: CGL nodes ordered x_0 = b (right), x_n = a (left)
    var j = 0
    while j < np { L[0 * np + j] = 0.0; j = j + 1 }
    L[0 * np + 0] = 1.0
    rhs[0] = beta

    j = 0
    while j < np { L[n * np + j] = 0.0; j = j + 1 }
    L[n * np + n] = 1.0
    rhs[n] = alpha

    sp_gauss_solve(&!L, &!rhs, u, np)
}

fn sp_atan_core(t: f64) -> f64 with Mut, Div, Panic {
    let t2 = t * t
    var sum = t
    var power = t
    var k = 1
    while k < 30 {
        power = 0.0 - power * t2
        sum = sum + power / (2 * k + 1) as f64
        k = k + 1
    }
    sum
}

fn sp_atan_series(t: f64) -> f64 with Mut, Div, Panic {
    if sp_abs(t) > 1.0 {
        let inv = 1.0 / t
        let a = sp_atan_core(inv)
        if t > 0.0 { return sp_pi() / 2.0 - a }
        return 0.0 - sp_pi() / 2.0 - a
    }
    sp_atan_core(t)
}

fn sp_atan2(y: f64, x: f64) -> f64 with Mut, Div, Panic {
    if sp_abs(x) < 1.0e-30 {
        if y > 0.0 { return sp_pi() / 2.0 }
        if y < 0.0 { return 0.0 - sp_pi() / 2.0 }
        return 0.0
    }
    let ratio = y / x
    var a = sp_atan_series(ratio)
    if x < 0.0 {
        if y >= 0.0 { a = a + sp_pi() } else { a = a - sp_pi() }
    }
    a
}

fn spectral_eigval(n: i32, a: f64, b: f64,
                   V_fn: fn(f64) -> f64 with Mut, Div, Panic,
                   eigenvalues: &![f64; 256],
                   n_found: &!i32) with Mut, Div, Panic {
    let np = n + 1

    var x: [f64; 256] = [0.0; 256]
    cheb_nodes_ab(n, a, b, &!x)

    var D2: [f64; 4096] = [0.0; 4096]
    cheb_diffmat2_ab(n, a, b, &!D2)

    let m = n - 1
    if m <= 0 { n_found[0] = 0; return }

    var L: [f64; 4096] = [0.0; 4096]
    var i = 0
    while i < m {
        var j = 0
        while j < m {
            L[i * m + j] = 0.0 - D2[(i + 1) * np + (j + 1)]
            j = j + 1
        }
        L[i * m + i] = L[i * m + i] + V_fn(x[i + 1])
        i = i + 1
    }

    var max_iter = 100 * m * m
    if max_iter > 100000 { max_iter = 100000 }
    var iter = 0
    while iter < max_iter {
        var max_off = 0.0
        var p = 0
        var q = 1
        i = 0
        while i < m {
            var j = i + 1
            while j < m {
                let val = sp_abs(L[i * m + j])
                if val > max_off { max_off = val; p = i; q = j }
                j = j + 1
            }
            i = i + 1
        }

        if max_off < 1.0e-12 { iter = max_iter }
        else {
            let app = L[p * m + p]
            let aqq = L[q * m + q]
            let apq = L[p * m + q]

            var theta = 0.0
            let diff = aqq - app
            if sp_abs(diff) < 1.0e-30 {
                theta = sp_pi() / 4.0
            } else {
                theta = 0.5 * sp_atan2(2.0 * apq, diff)
            }

            let cos_t = sp_cos(theta)
            let sin_t = sp_sin(theta)

            var k = 0
            while k < m {
                if k != p && k != q {
                    let lkp = L[k * m + p]
                    let lkq = L[k * m + q]
                    L[k * m + p] = cos_t * lkp + sin_t * lkq
                    L[k * m + q] = 0.0 - sin_t * lkp + cos_t * lkq
                    L[p * m + k] = L[k * m + p]
                    L[q * m + k] = L[k * m + q]
                }
                k = k + 1
            }

            let new_pp = cos_t * cos_t * app + 2.0 * cos_t * sin_t * apq + sin_t * sin_t * aqq
            let new_qq = sin_t * sin_t * app - 2.0 * cos_t * sin_t * apq + cos_t * cos_t * aqq
            L[p * m + p] = new_pp
            L[q * m + q] = new_qq
            L[p * m + q] = 0.0
            L[q * m + p] = 0.0

            iter = iter + 1
        }
    }

    i = 0
    while i < m { eigenvalues[i] = L[i * m + i]; i = i + 1 }

    i = 1
    while i < m {
        let key = eigenvalues[i]
        var j = i - 1
        while j >= 0 && eigenvalues[j] > key {
            eigenvalues[j + 1] = eigenvalues[j]
            j = j - 1
        }
        eigenvalues[j + 1] = key
        i = i + 1
    }

    n_found[0] = m
}

fn cc_weights(n: i32, w: &![f64; 256]) with Mut, Div, Panic {
    if n == 0 { w[0] = 2.0; return }
    if n == 1 { w[0] = 1.0; w[1] = 1.0; return }

    let half_n = n / 2

    var j = 0
    while j <= n {
        var sum = 0.0
        var k = 0
        while k <= half_n {
            let denom = 1.0 - 4.0 * (k as f64) * (k as f64)
            let theta = 2.0 * (k as f64) * (j as f64) * sp_pi() / (n as f64)
            var term = sp_cos(theta) / denom

            if k == 0 { term = term * 0.5 }
            if k == half_n { term = term * 0.5 }

            sum = sum + term
            k = k + 1
        }

        w[j] = 2.0 * sum / (n as f64)
        if j != 0 && j != n { w[j] = w[j] * 2.0 }
        j = j + 1
    }
}

fn cc_integrate(f_vals: &[f64; 256], n: i32) -> f64 with Mut, Div, Panic {
    var w: [f64; 256] = [0.0; 256]
    cc_weights(n, &!w)

    var sum = 0.0
    var j = 0
    while j <= n {
        sum = sum + w[j] * f_vals[j]
        j = j + 1
    }
    sum
}

fn cheb_interpolate(f_vals: &[f64; 256], n: i32, x: f64) -> f64 with Mut, Div, Panic {
    var nodes: [f64; 256] = [0.0; 256]
    var j = 0
    while j <= n { nodes[j] = sp_cos((j as f64) * sp_pi() / (n as f64)); j = j + 1 }

    j = 0
    while j <= n {
        if sp_abs(x - nodes[j]) < 1.0e-15 { return f_vals[j] }
        j = j + 1
    }

    var numer = 0.0
    var denom = 0.0
    j = 0
    while j <= n {
        var w = 1.0
        if j - (j / 2) * 2 != 0 { w = 0.0 - 1.0 }
        if j == 0 || j == n { w = w * 0.5 }

        let term = w / (x - nodes[j])
        numer = numer + term * f_vals[j]
        denom = denom + term
        j = j + 1
    }
    numer / denom
}

fn cheb_coeffs_from_values(f_vals: &[f64; 256], n: i32, coeffs: &![f64; 256]) with Mut, Div, Panic {
    var k = 0
    while k <= n {
        var sum = 0.0
        var j = 0
        while j <= n {
            let theta = (k as f64) * (j as f64) * sp_pi() / (n as f64)
            var term = f_vals[j] * sp_cos(theta)

            if j == 0 { term = term * 0.5 }
            if j == n { term = term * 0.5 }

            sum = sum + term
            j = j + 1
        }

        coeffs[k] = 2.0 * sum / (n as f64)
        k = k + 1
    }

    coeffs[0] = coeffs[0] * 0.5
    if n > 0 { coeffs[n] = coeffs[n] * 0.5 }
}

fn cheb_eval_from_coeffs(coeffs: &[f64; 256], n: i32, x: f64) -> f64 with Mut, Div, Panic {
    if n == 0 { return coeffs[0] }
    if n == 1 { return coeffs[0] + coeffs[1] * x }

    var b_next = 0.0
    var b_curr = 0.0

    var k = n
    while k >= 1 {
        let b_new = 2.0 * x * b_curr - b_next + coeffs[k]
        b_next = b_curr
        b_curr = b_new
        k = k - 1
    }

    coeffs[0] + x * b_curr - b_next
}

fn test_cheb_nodes_standard() -> bool with Mut, Div, Panic {
    let n = 16
    var x: [f64; 256] = [0.0; 256]
    cheb_nodes(n, &!x)

    let tol = 1.0e-12
    if sp_abs(x[0] - 1.0) > tol { return false }
    if sp_abs(x[n] - (0.0 - 1.0)) > tol { return false }

    // Nodes should be strictly decreasing
    var i = 0
    while i < n {
        if x[i] <= x[i + 1] { return false }
        i = i + 1
    }

    // Middle node for even n: x_{n/2} = cos(pi/2) = 0
    if sp_abs(x[n / 2]) > tol { return false }

    true
}

