fn ep_sqrt(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var r = x
    var si = 0
    while si < 20 {
        r = 0.5 * (r + x / r)
        si = si + 1
    }
    return r
}

fn ep_exp_neg(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 1.0 }
    // Count whole units
    var en_whole = 0
    var en_rem = x
    while en_rem >= 1.0 {
        en_whole = en_whole + 1
        en_rem = en_rem - 1.0
    }
    // Taylor series for e^(-en_rem), en_rem in [0,1) — fast convergence
    var en_result = 1.0
    var en_term = 1.0
    var ek = 1
    while ek <= 15 {
        let ekf = ek as f64
        en_term = en_term * (0.0 - en_rem) / ekf
        en_result = en_result + en_term
        ek = ek + 1
    }
    // Multiply by e^(-1)^n_whole; e^(-1) = 0.36787944117144232
    let e_inv = 0.36787944117
    var ei = 0
    while ei < en_whole {
        en_result = en_result * e_inv
        ei = ei + 1
    }
    return en_result
}

