fn tape_new_var(tape: Tape, val: f64) -> Tape {
    let idx = tape.size
    let node = TapeNode { value: val, adjoint: 0.0, op: op_var(), parent1: 0 - 1, parent2: 0 - 1, aux: 0.0 }
    let t = tape_set(tape, idx, node)
    return tape_with_size(t, idx + 1)
}

