fn backward_add_p2(tape: Tape, p2_idx: i64, adj: f64) -> Tape {
    if p2_idx < 0 { return tape }
    let p2 = tape_get(tape, p2_idx)
    let p2_new = TapeNode { value: p2.value, adjoint: p2.adjoint + adj, op: p2.op, parent1: p2.parent1, parent2: p2.parent2, aux: p2.aux }
    return tape_set(tape, p2_idx, p2_new)
}

fn backward_sub_p2(tape: Tape, p2_idx: i64, adj: f64) -> Tape {
    if p2_idx < 0 { return tape }
    let p2 = tape_get(tape, p2_idx)
    let p2_new = TapeNode { value: p2.value, adjoint: p2.adjoint - adj, op: p2.op, parent1: p2.parent1, parent2: p2.parent2, aux: p2.aux }
    return tape_set(tape, p2_idx, p2_new)
}

fn backward_mul(tape: Tape, p1_idx: i64, p2_idx: i64, adj: f64) -> Tape {
    if p2_idx < 0 { return tape }
    let p1 = tape_get(tape, p1_idx)
    let p2 = tape_get(tape, p2_idx)

    if p1_idx == p2_idx {
        // Same variable: d/dx(x*x) = 2x
        let p1_new = TapeNode { value: p1.value, adjoint: p1.adjoint + adj * p1.value * 2.0, op: p1.op, parent1: p1.parent1, parent2: p1.parent2, aux: p1.aux }
        return tape_set(tape, p1_idx, p1_new)
    }

    // Different variables: d/da(a*b) = b, d/db(a*b) = a
    let p1_new = TapeNode { value: p1.value, adjoint: p1.adjoint + adj * p2.value, op: p1.op, parent1: p1.parent1, parent2: p1.parent2, aux: p1.aux }
    let tape2 = tape_set(tape, p1_idx, p1_new)
    let p2_new = TapeNode { value: p2.value, adjoint: p2.adjoint + adj * p1.value, op: p2.op, parent1: p2.parent1, parent2: p2.parent2, aux: p2.aux }
    return tape_set(tape2, p2_idx, p2_new)
}

fn backward_div(tape: Tape, p1_idx: i64, p2_idx: i64, adj: f64) -> Tape {
    if p2_idx < 0 { return tape }
    let p1 = tape_get(tape, p1_idx)
    let p2 = tape_get(tape, p2_idx)
    // d/da(a/b) = 1/b, d/db(a/b) = -a/b²
    let p1_new = TapeNode { value: p1.value, adjoint: p1.adjoint + adj / p2.value, op: p1.op, parent1: p1.parent1, parent2: p1.parent2, aux: p1.aux }
    let tape2 = tape_set(tape, p1_idx, p1_new)
    let p2_new = TapeNode { value: p2.value, adjoint: p2.adjoint - adj * p1.value / (p2.value * p2.value), op: p2.op, parent1: p2.parent1, parent2: p2.parent2, aux: p2.aux }
    return tape_set(tape2, p2_idx, p2_new)
}

fn backward_unary(tape: Tape, p1_idx: i64, grad: f64) -> Tape {
    let p1 = tape_get(tape, p1_idx)
    let p1_new = TapeNode { value: p1.value, adjoint: p1.adjoint + grad, op: p1.op, parent1: p1.parent1, parent2: p1.parent2, aux: p1.aux }
    return tape_set(tape, p1_idx, p1_new)
}

fn backward_node(tape: Tape, idx: i64) -> Tape {
    let node = tape_get(tape, idx)

    // Copy ALL needed values to local vars at function start
    let cur_adj = node.adjoint
    let cur_op = node.op
    let cur_p1_idx = node.parent1
    let cur_p2_idx = node.parent2
    let cur_aux = node.aux
    let cur_value = node.value

    // No parent means nothing to backprop
    if cur_p1_idx < 0 {
        return tape
    }

    // Get parent info
    let p1 = tape_get(tape, cur_p1_idx)
    let p1_value = p1.value

    // Dispatch to helper functions (no nested if blocks)
    if cur_op == op_add() {
        let t1 = backward_unary(tape, cur_p1_idx, cur_adj)
        return backward_add_p2(t1, cur_p2_idx, cur_adj)
    }

    if cur_op == op_sub() {
        let t1 = backward_unary(tape, cur_p1_idx, cur_adj)
        return backward_sub_p2(t1, cur_p2_idx, cur_adj)
    }

    if cur_op == op_mul() {
        return backward_mul(tape, cur_p1_idx, cur_p2_idx, cur_adj)
    }

    if cur_op == op_div() {
        return backward_div(tape, cur_p1_idx, cur_p2_idx, cur_adj)
    }

    if cur_op == op_neg() {
        return backward_unary(tape, cur_p1_idx, 0.0 - cur_adj)
    }

    if cur_op == op_sqrt() {
        // d/dx sqrt(x) = 1/(2*sqrt(x))
        let grad = cur_adj / (2.0 * cur_value)
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_exp() {
        // d/dx exp(x) = exp(x)
        let grad = cur_adj * cur_value
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_ln() {
        // d/dx ln(x) = 1/x
        let grad = cur_adj / p1_value
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_sin() {
        // d/dx sin(x) = cos(x)
        let grad = cur_adj * cos_f64(p1_value)
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_cos() {
        // d/dx cos(x) = -sin(x)
        let grad = 0.0 - cur_adj * sin_f64(p1_value)
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_tanh() {
        // d/dx tanh(x) = 1 - tanh²(x)
        let grad = cur_adj * (1.0 - cur_value * cur_value)
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_pow() {
        // d/dx x^n = n * x^(n-1)
        let n = cur_aux
        let grad = cur_adj * n * pow_f64(p1_value, n - 1.0)
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_relu() {
        // d/dx ReLU(x) = 1 if x > 0, else 0
        let grad = if p1_value > 0.0 { cur_adj } else { 0.0 }
        return backward_unary(tape, cur_p1_idx, grad)
    }

    if cur_op == op_sigmoid() {
        // d/dx σ(x) = σ(x)(1-σ(x))
        let grad = cur_adj * cur_value * (1.0 - cur_value)
        return backward_unary(tape, cur_p1_idx, grad)
    }

    // Unknown op - return unchanged
    return tape
}

fn backward(tape: Tape, output: Var) -> Tape {

    // Set output adjoint to 1
    let out_node = tape_get(tape, output.idx)
    let out_new = TapeNode { value: out_node.value, adjoint: 1.0, op: out_node.op, parent1: out_node.parent1, parent2: out_node.parent2, aux: out_node.aux }
    var t = tape_set(tape, output.idx, out_new)

    // Traverse in reverse order
    var i = output.idx
    while i >= 0 {
        t = backward_node(t, i)
        i = i - 1
    }

    return t
}

fn get_grad(tape: Tape, v: Var) -> f64 {
    return tape_get(tape, v.idx).adjoint
}

fn test_tape_square() -> bool {
    // f(x) = x², df/dx = 2x
    // At x=3: f(3) = 9, df/dx = 6
    var tape = new_tape()
    tape = tape_new_var(tape, 3.0)
    let x = tape_last_var(tape)
    tape = tape_mul(tape, x, x)
    let y = tape_last_var(tape)
    tape = backward(tape, y)

    let grad = get_grad(tape, x)
    let error = abs_f64(grad - 6.0)
    return error < 0.001
}

fn test_tape_chain() -> bool {
    // f(x) = sin(x²), df/dx = 2x·cos(x²)
    // At x=2: f(4) = sin(4) ≈ -0.7568, df/dx = 4·cos(4) ≈ -2.614
    var tape = new_tape()
    tape = tape_new_var(tape, 2.0)
    let x = tape_last_var(tape)
    tape = tape_mul(tape, x, x)
    let x2 = tape_last_var(tape)
    tape = tape_sin(tape, x2)
    let y = tape_last_var(tape)
    tape = backward(tape, y)

    let grad = get_grad(tape, x)
    let expected = 4.0 * cos_f64(4.0)
    let error = abs_f64(grad - expected)
    return error < 0.01
}

fn test_tape_product() -> bool {
    // f(x,y) = x·y, df/dx = y, df/dy = x
    // At x=3, y=5: f = 15, df/dx = 5, df/dy = 3
    var tape = new_tape()
    tape = tape_new_var(tape, 3.0)
    let x = tape_last_var(tape)
    tape = tape_new_var(tape, 5.0)
    let y = tape_last_var(tape)
    tape = tape_mul(tape, x, y)
    let z = tape_last_var(tape)
    tape = backward(tape, z)

    let grad_x = get_grad(tape, x)
    let grad_y = get_grad(tape, y)
    let err_x = abs_f64(grad_x - 5.0)
    let err_y = abs_f64(grad_y - 3.0)
    return err_x < 0.001 && err_y < 0.001
}

fn test_tape_exp() -> bool {
    // f(x) = exp(x), df/dx = exp(x)
    // At x=2: f = exp(2) ≈ 7.389, df/dx = exp(2)
    var tape = new_tape()
    tape = tape_new_var(tape, 2.0)
    let x = tape_last_var(tape)
    tape = tape_exp(tape, x)
    let y = tape_last_var(tape)
    tape = backward(tape, y)

    let grad = get_grad(tape, x)
    let expected = exp_f64(2.0)
    let error = abs_f64(grad - expected)
    return error < 0.01
}

fn test_tape_sigmoid() -> bool {
    // f(x) = σ(x) = 1/(1+exp(-x)), df/dx = σ(x)(1-σ(x))
    // At x=0: σ(0) = 0.5, df/dx = 0.25
    var tape = new_tape()
    tape = tape_new_var(tape, 0.0)
    let x = tape_last_var(tape)
    tape = tape_sigmoid(tape, x)
    let y = tape_last_var(tape)
    tape = backward(tape, y)

    let grad = get_grad(tape, x)
    let error = abs_f64(grad - 0.25)
    return error < 0.001
}

fn test_tape_division() -> bool {
    // f(x,y) = x/y, df/dx = 1/y, df/dy = -x/y²
    // At x=6, y=2: f = 3, df/dx = 0.5, df/dy = -1.5
    var tape = new_tape()
    tape = tape_new_var(tape, 6.0)
    let x = tape_last_var(tape)
    tape = tape_new_var(tape, 2.0)
    let y = tape_last_var(tape)
    tape = tape_div(tape, x, y)
    let z = tape_last_var(tape)
    tape = backward(tape, z)

    let grad_x = get_grad(tape, x)
    let grad_y = get_grad(tape, y)
    let err_x = abs_f64(grad_x - 0.5)
    let err_y = abs_f64(grad_y - (0.0 - 1.5))
    return err_x < 0.001 && err_y < 0.001
}

fn test_tape_relu() -> bool {
    // f(x) = ReLU(x), df/dx = 1 if x>0 else 0
    // At x=3: f = 3, df/dx = 1
    // At x=-2: f = 0, df/dx = 0
    var tape1 = new_tape()
    tape1 = tape_new_var(tape1, 3.0)
    let x1 = tape_last_var(tape1)
    tape1 = tape_relu(tape1, x1)
    let y1 = tape_last_var(tape1)
    tape1 = backward(tape1, y1)
    let grad1 = get_grad(tape1, x1)

    var tape2 = new_tape()
    tape2 = tape_new_var(tape2, 0.0 - 2.0)
    let x2 = tape_last_var(tape2)
    tape2 = tape_relu(tape2, x2)
    let y2 = tape_last_var(tape2)
    tape2 = backward(tape2, y2)
    let grad2 = get_grad(tape2, x2)

    let err1 = abs_f64(grad1 - 1.0)
    let err2 = abs_f64(grad2 - 0.0)
    return err1 < 0.001 && err2 < 0.001
}

fn test_tape_neural_net() -> bool {
    // Simple 1-hidden-layer network: f(x) = tanh(w1·x + b1)·w2
    // At x=2, w1=0.5, b1=1, w2=3:
    //   h = tanh(0.5·2 + 1) = tanh(2) ≈ 0.964
    //   y = 0.964·3 ≈ 2.892
    // Gradients:
    //   dy/dw2 = h ≈ 0.964
    //   dy/db1 = w2·(1-h²) ≈ 3·(1-0.964²) ≈ 0.209
    //   dy/dx = w1·w2·(1-h²) ≈ 0.5·3·0.0707 ≈ 0.106

    var tape = new_tape()
    tape = tape_new_var(tape, 2.0)
    let x = tape_last_var(tape)
    tape = tape_const(tape, 0.5)
    let w1 = tape_last_var(tape)
    tape = tape_const(tape, 1.0)
    let b1 = tape_last_var(tape)
    tape = tape_const(tape, 3.0)
    let w2 = tape_last_var(tape)

    // h = w1·x + b1
    tape = tape_mul(tape, w1, x)
    let w1x = tape_last_var(tape)
    tape = tape_add(tape, w1x, b1)
    let h_in = tape_last_var(tape)
    tape = tape_tanh(tape, h_in)
    let h = tape_last_var(tape)

    // y = h·w2
    tape = tape_mul(tape, h, w2)
    let y = tape_last_var(tape)

    tape = backward(tape, y)

    let grad_w2 = get_grad(tape, w2)
    let grad_x = get_grad(tape, x)

    // Check dy/dw2 ≈ 0.964
    let h_val = tanh_f64(2.0)
    let err_w2 = abs_f64(grad_w2 - h_val)

    // Check dy/dx ≈ 0.106
    let expected_grad_x = 0.5 * 3.0 * (1.0 - h_val * h_val)
    let err_x = abs_f64(grad_x - expected_grad_x)

    return err_w2 < 0.01 && err_x < 0.01
}

fn run_tape_tests() -> i32 {
    var passed = 0
    if test_tape_square() { passed = passed + 1 }
    if test_tape_chain() { passed = passed + 1 }
    if test_tape_product() { passed = passed + 1 }
    if test_tape_exp() { passed = passed + 1 }
    if test_tape_sigmoid() { passed = passed + 1 }
    if test_tape_division() { passed = passed + 1 }
    if test_tape_relu() { passed = passed + 1 }
    if test_tape_neural_net() { passed = passed + 1 }
    return passed
}

fn add_entry(budget: UncertaintyBudget, entry: BudgetEntry) -> UncertaintyBudget {
    var result = budget
    let idx = budget.entry_count

    if idx == 0 { result.e0 = entry }
    else if idx == 1 { result.e1 = entry }
    else if idx == 2 { result.e2 = entry }
    else if idx == 3 { result.e3 = entry }

    if idx < 4 {
        result.entry_count = idx + 1
    }

    return result
}

fn compute_combined(budget: UncertaintyBudget) -> UncertaintyBudget {
    var result = budget
    var total_var: f64 = 0.0

    if budget.entry_count > 0 {
        total_var = total_var + budget.e0.contribution
    }
    if budget.entry_count > 1 {
        total_var = total_var + budget.e1.contribution
    }
    if budget.entry_count > 2 {
        total_var = total_var + budget.e2.contribution
    }
    if budget.entry_count > 3 {
        total_var = total_var + budget.e3.contribution
    }

    result.combined_variance = total_var
    result.combined_std_uncert = sqrt_f64(total_var)

    return result
}

fn compute_dof(budget: UncertaintyBudget) -> UncertaintyBudget {
    var result = budget
    let u_c4 = budget.combined_variance * budget.combined_variance
    var denom: f64 = 0.0

    if budget.entry_count > 0 && budget.e0.dof < 1.0e20 {
        let c4 = budget.e0.contribution * budget.e0.contribution
        denom = denom + c4 / budget.e0.dof
    }
    if budget.entry_count > 1 && budget.e1.dof < 1.0e20 {
        let c4 = budget.e1.contribution * budget.e1.contribution
        denom = denom + c4 / budget.e1.dof
    }
    if budget.entry_count > 2 && budget.e2.dof < 1.0e20 {
        let c4 = budget.e2.contribution * budget.e2.contribution
        denom = denom + c4 / budget.e2.dof
    }
    if budget.entry_count > 3 && budget.e3.dof < 1.0e20 {
        let c4 = budget.e3.contribution * budget.e3.contribution
        denom = denom + c4 / budget.e3.dof
    }

    if denom > 1.0e-15 {
        result.effective_dof = u_c4 / denom
    } else {
        result.effective_dof = 1.0e30
    }

    return result
}

fn budget_summary(budget: UncertaintyBudget) -> BudgetSummary {
    var rel_uncert: f64 = 0.0
    if abs_f64(budget.result_value) > 1.0e-15 {
        rel_uncert = 100.0 * budget.combined_std_uncert / abs_f64(budget.result_value)
    }

    return BudgetSummary {
        result_value: budget.result_value,
        combined_std_uncert: budget.combined_std_uncert,
        relative_uncert_percent: rel_uncert,
        effective_dof: budget.effective_dof,
        entry_count: budget.entry_count,
    }
}

fn coverage_factor(dof: f64, conf: f64) -> f64 {
    // Approximate t-values for 95% confidence
    if conf < 0.95 {
        if dof < 5.0 { return 2.13 }
        if dof < 10.0 { return 1.83 }
        return 1.65
    }
    // 95% confidence
    if dof < 3.0 { return 4.30 }
    if dof < 5.0 { return 2.78 }
    if dof < 10.0 { return 2.26 }
    if dof < 30.0 { return 2.04 }
    return 1.96
}

fn expanded_uncertainty(budget: UncertaintyBudget, conf: f64) -> f64 {
    let k = coverage_factor(budget.effective_dof, conf)
    return k * budget.combined_std_uncert
}

fn conf_interval(budget: UncertaintyBudget, conf: f64) -> ConfInterval {
    let k = coverage_factor(budget.effective_dof, conf)
    let u_exp = k * budget.combined_std_uncert
    return ConfInterval {
        lower: budget.result_value - u_exp,
        upper: budget.result_value + u_exp,
        coverage_k: k,
    }
}

fn test_simple_budget() -> bool {
    var budget = budget_new(100.0, 0.9)

    // Source 1: u=1.0, c=1.0 → contribution = 1.0
    budget = add_type_a(budget, 50.0, 1.0, 1.0, 10.0)

    // Source 2: u=2.0, c=1.0 → contribution = 4.0
    budget = add_type_a(budget, 50.0, 2.0, 1.0, 10.0)

    budget = finalize_budget(budget)

    // Combined variance = 1 + 4 = 5
    let diff = abs_f64(budget.combined_variance - 5.0)
    if diff > 0.01 { return false }

    // Combined std = sqrt(5) ≈ 2.236
    let diff2 = abs_f64(budget.combined_std_uncert - sqrt_f64(5.0))
    if diff2 > 0.01 { return false }

    return true
}

fn test_percent_contribution() -> bool {
    var budget = budget_new(100.0, 0.9)

    // Source 1: contribution = 1.0 (20%)
    budget = add_type_b(budget, 50.0, 1.0, 1.0)

    // Source 2: contribution = 4.0 (80%)
    budget = add_type_b(budget, 50.0, 2.0, 1.0)

    budget = finalize_budget(budget)

    let pct1 = percent_contribution(budget, 0)
    let pct2 = percent_contribution(budget, 1)

    if abs_f64(pct1 - 20.0) > 1.0 { return false }
    if abs_f64(pct2 - 80.0) > 1.0 { return false }

    return true
}

fn test_expanded_uncertainty() -> bool {
    var budget = budget_new(100.0, 0.95)
    budget = add_type_a(budget, 100.0, 2.0, 1.0, 10.0)
    budget = finalize_budget(budget)

    // Combined u_c = 2.0
    if abs_f64(budget.combined_std_uncert - 2.0) > 0.01 { return false }

    // Effective DOF = 9 (n-1)
    if abs_f64(budget.effective_dof - 9.0) > 0.1 { return false }

    // 95% confidence interval
    let ci = conf_interval(budget, 0.95)

    // k should be about 2.26 for ν=9
    if ci.coverage_k < 2.0 { return false }
    if ci.coverage_k > 2.5 { return false }

    return true
}

fn test_summary() -> bool {
    var budget = budget_new(100.0, 0.9)
    budget = add_type_b(budget, 100.0, 5.0, 1.0)
    budget = finalize_budget(budget)

    let summary = budget_summary(budget)

    if summary.entry_count != 1 { return false }
    if abs_f64(summary.combined_std_uncert - 5.0) > 0.01 { return false }
    if abs_f64(summary.relative_uncert_percent - 5.0) > 0.1 { return false }

    return true
}

