}

fn beta_new(alpha: f64, b: f64) -> Beta {
    var sa = alpha
    var sb = b
    if sa < 0.0001 { sa = 0.0001 }
    if sb < 0.0001 { sb = 0.0001 }
    Beta { alpha: sa, beta: sb }
}

fn beta_mean(b: Beta) -> f64 {
    b.alpha / (b.alpha + b.beta)
}

fn beta_variance(b: Beta) -> f64 {
    let n = b.alpha + b.beta
    (b.alpha * b.beta) / (n * n * (n + 1.0))
}

fn beta_std(b: Beta) -> f64 {
    beta_sqrt_f64(beta_variance(b))
}

fn beta_posterior(prior: Beta, successes: i64, failures: i64) -> Beta {
    var sf = 0.0
    var count = 0
    while count < successes {
        sf = sf + 1.0
        count = count + 1
    }
    var ff = 0.0
    count = 0
    while count < failures {
        ff = ff + 1.0
        count = count + 1
    }
    Beta { alpha: prior.alpha + sf, beta: prior.beta + ff }
}

fn exp_f64(x: f64) -> f64 {
    // Taylor series approximation for small x
    if x > 10.0 { return 22026.465794806718 * exp_f64(x - 10.0) }
    if x < -10.0 { return 0.00004539992976248485 * exp_f64(x + 10.0) }

    var result = 1.0
    var term = 1.0
    var i = 1
    while i < 20 {
        term = term * x / (i as f64)
        result = result + term
        i = i + 1
    }
    return result
}

fn ln_f64(x: f64) -> f64 {
    if x <= 0.0 { return 0.0 - 999999.0 }  // -inf approximation
    if x == 1.0 { return 0.0 }

    // ln(x) = 2 * arctanh((x-1)/(x+1)) for x > 0
    let y = (x - 1.0) / (x + 1.0)
    var result = 0.0
    var term = y
    var i = 1
    while i < 30 {
        result = result + term / (i as f64)
        term = term * y * y
        i = i + 2
    }
    return 2.0 * result
}

fn erf_approx(x: f64) -> f64 {
    // Abramowitz and Stegun approximation
    let a1 = 0.254829592
    let a2 = 0.0 - 0.284496736
    let a3 = 1.421413741
    let a4 = 0.0 - 1.453152027
    let a5 = 1.061405429
    let p = 0.3275911

    let sign = if x < 0.0 { 0.0 - 1.0 } else { 1.0 }
    let x_abs = if x < 0.0 { 0.0 - x } else { x }

    let t = 1.0 / (1.0 + p * x_abs)
    let y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * exp_f64(0.0 - x_abs * x_abs)

    return sign * y
}

