fn sed64_ln(x: f64) -> f64 {
    // Natural log via Halley's method: ln(x) where x > 0
    if x <= 0.0 { return 0.0 }
    // Initial guess using exponent decomposition
    var y = 0.0
    var t = x
    if t > 1.0 {
        while t > 2.718281828 {
            t = t / 2.718281828
            y = y + 1.0
        }
        y = y + (t - 1.0) / t
    } else {
        while t < 0.367879441 {
            t = t * 2.718281828
            y = y - 1.0
        }
        y = y + (t - 1.0) / t
    }
    // Newton refinement for exp(y) = x  =>  y = y + (x - exp(y))/exp(y)
    // Use exp approximation
    var i = 0
    while i < 8 {
        // exp(y) via Taylor
        let ey = sed64_exp_approx(y)
        y = y + (x - ey) / ey
        i = i + 1
    }
    return y
}

fn sed64_exp_approx(x: f64) -> f64 {
    // exp(x) via range reduction + polynomial
    var k = 0
    var r = x
    while r > 1.0 {
        r = r * 0.5
        k = k + 1
    }
    while r < -1.0 {
        r = r * 0.5
        k = k + 1
    }
    // Taylor: 1 + r + r^2/2 + r^3/6 + r^4/24 + r^5/120 + r^6/720
    let r2 = r * r
    let r3 = r2 * r
    let r4 = r3 * r
    let r5 = r4 * r
    let r6 = r5 * r
    var result = 1.0 + r + r2 * 0.5 + r3 / 6.0 + r4 / 24.0 + r5 / 120.0 + r6 / 720.0
    var j = 0
    while j < k {
        result = result * result
        j = j + 1
    }
    return result
}

