pub fn sed64_is_zero_divisor(s: Sedenion64, tol: f64) -> bool {
    let alpha_nsq = oct64_norm_sq_components(s.e0, s.e1, s.e2, s.e3, s.e4, s.e5, s.e6, s.e7)
    let beta_nsq = oct64_norm_sq_components(s.e8, s.e9, s.e10, s.e11, s.e12, s.e13, s.e14, s.e15)
    let a_norm = sed64_sqrt(alpha_nsq)
    let b_norm = sed64_sqrt(beta_nsq)
    // Condition 1: |alpha| ~ |beta|
    let norm_diff = sed64_abs(a_norm - b_norm)
    if norm_diff >= tol * (a_norm + b_norm + 1e-15) { return 0 }
    // Condition 2: <alpha, beta> ~ 0  (Euclidean dot product of the two halves)
    let inner = s.e0*s.e8 + s.e1*s.e9 + s.e2*s.e10 + s.e3*s.e11 +
                s.e4*s.e12 + s.e5*s.e13 + s.e6*s.e14 + s.e7*s.e15
    sed64_abs(inner) < tol * (a_norm * b_norm + 1e-15)
}

pub fn sed64_normalize(s: Sedenion64) -> Sedenion64 with Panic {
    let n = sed64_norm(s)
    if n < 1e-30 {
        sed64_one()
    } else {
        sed64_scale(s, 1.0 / n)
    }
}

pub fn sed64_putative_inv(s: Sedenion64) -> Sedenion64 with Panic {
    let nsq = sed64_norm_sq(s)
    if nsq < 1e-30 {
        sed64_one()
    } else {
        sed64_scale(sed64_conj(s), 1.0 / nsq)
    }
}

pub fn sed64_zero_divisor_distance(s: Sedenion64) -> f64 {
    let alpha_nsq = s.e0*s.e0 + s.e1*s.e1 + s.e2*s.e2 + s.e3*s.e3 +
                    s.e4*s.e4 + s.e5*s.e5 + s.e6*s.e6 + s.e7*s.e7
    let beta_nsq  = s.e8*s.e8 + s.e9*s.e9 + s.e10*s.e10 + s.e11*s.e11 +
                    s.e12*s.e12 + s.e13*s.e13 + s.e14*s.e14 + s.e15*s.e15
    let a_norm = sed64_sqrt(alpha_nsq)
    let b_norm = sed64_sqrt(beta_nsq)
    let norm_sum = a_norm + b_norm + 1e-30
    let norm_imb = sed64_abs(a_norm - b_norm) / norm_sum
    let inner = s.e0*s.e8 + s.e1*s.e9 + s.e2*s.e10 + s.e3*s.e11 +
                s.e4*s.e12 + s.e5*s.e13 + s.e6*s.e14 + s.e7*s.e15
    let orth_viol = sed64_abs(inner) / (a_norm * b_norm + 1e-30)
    sed64_sqrt(norm_imb * norm_imb + orth_viol * orth_viol)
}

